-- OpenBooks canonical PostgreSQL baseline.
--
-- This file defines the complete schema for a fresh installation: tables,
-- constraints, indexes, functions, triggers, row-level security policies,
-- governed query views, and grants. Deployment bootstrap applies it exactly
-- once and records its digest in _applied_migrations.

SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
--
-- Name: openbooks_query; Type: SCHEMA; Schema: -; Owner: -
--

CREATE SCHEMA openbooks_query;


-- Trigram search is an optional acceleration. PostgreSQL providers that do
-- not allow application roles to install extensions still receive the full
-- canonical schema and use the application's substring-search fallback.
DO $extension$
BEGIN
  CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA public;
EXCEPTION
  WHEN insufficient_privilege OR undefined_file THEN
    RAISE NOTICE 'pg_trgm is unavailable; trigram indexes will be skipped';
END
$extension$;


--
-- Name: tenant_retirement; Type: SCHEMA; Schema: -; Owner: -
--

CREATE SCHEMA tenant_retirement;


--
-- Name: btree_gist; Type: EXTENSION; Schema: -; Owner: -
--

CREATE EXTENSION IF NOT EXISTS btree_gist WITH SCHEMA public;


--
-- Name: pg_trgm; Type: EXTENSION; Schema: -; Owner: -
--



--
-- Name: pgcrypto; Type: EXTENSION; Schema: -; Owner: -
--

CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA public;


--
-- Name: account_group_catch_all_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_group_catch_all_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  existing_key text;
BEGIN
  IF NEW.is_catch_all AND NEW.is_active THEN
    IF TG_OP = 'INSERT' AND EXISTS (
      SELECT 1
        FROM public.account_groups existing
       WHERE existing.org_id = NEW.org_id
         AND existing.dimension = NEW.dimension
         AND existing.key = NEW.key
    ) THEN
      RETURN NEW;
    END IF;
    SELECT g.key
      INTO existing_key
      FROM public.account_groups g
     WHERE g.org_id = NEW.org_id
       AND g.dimension = NEW.dimension
       AND g.is_catch_all
       AND g.is_active
       AND g.id IS DISTINCT FROM NEW.id
     LIMIT 1;
    IF FOUND THEN
      RAISE EXCEPTION 'only one active catch-all account group is allowed per organization and dimension (org % dimension % already resolves unmatched accounts to "%"); deactivate that group first, or edit it instead of adding a second catch-all',
        NEW.org_id, NEW.dimension, existing_key
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION account_group_catch_all_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.account_group_catch_all_guard() IS 'openbooks:account_group_catch_all_guard:v1 - refuses a second active catch-all per (org, dimension) with the remedy, for API and direct-SQL writers alike';


--
-- Name: account_group_member_parent_scope_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_group_member_parent_scope_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (NEW.org_id IS DISTINCT FROM OLD.org_id OR NEW.dimension IS DISTINCT FROM OLD.dimension)
     AND EXISTS (
       SELECT 1
         FROM public.account_group_members member
        WHERE member.group_id = OLD.id
     ) THEN
    RAISE EXCEPTION 'account group organization or dimension cannot change while pins exist'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION account_group_member_parent_scope_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.account_group_member_parent_scope_guard() IS 'openbooks:account_group_member_parent_scope_guard:v1 - prevents parent scope edits from invalidating denormalized account-group member dimensions';


--
-- Name: account_group_member_scope_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_group_member_scope_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  group_org uuid;
  group_dimension text;
  account_org uuid;
  old_lock_key text;
  new_lock_key text;
  first_lock_key text;
  second_lock_key text;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' THEN
    PERFORM pg_advisory_xact_lock(
      hashtextextended(
        'account-group-pin:' || OLD.org_id::text || ':' || OLD.dimension || ':' || OLD.account_id::text,
        0
      )
    );
    RETURN OLD;
  END IF;

  SELECT group_row.org_id, group_row.dimension
    INTO group_org, group_dimension
    FROM public.account_groups group_row
   WHERE group_row.id = NEW.group_id
   FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'account group % does not exist', NEW.group_id
      USING ERRCODE = '23503';
  END IF;
  IF group_org IS DISTINCT FROM NEW.org_id THEN
    RAISE EXCEPTION 'account group % belongs to another organization', NEW.group_id
      USING ERRCODE = '23514';
  END IF;
  IF NEW.dimension IS DISTINCT FROM group_dimension THEN
    RAISE EXCEPTION 'account group member dimension must match its group'
      USING ERRCODE = '23514';
  END IF;

  SELECT account_row.org_id
    INTO account_org
    FROM public.accounts account_row
   WHERE account_row.id = NEW.account_id
   FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'account % does not exist', NEW.account_id
      USING ERRCODE = '23503';
  END IF;
  IF account_org IS DISTINCT FROM NEW.org_id THEN
    RAISE EXCEPTION 'account % belongs to another organization', NEW.account_id
      USING ERRCODE = '23514';
  END IF;

  new_lock_key := 'account-group-pin:' || NEW.org_id::text || ':' || NEW.dimension || ':' || NEW.account_id::text;
  IF TG_OP = 'UPDATE' THEN
    old_lock_key := 'account-group-pin:' || OLD.org_id::text || ':' || OLD.dimension || ':' || OLD.account_id::text;
    first_lock_key := LEAST(old_lock_key, new_lock_key);
    second_lock_key := GREATEST(old_lock_key, new_lock_key);
    PERFORM pg_advisory_xact_lock(hashtextextended(first_lock_key, 0));
    IF second_lock_key IS DISTINCT FROM first_lock_key THEN
      PERFORM pg_advisory_xact_lock(hashtextextended(second_lock_key, 0));
    END IF;
  ELSE
    PERFORM pg_advisory_xact_lock(hashtextextended(new_lock_key, 0));
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION account_group_member_scope_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.account_group_member_scope_guard() IS 'openbooks:account_group_member_scope_guard:v1 - validates tenant and dimension coherence and serializes every account-group pin mutation on one transaction advisory fence';


--
-- Name: account_merge_change_binding(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_merge_change_binding() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
BEGIN
  IF NEW.domain <> 'ledger' THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' AND public.openbooks_clone_authority() THEN
    RETURN NEW;
  END IF;
  IF NEW.operation <> 'account_merge' THEN
    RAISE EXCEPTION 'ledger accounting events admit only the account_merge operation, not %', NEW.operation
      USING ERRCODE = '23514';
  END IF;
  IF jsonb_typeof(NEW.payload) IS DISTINCT FROM 'object'
     OR NEW.payload ->> 'sourceAccountId' IS DISTINCT FROM NEW.subject_id::text
     OR NEW.payload ->> 'effectiveDate' IS DISTINCT FROM NEW.effective_on::text
     OR coalesce(NEW.payload ->> 'previewDigest', '') !~ '^[0-9a-f]{64}$'
     OR coalesce(NEW.payload ->> 'targetAccountId', '') !~ '^[0-9a-fA-F-]{36}$'
     OR jsonb_typeof(NEW.payload -> 'requiredSubsidiaryIds') IS DISTINCT FROM 'array'
     OR NOT EXISTS (SELECT 1 FROM public.accounts WHERE org_id = NEW.org_id AND id = NEW.subject_id)
     OR NOT EXISTS (SELECT 1 FROM public.accounts WHERE org_id = NEW.org_id AND id = (NEW.payload ->> 'targetAccountId')::uuid) THEN
    RAISE EXCEPTION 'An account merge proposal must bind its source account, surviving account, effective date and previewed consequences.'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$_$;


--
-- Name: account_merge_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_merge_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_survivor record;
  v_parent_survivor uuid;
BEGIN
  IF TG_OP = 'INSERT' AND public.openbooks_clone_authority() THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.merged_into_id IS NOT NULL THEN
    IF NEW.merged_into_id IS DISTINCT FROM OLD.merged_into_id
       OR NEW.merged_at IS DISTINCT FROM OLD.merged_at
       OR NEW.merged_by IS DISTINCT FROM OLD.merged_by
       OR NEW.merge_reason IS DISTINCT FROM OLD.merge_reason THEN
      RAISE EXCEPTION 'account % was merged into account %; a merge is permanent — correct it with an adjusting journal entry', OLD.id, OLD.merged_into_id
        USING ERRCODE = '23514';
    END IF;
    IF NEW.is_active THEN
      RAISE EXCEPTION 'account % was merged into account % and cannot be reactivated — use the surviving account', OLD.id, OLD.merged_into_id
        USING ERRCODE = '23514';
    END IF;
  END IF;
  IF NEW.merged_into_id IS NOT NULL AND (TG_OP = 'INSERT' OR OLD.merged_into_id IS NULL) THEN
    SELECT id, is_active, is_summary, merged_into_id INTO v_survivor
      FROM public.accounts
     WHERE org_id = NEW.org_id AND id = NEW.merged_into_id
     FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'account % can only be merged into an account of the same organization', NEW.id
        USING ERRCODE = '23514';
    END IF;
    IF NOT v_survivor.is_active OR v_survivor.is_summary OR v_survivor.merged_into_id IS NOT NULL THEN
      RAISE EXCEPTION 'account % can only be merged into an active, postable, unmerged account', NEW.id
        USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.account_merges m
       WHERE m.org_id = NEW.org_id AND m.source_account_id = NEW.id
         AND m.target_account_id = NEW.merged_into_id
    ) THEN
      RAISE EXCEPTION 'account % is marked merged only by the account merge command, which records the merge first', NEW.id
        USING ERRCODE = '23514';
    END IF;
  END IF;
  IF NEW.parent_id IS NOT NULL AND (TG_OP = 'INSERT' OR NEW.parent_id IS DISTINCT FROM OLD.parent_id) THEN
    SELECT merged_into_id INTO v_parent_survivor
      FROM public.accounts WHERE org_id = NEW.org_id AND id = NEW.parent_id;
    IF v_parent_survivor IS NOT NULL THEN
      RAISE EXCEPTION 'parent account % was merged into account % — choose the surviving account as the parent', NEW.parent_id, v_parent_survivor
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: account_merge_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_merge_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;
  IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'Account merges are permanent history; correct a merge with an adjusting journal entry.';
END;
$$;


--
-- Name: account_posting_classification_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_posting_classification_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_has_lines boolean;
begin
  if new.type is not distinct from old.type
     and new.is_summary is not distinct from old.is_summary then
    return new;
  end if;

  select exists (
    select 1
      from journal_lines
     where org_id = old.org_id
       and account_id = old.id
  ) into v_has_lines;

  if not v_has_lines then
    return new;
  end if;

  if new.type is distinct from old.type then
    raise exception 'account % type cannot change after journal lines exist', old.id
      using errcode = '23514', constraint = 'accounts_type_has_transactions';
  end if;

  if new.is_summary is distinct from old.is_summary then
    raise exception 'account % summary classification cannot change after journal lines exist', old.id
      using errcode = '23514', constraint = 'accounts_summary_has_transactions';
  end if;

  return new;
end $$;


--
-- Name: FUNCTION account_posting_classification_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.account_posting_classification_guard() IS 'openbooks:account_posting_classification_guard:v1 - prevents direct type/summary reclassification after ledger history exists';


--
-- Name: account_translation_rate_type(uuid, uuid, date, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_translation_rate_type(p_org uuid, p_account uuid, p_date date, p_cash_flow boolean DEFAULT false) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
 SELECT CASE WHEN p_cash_flow THEN cash_flow_rate_type ELSE general_rate_type END FROM account_translation_policies
 WHERE org_id=p_org AND account_id=p_account AND effective_from<=p_date ORDER BY effective_from DESC LIMIT 1 $$;


--
-- Name: accounting_book_account_map_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_book_account_map_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;
  IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;
  IF coalesce(current_setting('openbooks.migration', true), 'off') = 'on' THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN
    IF public.accounting_book_has_lines(OLD.org_id, OLD.book_id, OLD.subsidiary_id, OLD.target_account_id, OLD.effective_from, OLD.effective_to)
       OR public.accounting_book_has_lines(OLD.org_id, OLD.book_id, OLD.subsidiary_id, OLD.source_account_id, OLD.effective_from, OLD.effective_to) THEN
      RAISE EXCEPTION 'This account mapping governs entries the book already holds; close its window after them instead'
        USING ERRCODE = '23514';
    END IF;
    RETURN OLD;
  END IF;
  IF EXISTS (SELECT 1 FROM public.accounting_books b WHERE b.org_id = NEW.org_id AND b.id = NEW.book_id AND b.is_primary) THEN
    RAISE EXCEPTION 'The primary book is the chart of record; map accounts in a secondary book'
      USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF NEW.org_id IS DISTINCT FROM OLD.org_id OR NEW.book_id IS DISTINCT FROM OLD.book_id
       OR NEW.subsidiary_id IS DISTINCT FROM OLD.subsidiary_id OR NEW.source_account_id IS DISTINCT FROM OLD.source_account_id
       OR NEW.target_account_id IS DISTINCT FROM OLD.target_account_id OR NEW.effective_from IS DISTINCT FROM OLD.effective_from
       OR NEW.reason IS DISTINCT FROM OLD.reason THEN
      RAISE EXCEPTION 'An account mapping keeps its accounts, scope and start date; add a new mapping from a later date instead'
        USING ERRCODE = '23514';
    END IF;
    IF NEW.effective_to IS NOT NULL AND (OLD.effective_to IS NULL OR NEW.effective_to < OLD.effective_to)
       AND (public.accounting_book_has_lines(OLD.org_id, OLD.book_id, OLD.subsidiary_id, OLD.target_account_id, NEW.effective_to + 1, OLD.effective_to)
            OR public.accounting_book_has_lines(OLD.org_id, OLD.book_id, OLD.subsidiary_id, OLD.source_account_id, NEW.effective_to + 1, OLD.effective_to)) THEN
      RAISE EXCEPTION 'The book already holds entries this mapping governed after %; end the window on or after its latest entry', NEW.effective_to
        USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;
  IF public.accounting_book_has_lines(NEW.org_id, NEW.book_id, NEW.subsidiary_id, NEW.source_account_id, NEW.effective_from, NEW.effective_to) THEN
    RAISE EXCEPTION 'The book already holds entries on the source account on or after %; start the mapping after its latest entry', NEW.effective_from
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: accounting_book_currency(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_book_currency(p_org uuid, p_book uuid, p_subsidiary uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT coalesce(
    (SELECT c.currency FROM public.accounting_book_currencies c
      WHERE c.org_id = p_org AND c.book_id = p_book AND c.subsidiary_id = p_subsidiary LIMIT 1),
    (SELECT s.base_currency FROM public.subsidiaries s WHERE s.org_id = p_org AND s.id = p_subsidiary))
$$;


--
-- Name: accounting_book_currency_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_book_currency_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  established text;
  base text;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;
  IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;
  IF coalesce(current_setting('openbooks.migration', true), 'off') = 'on' THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN
    IF public.accounting_book_has_lines(OLD.org_id, OLD.book_id, OLD.subsidiary_id, NULL, OLD.effective_from, OLD.effective_to) THEN
      RAISE EXCEPTION 'This book currency governs entries the book already holds; close its window after them instead'
        USING ERRCODE = '23514';
    END IF;
    RETURN OLD;
  END IF;
  IF EXISTS (SELECT 1 FROM public.accounting_books b WHERE b.org_id = NEW.org_id AND b.id = NEW.book_id AND b.is_primary) THEN
    RAISE EXCEPTION 'The primary book carries every subsidiary in its functional currency'
      USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF NEW.org_id IS DISTINCT FROM OLD.org_id OR NEW.book_id IS DISTINCT FROM OLD.book_id
       OR NEW.subsidiary_id IS DISTINCT FROM OLD.subsidiary_id OR NEW.currency IS DISTINCT FROM OLD.currency
       OR NEW.rate_type IS DISTINCT FROM OLD.rate_type OR NEW.effective_from IS DISTINCT FROM OLD.effective_from
       OR NEW.reason IS DISTINCT FROM OLD.reason THEN
      RAISE EXCEPTION 'A book currency version keeps its currency, rate type and start date; add a new version from a later date instead'
        USING ERRCODE = '23514';
    END IF;
    IF NEW.effective_to IS NOT NULL AND (OLD.effective_to IS NULL OR NEW.effective_to < OLD.effective_to)
       AND public.accounting_book_has_lines(OLD.org_id, OLD.book_id, OLD.subsidiary_id, NULL, NEW.effective_to + 1, OLD.effective_to) THEN
      RAISE EXCEPTION 'The book already holds entries for this subsidiary after %; end the window on or after its latest entry', NEW.effective_to
        USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;
  SELECT c.currency INTO established
    FROM public.accounting_book_currencies c
   WHERE c.org_id = NEW.org_id AND c.book_id = NEW.book_id AND c.subsidiary_id = NEW.subsidiary_id
   LIMIT 1;
  IF established IS NOT NULL AND established <> NEW.currency THEN
    RAISE EXCEPTION 'This book carries the subsidiary in %; a book keeps one currency per subsidiary', established
      USING ERRCODE = '23514';
  END IF;
  IF established IS NULL THEN
    SELECT s.base_currency INTO base FROM public.subsidiaries s WHERE s.org_id = NEW.org_id AND s.id = NEW.subsidiary_id;
    IF NEW.currency <> base AND public.accounting_book_has_lines(NEW.org_id, NEW.book_id, NEW.subsidiary_id, NULL, NULL, NULL) THEN
      RAISE EXCEPTION 'The book already holds % entries for this subsidiary; a different book currency needs a new book', base
        USING ERRCODE = '23514';
    END IF;
  END IF;
  IF public.accounting_book_has_lines(NEW.org_id, NEW.book_id, NEW.subsidiary_id, NULL, NEW.effective_from, NEW.effective_to) THEN
    RAISE EXCEPTION 'The book already holds entries for this subsidiary on or after %; start the version after its latest entry', NEW.effective_from
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: accounting_book_has_lines(uuid, uuid, uuid, uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_book_has_lines(p_org uuid, p_book uuid, p_subsidiary uuid, p_account uuid, p_from date, p_to date) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM public.journal_lines l
      JOIN public.journal_entries e ON e.id = l.entry_id AND e.org_id = l.org_id
     WHERE l.org_id = p_org AND e.book_id = p_book
       AND (p_subsidiary IS NULL OR l.subsidiary_id = p_subsidiary)
       AND (p_account IS NULL OR l.account_id = p_account)
       AND (p_from IS NULL OR e.posting_date >= p_from)
       AND (p_to IS NULL OR e.posting_date <= p_to)
  )
$$;


--
-- Name: accounting_book_replication_run_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_book_replication_run_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.created_txid = txid_current() THEN
    IF (to_jsonb(NEW) - 'replicated_count' - 'excluded_count' - 'opening_entry_ids')
       = (to_jsonb(OLD) - 'replicated_count' - 'excluded_count' - 'opening_entry_ids') THEN
      RETURN NEW;
    END IF;
  END IF;
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;
  IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'Multi-book replication runs are append-only history'
    USING ERRCODE = '23514';
END;
$$;


--
-- Name: accounting_book_replication_settings_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_book_replication_settings_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF coalesce(current_setting('openbooks.migration', true), 'off') = 'on' THEN
    RETURN NEW;
  END IF;
  IF NEW.replication_mode IS NOT DISTINCT FROM OLD.replication_mode
     AND NEW.replication_from IS NOT DISTINCT FROM OLD.replication_from
     AND NEW.currency_difference_account_id IS NOT DISTINCT FROM OLD.currency_difference_account_id THEN
    RETURN NEW;
  END IF;
  IF OLD.replication_from IS NOT NULL AND NEW.replication_from IS DISTINCT FROM OLD.replication_from THEN
    RAISE EXCEPTION 'The replication start date of book % is fixed once set; catch up from it instead', OLD.code
      USING ERRCODE = '23514';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.accounting_book_replication_runs run
     WHERE run.org_id = NEW.org_id AND run.book_id = NEW.id AND run.created_txid = txid_current()
  ) THEN
    RAISE EXCEPTION 'Replication settings of book % change only through a recorded replication change with a reason', OLD.code
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: accounting_period_posting_window(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_period_posting_window(p_org_id uuid, p_period_id uuid) RETURNS TABLE(is_adjustment boolean, period_name text, fiscal_year integer, window_start date, window_end date)
    LANGUAGE sql STABLE
    AS $$
  select p.is_adjustment, p.name, p.fiscal_year,
         case when p.is_adjustment then least(p.starts_on, fy.starts_on) else p.starts_on end,
         case when p.is_adjustment then greatest(p.ends_on, fy.ends_on) else p.ends_on end
    from public.accounting_periods p
    left join lateral (
      select min(r.starts_on) as starts_on, max(r.ends_on) as ends_on
        from public.accounting_periods r
       where r.org_id = p.org_id
         and r.fiscal_calendar_id = p.fiscal_calendar_id
         and r.fiscal_year = p.fiscal_year
         and not r.is_adjustment
    ) fy on true
   where p.org_id = p_org_id and p.id = p_period_id
$$;


--
-- Name: aging_boundaries_valid(integer[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aging_boundaries_valid(boundaries integer[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT coalesce(array_length(boundaries, 1), 0) >= 1
     AND array_ndims(boundaries) = 1
     AND array_lower(boundaries, 1) = 1
     AND NOT EXISTS (
       SELECT 1 FROM unnest(boundaries) WITH ORDINALITY AS b(day, ord)
        WHERE b.day IS NULL OR b.day < 1 OR b.day > 36500
           OR (b.ord > 1 AND b.day <= boundaries[(b.ord - 1)::int])
     );
$$;


--
-- Name: aging_bucket_policies_history_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aging_bucket_policies_history_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF public.app_bypass_rls_active() AND coalesce(current_setting('openbooks.amend',true),'off')='on' THEN
   IF TG_OP='DELETE' THEN RETURN OLD; END IF;
   RETURN NEW;
 END IF;
 IF TG_OP='DELETE' THEN
   RAISE EXCEPTION 'Aging bucket policy history is preserved; deactivate the version instead of deleting it in Setup → Company → Aging bucket policies'
   USING ERRCODE = '23514';
 END IF;
 IF ROW(OLD.org_id, OLD.id, OLD.boundaries, OLD.effective_from, OLD.created_at, OLD.created_by)
    IS DISTINCT FROM
    ROW(NEW.org_id, NEW.id, NEW.boundaries, NEW.effective_from, NEW.created_at, NEW.created_by) THEN
   RAISE EXCEPTION 'Aging bucket policy versions are immutable; close the window (set its effective-to) and create a new version in Setup → Company → Aging bucket policies'
   USING ERRCODE = '23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: ai_decisions_refuse_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_decisions_refuse_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF coalesce(current_setting('openbooks.amend', true), 'off') = 'on' THEN
    RETURN COALESCE(OLD, NEW);
  END IF;
  RAISE EXCEPTION 'ai_decisions is append-only: decisions cannot be updated or deleted; record a new row (capability %, subject %)',
    COALESCE(OLD.capability_key, NEW.capability_key),
    COALESCE(OLD.subject_kind, NEW.subject_kind);
  RETURN NULL;
END;
$$;


--
-- Name: FUNCTION ai_decisions_refuse_update(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ai_decisions_refuse_update() IS 'openbooks:ai_decisions_append_only:v1 - refuses UPDATE and DELETE on ai_decisions; corrections are new rows';


--
-- Name: allocation_rule_target_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.allocation_rule_target_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_status text;
  v_version uuid;
begin
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  v_version := coalesce(new.version_id, old.version_id);
  select status into v_status from public.allocation_rule_versions where id = v_version;
  if v_status is not null and v_status <> 'draft' then
    raise exception 'allocation rule version % is %; its targets are immutable', v_version, v_status;
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;


--
-- Name: allocation_rule_version_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.allocation_rule_version_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.status = 'draft' then
    return new;
  end if;
  if old.status = 'retired' then
    raise exception 'allocation rule version % is retired and immutable', old.id;
  end if;
  -- published: allow draft→published transition already applied; now lock the definition
  if new.status not in ('published', 'retired') then
    raise exception 'allocation rule version % is published; it can only be retired', old.id;
  end if;
  if row(new.rule_id, new.version_no, new.effective_from, new.effective_to, new.book_scope, new.book_ids,
         new.document_kinds, new.account_scope, new.dimension_filters, new.apply_policy, new.source_measure,
         new.basis_kind, new.driver_id, new.driver_as_of, new.basis_config, new.target_kind, new.dynamic_target,
         new.impact, new.offset_account_id, new.residual_policy, new.residual_target_id, new.solve_method,
         new.memo_template, new.line_description_template, new.definition_hash, new.published_at, new.published_by)
     is distinct from
     row(old.rule_id, old.version_no, old.effective_from, old.effective_to, old.book_scope, old.book_ids,
         old.document_kinds, old.account_scope, old.dimension_filters, old.apply_policy, old.source_measure,
         old.basis_kind, old.driver_id, old.driver_as_of, old.basis_config, old.target_kind, old.dynamic_target,
         old.impact, old.offset_account_id, old.residual_policy, old.residual_target_id, old.solve_method,
         old.memo_template, old.line_description_template, old.definition_hash, old.published_at, old.published_by)
  then
    raise exception 'allocation rule version % is published; its definition is immutable (retire it and publish a new version)', old.id;
  end if;
  return new;
end;
$$;


--
-- Name: app_bypass_rls_active(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_bypass_rls_active() RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT current_setting('app.bypass_rls', true) = 'on'
     AND (
       -- Dedicated cross-tenant login (BYPASSRLS attribute), and any
       -- superuser: the local/CI bootstrap login doubles as the bypass pool
       -- (superusers imply rolbypassrls), and restores may connect as an
       -- explicitly controlled superuser.
       EXISTS (
         SELECT 1
           FROM pg_catalog.pg_roles
          WHERE rolname = session_user
            AND (rolbypassrls OR rolsuper)
       )
       -- Migration/installer owner: the role that owns this function, i.e.
       -- the login that ran this migration. Least-privilege owners (stock
       -- compose superuser-owners, host-managed NOBYPASSRLS owners, the
       -- one-shot installer pool) hold no bypass attribute, so ownership is
       -- the only stable mark — and it is transfer-proof: the test ownership
       -- transfer loop covers public/openbooks_query objects, and this
       -- function lives in public but bootstrap excludes it by name, so the
       -- runtime role can never become its owner. pg_has_role (not =) so a
       -- future owner that inherits the original still qualifies; the
       -- runtime role is never granted the owner role (communal-postgres.md:
       -- "never grant the owner role to the runtime role"), so it stays out.
       OR pg_catalog.pg_has_role(
            session_user,
            (SELECT proowner
               FROM pg_catalog.pg_proc
              WHERE oid = pg_catalog.to_regprocedure('public.app_bypass_rls_active()')),
            'MEMBER'
          )
     )
$$;


--
-- Name: FUNCTION app_bypass_rls_active(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.app_bypass_rls_active() IS 'Single definition of privileged RLS bypass: true only when app.bypass_rls is ''on'' AND the session login holds BYPASSRLS/superuser or inherits this function''s owner (the migration/installer owner). The runtime role never qualifies. Policies must call this instead of trusting the GUC inline.';


--
-- Name: app_check_open(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_check_open() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_line numeric(19,4);
  v_applied numeric(19,4);
  v_transaction numeric(19,4);
begin
  if new.unapplied_at is not null then return new; end if;
  -- target side: total applied to the open item <= |line amount|
  select abs(amount) into v_line from journal_lines where id = new.to_line_id;
  select coalesce(sum(amount), 0) into v_applied
    from applications
   where to_line_id = new.to_line_id and unapplied_at is null and id <> new.id;
  if v_applied + new.amount > v_line then
    raise exception 'application exceeds open amount on target line % (% applied of %)',
      new.to_line_id, v_applied + new.amount, v_line;
  end if;

  select abs(txn_amount) into v_line from journal_lines where id = new.to_line_id;
  select coalesce(sum(target_transaction_amount), 0) into v_transaction from applications
   where to_line_id = new.to_line_id and unapplied_at is null and id <> new.id;
  if v_transaction + new.target_transaction_amount > v_line then
    raise exception 'application exceeds transaction amount on target line %', new.to_line_id using errcode = '23514';
  end if;

  -- source side uses its independently recorded carrying amount.
  select abs(amount) into v_line from journal_lines where id = new.from_line_id;
  select coalesce(sum(source_amount), 0) into v_applied
    from applications
   where from_line_id = new.from_line_id and unapplied_at is null and id <> new.id;
  if v_applied + new.source_amount > v_line then
    raise exception 'application exceeds available amount on source line %', new.from_line_id using errcode = '23514';
  end if;
  select abs(txn_amount) into v_line from journal_lines where id = new.from_line_id;
  select coalesce(sum(source_transaction_amount), 0) into v_transaction from applications
   where from_line_id = new.from_line_id and unapplied_at is null and id <> new.id;
  if v_transaction + new.source_transaction_amount > v_line then
    raise exception 'application exceeds transaction amount on source line %', new.from_line_id using errcode = '23514';
  end if;
  return new;
end $$;


--
-- Name: app_validate_endpoints(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_validate_endpoints() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_from journal_lines%rowtype;
  v_to journal_lines%rowtype;
  v_fx fx_rates%rowtype;
  v_status_count integer;
begin
  -- Bulk migration / sandbox-clone copies pre-validated application rows through
  -- ob_rebase before their journal lines exist in the target, so this row-by-row
  -- cross-reference check can't hold mid-copy. 'set local openbooks.migration = on'
  -- (transaction-scoped, direct-DB only) relaxes it; every normal write still
  -- validates in full.
  if coalesce(current_setting('openbooks.migration', true), 'off') = 'on' then
    return new;
  end if;
  -- Deterministic row locks serialize competing applications to either line.
  perform id from journal_lines
   where id in (new.from_line_id, new.to_line_id)
   order by id for update;
  select * into v_from from journal_lines where id = new.from_line_id;
  select * into v_to from journal_lines where id = new.to_line_id;
  if v_from.id is null or v_to.id is null or v_from.id = v_to.id then
    raise exception 'application endpoints must be two distinct journal lines' using errcode = '23514';
  end if;
  if v_from.org_id <> new.org_id or v_to.org_id <> new.org_id
     or v_from.org_id <> v_to.org_id then
    raise exception 'application endpoints must belong to the application tenant' using errcode = '23514';
  end if;
  if new.unapplied_at is not null then return new; end if;
  -- Parallel accounting books are representations, not additional balances.
  -- Posted entry book identity is immutable. The existing sorted endpoint
  -- locks below the migration exemption continue to serialize allocations.
  -- Keep this after the unapply return so legacy invalid evidence can be
  -- corrected through the ordinary audited unapplication lifecycle.
  if not exists (
    select 1 from journal_entries source_entry
    join journal_entries target_entry
      on target_entry.id = v_to.entry_id
     and target_entry.org_id = new.org_id
     and target_entry.book_id = source_entry.book_id
    where source_entry.id = v_from.entry_id
      and source_entry.org_id = new.org_id
  ) then
    raise exception 'application endpoints must share an accounting book' using errcode = '23514';
  end if;
  if not v_from.is_open_item or not v_to.is_open_item then
    raise exception 'applications require open-item journal lines' using errcode = '23514';
  end if;
  if v_from.account_id <> v_to.account_id
     or v_from.party_id is distinct from v_to.party_id
     or v_from.subsidiary_id <> v_to.subsidiary_id then
    raise exception 'application endpoints must share account, party, and subsidiary' using errcode = '23514';
  end if;
  if sign(v_from.amount) = sign(v_to.amount) then
    raise exception 'application endpoints must have opposite debit/credit signs' using errcode = '23514';
  end if;
  if v_from.currency <> new.source_transaction_currency
     or v_to.currency <> new.target_transaction_currency then
    raise exception 'application source and target currencies must match their journal lines' using errcode = '23514';
  end if;
  if abs(new.target_transaction_amount - round(new.source_transaction_amount * new.settlement_rate, 4)) > 0.0001 then
    raise exception 'application settlement rate does not cross-foot source and target transaction amounts' using errcode = '23514';
  end if;
  if new.source_transaction_currency = new.target_transaction_currency then
    if new.source_transaction_amount <> new.target_transaction_amount
       or new.settlement_rate <> 1
       or new.settlement_rate_source <> 'same_currency' then
      raise exception 'same-currency applications require equal transaction amounts and a rate of one' using errcode = '23514';
    end if;
  elsif new.settlement_rate_source = 'same_currency' then
    raise exception 'cross-currency applications require explicit settlement-rate evidence' using errcode = '23514';
  end if;
  if new.settlement_rate_source = 'provider' and new.settlement_fx_rate_id is null then
    raise exception 'provider settlement evidence requires an FX rate observation' using errcode = '23514';
  end if;
  if new.settlement_fx_rate_id is not null then
    select * into v_fx from fx_rates where id = new.settlement_fx_rate_id;
    if v_fx.id is null
       or v_fx.org_id <> new.org_id
       or v_fx.from_currency <> new.source_transaction_currency
       or v_fx.to_currency <> new.target_transaction_currency
       or v_fx.rate <> new.settlement_rate
       or v_fx.as_of > new.applied_on then
      raise exception 'settlement FX observation does not match the application evidence' using errcode = '23514';
    end if;
  end if;
  select count(*) into v_status_count from journal_entries
   where id in (v_from.entry_id, v_to.entry_id) and status = 'posted';
  if v_status_count <> 2 then
    raise exception 'applications may only connect posted journal entries' using errcode = '23514';
  end if;
  return new;
end $$;


--
-- Name: application_evidence_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.application_evidence_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  if tg_op = 'DELETE' then
    if openbooks_sandbox_wipe_allowed(old.org_id) then return old; end if;
    raise exception 'application evidence is immutable; unapply it instead';
  end if;
  if new.org_id is distinct from old.org_id
     or new.from_line_id is distinct from old.from_line_id
     or new.to_line_id is distinct from old.to_line_id
     or new.amount is distinct from old.amount
     or new.source_amount is distinct from old.source_amount
     or new.source_transaction_amount is distinct from old.source_transaction_amount
     or new.source_transaction_currency is distinct from old.source_transaction_currency
     or new.target_transaction_amount is distinct from old.target_transaction_amount
     or new.target_transaction_currency is distinct from old.target_transaction_currency
     or new.settlement_rate is distinct from old.settlement_rate
     or new.settlement_rate_source is distinct from old.settlement_rate_source
     or new.settlement_rate_reference is distinct from old.settlement_rate_reference
     or new.settlement_fx_rate_id is distinct from old.settlement_fx_rate_id
     or new.applied_on is distinct from old.applied_on
     or new.fx_gain_loss_entry_id is distinct from old.fx_gain_loss_entry_id
     or old.unapplied_at is not null
     or new.unapplied_at is null then
    raise exception 'application evidence is immutable; only a one-time unapply is allowed';
  end if;
  return new;
end $$;


--
-- Name: application_respects_run_reservation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.application_respects_run_reservation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_source_document uuid;
  v_reservation record;
begin
  -- Only a live application settles anything; unapplying never pays twice.
  if new.unapplied_at is not null then
    return new;
  end if;
  if tg_op = 'UPDATE'
     and old.unapplied_at is null
     and new.from_line_id = old.from_line_id
     and new.to_line_id = old.to_line_id then
    return new;
  end if;
  -- The deterministic sandbox clone copies posted history verbatim.
  if public.openbooks_clone_authority() then
    return new;
  end if;

  for v_reservation in
    select item.payment_run_id, item.payment_instruction_id,
           run.run_number, run.status as run_status,
           document.document_number
      from public.payment_run_items item
      join public.payment_runs run
        on run.id = item.payment_run_id and run.org_id = item.org_id
      left join public.documents document
        on document.id = item.source_document_id and document.org_id = item.org_id
     where item.org_id = new.org_id
       and item.status = 'selected'
       and item.source_open_line_id in (new.from_line_id, new.to_line_id)
     order by item.id
  loop
    if v_reservation.run_status = 'processing' then
      -- The run's own cash: the source line belongs to the payment document
      -- of the reserving run's instruction.
      if v_source_document is null then
        select entry.source_document_id into v_source_document
          from public.journal_lines line
          join public.journal_entries entry
            on entry.id = line.entry_id and entry.org_id = line.org_id
         where line.id = new.from_line_id and line.org_id = new.org_id;
      end if;
      if v_source_document is not null and exists (
        select 1 from public.payment_instructions instruction
         where instruction.id = v_reservation.payment_instruction_id
           and instruction.org_id = new.org_id
           and instruction.payment_run_id = v_reservation.payment_run_id
           and instruction.payment_document_id = v_source_document
      ) then
        continue;
      end if;
      -- The run's own credit: the same run reserved this credit line and
      -- planned it against this exact target.
      if exists (
        select 1 from public.payment_run_items credit
         where credit.org_id = new.org_id
           and credit.payment_run_id = v_reservation.payment_run_id
           and credit.kind = 'credit'
           and credit.status = 'selected'
           and credit.source_open_line_id = new.from_line_id
           and credit.credit_target_allocations @> jsonb_build_array(
                 jsonb_build_object('toLineId', new.to_line_id::text))
      ) then
        continue;
      end if;
    end if;
    raise exception '% is reserved by payment run % (%), which will pay it; settle it through that run, or cancel or roll back the run before settling it elsewhere',
      coalesce(v_reservation.document_number, 'this open item'),
      v_reservation.run_number,
      replace(v_reservation.run_status, '_', ' ')
      using errcode = '23514';
  end loop;
  return new;
end $$;


--
-- Name: FUNCTION application_respects_run_reservation(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.application_respects_run_reservation() IS 'Refuses an application that settles an open item reserved by a live payment run, unless it is that run''s own cash or planned credit written while the run posts.';


--
-- Name: assembly_disassembly_binding(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assembly_disassembly_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  operation_id uuid;
  operation public.assembly_disassemblies%ROWTYPE;
  source public.inventory_movements%ROWTYPE;
  component jsonb;
  actual_count integer;
BEGIN
  IF TG_TABLE_NAME='assembly_disassemblies' THEN operation_id:=NEW.id;
  ELSE operation_id:=NEW.assembly_disassembly_id; END IF;
  IF operation_id IS NULL THEN
    IF TG_TABLE_NAME='inventory_movements' THEN
    IF NEW.reverses_movement_id IS NOT NULL AND EXISTS(
      SELECT 1 FROM public.inventory_movements m WHERE m.id=NEW.reverses_movement_id AND m.org_id=NEW.org_id AND m.assembly_disassembly_id IS NOT NULL) THEN
      RAISE EXCEPTION 'a disassembly reversal must retain its operation identity';
    END IF;
    END IF;
    RETURN NEW;
  END IF;
  SELECT * INTO STRICT operation FROM public.assembly_disassemblies WHERE id=operation_id AND org_id=NEW.org_id;
  SELECT * INTO STRICT source FROM public.inventory_movements WHERE id=operation.build_movement_id AND org_id=operation.org_id;
  IF source.kind<>'assembly_build' OR source.status<>'posted' OR source.subsidiary_id<>operation.subsidiary_id
     OR operation.moved_on<source.moved_at::date OR NOT EXISTS(
       SELECT 1 FROM public.journal_entries e WHERE e.id=source.journal_entry_id AND e.org_id=operation.org_id
         AND e.book_id=operation.book_id AND e.origin='inventory' AND e.custom ? 'assemblyBuild') THEN
    RAISE EXCEPTION 'disassembly must bind to its original build, organization, legal entity and accounting book';
  END IF;
  IF operation.journal_entry_id IS NOT NULL THEN
    IF NOT EXISTS(SELECT 1 FROM public.journal_entries e WHERE e.id=operation.journal_entry_id AND e.org_id=operation.org_id
      AND e.book_id=operation.book_id AND e.subsidiary_id=operation.subsidiary_id AND e.origin='inventory' AND e.status IN ('posted','reversed')
      AND e.custom->'assemblyDisassembly'->>'operationId'=operation.id::text
      AND e.custom->'assemblyDisassembly'->'components'=operation.components) THEN
      RAISE EXCEPTION 'disassembly journal must retain the same operation and recovery evidence';
    END IF;
  ELSIF operation.withdrawn_value<>0 OR EXISTS(SELECT 1 FROM jsonb_array_elements(operation.components) c WHERE (c->>'value')::numeric<>0) THEN
    RAISE EXCEPTION 'a value-carrying disassembly requires a posted journal';
  END IF;
  SELECT count(*) INTO actual_count FROM public.inventory_movements m WHERE m.org_id=operation.org_id
    AND m.assembly_disassembly_id=operation.id AND m.kind IN ('assembly_disassembly','assembly_recovery');
  IF actual_count<>1+jsonb_array_length(operation.components) OR NOT EXISTS(
    SELECT 1 FROM public.inventory_movements m WHERE m.org_id=operation.org_id AND m.assembly_disassembly_id=operation.id
      AND m.kind='assembly_disassembly' AND m.item_id=source.item_id AND m.subsidiary_id=source.subsidiary_id
      AND m.stock_location_id=source.stock_location_id AND m.quantity=-operation.quantity AND m.total_value=-operation.withdrawn_value
      AND m.journal_entry_id IS NOT DISTINCT FROM operation.journal_entry_id AND m.status='posted') THEN
    RAISE EXCEPTION 'disassembly must record one complete quantity and value operation';
  END IF;
  FOR component IN SELECT value FROM jsonb_array_elements(operation.components) LOOP
    IF NOT component ?& ARRAY['itemId','quantity','value','originalCost']
      OR component->>'itemId' IS NULL OR component->>'quantity' IS NULL OR component->>'value' IS NULL OR component->>'originalCost' IS NULL
      OR (component->>'quantity')::numeric<=0 OR (component->>'value')::numeric<0 OR (component->>'originalCost')::numeric<0
      OR NOT EXISTS(SELECT 1 FROM public.inventory_movements m WHERE m.org_id=operation.org_id AND m.assembly_disassembly_id=operation.id
        AND m.kind='assembly_recovery' AND m.item_id=(component->>'itemId')::uuid AND m.subsidiary_id=source.subsidiary_id
        AND m.stock_location_id=source.stock_location_id AND m.quantity=(component->>'quantity')::numeric AND m.total_value=(component->>'value')::numeric
        AND m.journal_entry_id IS NOT DISTINCT FROM operation.journal_entry_id AND m.status='posted') THEN
      RAISE EXCEPTION 'each recovered component must match its recorded quantity, cost and legal entity';
    END IF;
  END LOOP;
  IF TG_TABLE_NAME='inventory_movements' THEN
  IF NEW.kind='return' AND NOT EXISTS(
    SELECT 1 FROM public.inventory_movements m WHERE m.id=NEW.reverses_movement_id AND m.org_id=NEW.org_id
      AND m.assembly_disassembly_id=operation.id AND m.item_id=NEW.item_id AND m.subsidiary_id=NEW.subsidiary_id
      AND m.stock_location_id=NEW.stock_location_id AND NEW.quantity=-m.quantity AND NEW.total_value=-m.total_value) THEN
    RAISE EXCEPTION 'a disassembly reversal must mirror its original movement';
  END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: assembly_disassembly_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assembly_disassembly_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF public.app_bypass_rls_active() AND coalesce(current_setting('openbooks.amend',true),'off')='on' THEN
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'physical disassembly evidence is immutable; use its controlled inventory movement reversal';
END $$;


--
-- Name: assert_active_user_has_role(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_active_user_has_role(checked_user_id uuid, checked_org_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE active boolean;
BEGIN
  -- Serialize activation and assignment removal on the same identity row.
  SELECT u.is_active INTO active
    FROM public.users u
   WHERE u.id = checked_user_id AND u.org_id = checked_org_id
   FOR UPDATE;
  IF active IS DISTINCT FROM true THEN
    RETURN;
  END IF;

  -- A locking read also refuses a surviving assignment deleted since a
  -- repeatable-read snapshot, instead of treating stale history as access.
  PERFORM a.id
    FROM public.role_assignments a
   WHERE a.user_id = checked_user_id AND a.org_id = checked_org_id
   ORDER BY a.id
   LIMIT 1 FOR KEY SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'active user % must have at least one explicit role assignment', checked_user_id
      USING ERRCODE = '23514', CONSTRAINT = 'active_user_role_required';
  END IF;
END;
$$;


--
-- Name: assert_document_totals_match_lines(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_document_totals_match_lines(p_document_id uuid, p_org_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_kind text;
    v_stored_subtotal numeric;
    v_stored_tax numeric;
    v_stored_total numeric;
    v_line_count integer;
    v_amount_sum numeric;
    v_tax_sum numeric;
    v_debit_sum numeric;
    v_want_subtotal numeric;
    v_want_tax numeric;
    v_want_total numeric;
BEGIN
    SELECT kind, subtotal, tax_total, total
      INTO v_kind, v_stored_subtotal, v_stored_tax, v_stored_total
      FROM public.documents
     WHERE id = p_document_id AND org_id = p_org_id;
    IF NOT FOUND THEN
        RETURN;
    END IF;
    SELECT count(*)::int,
           coalesce(sum(l.amount), 0),
           coalesce(sum(l.tax_amount), 0),
           coalesce(sum(l.amount) FILTER (WHERE l.amount > 0), 0)
      INTO v_line_count, v_amount_sum, v_tax_sum, v_debit_sum
      FROM public.document_lines l
     WHERE l.document_id = p_document_id AND l.org_id = p_org_id;
    IF v_line_count = 0 THEN
        RETURN;
    END IF;
    IF v_kind IN ('journal', 'pay_run') THEN
        v_want_tax := v_tax_sum;
        v_want_total := v_debit_sum;
        v_want_subtotal := v_debit_sum - v_tax_sum;
    ELSE
        v_want_subtotal := v_amount_sum;
        v_want_tax := v_tax_sum;
        v_want_total := v_amount_sum + v_tax_sum;
    END IF;
    IF v_stored_subtotal IS DISTINCT FROM v_want_subtotal
       OR v_stored_tax IS DISTINCT FROM v_want_tax
       OR v_stored_total IS DISTINCT FROM v_want_total THEN
        RAISE EXCEPTION
            'document % header totals do not tie to its lines: stored subtotal %, tax_total %, total % but its % line(s) sum to subtotal %, tax_total %, total %',
            p_document_id, v_stored_subtotal, v_stored_tax, v_stored_total,
            v_line_count, v_want_subtotal, v_want_tax, v_want_total
            USING ERRCODE = 'check_violation';
    END IF;
END;
$$;


--
-- Name: FUNCTION assert_document_totals_match_lines(p_document_id uuid, p_org_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.assert_document_totals_match_lines(p_document_id uuid, p_org_id uuid) IS 'openbooks:document_total_line_invariant:v1 - rejects committed document headers whose subtotal/tax_total/total disagree with their own lines (debit-side totals for journal-shaped kinds)';


--
-- Name: asset_basis_change_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.asset_basis_change_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'asset basis changes are immutable; approve an adjusting change'; END IF;
 IF NOT EXISTS(SELECT 1 FROM financial_changes f WHERE f.id=NEW.change_id AND f.org_id=NEW.org_id AND f.domain='asset' AND f.subject_id=NEW.asset_id AND f.status='approved') THEN RAISE EXCEPTION 'asset basis requires independent approval for this asset'; END IF;
 IF NOT EXISTS(SELECT 1 FROM fixed_assets a WHERE a.id=NEW.asset_id AND a.org_id=NEW.org_id) OR NOT EXISTS(SELECT 1 FROM accounting_books b WHERE b.id=NEW.book_id AND b.org_id=NEW.org_id) THEN RAISE EXCEPTION 'asset basis references another organization'; END IF;
 IF NEW.journal_entry_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM journal_entries e WHERE e.id=NEW.journal_entry_id AND e.org_id=NEW.org_id AND e.book_id=NEW.book_id AND e.status='posted' AND e.posting_date=NEW.effective_on AND e.subsidiary_id=(SELECT a.subsidiary_id FROM fixed_assets a WHERE a.org_id=NEW.org_id AND a.id=NEW.asset_id)) THEN RAISE EXCEPTION 'asset basis requires its posted book journal'; END IF;
 IF NEW.stub_journal_entry_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM journal_entries e WHERE e.id=NEW.stub_journal_entry_id AND e.org_id=NEW.org_id AND e.book_id=NEW.book_id AND e.status='posted' AND e.posting_date=NEW.effective_on AND e.subsidiary_id=(SELECT a.subsidiary_id FROM fixed_assets a WHERE a.org_id=NEW.org_id AND a.id=NEW.asset_id)) THEN RAISE EXCEPTION 'elapsed depreciation must reference its posted book journal'; END IF;
 -- Absence must match too: accepting NULL when the approval contains a group
 -- component would silently make consolidation infer a legal-book fraction.
 IF NEW.group_component IS DISTINCT FROM (SELECT f.before_state->'groupComponents'->NEW.book_id::text FROM financial_changes f WHERE f.org_id=NEW.org_id AND f.id=NEW.change_id AND f.operation IN('partial_disposal','intercompany_transfer')) OR (NEW.group_component IS NOT NULL AND NOT EXISTS(SELECT 1 FROM asset_transfer_bases t WHERE t.org_id=NEW.org_id AND t.receiving_asset_id=NEW.asset_id AND t.book_id=NEW.book_id AND t.reversed_by_change_id IS NULL)) THEN RAISE EXCEPTION 'group component basis must match its independently approved retained and removed measurements'; END IF;
 IF NEW.effective_on<>(SELECT f.effective_on FROM financial_changes f WHERE f.org_id=NEW.org_id AND f.id=NEW.change_id) THEN RAISE EXCEPTION 'basis date differs from the approved effective date'; END IF;
 RETURN NEW;
END $$;


--
-- Name: asset_capitalization_rule_terms_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.asset_capitalization_rule_terms_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF coalesce(current_setting('openbooks.amend', true), 'off') = 'on' THEN
    RETURN NEW;
  END IF;
  IF (NEW.org_id, NEW.subsidiary_id, NEW.match_kind, NEW.account_id, NEW.item_id, NEW.item_category, NEW.minimum_amount, NEW.effective_from)
     IS DISTINCT FROM
     (OLD.org_id, OLD.subsidiary_id, OLD.match_kind, OLD.account_id, OLD.item_id, OLD.item_category, OLD.minimum_amount, OLD.effective_from) THEN
    RAISE EXCEPTION 'capitalization rule terms are effective-dated; end this rule and add a new one from the change date' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: asset_capitalization_source_reversal_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.asset_capitalization_source_reversal_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF coalesce(current_setting('openbooks.amend', true), 'off') = 'on' THEN
    RETURN NEW;
  END IF;
  IF EXISTS (SELECT 1 FROM public.asset_proposals p
              WHERE p.org_id = NEW.org_id AND p.source_entry_id = NEW.id AND p.status = 'accepted') THEN
    RAISE EXCEPTION 'this transaction is the source of an accepted fixed-asset proposal; reverse the acceptance from Fixed Assets → Proposals before reversing it' USING ERRCODE = '23514';
  END IF;
  IF EXISTS (SELECT 1 FROM public.asset_cip_costs c
              WHERE c.org_id = NEW.org_id AND c.source_entry_id = NEW.id AND c.status = 'linked') THEN
    RAISE EXCEPTION 'this transaction carries a cost linked to construction in progress; unlink the cost from Fixed Assets → Construction in progress before reversing it' USING ERRCODE = '23514';
  END IF;
  IF EXISTS (SELECT 1 FROM public.asset_proposal_acceptances a
              WHERE a.org_id = NEW.org_id AND a.reclass_entry_id = NEW.id AND a.status = 'posted') THEN
    RAISE EXCEPTION 'this reclassification belongs to an accepted fixed-asset proposal; use Reverse acceptance on the proposal instead' USING ERRCODE = '23514';
  END IF;
  IF EXISTS (SELECT 1 FROM public.asset_cip_capitalizations k
              WHERE k.org_id = NEW.org_id AND k.entry_id = NEW.id AND k.status = 'posted') THEN
    RAISE EXCEPTION 'this journal belongs to a construction-in-progress capitalization; use Reverse capitalization on the record instead' USING ERRCODE = '23514';
  END IF;
  UPDATE public.asset_proposals
     SET status = 'voided', resolved_at = now(), resolved_by = NULL,
         resolution_reason = 'The source transaction was reversed.',
         updated_at = now(), updated_by = NEW.updated_by
   WHERE org_id = NEW.org_id AND source_entry_id = NEW.id AND status = 'pending';
  RETURN NEW;
END;
$$;


--
-- Name: asset_category_policy_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.asset_category_policy_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF ROW(NEW.id, NEW.org_id, NEW.asset_account_id,
         NEW.accumulated_depreciation_account_id, NEW.depreciation_expense_account_id,
         NEW.gain_loss_account_id, NEW.default_method, NEW.default_depreciation_method_id,
         NEW.default_life_months, NEW.default_convention)
     IS NOT DISTINCT FROM
     ROW(OLD.id, OLD.org_id, OLD.asset_account_id,
         OLD.accumulated_depreciation_account_id, OLD.depreciation_expense_account_id,
         OLD.gain_loss_account_id, OLD.default_method, OLD.default_depreciation_method_id,
         OLD.default_life_months, OLD.default_convention) THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.fixed_assets a
     WHERE a.org_id = OLD.org_id AND a.category_id = OLD.id
       AND (EXISTS (
         SELECT 1 FROM public.depreciation_schedules s
         JOIN public.depreciation_schedule_lines l ON l.org_id = s.org_id AND l.schedule_id = s.id
          WHERE s.org_id = a.org_id AND s.asset_id = a.id AND l.posted_amount IS NOT NULL
       ) OR EXISTS (
         SELECT 1 FROM public.asset_events e
         JOIN public.journal_entries j ON j.org_id = e.org_id AND j.id = e.journal_entry_id
          WHERE e.org_id = a.org_id AND e.asset_id = a.id AND j.status IN ('posted', 'reversed')
       ))
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      CONSTRAINT = 'asset_category_posted_policy',
      MESSAGE = 'Asset category accounting policy is fixed after financial history exists. Create a new category or use a controlled adjustment.';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: asset_changed_basis_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.asset_changed_basis_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN RETURN NEW; END IF;
 IF EXISTS(SELECT 1 FROM asset_basis_changes x WHERE x.org_id=OLD.org_id AND x.asset_id=OLD.id) OR OLD.transferred_from_asset_id IS NOT NULL THEN
  IF (NEW.org_id,NEW.id,NEW.subsidiary_id,NEW.category_id,NEW.acquisition_cost,NEW.salvage_value,NEW.in_service_on,NEW.opening_accumulated_depreciation,NEW.opening_accumulated_as_of,NEW.asset_account_id,NEW.accumulated_depreciation_account_id,NEW.depreciation_expense_account_id,NEW.depreciation_method,NEW.depreciation_method_id,NEW.useful_life_months,NEW.depreciation_rate_percent,NEW.depreciation_convention,NEW.depreciation_units_total,NEW.transferred_from_asset_id) IS DISTINCT FROM (OLD.org_id,OLD.id,OLD.subsidiary_id,OLD.category_id,OLD.acquisition_cost,OLD.salvage_value,OLD.in_service_on,OLD.opening_accumulated_depreciation,OLD.opening_accumulated_as_of,OLD.asset_account_id,OLD.accumulated_depreciation_account_id,OLD.depreciation_expense_account_id,OLD.depreciation_method,OLD.depreciation_method_id,OLD.useful_life_months,OLD.depreciation_rate_percent,OLD.depreciation_convention,OLD.depreciation_units_total,OLD.transferred_from_asset_id) THEN RAISE EXCEPTION 'approved asset basis cannot be rewritten; propose a lifecycle change'; END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: asset_event_append_only_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.asset_event_append_only_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE source record;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP IN('UPDATE','DELETE') THEN
  IF openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN coalesce(NEW,OLD); END IF;
  RAISE EXCEPTION 'asset lifecycle evidence is append-only; post a linked reversal event';
 END IF;
 IF NEW.kind='reversed' THEN
  SELECT * INTO source FROM asset_events WHERE id=NEW.reverses_event_id FOR SHARE;
  IF source.id IS NULL OR source.org_id<>NEW.org_id OR source.asset_id<>NEW.asset_id OR source.kind NOT IN('revalued','impaired','disposed','written_off','partially_disposed','transferred','acquired') THEN RAISE EXCEPTION 'an asset reversal must reference a reversible event for the same tenant and asset'; END IF;
  IF source.financial_change_id IS NOT NULL THEN
   IF NEW.book_id IS DISTINCT FROM source.book_id OR NOT EXISTS(SELECT 1 FROM financial_changes f WHERE f.org_id=NEW.org_id AND f.id=NEW.financial_change_id AND f.domain='asset' AND f.operation='reversal' AND f.status='approved' AND f.payload->>'sourceChangeId'=source.financial_change_id::text) THEN RAISE EXCEPTION 'governed asset events require the approved correction of their original change and book'; END IF;
  ELSIF source.kind IN('acquired','partially_disposed','transferred') THEN
   RAISE EXCEPTION 'this acquisition or transfer has no governed correction evidence';
  END IF;
  IF source.financial_change_id IS NOT NULL AND ((source.journal_entry_id IS NULL) IS DISTINCT FROM (NEW.journal_entry_id IS NULL) OR (source.journal_entry_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM journal_entries e WHERE e.org_id=NEW.org_id AND e.id=NEW.journal_entry_id AND e.reverses_entry_id=source.journal_entry_id AND e.status='posted'))) THEN RAISE EXCEPTION 'asset correction event must link the exact reversing journal'; END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: asset_lifecycle_reference_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.asset_lifecycle_reference_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_TABLE_NAME='fixed_assets' THEN
  IF NEW.transferred_from_asset_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM fixed_assets a WHERE a.org_id=NEW.org_id AND a.id=NEW.transferred_from_asset_id AND a.id<>NEW.id) THEN RAISE EXCEPTION 'the source asset must belong to the same organization'; END IF;
 ELSE
  IF NEW.financial_change_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM financial_changes f JOIN fixed_assets a ON a.org_id=f.org_id AND a.id=NEW.asset_id WHERE f.org_id=NEW.org_id AND f.id=NEW.financial_change_id AND f.domain='asset' AND f.status='approved' AND f.effective_on=NEW.occurred_on AND (f.subject_id=a.id OR (a.transferred_from_asset_id=f.subject_id AND (NEW.kind='acquired' AND f.operation='intercompany_transfer' OR NEW.kind='reversed' AND f.operation='reversal')))) THEN RAISE EXCEPTION 'asset event requires independent approval for this asset and effective date'; END IF;
  IF NEW.book_id IS NOT NULL AND (NOT EXISTS(SELECT 1 FROM accounting_books b WHERE b.org_id=NEW.org_id AND b.id=NEW.book_id) OR (NEW.journal_entry_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM journal_entries e WHERE e.org_id=NEW.org_id AND e.id=NEW.journal_entry_id AND e.book_id=NEW.book_id))) THEN RAISE EXCEPTION 'asset event book must match its tenant and journal'; END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: asset_transfer_history_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.asset_transfer_history_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END IF;
 IF TG_TABLE_NAME='asset_transfer_bases' THEN
  IF TG_OP='INSERT' THEN
   IF NOT EXISTS(SELECT 1 FROM fixed_assets a WHERE a.org_id=NEW.org_id AND a.id=NEW.source_asset_id AND a.subsidiary_id=NEW.seller_subsidiary_id) OR NOT EXISTS(SELECT 1 FROM fixed_assets a WHERE a.org_id=NEW.org_id AND a.id=NEW.receiving_asset_id AND a.subsidiary_id=NEW.buyer_subsidiary_id AND a.transferred_from_asset_id=NEW.source_asset_id) OR NOT EXISTS(SELECT 1 FROM subsidiaries s WHERE s.org_id=NEW.org_id AND s.id=NEW.elimination_subsidiary_id AND s.is_elimination AND s.base_currency=NEW.group_currency) OR NOT EXISTS(SELECT 1 FROM accounting_books b WHERE b.org_id=NEW.org_id AND b.id=NEW.book_id) THEN RAISE EXCEPTION 'transfer evidence must reference its tenant, asset owners, book and group currency'; END IF;
   IF NOT EXISTS(SELECT 1 FROM financial_changes f WHERE f.org_id=NEW.org_id AND f.id=NEW.change_id AND f.subject_id=NEW.source_asset_id AND f.domain='asset' AND f.operation='intercompany_transfer' AND f.status='approved') THEN RAISE EXCEPTION 'transfer basis requires its independently approved change'; END IF;
  ELSIF TG_OP='UPDATE' THEN
   IF OLD.reversed_by_change_id IS NOT NULL OR NEW.reversed_by_change_id IS NULL OR NEW.reversed_on IS NULL OR NEW.reversed_on<OLD.effective_on OR (to_jsonb(NEW)-ARRAY['reversed_by_change_id','reversed_on']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['reversed_by_change_id','reversed_on']) OR NOT EXISTS(SELECT 1 FROM financial_changes f WHERE f.org_id=OLD.org_id AND f.id=NEW.reversed_by_change_id AND f.domain='asset' AND f.operation='reversal' AND f.subject_id=OLD.source_asset_id AND f.payload->>'sourceChangeId'=OLD.change_id::text AND f.status='approved') THEN RAISE EXCEPTION 'only an independently approved reversal may close a transfer basis'; END IF;
  ELSE RAISE EXCEPTION 'asset transfer evidence is immutable'; END IF;
 ELSE
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'asset transfer consolidation evidence is immutable'; END IF;
  IF NOT EXISTS(SELECT 1 FROM asset_transfer_bases b JOIN journal_entries e ON e.org_id=b.org_id AND e.id=NEW.journal_entry_id AND e.book_id=b.book_id AND e.subsidiary_id=b.elimination_subsidiary_id AND e.status='posted' AND e.period_id=NEW.period_id JOIN accounting_periods p ON p.org_id=e.org_id AND p.id=e.period_id WHERE b.org_id=NEW.org_id AND b.id=NEW.transfer_id) THEN RAISE EXCEPTION 'asset consolidation evidence requires its posted group/book journal'; END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: asset_transfer_measurement_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.asset_transfer_measurement_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'approved group asset measurements are immutable; propose a correcting group valuation'; END IF;
 IF NOT EXISTS(SELECT 1 FROM asset_transfer_bases b JOIN asset_events v ON v.org_id=b.org_id AND v.asset_id=b.receiving_asset_id JOIN journal_entries e ON e.org_id=v.org_id AND e.id=v.journal_entry_id JOIN financial_changes f ON f.org_id=b.org_id AND f.id=NEW.change_id WHERE b.org_id=NEW.org_id AND b.id=NEW.transfer_id AND b.reversed_by_change_id IS NULL AND v.id=NEW.source_event_id AND v.kind IN('impaired','revalued') AND v.occurred_on=NEW.effective_on AND e.book_id=b.book_id AND e.status='posted' AND f.subject_id=b.receiving_asset_id AND f.domain='asset' AND f.operation='group_valuation' AND f.status='approved' AND f.effective_on=NEW.effective_on) THEN RAISE EXCEPTION 'group valuation requires its approved asset, book and source valuation'; END IF;
 RETURN NEW;
END $$;


--
-- Name: audit_log_append_only_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_log_append_only_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  if tg_op = 'DELETE' and openbooks_sandbox_wipe_allowed(old.org_id) then
    return old;
  end if;
  raise exception 'audit_log is append-only';
end $$;


--
-- Name: uuid_generate_v7(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.uuid_generate_v7() RETURNS uuid
    LANGUAGE sql PARALLEL SAFE
    AS $$
      select encode(set_bit(set_bit(overlay(uuid_send(gen_random_uuid())
        placing substring(int8send((extract(epoch from clock_timestamp()) * 1000)::bigint) from 3)
        from 1 for 6), 52, 1), 53, 1), 'hex')::uuid
    $$;


--
-- Name: party_bank_accounts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.party_bank_accounts (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    party_id uuid NOT NULL,
    bank_name text,
    country text,
    currency text,
    routing jsonb DEFAULT '{}'::jsonb NOT NULL,
    account_number_encrypted text,
    account_last_four text,
    approved_at date,
    approved_by uuid,
    is_active boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    approval_status text DEFAULT 'pending'::text NOT NULL,
    submitted_by uuid,
    submitted_at timestamp with time zone,
    retired_at timestamp with time zone,
    retired_by uuid,
    retirement_reason text,
    source_change_request_id uuid,
    CONSTRAINT party_bank_accounts_retirement_evidence CHECK (((retired_at IS NULL) OR ((is_active = false) AND (retired_by IS NOT NULL) AND (retirement_reason IS NOT NULL) AND ((length(btrim(retirement_reason)) >= 5) AND (length(btrim(retirement_reason)) <= 500)))))
);

ALTER TABLE ONLY public.party_bank_accounts FORCE ROW LEVEL SECURITY;


--
-- Name: bank_approval_fingerprint(public.party_bank_accounts); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_approval_fingerprint(account public.party_bank_accounts) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 SELECT encode(sha256(convert_to(jsonb_build_array(account.id,account.org_id,account.party_id,
   account.bank_name,account.country,account.currency,account.routing,account.account_number_encrypted,
   extract(epoch FROM account.submitted_at))::text,'UTF8')),'hex')
$$;


--
-- Name: bank_flow_admission_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_flow_admission_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE fingerprint text;
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND NEW.source_change_request_id IS DISTINCT FROM OLD.source_change_request_id THEN
  RAISE EXCEPTION 'The bank detail source request is immutable. File a new bank change.';
 END IF;
 IF NEW.source_change_request_id IS NOT NULL THEN
  IF TG_OP='INSERT' THEN
   IF NEW.approval_status<>'approved' OR NOT NEW.is_active OR NEW.approved_at IS NULL
     OR NOT public.employment_bank_projection_authorized(NEW) THEN
    RAISE EXCEPTION 'Apply these exact bank details through their completed native employment-change Flow.';
   END IF;
  ELSIF public.bank_approval_fingerprint(NEW) IS DISTINCT FROM public.bank_approval_fingerprint(OLD)
    OR ROW(NEW.approved_by,NEW.approved_at,NEW.submitted_by,NEW.approval_status)
      IS DISTINCT FROM ROW(OLD.approved_by,OLD.approved_at,OLD.submitted_by,OLD.approval_status) THEN
   RAISE EXCEPTION 'Approved employment bank details are immutable. File a replacement bank change.';
  END IF;
  RETURN NEW;
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.approval_status<>'pending' OR NEW.is_active OR NEW.approved_by IS NOT NULL OR NEW.approved_at IS NOT NULL THEN
   RAISE EXCEPTION 'Save new bank details pending native Flow routing.';
  END IF;
  RETURN NEW;
 END IF;
 IF NEW.approval_status='approved' AND (OLD.approval_status<>'approved'
   OR public.bank_approval_fingerprint(NEW) IS DISTINCT FROM public.bank_approval_fingerprint(OLD)) THEN
  fingerprint:=public.bank_approval_fingerprint(NEW);
  IF public.flow_ungated_submission_authorized(NEW.org_id,'party_bank_account',NEW.id,NEW.approved_by,
     jsonb_build_object('approvalFingerprint',fingerprint)) THEN RETURN NEW; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.flow_gates g JOIN public.flow_runs r ON r.org_id=g.org_id AND r.id=g.run_id
    WHERE g.org_id=NEW.org_id AND g.subject_kind='party_bank_account' AND g.subject_id=NEW.id
      AND g.status='approved' AND g.decided_by=NEW.approved_by
      AND r.context->>'approvalFingerprint'=fingerprint
      AND r.context->'submissionPolicy'->>'flowId'=r.flow_id::text
      AND (NEW.approved_by IS DISTINCT FROM NEW.submitted_by OR EXISTS(
        SELECT 1 FROM jsonb_array_elements(r.context->'submissionPolicy'->'graph'->'nodes') node
         WHERE node->>'id'=g.node_id AND node->'data'->>'kind'='gate'
          AND node->'data'->'gate'->'preventSelfApproval'='false'::jsonb)))
   OR EXISTS(SELECT 1 FROM public.flow_gates g WHERE g.org_id=NEW.org_id AND g.subject_kind='party_bank_account'
      AND g.subject_id=NEW.id AND g.status IN('pending','escalated')) THEN
   RAISE EXCEPTION 'Release the current bank details through their configured native Flow gates.';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: benefit_catalog_attach(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.benefit_catalog_attach() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 INSERT INTO public.hrm_benefit_catalog(id,org_id,insured_plan_id,employer_program_id,entitlement_plan_id,created_at,created_by,updated_at,updated_by)
 VALUES(NEW.id,NEW.org_id,
  CASE WHEN TG_TABLE_NAME='hrm_benefit_plans' THEN NEW.id END,
  CASE WHEN TG_TABLE_NAME='hrm_benefit_programs' THEN NEW.id END,
  CASE WHEN TG_TABLE_NAME='entitlement_plans' THEN NEW.id END,
  NEW.created_at,NEW.created_by,NEW.updated_at,NEW.updated_by);
 RETURN NEW;
END $$;


--
-- Name: benefit_catalog_identity_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.benefit_catalog_identity_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='UPDATE' THEN
  RAISE EXCEPTION 'Program identity is immutable; change its native program record instead.' USING ERRCODE='23514';
 END IF;
 IF EXISTS(SELECT 1 FROM public.hrm_benefit_plans WHERE org_id=OLD.org_id AND id=OLD.insured_plan_id)
  OR EXISTS(SELECT 1 FROM public.hrm_benefit_programs WHERE org_id=OLD.org_id AND id=OLD.employer_program_id)
  OR EXISTS(SELECT 1 FROM public.entitlement_plans WHERE org_id=OLD.org_id AND id=OLD.entitlement_plan_id) THEN
  RAISE EXCEPTION 'A program identity cannot be removed while its native offering exists; retire or delete the native program through its record action.' USING ERRCODE='23514';
 END IF;
 RETURN OLD;
END $$;


--
-- Name: benefit_clone_decision_evidence(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.benefit_clone_decision_evidence(evidence jsonb, seed uuid) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE result jsonb:=evidence; identity_key text; entries_data jsonb;
BEGIN
 IF evidence IS NULL THEN RETURN NULL; END IF;
 FOREACH identity_key IN ARRAY ARRAY['planId','runId','submissionId'] LOOP
  IF jsonb_typeof(result->identity_key)='string' THEN
   result:=jsonb_set(result,ARRAY[identity_key],to_jsonb(public.ob_rebase((result->>identity_key)::uuid,seed)::text));
  END IF;
 END LOOP;
 IF jsonb_typeof(result->'runs')='array' THEN
  SELECT COALESCE(jsonb_agg(value
   || CASE WHEN jsonb_typeof(value->'id')='string' THEN jsonb_build_object('id',public.ob_rebase((value->>'id')::uuid,seed)) ELSE '{}'::jsonb END
   || CASE WHEN value ? 'context' THEN jsonb_build_object('context',public.benefit_clone_submission_evidence(value->'context',seed)) ELSE '{}'::jsonb END
   ORDER BY ordinal),'[]'::jsonb) INTO entries_data
   FROM jsonb_array_elements(result->'runs') WITH ORDINALITY AS entries(value,ordinal);
  result:=jsonb_set(result,'{runs}',entries_data);
 END IF;
 IF jsonb_typeof(result->'gates')='array' THEN
  SELECT COALESCE(jsonb_agg(value
   || CASE WHEN jsonb_typeof(value->'id')='string' THEN jsonb_build_object('id',public.ob_rebase((value->>'id')::uuid,seed)) ELSE '{}'::jsonb END
   || CASE WHEN jsonb_typeof(value->'decided_by')='string' THEN jsonb_build_object('decided_by',public.ob_rebase((value->>'decided_by')::uuid,seed)) ELSE '{}'::jsonb END
   ORDER BY ordinal),'[]'::jsonb) INTO entries_data
   FROM jsonb_array_elements(result->'gates') WITH ORDINALITY AS entries(value,ordinal);
  result:=jsonb_set(result,'{gates}',entries_data);
 END IF;
 IF jsonb_typeof(result->'policy')='object' THEN
  result:=jsonb_set(result,'{policy}',public.flow_clone_evidence(result->'policy',seed,'policy'));
 END IF;
 RETURN result;
END $$;


--
-- Name: benefit_clone_submission_evidence(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.benefit_clone_submission_evidence(evidence jsonb, seed uuid) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
 SELECT public.flow_clone_evidence(evidence,seed,'context')
$$;


--
-- Name: benefit_enrollment_submission_source(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.benefit_enrollment_submission_source(input_org uuid, input_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
select jsonb_build_object(
    'planId',p.id,'planCode',p.code,'planName',p.name,'planKind',p.kind,'approvalMode',p.approval_mode,
    'classKey',e.class_key,'matchEligible',e.match_eligible,'employmentId',e.employment_id,'legalEntityId',w.employer_subsidiary_id,
    'departmentId',(select department_id from employment_assignment_versions v where v.org_id=e.org_id and v.employment_id=e.employment_id
      and v.recorded_until is null and v.is_primary and v.effective_from<=e.effective_from and (v.effective_to is null or v.effective_to>e.effective_from) order by v.effective_from desc,v.id desc limit 1),
    'effectiveFrom',e.effective_from::text,'effectiveTo',e.effective_to::text,'replacesEnrollmentId',e.replaces_enrollment_id,'createdBy',e.created_by,
    'contributions',(select jsonb_agg(jsonb_build_object('ruleId',r.id,'name',r.name,'kind',r.kind,'basis',r.basis,'electionMode',t.election_mode,
      'electedRate',t.elected_rate::text,'policyRate',r.rate::text,'rateFormula',r.rate_formula,'hoursCoverage',r.hours_coverage,'effectiveFrom',t.effective_from::text,'effectiveTo',t.effective_to::text,
      'declaredPeriodsPerYear',t.declared_periods_per_year) order by r.position,t.id) from hrm_benefit_enrollment_terms t
      join hrm_benefit_contribution_rules r on r.org_id=t.org_id and r.id=t.rule_id where t.org_id=e.org_id and t.enrollment_id=e.id))
    from hrm_benefit_enrollments e join hrm_benefit_plans p on p.org_id=e.org_id and p.id=e.plan_id
    join worker_employments w on w.org_id=e.org_id and w.id=e.employment_id where e.org_id=input_org and e.id=input_id and e.status='elected';
$$;


--
-- Name: benefit_enrollment_workflow_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.benefit_enrollment_workflow_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE run_row public.flow_runs%ROWTYPE; mode text; unused_withdrawal boolean := false;
BEGIN
 IF TG_OP='INSERT' THEN
  IF public.benefit_historical_clone_matches(TG_RELID,to_jsonb(NEW)) THEN RETURN NEW; END IF;
  IF NEW.status NOT IN ('elected','waived') OR NEW.flow_run_id IS NOT NULL OR NEW.submission_snapshot IS NOT NULL OR NEW.decision_snapshot IS NOT NULL THEN
   RAISE EXCEPTION 'Create a benefit election, then submit it through tenant Flows; active coverage cannot be supplied on creation.' USING ERRCODE='23514';
  END IF;
  IF NEW.replaces_enrollment_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.hrm_benefit_enrollments e WHERE e.org_id=NEW.org_id AND e.id=NEW.replaces_enrollment_id AND e.employment_id=NEW.employment_id AND e.plan_id=NEW.plan_id AND e.status='active' AND e.effective_from<NEW.effective_from) THEN RAISE EXCEPTION 'A successor must replace active coverage on the same employment and plan from a later date.' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 IF OLD.status IN ('active','ended') AND NEW.status='cancelled' THEN
  PERFORM pg_advisory_xact_lock(hashtextextended('openbooks:benefit-recurring:' || NEW.org_id::text,0));
  unused_withdrawal := coalesce(current_setting('openbooks.hrm_benefit_withdrawal',true)=NEW.org_id::text || ':' || NEW.id::text || ':' || NEW.updated_by::text,false)
    AND nullif(btrim(NEW.ended_reason),'') IS NOT NULL
    AND NOT EXISTS(SELECT 1 FROM public.pay_run_benefit_allocations a WHERE a.org_id=OLD.org_id AND a.enrollment_id=OLD.id)
    AND NOT EXISTS(SELECT 1 FROM public.hrm_benefit_payroll_inputs i WHERE i.org_id=OLD.org_id AND i.enrollment_id=OLD.id)
    AND NOT EXISTS(SELECT 1 FROM public.hrm_benefit_enrollments e WHERE e.org_id=OLD.org_id AND e.replaces_enrollment_id=OLD.id AND e.status IN ('elected','pending_approval'));
 END IF;
 IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
  OLD.status='elected' AND NEW.status IN ('pending_approval','active','cancelled') OR
  OLD.status='pending_approval' AND NEW.status IN ('active','cancelled') OR
  OLD.status='active' AND (NEW.status='ended' OR (NEW.status='cancelled'
    AND NOT EXISTS(SELECT 1 FROM public.pay_run_benefit_allocations a WHERE a.org_id=OLD.org_id AND a.enrollment_id=OLD.id AND a.status IN ('committed','voided'))
    AND NOT EXISTS(SELECT 1 FROM public.hrm_benefit_payroll_inputs i WHERE i.org_id=OLD.org_id AND i.enrollment_id=OLD.id)
    AND EXISTS(SELECT 1 FROM public.worker_employment_versions v WHERE v.org_id=OLD.org_id AND v.employment_id=OLD.employment_id AND v.recorded_until IS NULL AND v.status='terminated' AND v.effective_from<=OLD.effective_from)) OR (NEW.status='cancelled' AND unused_withdrawal)) OR (OLD.status='ended' AND NEW.status='cancelled' AND unused_withdrawal) OR OLD.status='waived' AND NEW.status='cancelled') THEN
  RAISE EXCEPTION 'This benefit lifecycle transition is not permitted; use the enrollment record actions or create a successor election.' USING ERRCODE='23514';
 END IF;
 IF (OLD.submission_snapshot IS NOT NULL OR OLD.status IN ('active','ended')) AND
  ROW(NEW.org_id,NEW.employment_id,NEW.plan_id,NEW.currency,NEW.effective_from) IS DISTINCT FROM
  ROW(OLD.org_id,OLD.employment_id,OLD.plan_id,OLD.currency,OLD.effective_from) THEN
  RAISE EXCEPTION 'Submitted coverage identity and start date are immutable; create a successor enrollment.' USING ERRCODE='23514';
 END IF;
 IF OLD.status='ended' AND NEW.effective_to IS DISTINCT FROM OLD.effective_to THEN
  RAISE EXCEPTION 'Ended coverage dates are immutable; use a correcting successor election.' USING ERRCODE='23514';
 END IF;
 IF OLD.submission_snapshot IS NULL AND NEW.submission_snapshot IS NOT NULL THEN
  IF OLD.status<>'elected' OR NEW.submission_snapshot IS DISTINCT FROM public.benefit_enrollment_submission_source(OLD.org_id,OLD.id)
   OR NEW.submitted_by IS NULL OR NEW.submitted_by IS DISTINCT FROM NEW.updated_by OR NEW.submitted_at IS NULL THEN
   RAISE EXCEPTION 'Benefit submission must pin the exact contribution elections and tenant Flow policy; submit through its record action.' USING ERRCODE='23514';
  END IF;
 END IF;
 IF OLD.submission_snapshot IS NOT NULL AND (NEW.submission_snapshot IS DISTINCT FROM OLD.submission_snapshot OR NEW.submitted_by IS DISTINCT FROM OLD.submitted_by OR NEW.submitted_at IS DISTINCT FROM OLD.submitted_at
  OR NEW.class_key IS DISTINCT FROM OLD.class_key OR NEW.match_eligible IS DISTINCT FROM OLD.match_eligible OR NEW.replaces_enrollment_id IS DISTINCT FROM OLD.replaces_enrollment_id) THEN
  RAISE EXCEPTION 'Submitted benefit evidence is immutable; change the enrollment through its record action.' USING ERRCODE='23514';
 END IF;
 IF OLD.status IN ('active','ended') AND (NEW.class_key IS DISTINCT FROM OLD.class_key OR NEW.match_eligible IS DISTINCT FROM OLD.match_eligible) THEN
  RAISE EXCEPTION 'Active contribution classification is immutable; change the enrollment through its record action.' USING ERRCODE='23514';
 END IF;
 IF OLD.decision_snapshot IS NOT NULL AND NEW.decision_snapshot IS DISTINCT FROM OLD.decision_snapshot THEN RAISE EXCEPTION 'Benefit approval decisions are immutable; create a successor enrollment.' USING ERRCODE='23514'; END IF;
 IF OLD.flow_run_id IS NOT NULL AND NEW.flow_run_id IS DISTINCT FROM OLD.flow_run_id THEN RAISE EXCEPTION 'Benefit workflow linkage is immutable; create a successor enrollment.' USING ERRCODE='23514'; END IF;
 IF NEW.status='active' AND OLD.status<>'active' THEN
  IF NEW.submission_snapshot IS NULL OR NEW.decision_snapshot IS NULL OR NEW.decision_snapshot->>'outcome' IS DISTINCT FROM 'approved'
   OR NEW.submitted_by IS NULL OR NEW.submitted_at IS NULL OR NOT EXISTS (SELECT 1 FROM public.hrm_benefit_enrollment_terms t WHERE t.org_id=NEW.org_id AND t.enrollment_id=NEW.id) THEN
   RAISE EXCEPTION 'Coverage requires explicit contribution elections and submission evidence; submit the enrollment through its record action.' USING ERRCODE='23514';
  END IF;
 END IF;
 IF NEW.flow_run_id IS NOT NULL THEN
  SELECT * INTO run_row FROM public.flow_runs WHERE org_id=NEW.org_id AND id=NEW.flow_run_id AND subject_kind='hrm_benefit_enrollment' AND subject_id=NEW.id AND trigger='on_submit';
  IF NOT FOUND OR run_row.created_by IS DISTINCT FROM NEW.submitted_by
   OR run_row.context->>'planId' IS DISTINCT FROM NEW.plan_id::text OR run_row.context->>'employmentId' IS DISTINCT FROM NEW.employment_id::text
   OR run_row.context->'contributions' IS DISTINCT FROM NEW.submission_snapshot->'contributions' THEN
   RAISE EXCEPTION 'Benefit workflow evidence must match the enrollment, organization, submitter and elections; submit through its record action.' USING ERRCODE='23514';
  END IF;
 END IF;
 IF NEW.status='pending_approval' AND OLD.status<>'pending_approval' AND NEW.flow_run_id IS NULL THEN RAISE EXCEPTION 'Submit the enrollment to a configured native Flow before pending approval.' USING ERRCODE='23514'; END IF;
 IF NEW.status='active' AND OLD.status<>'active' THEN
  mode:=NEW.decision_snapshot->>'mode';
  IF mode='ungated' THEN
   IF NOT public.flow_ungated_submission_authorized(NEW.org_id,'hrm_benefit_enrollment',NEW.id,NEW.submitted_by,NEW.submission_snapshot) THEN
    RAISE EXCEPTION 'Coverage requires its complete ungated Flow submission receipt.' USING ERRCODE='23514';
   END IF;
  ELSIF mode='human' THEN
   IF NEW.flow_run_id IS NULL OR NEW.decision_snapshot->>'runId' IS DISTINCT FROM NEW.flow_run_id::text
    OR current_setting('openbooks.hrm_benefit_release',true) IS DISTINCT FROM NEW.org_id::text || ':' || NEW.id::text || ':' || NEW.updated_by::text
    OR NOT public.benefit_flow_decision_authorized(NEW.org_id,'hrm_benefit_enrollment',NEW.id,NEW.flow_run_id,NEW.updated_by,'approved') THEN
    RAISE EXCEPTION 'Complete every current enrollment Flow gate through its assigned decision before releasing coverage.' USING ERRCODE='23514';
   END IF;
  ELSE
   RAISE EXCEPTION 'Coverage release requires a canonical ungated receipt or completed native Flow gates.' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: benefit_flow_decision_authorized(uuid, text, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.benefit_flow_decision_authorized(organization uuid, kind text, subject uuid, linked_run uuid, actor uuid, outcome text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 SELECT EXISTS(SELECT 1 FROM public.flow_submissions s WHERE s.org_id=organization AND s.subject_kind=kind
  AND s.subject_id=subject AND s.policy->>'kind'='gated' AND s.policy->'runIds' ? linked_run::text
  AND public.flow_submission_runs_valid(s.org_id,s.subject_kind,s.subject_id,s.id)
  AND NOT EXISTS(SELECT 1 FROM public.flow_submissions newer WHERE newer.org_id=s.org_id
    AND newer.subject_kind=s.subject_kind AND newer.subject_id=s.subject_id
    AND (newer.created_at,newer.id)>(s.created_at,s.id))
  AND NOT EXISTS(SELECT 1 FROM public.flow_gates g WHERE g.org_id=s.org_id
    AND g.subject_kind=s.subject_kind AND g.subject_id=s.subject_id AND g.status IN('pending','escalated'))
  AND (outcome='rejected' OR outcome='approved' AND public.flow_submission_approved(s.org_id,s.subject_kind,s.subject_id,s.id))
  AND EXISTS(SELECT 1 FROM public.flow_gates g JOIN public.flow_runs r ON r.org_id=g.org_id AND r.id=g.run_id
    WHERE g.org_id=s.org_id AND g.subject_kind=s.subject_kind AND g.subject_id=s.subject_id
      AND s.policy->'runIds' ? r.id::text AND r.status IN('waiting','completed') AND r.error IS NULL
      AND g.status=outcome AND g.decided_by=actor AND g.decided_at IS NOT NULL
      AND (actor<>s.actor_id OR EXISTS(SELECT 1 FROM jsonb_array_elements(r.context #> '{submissionPolicy,graph,nodes}') node
        WHERE node->>'id'=g.node_id AND node->'data'->>'kind'='gate'
          AND node #> '{data,gate,preventSelfApproval}'='false'::jsonb))))
$$;


--
-- Name: benefit_historical_clone_matches(regclass, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.benefit_historical_clone_matches(relation regclass, candidate jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE target record; original jsonb; expected jsonb; column_row record; removed jsonb;
BEGIN
 IF NOT public.openbooks_clone_authority() OR relation NOT IN (
  'public.hrm_benefit_enrollments'::regclass,'public.hrm_benefit_enrollment_terms'::regclass,
  'public.hrm_benefit_payroll_inputs'::regclass) THEN RETURN false; END IF;
 SELECT o.id,o.sandbox_of,o.sandbox_seed,s.masked INTO target FROM public.orgs o
 JOIN public.sandboxes s ON s.org_id=o.id AND s.production_org_id=o.sandbox_of
 JOIN public.orgs source ON source.id=o.sandbox_of
 WHERE o.id=(candidate->>'org_id')::uuid AND o.env_kind='sandbox' AND o.sandbox_seed IS NOT NULL;
 IF NOT FOUND THEN RETURN false; END IF;
 EXECUTE format('SELECT to_jsonb(original) FROM %s original WHERE original.org_id=$1 AND public.ob_rebase(original.id,$2)=$3',relation)
 INTO original USING target.sandbox_of,target.sandbox_seed,(candidate->>'id')::uuid;
 IF original IS NULL THEN RETURN false; END IF;
 expected:=original;
 FOR column_row IN SELECT attname,atttypid,attnotnull FROM pg_catalog.pg_attribute
  WHERE attrelid=relation AND attnum>0 AND NOT attisdropped LOOP
  IF column_row.attname='org_id' THEN
   expected:=jsonb_set(expected,ARRAY[column_row.attname],to_jsonb(target.id));
  ELSIF column_row.atttypid='uuid'::regtype AND jsonb_typeof(original->column_row.attname)='string' THEN
   expected:=jsonb_set(expected,ARRAY[column_row.attname],to_jsonb(public.ob_rebase((original->>column_row.attname)::uuid,target.sandbox_seed)));
  ELSIF relation='public.hrm_benefit_enrollments'::regclass AND column_row.attname='submission_snapshot' THEN
   expected:=jsonb_set(expected,ARRAY[column_row.attname],COALESCE(public.benefit_clone_submission_evidence(original->column_row.attname,target.sandbox_seed),'null'::jsonb));
  ELSIF relation='public.hrm_benefit_enrollments'::regclass AND column_row.attname='decision_snapshot' THEN
   expected:=jsonb_set(expected,ARRAY[column_row.attname],COALESCE(public.benefit_clone_decision_evidence(original->column_row.attname,target.sandbox_seed),'null'::jsonb));
  END IF;
  -- Only existing value-removing policies may remove evidence from a masked
  -- copy. Masking never permits changed rates, dates, state or identities.
  IF target.masked AND column_row.attname IN ('submission_snapshot','decision_snapshot','provenance','source_decimal','override_reason')
   AND EXISTS(SELECT 1 FROM public.masking_policies p WHERE p.org_id=target.sandbox_of
    AND p.table_name=CASE relation WHEN 'public.hrm_benefit_enrollments'::regclass THEN 'hrm_benefit_enrollments'
     WHEN 'public.hrm_benefit_enrollment_terms'::regclass THEN 'hrm_benefit_enrollment_terms' ELSE 'hrm_benefit_payroll_inputs' END
    AND p.column_name=column_row.attname AND p.is_active AND p.transform='null_out') THEN
   removed:=CASE WHEN column_row.attname='override_reason' AND original->column_row.attname<>'null'::jsonb THEN to_jsonb('REDACTED'::text)
    WHEN column_row.attnotnull AND column_row.atttypid='jsonb'::regtype THEN '{}'::jsonb ELSE 'null'::jsonb END;
   expected:=jsonb_set(expected,ARRAY[column_row.attname],removed);
  END IF;
 END LOOP;
 RETURN candidate=expected;
END $_$;


--
-- Name: benefit_hours_coverage_election_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.benefit_hours_coverage_election_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF NEW.hours_coverage IS DISTINCT FROM OLD.hours_coverage AND EXISTS (
  SELECT 1 FROM public.hrm_benefit_enrollment_terms t
  JOIN public.hrm_benefit_enrollments e ON e.org_id=t.org_id AND e.id=t.enrollment_id
  WHERE t.org_id=OLD.org_id AND t.rule_id=OLD.id AND e.submission_snapshot IS NOT NULL
 ) THEN
  RAISE EXCEPTION 'Hour eligibility has submitted election evidence; preserve the rule and create an effective-dated replacement with new election terms.';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: benefit_legacy_pricing_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.benefit_legacy_pricing_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF ROW(NEW.employee_cost_basis,NEW.employee_cost,NEW.employer_cost_basis,NEW.employer_cost,NEW.employee_pay_component_id,NEW.employer_pay_component_id,NEW.proration_basis,NEW.requires_approval)
 IS DISTINCT FROM ROW(OLD.employee_cost_basis,OLD.employee_cost,OLD.employer_cost_basis,OLD.employer_cost,OLD.employee_pay_component_id,OLD.employer_pay_component_id,OLD.proration_basis,OLD.requires_approval) THEN
  RAISE EXCEPTION 'Two-side benefit pricing is retained as historical evidence; configure native contribution rules for future elections.';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: benefit_monthly_queue_retired(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.benefit_monthly_queue_retired() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF public.benefit_historical_clone_matches(TG_RELID,to_jsonb(NEW)) THEN RETURN NEW; END IF;
 RAISE EXCEPTION 'Monthly benefit input generation has been replaced by native pay-run calculation; record enrollment contribution terms and calculate the pay run.';
END $$;


--
-- Name: benefit_recovery_rule_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.benefit_recovery_rule_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM public.hrm_benefit_recovery_sources s WHERE s.org_id=NEW.org_id AND s.rule_id=NEW.id)
  AND (NEW.kind<>'employee_deduction' OR NEW.unpaid_period_treatment<>'carry' OR NEW.arrears_plan_id IS NULL) THEN
  RAISE EXCEPTION 'This rule owns insured premium recovery; preserve its native carry deduction or replace the effective-dated rule.';
 END IF;
 IF EXISTS(SELECT 1 FROM public.hrm_benefit_recovery_sources s WHERE s.org_id=NEW.org_id AND s.premium_rule_id=NEW.id)
  AND (NEW.kind NOT IN ('employer_contribution','taxable_non_cash') OR NEW.basis NOT IN ('per_period','per_month','per_year')) THEN
  RAISE EXCEPTION 'This insured premium is linked to recovery; preserve its flat employer premium treatment or replace the effective-dated rule.';
 END IF;
 IF EXISTS(SELECT 1 FROM public.hrm_benefit_recovery_sources a JOIN public.hrm_benefit_recovery_sources b
  ON b.org_id=a.org_id AND b.premium_rule_id=a.premium_rule_id AND b.rule_id<>a.rule_id
  JOIN public.hrm_benefit_contribution_rules prior_rule ON prior_rule.org_id=b.org_id AND prior_rule.id=b.rule_id
  WHERE a.org_id=NEW.org_id AND a.rule_id=NEW.id AND
   daterange(prior_rule.effective_from,COALESCE(prior_rule.effective_to,DATE '9999-12-31'),'[]') && daterange(NEW.effective_from,COALESCE(NEW.effective_to,DATE '9999-12-31'),'[]')) THEN
  RAISE EXCEPTION 'Insured premium recovery ownership dates overlap; close the prior rule before the successor begins.';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: benefit_recovery_source_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.benefit_recovery_source_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 IF TG_OP IN ('UPDATE','DELETE') AND EXISTS(SELECT 1 FROM public.pay_run_benefit_allocations a WHERE a.org_id=OLD.org_id AND a.rule_id=OLD.rule_id AND a.status IN ('committed','voided')) THEN RAISE EXCEPTION 'Recovery source configuration has committed payroll evidence; add an effective-dated replacement recovery rule.'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 IF EXISTS(SELECT 1 FROM public.pay_run_benefit_allocations a WHERE a.org_id=NEW.org_id AND a.rule_id=NEW.rule_id AND a.status IN ('committed','voided')) THEN RAISE EXCEPTION 'Recovery source configuration has committed payroll evidence; add an effective-dated replacement recovery rule.'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.hrm_benefit_contribution_rules r WHERE r.org_id=NEW.org_id AND r.plan_id=NEW.plan_id AND r.id=NEW.rule_id AND r.kind='employee_deduction' AND r.unpaid_period_treatment='carry' AND r.arrears_plan_id IS NOT NULL)
  OR NOT EXISTS(SELECT 1 FROM public.hrm_benefit_contribution_rules r WHERE r.org_id=NEW.org_id AND r.plan_id=NEW.plan_id AND r.id=NEW.premium_rule_id AND r.kind IN ('employer_contribution','taxable_non_cash') AND r.basis IN ('per_period','per_month','per_year')) THEN
  RAISE EXCEPTION 'Link a native employee recovery deduction to flat-period employer premium rules on the same plan.';
 END IF;
 IF EXISTS(SELECT 1 FROM public.hrm_benefit_recovery_sources s
  JOIN public.hrm_benefit_contribution_rules prior_rule ON prior_rule.org_id=s.org_id AND prior_rule.id=s.rule_id
  JOIN public.hrm_benefit_contribution_rules new_rule ON new_rule.org_id=NEW.org_id AND new_rule.id=NEW.rule_id
  WHERE s.org_id=NEW.org_id AND s.premium_rule_id=NEW.premium_rule_id AND s.id<>NEW.id AND
   daterange(prior_rule.effective_from,COALESCE(prior_rule.effective_to,DATE '9999-12-31'),'[]') && daterange(new_rule.effective_from,COALESCE(new_rule.effective_to,DATE '9999-12-31'),'[]')) THEN
  RAISE EXCEPTION 'An insured premium already has a recovery owner during these dates; close the prior recovery rule before linking its successor.';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: benefit_recurring_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.benefit_recurring_audit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE row_value jsonb;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 IF TG_OP = 'DELETE' THEN row_value := to_jsonb(OLD); ELSE row_value := to_jsonb(NEW); END IF;
 INSERT INTO public.audit_log(org_id,table_name,row_id,action,changes,actor_id)
 VALUES ((row_value->>'org_id')::uuid,TG_TABLE_NAME,(row_value->>'id')::uuid,lower(TG_OP),
 jsonb_build_object('before',CASE WHEN TG_OP <> 'INSERT' THEN to_jsonb(OLD) END,'after',CASE WHEN TG_OP <> 'DELETE' THEN to_jsonb(NEW) END),
 coalesce((row_value->>'updated_by')::uuid,(row_value->>'created_by')::uuid));
 IF TG_OP = 'DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $$;


--
-- Name: benefit_recurring_configuration_lock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.benefit_recurring_configuration_lock() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE tenant uuid;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP = 'DELETE' THEN tenant := OLD.org_id; ELSE tenant := NEW.org_id; END IF;
 IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(tenant) THEN RETURN OLD; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('openbooks:benefit-recurring:' || tenant::text,0));
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $$;


--
-- Name: benefit_recurring_history_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.benefit_recurring_history_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE run_status text; historical_through date;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 IF TG_TABLE_NAME='hrm_benefit_enrollment_terms' THEN
  IF EXISTS (SELECT 1 FROM public.hrm_benefit_enrollments e
  WHERE e.org_id=OLD.org_id AND e.id=OLD.enrollment_id AND (e.status<>'elected' OR e.submission_snapshot IS NOT NULL)) THEN
   RAISE EXCEPTION 'Submitted contribution elections are immutable; change the enrollment through its record action.' USING ERRCODE='23514';
  END IF;
 END IF;
 IF TG_TABLE_NAME <> 'pay_run_benefit_allocations' AND TG_OP = 'UPDATE' THEN
  SELECT max(a.period_to) INTO historical_through FROM public.pay_run_benefit_allocations a
  WHERE a.org_id=OLD.org_id AND a.status IN ('committed','voided') AND
   CASE TG_TABLE_NAME WHEN 'hrm_benefit_enrollment_terms' THEN a.term_id=OLD.id
    WHEN 'hrm_benefit_contribution_tiers' THEN a.source_snapshot #>> '{basis,tier,id}'=OLD.id::text
    ELSE a.rule_id=OLD.id END;
  IF NEW.effective_to IS NOT NULL AND (OLD.effective_to IS NULL OR NEW.effective_to<=OLD.effective_to)
   AND (historical_through IS NULL OR NEW.effective_to>=historical_through)
   AND (to_jsonb(NEW)-'effective_to'-'updated_at'-'updated_by')=(to_jsonb(OLD)-'effective_to'-'updated_at'-'updated_by') THEN RETURN NEW; END IF;
 END IF;
 IF TG_TABLE_NAME = 'pay_run_benefit_allocations' THEN
  SELECT r.run_status INTO run_status FROM public.pay_runs r WHERE r.org_id = OLD.org_id AND r.document_id = OLD.pay_run_document_id;
  IF OLD.status IN ('committed','voided') OR run_status IN ('committed','voided') THEN
   IF TG_OP = 'UPDATE' AND NEW.status = 'voided' AND OLD.status = 'committed' AND
      (to_jsonb(NEW) - 'status' - 'updated_at' - 'updated_by') = (to_jsonb(OLD) - 'status' - 'updated_at' - 'updated_by') THEN RETURN NEW; END IF;
   RAISE EXCEPTION 'Committed benefit allocations are immutable; use a reversing or correcting payroll run.' USING ERRCODE='23514';
  END IF;
 ELSIF TG_TABLE_NAME = 'hrm_benefit_contribution_tiers' THEN
  IF EXISTS (SELECT 1 FROM public.pay_run_benefit_allocations a WHERE a.org_id=OLD.org_id AND a.status IN ('committed','voided')
   AND a.source_snapshot #>> '{basis,tier,id}' = OLD.id::text) THEN
   RAISE EXCEPTION 'This contribution tier has committed payroll evidence; add an effective-dated replacement tier for future coverage.' USING ERRCODE='23514';
  END IF;
 ELSE
  IF EXISTS (SELECT 1 FROM public.pay_run_benefit_allocations a WHERE a.org_id = OLD.org_id AND a.status IN ('committed','voided')
    AND CASE TG_TABLE_NAME WHEN 'hrm_benefit_enrollment_terms' THEN a.term_id = OLD.id ELSE a.rule_id = OLD.id END) THEN
   RAISE EXCEPTION 'This contribution configuration has committed payroll evidence; preserve it and add effective-dated replacement terms or a new rule.' USING ERRCODE='23514';
  END IF;
 END IF;
 IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $$;


--
-- Name: benefit_recurring_run_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.benefit_recurring_run_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF OLD.run_status IN ('committed','voided') AND NEW.benefit_source_snapshot IS DISTINCT FROM OLD.benefit_source_snapshot THEN
  RAISE EXCEPTION 'Committed recurring benefit source evidence is immutable; use a correcting payroll run.';
 END IF;
 IF NEW.run_status = 'committed' AND OLD.run_status <> 'committed' THEN
  IF NEW.benefit_source_snapshot IS NULL THEN RAISE EXCEPTION 'Recurring benefit source evidence is missing; recalculate the pay run before committing.'; END IF;
  IF EXISTS (SELECT 1 FROM public.pay_run_benefit_allocations a LEFT JOIN public.pay_stub_lines l ON l.org_id=a.org_id AND l.id=a.pay_stub_line_id
    LEFT JOIN public.pay_stubs s ON s.org_id=l.org_id AND s.id=l.stub_id
    WHERE a.org_id=NEW.org_id AND a.pay_run_document_id=NEW.document_id AND a.amount>0
    AND (l.id IS NULL OR l.amount IS DISTINCT FROM a.amount OR s.pay_run_document_id IS DISTINCT FROM a.pay_run_document_id
    OR s.employment_id IS DISTINCT FROM a.employment_id OR l.component_id::text IS DISTINCT FROM (a.source_snapshot #>> '{rule,payComponentId}'))) THEN
   RAISE EXCEPTION 'A benefit allocation is missing its exact native payroll line; recalculate the pay run before committing.';
  END IF;
  UPDATE public.pay_run_benefit_allocations SET status = 'committed',updated_at = now(),updated_by = NEW.updated_by
   WHERE org_id = NEW.org_id AND pay_run_document_id = NEW.document_id AND status = 'calculated';
 ELSIF NEW.run_status = 'voided' AND OLD.run_status = 'committed' THEN
  UPDATE public.pay_run_benefit_allocations SET status = 'voided',updated_at = now(),updated_by = NEW.updated_by
   WHERE org_id = NEW.org_id AND pay_run_document_id = NEW.document_id AND status = 'committed';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: benefit_recurring_subject_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.benefit_recurring_subject_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE e record; r record;
BEGIN
 IF TG_OP='INSERT' AND public.benefit_historical_clone_matches(TG_RELID,to_jsonb(NEW)) THEN RETURN NEW; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('openbooks:benefit-recurring:' || NEW.org_id::text,0));
 SELECT * INTO e FROM public.hrm_benefit_enrollments WHERE org_id = NEW.org_id AND id = NEW.enrollment_id;
 SELECT * INTO r FROM public.hrm_benefit_contribution_rules WHERE org_id = NEW.org_id AND id = NEW.rule_id;
 IF e.status <> 'elected' OR e.submission_snapshot IS NOT NULL THEN RAISE EXCEPTION 'Submitted contribution elections are immutable; change the enrollment through its record action.'; END IF;
 IF e.plan_id IS DISTINCT FROM r.plan_id THEN
  RAISE EXCEPTION 'Contribution terms must belong to a rule on the enrollment plan; select a rule from that plan.';
 END IF;
 IF NEW.effective_from < e.effective_from OR (e.effective_to IS NOT NULL AND (NEW.effective_to IS NULL OR NEW.effective_to > e.effective_to)) THEN
  RAISE EXCEPTION 'Contribution terms must fit inside enrollment coverage; choose dates within that enrollment.';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: benefit_transaction_rule_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.benefit_transaction_rule_audit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE row_data jsonb; owner_org uuid; owner_program uuid;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 row_data:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
 owner_org:=(row_data->>'org_id')::uuid; owner_program:=(row_data->>'program_id')::uuid;
 IF public.openbooks_clone_authority() OR public.openbooks_sandbox_wipe_allowed(owner_org) THEN
  RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
 END IF;
 INSERT INTO public.audit_log(org_id,table_name,row_id,action,actor_id,changes)
 VALUES(owner_org,TG_TABLE_NAME,(row_data->>'id')::uuid,lower(TG_OP),(row_data->>'updated_by')::uuid,
  jsonb_build_object('before',CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(OLD) END,
   'after',CASE WHEN TG_OP='DELETE' THEN NULL ELSE to_jsonb(NEW) END,'reason',row_data->>'reason'));
 UPDATE public.hrm_benefit_programs SET revision=revision+1,updated_at=clock_timestamp(),updated_by=(row_data->>'updated_by')::uuid
  WHERE org_id=owner_org AND id=owner_program;
 IF NOT FOUND THEN RAISE EXCEPTION 'The program revision was not saved; reload its rules before continuing.'; END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$;


--
-- Name: benefit_transaction_rule_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.benefit_transaction_rule_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE owner_org uuid; owner_program uuid; program_status text; employer uuid; segment record; group_table text; valid_group boolean; group_subsidiary uuid; include_children boolean;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 owner_org:=CASE WHEN TG_OP='DELETE' THEN OLD.org_id ELSE NEW.org_id END;
 owner_program:=CASE WHEN TG_OP='DELETE' THEN OLD.program_id ELSE NEW.program_id END;
 SELECT status,legal_entity_id INTO program_status,employer FROM public.hrm_benefit_programs
  WHERE org_id=owner_org AND id=owner_program FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Choose a benefit program in this organization before configuring its transaction rules.'; END IF;
 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(owner_org) THEN RETURN OLD; END IF;
 IF TG_OP='INSERT' AND public.openbooks_clone_authority()
  AND EXISTS(SELECT 1 FROM public.orgs WHERE id=owner_org AND env_kind='sandbox' AND sandbox_of IS NOT NULL) THEN RETURN NEW; END IF;
 IF program_status<>'draft' AND NOT (program_status='active' AND public.hrm_benefit_program_revision_open(owner_org,owner_program)) THEN
  RAISE EXCEPTION 'Active benefit transaction rules change through a dated program revision; save them with a change date.';
 END IF;
 IF TG_OP<>'DELETE' AND TG_TABLE_NAME IN ('hrm_benefit_transaction_responsibilities','hrm_benefit_transaction_limits') THEN
  SELECT s.id,s.source_kind,s.storage_column INTO segment FROM public.hrm_benefit_transaction_policies p
   LEFT JOIN public.segment_definitions s ON s.org_id=p.org_id AND s.id=p.grouping_segment_id
   WHERE p.org_id=owner_org AND p.program_id=owner_program FOR SHARE OF p;
  IF NOT FOUND THEN RAISE EXCEPTION 'Configure the program transaction source and grouping dimension before recording responsibilities or ceilings.'; END IF;
  IF segment.id IS NULL THEN
   valid_group:=NEW.group_id=employer;
  ELSIF segment.source_kind='custom' AND segment.storage_column IS NULL THEN
   SELECT EXISTS(SELECT 1 FROM public.segment_values WHERE org_id=owner_org AND segment_id=segment.id AND id=NEW.group_id) INTO valid_group;
  ELSE
   group_table:=CASE segment.storage_column WHEN 'subsidiary_id' THEN 'subsidiaries' WHEN 'department_id' THEN 'departments'
    WHEN 'project_id' THEN 'projects' WHEN 'location_id' THEN 'locations' WHEN 'class_id' THEN 'classes' END;
   IF group_table IS NULL THEN RAISE EXCEPTION 'Select a grouping dimension with a supported native storage mapping.'; END IF;
   EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE org_id=$1 AND id=$2)',group_table) INTO valid_group USING owner_org,NEW.group_id;
   IF group_table='subsidiaries' THEN valid_group:=valid_group AND NEW.group_id=employer; END IF;
  END IF;
  IF valid_group IS DISTINCT FROM true THEN RAISE EXCEPTION 'The assigned group belongs to another organization or dimension; select a native group from the configured dimension.'; END IF;
  IF segment.id IS NOT NULL AND group_table IS DISTINCT FROM 'subsidiaries' THEN
   IF segment.source_kind='custom' THEN group_table:='segment_values'; END IF;
   EXECUTE format('SELECT subsidiary_id,subsidiary_include_children FROM public.%I WHERE org_id=$1 AND id=$2',group_table)
    INTO group_subsidiary,include_children USING owner_org,NEW.group_id;
   IF group_subsidiary IS NOT NULL AND group_subsidiary<>employer AND NOT (
    include_children AND EXISTS(WITH RECURSIVE descendants AS (
     SELECT id FROM public.subsidiaries WHERE org_id=owner_org AND id=group_subsidiary
     UNION ALL SELECT s.id FROM public.subsidiaries s JOIN descendants d ON s.parent_id=d.id WHERE s.org_id=owner_org
    ) SELECT 1 FROM descendants WHERE id=employer)) THEN
    RAISE EXCEPTION 'The assigned group is restricted to another legal employer; choose a group available to the program employer.';
   END IF;
  END IF;
  IF TG_TABLE_NAME='hrm_benefit_transaction_responsibilities' THEN
   IF NOT EXISTS(SELECT 1 FROM public.worker_employments WHERE org_id=owner_org AND id=NEW.employment_id AND employer_subsidiary_id=employer) THEN
    RAISE EXCEPTION 'Choose a recipient employment belonging to the program legal employer.';
   END IF;
  END IF;
 END IF;
 IF TG_OP='UPDATE' AND ROW(NEW.id,NEW.org_id,NEW.program_id,NEW.created_at,NEW.created_by)
  IS DISTINCT FROM ROW(OLD.id,OLD.org_id,OLD.program_id,OLD.created_at,OLD.created_by) THEN
  RAISE EXCEPTION 'Transaction rule ownership and creation evidence are immutable.';
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $_$;


--
-- Name: billing_request_field_ticket_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.billing_request_field_ticket_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ DECLARE request_project_id uuid; request_basis text; request_status text; BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;
 IF tg_op = 'DELETE' AND openbooks_sandbox_wipe_allowed(old.org_id) THEN RETURN old; END IF; IF tg_op IN ('UPDATE', 'DELETE') THEN RAISE EXCEPTION 'billing request Field Ticket selections are immutable; cancel the request and create a new one'; END IF; SELECT br.project_id, br.basis, br.status INTO request_project_id, request_basis, request_status FROM billing_requests br WHERE br.id = new.billing_request_id AND br.org_id = new.org_id; IF request_project_id IS NULL OR request_basis <> 'field_ticket' OR request_status <> 'open' THEN RAISE EXCEPTION 'Field Ticket selections require an open field-ticket billing request in the same organization'; END IF; IF NOT EXISTS (SELECT 1 FROM documents ticket WHERE ticket.id = new.field_ticket_id AND ticket.org_id = new.org_id AND ticket.project_id = request_project_id AND ticket.kind = 'field_ticket' AND ticket.status = 'approved') THEN RAISE EXCEPTION 'selected Field Ticket must be approved and belong to the billing request project'; END IF; IF new.selected_by IS NOT NULL AND NOT EXISTS (SELECT 1 FROM users actor WHERE actor.id = new.selected_by AND actor.org_id = new.org_id) THEN RAISE EXCEPTION 'Field Ticket selection actor must belong to the same organization'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('billing-field-ticket:' || new.org_id::text || ':' || new.field_ticket_id::text, 0)); IF EXISTS (SELECT 1 FROM billing_request_field_tickets existing JOIN billing_requests existing_request ON existing_request.id = existing.billing_request_id AND existing_request.org_id = existing.org_id WHERE existing.org_id = new.org_id AND existing.field_ticket_id = new.field_ticket_id AND existing_request.status <> 'cancelled') THEN RAISE EXCEPTION 'Field Ticket is already selected by another active or completed billing request'; END IF; RETURN new; END; $$;


--
-- Name: billing_request_field_ticket_request_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.billing_request_field_ticket_request_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  selection_count bigint;
BEGIN
  SELECT count(*)
    INTO selection_count
    FROM billing_request_field_tickets selected
   WHERE selected.org_id = new.org_id
     AND selected.billing_request_id = new.id;

  IF new.basis = 'field_ticket' AND selection_count = 0 THEN
    RAISE EXCEPTION
      'a Field Ticket billing request requires at least one relational ticket selection';
  END IF;

  IF new.basis <> 'field_ticket' AND selection_count <> 0 THEN
    RAISE EXCEPTION
      'Field Ticket selections may only belong to a field-ticket billing request';
  END IF;

  IF EXISTS (
    SELECT 1
      FROM billing_request_field_tickets selected
      JOIN documents ticket
        ON ticket.id = selected.field_ticket_id
       AND ticket.org_id = selected.org_id
     WHERE selected.org_id = new.org_id
       AND selected.billing_request_id = new.id
       AND (
         ticket.kind <> 'field_ticket'
         OR ticket.project_id IS DISTINCT FROM new.project_id
       )
  ) THEN
    RAISE EXCEPTION
      'Field Ticket billing selections must remain in the request organization and project';
  END IF;

  RETURN new;
END;
$$;


--
-- Name: budget_flow_admission_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.budget_flow_admission_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status NOT IN('draft','archived') OR NEW.submission_policy IS NOT NULL THEN
   RAISE EXCEPTION 'Create a draft budget before submitting it through Flows.';
  END IF;
  RETURN NEW;
 END IF;
 IF OLD.status='draft' AND NEW.status='pending_approval' THEN
  IF NEW.submitted_by IS NULL OR NOT public.flow_submission_policy_valid(NEW.org_id,'budget_scenario',NEW.id,NEW.submitted_by,NEW.submission_policy)
   OR NOT EXISTS(SELECT 1 FROM public.flow_submissions s WHERE s.org_id=NEW.org_id AND s.subject_kind='budget_scenario'
    AND s.subject_id=NEW.id AND s.actor_id=NEW.submitted_by AND s.policy=NEW.submission_policy
    AND s.context @> jsonb_build_object('revision',OLD.revision)
    AND NOT EXISTS(SELECT 1 FROM public.flow_submissions newer WHERE newer.org_id=s.org_id AND newer.subject_kind=s.subject_kind
      AND newer.subject_id=s.subject_id AND (newer.created_at,newer.id)>(s.created_at,s.id))) THEN
   RAISE EXCEPTION 'Submit the current budget revision through native Flow routing.';
  END IF;
 ELSIF OLD.status='pending_approval' AND NEW.status='draft' THEN
  IF NEW.submission_policy IS NOT NULL OR EXISTS(SELECT 1 FROM public.flow_gates g WHERE g.org_id=NEW.org_id
    AND g.subject_kind='budget_scenario' AND g.subject_id=NEW.id AND g.status IN('pending','escalated')) THEN
   RAISE EXCEPTION 'Reject through the Flow gate or withdraw the submitted budget before editing it.';
  END IF;
 ELSIF NEW.submission_policy IS DISTINCT FROM OLD.submission_policy THEN
  RAISE EXCEPTION 'Budget submission routing is immutable until the budget returns to draft.';
 END IF;
 IF NEW.status='approved' AND OLD.status<>'approved' THEN
  IF OLD.status<>'pending_approval' OR NEW.submission_policy IS NULL THEN
   RAISE EXCEPTION 'Submit the budget through Flows before release.';
  END IF;
  IF NEW.submission_policy->>'kind'='ungated' THEN
   IF NEW.approved_by IS DISTINCT FROM NEW.submitted_by
    OR NOT public.flow_ungated_submission_authorized(NEW.org_id,'budget_scenario',NEW.id,NEW.submitted_by,
      jsonb_build_object('revision',OLD.revision-1)) THEN
    RAISE EXCEPTION 'An ungated budget requires its current submission receipt.';
   END IF;
  ELSIF NOT EXISTS(SELECT 1 FROM public.flow_submissions s WHERE s.org_id=NEW.org_id
    AND s.subject_kind='budget_scenario' AND s.subject_id=NEW.id AND s.policy=NEW.submission_policy
    AND public.flow_submission_approved(s.org_id,s.subject_kind,s.subject_id,s.id))
    OR NOT EXISTS(SELECT 1 FROM public.flow_gates g JOIN public.flow_runs r ON r.org_id=g.org_id AND r.id=g.run_id
    WHERE g.org_id=NEW.org_id AND g.subject_kind='budget_scenario' AND g.subject_id=NEW.id
      AND NEW.submission_policy->'runIds' ? r.id::text AND g.status='approved' AND g.decided_by=NEW.approved_by
      AND r.context->'submissionPolicy'->>'flowId'=r.flow_id::text
      AND (NEW.approved_by IS DISTINCT FROM NEW.submitted_by OR EXISTS(
        SELECT 1 FROM jsonb_array_elements(r.context->'submissionPolicy'->'graph'->'nodes') node
         WHERE node->>'id'=g.node_id AND node->'data'->>'kind'='gate'
          AND node->'data'->'gate'->'preventSelfApproval'='false'::jsonb)))
    OR EXISTS(SELECT 1 FROM public.flow_gates g WHERE g.org_id=NEW.org_id AND g.subject_kind='budget_scenario'
      AND g.subject_id=NEW.id AND g.status IN('pending','escalated')) THEN
   RAISE EXCEPTION 'Complete every configured budget approval gate before release.';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: business_calendar_weekend_valid(smallint[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_calendar_weekend_valid(days smallint[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT days IS NOT NULL
     AND (cardinality(days) = 0 OR array_ndims(days) = 1)
     AND cardinality(days) < 7
     AND NOT EXISTS (
       SELECT 1 FROM unnest(days) AS day
        WHERE day IS NULL OR day < 1 OR day > 7
     )
     AND (SELECT count(*) FROM unnest(days) AS day)
       = (SELECT count(DISTINCT day) FROM unnest(days) AS day);
$$;


--
-- Name: calibrated_review_flow_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calibrated_review_flow_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF NEW.status='calibrated' AND OLD.status<>'calibrated' AND NOT EXISTS(
   SELECT 1 FROM public.hrm_calibration_entries e JOIN public.hrm_calibration_sessions s ON s.org_id=e.org_id AND s.id=e.session_id
   WHERE e.org_id=NEW.org_id AND e.review_id=NEW.id AND s.status='closed' AND s.updated_by=NEW.updated_by
    AND e.calibrated_rating=NEW.calibrated_rating AND NEW.calibration_reason IS NOT DISTINCT FROM coalesce(e.justification,'decided in calibration')) THEN
  RAISE EXCEPTION 'Publish calibrated ratings through their session and its tenant Flow policy.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: calibration_entry_published_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calibration_entry_published_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE candidate jsonb;
BEGIN
 IF TG_OP='DELETE' THEN
  IF tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD))
    OR public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 END IF;
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 FOR candidate IN SELECT value FROM jsonb_array_elements(jsonb_build_array(
   CASE WHEN TG_OP<>'INSERT' THEN to_jsonb(OLD) ELSE NULL END,CASE WHEN TG_OP<>'DELETE' THEN to_jsonb(NEW) ELSE NULL END)) WHERE value<>'null'::jsonb LOOP
  IF EXISTS(SELECT 1 FROM public.hrm_calibration_sessions s WHERE s.org_id=(candidate->>'org_id')::uuid
     AND s.id=(candidate->>'session_id')::uuid AND s.status='closed') THEN
   RAISE EXCEPTION 'Published calibration entries are immutable; create a new session for revised ratings.' USING ERRCODE='23514';
  END IF;
 END LOOP;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $$;


--
-- Name: calibration_session_approval_dependencies(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calibration_session_approval_dependencies(organization uuid, subject uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('cycle',to_jsonb(c),'entries',coalesce((SELECT jsonb_agg(jsonb_build_object('entry',to_jsonb(e),'review',to_jsonb(r),
   'employment',jsonb_build_object('id',w.id,'employer',w.employer_subsidiary_id)) ORDER BY e.id)
  FROM public.hrm_calibration_entries e JOIN public.hrm_reviews r ON r.org_id=e.org_id AND r.id=e.review_id
  JOIN public.worker_employments w ON w.org_id=r.org_id AND w.id=r.employment_id
  WHERE e.org_id=s.org_id AND e.session_id=s.id),'[]'::jsonb))
 FROM public.hrm_calibration_sessions s JOIN public.hrm_review_cycles c ON c.org_id=s.org_id AND c.id=s.cycle_id
 WHERE s.org_id=organization AND s.id=subject
$$;


--
-- Name: calibration_session_approval_entities(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calibration_session_approval_entities(organization uuid, subject uuid) RETURNS text[]
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
 SELECT array(SELECT DISTINCT entity FROM (
  SELECT c.applies_to->>'employer_subsidiary_id' as entity FROM public.hrm_calibration_sessions s
   JOIN public.hrm_review_cycles c ON c.org_id=s.org_id AND c.id=s.cycle_id WHERE s.org_id=organization AND s.id=subject
  UNION ALL SELECT w.employer_subsidiary_id::text FROM public.hrm_calibration_entries e
   JOIN public.hrm_reviews r ON r.org_id=e.org_id AND r.id=e.review_id
   JOIN public.worker_employments w ON w.org_id=r.org_id AND w.id=r.employment_id WHERE e.org_id=organization AND e.session_id=subject
 ) owners WHERE entity IS NOT NULL ORDER BY entity)
$$;


--
-- Name: calibration_session_flow_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calibration_session_flow_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='INSERT' THEN
  IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
  IF NEW.status<>'draft' THEN RAISE EXCEPTION 'Create a draft calibration session before opening and publishing it.' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 IF OLD.status='closed' AND (to_jsonb(NEW)-ARRAY['updated_at','updated_by']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['updated_at','updated_by']) THEN
  RAISE EXCEPTION 'Published calibration evidence is immutable; create a new session for revised ratings.' USING ERRCODE='23514';
 END IF;
 IF NEW.status='closed' AND OLD.status<>'closed' AND (OLD.status<>'open' OR NEW.closed_at IS NULL
   OR NOT public.flow_command_authorized(NEW.org_id,'hrm_calibration_session',NEW.id,NEW.updated_by,
     public.flow_command_record_fingerprint(to_jsonb(OLD),public.calibration_session_approval_dependencies(OLD.org_id,OLD.id)),
     jsonb_build_object('action','close'))) THEN
  RAISE EXCEPTION 'Submit the current calibration session and complete every configured Flow gate before publishing ratings.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: cam_pool_source_account_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cam_pool_source_account_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_conflict public.cam_pools%ROWTYPE;
BEGIN
  -- Retiring a pool always succeeds and releases its sources for reuse.
  IF new.status = 'cancelled' THEN
    RETURN new;
  END IF;

  -- Serialize this property's pool lifecycle BEFORE reading, so mutually
  -- uncommitted writers cannot each pass the overlap check: under READ
  -- COMMITTED every statement takes its snapshot after acquiring the lock,
  -- and the second writer therefore sees the first writer's row.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('cam-pool:' || new.org_id::text || ':' || new.property_id::text, 0)
  );

  SELECT other.*
    INTO v_conflict
    FROM public.cam_pools other
   WHERE other.org_id = new.org_id
     AND other.property_id = new.property_id
     AND (TG_OP = 'INSERT' OR other.id <> new.id)
     AND other.status <> 'cancelled'
     AND other.period_starts_on <= new.period_ends_on
     AND other.period_ends_on >= new.period_starts_on
     AND EXISTS (
       SELECT 1
         FROM jsonb_array_elements_text(new.expense_account_ids) wanted(account)
        WHERE lower(account) IN (
          SELECT lower(shared) FROM jsonb_array_elements_text(other.expense_account_ids) shared
        )
     )
   ORDER BY other.created_at, other.id
   LIMIT 1;

  IF FOUND THEN
    RAISE EXCEPTION
      'CAM pools cannot overlap periods while sharing any expense account: pool "%" (% to %) already bills these sources for this property over an overlapping window',
      v_conflict.name, v_conflict.period_starts_on::text, v_conflict.period_ends_on::text;
  END IF;

  RETURN new;
END $$;


--
-- Name: FUNCTION cam_pool_source_account_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cam_pool_source_account_guard() IS 'openbooks:cam_pool_source_account_guard:v1 - at most one non-cancelled CAM pool per property may bill a given expense account across an overlapping window; a per-(org,property) transaction advisory fence serializes racing create/update writers so neither can claim shared sources twice';


--
-- Name: change_order_target_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.change_order_target_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.target_sov_line_id is not null and not exists (
    select 1
      from sov_lines sl
     where sl.id = new.target_sov_line_id
       and sl.org_id = new.org_id
       and sl.project_id = new.project_id
  ) then
    raise exception 'change-order target must belong to the same organization and project';
  end if;
  return new;
end $$;


--
-- Name: change_set_items_lifecycle_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.change_set_items_lifecycle_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  parent_id uuid := COALESCE(NEW.change_set_id, OLD.change_set_id);
  parent_org uuid;
  parent_status text;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  SELECT org_id, status
    INTO parent_org, parent_status
    FROM public.change_sets
   WHERE id = parent_id
   FOR UPDATE;
  -- ON DELETE CASCADE removes child rows as part of deleting their parent;
  -- allow that internal delete while rejecting orphaned standalone writes.
  IF parent_status IS NULL AND TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  IF parent_status IS NULL THEN
    RAISE EXCEPTION 'change set % does not exist', parent_id;
  END IF;
  IF parent_status <> 'draft' THEN
    RAISE EXCEPTION 'change set items are immutable after review (status=%)', parent_status;
  END IF;
  IF TG_OP <> 'DELETE' AND NEW.org_id <> parent_org THEN
    RAISE EXCEPTION 'change set item organization must match its change set';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END
$$;


--
-- Name: checklist_flow_admission_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checklist_flow_admission_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF NEW.approval_status='approved' AND OLD.approval_status<>'approved' THEN
  IF NEW.flow_run_id IS NULL THEN
   IF NOT public.flow_ungated_submission_authorized(NEW.org_id,'hrm_process_step',NEW.id,NEW.submitted_by,
     jsonb_build_object('submittedAt',NEW.submitted_at::text)) THEN
    RAISE EXCEPTION 'Checklist release requires its native ungated submission receipt.';
   END IF;
  ELSIF NOT EXISTS(SELECT 1 FROM flow_gates WHERE org_id=NEW.org_id AND subject_kind='hrm_process_step'
    AND subject_id=NEW.id AND status='approved' AND decided_by=NEW.updated_by AND decided_at IS NOT NULL)
   OR EXISTS(SELECT 1 FROM flow_gates WHERE org_id=NEW.org_id AND subject_kind='hrm_process_step'
    AND subject_id=NEW.id AND status IN('pending','escalated')) THEN
   RAISE EXCEPTION 'Complete the checklist Flow gates before releasing its evidence.';
  END IF;
 END IF;
 IF NEW.status='done' AND OLD.status<>'done' AND NEW.approval_status<>'approved' THEN
  RAISE EXCEPTION 'Submit the checklist evidence through its native Flows before completion.';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: close_append_only_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_append_only_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  if tg_op = 'DELETE' and openbooks_sandbox_wipe_allowed(old.org_id) then
    return old;
  end if;
  raise exception '% is append-only', tg_table_name;
end $$;


--
-- Name: close_run_approval_fingerprint(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_run_approval_fingerprint(organization uuid, subject uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
 SELECT encode(sha256(convert_to(jsonb_build_object('id',r.id,'orgId',r.org_id,'periodId',r.period_id,
   'bookId',r.book_id,'blueprintId',r.blueprint_id,'scope',r.scope,'startedBy',r.started_by,'ledger',r.data_fingerprint,
   'tasks',coalesce((SELECT jsonb_agg(jsonb_build_object('task',to_jsonb(t)-ARRAY['updated_at','updated_by'],
      'evidence',coalesce((SELECT jsonb_agg(to_jsonb(e) ORDER BY e.id) FROM public.close_task_evidence e
        WHERE e.org_id=t.org_id AND e.task_id=t.id),'[]'::jsonb)) ORDER BY t.id)
     FROM public.close_run_tasks t WHERE t.org_id=r.org_id AND t.run_id=r.id
       AND t.completion_mode='manual' AND t.task_type<>'approval'),'[]'::jsonb))::text,'UTF8')),'hex')
 FROM public.close_runs r WHERE r.org_id=organization AND r.id=subject AND r.data_fingerprint IS NOT NULL
$$;


--
-- Name: close_run_flow_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_run_flow_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='INSERT' THEN
  IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
  IF NEW.status IN('approved','closed','published') THEN
   RAISE EXCEPTION 'Create the close run and submit its current evidence through Flows before release.' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
 END IF;
 IF NEW.status='approved' AND OLD.status IS DISTINCT FROM NEW.status THEN
  IF OLD.status<>'review' OR NEW.approved_by IS NULL OR NEW.approved_at IS NULL
    OR NEW.approved_by IS DISTINCT FROM NEW.updated_by
    OR NOT public.flow_subject_decision_authorized(NEW.org_id,'close_run',NEW.id,NEW.approved_by,
      public.close_run_approval_fingerprint(OLD.org_id,OLD.id),'approved') THEN
   RAISE EXCEPTION 'Submit the close run and complete every configured Flow gate before approval.' USING ERRCODE='23514';
  END IF;
 END IF;
 IF NEW.status IN('approved','closed','published') AND (ROW(NEW.id,NEW.org_id,NEW.period_id,NEW.book_id,NEW.blueprint_id,NEW.scope,NEW.started_by)
    IS DISTINCT FROM ROW(OLD.id,OLD.org_id,OLD.period_id,OLD.book_id,OLD.blueprint_id,OLD.scope,OLD.started_by)
    OR NEW.status='approved' AND NEW.data_fingerprint IS DISTINCT FROM OLD.data_fingerprint) THEN
  RAISE EXCEPTION 'Revalidate the close run and submit its changed terms through Flows.' USING ERRCODE='23514';
 END IF;
 IF OLD.status='approved' AND NEW.status='approved' AND ROW(NEW.approved_by,NEW.approved_at)
    IS DISTINCT FROM ROW(OLD.approved_by,OLD.approved_at) THEN
  RAISE EXCEPTION 'The recorded close decision retains its actual actor and timestamp.' USING ERRCODE='23514';
 END IF;
 IF NEW.status='closed' AND OLD.status IS DISTINCT FROM NEW.status THEN
  IF OLD.status<>'approved' OR NEW.closed_by IS NULL OR NEW.closed_at IS NULL
    OR NEW.closed_by IS DISTINCT FROM NEW.updated_by
    OR NOT public.flow_subject_decision_authorized(OLD.org_id,'close_run',OLD.id,OLD.approved_by,
      public.close_run_approval_fingerprint(OLD.org_id,OLD.id),'approved') THEN
   RAISE EXCEPTION 'Lock only a close run with its retained current Flow approval.' USING ERRCODE='23514';
  END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(NEW.scope->'subsidiaryIds')='array'
      AND jsonb_array_length(NEW.scope->'subsidiaryIds')>0 THEN NEW.scope->'subsidiaryIds' ELSE '[null]'::jsonb END) entity(id)
    CROSS JOIN unnest(ARRAY['ar','ap','banking','assets','tax','gl']) module(name)
    WHERE NOT EXISTS(SELECT 1 FROM public.period_locks l WHERE l.org_id=NEW.org_id AND l.period_id=NEW.period_id
      AND l.book_id=NEW.book_id AND l.subsidiary_id IS NOT DISTINCT FROM entity.id::uuid AND l.module=module.name
      AND l.state='closed' AND (l.reopen_expires_at IS NULL OR l.reopen_expires_at<=now()))) THEN
   RAISE EXCEPTION 'Close the run through its native command so every scoped subledger and GL lock seals atomically.' USING ERRCODE='23514';
  END IF;
 END IF;
 IF NEW.status='published' AND OLD.status IS DISTINCT FROM NEW.status AND
    (OLD.status<>'closed' OR NEW.published_by IS NULL OR NEW.published_at IS NULL OR NEW.published_by IS DISTINCT FROM NEW.updated_by) THEN
  RAISE EXCEPTION 'Publish only the retained closed run through its native publication command.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: close_task_approval_dependencies(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_task_approval_dependencies(organization uuid, subject uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('run',jsonb_build_object('id',r.id,'fingerprint',r.data_fingerprint,'status',r.status),
   'evidence',coalesce((SELECT jsonb_agg(to_jsonb(e) ORDER BY e.id) FROM public.close_task_evidence e
     WHERE e.org_id=t.org_id AND e.task_id=t.id),'[]'::jsonb))
 FROM public.close_run_tasks t JOIN public.close_runs r ON r.org_id=t.org_id AND r.id=t.run_id
 WHERE t.org_id=organization AND t.id=subject
$$;


--
-- Name: close_task_flow_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_task_flow_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE fingerprint text; receipt public.flow_submissions;
BEGIN
 IF TG_OP='INSERT' THEN
  IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
  IF NEW.completion_mode='manual' AND NEW.status IN('submitted','complete','waived') THEN
   RAISE EXCEPTION 'Create the close task, then submit its current evidence through Flows.' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
 END IF;
 IF OLD.completion_mode='manual' AND OLD.status IN('complete','waived') AND NEW.status=OLD.status
  AND (to_jsonb(NEW)-ARRAY['updated_at','updated_by']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['updated_at','updated_by']) THEN
  RAISE EXCEPTION 'Completed close task evidence is immutable; revalidate the close run for changed work.' USING ERRCODE='23514';
 END IF;
 IF OLD.task_type='approval' AND NEW.status IS DISTINCT FROM OLD.status AND NEW.status IN('complete','changes_requested') THEN
  SELECT * INTO receipt FROM public.flow_submissions s WHERE s.org_id=NEW.org_id AND s.subject_kind='close_run'
    AND s.subject_id=NEW.run_id ORDER BY s.created_at DESC,s.id DESC LIMIT 1;
  IF NOT public.flow_subject_decision_authorized(NEW.org_id,'close_run',NEW.run_id,NEW.updated_by,
      public.close_run_approval_fingerprint(NEW.org_id,NEW.run_id),CASE WHEN NEW.status='complete' THEN 'approved' ELSE 'rejected' END)
    OR NOT EXISTS(SELECT 1 FROM public.close_runs r WHERE r.org_id=NEW.org_id AND r.id=NEW.run_id
      AND r.data_fingerprint=NEW.data_fingerprint AND r.status=CASE WHEN NEW.status='complete' THEN 'approved' ELSE 'in_progress' END)
    OR NEW.status='complete' AND (NEW.completed_at IS NULL OR NEW.completed_by IS DISTINCT FROM NEW.updated_by)
    OR receipt.policy->>'kind'='ungated' AND (NEW.reviewed_by IS NOT NULL OR NEW.reviewed_at IS NOT NULL)
    OR receipt.policy->>'kind'='gated' AND (NEW.reviewed_by IS DISTINCT FROM NEW.updated_by OR NEW.reviewed_at IS NULL) THEN
   RAISE EXCEPTION 'Approval tasks retain the parent close run decision, current evidence and actual Flow reviewer.' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
 END IF;
 IF NEW.completion_mode='manual' AND NEW.status IS DISTINCT FROM OLD.status AND NEW.status IN('complete','waived','changes_requested') THEN
  fingerprint:=public.flow_command_record_fingerprint(to_jsonb(OLD),public.close_task_approval_dependencies(OLD.org_id,OLD.id));
  IF NEW.status='changes_requested' THEN
   IF NOT public.flow_subject_decision_authorized(NEW.org_id,'close_task',NEW.id,NEW.updated_by,fingerprint,'rejected') THEN
    RAISE EXCEPTION 'Return the close task through its assigned current Flow gate.' USING ERRCODE='23514';
   END IF;
  ELSE
   IF NEW.completed_at IS NULL OR NOT public.flow_command_authorized(NEW.org_id,'close_task',NEW.id,NEW.updated_by,fingerprint,
     jsonb_build_object('action',CASE WHEN NEW.status='waived' THEN 'waive' ELSE 'complete' END)) THEN
    RAISE EXCEPTION 'Submit the close task and complete every configured Flow gate before release.' USING ERRCODE='23514';
   END IF;
   SELECT * INTO receipt FROM public.flow_submissions s WHERE s.org_id=NEW.org_id AND s.subject_kind='close_task' AND s.subject_id=NEW.id ORDER BY s.created_at DESC,s.id DESC LIMIT 1;
   IF NEW.completed_by IS DISTINCT FROM receipt.actor_id
     OR receipt.policy->>'kind'='ungated' AND (NEW.reviewed_by IS NOT NULL OR NEW.reviewed_at IS NOT NULL)
     OR receipt.policy->>'kind'='gated' AND (NEW.reviewed_by IS DISTINCT FROM NEW.updated_by OR NEW.reviewed_at IS NULL) THEN
    RAISE EXCEPTION 'Retain the close task preparer and actual native Flow decision identity.' USING ERRCODE='23514';
   END IF;
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: hrm_comp_cycles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hrm_comp_cycles (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    name text NOT NULL,
    kind text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    effective_on date,
    budget_basis text DEFAULT 'combined'::text NOT NULL,
    budget_total numeric(19,4),
    currency character(3) NOT NULL,
    guideline_kind text DEFAULT 'matrix'::text NOT NULL,
    guideline jsonb DEFAULT '{}'::jsonb NOT NULL,
    scope jsonb DEFAULT '{}'::jsonb NOT NULL,
    scope_employer_subsidiary_id uuid GENERATED ALWAYS AS (((scope ->> 'employer_subsidiary_id'::text))::uuid) STORED,
    scope_department_id uuid GENERATED ALWAYS AS (((scope ->> 'department_id'::text))::uuid) STORED,
    revision integer DEFAULT 1 NOT NULL,
    flow_run_id uuid,
    opened_at timestamp with time zone,
    approved_at timestamp with time zone,
    pushed_at timestamp with time zone,
    closed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    source_key text,
    source_evidence jsonb,
    CONSTRAINT hrm_comp_cycles_budget_basis CHECK ((budget_basis = ANY (ARRAY['top_down'::text, 'bottom_up'::text, 'combined'::text]))),
    CONSTRAINT hrm_comp_cycles_budget_nonneg CHECK (((budget_total IS NULL) OR (budget_total >= (0)::numeric))),
    CONSTRAINT hrm_comp_cycles_effective_date_required CHECK (((status = 'historical'::text) OR (effective_on IS NOT NULL))),
    CONSTRAINT hrm_comp_cycles_effective_on_finite CHECK (((effective_on >= '0001-01-01'::date) AND (effective_on <= '9999-12-31'::date))),
    CONSTRAINT hrm_comp_cycles_guideline_kind CHECK ((guideline_kind = ANY (ARRAY['matrix'::text, 'formula'::text]))),
    CONSTRAINT hrm_comp_cycles_guideline_shape CHECK ((jsonb_typeof(guideline) = 'object'::text)),
    CONSTRAINT hrm_comp_cycles_kind CHECK ((kind = ANY (ARRAY['merit'::text, 'promotion'::text, 'adjustment'::text, 'cola'::text]))),
    CONSTRAINT hrm_comp_cycles_name_not_blank CHECK ((char_length(btrim(name)) > 0)),
    CONSTRAINT hrm_comp_cycles_revision CHECK ((revision >= 1)),
    CONSTRAINT hrm_comp_cycles_scope_shape CHECK (((jsonb_typeof(scope) = 'object'::text) AND (((scope - 'employer_subsidiary_id'::text) - 'department_id'::text) = '{}'::jsonb) AND ((NOT (scope ? 'employer_subsidiary_id'::text)) OR (jsonb_typeof((scope -> 'employer_subsidiary_id'::text)) = 'null'::text) OR ((jsonb_typeof((scope -> 'employer_subsidiary_id'::text)) = 'string'::text) AND ((scope ->> 'employer_subsidiary_id'::text) ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'::text))) AND ((NOT (scope ? 'department_id'::text)) OR (jsonb_typeof((scope -> 'department_id'::text)) = 'null'::text) OR ((jsonb_typeof((scope -> 'department_id'::text)) = 'string'::text) AND ((scope ->> 'department_id'::text) ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'::text))))),
    CONSTRAINT hrm_comp_cycles_source_origin CHECK ((((status = 'historical'::text) = ((source_key IS NOT NULL) AND (source_evidence IS NOT NULL))) AND ((source_key IS NULL) = (source_evidence IS NULL)) AND ((source_evidence IS NULL) OR (jsonb_typeof(source_evidence) = 'object'::text)) AND ((source_key IS NULL) OR (length(btrim(source_key)) > 0)))),
    CONSTRAINT hrm_comp_cycles_status CHECK ((status = ANY (ARRAY['draft'::text, 'open'::text, 'in_review'::text, 'approved'::text, 'pushed'::text, 'closed'::text, 'cancelled'::text, 'historical'::text])))
);

ALTER TABLE ONLY public.hrm_comp_cycles FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE hrm_comp_cycles; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.hrm_comp_cycles IS 'HRM merit rounds: draft, open, in_review, approved, pushed, closed (or cancelled) with the date new rates take effect, the budget basis, and the matrix-or-formula guideline evaluated by the fixed-grammar service evaluator.';


--
-- Name: compensation_cycle_approval_fingerprint(public.hrm_comp_cycles); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compensation_cycle_approval_fingerprint(c public.hrm_comp_cycles) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 SELECT public.flow_command_record_fingerprint(to_jsonb(c)-ARRAY['revision','flow_run_id'],
  (SELECT coalesce(jsonb_agg(to_jsonb(l)-ARRAY['status','revision','decided_at','approver_party_id','updated_at','updated_by','reason'] ORDER BY l.id),'[]'::jsonb)
   FROM public.hrm_comp_cycle_lines l WHERE l.org_id=c.org_id AND l.cycle_id=c.id))
$$;


--
-- Name: compensation_cycle_flow_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compensation_cycle_flow_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status='approved' THEN RAISE EXCEPTION 'Create the compensation round before submission through Flows.'; END IF;
  RETURN NEW;
 END IF;
 IF OLD.status<>'approved' AND NEW.status='approved' AND NOT public.flow_command_authorized(NEW.org_id,'hrm_comp_cycle',NEW.id,NEW.updated_by,public.compensation_cycle_approval_fingerprint(OLD)) THEN
  RAISE EXCEPTION 'Release the compensation round through its complete native Flow submission.';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: compensation_self_decision_authorized(uuid, text, uuid, uuid, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compensation_self_decision_authorized(organization uuid, subject_kind text, subject_id uuid, package_id uuid, submitted_revision integer, outcome text, decision_actor uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 SELECT decision_actor IS NOT NULL AND subject_kind IN ('compensation_package_version','compensation_package_assignment')
  AND outcome IN ('approved','rejected') AND EXISTS (
   SELECT 1 FROM public.flow_runs r JOIN public.flow_gates g
     ON g.org_id=r.org_id AND g.run_id=r.id AND g.flow_id=r.flow_id
       AND g.subject_kind=r.subject_kind AND g.subject_id=r.subject_id
   WHERE r.org_id=organization AND r.subject_kind=compensation_self_decision_authorized.subject_kind
     AND r.subject_id=compensation_self_decision_authorized.subject_id AND r.trigger='on_submit'
     AND r.context->>'packageId'=package_id::text AND r.context->>'revision'=submitted_revision::text
     AND r.context->>'status'='submitted' AND r.context->'submissionPolicy'->>'flowId'=r.flow_id::text
     AND g.status=outcome AND g.decided_by=decision_actor AND g.decided_at IS NOT NULL
     AND EXISTS (SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(r.context #> '{submissionPolicy,graph,nodes}')='array'
       THEN r.context #> '{submissionPolicy,graph,nodes}' ELSE '[]'::jsonb END) node
       WHERE node->>'id'=g.node_id AND node->'data'->>'kind'='gate'
         AND node->'data'->'gate'->'preventSelfApproval'='false'::jsonb)
     AND NOT EXISTS (SELECT 1 FROM public.flow_gates pending WHERE pending.org_id=r.org_id
       AND pending.subject_kind=r.subject_kind AND pending.subject_id=r.subject_id AND pending.status IN ('pending','escalated'))
  );
$$;


--
-- Name: compensation_ungated_submission_authorized(uuid, text, uuid, uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compensation_ungated_submission_authorized(organization uuid, subject_kind text, subject_id uuid, package_id uuid, submitted_revision integer, decision_actor uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 SELECT subject_kind IN ('compensation_package_version','compensation_package_assignment')
  AND public.flow_ungated_submission_authorized(organization,subject_kind,subject_id,decision_actor,
    jsonb_build_object('packageId',package_id::text,'revision',submitted_revision,'status','submitted','submittedBy',decision_actor::text));
$$;


--
-- Name: compliance_certificate_flow_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compliance_certificate_flow_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.verified_at IS NOT NULL OR NEW.verified_by IS NOT NULL OR NEW.verified_revision IS NOT NULL THEN
   RAISE EXCEPTION 'Record the certificate before submitting verification through Flows.';
  END IF;
  RETURN NEW;
 END IF;
 IF ROW(NEW.verified_at,NEW.verified_by,NEW.verified_revision) IS DISTINCT FROM ROW(OLD.verified_at,OLD.verified_by,OLD.verified_revision)
  AND NEW.verified_at IS NOT NULL THEN
  IF NEW.status<>'active' OR NEW.verified_revision IS DISTINCT FROM OLD.revision OR NEW.revision<>OLD.revision+1
    OR (to_jsonb(NEW)-ARRAY['status','verified_at','verified_by','verified_revision','revision','rejected_reason','updated_at','updated_by'])
      IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','verified_at','verified_by','verified_revision','revision','rejected_reason','updated_at','updated_by'])
    OR NOT public.flow_command_authorized(NEW.org_id,'compliance_certificate',NEW.id,NEW.verified_by,
      public.flow_command_record_fingerprint(to_jsonb(OLD)),jsonb_build_object('revision',OLD.revision)) THEN
   RAISE EXCEPTION 'Verify this exact certificate revision through its native Flow submission.';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: compliance_record_renewal_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compliance_record_renewal_audit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.superseded_by_id IS DISTINCT FROM OLD.superseded_by_id
     AND NEW.superseded_by_id IS NOT NULL THEN
    INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id)
    VALUES (
      NEW.org_id,
      'compliance_records',
      NEW.id,
      'supersede',
      jsonb_build_object(
        'before', jsonb_build_object(
          'status', OLD.status,
          'supersededById', OLD.superseded_by_id
        ),
        'after', jsonb_build_object(
          'status', NEW.status,
          'supersededById', NEW.superseded_by_id
        )
      ),
      NEW.updated_by
    );
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: FUNCTION compliance_record_renewal_audit(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.compliance_record_renewal_audit() IS 'openbooks:compliance_record_renewal_audit:v1 - append-only before/after evidence for the predecessor mutation in a certificate renewal';


--
-- Name: compliance_record_renewal_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compliance_record_renewal_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  successor public.compliance_records%ROWTYPE;
BEGIN
  IF OLD.status = 'superseded' AND NEW.status <> 'superseded' THEN
    RAISE EXCEPTION
      'a superseded compliance record cannot be reinstated'
      USING ERRCODE = '23514';
  END IF;

  -- A renewal is the only legal operation that fills superseded_by_id.  The
  -- UPDATE row lock serializes competing transactions on the predecessor; the
  -- second waiter then sees the committed superseded state and is rejected.
  IF NEW.superseded_by_id IS NOT DISTINCT FROM OLD.superseded_by_id THEN
    IF NEW.status = 'superseded' AND NEW.superseded_by_id IS NULL THEN
      RAISE EXCEPTION
        'a superseded compliance record must identify its pending successor'
        USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.superseded_by_id IS NULL THEN
    RAISE EXCEPTION
      'a compliance record supersession pointer cannot be cleared'
      USING ERRCODE = '23514';
  END IF;

  IF OLD.status = 'superseded' OR OLD.superseded_by_id IS NOT NULL THEN
    RAISE EXCEPTION
      'compliance record % has already been superseded; renew the current record instead',
      OLD.id
      USING ERRCODE = '23505';
  END IF;

  IF NEW.status <> 'superseded' THEN
    RAISE EXCEPTION
      'a compliance renewal must mark its predecessor superseded'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.superseded_by_id = NEW.id THEN
    RAISE EXCEPTION
      'a compliance record cannot supersede itself'
      USING ERRCODE = '23514';
  END IF;

  SELECT *
    INTO successor
    FROM public.compliance_records
   WHERE id = NEW.superseded_by_id
   FOR KEY SHARE;

  IF NOT FOUND THEN
    RAISE EXCEPTION
      'compliance renewal successor % does not exist',
      NEW.superseded_by_id
      USING ERRCODE = '23503';
  END IF;

  IF successor.org_id IS DISTINCT FROM NEW.org_id
     OR successor.party_id IS DISTINCT FROM NEW.party_id
     OR successor.requirement_id IS DISTINCT FROM NEW.requirement_id
     OR successor.project_id IS DISTINCT FROM NEW.project_id
     OR successor.status <> 'pending_review'
     OR successor.superseded_by_id IS NOT NULL THEN
    RAISE EXCEPTION
      'compliance renewal successor % must be a pending record for the same organization, vendor, requirement, and project',
      NEW.superseded_by_id
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END
$$;


--
-- Name: FUNCTION compliance_record_renewal_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.compliance_record_renewal_guard() IS 'openbooks:compliance_record_renewal_guard:v1 - serializes predecessor supersession, rejects competing successors, and validates same-scope pending successor identity';


--
-- Name: compliance_waiver_flow_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compliance_waiver_flow_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.approved_at IS NOT NULL OR NEW.approved_by IS NOT NULL THEN RAISE EXCEPTION 'File the exception before submitting it through Flows.'; END IF;
  RETURN NEW;
 END IF;
 IF OLD.approved_at IS NOT NULL AND (to_jsonb(NEW)-ARRAY['revoked_at','revoked_by','revoke_reason','updated_at','updated_by']) IS DISTINCT FROM
   (to_jsonb(OLD)-ARRAY['revoked_at','revoked_by','revoke_reason','updated_at','updated_by']) THEN
  RAISE EXCEPTION 'An effective compliance exception is immutable; revoke it with a reason and submit a new exception.';
 END IF;
 IF OLD.approved_at IS NULL AND NEW.approved_at IS NOT NULL AND NOT public.flow_command_authorized(NEW.org_id,'compliance_waiver',NEW.id,NEW.approved_by,public.flow_command_record_fingerprint(to_jsonb(OLD))) THEN
  RAISE EXCEPTION 'Release this exception through its complete native Flow submission.';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: connector_historical_replay_authorized(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connector_historical_replay_authorized(p_org uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select
    coalesce(current_setting('openbooks.connector_replay', true), 'off') = 'on'
    and nullif(current_setting('openbooks.connector_replay_request', true), '') is not null
    and nullif(current_setting('openbooks.connector_replay_actor', true), '') is not null
    and current_setting('app.current_org', true) = p_org::text
    and exists (
      select 1
        from sync_runs run
        join connections connection
          on connection.id = run.connection_id
         and connection.org_id = run.org_id
        join users controller
          on controller.id = connection.posted_change_authorized_by
         and controller.org_id = connection.org_id
         and controller.is_active
       where run.id::text = current_setting('openbooks.connector_replay_request', true)
         and run.org_id = p_org
         and run.status = 'running'
         and run.kind in ('incremental', 'full_migration')
         and run.source = connection.source
         and connection.status not in ('paused', 'unconfigured')
         and connection.posted_change_policy = 'append_only_automatic'
         and connection.posted_change_authorized_at is not null
         and run.started_at >= connection.posted_change_authorized_at
         and connection.posted_change_authorized_by::text =
               current_setting('openbooks.connector_replay_actor', true)
    )
$$;


--
-- Name: FUNCTION connector_historical_replay_authorized(p_org uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.connector_historical_replay_authorized(p_org uuid) IS 'Fail-closed proof for controller-authorized append-only connector replay into a preserved closed period.';


--
-- Name: consignment_event_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consignment_event_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 RAISE EXCEPTION 'Consignment events are immutable; record a correcting stock operation';
END $$;


--
-- Name: consignment_position_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consignment_position_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE tracking_mode text; location_owner text; location_party uuid;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' THEN
  IF public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'Custody history is immutable; return the stock through the custody command';
 END IF;
 IF TG_OP='UPDATE' THEN
  IF (NEW.id,NEW.org_id,NEW.subsidiary_id,NEW.item_id,NEW.stock_location_id,NEW.owner_party_id,NEW.owner_kind,NEW.lot_id,NEW.serial_id,NEW.received_on,NEW.original_quantity,NEW.reason,NEW.created_by,NEW.created_at)
    IS DISTINCT FROM (OLD.id,OLD.org_id,OLD.subsidiary_id,OLD.item_id,OLD.stock_location_id,OLD.owner_party_id,OLD.owner_kind,OLD.lot_id,OLD.serial_id,OLD.received_on,OLD.original_quantity,OLD.reason,OLD.created_by,OLD.created_at)
    OR NEW.remaining_quantity>OLD.remaining_quantity THEN
   RAISE EXCEPTION 'Custody identity and received quantity are immutable; record a new custody operation';
  END IF;
  RETURN NEW;
 END IF;
 SELECT inventory_ownership,owner_party_id INTO location_owner,location_party FROM public.stock_locations
  WHERE org_id=NEW.org_id AND id=NEW.stock_location_id FOR SHARE;
 IF location_owner IS DISTINCT FROM NEW.owner_kind OR location_party IS DISTINCT FROM NEW.owner_party_id THEN
  RAISE EXCEPTION 'Custody location must carry the recorded external owner';
 END IF;
 SELECT tracking INTO tracking_mode FROM public.item_inventory_profiles WHERE org_id=NEW.org_id AND item_id=NEW.item_id FOR SHARE;
 IF tracking_mode IS NULL OR tracking_mode NOT IN('none','lot','serial','lot_serial') THEN RAISE EXCEPTION 'Custody requires an inventory profile'; END IF;
 IF tracking_mode IN('lot','lot_serial') THEN
  IF NEW.lot_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.lots WHERE org_id=NEW.org_id AND id=NEW.lot_id AND item_id=NEW.item_id) THEN RAISE EXCEPTION 'Custody requires the item lot'; END IF;
 ELSIF NEW.lot_id IS NOT NULL THEN RAISE EXCEPTION 'This custody item does not track lots'; END IF;
 IF tracking_mode IN('serial','lot_serial') THEN
  PERFORM id FROM public.serials WHERE org_id=NEW.org_id AND id=NEW.serial_id FOR UPDATE;
  IF NEW.serial_id IS NULL OR NEW.original_quantity<>1 OR NOT EXISTS(SELECT 1 FROM public.serials
    WHERE org_id=NEW.org_id AND id=NEW.serial_id AND item_id=NEW.item_id
      AND (tracking_mode<>'lot_serial' OR lot_id=NEW.lot_id)) THEN RAISE EXCEPTION 'Custody requires one unit of the item serial and its lot'; END IF;
  IF NEW.remaining_quantity>0 AND EXISTS(SELECT 1 FROM public.cost_layers layer JOIN public.inventory_movements source ON source.org_id=layer.org_id AND source.id=layer.source_movement_id
    WHERE layer.org_id=NEW.org_id AND source.serial_id=NEW.serial_id AND layer.remaining_quantity>0) THEN
   RAISE EXCEPTION 'Serial is already valued stock; issue or return it before receiving external custody';
  END IF;
 ELSIF NEW.serial_id IS NOT NULL THEN RAISE EXCEPTION 'This custody item does not track serials'; END IF;
 RETURN NEW;
END $$;


--
-- Name: contract_cost_amortization_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_cost_amortization_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  RAISE EXCEPTION 'Contract cost amortization is immutable; post an impairment or reversal entry instead.'
    USING ERRCODE = '23514';
  RETURN NULL;
END $$;


--
-- Name: contract_cost_asset_terms_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_cost_asset_terms_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF (NEW.amount_minor IS DISTINCT FROM OLD.amount_minor
      OR NEW.currency IS DISTINCT FROM OLD.currency
      OR NEW.amort_start_on IS DISTINCT FROM OLD.amort_start_on
      OR NEW.amort_end_on IS DISTINCT FROM OLD.amort_end_on
      OR NEW.method IS DISTINCT FROM OLD.method)
     AND EXISTS (SELECT 1 FROM public.contract_cost_amortization
                  WHERE org_id = OLD.org_id AND asset_id = OLD.id) THEN
    RAISE EXCEPTION 'A contract cost asset with posted amortization cannot change its amount, currency, method or amortization window; impair it instead.'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: control_loss_asset_measurement_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.control_loss_asset_measurement_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM asset_transfer_bases b JOIN consolidation_control_losses loss ON loss.org_id=b.org_id AND loss.reversed_by_change_id IS NULL AND (loss.excluded_subsidiary_ids ? b.buyer_subsidiary_id::text OR loss.excluded_subsidiary_ids ? b.seller_subsidiary_id::text) WHERE b.org_id=NEW.org_id AND b.id=NEW.transfer_id AND NEW.effective_on<=loss.effective_on) THEN RAISE EXCEPTION 'this group measurement changes an approved disposal basis; correct that disposal through Accounting changes first'; END IF;
 RETURN NEW;
END $$;


--
-- Name: control_loss_component_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.control_loss_component_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.group_component IS NOT NULL AND EXISTS(SELECT 1 FROM asset_transfer_bases b JOIN consolidation_control_losses loss ON loss.org_id=b.org_id AND loss.reversed_by_change_id IS NULL AND (loss.excluded_subsidiary_ids ? b.buyer_subsidiary_id::text OR loss.excluded_subsidiary_ids ? b.seller_subsidiary_id::text) WHERE b.org_id=NEW.org_id AND b.receiving_asset_id=NEW.asset_id AND b.book_id=NEW.book_id AND NEW.effective_on<=loss.effective_on) THEN RAISE EXCEPTION 'the component measurement changes an approved loss-of-control basis; correct that disposal through Accounting changes first'; END IF;
 RETURN NEW;
END $$;


--
-- Name: control_loss_hierarchy_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.control_loss_hierarchy_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN RETURN NEW; END IF;
 IF (NEW.parent_id,NEW.base_currency,NEW.is_active,NEW.is_elimination) IS DISTINCT FROM (OLD.parent_id,OLD.base_currency,OLD.is_active,OLD.is_elimination) AND EXISTS(SELECT 1 FROM consolidation_control_losses loss WHERE loss.org_id=OLD.org_id AND loss.reversed_by_change_id IS NULL AND (loss.excluded_subsidiary_ids ? OLD.id::text OR OLD.id IN(loss.parent_subsidiary_id,loss.elimination_subsidiary_id))) THEN RAISE EXCEPTION 'the entity hierarchy and currency support an approved disposal; correct the disposal before changing its historical reporting scope'; END IF;
 RETURN NEW;
END $$;


--
-- Name: control_loss_history_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.control_loss_history_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END IF;
 IF TG_OP='UPDATE' THEN
  IF OLD.reversed_by_change_id IS NULL AND NEW.reversed_by_change_id IS NOT NULL AND (to_jsonb(NEW)-'reversed_by_change_id') IS NOT DISTINCT FROM (to_jsonb(OLD)-'reversed_by_change_id') AND EXISTS(SELECT 1 FROM financial_changes f WHERE f.org_id=OLD.org_id AND f.id=NEW.reversed_by_change_id AND f.domain='consolidation' AND f.operation='reversal' AND f.payload->>'sourceChangeId'=OLD.change_id::text AND f.status='approved') THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'loss-of-control evidence is immutable; propose its independently approved correction';
 ELSIF TG_OP='DELETE' THEN RAISE EXCEPTION 'loss-of-control evidence cannot be deleted'; END IF;
 IF NOT(NEW.excluded_subsidiary_ids ? NEW.subsidiary_id::text) OR NOT EXISTS(SELECT 1 FROM subsidiaries s WHERE s.org_id=NEW.org_id AND s.id=NEW.elimination_subsidiary_id AND s.is_elimination) OR (NEW.retained_interest_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM subsidiary_ownership_interests p WHERE p.org_id=NEW.org_id AND p.id=NEW.retained_interest_id AND p.subsidiary_id=NEW.subsidiary_id AND p.parent_subsidiary_id=NEW.parent_subsidiary_id AND p.method=NEW.retained_method AND p.effective_from=NEW.effective_on+1)) THEN RAISE EXCEPTION 'loss-of-control entities and retained interest must match the approved ownership scope'; END IF;
 IF NOT EXISTS(SELECT 1 FROM accounting_books b WHERE b.id=NEW.book_id AND b.org_id=NEW.org_id AND b.is_primary AND b.posts_gl AND b.is_active) OR NOT EXISTS(SELECT 1 FROM accounting_periods p WHERE p.id=NEW.period_id AND p.org_id=NEW.org_id AND NEW.effective_on BETWEEN p.starts_on AND p.ends_on) OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(NEW.excluded_subsidiary_ids) child(id) WHERE NOT EXISTS(SELECT 1 FROM subsidiaries s WHERE s.id=child.id::uuid AND s.org_id=NEW.org_id)) THEN RAISE EXCEPTION 'loss-of-control scope must reference this organization and accounting period'; END IF;
 IF EXISTS(SELECT 1 FROM unnest(array_remove(ARRAY[NEW.parent_journal_entry_id,NEW.journal_entry_id],NULL)) wanted(id) WHERE NOT EXISTS(SELECT 1 FROM journal_entries e WHERE e.org_id=NEW.org_id AND e.id=wanted.id AND e.book_id=NEW.book_id AND e.period_id=NEW.period_id AND e.status='posted')) THEN RAISE EXCEPTION 'loss-of-control journals must be posted in its accounting book and period'; END IF;
 IF NOT EXISTS(SELECT 1 FROM financial_changes f WHERE f.org_id=NEW.org_id AND f.id=NEW.change_id AND f.domain='consolidation' AND f.subject_id=NEW.interest_id AND f.status='approved') THEN RAISE EXCEPTION 'loss of control requires independent approval for this ownership interest'; END IF;
 IF NOT EXISTS(SELECT 1 FROM subsidiary_ownership_interests p WHERE p.org_id=NEW.org_id AND p.id=NEW.interest_id AND p.subsidiary_id=NEW.subsidiary_id AND p.parent_subsidiary_id=NEW.parent_subsidiary_id AND p.effective_to=NEW.effective_on) THEN RAISE EXCEPTION 'loss of control must close its ownership window at the approved date'; END IF;
 RETURN NEW;
END $$;


--
-- Name: control_loss_source_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.control_loss_source_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END IF;
 IF TG_TABLE_NAME='journal_entries' THEN
  IF NEW.status='posted' AND (TG_OP='INSERT' OR OLD.status<>'posted') AND EXISTS(SELECT 1 FROM consolidation_control_losses loss WHERE loss.org_id=NEW.org_id AND loss.reversed_by_change_id IS NULL AND loss.book_id=NEW.book_id AND ( (NEW.posting_date<=loss.effective_on AND EXISTS(SELECT 1 FROM journal_lines l WHERE l.org_id=NEW.org_id AND l.entry_id=NEW.id AND loss.excluded_subsidiary_ids ? l.subsidiary_id::text)) OR NEW.reverses_entry_id IN(SELECT jsonb_array_elements_text(loss.measurement->'sourceEntryIds')::uuid) OR NEW.reverses_entry_id IN(SELECT jsonb_array_elements_text(f.result->'entryIds')::uuid FROM financial_changes f WHERE f.org_id=loss.org_id AND f.id=loss.change_id) OR NEW.reverses_entry_id IN(SELECT (evidence->>'entryId')::uuid FROM jsonb_array_elements(loss.measurement->'manualEvidence') evidence))) THEN RAISE EXCEPTION 'this posting changes an approved disposal source; propose a correction from Accounting changes before changing the historical balances'; END IF;
  RETURN NEW;
 ELSIF TG_TABLE_NAME='consolidated_fx_rates' THEN
  IF EXISTS(SELECT 1 FROM consolidation_control_losses loss JOIN accounting_periods p ON p.org_id=loss.org_id AND p.id=OLD.period_id WHERE loss.org_id=OLD.org_id AND loss.reversed_by_change_id IS NULL AND p.starts_on<=loss.effective_on AND EXISTS(SELECT 1 FROM subsidiaries s WHERE s.org_id=loss.org_id AND loss.excluded_subsidiary_ids ? s.id::text AND s.base_currency=OLD.from_currency)) AND (TG_OP='DELETE' OR (NEW.current_rate,NEW.average_rate,NEW.historical_rate) IS DISTINCT FROM (OLD.current_rate,OLD.average_rate,OLD.historical_rate)) THEN RAISE EXCEPTION 'consolidated rates support an approved disposal; correct that disposal before changing its historical translation evidence'; END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: cost_layer_fill_subsidiary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cost_layer_fill_subsidiary() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  owner uuid;
BEGIN
  IF NEW.subsidiary_id IS NOT NULL THEN
    RETURN NEW;
  END IF;
  SELECT m.subsidiary_id INTO owner
    FROM public.inventory_movements m
   WHERE m.id = NEW.source_movement_id
     AND m.org_id = NEW.org_id;
  IF owner IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = 'check_violation',
      MESSAGE = 'cost layer requires the legal entity of its source receipt movement',
      DETAIL = 'The source movement was not found, so ownership could not be derived.',
      HINT = 'Create the source movement before its cost layer.';
  END IF;
  NEW.subsidiary_id := owner;
  RETURN NEW;
END;
$$;


--
-- Name: create_org_base_price_level(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_org_base_price_level() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.sandbox_of IS NOT NULL THEN
    RETURN NEW;
  END IF;
  INSERT INTO public.price_levels (org_id, code, name, is_base, is_active)
  VALUES (NEW.id, 'BASE', 'Base price', true, true);
  RETURN NEW;
END;
$$;


--
-- Name: crew_time_batches; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.crew_time_batches (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    foreman_party_id uuid NOT NULL,
    project_id uuid NOT NULL,
    worked_on date NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    signature_evidence jsonb,
    submitted_at timestamp with time zone,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT crew_time_batches_status CHECK ((status = ANY (ARRAY['draft'::text, 'submitted'::text, 'approved'::text, 'rejected'::text, 'posted'::text]))),
    CONSTRAINT crew_time_batches_submitted_at CHECK ((((status = ANY (ARRAY['draft'::text, 'rejected'::text])) AND (submitted_at IS NULL)) OR (status <> ALL (ARRAY['draft'::text, 'rejected'::text]))))
);

ALTER TABLE ONLY public.crew_time_batches FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE crew_time_batches; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.crew_time_batches IS 'Field crew batches: foreman batch per project per day with signed submit and multi-stage approval; posting creates time_entries.';


--
-- Name: crew_time_batch_approval_fingerprint(public.crew_time_batches); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crew_time_batch_approval_fingerprint(b public.crew_time_batches) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 SELECT public.flow_command_record_fingerprint(to_jsonb(b),(SELECT coalesce(jsonb_agg(to_jsonb(l) ORDER BY l.id),'[]'::jsonb)
  FROM public.crew_time_batch_lines l WHERE l.org_id=b.org_id AND l.batch_id=b.id))
$$;


--
-- Name: crew_time_batch_flow_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crew_time_batch_flow_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status IN('approved','posted','rejected') THEN RAISE EXCEPTION 'Create a draft crew batch before native submission.'; END IF;
  RETURN NEW;
 END IF;
 IF OLD.status='submitted' AND NEW.status IN('approved','rejected') THEN
  IF (to_jsonb(NEW)-ARRAY['status','submitted_at','updated_at','updated_by']) IS DISTINCT FROM
    (to_jsonb(OLD)-ARRAY['status','submitted_at','updated_at','updated_by']) THEN
   RAISE EXCEPTION 'A crew decision cannot replace submitted hours, project or signature evidence.';
  END IF;
  IF NEW.status='approved' AND public.flow_ungated_submission_authorized(NEW.org_id,'crew_time_batch',NEW.id,NEW.updated_by,
    jsonb_build_object('approvalFingerprint',public.crew_time_batch_approval_fingerprint(OLD))) THEN RETURN NEW; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.flow_submissions s JOIN public.flow_runs r ON r.org_id=s.org_id AND s.policy->'runIds' ? r.id::text
    JOIN public.flow_gates g ON g.org_id=r.org_id AND g.run_id=r.id
    WHERE s.org_id=NEW.org_id AND s.subject_kind='crew_time_batch' AND s.subject_id=NEW.id
      AND s.context->>'approvalFingerprint'=public.crew_time_batch_approval_fingerprint(OLD)
      AND g.status=NEW.status AND g.decided_by=NEW.updated_by AND r.status IN('waiting','completed') AND r.error IS NULL
      AND NOT EXISTS(SELECT 1 FROM public.flow_submissions newer WHERE newer.org_id=s.org_id AND newer.subject_kind=s.subject_kind
        AND newer.subject_id=s.subject_id AND (newer.created_at,newer.id)>(s.created_at,s.id))
      AND (NEW.status='rejected' OR public.flow_submission_approved(s.org_id,s.subject_kind,s.subject_id,s.id)))
    OR EXISTS(SELECT 1 FROM public.flow_gates g WHERE g.org_id=NEW.org_id AND g.subject_kind='crew_time_batch'
       AND g.subject_id=NEW.id AND g.status IN('pending','escalated')) THEN
   RAISE EXCEPTION 'Complete the current crew batch Flow submission before deciding it.';
  END IF;
 ELSIF OLD.status='draft' AND NEW.status IN('approved','posted','rejected') THEN
  RAISE EXCEPTION 'Submit the crew batch through Flows before release.';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: customer_price_level_end_date_on_deactivate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_price_level_end_date_on_deactivate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT NEW.is_active AND OLD.is_active THEN
    -- Only a still-open window can be revoked into history or removed; an
    -- already-closed window stays exactly as the operator left it, so late
    -- transactions inside it keep pricing off it.
    IF NEW.effective_to IS NULL OR NEW.effective_to >= current_date THEN
      IF NEW.effective_from > current_date THEN
        -- Revoked before a future window ever started: never effective, so
        -- end-dating would leave a live future window on a dead row. Remove
        -- it instead; no transaction could have priced off it — but the
        -- removal is audited with the row's before-image, never silent
        -- (PRC15d). The delete and its audit run as the deactivating role
        -- under the same org_isolation predicate that permitted the update,
        -- and the caller observes zero updated rows and must report the
        -- revocation as the delete it was (see updateSetupRecord).
        INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id)
        VALUES (NEW.org_id, 'customer_price_level_assignments', NEW.id, 'delete',
                jsonb_build_object('before', to_jsonb(OLD)), NEW.updated_by);
        DELETE FROM public.customer_price_level_assignments
         WHERE org_id = NEW.org_id AND id = NEW.id;
        RETURN NULL;
      ELSIF NEW.effective_from = current_date THEN
        -- Same-day revoke: the row stays. It may already have priced
        -- intraday transactions, and their recorded basis points at this
        -- row, so removing it would destroy priced lineage (RESIDUAL).
        -- Dating the window to yesterday would violate
        -- customer_price_level_dates and any storable window would still
        -- price today, so the revoke is stamped as an instant instead: the
        -- resolver treats the row as inactive for lookups at or after it.
        NEW.revoked_at := now();
        NEW.revoked_by := NEW.updated_by;
      ELSE
        NEW.effective_to := current_date - 1;
      END IF;
    END IF;
  ELSIF NEW.is_active AND NOT OLD.is_active THEN
    -- Re-offered: a stale revoke instant must not keep the row dark.
    NEW.revoked_at := NULL;
    NEW.revoked_by := NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: data_transfer_evidence_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.data_transfer_evidence_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF public.app_bypass_rls_active() AND current_setting('openbooks.amend',true)='on' THEN
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
 END IF;
 IF TG_TABLE_NAME='data_transfer_chunks' THEN
  IF TG_OP='DELETE' AND OLD.direction='output'
     AND EXISTS (SELECT 1 FROM public.data_transfer_jobs WHERE org_id=OLD.org_id AND id=OLD.job_id AND state='exporting') THEN
   RETURN OLD;
  END IF;
 ELSIF TG_TABLE_NAME='data_transfer_rows' THEN
  IF TG_OP='UPDATE' AND ROW(NEW.org_id,NEW.job_id,NEW.row_no,NEW.data) IS NOT DISTINCT FROM ROW(OLD.org_id,OLD.job_id,OLD.row_no,OLD.data) THEN
   RETURN NEW;
  END IF;
 END IF;
 RAISE EXCEPTION 'Transfer source and lifecycle evidence are immutable; create a new transfer for corrected source data.' USING ERRCODE='23514';
END $$;


--
-- Name: depreciation_book_policy_history_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.depreciation_book_policy_history_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' AND NOT EXISTS (SELECT 1 FROM public.orgs WHERE id = OLD.org_id) THEN
    RETURN OLD; -- Permit the owning tenant's cascade, not ordinary policy deletion.
  END IF;
  IF TG_OP = 'UPDATE' AND
     ROW(NEW.id, NEW.org_id, NEW.book_id, NEW.category_id, NEW.method,
         NEW.depreciation_method_id, NEW.life_months, NEW.rate_percent, NEW.units_total, NEW.convention)
     IS NOT DISTINCT FROM
     ROW(OLD.id, OLD.org_id, OLD.book_id, OLD.category_id, OLD.method,
         OLD.depreciation_method_id, OLD.life_months, OLD.rate_percent, OLD.units_total, OLD.convention) THEN
    RETURN NEW;
  END IF;

  -- Builders/posters take this same fence. They must read policy by MVCC,
  -- without a policy tuple lock: UPDATE already owns that tuple before its
  -- trigger executes and may be waiting here for a builder to finish.
  PERFORM 1 FROM public.asset_categories c
   WHERE (TG_OP <> 'INSERT' AND c.org_id = OLD.org_id AND c.id = OLD.category_id)
      OR (TG_OP <> 'DELETE' AND c.org_id = NEW.org_id AND c.id = NEW.category_id)
   ORDER BY c.org_id, c.id FOR UPDATE;

  IF EXISTS (
    SELECT 1 FROM public.fixed_assets a
     WHERE ((TG_OP <> 'INSERT' AND a.org_id = OLD.org_id AND a.category_id = OLD.category_id)
         OR (TG_OP <> 'DELETE' AND a.org_id = NEW.org_id AND a.category_id = NEW.category_id))
       AND (EXISTS (
       SELECT 1 FROM public.depreciation_schedules s
       JOIN public.depreciation_schedule_lines l ON l.org_id = s.org_id AND l.schedule_id = s.id
        WHERE s.org_id = a.org_id AND s.asset_id = a.id AND l.posted_amount IS NOT NULL
          AND ((TG_OP <> 'INSERT' AND a.org_id = OLD.org_id AND a.category_id = OLD.category_id AND s.book_id = OLD.book_id)
            OR (TG_OP <> 'DELETE' AND a.org_id = NEW.org_id AND a.category_id = NEW.category_id AND s.book_id = NEW.book_id))
     ) OR EXISTS (
       SELECT 1 FROM public.asset_events e
       JOIN public.journal_entries j ON j.org_id = e.org_id AND j.id = e.journal_entry_id
        WHERE e.org_id = a.org_id AND e.asset_id = a.id AND j.status IN ('posted', 'reversed')
          AND ((TG_OP <> 'INSERT' AND a.org_id = OLD.org_id AND a.category_id = OLD.category_id AND j.book_id = OLD.book_id)
            OR (TG_OP <> 'DELETE' AND a.org_id = NEW.org_id AND a.category_id = NEW.category_id AND j.book_id = NEW.book_id))
     ))
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'depreciation_book_posted_policy',
      MESSAGE = 'Depreciation book accounting policy is fixed after financial history exists. Create a new category or use a controlled adjustment.';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END
$$;


--
-- Name: depreciation_evidence_attachment_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.depreciation_evidence_attachment_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  if tg_op = 'DELETE' and public.openbooks_sandbox_wipe_allowed(old.org_id) then
    return old;
  end if;
  if old.target_table = 'fixed_assets' and exists (
    select 1
      from depreciation_inputs i
      join depreciation_schedules s on s.id = i.schedule_id
     where i.org_id = old.org_id and i.evidence_file_id = old.file_id and s.asset_id = old.target_id
  ) then
    raise exception 'file attachment is retained by depreciation evidence';
  end if;
  return coalesce(new, old);
end $$;


--
-- Name: depreciation_input_file_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.depreciation_input_file_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  owning_asset uuid;
begin
  select s.asset_id into owning_asset
    from depreciation_schedules s
   where s.id = new.schedule_id and s.org_id = new.org_id;
  if owning_asset is null then
    raise exception 'depreciation input schedule must belong to the tenant';
  end if;
  if not exists (select 1 from files f where f.id = new.evidence_file_id and f.org_id = new.org_id and not f.is_inactive) then
    raise exception 'depreciation evidence file must be active and belong to the tenant';
  end if;
  if not exists (
    select 1 from file_attachments fa
     where fa.org_id = new.org_id and fa.file_id = new.evidence_file_id
       and fa.target_table = 'fixed_assets' and fa.target_id = owning_asset
  ) then
    raise exception 'depreciation evidence file must be attached to the owning fixed asset';
  end if;
  return new;
end $$;


--
-- Name: depreciation_method_definition_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.depreciation_method_definition_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if (new.org_id is distinct from old.org_id
      or new.formula is distinct from old.formula
      or new.end_of_life is distinct from old.end_of_life
      or new.is_active is distinct from old.is_active) and exists (
    select 1 from depreciation_schedules s where s.depreciation_method_id = old.id
  ) then
    raise exception 'a depreciation formula used by a schedule is immutable; create a new method version';
  end if;
  return new;
end $$;


--
-- Name: depreciation_non_gl_recognition_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.depreciation_non_gl_recognition_audit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.non_gl_recognized_at IS NOT NULL
     AND (TG_OP = 'INSERT' OR OLD.non_gl_recognized_at IS NULL) THEN
    INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id)
    VALUES (NEW.org_id, 'depreciation_schedule_lines', NEW.id, lower(TG_OP),
      jsonb_build_object(
        'before', CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE to_jsonb(OLD) END,
        'after', to_jsonb(NEW),
        'reason', 'Recognize reporting-book depreciation without a GL journal'),
      NEW.updated_by);
  END IF;
  RETURN NEW;
END $$;


--
-- Name: depreciation_non_gl_recognition_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.depreciation_non_gl_recognition_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  book_id uuid;
  subsidiary_id uuid;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP <> 'INSERT' AND OLD.non_gl_recognized_at IS NOT NULL THEN
    IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    IF TG_OP = 'DELETE' OR NEW IS DISTINCT FROM OLD THEN
      RAISE EXCEPTION 'recognized reporting-book depreciation is immutable; retain this line and rebuild only unrecognized schedule lines';
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  IF NEW.non_gl_recognized_at IS NULL THEN RETURN NEW; END IF;

  -- A recognition completes an existing measurement, never rewrites a posted
  -- one or launders imported/GL evidence into the reporting-only path.
  IF NEW.posted_amount IS NULL OR NEW.posted_amount IS DISTINCT FROM NEW.planned_amount
     OR NEW.journal_entry_id IS NOT NULL OR NEW.source = 'imported'
     OR (TG_OP = 'UPDATE' AND OLD.posted_amount IS NOT NULL) THEN
    RAISE EXCEPTION 'reporting-book recognition requires its unrecognized planned amount and no GL journal';
  END IF;
  IF TG_OP = 'UPDATE' AND
     (to_jsonb(NEW) - ARRAY['posted_amount','non_gl_recognized_at','updated_at','updated_by'])
     IS DISTINCT FROM
     (to_jsonb(OLD) - ARRAY['posted_amount','non_gl_recognized_at','updated_at','updated_by']) THEN
    RAISE EXCEPTION 'recognize the existing depreciation measurement before proposing a separate correction';
  END IF;
  -- Branch: clone-authority-insert (0316). The deterministic clone replays
  -- recognized reporting-book history verbatim. The referenced book, asset
  -- and period rows may not be visible yet — bulk-copy order is not
  -- topological inside a reference cycle, so a row trigger cannot assume its
  -- parents were copied first (the deferred foreign keys validate them at
  -- commit instead) — and the target period may already be closed there, even
  -- though the recognition was valid where it was written. Skip the
  -- live-state revalidation below for the copied row: the shape checks above
  -- still ran, the CHECK constraints still apply, and the row keeps its
  -- source recognition instant verbatim instead of restamping it. INSERT-only:
  -- an UPDATE or DELETE under the authority still runs every check below.
  IF TG_OP = 'INSERT' AND public.openbooks_clone_authority() THEN
    RETURN NEW;
  END IF;
  SELECT b.id, a.subsidiary_id INTO book_id, subsidiary_id
    FROM public.depreciation_schedules s
    JOIN public.accounting_books b ON b.id = s.book_id AND b.org_id = s.org_id
    JOIN public.fixed_assets a ON a.id = s.asset_id AND a.org_id = s.org_id
    JOIN public.accounting_periods p ON p.id = NEW.period_id AND p.org_id = s.org_id
   WHERE s.id = NEW.schedule_id AND s.org_id = NEW.org_id
     AND b.is_active AND NOT b.posts_gl
     AND a.status NOT IN ('disposed', 'written_off')
   FOR SHARE OF b;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'reporting-book recognition requires an active non-posting book and an active asset and period in the same organization';
  END IF;
  IF NEW.updated_by IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.users u WHERE u.id = NEW.updated_by AND u.org_id = NEW.org_id
  ) THEN
    RAISE EXCEPTION 'depreciation recognition actor must belong to the same organization';
  END IF;
  PERFORM public.period_posting_fence(NEW.org_id, NEW.period_id, book_id);
  IF public.period_module_blocks_write(NEW.org_id, NEW.period_id, book_id, subsidiary_id, 'assets', false)
     OR public.period_module_blocks_write(NEW.org_id, NEW.period_id, book_id, subsidiary_id, 'gl', false) THEN
    RAISE EXCEPTION 'the accounting book is closed for depreciation; obtain an authorized period reopening before running depreciation';
  END IF;
  -- An operator cannot backdate the recognition timestamp used by reversal
  -- guards. The effective service period remains NEW.period_id.
  NEW.non_gl_recognized_at := clock_timestamp();
  NEW.updated_at := NEW.non_gl_recognized_at;
  RETURN NEW;
END $$;


--
-- Name: depreciation_source_authority_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.depreciation_source_authority_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  original depreciation_schedule_lines%ROWTYPE;
  asset fixed_assets%ROWTYPE;
  schedule depreciation_schedules%ROWTYPE;
BEGIN
  IF TG_OP='DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;
  IF TG_OP<>'INSERT' AND (OLD.journal_entry_id IS NOT NULL OR OLD.non_gl_recognized_at IS NOT NULL) THEN
    IF TG_OP='DELETE' AND openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
    IF TG_OP='DELETE' OR NEW IS DISTINCT FROM OLD THEN
      RAISE EXCEPTION 'Posted depreciation evidence is immutable; append a governed reversal.';
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  IF TG_OP='INSERT' AND openbooks_clone_authority() THEN RETURN NEW; END IF;
  SELECT * INTO STRICT schedule FROM depreciation_schedules WHERE org_id=NEW.org_id AND id=NEW.schedule_id;
  SELECT * INTO STRICT asset FROM fixed_assets WHERE org_id=NEW.org_id AND id=schedule.asset_id FOR SHARE;
  IF asset.custom->'sourceManaged'='true'::jsonb AND NEW.source NOT IN('imported','reversal') THEN
    RAISE EXCEPTION 'Source-managed assets require source depreciation; synchronize the owning connection.';
  END IF;
  IF NEW.source<>'reversal' THEN RETURN NEW; END IF;
  SELECT * INTO STRICT original FROM depreciation_schedule_lines WHERE org_id=NEW.org_id AND id=NEW.reverses_line_id FOR UPDATE;
  IF original.source IN('imported','reversal') OR original.posted_amount IS NULL OR original.posted_amount=0
    OR original.journal_entry_id IS NULL OR original.non_gl_recognized_at IS NOT NULL
    OR original.schedule_id<>NEW.schedule_id OR original.period_id<>NEW.period_id
    OR NEW.posted_amount<>-original.posted_amount OR NEW.planned_amount<>-original.posted_amount
    OR asset.custom->'sourceManaged' IS DISTINCT FROM 'true'::jsonb THEN
    RAISE EXCEPTION 'Depreciation correction must negate one local posting on its source-managed asset, book and period.';
  END IF;
  IF NOT EXISTS(
    SELECT 1 FROM journal_entries source JOIN journal_entries reversal
      ON reversal.org_id=source.org_id AND reversal.reverses_entry_id=source.id
    WHERE source.org_id=NEW.org_id AND source.id=original.journal_entry_id AND source.status='reversed'
      AND source.origin='depreciation' AND source.book_id=schedule.book_id AND source.subsidiary_id=asset.subsidiary_id
      AND reversal.id=NEW.journal_entry_id AND reversal.status='posted' AND reversal.origin='depreciation'
      AND reversal.book_id=source.book_id AND reversal.period_id=source.period_id
      AND reversal.posting_date=source.posting_date AND reversal.subsidiary_id=source.subsidiary_id
  ) THEN RAISE EXCEPTION 'Depreciation correction requires its posted original-date journal reversal.'; END IF;
  RETURN NEW;
END $$;


--
-- Name: document_payment_terms_snapshot_valid(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_payment_terms_snapshot_valid(evidence jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog'
    SET "DateStyle" TO 'ISO, YMD'
    AS $_$
DECLARE terms jsonb; percentage numeric; has_discount boolean;
BEGIN
 IF evidence IS NULL THEN RETURN true; END IF;
 IF jsonb_typeof(evidence) <> 'object' OR (SELECT count(*) FROM jsonb_object_keys(evidence)) <> 7
  OR NOT evidence ?& ARRAY['version','mode','source','documentKind','partyId','documentDate','terms']
  OR evidence->'version' <> '1'::jsonb
  OR jsonb_typeof(evidence->'documentDate') <> 'string'
  OR (evidence->>'documentDate') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
  OR (evidence->>'documentDate')::date::text <> evidence->>'documentDate'
  OR (evidence->>'documentDate')::date NOT BETWEEN DATE '0001-01-01' AND DATE '9999-12-31'
 THEN RETURN false; END IF;
 IF evidence->>'mode' = 'not_applicable' THEN
  RETURN evidence->>'documentKind' = 'expense_report' AND evidence->>'source' = 'not_applicable'
   AND evidence->'terms' = 'null'::jsonb
   AND (evidence->'partyId' = 'null'::jsonb OR
    (jsonb_typeof(evidence->'partyId') = 'string' AND
     (evidence->>'partyId') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'));
 END IF;
 IF evidence->>'documentKind' <> 'vendor_bill' OR jsonb_typeof(evidence->'partyId') <> 'string'
  OR (evidence->>'partyId') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
 THEN RETURN false; END IF;
 IF evidence->>'source' = 'none' THEN
  RETURN evidence->>'mode' = 'no_discount' AND evidence->'terms' = 'null'::jsonb;
 END IF;
 terms := evidence->'terms';
 IF evidence->>'source' NOT IN ('vendor','company') OR jsonb_typeof(terms) <> 'object'
  OR (SELECT count(*) FROM jsonb_object_keys(terms)) <> 6
  OR NOT terms ?& ARRAY['id','name','netDays','discountDays','discountPercent','revisionHash']
  OR jsonb_typeof(terms->'id') <> 'string'
  OR (terms->>'id') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
  OR jsonb_typeof(terms->'name') <> 'string' OR btrim(terms->>'name') = ''
  OR jsonb_typeof(terms->'revisionHash') <> 'string' OR (terms->>'revisionHash') !~ '^[a-f0-9]{64}$'
  OR jsonb_typeof(terms->'netDays') <> 'number' OR (terms->>'netDays') !~ '^[0-9]+$'
  OR (terms->>'netDays')::numeric > 3652058
 THEN RETURN false; END IF;
 IF (evidence->>'documentDate')::date + (terms->>'netDays')::integer > DATE '9999-12-31' THEN RETURN false; END IF;
 IF terms->'discountDays' <> 'null'::jsonb AND
  (jsonb_typeof(terms->'discountDays') <> 'number' OR (terms->>'discountDays') !~ '^[0-9]+$'
   OR (terms->>'discountDays')::numeric > 3652058)
 THEN RETURN false; END IF;
 IF terms->'discountPercent' = 'null'::jsonb THEN percentage := 0;
 ELSE
  IF jsonb_typeof(terms->'discountPercent') <> 'string'
   OR (terms->>'discountPercent') !~ '^[0-9]{1,15}(\.[0-9]{1,4})?$' THEN RETURN false; END IF;
  percentage := (terms->>'discountPercent')::numeric;
  IF percentage < 0 OR percentage >= 100 THEN RETURN false; END IF;
 END IF;
 has_discount := percentage > 0;
 IF has_discount AND terms->'discountDays' = 'null'::jsonb THEN RETURN false; END IF;
 IF has_discount AND (evidence->>'documentDate')::date + (terms->>'discountDays')::integer > DATE '9999-12-31' THEN RETURN false; END IF;
 RETURN evidence->>'mode' = CASE WHEN has_discount THEN 'discount' ELSE 'no_discount' END;
EXCEPTION WHEN OTHERS THEN RETURN false;
END;
$_$;


--
-- Name: documents; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.documents (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    kind text NOT NULL,
    document_number text NOT NULL,
    party_id uuid,
    document_date date NOT NULL,
    posting_date date,
    due_date date,
    currency text NOT NULL,
    fx_rate numeric(19,10) DEFAULT '1'::numeric NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    posted_entry_id uuid,
    voided_at timestamp with time zone,
    subtotal numeric(19,4) DEFAULT '0'::numeric NOT NULL,
    tax_total numeric(19,4) DEFAULT '0'::numeric NOT NULL,
    total numeric(19,4) DEFAULT '0'::numeric NOT NULL,
    department_id uuid,
    project_id uuid,
    location_id uuid,
    class_id uuid,
    payment_card_id uuid,
    billing_method text,
    is_final_invoice boolean DEFAULT false NOT NULL,
    reference_number text,
    internal_notes text,
    payment_hold_reason text,
    expected_pay_date date,
    memo text,
    custom jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    open_balance numeric(19,4),
    subsidiary_id uuid,
    extra_dims jsonb DEFAULT '{}'::jsonb NOT NULL,
    subscription_id uuid,
    posting_period_id uuid,
    submitted_by uuid,
    submitted_at timestamp with time zone,
    voided_by uuid,
    void_reason text,
    void_requested_at timestamp with time zone,
    void_requested_by uuid,
    void_reversal_date date,
    reversal_entry_id uuid,
    revision_seq bigint DEFAULT 0 NOT NULL,
    ship_to_country text,
    ship_to_region text,
    idempotency_key text,
    void_reversal_period_id uuid,
    sales_rep_id uuid,
    sales_team_id uuid,
    external_ref text,
    external_source text,
    source_channel_id uuid,
    work_completed_on date,
    internal_billing_rule_id uuid,
    accounting_book_id uuid,
    journal_mode text DEFAULT 'monetary'::text NOT NULL,
    journal_reverse_on date,
    journal_fx_rate_explicit boolean DEFAULT false NOT NULL,
    payment_terms_snapshot jsonb,
    document_fx_rate_evidence jsonb,
    CONSTRAINT documents_accounting_book_journal_only CHECK (((accounting_book_id IS NULL) OR (kind = 'journal'::text))),
    CONSTRAINT documents_external_ref_nonblank CHECK (((external_ref IS NULL) OR (length(btrim(external_ref)) > 0))),
    CONSTRAINT documents_external_ref_source_pair CHECK (((external_ref IS NULL) = (external_source IS NULL))),
    CONSTRAINT documents_external_source_nonblank CHECK (((external_source IS NULL) OR (length(btrim(external_source)) > 0))),
    CONSTRAINT documents_fx_rate_evidence_bound CHECK (((document_fx_rate_evidence IS NULL) OR COALESCE(((kind = ANY (ARRAY['customer_invoice'::text, 'vendor_bill'::text, 'customer_credit'::text, 'vendor_credit'::text, 'customer_payment'::text, 'vendor_payment'::text])) AND (jsonb_typeof(document_fx_rate_evidence) = 'object'::text) AND (document_fx_rate_evidence ?& ARRAY['version'::text, 'rate'::text, 'source'::text, 'reason'::text, 'fromCurrency'::text, 'toCurrency'::text, 'rateDate'::text, 'subsidiaryId'::text]) AND ((document_fx_rate_evidence - ARRAY['version'::text, 'rate'::text, 'source'::text, 'reason'::text, 'fromCurrency'::text, 'toCurrency'::text, 'rateDate'::text, 'subsidiaryId'::text]) = '{}'::jsonb) AND ((document_fx_rate_evidence -> 'version'::text) = '1'::jsonb) AND (jsonb_typeof((document_fx_rate_evidence -> 'rate'::text)) = 'string'::text) AND (jsonb_typeof((document_fx_rate_evidence -> 'source'::text)) = 'string'::text) AND (jsonb_typeof((document_fx_rate_evidence -> 'reason'::text)) = 'string'::text) AND (jsonb_typeof((document_fx_rate_evidence -> 'fromCurrency'::text)) = 'string'::text) AND (jsonb_typeof((document_fx_rate_evidence -> 'toCurrency'::text)) = 'string'::text) AND (jsonb_typeof((document_fx_rate_evidence -> 'rateDate'::text)) = 'string'::text) AND (jsonb_typeof((document_fx_rate_evidence -> 'subsidiaryId'::text)) = 'string'::text) AND
CASE
    WHEN ((document_fx_rate_evidence ->> 'rate'::text) ~ '^[0-9]{1,9}(\.[0-9]{1,10})?$'::text) THEN ((((document_fx_rate_evidence ->> 'rate'::text))::numeric > (0)::numeric) AND (fx_rate = ((document_fx_rate_evidence ->> 'rate'::text))::numeric))
    ELSE false
END AND ((char_length((document_fx_rate_evidence ->> 'source'::text)) >= 1) AND (char_length((document_fx_rate_evidence ->> 'source'::text)) <= 120)) AND ((document_fx_rate_evidence ->> 'source'::text) = btrim((document_fx_rate_evidence ->> 'source'::text))) AND ((char_length((document_fx_rate_evidence ->> 'reason'::text)) >= 8) AND (char_length((document_fx_rate_evidence ->> 'reason'::text)) <= 500)) AND ((document_fx_rate_evidence ->> 'reason'::text) = btrim((document_fx_rate_evidence ->> 'reason'::text))) AND ((document_fx_rate_evidence ->> 'fromCurrency'::text) ~ '^[A-Z]{3}$'::text) AND ((document_fx_rate_evidence ->> 'toCurrency'::text) ~ '^[A-Z]{3}$'::text) AND ((document_fx_rate_evidence ->> 'fromCurrency'::text) <> (document_fx_rate_evidence ->> 'toCurrency'::text)) AND (currency = (document_fx_rate_evidence ->> 'fromCurrency'::text)) AND ((document_fx_rate_evidence ->> 'rateDate'::text) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'::text) AND (subsidiary_id IS NOT NULL) AND ((subsidiary_id)::text = (document_fx_rate_evidence ->> 'subsidiaryId'::text))), false))),
    CONSTRAINT documents_internal_billing_rule_kind CHECK (((internal_billing_rule_id IS NULL) OR (kind = 'internal_billing'::text))),
    CONSTRAINT documents_journal_mode_check CHECK ((journal_mode = ANY (ARRAY['monetary'::text, 'statistical'::text, 'currency_adjustment'::text]))),
    CONSTRAINT documents_no_field_ticket_custom CHECK ((NOT (custom ? 'fieldTicket'::text))),
    CONSTRAINT documents_payment_terms_snapshot_shape CHECK ((public.document_payment_terms_snapshot_valid(payment_terms_snapshot) IS TRUE)),
    CONSTRAINT documents_posted_period_required CHECK (((status <> 'posted'::text) OR ((posted_entry_id IS NOT NULL) AND (posting_period_id IS NOT NULL)))),
    CONSTRAINT documents_void_reason_required CHECK (((status <> 'voided'::text) OR ((voided_at IS NOT NULL) AND (voided_by IS NOT NULL) AND (void_reason IS NOT NULL) AND ((length(btrim(void_reason)) >= 5) AND (length(btrim(void_reason)) <= 500)) AND ((posted_entry_id IS NULL) OR (reversal_entry_id IS NOT NULL))))),
    CONSTRAINT documents_void_request_evidence CHECK ((((void_requested_at IS NULL) AND (void_requested_by IS NULL) AND (void_reversal_date IS NULL)) OR ((void_requested_at IS NOT NULL) AND (void_requested_by IS NOT NULL) AND (void_reversal_date IS NOT NULL) AND (void_reason IS NOT NULL) AND ((length(btrim(void_reason)) >= 5) AND (length(btrim(void_reason)) <= 500)) AND (status = ANY (ARRAY['approved'::text, 'posted'::text])))))
);

ALTER TABLE ONLY public.documents FORCE ROW LEVEL SECURITY;


--
-- Name: COLUMN documents.payment_card_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documents.payment_card_id IS 'Funding card: the card_charge/refund instrument, or the single corporate card backing the company_paid and personal lines of an expense_report (one card per report)';


--
-- Name: COLUMN documents.ship_to_country; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documents.ship_to_country IS 'Frozen sale destination country: the jurisdiction the document was taxed/posted with. Stamped by the posting kernel for customer invoices/credits; the nexus ledger reads this (then quote evidence) and reports the rest as unattributed — never the live address book.';


--
-- Name: COLUMN documents.ship_to_region; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documents.ship_to_region IS 'Frozen sale destination region/state: see ship_to_country.';


--
-- Name: COLUMN documents.work_completed_on; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documents.work_completed_on IS 'Date the work an invoice charges for was completed. Generated invoices take the latest work date of their source lines.';


--
-- Name: COLUMN documents.accounting_book_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documents.accounting_book_id IS 'Book-specific journal target. Null: the journal posts to the primary book and replicates into full books. Set: the journal posts to that book only.';


--
-- Name: COLUMN documents.payment_terms_snapshot; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documents.payment_terms_snapshot IS 'Native posting-time vendor payment terms and economic revision. Null means no retained authority; automatic discount capture refuses it.';


--
-- Name: COLUMN documents.document_fx_rate_evidence; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documents.document_fx_rate_evidence IS 'Operator-recorded document-to-functional exchange rate with source, reason, currencies, rate date and owning legal entity. Null: the rate is resolved from the organization''s exchange rates at posting.';


--
-- Name: document_balance_clone_child_matches(public.documents, regclass, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_balance_clone_child_matches(parent public.documents, relation regclass, candidate jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE target record; source_entry uuid; original jsonb; expected jsonb;
 column_row record; policy_transform text; source_table_name text;
BEGIN
 IF NOT public.openbooks_clone_authority() OR relation NOT IN (
  'public.journal_lines'::regclass,'public.applications'::regclass)
  OR (parent).org_id IS DISTINCT FROM (candidate->>'org_id')::uuid
  OR NOT public.sales_document_clone_matches(parent) THEN RETURN false; END IF;
 SELECT o.id,o.sandbox_of,o.sandbox_seed,s.masked INTO target FROM public.orgs o
 JOIN public.sandboxes s ON s.org_id=o.id AND s.production_org_id=o.sandbox_of
 JOIN public.orgs source ON source.id=o.sandbox_of
 WHERE o.id=(parent).org_id AND o.env_kind='sandbox' AND o.sandbox_seed IS NOT NULL;
 IF NOT FOUND THEN RETURN false; END IF;
 SELECT d.posted_entry_id INTO source_entry FROM public.documents d
 WHERE d.org_id=target.sandbox_of AND d.kind=(parent).kind
  AND d.document_number=(parent).document_number
  AND public.ob_rebase(d.id,target.sandbox_seed)=(parent).id;
 IF source_entry IS NULL THEN RETURN false; END IF;
 IF relation='public.journal_lines'::regclass THEN
  source_table_name:='journal_lines';
  SELECT to_jsonb(l) INTO original FROM public.journal_lines l
  WHERE l.org_id=target.sandbox_of AND l.entry_id=source_entry
   AND l.line_number=(candidate->>'line_number')::integer
   AND public.ob_rebase(l.id,target.sandbox_seed)=(candidate->>'id')::uuid;
 ELSE
  source_table_name:='applications';
  SELECT to_jsonb(a) INTO original FROM public.applications a
  WHERE a.org_id=target.sandbox_of
   AND (a.from_line_id IN (SELECT l.id FROM public.journal_lines l WHERE l.org_id=target.sandbox_of AND l.entry_id=source_entry)
     OR a.to_line_id IN (SELECT l.id FROM public.journal_lines l WHERE l.org_id=target.sandbox_of AND l.entry_id=source_entry))
   AND public.ob_rebase(a.id,target.sandbox_seed)=(candidate->>'id')::uuid;
 END IF;
 IF original IS NULL THEN RETURN false; END IF;
 expected:=original;
 FOR column_row IN SELECT attname,atttypid,attnotnull FROM pg_catalog.pg_attribute
  WHERE attrelid=relation AND attnum>0 AND NOT attisdropped LOOP
  IF column_row.attname='org_id' THEN
   expected:=jsonb_set(expected,ARRAY[column_row.attname],to_jsonb(target.id));
  ELSIF column_row.atttypid='uuid'::regtype
   AND (column_row.attname='id' OR right(column_row.attname,3)='_id')
   AND jsonb_typeof(original->column_row.attname)='string' THEN
   expected:=jsonb_set(expected,ARRAY[column_row.attname],to_jsonb(public.ob_rebase((original->>column_row.attname)::uuid,target.sandbox_seed)));
  END IF;
  -- Masking may remove free-form text and custom payloads, never financial
  -- values, dates or identities. Custom JSON is removed by default in masked
  -- copies; a declared value-removing policy must produce the same result.
  IF target.masked AND column_row.attname IN ('memo','custom') THEN
   SELECT p.transform INTO policy_transform FROM public.masking_policies p
   WHERE p.org_id=target.sandbox_of AND p.table_name=source_table_name
    AND p.column_name=column_row.attname AND p.is_active;
   IF column_row.attname='custom' AND policy_transform IS NULL THEN
    expected:=jsonb_set(expected,ARRAY[column_row.attname],'{}'::jsonb);
   ELSIF policy_transform='null_out' THEN
    expected:=jsonb_set(expected,ARRAY[column_row.attname],
     CASE WHEN column_row.attnotnull AND column_row.atttypid='jsonb'::regtype THEN '{}'::jsonb ELSE 'null'::jsonb END);
   ELSIF policy_transform='redact' AND original->column_row.attname<>'null'::jsonb THEN
    expected:=jsonb_set(expected,ARRAY[column_row.attname],to_jsonb('REDACTED'::text));
   ELSIF policy_transform='hash' AND original->column_row.attname<>'null'::jsonb THEN
    expected:=jsonb_set(expected,ARRAY[column_row.attname],to_jsonb(md5(original->>column_row.attname)));
   END IF;
  END IF;
 END LOOP;
 RETURN candidate=expected;
END $$;


