--
-- Name: document_correction_lineage_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_correction_lineage_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  replacement record;
  source record;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF tg_op <> 'INSERT' THEN
    IF old.link_type = 'reverses'
       AND NOT openbooks_sandbox_wipe_allowed(old.org_id)
    THEN
      RAISE EXCEPTION
        'document correction lineage is immutable; retain the source and replacement';
    END IF;
    RETURN coalesce(new, old);
  END IF;

  IF new.link_type <> 'reverses' THEN
    RETURN new;
  END IF;

  SELECT id, org_id, kind, status, posted_entry_id
    INTO replacement
    FROM documents
   WHERE id = new.from_document_id
   FOR KEY SHARE;
  SELECT id, org_id, kind, status, posted_entry_id
    INTO source
    FROM documents
   WHERE id = new.to_document_id
   FOR KEY SHARE;

  IF replacement.id IS NULL OR source.id IS NULL
     OR replacement.org_id <> new.org_id
     OR source.org_id <> new.org_id
  THEN
    RAISE EXCEPTION
      'a correction source and replacement must belong to the same tenant';
  END IF;
  IF replacement.id = source.id THEN
    RAISE EXCEPTION 'a document cannot correct itself';
  END IF;
  IF replacement.kind <> source.kind THEN
    RAISE EXCEPTION
      'a correction must retain the source document kind';
  END IF;
  IF source.status NOT IN ('posted', 'voided') THEN
    RAISE EXCEPTION
      'only a posted or already-voided document can be the source of a correction';
  END IF;
  IF replacement.status <> 'draft'
     OR replacement.posted_entry_id IS NOT NULL
  THEN
    RAISE EXCEPTION
      'correction lineage must be established while the replacement is an unposted draft';
  END IF;
  RETURN new;
END
$$;


--
-- Name: document_fx_rate_evidence_clone_matches(public.documents); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_fx_rate_evidence_clone_matches(candidate public.documents) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
 SELECT EXISTS (
  SELECT 1 FROM public.orgs target
   JOIN public.sandboxes control ON control.org_id = target.id AND control.production_org_id = target.sandbox_of
   JOIN public.orgs source ON source.id = target.sandbox_of
   JOIN public.documents original ON original.org_id = source.id
  WHERE public.openbooks_clone_authority() AND target.id = (candidate).org_id
   AND target.env_kind = 'sandbox' AND target.sandbox_seed IS NOT NULL
   AND original.kind = (candidate).kind AND original.document_number = (candidate).document_number
   AND public.ob_rebase(original.id, target.sandbox_seed) = (candidate).id
   AND public.ob_rebase(original.subsidiary_id, target.sandbox_seed) IS NOT DISTINCT FROM (candidate).subsidiary_id
   AND (original.currency, original.fx_rate) IS NOT DISTINCT FROM ((candidate).currency, (candidate).fx_rate)
   AND public.document_fx_rate_evidence_for_clone(original.document_fx_rate_evidence, target.sandbox_seed, control.masked)
       IS NOT DISTINCT FROM (candidate).document_fx_rate_evidence
 );
$$;


--
-- Name: document_fx_rate_evidence_for_clone(jsonb, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_fx_rate_evidence_for_clone(evidence jsonb, seed uuid, masked boolean) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
 SELECT CASE WHEN evidence IS NULL THEN NULL
  ELSE evidence
   || jsonb_build_object('subsidiaryId', public.ob_rebase((evidence->>'subsidiaryId')::uuid, seed)::text)
   || CASE WHEN masked IS TRUE THEN jsonb_build_object('source', 'REDACTED', 'reason', 'REDACTED') ELSE '{}'::jsonb END
  END;
$$;


--
-- Name: document_fx_rate_evidence_frozen_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_fx_rate_evidence_frozen_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF OLD.status <> 'draft' AND NEW.document_fx_rate_evidence IS DISTINCT FROM OLD.document_fx_rate_evidence THEN
  RAISE EXCEPTION 'document % is % — its recorded exchange rate evidence changes only on a draft; return it to draft and record the rate again', OLD.id, OLD.status
   USING ERRCODE = '23514';
 END IF;
 RETURN NEW;
END
$$;


--
-- Name: document_fx_rate_evidence_insert_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_fx_rate_evidence_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF public.openbooks_clone_authority() AND public.document_fx_rate_evidence_clone_matches(NEW) THEN
  RETURN NEW;
 END IF;
 RAISE EXCEPTION 'Explicit exchange rate evidence is recorded on a draft through the document editor; a copied document must retain its source document''s exact evidence.'
  USING ERRCODE = '23514';
END
$$;


--
-- Name: document_line_immutability_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_line_immutability_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_old_document_id uuid;
  v_new_document_id uuid;
  v_old_org_id uuid;
  v_new_org_id uuid;
  v_old_found boolean := false;
  v_new_found boolean := false;
  v_old_status text;
  v_new_status text;
  v_old_kind text;
  v_new_kind text;
  v_parent record;
  v_sandbox_wipe boolean;
  v_trusted_replay boolean;
  v_payroll_commit text;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  v_old_document_id := CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN OLD.document_id ELSE NULL END;
  v_new_document_id := CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN NEW.document_id ELSE NULL END;
  v_old_org_id := CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN OLD.org_id ELSE NULL END;
  v_new_org_id := CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN NEW.org_id ELSE NULL END;

  -- Sandbox teardown is an explicit, tenant-scoped delete path. It runs before
  -- parent lookup because the teardown deliberately deletes children first and
  -- may encounter a parent that was already removed by an earlier pass.
  v_sandbox_wipe :=
    TG_OP = 'DELETE'
    AND (v_old_org_id IS NULL OR public.openbooks_sandbox_wipe_allowed(v_old_org_id));
  IF v_sandbox_wipe THEN
    RETURN OLD;
  END IF;

  -- Trusted replay runs before the parent lookup (moved here in 0148): the
  -- sandbox clone copies document lines before their documents, so a
  -- legitimately absent parent must not raise for a replay caller. The
  -- authority is unchanged — paired, transaction-local migration+amend — and
  -- ordinary writers still fall through to the lookup and freeze below. The
  -- parent row lock is not load-bearing for replay: frozen posted lines admit
  -- no concurrent ordinary writer on the same document.
  v_trusted_replay :=
    coalesce(current_setting('openbooks.migration', true), 'off') = 'on'
    AND coalesce(current_setting('openbooks.amend', true), 'off') = 'on';
  IF v_trusted_replay THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  -- Lock every referenced parent in deterministic id order. The lookup uses
  -- the physical parent id first, then checks org_id explicitly so a line can
  -- never borrow a document from another tenant even while composite foreign
  -- keys are being upgraded on an older installation.
  FOR v_parent IN
    SELECT d.id, d.org_id, d.status, d.kind
      FROM public.documents d
     WHERE d.id IN (v_old_document_id, v_new_document_id)
     ORDER BY d.id
     FOR UPDATE
  LOOP
    IF v_parent.id = v_old_document_id THEN
      v_old_found := true;
      IF v_parent.org_id IS DISTINCT FROM v_old_org_id THEN
        RAISE EXCEPTION
          'document % does not exist in organization %',
          v_old_document_id, v_old_org_id
          USING ERRCODE = 'foreign_key_violation';
      END IF;
      v_old_status := v_parent.status;
      v_old_kind := v_parent.kind;
    END IF;
    IF v_parent.id = v_new_document_id THEN
      v_new_found := true;
      IF v_parent.org_id IS DISTINCT FROM v_new_org_id THEN
        RAISE EXCEPTION
          'document % does not exist in organization %',
          v_new_document_id, v_new_org_id
          USING ERRCODE = 'foreign_key_violation';
      END IF;
      v_new_status := v_parent.status;
      v_new_kind := v_parent.kind;
    END IF;
  END LOOP;

  IF v_old_document_id IS NOT NULL AND NOT v_old_found THEN
    RAISE EXCEPTION
      'document % does not exist in organization %',
      v_old_document_id, v_old_org_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF v_new_document_id IS NOT NULL AND NOT v_new_found THEN
    RAISE EXCEPTION
      'document % does not exist in organization %',
      v_new_document_id, v_new_org_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;

  -- Payroll commit on an approved pay run (migration 0145). The engine sets
  -- `openbooks.payroll_commit` to the committing run's document id inside its
  -- commit transaction only, after the approval release, the commit-time
  -- fences, and both freshness re-checks have passed. Honored solely for that
  -- document's own lines, solely while its parent is an approved pay_run, and
  -- solely for the delete+insert pair a commit performs — UPDATE stays frozen.
  v_payroll_commit := coalesce(current_setting('openbooks.payroll_commit', true), '');
  IF (TG_OP = 'DELETE' OR TG_OP = 'INSERT') AND v_payroll_commit <> '' THEN
    IF TG_OP = 'DELETE'
       AND v_old_document_id::text = v_payroll_commit
       AND v_old_kind = 'pay_run' AND v_old_status = 'approved' THEN
      RETURN OLD;
    END IF;
    IF TG_OP = 'INSERT'
       AND v_new_document_id::text = v_payroll_commit
       AND v_new_kind = 'pay_run' AND v_new_status = 'approved' THEN
      RETURN NEW;
    END IF;
  END IF;

  IF v_old_document_id IS NOT NULL AND v_old_status IS DISTINCT FROM 'draft' THEN
    RAISE EXCEPTION
      'document % is % — its lines are immutable outside draft status',
      v_old_document_id, v_old_status
      USING ERRCODE = 'object_not_in_prerequisite_state';
  END IF;
  IF v_new_document_id IS NOT NULL AND v_new_status IS DISTINCT FROM 'draft' THEN
    RAISE EXCEPTION
      'document % is % — its lines are immutable outside draft status',
      v_new_document_id, v_new_status
      USING ERRCODE = 'object_not_in_prerequisite_state';
  END IF;

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END
$$;


--
-- Name: FUNCTION document_line_immutability_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.document_line_immutability_guard() IS 'openbooks:document_line_immutability:v3 - locks the tenant-owned parent document and permits ordinary line writes only while it is draft; payroll commit may replace its own approved pay_run lines under transaction-local openbooks.payroll_commit; sandbox wipe and paired migration/amend replay are explicit trusted paths, with replay evaluated before the parent lookup so out-of-order trusted copies never trip on legitimately absent parents';


--
-- Name: document_line_tax_component_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_line_tax_component_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare v_status text;
declare v_org uuid;
begin
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  v_org := case when tg_op = 'DELETE' then old.org_id else new.org_id end;
  if tg_op = 'DELETE' and openbooks_sandbox_wipe_allowed(v_org) then return old; end if;
  select d.status into v_status
    from documents d join document_lines dl on dl.document_id = d.id
   where dl.id = case when tg_op = 'DELETE' then old.document_line_id else new.document_line_id end;
  if v_status <> 'draft'
     and coalesce(current_setting('openbooks.amend', true), 'off') <> 'on' then
    raise exception 'posted tax calculation evidence is immutable';
  end if;
  return coalesce(new, old);
end $$;


--
-- Name: document_lines_total_line_refresh(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_lines_total_line_refresh() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

    IF tg_op = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(old.org_id) THEN
        RETURN NULL;
    ELSIF tg_op = 'DELETE' THEN
        PERFORM public.refresh_document_totals_from_lines(old.document_id, old.org_id);
    ELSIF tg_op = 'UPDATE' THEN
        IF (old.document_id, old.org_id) IS DISTINCT FROM (new.document_id, new.org_id) THEN
            PERFORM public.refresh_document_totals_from_lines(old.document_id, old.org_id);
        END IF;
        PERFORM public.refresh_document_totals_from_lines(new.document_id, new.org_id);
    ELSE
        PERFORM public.refresh_document_totals_from_lines(new.document_id, new.org_id);
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: document_lines_total_line_tieout(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_lines_total_line_tieout() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

    IF tg_op = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(old.org_id) THEN
        RETURN NULL;
    ELSIF tg_op = 'DELETE' THEN
        PERFORM public.assert_document_totals_match_lines(old.document_id, old.org_id);
    ELSIF tg_op = 'UPDATE' THEN
        IF (old.document_id, old.org_id) IS DISTINCT FROM (new.document_id, new.org_id) THEN
            PERFORM public.assert_document_totals_match_lines(old.document_id, old.org_id);
        END IF;
        PERFORM public.assert_document_totals_match_lines(new.document_id, new.org_id);
    ELSE
        PERFORM public.assert_document_totals_match_lines(new.document_id, new.org_id);
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: document_open_balance_amount(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_open_balance_amount(p_org uuid, p_entry uuid, p_currency text, p_status text) RETURNS numeric
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_count bigint;
  v_valid boolean;
  v_balance numeric;
BEGIN
  IF p_status = 'voided' OR p_entry IS NULL THEN RETURN NULL; END IF;
  SELECT count(jl.id),
         bool_and(jl.currency = p_currency),
         sum(abs(jl.txn_amount)) - coalesce(sum(ap.applied), 0)
    INTO v_count, v_valid, v_balance
    FROM public.journal_lines jl
    LEFT JOIN LATERAL (
      SELECT sum(CASE WHEN a.from_line_id = jl.id
                      THEN a.source_transaction_amount
                      ELSE a.target_transaction_amount END) AS applied
        FROM public.applications a
       WHERE a.org_id = p_org AND a.unapplied_at IS NULL
         AND (a.from_line_id = jl.id OR a.to_line_id = jl.id)
    ) ap ON true
   WHERE jl.entry_id = p_entry AND jl.org_id = p_org AND jl.is_open_item;
  IF v_count = 0 THEN RETURN NULL; END IF;
  IF v_valid IS NOT TRUE THEN
    RAISE EXCEPTION 'document open-item currency mismatch: org %, posted entry %, expected currency %',
      p_org, p_entry, p_currency
      USING ERRCODE = '23514';
  END IF;
  RETURN v_balance;
END;
$$;


--
-- Name: document_payment_terms_snapshot_for_clone(jsonb, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_payment_terms_snapshot_for_clone(evidence jsonb, source_tenant uuid, source_party uuid, seed uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE result jsonb;
BEGIN
 IF evidence IS NULL THEN RETURN NULL; END IF;
 IF public.document_payment_terms_snapshot_valid(evidence) IS NOT TRUE OR seed IS NULL
  OR evidence->'partyId' IS DISTINCT FROM coalesce(to_jsonb(source_party), 'null'::jsonb) THEN
  RAISE EXCEPTION 'Cannot clone payment terms whose source document identity is missing or invalid.' USING ERRCODE='23514';
 END IF;
 IF source_party IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM public.parties WHERE org_id = source_tenant AND id = source_party
 ) THEN
  RAISE EXCEPTION 'Cannot clone payment terms whose party has no source-organization identity.' USING ERRCODE='23514';
 END IF;
 IF evidence->'terms' <> 'null'::jsonb AND NOT EXISTS (
  SELECT 1 FROM public.payment_terms WHERE org_id = source_tenant AND id = (evidence #>> '{terms,id}')::uuid
 ) THEN
  RAISE EXCEPTION 'Cannot clone retained payment terms whose policy identity is absent from the source organization.' USING ERRCODE='23514';
 END IF;
 result := jsonb_set(evidence, '{partyId}', coalesce(to_jsonb(public.ob_rebase(source_party, seed)::text), 'null'::jsonb), false);
 IF evidence->'terms' <> 'null'::jsonb THEN
  result := jsonb_set(result, '{terms,id}', to_jsonb(public.ob_rebase((evidence #>> '{terms,id}')::uuid, seed)::text), false);
 END IF;
 RETURN result;
END;
$$;


--
-- Name: document_payment_terms_snapshot_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_payment_terms_snapshot_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 -- Native financial-history cloning is an explicit paired transaction-local
 -- operation; its source evidence remains subject to the shape constraint.
 IF TG_OP = 'INSERT' AND coalesce(current_setting('openbooks.migration', true),'off') = 'on'
  AND coalesce(current_setting('openbooks.amend', true),'off') = 'on' THEN RETURN NEW; END IF;
 IF TG_OP = 'INSERT' THEN
  IF NEW.payment_terms_snapshot IS NOT NULL THEN
   RAISE EXCEPTION 'Payment terms are captured only by posting an approved document.' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
 END IF;
 IF NEW.payment_terms_snapshot IS NOT DISTINCT FROM OLD.payment_terms_snapshot THEN RETURN NEW; END IF;
 IF OLD.payment_terms_snapshot IS NOT NULL OR OLD.status <> 'approved' OR NEW.status <> 'posted' THEN
  RAISE EXCEPTION 'Posted payment terms are immutable; preserve the source and use a governed document correction.' USING ERRCODE='23514';
 END IF;
 IF NEW.payment_terms_snapshot->>'documentKind' IS DISTINCT FROM NEW.kind
  OR NEW.payment_terms_snapshot->'partyId' IS DISTINCT FROM coalesce(to_jsonb(NEW.party_id), 'null'::jsonb)
  OR NEW.payment_terms_snapshot->>'documentDate' IS DISTINCT FROM NEW.document_date::text THEN
  RAISE EXCEPTION 'Retained payment terms must belong to the posting document and vendor.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: document_supply_evidence_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_supply_evidence_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE document_state text;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF public.app_bypass_rls_active() AND coalesce(current_setting('openbooks.amend',true),'off')='on' THEN
    IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
  END IF;
  SELECT d.status INTO document_state FROM public.documents d
    WHERE d.org_id = COALESCE(NEW.org_id, OLD.org_id)
      AND d.id = COALESCE(NEW.document_id, OLD.document_id);
  IF document_state IS DISTINCT FROM 'draft' THEN
    RAISE EXCEPTION 'supply evidence is immutable once the document leaves draft; return the document to draft and recollect its evidence';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;


--
-- Name: document_tender_lifecycle_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_tender_lifecycle_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_old_document_id uuid;
  v_new_document_id uuid;
  v_old_org_id uuid;
  v_new_org_id uuid;
  v_old_found boolean := false;
  v_new_found boolean := false;
  v_old_status text;
  v_new_status text;
  v_old_kind text;
  v_new_kind text;
  v_parent record;
  v_sandbox_wipe boolean;
  v_trusted_replay boolean;
  v_mint_fill boolean;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  v_old_document_id := CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN OLD.document_id ELSE NULL END;
  v_new_document_id := CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN NEW.document_id ELSE NULL END;
  v_old_org_id := CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN OLD.org_id ELSE NULL END;
  v_new_org_id := CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN NEW.org_id ELSE NULL END;

  v_sandbox_wipe :=
    TG_OP = 'DELETE'
    AND (v_old_org_id IS NULL OR public.openbooks_sandbox_wipe_allowed(v_old_org_id));
  IF v_sandbox_wipe THEN
    RETURN OLD;
  END IF;

  FOR v_parent IN
    SELECT d.id, d.org_id, d.status, d.kind
      FROM public.documents d
     WHERE d.id IN (v_old_document_id, v_new_document_id)
     ORDER BY d.id
     FOR UPDATE
  LOOP
    IF v_parent.id = v_old_document_id THEN
      v_old_found := true;
      IF v_parent.org_id IS DISTINCT FROM v_old_org_id THEN
        RAISE EXCEPTION
          'document % does not exist in organization %',
          v_old_document_id, v_old_org_id
          USING ERRCODE = 'foreign_key_violation';
      END IF;
      v_old_status := v_parent.status;
      v_old_kind := v_parent.kind;
    END IF;
    IF v_parent.id = v_new_document_id THEN
      v_new_found := true;
      IF v_parent.org_id IS DISTINCT FROM v_new_org_id THEN
        RAISE EXCEPTION
          'document % does not exist in organization %',
          v_new_document_id, v_new_org_id
          USING ERRCODE = 'foreign_key_violation';
      END IF;
      v_new_status := v_parent.status;
      v_new_kind := v_parent.kind;
    END IF;
  END LOOP;

  IF v_old_document_id IS NOT NULL AND NOT v_old_found THEN
    RAISE EXCEPTION
      'document % does not exist in organization %',
      v_old_document_id, v_old_org_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF v_new_document_id IS NOT NULL AND NOT v_new_found THEN
    RAISE EXCEPTION
      'document % does not exist in organization %',
      v_new_document_id, v_new_org_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;

  v_trusted_replay :=
    coalesce(current_setting('openbooks.migration', true), 'off') = 'on'
    AND coalesce(current_setting('openbooks.amend', true), 'off') = 'on';
  IF v_trusted_replay THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  -- Mint-fill: the refund settle effect mints the store-credit account after
  -- posting and records it on the tender. Only this single-column fill passes
  -- on a non-draft parent; every other post-commit write is refused.
  v_mint_fill :=
    TG_OP = 'UPDATE'
    AND v_old_status IS DISTINCT FROM 'draft'
    AND OLD.kind = 'stored_value'
    AND OLD.stored_value_account_id IS NULL
    AND NEW.stored_value_account_id IS NOT NULL
    AND NEW.org_id IS NOT DISTINCT FROM OLD.org_id
    AND NEW.document_id IS NOT DISTINCT FROM OLD.document_id
    AND NEW.position IS NOT DISTINCT FROM OLD.position
    AND NEW.kind IS NOT DISTINCT FROM OLD.kind
    AND NEW.method_label IS NOT DISTINCT FROM OLD.method_label
    AND NEW.account_id IS NOT DISTINCT FROM OLD.account_id
    AND NEW.amount_minor IS NOT DISTINCT FROM OLD.amount_minor
    AND NEW.currency IS NOT DISTINCT FROM OLD.currency
    AND NEW.reference IS NOT DISTINCT FROM OLD.reference
    AND NEW.external_ref IS NOT DISTINCT FROM OLD.external_ref;
  IF v_mint_fill THEN
    RETURN NEW;
  END IF;

  IF v_old_document_id IS NOT NULL AND v_old_status IS DISTINCT FROM 'draft' THEN
    RAISE EXCEPTION
      'document % is % — its tenders are immutable outside draft status',
      v_old_document_id, v_old_status
      USING ERRCODE = 'object_not_in_prerequisite_state';
  END IF;
  IF v_new_document_id IS NOT NULL AND v_new_status IS DISTINCT FROM 'draft' THEN
    RAISE EXCEPTION
      'document % is % — its tenders are immutable outside draft status',
      v_new_document_id, v_new_status
      USING ERRCODE = 'object_not_in_prerequisite_state';
  END IF;

  -- A sale redeems an existing balance at posting, so the account must be
  -- resolved while the draft is still editable. A refund may mint the
  -- credit at settle instead.
  IF v_new_document_id IS NOT NULL AND TG_OP = 'INSERT'
     AND NEW.kind = 'stored_value' AND NEW.stored_value_account_id IS NULL
     AND v_new_kind = 'cash_sale' THEN
    RAISE EXCEPTION
      'cash sale tender % names no stored-value account — resolve the gift card or store credit being redeemed before posting',
      NEW.position
      USING ERRCODE = 'foreign_key_violation';
  END IF;

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END
$$;


--
-- Name: FUNCTION document_tender_lifecycle_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.document_tender_lifecycle_guard() IS 'openbooks:document_tender_lifecycle:v1 - locks the tenant-owned parent document and permits ordinary tender writes only while it is draft; the refund mint-fill is the only post-commit write; sandbox wipe and paired migration/amend replay are explicit trusted paths';


--
-- Name: documents_revision_monotonic(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.documents_revision_monotonic() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.updated_at = OLD.updated_at THEN
    -- A write that leaves the revision byte-identical is indistinguishable
    -- from "nothing happened" to every optimistic-concurrency holder of the
    -- previous token. Force strictly-forward motion: prefer the wall clock,
    -- falling back to one microsecond past the stored revision when several
    -- writes land inside the same microsecond or the clock stalls.
    NEW.updated_at := greatest(
      clock_timestamp(),
      OLD.updated_at + interval '1 microsecond'
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION documents_revision_monotonic(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.documents_revision_monotonic() IS 'openbooks:document_revision_monotonic:v1 - advances documents.updated_at whenever an update would repeat the stored revision, keeping optimistic-concurrency tokens unique across sub-millisecond writes';


--
-- Name: documents_total_line_tieout(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.documents_total_line_tieout() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
