    PERFORM public.assert_document_totals_match_lines(new.id, new.org_id);
    RETURN NULL;
END;
$$;


--
-- Name: drop_ship_allocation_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.drop_ship_allocation_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP<>'INSERT' THEN
    IF public.app_bypass_rls_active() AND coalesce(current_setting('openbooks.amend',true),'off')='on' THEN
      IF TG_OP='DELETE' THEN RETURN OLD; END IF;
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'agency allocations are immutable; reverse and replace the document through its controlled workflow';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.financial_changes change JOIN public.document_lines line ON line.org_id=change.org_id AND line.id=NEW.document_line_id
    JOIN public.documents document ON document.org_id=line.org_id AND document.id=line.document_id
    WHERE change.id=NEW.change_id AND change.org_id=NEW.org_id AND change.domain='sales' AND change.subject_id=NEW.sales_order_line_id AND change.status='applied'
      AND change.payload->>'controlsBeforeTransfer'='false' AND document.id=NEW.document_id AND document.kind=NEW.kind AND document.subsidiary_id=change.subsidiary_id)
    THEN RAISE EXCEPTION 'agency allocation must bind to its approved control judgment and native document'; END IF;
  RETURN NEW;
END $$;


--
-- Name: drop_ship_control_binding(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.drop_ship_control_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.domain='sales' AND NOT EXISTS(SELECT 1 FROM public.drop_ship_lines route
    JOIN public.document_lines line ON line.org_id=route.org_id AND line.id=route.sales_order_line_id
    JOIN public.documents document ON document.org_id=line.org_id AND document.id=line.document_id
    WHERE route.org_id=NEW.org_id AND route.sales_order_line_id=NEW.subject_id AND document.subsidiary_id=NEW.subsidiary_id
      AND NEW.operation='drop_ship_control_assessment' AND NEW.payload->'requiredSubsidiaryIds'=jsonb_build_array(NEW.subsidiary_id::text)
  ) THEN RAISE EXCEPTION 'control assessment must bind to its routed order line and legal entity'; END IF;
  RETURN NEW;
END $$;


--
-- Name: dunning_log_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dunning_log_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  if public.app_bypass_rls_active() then
    return coalesce(new, old);
  end if;
  if tg_op = 'DELETE' and public.openbooks_sandbox_wipe_allowed(old.org_id) then
    return old;
  end if;
  if TG_OP = 'DELETE' then
    raise exception 'dunning_log is append-only: DELETE is refused; a rung''s lifecycle moves forward through staged/sent/failed/suppressed transitions only';
  end if;
  if TG_OP = 'INSERT' then
    return new;
  end if;
  if old.status = 'sent' or old.status = 'skipped' then
    raise exception 'dunning_log % rows are terminal delivery evidence and cannot be updated; failed and suppressed rows re-arm to staged, sent rows never move', old.status;
  end if;
  if old.status = 'staged' and new.status in ('sent', 'failed', 'suppressed') then
    return new;
  end if;
  if (old.status = 'failed' or old.status = 'suppressed') and new.status = 'staged' then
    return new;
  end if;
  raise exception 'dunning_log transition % to % is refused: the send attempt may move staged to sent/failed/suppressed, and the runner may re-arm failed/suppressed to staged', old.status, new.status;
end;
$$;


--
-- Name: effective_date_ranges_overlap(date, date, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.effective_date_ranges_overlap(a_from date, a_to date, b_from date, b_to date) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  select daterange(a_from, coalesce(a_to, 'infinity'::date), '[]')
      && daterange(b_from, coalesce(b_to, 'infinity'::date), '[]')
$$;


--
-- Name: einvoice_documents_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.einvoice_documents_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 RAISE EXCEPTION 'Issued e-invoices are retained unchanged; issue a corrected invoice or credit note instead.' USING ERRCODE='23514';
END $$;


--
-- Name: employment_assignment_versions_closure_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.employment_assignment_versions_closure_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE'
     AND coalesce(current_setting('openbooks.amend', true), 'off') = 'on' THEN
    RETURN OLD;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'employment_assignment_versions: rows are never deleted; close with a superseding version'
      USING ERRCODE = '23514';
  END IF;
  IF OLD.superseded_by IS NOT NULL THEN
    RAISE EXCEPTION 'employment_assignment_versions: closed versions are immutable'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.superseded_by IS NULL AND NEW.recorded_until IS NULL
     AND NEW.closed_by_change_id IS NULL
     AND to_jsonb(NEW) - ARRAY['updated_at','updated_by']
       = to_jsonb(OLD) - ARRAY['updated_at','updated_by'] THEN
    RETURN NEW;
  END IF;
  IF NEW.superseded_by IS NULL OR NEW.recorded_until IS NULL THEN
    RAISE EXCEPTION 'employment_assignment_versions: live rows are append-only; the only allowed UPDATE is the closing transition (recorded_until + superseded_by) or a pure audit touch'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.org_id IS DISTINCT FROM OLD.org_id
     OR NEW.assignment_id IS DISTINCT FROM OLD.assignment_id
     OR NEW.employment_id IS DISTINCT FROM OLD.employment_id
     OR NEW.position_id IS DISTINCT FROM OLD.position_id
     OR NEW.version_no IS DISTINCT FROM OLD.version_no
     OR NEW.job_title IS DISTINCT FROM OLD.job_title
     OR NEW.department_id IS DISTINCT FROM OLD.department_id
     OR NEW.location_id IS DISTINCT FROM OLD.location_id
     OR NEW.fte IS DISTINCT FROM OLD.fte
     OR NEW.is_primary IS DISTINCT FROM OLD.is_primary
     OR NEW.effective_from IS DISTINCT FROM OLD.effective_from
     OR NEW.effective_to IS DISTINCT FROM OLD.effective_to
     OR NEW.recorded_at IS DISTINCT FROM OLD.recorded_at
     OR NEW.created_at IS DISTINCT FROM OLD.created_at
     OR NEW.created_by IS DISTINCT FROM OLD.created_by THEN
    RAISE EXCEPTION 'employment_assignment_versions: closure sets recorded_until + superseded_by + closed_by_change_id (plus audit touch) only'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: FUNCTION employment_assignment_versions_closure_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.employment_assignment_versions_closure_guard() IS 'openbooks:employment_assignment_versions_closure_guard:v2 - closed rows immutable; live rows accept only the closing transition or a pure audit touch; successor + evidence proven deferred by hrm_closure_evidence_guard; v2 adds position_id to the content allowlist so a closure cannot repoint the position link';


--
-- Name: employment_assignment_versions_employment_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.employment_assignment_versions_employment_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE actual_employment uuid;
BEGIN
  SELECT employment_id INTO actual_employment FROM public.employment_assignments
    WHERE id = NEW.assignment_id AND org_id = NEW.org_id;
  IF actual_employment IS NULL THEN
    RAISE EXCEPTION 'employment_assignment_versions: assignment must exist in the same organization'
      USING ERRCODE = '23514';
  END IF;
  IF actual_employment IS DISTINCT FROM NEW.employment_id THEN
    RAISE EXCEPTION 'employment_assignment_versions: employment_id must match the assignment''s employment'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: FUNCTION employment_assignment_versions_employment_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.employment_assignment_versions_employment_guard() IS 'openbooks:employment_assignment_versions_employment_guard:v1 - denormalized employment_id proven against the assignment row';


--
-- Name: employment_assignments_identity_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.employment_assignments_identity_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.org_id IS DISTINCT FROM OLD.org_id
     OR NEW.employment_id IS DISTINCT FROM OLD.employment_id THEN
    RAISE EXCEPTION 'employment_assignments: org_id and employment_id are immutable (close the slot and open a new one, never move it)'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: FUNCTION employment_assignments_identity_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.employment_assignments_identity_guard() IS 'openbooks:employment_assignments_identity_guard:v1 - stable slot identity; parent keys immutable so version provenance proofs cannot be invalidated';


--
-- Name: employment_bank_projection_authorized(public.party_bank_accounts); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.employment_bank_projection_authorized(account public.party_bank_accounts) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT 1 FROM public.hrm_employment_change_requests r
  JOIN public.worker_employments e ON e.org_id=r.org_id AND e.id=r.employment_id
  JOIN public.flow_submissions s ON s.org_id=r.org_id AND s.subject_kind='hrm_employment_change_request'
   AND s.subject_id=r.id AND s.actor_id=r.submitted_by
  WHERE r.org_id=account.org_id AND r.id=account.source_change_request_id AND r.status='approved'
   AND e.worker_party_id=account.party_id AND r.payload->>'kind'='bank_change'
   AND r.updated_by=account.approved_by AND r.submitted_by=account.submitted_by
   AND r.decision_snapshot->>'outcome'='approved'
   AND s.context->>'requestId'=r.id::text AND s.context->>'payloadDigest'=r.payload_digest
   AND s.context->'payload'=r.payload
   AND r.payload->>'bankName' IS NOT DISTINCT FROM account.bank_name
   AND r.payload->>'country' IS NOT DISTINCT FROM account.country
   AND r.payload->>'currency' IS NOT DISTINCT FROM account.currency
   AND coalesce(nullif(r.payload->'routing','null'::jsonb),'{}'::jsonb)=account.routing
   AND r.payload->>'sealedAccount'=account.account_number_encrypted
   AND r.payload->>'accountLastFour'=account.account_last_four
   AND NOT EXISTS(SELECT 1 FROM public.flow_submissions newer WHERE newer.org_id=s.org_id
    AND newer.subject_kind=s.subject_kind AND newer.subject_id=s.subject_id
    AND (newer.created_at,newer.id)>(s.created_at,s.id))
   AND ((s.policy->>'kind'='ungated' AND account.approved_by=s.actor_id
      AND public.flow_ungated_submission_authorized(r.org_id,s.subject_kind,r.id,s.actor_id))
    OR (s.policy->>'kind'='gated' AND public.flow_submission_approved(r.org_id,s.subject_kind,r.id,s.id)
      AND EXISTS(SELECT 1 FROM public.flow_gates g WHERE g.org_id=s.org_id AND s.policy->'runIds' ? g.run_id::text
       AND g.status='approved' AND g.decided_by=account.approved_by))))
$$;


--
-- Name: employment_changes_immutable_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.employment_changes_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF coalesce(current_setting('openbooks.amend', true), 'off') = 'on' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'employment_changes: evidence rows are immutable; record a new revision instead'
    USING ERRCODE = '23514';
  RETURN NULL;
END $$;


--
-- Name: FUNCTION employment_changes_immutable_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.employment_changes_immutable_guard() IS 'openbooks:employment_changes_immutable_guard:v1 - evidence immutable; closure lives on version tables';


--
-- Name: employment_changes_provenance_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.employment_changes_provenance_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE actual_employment uuid;
BEGIN
  IF NEW.assignment_id IS NOT NULL THEN
    SELECT employment_id INTO actual_employment FROM public.employment_assignments
      WHERE id = NEW.assignment_id AND org_id = NEW.org_id;
    IF actual_employment IS NULL THEN
      RAISE EXCEPTION 'employment_changes: assignment must exist in the same organization'
        USING ERRCODE = '23514';
    END IF;
    IF actual_employment IS DISTINCT FROM NEW.employment_id THEN
      RAISE EXCEPTION 'employment_changes: assignment must belong to the same employment'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  IF NEW.supersedes_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.employment_changes c
                   WHERE c.id = NEW.supersedes_id AND c.org_id = NEW.org_id
                     AND c.employment_id = NEW.employment_id) THEN
      RAISE EXCEPTION 'employment_changes: supersedes_id must name evidence for the same employment'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: FUNCTION employment_changes_provenance_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.employment_changes_provenance_guard() IS 'openbooks:employment_changes_provenance_guard:v1 - assignment and supersedes proven to the same employment';


