--
-- Name: employment_mapping_flow_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.employment_mapping_flow_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'draft' THEN RAISE EXCEPTION 'Create the exact mapping subject before native submission.'; END IF;
  RETURN NEW;
 END IF;
 IF ROW(NEW.mapping_digest,NEW.org_id,NEW.id,NEW.requested_by,NEW.created_by) IS DISTINCT FROM ROW(OLD.mapping_digest,OLD.org_id,OLD.id,OLD.requested_by,OLD.created_by) THEN
  RAISE EXCEPTION 'A mapping submission identity and exact mapping digest are immutable.';
 END IF;
 IF NEW.status IN('approved','rejected','pending_approval') AND NEW.status IS DISTINCT FROM OLD.status THEN
  IF NOT EXISTS(SELECT 1 FROM public.flow_submissions s WHERE s.org_id=NEW.org_id AND s.subject_kind='hrm_employment_migration_mapping' AND s.subject_id=NEW.id
    AND s.context->>'mappingDigest'=NEW.mapping_digest
    AND NOT EXISTS(SELECT 1 FROM public.flow_submissions newer WHERE newer.org_id=s.org_id AND newer.subject_kind=s.subject_kind
      AND newer.subject_id=s.subject_id AND (newer.created_at,newer.id)>(s.created_at,s.id))
    AND ((OLD.status='draft' AND NEW.status='pending_approval' AND s.policy->>'kind'='gated' AND s.actor_id=NEW.updated_by)
      OR (OLD.status='draft' AND NEW.status='approved' AND public.flow_ungated_submission_authorized(s.org_id,s.subject_kind,s.subject_id,NEW.updated_by))
      OR (OLD.status='pending_approval' AND EXISTS(SELECT 1 FROM public.flow_gates g JOIN public.flow_runs r ON r.org_id=g.org_id AND r.id=g.run_id
        WHERE g.org_id=s.org_id AND s.policy->'runIds' ? r.id::text AND g.status=NEW.status AND g.decided_by=NEW.updated_by
          AND r.status IN('waiting','completed') AND r.error IS NULL AND (NEW.status='rejected' OR public.flow_submission_approved(s.org_id,s.subject_kind,s.subject_id,s.id)))))) THEN
   RAISE EXCEPTION 'Release this exact mapping set through its current native Flow submission.';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: enforce_deleted_role_assignment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_deleted_role_assignment() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'UPDATE' AND
     ROW(OLD.user_id, OLD.org_id) IS NOT DISTINCT FROM ROW(NEW.user_id, NEW.org_id) THEN
    RETURN NULL;
  END IF;
  PERFORM public.assert_active_user_has_role(OLD.user_id, OLD.org_id);
  RETURN NULL;
END;
$$;


--
-- Name: enforce_payment_instruction_posting_claim(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_payment_instruction_posting_claim() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  run_status text;
  run_token uuid;
  subject_id uuid;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  subject_id := COALESCE(NEW.id, OLD.id);

  -- Sandbox teardown destroys scratch data wholesale; it never posts, and it
  -- must remain able to remove rows regardless of leftover claim state. The
  -- canonical helper checks both the caller's teardown GUC and the tenant's
  -- sandbox classification; a raw session setting is never authority, and
  -- INSERT/UPDATE must continue through the claim fence.
  IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;

  SELECT r.status, r.posting_claim_token
    INTO run_status, run_token
    FROM public.payment_runs r
   WHERE r.id = COALESCE(NEW.payment_run_id, OLD.payment_run_id)
     AND r.org_id = COALESCE(NEW.org_id, OLD.org_id);
  IF NOT FOUND THEN
    -- Orphaned rows are the foreign key's problem, not ours.
    RETURN COALESCE(NEW, OLD);
  END IF;

  -- Only a claimed (`processing`) run restricts writers: creation, cancellation,
  -- and terminal-state settlement mutate instructions of unclaimed runs freely.
  IF run_status <> 'processing' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  -- The live claim holder presents the run's current token for this transaction.
  IF run_token IS NOT NULL
     AND current_setting('openbooks.payment_run_claim', true)
         = COALESCE(NEW.payment_run_id, OLD.payment_run_id)::text || ':' || run_token::text THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  -- Without the live claim, only a settlement-style retreat may move a row,
  -- and it may change only status plus the normal audit stamps. This comparison
  -- deliberately covers every other current and future instruction column,
  -- including amount, payment_run_id, payee_bank_account_id, and
  -- payment_document_id.
  IF TG_OP = 'UPDATE'
     AND OLD.status IS DISTINCT FROM NEW.status
     AND NEW.status IN ('settled', 'returned', 'rejected')
     AND (to_jsonb(NEW) - 'status' - 'updated_at' - 'updated_by')
         = (to_jsonb(OLD) - 'status' - 'updated_at' - 'updated_by') THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION USING
    ERRCODE = 'check_violation',
    MESSAGE = 'payment instruction ' || subject_id::text ||
              ' belongs to a processing payment run; only the current posting claim may mutate it',
    DETAIL = 'Present the live lease as openbooks.payment_run_claim = <runId>:<postingClaimToken> '
             || 'inside the writing transaction.',
    HINT = 'The claim was recovered, retired, or never taken; re-claim the run before writing its instructions.';
END;
$$;


--
-- Name: FUNCTION enforce_payment_instruction_posting_claim(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enforce_payment_instruction_posting_claim() IS 'Rejects payment-instruction mutations on a processing run unless the writing transaction presents that run''s current posting-claim token via openbooks.payment_run_claim; settlement-style lifecycle retreats (settled/returned/rejected) remain open to the bank-outcome writer only when every other instruction field is unchanged.';


--
-- Name: enforce_user_active_role_assignment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_user_active_role_assignment() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM assert_active_user_has_role(NEW.id, NEW.org_id);
  RETURN NULL;
END;
$$;


--
-- Name: entitlement_ledger_append_only_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.entitlement_ledger_append_only_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  if tg_op = 'UPDATE' then
    raise exception
      'entitlement_ledger is append-only; correct a balance with an adjustment movement';
  end if;
  if openbooks_sandbox_wipe_allowed(old.org_id) then
    return old;
  end if;
  if old.pay_run_document_id is not null and exists (
    select 1 from pay_runs r
     where r.document_id = old.pay_run_document_id
       and r.run_status <> 'committed'
  ) then
    return old;
  end if;
  if old.kind = 'opening' and old.pay_run_document_id is null then
    if exists (
      select 1 from pay_stubs s
        join pay_runs r on r.document_id = s.pay_run_document_id and r.org_id = s.org_id
       where s.org_id = old.org_id
         and s.employee_party_id = old.employee_party_id
         and r.run_status = 'committed'
         and s.pay_date >= old.movement_date
    ) then
      raise exception
        'entitlement_ledger opening carry-in has already been consumed by a committed pay run; void that run before changing it';
    end if;
    return old;
  end if;
  raise exception
    'entitlement_ledger movements cannot be deleted once their pay run is committed';
end $$;


--
-- Name: entitlement_program_binding_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.entitlement_program_binding_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF ROW(NEW.unit,NEW.direction) IS DISTINCT FROM ROW(OLD.unit,OLD.direction)
  AND EXISTS(SELECT 1 FROM public.entitlement_ledger WHERE org_id=OLD.org_id AND plan_id=OLD.id) THEN
  RAISE EXCEPTION 'A program with ledger history cannot change its balance unit or direction; create a separate program.' USING ERRCODE='23514';
 END IF;
 IF NEW.system_key IS DISTINCT FROM OLD.system_key AND (
  EXISTS(SELECT 1 FROM public.payroll_vacation_terms WHERE org_id=OLD.org_id AND plan_id=OLD.id)
  OR EXISTS(SELECT 1 FROM public.entitlement_ledger WHERE org_id=OLD.org_id AND plan_id=OLD.id)) THEN
  RAISE EXCEPTION 'A program with employee terms or ledger history cannot change its engine binding; create a separate program.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: equipment_fixed_asset_link_immutability_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.equipment_fixed_asset_link_immutability_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Initial capitalization is NULL -> asset and remains allowed.  Repeating
  -- the same value is a no-op.  Since no controlled reversal/de-capitalization
  -- path exists, every other change would disconnect audited asset history and
  -- is rejected at the storage boundary for all writers.  The repository's
  -- explicit sandbox teardown is the one controlled exception: it removes the
  -- whole tenant and its evidence under openbooks.sandbox_wipe.
  IF public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN NEW;
  END IF;
  IF OLD.fixed_asset_id IS NOT NULL
     AND NEW.fixed_asset_id IS DISTINCT FROM OLD.fixed_asset_id THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'equipment unit fixed-asset link is immutable after capitalization',
      HINT = 'A controlled de-capitalization/reversal lifecycle must be recorded before replacing or clearing this link.';
  END IF;

  RETURN NEW;
END
$$;


--
-- Name: FUNCTION equipment_fixed_asset_link_immutability_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.equipment_fixed_asset_link_immutability_guard() IS 'openbooks:equipment_capitalization_concurrency:v1 - permits the first NULL-to-asset link and rejects replacement/clearing until a controlled reversal lifecycle exists';


--
-- Name: equity_action_flow_decision_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.equity_action_flow_decision_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF NEW.status='withdrawn' AND NEW.status IS DISTINCT FROM OLD.status THEN
  IF OLD.status<>'pending_approval' OR NEW.decided_by IS DISTINCT FROM OLD.requested_by
   OR NEW.decided_at IS NULL OR NEW.decision_comment IS NULL OR length(btrim(NEW.decision_comment)) NOT BETWEEN 5 AND 2000
   OR NOT EXISTS(SELECT 1 FROM public.flow_submissions s WHERE s.org_id=OLD.org_id
      AND s.subject_kind='equity_action' AND s.subject_id=OLD.id AND s.actor_id=OLD.requested_by
      AND s.policy->>'kind'='gated')
   OR NOT EXISTS(SELECT 1 FROM public.flow_runs r WHERE r.org_id=OLD.org_id AND r.subject_kind='equity_action'
      AND r.subject_id=OLD.id AND r.status='cancelled' AND r.updated_by=NEW.decided_by
      AND r.context #>> '{submissionPolicy,flowId}'=r.flow_id::text)
   OR EXISTS(SELECT 1 FROM public.flow_runs r WHERE r.org_id=OLD.org_id AND r.subject_kind='equity_action'
      AND r.subject_id=OLD.id AND r.status IN('running','waiting'))
   OR EXISTS(SELECT 1 FROM public.flow_gates g WHERE g.org_id=OLD.org_id AND g.subject_kind='equity_action'
      AND g.subject_id=OLD.id AND g.status IN('pending','escalated')) THEN
   RAISE EXCEPTION 'Only the requester may withdraw the pending equity action after cancelling its native Flow gates.' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
 END IF;
 IF NEW.decided_by IS NULL OR NEW.status=OLD.status THEN RETURN NEW; END IF;
 IF NOT EXISTS(SELECT 1 FROM flow_gates g JOIN flow_runs r ON r.org_id=g.org_id AND r.id=g.run_id
   WHERE g.org_id=NEW.org_id AND g.subject_kind='equity_action' AND g.subject_id=NEW.id
     AND g.status=CASE WHEN NEW.status='rejected' THEN 'rejected' ELSE 'approved' END
     AND g.decided_by=NEW.decided_by AND g.decided_at IS NOT NULL
     AND r.context->'submissionPolicy'->>'flowId'=r.flow_id::text
     AND (NEW.decided_by<>NEW.requested_by OR EXISTS(
       SELECT 1 FROM jsonb_array_elements(r.context->'submissionPolicy'->'graph'->'nodes') node
       WHERE node->>'id'=g.node_id AND node->'data'->>'kind'='gate'
         AND node->'data'->'gate'->'preventSelfApproval'='false'::jsonb)))
   OR EXISTS(SELECT 1 FROM flow_gates g WHERE g.org_id=NEW.org_id AND g.subject_kind='equity_action'
     AND g.subject_id=NEW.id AND g.status IN('pending','escalated')) THEN
  RAISE EXCEPTION 'Equity decisions require the completed native Flow gates and their retained policy.';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: equity_action_request_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.equity_action_request_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN
  IF tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD)) OR public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'Equity action requests are retained history.' USING ERRCODE='23514';
 END IF;
 IF OLD.status <> 'pending_approval' OR NEW.status = 'pending_approval'
    OR (to_jsonb(NEW) - ARRAY['status','released_without_approval','decided_by','decided_at','decision_comment','result','applied_at'])
       <> (to_jsonb(OLD) - ARRAY['status','released_without_approval','decided_by','decided_at','decision_comment','result','applied_at']) THEN
  RAISE EXCEPTION 'An equity action request is decided once, from pending approval to applied or rejected.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: equity_attribute_copied_instrument_lines(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.equity_attribute_copied_instrument_lines(p_org uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE recorded integer;
BEGIN
 INSERT INTO equity_instrument_line_attributions (org_id, subsidiary_id, journal_entry_id, journal_line_id, security_id, role, recorded_identity, reason)
 SELECT resolved.org_id, resolved.subsidiary_id, resolved.entry_id, resolved.line_id, resolved.security_id, resolved.role, resolved.identity,
        'The line was copied from another environment under its source identity; the copy chain resolves it to this security.'
   FROM (
    SELECT l.org_id, e.subsidiary_id, e.id AS entry_id, l.id AS line_id, l.custom->>'equityRole' AS role, l.custom->>'equitySecurityId' AS identity,
           public.equity_copied_security(l.org_id, (l.custom->>'equitySecurityId')::uuid) AS security_id
      FROM journal_entries e
      JOIN journal_lines l ON l.org_id = e.org_id AND l.entry_id = e.id
     WHERE e.org_id = p_org AND e.origin = 'equity'
       AND (l.custom->>'equitySecurityId') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
       AND l.custom->>'equityRole' IN ('deposit', 'interest')
       AND NOT EXISTS (SELECT 1 FROM equity_securities own WHERE own.org_id = l.org_id AND own.id = (l.custom->>'equitySecurityId')::uuid)
       AND NOT EXISTS (SELECT 1 FROM equity_instrument_line_attributions a WHERE a.org_id = l.org_id AND a.journal_line_id = l.id)
   ) resolved
   JOIN equity_securities s ON s.org_id = resolved.org_id AND s.id = resolved.security_id AND s.subsidiary_id = resolved.subsidiary_id;
 GET DIAGNOSTICS recorded = ROW_COUNT;
 RETURN recorded;
END $_$;


--
-- Name: equity_copied_security(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.equity_copied_security(p_org uuid, p_identity uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE seeds uuid[] := '{}'; current_org uuid := p_org; source_org uuid; seed uuid; depth integer; step integer; candidate uuid;
BEGIN
 FOR depth IN 1..8 LOOP
  SELECT o.sandbox_seed, o.sandbox_of INTO seed, source_org FROM orgs o WHERE o.id = current_org;
  EXIT WHEN seed IS NULL;
  seeds := seeds || seed;
  EXIT WHEN source_org IS NULL;
  current_org := source_org;
 END LOOP;
 FOR depth IN 1..coalesce(array_length(seeds, 1), 0) LOOP
  candidate := p_identity;
  FOR step IN REVERSE depth..1 LOOP
   candidate := public.ob_rebase(candidate, seeds[step]);
  END LOOP;
  IF EXISTS (SELECT 1 FROM equity_securities s WHERE s.org_id = p_org AND s.id = candidate) THEN RETURN candidate; END IF;
 END LOOP;
 RETURN NULL;
END $$;


--
-- Name: equity_position_backfill(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.equity_position_backfill(p_org uuid, p_subsidiary uuid, p_apply boolean) RETURNS TABLE(position_kind text, security_id uuid, plan_id uuid, effective_on date, shares_delta bigint, as_converted_delta bigint)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE pos record; d date; shares bigint; converted bigint; prev_shares bigint; prev_converted bigint; r record; class_id uuid;
BEGIN
 IF p_apply AND EXISTS (SELECT 1 FROM equity_position_movements m WHERE m.org_id = p_org AND m.subsidiary_id = p_subsidiary) THEN
  RAISE EXCEPTION 'The position ledger of this legal entity already carries movements.' USING ERRCODE='23514';
 END IF;
 FOR pos IN
   SELECT CASE WHEN s.kind = 'share' THEN 'share' ELSE 'award' END AS kind, s.id AS sec, NULL::uuid AS plan, s.share_class_id AS cls, s.issue_date AS start_on
     FROM equity_securities s WHERE s.org_id = p_org AND s.subsidiary_id = p_subsidiary AND s.quantity IS NOT NULL AND s.share_class_id IS NOT NULL
   UNION ALL
   SELECT 'pool', NULL::uuid, p.id, p.share_class_id, p.effective_on
     FROM equity_plans p WHERE p.org_id = p_org AND p.subsidiary_id = p_subsidiary
   ORDER BY 5, 2, 3
 LOOP
  prev_shares := 0; prev_converted := 0;
  FOR d IN
    SELECT x.on_date FROM (
      SELECT issue_date AS on_date FROM equity_securities WHERE org_id = p_org AND subsidiary_id = p_subsidiary
      UNION SELECT e.effective_on FROM equity_security_events e WHERE e.org_id = p_org AND e.subsidiary_id = p_subsidiary
      UNION SELECT sp.effective_on FROM equity_splits sp WHERE sp.org_id = p_org AND sp.subsidiary_id = p_subsidiary
      UNION SELECT a.effective_on FROM equity_class_amendments a WHERE a.org_id = p_org AND a.subsidiary_id = p_subsidiary
      UNION SELECT c.effective_on FROM equity_plan_reserve_changes c WHERE c.org_id = p_org AND c.subsidiary_id = p_subsidiary
      UNION SELECT pl.effective_on FROM equity_plans pl WHERE pl.org_id = p_org AND pl.subsidiary_id = p_subsidiary
      UNION SELECT cl.effective_on FROM equity_share_classes cl WHERE cl.org_id = p_org AND cl.subsidiary_id = p_subsidiary
    ) x WHERE x.on_date >= pos.start_on ORDER BY 1
  LOOP
   IF pos.kind = 'pool' THEN shares := public.equity_position_pool(p_org, pos.plan, d);
   ELSE shares := public.equity_position_outstanding(p_org, pos.sec, d);
   END IF;
   IF shares = 0 THEN converted := 0;
   ELSE
    SELECT * INTO r FROM public.equity_position_ratio(p_org, pos.cls, d);
    converted := public.equity_position_floor(shares * r.num, r.den);
   END IF;
   IF shares <> prev_shares OR converted <> prev_converted THEN
    position_kind := pos.kind; security_id := pos.sec; plan_id := pos.plan; effective_on := d;
    shares_delta := shares - prev_shares; as_converted_delta := converted - prev_converted;
    IF p_apply THEN
     INSERT INTO equity_position_movements (org_id, subsidiary_id, position_kind, security_id, plan_id, effective_on, shares_delta, as_converted_delta)
     VALUES (p_org, p_subsidiary, pos.kind, pos.sec, pos.plan, d, shares - prev_shares, converted - prev_converted);
    END IF;
    RETURN NEXT;
    prev_shares := shares; prev_converted := converted;
   END IF;
  END LOOP;
 END LOOP;
END $$;


--
-- Name: equity_position_conversion_class(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.equity_position_conversion_class(p_org uuid, p_class uuid, p_on date) RETURNS uuid
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE cls record; amendment record; target uuid; stated date;
BEGIN
 SELECT * INTO cls FROM equity_share_classes WHERE org_id = p_org AND id = p_class;
 IF cls.kind <> 'preferred' THEN RETURN NULL; END IF;
 target := cls.conversion_share_class_id; stated := cls.effective_on;
 FOR amendment IN SELECT * FROM equity_class_amendments WHERE org_id = p_org AND share_class_id = p_class
   AND kind = 'conversion_class' AND effective_on <= p_on ORDER BY created_at, id LOOP
  IF amendment.effective_on >= stated THEN target := amendment.conversion_share_class_id; stated := amendment.effective_on; END IF;
 END LOOP;
 RETURN target;
END $$;


--
-- Name: equity_position_floor(numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.equity_position_floor(p_num numeric, p_den numeric) RETURNS bigint
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
 SELECT (CASE WHEN p_num < 0 AND mod(p_num, p_den) <> 0 THEN div(p_num, p_den) - 1 ELSE div(p_num, p_den) END)::bigint
$$;


--
-- Name: equity_position_outstanding(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.equity_position_outstanding(p_org uuid, p_security uuid, p_on date) RETURNS bigint
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE sec record; ev record; f record; num numeric; den numeric; g numeric;
BEGIN
 SELECT * INTO sec FROM equity_securities WHERE org_id = p_org AND id = p_security;
 IF sec.quantity IS NULL OR sec.share_class_id IS NULL OR p_on < sec.issue_date THEN RETURN 0; END IF;
 IF EXISTS (SELECT 1 FROM equity_security_events WHERE org_id = p_org AND security_id = p_security AND kind = 'void' AND effective_on <= p_on) THEN RETURN 0; END IF;
 SELECT * INTO f FROM public.equity_position_split_factor(p_org, sec.share_class_id, sec.issue_date, p_on);
 num := sec.quantity * f.num; den := f.den;
 FOR ev IN SELECT e.* FROM equity_security_events e
   WHERE e.org_id = p_org AND e.security_id = p_security AND e.effective_on <= p_on AND e.quantity IS NOT NULL
     AND e.kind IN ('exercise', 'settle', 'forfeit', 'expire', 'cancel', 'repurchase', 'transfer', 'convert')
     AND NOT EXISTS (SELECT 1 FROM equity_security_events r WHERE r.org_id = p_org AND r.kind = 'reverse'
       AND r.reverses_event_id = e.id AND r.effective_on <= p_on)
     AND NOT (e.resulting_security_id IS NOT NULL AND EXISTS (SELECT 1 FROM equity_security_events v WHERE v.org_id = p_org
       AND v.kind = 'void' AND v.security_id = e.resulting_security_id AND v.effective_on <= p_on)) LOOP
  SELECT * INTO f FROM public.equity_position_split_factor(p_org, sec.share_class_id, ev.effective_on, p_on);
  num := num * f.den - ev.quantity * f.num * den;
  den := den * f.den;
  g := gcd(num, den); IF g > 1 THEN num := num / g; den := den / g; END IF;
 END LOOP;
 RETURN public.equity_position_floor(num, den);
END $$;


--
-- Name: equity_position_pool(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.equity_position_pool(p_org uuid, p_plan uuid, p_on date) RETURNS bigint
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE plan record; item record; f record; num numeric := 0; den numeric := 1; g numeric; available bigint; sign_ integer; returns_ boolean;
BEGIN
 SELECT * INTO plan FROM equity_plans WHERE org_id = p_org AND id = p_plan;
 IF p_on < plan.effective_on THEN RETURN 0; END IF;
 -- Each term: (quantity stated on a date) × splits after it, signed.
 FOR item IN
   SELECT plan.initial_reserved_shares AS quantity, plan.effective_on AS stated_on, 1 AS sign_
   UNION ALL
   SELECT c.share_delta, c.effective_on, 1 FROM equity_plan_reserve_changes c
    WHERE c.org_id = p_org AND c.plan_id = p_plan AND c.effective_on <= p_on
   UNION ALL
   -- Awards granted, unless voided by the date.
   SELECT s.quantity, s.issue_date, -1 FROM equity_securities s
    WHERE s.org_id = p_org AND s.plan_id = p_plan AND s.quantity IS NOT NULL AND s.issue_date <= p_on
      AND NOT EXISTS (SELECT 1 FROM equity_security_events v WHERE v.org_id = p_org AND v.security_id = s.id AND v.kind = 'void' AND v.effective_on <= p_on)
   UNION ALL
   -- Units returned: forfeited, cancelled and expired awards, and repurchased award shares, per the recycling terms.
   SELECT e.quantity, e.effective_on, 1 FROM equity_security_events e
     JOIN equity_securities s ON s.org_id = e.org_id AND s.id = e.security_id
    WHERE e.org_id = p_org AND e.effective_on <= p_on AND e.quantity IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM equity_security_events r WHERE r.org_id = p_org AND r.kind = 'reverse' AND r.reverses_event_id = e.id AND r.effective_on <= p_on)
      AND (
        (s.plan_id = p_plan AND s.quantity IS NOT NULL AND s.issue_date <= p_on
          AND NOT EXISTS (SELECT 1 FROM equity_security_events v WHERE v.org_id = p_org AND v.security_id = s.id AND v.kind = 'void' AND v.effective_on <= p_on)
          AND ((e.kind IN ('forfeit', 'cancel') AND plan.recycle_forfeited) OR (e.kind = 'expire' AND plan.recycle_expired)))
        OR (s.kind = 'share' AND e.kind = 'repurchase' AND plan.recycle_repurchased
          AND NOT (s.plan_id IS NOT DISTINCT FROM p_plan)
          AND EXISTS (SELECT 1 FROM equity_securities a WHERE a.org_id = p_org AND a.id = s.source_security_id
            AND a.plan_id = p_plan AND a.quantity IS NOT NULL AND a.issue_date <= p_on)))
 LOOP
  SELECT * INTO f FROM public.equity_position_split_factor(p_org, plan.share_class_id, item.stated_on, p_on);
  num := num * f.den + item.sign_ * item.quantity * f.num * den;
  den := den * f.den;
  g := gcd(num, den); IF g > 1 THEN num := num / g; den := den / g; END IF;
 END LOOP;
 available := public.equity_position_floor(num, den);
 RETURN greatest(available, 0);
END $$;


--
-- Name: equity_position_ratio(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.equity_position_ratio(p_org uuid, p_class uuid, p_on date, OUT num numeric, OUT den numeric) RETURNS record
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE cls record; amendment record; split record; price numeric; stated date; f_stated record; f_effective record; g numeric;
BEGIN
 SELECT * INTO cls FROM equity_share_classes WHERE org_id = p_org AND id = p_class;
 IF cls.kind = 'common' THEN num := 1; den := 1; RETURN; END IF;
 price := cls.initial_conversion_price; stated := cls.effective_on;
 FOR amendment IN SELECT * FROM equity_class_amendments WHERE org_id = p_org AND share_class_id = p_class
   AND kind = 'conversion_price' AND effective_on <= p_on ORDER BY created_at, id LOOP
  IF amendment.effective_on >= stated THEN price := amendment.conversion_price; stated := amendment.effective_on; END IF;
 END LOOP;
 SELECT * INTO f_stated FROM public.equity_position_split_factor(p_org, p_class, stated, p_on);
 SELECT * INTO f_effective FROM public.equity_position_split_factor(p_org, p_class, cls.effective_on, p_on);
 -- Prices carry ten places: scale them to whole numbers.
 num := (cls.original_issue_price * 10000000000) * f_stated.num * f_effective.den;
 den := (price * 10000000000) * f_stated.den * f_effective.num;
 IF cls.conversion_adjusts_for_splits THEN
  FOR split IN SELECT * FROM equity_splits WHERE org_id = p_org AND share_class_id <> p_class
    AND effective_on > stated AND effective_on <= p_on ORDER BY effective_on, created_at, id LOOP
   IF public.equity_position_conversion_class(p_org, p_class, split.effective_on) = split.share_class_id THEN
    num := num * split.ratio_numerator; den := den * split.ratio_denominator;
   END IF;
  END LOOP;
 END IF;
 g := gcd(num, den); num := num / g; den := den / g;
END $$;


--
-- Name: equity_position_split_factor(uuid, uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.equity_position_split_factor(p_org uuid, p_class uuid, p_after date, p_through date, OUT num numeric, OUT den numeric) RETURNS record
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE split record;
BEGIN
 num := 1; den := 1;
 FOR split IN SELECT ratio_numerator, ratio_denominator FROM equity_splits
   WHERE org_id = p_org AND share_class_id = p_class AND effective_on > p_after AND effective_on <= p_through LOOP
  num := num * split.ratio_numerator; den := den * split.ratio_denominator;
 END LOOP;
END $$;


--
-- Name: equity_record_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.equity_record_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD)) OR public.openbooks_sandbox_wipe_allowed(OLD.org_id)) THEN RETURN OLD; END IF;
 IF TG_OP='UPDATE' AND TG_TABLE_NAME='equity_securities' AND (to_jsonb(NEW)-'holder_party_id')=(to_jsonb(OLD)-'holder_party_id') THEN RETURN NEW; END IF;
 RAISE EXCEPTION 'Equity records are retained history. Record a void, cancellation or amendment instead.' USING ERRCODE='23514';
END $$;


--
-- Name: expense_amortization_event_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expense_amortization_event_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD))
                           OR public.openbooks_sandbox_wipe_allowed(OLD.org_id)) THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'Amortization schedule events are append-only history.'
    USING ERRCODE = '23514';
END $$;


--
-- Name: expense_amortization_line_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expense_amortization_line_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD))
       OR public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'Amortization plan lines are retained history; re-forecast or cancel the schedule instead.'
      USING ERRCODE = '23514';
  END IF;
  IF OLD.status <> 'planned' THEN
    RAISE EXCEPTION 'A % amortization line is final.', OLD.status
      USING ERRCODE = '23514';
  END IF;
  IF NEW.org_id IS DISTINCT FROM OLD.org_id
     OR NEW.schedule_id IS DISTINCT FROM OLD.schedule_id
     OR NEW.plan_revision IS DISTINCT FROM OLD.plan_revision
     OR NEW.period_start IS DISTINCT FROM OLD.period_start
     OR NEW.period_end IS DISTINCT FROM OLD.period_end
     OR NEW.weight IS DISTINCT FROM OLD.weight
     OR NEW.planned_amount IS DISTINCT FROM OLD.planned_amount
     OR NEW.destination_account_id IS DISTINCT FROM OLD.destination_account_id
     OR NEW.created_at IS DISTINCT FROM OLD.created_at
     OR NEW.created_by IS DISTINCT FROM OLD.created_by
     OR NEW.status NOT IN ('posted', 'superseded', 'cancelled') THEN
    RAISE EXCEPTION 'An amortization line keeps its period, amount and account; it can only post, be superseded or be cancelled.'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: expense_amortization_schedule_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expense_amortization_schedule_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD))
       OR public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'Amortization schedules are retained history; cancel the schedule instead of deleting it.'
      USING ERRCODE = '23514';
  END IF;
  -- A project merge re-points the project dimension across history, exactly
  -- as it re-points the posted journal lines the schedule produced.
  IF (to_jsonb(NEW) - 'project_id' - 'updated_at' - 'updated_by')
     = (to_jsonb(OLD) - 'project_id' - 'updated_at' - 'updated_by') THEN
    RETURN NEW;
  END IF;
  IF OLD.status = 'cancelled' THEN
    RAISE EXCEPTION 'Amortization schedule % is cancelled, which is final.', OLD.schedule_number
      USING ERRCODE = '23514';
  END IF;
  IF NEW.org_id IS DISTINCT FROM OLD.org_id
     OR NEW.schedule_number IS DISTINCT FROM OLD.schedule_number
     OR NEW.source_kind IS DISTINCT FROM OLD.source_kind
     OR NEW.source_document_id IS DISTINCT FROM OLD.source_document_id
     OR NEW.source_line_id IS DISTINCT FROM OLD.source_line_id
     OR NEW.source_entry_id IS DISTINCT FROM OLD.source_entry_id
     OR NEW.template_id IS DISTINCT FROM OLD.template_id
     OR NEW.method IS DISTINCT FROM OLD.method
     OR NEW.term_source IS DISTINCT FROM OLD.term_source
     OR NEW.subsidiary_id IS DISTINCT FROM OLD.subsidiary_id
     OR NEW.book_id IS DISTINCT FROM OLD.book_id
     OR NEW.currency IS DISTINCT FROM OLD.currency
     OR NEW.deferral_account_id IS DISTINCT FROM OLD.deferral_account_id
     OR NEW.created_at IS DISTINCT FROM OLD.created_at
     OR NEW.created_by IS DISTINCT FROM OLD.created_by THEN
    RAISE EXCEPTION 'Amortization schedule % keeps its source, template, entity, book, currency and deferral account.', OLD.schedule_number
      USING ERRCODE = '23514';
  END IF;
  IF OLD.status <> 'draft' AND (
       NEW.opening_amortized_amount IS DISTINCT FROM OLD.opening_amortized_amount
       OR NEW.service_start_on IS DISTINCT FROM OLD.service_start_on
       OR NEW.first_period_on IS DISTINCT FROM OLD.first_period_on
       OR NEW.period_offset IS DISTINCT FROM OLD.period_offset
       OR NEW.total_amount > OLD.total_amount
       OR NEW.reversed_amount < OLD.reversed_amount) THEN
    RAISE EXCEPTION 'Amortization schedule % changes only through its recorded events once activated.', OLD.schedule_number
      USING ERRCODE = '23514';
  END IF;
  IF NEW.revision <> OLD.revision + 1 THEN
    RAISE EXCEPTION 'Amortization schedule % changed concurrently; reload it and try again.', OLD.schedule_number
      USING ERRCODE = '40001';
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
       (OLD.status = 'draft' AND NEW.status IN ('active', 'cancelled'))
       OR (OLD.status = 'active' AND NEW.status IN ('on_hold', 'completed', 'cancelled'))
       OR (OLD.status = 'on_hold' AND NEW.status IN ('active', 'cancelled'))
       OR (OLD.status = 'completed' AND NEW.status = 'cancelled')) THEN
    RAISE EXCEPTION 'Amortization schedule % cannot move from % to %.', OLD.schedule_number, OLD.status, NEW.status
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: expense_amortization_template_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expense_amortization_template_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF (NEW.code IS DISTINCT FROM OLD.code
      OR NEW.effective_from IS DISTINCT FROM OLD.effective_from
      OR NEW.method IS DISTINCT FROM OLD.method
      OR NEW.term_source IS DISTINCT FROM OLD.term_source
      OR NEW.period_count IS DISTINCT FROM OLD.period_count
      OR NEW.percentages IS DISTINCT FROM OLD.percentages
      OR NEW.deferral_account_id IS DISTINCT FROM OLD.deferral_account_id
      OR NEW.destination_account_id IS DISTINCT FROM OLD.destination_account_id
      OR NEW.period_offset IS DISTINCT FROM OLD.period_offset
      OR NEW.rounding IS DISTINCT FROM OLD.rounding
      OR NEW.org_id IS DISTINCT FROM OLD.org_id)
     AND (EXISTS (SELECT 1 FROM public.expense_amortization_schedules s
                   WHERE s.org_id = OLD.org_id AND s.template_id = OLD.id)
          OR EXISTS (SELECT 1 FROM public.document_lines l
                       JOIN public.documents d ON d.org_id = l.org_id AND d.id = l.document_id
                      WHERE l.org_id = OLD.org_id AND l.amortization_template_id = OLD.id
                        AND d.status <> 'draft')) THEN
    RAISE EXCEPTION 'Amortization template % (effective %) is in use and its policy is fixed; add a new version with a later effective date instead.', OLD.code, OLD.effective_from
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: extension_draft_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.extension_draft_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (NEW.id,NEW.org_id,NEW.created_by,NEW.extension_key,NEW.bundle,NEW.content_hash,NEW.base_version_id,NEW.reason,NEW.created_at)
     IS DISTINCT FROM
     (OLD.id,OLD.org_id,OLD.created_by,OLD.extension_key,OLD.bundle,OLD.content_hash,OLD.base_version_id,OLD.reason,OLD.created_at) THEN
    RAISE EXCEPTION 'Extension draft revisions are immutable; create a new revision';
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status AND NOT (OLD.status='draft' AND NEW.status IN ('applied','discarded')) THEN
    RAISE EXCEPTION 'Invalid extension draft transition';
  END IF;
  IF (NEW.status='applied') IS DISTINCT FROM (NEW.applied_at IS NOT NULL) OR
     (OLD.status='applied' AND NEW.applied_at IS DISTINCT FROM OLD.applied_at) THEN
    RAISE EXCEPTION 'Invalid extension activation timestamp';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: extension_file_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.extension_file_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (NEW.id,NEW.org_id,NEW.app_id,NEW.version_id,NEW.path,NEW.kind,NEW.content_type,NEW.content,NEW.is_binary,NEW.size,NEW.created_at,NEW.created_by)
    IS DISTINCT FROM (OLD.id,OLD.org_id,OLD.app_id,OLD.version_id,OLD.path,OLD.kind,OLD.content_type,OLD.content,OLD.is_binary,OLD.size,OLD.created_at,OLD.created_by) THEN
    RAISE EXCEPTION 'Extension files are immutable; create a reviewed revision';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: extension_version_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.extension_version_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (NEW.id,NEW.org_id,NEW.app_id,NEW.version,NEW.manifest,NEW.created_at,NEW.created_by)
    IS DISTINCT FROM (OLD.id,OLD.org_id,OLD.app_id,OLD.version,OLD.manifest,OLD.created_at,OLD.created_by) THEN
    RAISE EXCEPTION 'Extension versions are immutable; create a reviewed revision';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: fair_value_used_policy_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fair_value_used_policy_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP='DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD)) OR public.openbooks_sandbox_wipe_allowed(OLD.org_id)) THEN RETURN OLD; END IF;
  IF EXISTS (SELECT 1 FROM public.performance_obligations o WHERE o.org_id=OLD.org_id AND o.allocation_basis->>'fairValuePriceId'=OLD.id::text) THEN
    IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Used fair-value policy is retained; create a successor dated policy'; END IF;
    IF ROW(NEW.org_id,NEW.item_id,NEW.currency,NEW.unit_price,NEW.low_value,NEW.high_value,NEW.effective_from,NEW.calculation_method,NEW.formula_percent,NEW.list_price,NEW.unit_cost)
       IS DISTINCT FROM ROW(OLD.org_id,OLD.item_id,OLD.currency,OLD.unit_price,OLD.low_value,OLD.high_value,OLD.effective_from,OLD.calculation_method,OLD.formula_percent,OLD.list_price,OLD.unit_cost) THEN
      RAISE EXCEPTION 'Used fair-value terms are immutable; close this window and create a successor dated policy';
    END IF;
    IF NEW.effective_to IS NOT NULL AND EXISTS (
      SELECT 1 FROM public.performance_obligations o JOIN public.document_lines dl ON dl.org_id=o.org_id AND dl.id=o.document_line_id
      JOIN public.documents d ON d.org_id=dl.org_id AND d.id=dl.document_id
      WHERE o.org_id=OLD.org_id AND o.allocation_basis->>'fairValuePriceId'=OLD.id::text AND d.document_date>NEW.effective_to
    ) THEN RAISE EXCEPTION 'A fair-value window cannot exclude an obligation already priced by it'; END IF;
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;


--
-- Name: field_ticket_evidence_integrity_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_ticket_evidence_integrity_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_row jsonb;
  v_org_id uuid;
  v_field_ticket_id uuid;
  v_evidence_id uuid;
BEGIN
  -- to_jsonb(NEW) is safe for either trigger relation.  Keep the casts here so
  -- malformed identifiers fail closed rather than being treated as absent.
  v_row := to_jsonb(NEW);
  v_org_id := (v_row ->> 'org_id')::uuid;
  v_field_ticket_id := (v_row ->> 'field_ticket_id')::uuid;

  IF NOT EXISTS (
    SELECT 1
      FROM public.field_tickets ft
     WHERE ft.document_id = v_field_ticket_id
       AND ft.org_id = v_org_id
  ) THEN
    RAISE EXCEPTION 'field ticket evidence must belong to the same organization'
      USING ERRCODE = '23514';
  END IF;

  IF TG_TABLE_NAME = 'field_ticket_signatures' THEN
    v_evidence_id := NULLIF(v_row ->> 'signature_file_id', '')::uuid;
    IF v_evidence_id IS NULL OR NOT EXISTS (
      SELECT 1
        FROM public.files f
       WHERE f.id = v_evidence_id
         AND f.org_id = v_org_id
    ) THEN
      RAISE EXCEPTION 'field ticket signature file must belong to the same organization'
        USING ERRCODE = '23514';
    END IF;
  ELSIF TG_TABLE_NAME = 'field_ticket_signature_requests' THEN
    v_evidence_id := NULLIF(v_row ->> 'email_log_id', '')::uuid;
    IF v_evidence_id IS NOT NULL AND NOT EXISTS (
      SELECT 1
        FROM public.email_log e
       WHERE e.id = v_evidence_id
         AND e.org_id = v_org_id
    ) THEN
      RAISE EXCEPTION 'field ticket signature email evidence must belong to the same organization'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END $$;


--
-- Name: field_ticket_labor_lines; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.field_ticket_labor_lines (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    snapshot_id uuid NOT NULL,
    field_ticket_id uuid NOT NULL,
    sequence integer NOT NULL,
    employee_party_id uuid NOT NULL,
    employee_name text NOT NULL,
    item_id uuid,
    item_name text,
    time_type_id uuid,
    time_type_name text NOT NULL,
    project_task_id uuid,
    project_task_name text,
    worked_on date NOT NULL,
    hours numeric(19,4) NOT NULL,
    time_entry_id uuid,
    time_entry_status text,
    cost_rate numeric(28,8),
    cost_rate_currency character varying(3),
    bill_rate numeric(28,8),
    bill_rate_currency character varying(3),
    cost_amount numeric(19,4),
    bill_amount numeric(19,4),
    source_system text,
    source_line_ref text,
    source_payload_hash text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    time_classification text NOT NULL,
    CONSTRAINT field_ticket_labor_lines_hours_nonzero CHECK ((hours <> (0)::numeric)),
    CONSTRAINT field_ticket_labor_lines_sequence_positive CHECK ((sequence > 0)),
    CONSTRAINT field_ticket_labor_lines_time_classification_valid CHECK ((time_classification = ANY (ARRAY['regular'::text, 'overtime'::text, 'double_time'::text, 'other'::text])))
);

ALTER TABLE ONLY public.field_ticket_labor_lines FORCE ROW LEVEL SECURITY;


--
-- Name: field_ticket_historical_labor_line_matches(public.field_ticket_labor_lines); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_ticket_historical_labor_line_matches(candidate public.field_ticket_labor_lines) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
 SELECT EXISTS (
  SELECT 1 FROM public.orgs target
  JOIN public.sandboxes control ON control.org_id=target.id AND control.production_org_id=target.sandbox_of
  JOIN public.orgs source ON source.id=target.sandbox_of
  JOIN public.documents copied_ticket ON copied_ticket.org_id=target.id AND copied_ticket.id=(candidate).field_ticket_id
  JOIN public.documents original_ticket ON original_ticket.org_id=source.id
   AND original_ticket.kind='field_ticket' AND original_ticket.document_number=copied_ticket.document_number
  JOIN public.field_ticket_labor_snapshots copied_snapshot ON copied_snapshot.org_id=target.id
   AND copied_snapshot.id=(candidate).snapshot_id AND copied_snapshot.field_ticket_id=copied_ticket.id
  JOIN public.field_ticket_labor_snapshots original_snapshot ON original_snapshot.org_id=source.id
   AND original_snapshot.field_ticket_id=original_ticket.id AND original_snapshot.revision=copied_snapshot.revision
  JOIN public.field_ticket_labor_lines original ON original.org_id=source.id
   AND original.snapshot_id=original_snapshot.id AND original.sequence=(candidate).sequence
  WHERE public.openbooks_clone_authority() AND target.id=(candidate).org_id
   AND target.env_kind='sandbox' AND target.sandbox_seed IS NOT NULL
   AND public.ob_rebase(original_ticket.id,target.sandbox_seed)=copied_ticket.id
   AND original_snapshot.superseded_at IS NOT NULL
   AND to_jsonb(copied_snapshot)=to_jsonb(original_snapshot)||jsonb_build_object(
    'id',public.ob_rebase(original_snapshot.id,target.sandbox_seed),'org_id',target.id,
    'field_ticket_id',public.ob_rebase(original_snapshot.field_ticket_id,target.sandbox_seed),
    'captured_by',public.ob_rebase(original_snapshot.captured_by,target.sandbox_seed),
    'superseded_by',public.ob_rebase(original_snapshot.superseded_by,target.sandbox_seed))
   AND to_jsonb(candidate)=to_jsonb(original)||jsonb_build_object(
    'id',public.ob_rebase(original.id,target.sandbox_seed),'org_id',target.id,
    'snapshot_id',public.ob_rebase(original.snapshot_id,target.sandbox_seed),
    'field_ticket_id',public.ob_rebase(original.field_ticket_id,target.sandbox_seed),
    'employee_party_id',public.ob_rebase(original.employee_party_id,target.sandbox_seed),
    'item_id',public.ob_rebase(original.item_id,target.sandbox_seed),
    'time_type_id',public.ob_rebase(original.time_type_id,target.sandbox_seed),
    'project_task_id',public.ob_rebase(original.project_task_id,target.sandbox_seed),
    'time_entry_id',public.ob_rebase(original.time_entry_id,target.sandbox_seed),
    'created_by',public.ob_rebase(original.created_by,target.sandbox_seed))
 );
$$;


--
-- Name: field_ticket_integrity_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_ticket_integrity_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if not exists (
    select 1 from documents d
     where d.id = new.document_id and d.org_id = new.org_id
       and d.kind = 'field_ticket'
  ) then
    raise exception 'field ticket header must extend a field_ticket document in the same organization'
      using errcode = '23514';
  end if;
  if new.foreman_party_id is not null and not exists (
    select 1 from parties p where p.id = new.foreman_party_id and p.org_id = new.org_id
  ) then
    raise exception 'field ticket foreman must belong to the same organization'
      using errcode = '23514';
  end if;
  if new.charge_document_id is not null and not exists (
    select 1 from documents d where d.id = new.charge_document_id and d.org_id = new.org_id
  ) then
    raise exception 'field ticket charge document must belong to the same organization'
      using errcode = '23514';
  end if;
  if new.submitted_by is not null and not exists (
    select 1 from users u where u.id = new.submitted_by and u.org_id = new.org_id
  ) then
    raise exception 'field ticket submitter must belong to the same organization'
      using errcode = '23514';
  end if;
  return new;
end $$;


--
-- Name: field_ticket_labor_line_classification_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_ticket_labor_line_classification_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  configured_classification text;
BEGIN
  IF new.time_type_id IS NOT NULL THEN
    SELECT classification
      INTO configured_classification
      FROM time_types
     WHERE id = new.time_type_id
       AND org_id = new.org_id;
  END IF;
  IF new.time_classification IS NULL THEN
    new.time_classification := coalesce(
      configured_classification,
      CASE
        WHEN lower(new.time_type_name) LIKE '%double%' THEN 'double_time'
        WHEN lower(new.time_type_name) LIKE '%over%' THEN 'overtime'
        ELSE 'regular'
      END
    );
  ELSIF configured_classification IS NOT NULL
        AND new.time_classification IS DISTINCT FROM configured_classification
  THEN
    RAISE EXCEPTION
      'field ticket labor classification must match its time type at capture'
      USING ERRCODE = '23514';
  END IF;
  RETURN new;
END
$$;


--
-- Name: field_ticket_labor_line_immutable_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_ticket_labor_line_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE'
     AND public.openbooks_sandbox_wipe_allowed(OLD.org_id)
     AND current_setting('openbooks.migration', true) = 'on'
     AND current_setting('openbooks.amend', true) = 'on'
     AND EXISTS (SELECT 1 FROM pg_catalog.pg_roles
                  WHERE rolname = current_user AND rolbypassrls)
     AND EXISTS (SELECT 1 FROM public.orgs target
                  JOIN public.sandboxes control
                    ON control.org_id = target.id
                   AND control.production_org_id = target.sandbox_of
                  JOIN public.orgs source ON source.id = target.sandbox_of
                 WHERE target.id = OLD.org_id AND target.env_kind = 'sandbox') THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'field ticket labor snapshot lines are append-only evidence';
END
$$;


--
-- Name: field_ticket_labor_line_integrity_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_ticket_labor_line_integrity_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  linked_time time_entries%ROWTYPE;
BEGIN
  IF NOT EXISTS (
    SELECT 1
      FROM field_ticket_labor_snapshots snapshot
     WHERE snapshot.id = new.snapshot_id
       AND snapshot.org_id = new.org_id
       AND snapshot.field_ticket_id = new.field_ticket_id
       AND snapshot.superseded_at IS NULL
  ) AND NOT (TG_OP = 'INSERT' AND public.field_ticket_historical_labor_line_matches(NEW)) THEN
    RAISE EXCEPTION
      'field ticket labor line must belong to the current snapshot and ticket in the same organization'
      USING ERRCODE = '23514';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM parties p
     WHERE p.id = new.employee_party_id AND p.org_id = new.org_id
  ) THEN
    RAISE EXCEPTION 'field ticket labor employee must belong to the same organization'
      USING ERRCODE = '23514';
  END IF;
  IF new.item_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM items i WHERE i.id = new.item_id AND i.org_id = new.org_id
  ) THEN
    RAISE EXCEPTION 'field ticket labor item must belong to the same organization'
      USING ERRCODE = '23514';
  END IF;
  IF new.time_type_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM time_types tt
     WHERE tt.id = new.time_type_id AND tt.org_id = new.org_id
  ) THEN
    RAISE EXCEPTION 'field ticket labor time type must belong to the same organization'
      USING ERRCODE = '23514';
  END IF;
  IF new.project_task_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
      FROM project_tasks pt
      JOIN documents d
        ON d.id = new.field_ticket_id
       AND d.org_id = pt.org_id
       AND d.project_id = pt.project_id
     WHERE pt.id = new.project_task_id
       AND pt.org_id = new.org_id
  ) THEN
    RAISE EXCEPTION 'field ticket labor task must belong to the ticket project'
      USING ERRCODE = '23514';
  END IF;
  IF new.created_by IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM users u WHERE u.id = new.created_by AND u.org_id = new.org_id
  ) THEN
    RAISE EXCEPTION 'field ticket labor line actor must belong to the same organization'
      USING ERRCODE = '23514';
  END IF;

  -- An optional link means exact atomic provenance, not a fuzzy association.
  IF new.time_entry_id IS NOT NULL THEN
    SELECT * INTO linked_time
      FROM time_entries te
     WHERE te.id = new.time_entry_id
       AND te.org_id = new.org_id;
    IF NOT FOUND
       OR linked_time.field_ticket_id IS DISTINCT FROM new.field_ticket_id
       OR linked_time.employee_party_id IS DISTINCT FROM new.employee_party_id
       OR linked_time.item_id IS DISTINCT FROM new.item_id
       OR linked_time.time_type_id IS DISTINCT FROM new.time_type_id
       OR linked_time.project_task_id IS DISTINCT FROM new.project_task_id
       OR linked_time.worked_on IS DISTINCT FROM new.worked_on
       OR linked_time.hours IS DISTINCT FROM new.hours
    THEN
      RAISE EXCEPTION
        'field ticket labor time-entry provenance must be an exact line on the same ticket'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN new;
END
$$;


--
-- Name: field_ticket_labor_snapshot_integrity_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_ticket_labor_snapshot_integrity_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
      FROM field_tickets ft
      JOIN documents d
        ON d.id = ft.document_id
       AND d.org_id = ft.org_id
       AND d.kind = 'field_ticket'
     WHERE ft.document_id = new.field_ticket_id
       AND ft.org_id = new.org_id
  ) THEN
    RAISE EXCEPTION
      'field ticket labor snapshot must belong to a Field Ticket in the same organization'
      USING ERRCODE = '23514';
  END IF;
  IF new.captured_by IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM users u
     WHERE u.id = new.captured_by AND u.org_id = new.org_id
  ) THEN
    RAISE EXCEPTION 'field ticket labor snapshot actor must belong to the same organization'
      USING ERRCODE = '23514';
  END IF;
  IF new.superseded_by IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM users u
     WHERE u.id = new.superseded_by AND u.org_id = new.org_id
  ) THEN
    RAISE EXCEPTION 'field ticket labor snapshot superseding actor must belong to the same organization'
      USING ERRCODE = '23514';
  END IF;
  IF new.superseded_at IS NOT NULL AND new.superseded_at < new.captured_at THEN
    RAISE EXCEPTION 'field ticket labor snapshot cannot be superseded before capture'
      USING ERRCODE = '23514';
  END IF;
  RETURN new;
END
$$;


--
-- Name: field_ticket_labor_snapshot_retention_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_ticket_labor_snapshot_retention_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE'
     AND public.openbooks_sandbox_wipe_allowed(OLD.org_id)
     AND current_setting('openbooks.migration', true) = 'on'
     AND current_setting('openbooks.amend', true) = 'on'
     AND EXISTS (SELECT 1 FROM pg_catalog.pg_roles
                  WHERE rolname = current_user AND rolbypassrls)
     AND EXISTS (SELECT 1 FROM public.orgs target
                  JOIN public.sandboxes control
                    ON control.org_id = target.id
                   AND control.production_org_id = target.sandbox_of
                  JOIN public.orgs source ON source.id = target.sandbox_of
                 WHERE target.id = OLD.org_id AND target.env_kind = 'sandbox') THEN
    RETURN OLD;
  END IF;
  IF tg_op = 'DELETE' THEN
    RAISE EXCEPTION 'field ticket labor snapshots are retained evidence';
  END IF;
  IF row(new.org_id, new.field_ticket_id, new.revision, new.evidence_basis,
         new.reason, new.source_system, new.source_payload_hash, new.currency,
         new.captured_by, new.captured_at)
     IS DISTINCT FROM
     row(old.org_id, old.field_ticket_id, old.revision, old.evidence_basis,
         old.reason, old.source_system, old.source_payload_hash, old.currency,
         old.captured_by, old.captured_at)
  THEN
    RAISE EXCEPTION 'field ticket labor snapshot evidence is immutable';
  END IF;
  IF old.superseded_at IS NOT NULL
     AND row(new.superseded_at, new.superseded_by)
         IS DISTINCT FROM row(old.superseded_at, old.superseded_by)
  THEN
    RAISE EXCEPTION 'field ticket labor snapshot supersession is immutable once recorded';
  END IF;
  IF old.superseded_at IS NULL
     AND (new.superseded_at IS NULL OR new.superseded_by IS NULL)
  THEN
    RAISE EXCEPTION 'field ticket labor snapshot may only change through a complete supersession';
  END IF;
  RETURN new;
END
$$;


--
-- Name: field_ticket_policy_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_ticket_policy_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.customer_party_id is not null and not exists (
    select 1 from parties p
     where p.id = new.customer_party_id and p.org_id = new.org_id
  ) then
    raise exception 'field ticket customer policy must belong to the same organization'
      using errcode = '23514';
  end if;
  if new.project_id is not null and not exists (
    select 1 from projects p
     where p.id = new.project_id and p.org_id = new.org_id
  ) then
    raise exception 'field ticket project policy must belong to the same organization'
      using errcode = '23514';
  end if;
  -- Effective-window exclusivity is owned by the
  -- field_ticket_policies_no_active_overlap exclusion constraint (0051),
  -- which stays correct under concurrent READ COMMITTED writers.
  return new;
end $$;


--
-- Name: FUNCTION field_ticket_policy_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.field_ticket_policy_guard() IS 'openbooks:field_ticket_policy_guard:v2 - tenant-integrity checks for Field Ticket policies; effective-window exclusivity moved to the field_ticket_policies_no_active_overlap exclusion constraint';


--
-- Name: field_ticket_signature_immutable_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_ticket_signature_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
begin
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE'
     AND public.openbooks_sandbox_wipe_allowed(OLD.org_id)
     AND current_setting('openbooks.migration', true) = 'on'
     AND current_setting('openbooks.amend', true) = 'on'
     AND EXISTS (SELECT 1 FROM pg_catalog.pg_roles
                  WHERE rolname = current_user AND rolbypassrls)
     AND EXISTS (SELECT 1 FROM public.orgs target
                  JOIN public.sandboxes control
                    ON control.org_id = target.id
                   AND control.production_org_id = target.sandbox_of
                  JOIN public.orgs source ON source.id = target.sandbox_of
                 WHERE target.id = OLD.org_id AND target.env_kind = 'sandbox') THEN
    RETURN OLD;
  END IF;
  raise exception 'field ticket signatures are append-only evidence';
end $$;


--
-- Name: field_ticket_signature_request_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_ticket_signature_request_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  if tg_op = 'DELETE' then
    raise exception 'field ticket signature requests are retained evidence';
  end if;
  if row(new.org_id, new.field_ticket_id, new.recipient, new.message,
         new.expires_at, new.token_digest, new.email_log_id,
         new.created_by, new.created_at)
     is distinct from
     row(old.org_id, old.field_ticket_id, old.recipient, old.message,
         old.expires_at, old.token_digest, old.email_log_id,
         old.created_by, old.created_at)
  then
    raise exception 'field ticket signature request evidence is immutable';
  end if;
  if old.responded_at is not null and new.responded_at is distinct from old.responded_at then
    raise exception 'field ticket signature response timestamp is immutable once set';
  end if;
  if old.revoked_at is not null and new.revoked_at is distinct from old.revoked_at then
    raise exception 'field ticket signature revocation timestamp is immutable once set';
  end if;
  if old.sent_at is not null and new.sent_at is distinct from old.sent_at then
    raise exception 'field ticket signature delivery timestamp is immutable once set';
  end if;
  return new;
end $$;


--
-- Name: field_ticket_source_certification_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_ticket_source_certification_audit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 -- A copied row's provenance is its exact source match, not a new certification.
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id)
 VALUES (NEW.org_id, 'field_ticket_source_certifications', NEW.id, 'insert',
   jsonb_build_object('after', to_jsonb(NEW), 'reason', NEW.reason,
     'basis', NEW.reviewed_basis, 'requestId', NEW.request_id), NEW.certified_by);
 RETURN NEW;
END
$$;


--
-- Name: field_ticket_source_certification_clone_evidence(jsonb, uuid, text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_ticket_source_certification_clone_evidence(value jsonb, seed uuid, field_name text, target_org uuid, masked boolean) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF value IS NULL THEN RETURN NULL; END IF;
 IF field_name = 'source_row_snapshot' THEN
  RETURN CASE WHEN masked THEN public.production_mask_evidence(value) ELSE value END;
 END IF;
 IF masked AND field_name = 'native_point_in_time' THEN
  RETURN jsonb_build_object(
   'maskedEvidence', 'REDACTED',
   'fingerprintAttribution', 'native_fingerprint_sha256 retains the original source fingerprint; this masked copy carries no native point-in-time before-image');
 END IF;
 RETURN public.production_clone_safe_evidence(value, seed, field_name, target_org, masked);
END
$$;


--
-- Name: field_ticket_source_certification_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_ticket_source_certification_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP = 'INSERT' AND public.field_ticket_source_certifications_clone_matches(to_jsonb(NEW)) THEN
  RETURN NEW;
 END IF;
 IF TG_OP = 'DELETE' THEN
  IF tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD))
     OR public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
   RETURN OLD;
  END IF;
  RAISE EXCEPTION 'Field Ticket source-identity certifications are append-only; a certification cannot be deleted'
   USING ERRCODE = '23514';
 END IF;
 IF TG_OP = 'UPDATE' THEN
  RAISE EXCEPTION 'Field Ticket source-identity certifications are append-only; a certification cannot be replaced'
   USING ERRCODE = '23514';
 END IF;
 IF NOT EXISTS (SELECT 1 FROM public.documents
   WHERE org_id = NEW.org_id AND id = NEW.native_document_id AND kind = 'field_ticket'
     AND document_number = NEW.native_document_number
     AND project_id = NEW.native_project_id
     AND subsidiary_id = NEW.native_subsidiary_id) THEN
  RAISE EXCEPTION 'A Field Ticket source-identity certification requires the exact native ticket, number, project and legal entity in this organization'
   USING ERRCODE = '23514';
 END IF;
 IF NOT EXISTS (SELECT 1 FROM public.field_tickets
   WHERE org_id = NEW.org_id AND document_id = NEW.native_document_id) THEN
  RAISE EXCEPTION 'A Field Ticket source-identity certification requires the native Field Ticket header in this organization'
   USING ERRCODE = '23514';
 END IF;
 IF EXISTS (SELECT 1 FROM public.documents
   WHERE org_id = NEW.org_id AND kind = 'field_ticket' AND id <> NEW.native_document_id
     AND custom->'source'->>'system' = NEW.source_system
     AND custom->'source'->>'externalId' = NEW.source_external_id) THEN
  RAISE EXCEPTION 'This source ticket is already represented by another native Field Ticket; reconcile the duplicate source representation before certifying'
   USING ERRCODE = '23514';
 END IF;
 IF NOT EXISTS (SELECT 1 FROM public.files file
   JOIN public.file_versions version ON version.file_id = file.id
   WHERE file.org_id = NEW.org_id AND file.id = NEW.source_file_id AND NOT file.is_inactive
     AND version.id = NEW.source_version_id AND version.content_hash = NEW.source_file_sha256) THEN
  RAISE EXCEPTION 'A Field Ticket source-identity certification requires the exact active retained source file version and hash in this organization'
   USING ERRCODE = '23514';
 END IF;
 RETURN NEW;
END
$$;


--
-- Name: field_ticket_source_certification_projection_commit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_ticket_source_certification_projection_commit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF public.openbooks_clone_authority() THEN RETURN NULL; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.documents
   WHERE org_id = NEW.org_id AND id = NEW.native_document_id AND kind = 'field_ticket'
     AND custom->'source'->>'system' = NEW.source_system
     AND custom->'source'->>'externalId' = NEW.source_external_id) THEN
  RAISE EXCEPTION 'A Field Ticket source-identity certification must commit with its exact source projection on the native ticket'
   USING ERRCODE = '23514';
 END IF;
 IF NOT EXISTS (SELECT 1 FROM public.audit_log
   WHERE org_id = NEW.org_id AND table_name = 'documents' AND row_id = NEW.native_document_id
     AND action = 'update' AND actor_id = NEW.certified_by AND request_id = NEW.request_id::text
     AND changes->>'reason' = 'field_ticket_source_identity_certification'
     AND changes->>'certificationId' = NEW.id::text) THEN
  RAISE EXCEPTION 'A Field Ticket source-identity certification must commit with its governed document audit'
   USING ERRCODE = '23514';
 END IF;
 RETURN NULL;
END
$$;


--
-- Name: field_ticket_source_certifications_clone_matches(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_ticket_source_certifications_clone_matches(candidate jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  target record;
  original jsonb;
  expected jsonb;
  column_row record;
BEGIN
  IF NOT public.openbooks_clone_authority() THEN RETURN false; END IF;
  SELECT org.sandbox_of, org.sandbox_seed, sandbox.masked
    INTO target
    FROM public.orgs org
    JOIN public.sandboxes sandbox
      ON sandbox.org_id = org.id AND sandbox.production_org_id = org.sandbox_of
    JOIN public.orgs production ON production.id = org.sandbox_of AND production.id <> org.id
   WHERE org.id = (candidate->>'org_id')::uuid
     AND org.env_kind = 'sandbox'
     AND org.sandbox_seed IS NOT NULL
     AND sandbox.status IN ('provisioning', 'refreshing');
  IF NOT FOUND THEN RETURN false; END IF;

  SELECT to_jsonb(source)
    INTO original
    FROM public.field_ticket_source_certifications source
   WHERE source.org_id = target.sandbox_of
     AND public.ob_rebase(source.id, target.sandbox_seed) = (candidate->>'id')::uuid;
  IF original IS NULL THEN RETURN false; END IF;

  expected := original;
  FOR column_row IN
    SELECT attribute.attname, attribute.atttypid
      FROM pg_catalog.pg_attribute attribute
     WHERE attribute.attrelid = 'public.field_ticket_source_certifications'::regclass
       AND attribute.attnum > 0 AND NOT attribute.attisdropped
  LOOP
    IF column_row.attname = 'org_id' THEN
      expected := jsonb_set(expected, ARRAY[column_row.attname], to_jsonb((candidate->>'org_id')::uuid));
    ELSIF column_row.atttypid = 'uuid'::regtype
      AND jsonb_typeof(original->column_row.attname) = 'string' THEN
      expected := jsonb_set(expected, ARRAY[column_row.attname], to_jsonb(public.ob_rebase(
        (original->>column_row.attname)::uuid, target.sandbox_seed
      )));
    END IF;
  END LOOP;
  expected := jsonb_set(expected, '{source_row_snapshot}', public.field_ticket_source_certification_clone_evidence(
    original->'source_row_snapshot', target.sandbox_seed, 'source_row_snapshot',
    (candidate->>'org_id')::uuid, target.masked));
  expected := jsonb_set(expected, '{reference_map}', public.field_ticket_source_certification_clone_evidence(
    original->'reference_map', target.sandbox_seed, 'reference_map',
    (candidate->>'org_id')::uuid, target.masked));
  expected := jsonb_set(expected, '{native_point_in_time}', public.field_ticket_source_certification_clone_evidence(
    original->'native_point_in_time', target.sandbox_seed, 'native_point_in_time',
    (candidate->>'org_id')::uuid, target.masked));
  IF target.masked THEN
    expected := jsonb_set(expected, '{attestation}', to_jsonb('REDACTED'::text));
    expected := jsonb_set(expected, '{reason}', to_jsonb('REDACTED'::text));
  END IF;
  RETURN candidate = expected;
END
$$;


--
-- Name: field_ticket_source_projection_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_ticket_source_projection_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
 old_system text;
 old_external text;
 new_system text;
 new_external text;
BEGIN
 IF NEW.kind <> 'field_ticket' AND OLD.kind <> 'field_ticket' THEN RETURN NEW; END IF;
 old_system := CASE WHEN jsonb_typeof(OLD.custom->'source') = 'object' THEN OLD.custom->'source'->>'system' END;
 old_external := CASE WHEN jsonb_typeof(OLD.custom->'source') = 'object' THEN OLD.custom->'source'->>'externalId' END;
 new_system := CASE WHEN jsonb_typeof(NEW.custom->'source') = 'object' THEN NEW.custom->'source'->>'system' END;
 new_external := CASE WHEN jsonb_typeof(NEW.custom->'source') = 'object' THEN NEW.custom->'source'->>'externalId' END;
 IF (new_system, new_external) IS NOT DISTINCT FROM (old_system, old_external) THEN RETURN NEW; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.field_ticket_source_certifications
   WHERE org_id = NEW.org_id AND native_document_id = NEW.id
     AND source_system = new_system AND source_external_id = new_external) THEN
  RAISE EXCEPTION 'Field Ticket source identity may be set only from its governed source-identity certification; certify the ticket through the native certification command before projecting a source marker'
   USING ERRCODE = '23514';
 END IF;
 RETURN NEW;
END
$$;


--
-- Name: financial_change_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.financial_change_audit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO audit_log(org_id,table_name,row_id,action,changes,actor_id)
    VALUES (NEW.org_id,'financial_changes',NEW.id,lower(TG_OP),
      jsonb_build_object('before',CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(OLD) END,'after',to_jsonb(NEW)),
      NEW.updated_by);
  RETURN NEW;
END $$;


--
-- Name: financial_change_clone_context(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.financial_change_clone_context(value jsonb, seed uuid) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE result jsonb:=value; identity_key text;
BEGIN
 IF value IS NULL THEN RETURN NULL; END IF;
 FOREACH identity_key IN ARRAY ARRAY['id','subsidiaryId'] LOOP
  IF jsonb_typeof(result->identity_key)='string' THEN
   result:=jsonb_set(result,ARRAY[identity_key],to_jsonb(public.ob_rebase((result->>identity_key)::uuid,seed)::text));
  END IF;
 END LOOP;
 IF jsonb_typeof(result #> '{submissionPolicy,flowId}')='string' THEN
  result:=jsonb_set(result,'{submissionPolicy,flowId}',to_jsonb(public.ob_rebase((result #>> '{submissionPolicy,flowId}')::uuid,seed)::text));
 END IF;
 RETURN result;
END $$;


--
-- Name: financial_change_flow_decision_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.financial_change_flow_decision_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF OLD.status='pending' AND NEW.status IN('approved','rejected') THEN
  IF NEW.status='approved' AND NEW.submission_policy->>'kind'='ungated' AND NEW.approved_by=NEW.submitted_by
   AND public.flow_ungated_submission_authorized(NEW.org_id,'financial_change',NEW.id,NEW.approved_by) THEN RETURN NEW; END IF;
  IF NEW.submission_policy IS NULL OR NOT EXISTS(SELECT 1 FROM public.flow_gates g JOIN public.flow_runs r ON r.org_id=g.org_id AND r.id=g.run_id
    WHERE g.org_id=NEW.org_id AND g.subject_kind='financial_change' AND g.subject_id=NEW.id
      AND NEW.submission_policy->'runIds' ? r.id::text AND g.status=NEW.status AND g.decided_by=NEW.approved_by
      AND r.context->'submissionPolicy'->>'flowId'=r.flow_id::text)
    OR EXISTS(SELECT 1 FROM public.flow_gates g WHERE g.org_id=NEW.org_id AND g.subject_kind='financial_change'
      AND g.subject_id=NEW.id AND g.status IN('pending','escalated')) THEN
   RAISE EXCEPTION 'Complete every configured accounting-event Flow gate before deciding the proposal.';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: financial_change_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.financial_change_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
  scrap_work_order_subsidiary_id uuid;
  scrap_posted_entry_id uuid;
  scrap_posted_journal_subsidiary_id uuid;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;
  IF TG_OP='DELETE' THEN
    IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN RETURN OLD; END IF;
    RAISE EXCEPTION 'financial changes are immutable evidence; propose a correcting change';
  END IF;
  IF TG_OP='INSERT' AND NEW.submission_policy IS NOT NULL AND NOT public.openbooks_clone_authority() THEN
    RAISE EXCEPTION 'Submission routing evidence is captured only on submission.';
  END IF;
  IF TG_OP='UPDATE' AND NEW.submission_policy IS DISTINCT FROM OLD.submission_policy THEN
    IF OLD.status<>'draft' OR NEW.status<>'pending' OR OLD.submission_policy IS NOT NULL
      OR NOT public.flow_submission_policy_valid(NEW.org_id,'financial_change',NEW.id,NEW.submitted_by,NEW.submission_policy) THEN
      RAISE EXCEPTION 'The accounting event requires complete native Flow routing evidence, frozen on submission.';
    END IF;
  END IF;
  IF TG_OP='UPDATE' AND OLD.status='draft' AND NEW.status='pending' AND NEW.submission_policy IS NULL THEN
    RAISE EXCEPTION 'Submit the accounting event through its native Flow routing.';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM subsidiaries WHERE id=NEW.subsidiary_id AND org_id=NEW.org_id) THEN
    RAISE EXCEPTION 'financial change subsidiary must belong to the organization';
  END IF;
  IF TG_OP='INSERT' THEN
    IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
    IF NEW.status <> 'draft' THEN RAISE EXCEPTION 'financial changes must start as draft'; END IF;
  END IF;
  IF NEW.domain = 'manufacturing' AND (
       TG_OP = 'INSERT'
       OR (OLD.status = 'draft' AND NEW.status = 'pending')
       OR (OLD.status = 'pending' AND NEW.status IN ('approved', 'rejected'))
       OR (OLD.status = 'approved' AND NEW.status = 'applied')) THEN
    IF NEW.operation = 'work_order_loss_disposition' THEN
      IF NEW.payload->>'workOrderId' IS DISTINCT FROM NEW.subject_id::text
        OR NEW.payload->'requiredSubsidiaryIds' IS DISTINCT FROM jsonb_build_array(NEW.subsidiary_id::text)
        OR NEW.before_state->'order'->>'id' IS DISTINCT FROM NEW.subject_id::text
        OR NEW.before_state->'order'->>'subsidiary_id' IS DISTINCT FROM NEW.subsidiary_id::text
        OR NEW.before_state->>'onDate' IS DISTINCT FROM NEW.effective_on::text
        OR NEW.before_state->>'quantity' IS DISTINCT FROM NEW.payload->'input'->>'quantity'
        OR coalesce(NEW.before_state->>'value','') !~ '^[0-9]+([.][0-9]{1,4})?$'
        OR coalesce(NEW.before_state->>'quantity','') !~ '^[0-9]+([.][0-9]{1,4})?$'
        OR jsonb_typeof(NEW.payload->'input'->'times') IS DISTINCT FROM 'array'
        OR NOT EXISTS(SELECT 1 FROM public.mfg_work_orders WHERE org_id=NEW.org_id AND id=NEW.subject_id AND subsidiary_id=NEW.subsidiary_id) THEN
        RAISE EXCEPTION 'Production loss approval must bind its work, actual discarded quantity, conversion time, WIP and booking entity.' USING ERRCODE='23514';
      END IF;
      IF (NEW.before_state->>'quantity')::numeric<=0 OR (NEW.before_state->>'value')::numeric>999999999999999.9999 THEN RAISE EXCEPTION 'Production loss quantities and values require exact supported precision.' USING ERRCODE='23514'; END IF;
    ELSIF NEW.operation = 'standard_cost_rollup' THEN
      IF jsonb_typeof(NEW.payload) IS DISTINCT FROM 'object'
        OR NEW.payload->>'itemId' IS DISTINCT FROM NEW.subject_id::text
        OR NEW.payload->>'subsidiaryId' IS DISTINCT FROM NEW.subsidiary_id::text
        OR NEW.payload->>'onDate' IS DISTINCT FROM NEW.effective_on::text
        OR NEW.payload->'requiredSubsidiaryIds' IS DISTINCT FROM jsonb_build_array(NEW.subsidiary_id::text)
        OR coalesce(NEW.payload->>'batchQuantity','') !~ '^[0-9]+([.][0-9]{1,4})?$'
        OR coalesce(NEW.payload->>'standardCost','') !~ '^[0-9]+([.][0-9]{1,4})?$'
        OR NOT EXISTS(SELECT 1 FROM public.item_inventory_profiles WHERE org_id=NEW.org_id AND item_id=NEW.subject_id AND costing_method='standard') THEN
        RAISE EXCEPTION 'Standard roll-up must bind a tenant standard-cost item, costing date, positive batch, standard, and booking entity.' USING ERRCODE='23514';
      END IF;
      IF (NEW.payload->>'batchQuantity')::numeric<=0 THEN RAISE EXCEPTION 'Standard roll-up batch must be positive.' USING ERRCODE='23514'; END IF;
    ELSIF NEW.operation = 'bom_revision_activation' THEN
      IF NEW.payload->>'assemblyItemId' IS DISTINCT FROM NEW.subject_id::text
        OR NEW.payload->'requiredSubsidiaryIds' IS DISTINCT FROM jsonb_build_array(NEW.subsidiary_id::text)
        OR jsonb_typeof(NEW.payload->'components') IS DISTINCT FROM 'array'
        OR jsonb_typeof(NEW.before_state->'lines') IS DISTINCT FROM 'array'
        OR jsonb_array_length(NEW.payload->'components') NOT BETWEEN 1 AND 500
        OR NOT EXISTS(SELECT 1 FROM public.items WHERE org_id=NEW.org_id AND id=NEW.subject_id AND kind<>'kit') THEN
        RAISE EXCEPTION 'BOM approval must bind its tenant produced item, component revision and booking entity.' USING ERRCODE='23514';
      END IF;
    ELSIF NEW.operation = 'routing_revision_activation' THEN
      IF jsonb_typeof(NEW.payload) IS DISTINCT FROM 'object'
        OR NEW.payload->>'routingId' IS DISTINCT FROM NEW.subject_id::text
        OR NEW.payload->'requiredSubsidiaryIds' IS DISTINCT FROM jsonb_build_array(NEW.subsidiary_id::text)
        OR jsonb_typeof(NEW.payload->'supersedes') IS DISTINCT FROM 'array'
        OR NEW.before_state->'candidate'->>'id' IS DISTINCT FROM NEW.subject_id::text
        OR NEW.before_state->'candidate'->>'effectiveFrom' IS DISTINCT FROM NEW.effective_on::text
        OR NOT EXISTS(SELECT 1 FROM public.mfg_routings WHERE org_id=NEW.org_id AND id=NEW.subject_id) THEN
        RAISE EXCEPTION 'Routing approval must bind its tenant revision, effective date and governed prior windows.' USING ERRCODE='23514';
      END IF;
    ELSE
    IF NEW.operation <> 'scrap_snapshot_restatement' THEN
      RAISE EXCEPTION 'manufacturing financial changes admit only the scrap_snapshot_restatement operation, not %', NEW.operation;
    END IF;
    IF NEW.payload IS NULL OR jsonb_typeof(NEW.payload) <> 'object' THEN
      RAISE EXCEPTION 'manufacturing scrap restatement proposals must carry an object payload binding the event, work order, subsidiary, and approval flag';
    END IF;
    IF NOT (NEW.payload ? 'event_id')
      OR NOT (NEW.payload ? 'work_order_id')
      OR NOT (NEW.payload ? 'subsidiary_id')
      OR NOT (NEW.payload ? 'requiredSubsidiaryIds') THEN
      RAISE EXCEPTION 'manufacturing scrap restatement proposals must bind event_id, work_order_id, subsidiary_id, and requiredSubsidiaryIds in the payload';
    END IF;
    IF jsonb_typeof(NEW.payload -> 'requiredSubsidiaryIds') <> 'array'
      OR jsonb_typeof(NEW.payload -> 'approval_required') <> 'boolean' THEN
      RAISE EXCEPTION 'manufacturing scrap restatement proposals must bind requiredSubsidiaryIds as an array and the engine-derived approval_required as a boolean';
    END IF;
    IF (NEW.payload ->> 'event_id') <> NEW.subject_id::text THEN
      RAISE EXCEPTION 'manufacturing scrap restatement subject must be the bound event';
    END IF;
    SELECT work_order.subsidiary_id, scrap_event.posted_entry_id
      INTO scrap_work_order_subsidiary_id, scrap_posted_entry_id
      FROM public.mfg_scrap_events scrap_event
      JOIN public.mfg_work_orders work_order
        ON work_order.org_id = scrap_event.org_id
       AND work_order.id = scrap_event.work_order_id
     WHERE scrap_event.org_id = NEW.org_id
       AND scrap_event.id = NEW.subject_id
       AND scrap_event.work_order_id::text = (NEW.payload ->> 'work_order_id');
    IF NOT FOUND THEN
      RAISE EXCEPTION 'manufacturing scrap restatement must bind the same-organization event, its work order, and that work order''s subsidiary';
    END IF;
    IF scrap_work_order_subsidiary_id IS NULL THEN
      RAISE EXCEPTION 'manufacturing scrap restatement for event % is refused: work order % carries no subsidiary, and a restatement requires a non-null authoritative work-order subsidiary', NEW.subject_id, (NEW.payload ->> 'work_order_id');
    END IF;
    IF scrap_work_order_subsidiary_id IS DISTINCT FROM NEW.subsidiary_id THEN
      RAISE EXCEPTION 'manufacturing scrap restatement for event % must book the work order''s subsidiary %, not %', NEW.subject_id, scrap_work_order_subsidiary_id, NEW.subsidiary_id;
    END IF;
    IF (NEW.payload ->> 'subsidiary_id') IS DISTINCT FROM NEW.subsidiary_id::text THEN
      RAISE EXCEPTION 'manufacturing scrap restatement for event % payload subsidiary % must equal the booking subsidiary %', NEW.subject_id, (NEW.payload ->> 'subsidiary_id'), NEW.subsidiary_id;
    END IF;
    IF (NEW.payload -> 'requiredSubsidiaryIds') <> jsonb_build_array(NEW.subsidiary_id::text) THEN
      RAISE EXCEPTION 'manufacturing scrap restatement requiredSubsidiaryIds must be exactly the booking subsidiary';
    END IF;
    IF scrap_posted_entry_id IS NOT NULL THEN
      SELECT journal_entry.subsidiary_id
        INTO scrap_posted_journal_subsidiary_id
        FROM public.journal_entries journal_entry
       WHERE journal_entry.org_id = NEW.org_id
         AND journal_entry.id = scrap_posted_entry_id;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'manufacturing scrap restatement for event % references posted entry % which has no same-organization journal entry; reconcile the posted entry through the controlled accounting evidence correction workflow before retrying the restatement, without posting a duplicate entry, reversing the entry, rewriting the event, or fabricating journal evidence', NEW.subject_id, scrap_posted_entry_id;
      END IF;
      IF scrap_posted_journal_subsidiary_id IS DISTINCT FROM NEW.subsidiary_id THEN
        RAISE EXCEPTION 'manufacturing scrap restatement for event % posted entry % books subsidiary %, not the bound booking subsidiary %', NEW.subject_id, scrap_posted_entry_id, scrap_posted_journal_subsidiary_id, NEW.subsidiary_id;
      END IF;
    ELSE
      IF (NEW.payload ? 'posted_entry_id')
        OR (NEW.payload ? 'journal_entry_id')
        OR (NEW.payload ? 'entry_id') THEN
        RAISE EXCEPTION 'manufacturing scrap restatement for unposted event % must not carry journal evidence; payload keys posted_entry_id, journal_entry_id, and entry_id are refused', NEW.subject_id;
      END IF;
    END IF;
    END IF;
  END IF;
  IF TG_OP='INSERT' THEN
    RETURN NEW;
  END IF;
  IF (to_jsonb(NEW) - ARRAY['status','approved_by','approved_at','result','applied_by','applied_at','updated_at','updated_by','submission_policy'])
     IS DISTINCT FROM
     (to_jsonb(OLD) - ARRAY['status','approved_by','approved_at','result','applied_by','applied_at','updated_at','updated_by','submission_policy']) THEN
    RAISE EXCEPTION 'financial change proposal is immutable; create a new proposal';
  END IF;
  IF NOT ((OLD.status='draft' AND NEW.status='pending') OR
          (OLD.status='pending' AND NEW.status IN ('approved','rejected')) OR
          (OLD.status='approved' AND NEW.status='applied')) THEN
    RAISE EXCEPTION 'invalid financial change transition % -> %', OLD.status, NEW.status;
  END IF;
  IF OLD.status <> 'pending' AND (NEW.approved_by IS DISTINCT FROM OLD.approved_by OR NEW.approved_at IS DISTINCT FROM OLD.approved_at) THEN
    RAISE EXCEPTION 'financial change approval cannot be rewritten';
  END IF;
  RETURN NEW;
END $_$;


--
-- Name: financial_change_self_decision_authorized(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.financial_change_self_decision_authorized(organization uuid, change_id uuid, decision_actor uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 SELECT decision_actor IS NOT NULL AND (
  EXISTS (SELECT 1 FROM public.financial_changes c WHERE c.org_id=organization AND c.id=change_id
    AND c.submitted_by=decision_actor AND c.submission_policy->>'kind'='ungated'
    AND c.submission_policy->'version'='1'::jsonb
    AND public.flow_ungated_submission_authorized(c.org_id,'financial_change',c.id,decision_actor))
  OR (EXISTS (
   SELECT 1 FROM public.flow_gates g JOIN public.flow_runs r
    ON r.org_id=g.org_id AND r.id=g.run_id AND r.flow_id=g.flow_id
   WHERE g.org_id=organization AND g.subject_kind='financial_change' AND g.subject_id=change_id
     AND r.subject_kind=g.subject_kind AND r.subject_id=g.subject_id
     AND g.decided_by=decision_actor AND g.status IN('approved','rejected') AND g.decided_at IS NOT NULL
     AND r.context->'submissionPolicy'->>'flowId'=r.flow_id::text
     AND EXISTS (SELECT 1 FROM jsonb_array_elements(r.context->'submissionPolicy'->'graph'->'nodes') node
       WHERE node->>'id'=g.node_id AND node->'data'->>'kind'='gate'
         AND node->'data'->'gate'->'preventSelfApproval'='false'::jsonb)
  )
  AND NOT EXISTS (
   SELECT 1 FROM public.flow_gates g LEFT JOIN public.flow_runs r
    ON r.org_id=g.org_id AND r.id=g.run_id AND r.flow_id=g.flow_id
   WHERE g.org_id=organization AND g.subject_kind='financial_change' AND g.subject_id=change_id
     AND g.decided_by=decision_actor AND g.status IN('approved','rejected')
     AND (r.id IS NULL OR r.subject_kind IS DISTINCT FROM g.subject_kind
       OR r.subject_id IS DISTINCT FROM g.subject_id OR g.decided_at IS NULL
       OR r.context->'submissionPolicy'->>'flowId' IS DISTINCT FROM r.flow_id::text
       OR NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r.context->'submissionPolicy'->'graph'->'nodes') node
         WHERE node->>'id'=g.node_id AND node->'data'->>'kind'='gate'
           AND node->'data'->'gate'->'preventSelfApproval'='false'::jsonb))
  )));
$$;


--
-- Name: financial_change_self_decision_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.financial_change_self_decision_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF NEW.approved_by=NEW.submitted_by AND NOT public.financial_change_self_decision_authorized(NEW.org_id,NEW.id,NEW.approved_by) THEN
  RAISE EXCEPTION 'Submit through Flows; release requires successful ungated routing or its retained gate decisions.';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: financial_history_clone_scope(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.financial_history_clone_scope(source_scope text, seed uuid) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
BEGIN
 IF source_scope='all' THEN RETURN source_scope; END IF;
 IF source_scope ~ '^period:[0-9a-f-]{36}$' THEN
  RETURN 'period:'||public.ob_rebase(split_part(source_scope,':',2)::uuid,seed);
 END IF;
 IF source_scope ~ '^year:[0-9a-f-]{36}:[0-9]+$' THEN
  RETURN 'year:'||public.ob_rebase(split_part(source_scope,':',2)::uuid,seed)||':'||split_part(source_scope,':',3);
 END IF;
 RAISE EXCEPTION 'The retained GL audit scope has no native period or fiscal-year identity.' USING ERRCODE='23514';
END $_$;


--
-- Name: financial_history_native_clone_matches(regclass, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.financial_history_native_clone_matches(relation regclass, candidate jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE target record; original jsonb; expected jsonb; field record; reference record;
 parent_matches boolean; parent_predicate text; policy_prefix text; relation_name text;
BEGIN
 IF NOT public.openbooks_clone_authority() OR relation NOT IN (
  'public.fx_rate_types'::regclass,'public.account_translation_policies'::regclass,
  'public.subsidiary_accounting_preferences'::regclass,'public.segment_balancing_policies'::regclass,
  'public.gl_audit_number_policies'::regclass,'public.gl_audit_number_assignments'::regclass,
  'public.journal_lines'::regclass,'public.rebate_agreements'::regclass) THEN RETURN false; END IF;
 SELECT destination.id,destination.sandbox_of,destination.sandbox_seed,control.masked INTO target
 FROM public.orgs destination JOIN public.sandboxes control
  ON control.org_id=destination.id AND control.production_org_id=destination.sandbox_of
 JOIN public.orgs source ON source.id=destination.sandbox_of AND source.id<>destination.id
 WHERE destination.id=(candidate->>'org_id')::uuid AND destination.env_kind='sandbox'
  AND destination.sandbox_seed IS NOT NULL AND control.status IN('provisioning','refreshing');
 IF NOT FOUND THEN RETURN false; END IF;
 EXECUTE format('SELECT to_jsonb(source) FROM %s source WHERE source.org_id=$1 AND public.ob_rebase(source.id,$2)=$3',relation)
 INTO original USING target.sandbox_of,target.sandbox_seed,(candidate->>'id')::uuid;
 IF original IS NULL THEN RETURN false; END IF;
 SELECT relname INTO relation_name FROM pg_catalog.pg_class WHERE oid=relation;
 expected:=original;
 FOR field IN SELECT attname,atttypid FROM pg_catalog.pg_attribute
  WHERE attrelid=relation AND attnum>0 AND NOT attisdropped LOOP
  IF field.attname='org_id' THEN
   expected:=jsonb_set(expected,ARRAY[field.attname],to_jsonb(target.id));
  ELSIF field.atttypid='uuid'::regtype AND jsonb_typeof(original->field.attname)='string' THEN
   expected:=jsonb_set(expected,ARRAY[field.attname],to_jsonb(public.ob_rebase((original->>field.attname)::uuid,target.sandbox_seed)));
  END IF;
  IF target.masked AND field.attname IN('name','reason','memo') AND jsonb_typeof(original->field.attname)='string' THEN
   expected:=jsonb_set(expected,ARRAY[field.attname],to_jsonb('REDACTED'::text));
  END IF;
 END LOOP;
 IF jsonb_typeof(expected->'extra_dims')='object' THEN
  expected:=jsonb_set(expected,'{extra_dims}',coalesce((SELECT jsonb_object_agg(dim.key,CASE
   WHEN jsonb_typeof(dim.value)='string' AND EXISTS(SELECT 1 FROM public.segment_values value_row
    WHERE value_row.org_id=target.sandbox_of AND value_row.id::text=dim.value #>> '{}')
   THEN to_jsonb(public.ob_rebase((dim.value #>> '{}')::uuid,target.sandbox_seed)::text) ELSE dim.value END)
   FROM jsonb_each(expected->'extra_dims') dim),'{}'::jsonb));
 END IF;
 IF relation='public.journal_lines'::regclass AND coalesce(original->'custom'->>'equitySecurityId','') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN
  expected:=jsonb_set(expected,'{custom}',(CASE WHEN target.masked THEN '{}'::jsonb ELSE original->'custom' END)
   || jsonb_build_object('equitySecurityId',public.ob_rebase((original->'custom'->>'equitySecurityId')::uuid,target.sandbox_seed)::text,
      'equityRole',original->'custom'->'equityRole'));
 ELSIF relation='public.journal_lines'::regclass AND target.masked THEN
  expected:=jsonb_set(expected,'{custom}','{}'::jsonb);
 END IF;
 IF relation='public.gl_audit_number_assignments'::regclass THEN
  SELECT prefix INTO policy_prefix FROM public.gl_audit_number_policies
   WHERE org_id=target.sandbox_of AND id=(original->>'policy_id')::uuid;
  IF policy_prefix IS NULL THEN RETURN false; END IF;
  expected:=jsonb_set(expected,'{scope_key}',to_jsonb(public.financial_history_clone_scope(original->>'scope_key',target.sandbox_seed)));
  expected:=jsonb_set(expected,'{audit_number}',to_jsonb(policy_prefix||'-'||replace(expected->>'scope_key',':','-')||'-'||
   lpad(original->>'ordinal',greatest(6,length(original->>'ordinal')),'0')));
 END IF;
 IF candidate IS DISTINCT FROM expected THEN RETURN false; END IF;
 -- Validate the complete referenced parent identity, including composite tenant keys,
 -- before admitting a recorded fact under its sandbox counterpart.
 FOR reference IN SELECT con.oid,con.confrelid FROM pg_catalog.pg_constraint con
  WHERE con.conrelid=relation AND con.contype='f' LOOP
  IF EXISTS(SELECT 1 FROM pg_catalog.pg_constraint con
   JOIN pg_catalog.pg_attribute a ON a.attrelid=con.conrelid AND a.attnum=ANY(con.conkey)
   WHERE con.oid=reference.oid AND (candidate->a.attname IS NULL OR candidate->a.attname='null'::jsonb)) THEN CONTINUE; END IF;
  SELECT string_agg(format('parent.%I=($1->>%L)::%s',parent_column.attname,source_column.attname,
    pg_catalog.format_type(source_column.atttypid,source_column.atttypmod)),' AND ' ORDER BY position)
   INTO parent_predicate FROM pg_catalog.pg_constraint con
   CROSS JOIN LATERAL generate_subscripts(con.conkey,1) position
   JOIN pg_catalog.pg_attribute source_column ON source_column.attrelid=con.conrelid AND source_column.attnum=con.conkey[position]
   JOIN pg_catalog.pg_attribute parent_column ON parent_column.attrelid=con.confrelid AND parent_column.attnum=con.confkey[position]
   WHERE con.oid=reference.oid;
  IF EXISTS(SELECT 1 FROM pg_catalog.pg_attribute WHERE attrelid=reference.confrelid AND attname='org_id' AND NOT attisdropped) THEN
   parent_predicate:=parent_predicate||' AND parent.org_id=($1->>''org_id'')::uuid';
  END IF;
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM %s parent WHERE %s)',reference.confrelid::regclass,parent_predicate)
   INTO parent_matches USING candidate;
  IF NOT parent_matches THEN RETURN false; END IF;
 END LOOP;
 -- Legacy policy actor columns predate their explicit foreign keys.
 IF relation_name IN('fx_rate_types','account_translation_policies','subsidiary_accounting_preferences','segment_balancing_policies','gl_audit_number_policies') THEN
  IF EXISTS(SELECT 1 FROM unnest(ARRAY[candidate->>'created_by',candidate->>'updated_by']) actor(id)
   WHERE actor.id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.users u WHERE u.org_id=target.id AND u.id=actor.id::uuid)) THEN RETURN false; END IF;
 END IF;
 RETURN true;
END $_$;


--
-- Name: financial_history_seeded_rate_clone_conflict(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.financial_history_seeded_rate_clone_conflict(existing jsonb, candidate jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF candidate->>'key' NOT IN('spot','average','historical') OR
  existing->>'key' IS DISTINCT FROM candidate->>'key' OR existing->>'org_id' IS DISTINCT FROM candidate->>'org_id' OR
  existing->>'is_active'<>'true' OR existing->>'name' IS DISTINCT FROM
   (CASE candidate->>'key' WHEN 'spot' THEN 'Spot' WHEN 'average' THEN 'Average' ELSE 'Historical' END) OR
  existing->>'created_by' IS NOT NULL OR existing->>'updated_by' IS NOT NULL OR
  NOT public.financial_history_native_clone_matches('public.fx_rate_types'::regclass,candidate) THEN
  RAISE EXCEPTION 'A sandbox rate registry collision is not a native seeded built-in. Preserve the destination definitions and refresh through the native lifecycle.' USING ERRCODE='23514';
 END IF;
 RETURN true;
END $$;


--
-- Name: financial_policy_version_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.financial_policy_version_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD)) OR public.openbooks_sandbox_wipe_allowed(OLD.org_id)) THEN RETURN OLD; END IF;
 RAISE EXCEPTION 'Financial policy versions are retained history. Record a new version from its effective date.' USING ERRCODE='23514';
END $$;


--
-- Name: financial_preferences_version_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.financial_preferences_version_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN
  IF public.financial_history_native_clone_matches(TG_RELID,to_jsonb(NEW)) THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'Financial history clone admission requires the exact registered source row, seed and destination parents.' USING ERRCODE='23514';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('openbooks:ledger-setup:'||NEW.org_id,0));
 IF TG_TABLE_NAME='account_translation_policies' THEN
  IF NOT EXISTS(SELECT 1 FROM accounts WHERE org_id=NEW.org_id AND id=NEW.account_id AND is_active AND NOT is_summary AND type<>'statistical') THEN
   RAISE EXCEPTION 'Choose an active monetary posting account for a translation policy.' USING ERRCODE='23514'; END IF;
  IF EXISTS(SELECT 1 FROM journal_lines l JOIN journal_entries e ON e.org_id=l.org_id AND e.id=l.entry_id
    WHERE l.org_id=NEW.org_id AND l.account_id=NEW.account_id AND e.status IN('posted','reversed') AND e.posting_date>=NEW.effective_from) THEN
   RAISE EXCEPTION 'A translation policy cannot reinterpret posted activity. Start after the latest posting on this account.' USING ERRCODE='23514'; END IF;
 ELSE
  IF NEW.fiscal_calendar_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM fiscal_calendars WHERE org_id=NEW.org_id AND id=NEW.fiscal_calendar_id AND is_active) THEN
   RAISE EXCEPTION 'Choose an active fiscal calendar of this organization.' USING ERRCODE='23514'; END IF;
  IF coalesce(NEW.fiscal_calendar_id,(SELECT id FROM fiscal_calendars WHERE org_id=NEW.org_id AND is_default AND is_active)) IS DISTINCT FROM public.subsidiary_posting_calendar(NEW.org_id,NEW.subsidiary_id,NEW.effective_from-1) AND (
    NOT EXISTS(SELECT 1 FROM accounting_periods p WHERE p.org_id=NEW.org_id AND p.fiscal_calendar_id=coalesce(NEW.fiscal_calendar_id,(SELECT id FROM fiscal_calendars WHERE org_id=NEW.org_id AND is_default AND is_active)) AND NOT p.is_adjustment AND p.starts_on=NEW.effective_from)
    OR EXISTS(SELECT 1 FROM accounting_periods p WHERE p.org_id=NEW.org_id AND p.fiscal_calendar_id=public.subsidiary_posting_calendar(NEW.org_id,NEW.subsidiary_id,NEW.effective_from-1)
      AND NOT p.is_adjustment AND p.starts_on<NEW.effective_from AND p.ends_on>=NEW.effective_from)) THEN
   RAISE EXCEPTION 'Change fiscal calendars at a shared regular-period boundary. Generate the new calendar periods and choose the first day after the old period ends.' USING ERRCODE='23514'; END IF;
  IF NEW.default_journal_form_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM form_layouts WHERE org_id=NEW.org_id AND id=NEW.default_journal_form_id AND record_type='journal' AND is_active) THEN
   RAISE EXCEPTION 'Choose an active journal form of this organization.' USING ERRCODE='23514'; END IF;
  IF NOT EXISTS(SELECT 1 FROM fx_rate_types WHERE org_id=NEW.org_id AND key=NEW.posting_rate_type AND is_active) THEN
   RAISE EXCEPTION 'Choose an active posting exchange-rate type.' USING ERRCODE='23514'; END IF;
  IF EXISTS(SELECT 1 FROM journal_lines l JOIN journal_entries e ON e.org_id=l.org_id AND e.id=l.entry_id
    WHERE l.org_id=NEW.org_id AND l.subsidiary_id=NEW.subsidiary_id AND e.status IN('posted','reversed') AND e.posting_date>=NEW.effective_from) THEN
   RAISE EXCEPTION 'An entity preference cannot reinterpret posted activity. Start after the latest posting for this entity.' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: financial_rate_quote_type_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.financial_rate_quote_type_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM fx_rate_types WHERE org_id=NEW.org_id AND key=NEW.rate_type AND is_active) THEN
  RAISE EXCEPTION 'Choose an active registered exchange-rate type in Setup.' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: financial_rate_type_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.financial_rate_type_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('openbooks:ledger-setup:'||NEW.org_id,0));
 IF TG_OP='UPDATE' AND (NEW.org_id<>OLD.org_id OR NEW.key<>OLD.key) THEN
  RAISE EXCEPTION 'A named exchange-rate series retains its organization and key.' USING ERRCODE='23514'; END IF;
 IF NOT NEW.is_active AND (NEW.key IN('spot','average','historical') OR EXISTS(
  SELECT 1 FROM subsidiary_accounting_preferences p WHERE p.org_id=NEW.org_id AND p.posting_rate_type=NEW.key
   AND NOT EXISTS(SELECT 1 FROM subsidiary_accounting_preferences next WHERE next.org_id=p.org_id AND next.subsidiary_id=p.subsidiary_id
     AND next.effective_from>p.effective_from AND next.effective_from<=current_date))) THEN
  RAISE EXCEPTION 'An authoritative exchange-rate series cannot be deactivated. Record and activate successor entity preferences first.' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: fixed_asset_capitalization_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fixed_asset_capitalization_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF coalesce(current_setting('openbooks.amend', true), 'off') = 'on'
     OR coalesce(current_setting('openbooks.asset_cip_ledger', true), 'off') = 'on' THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.status IN ('construction', 'capitalized') THEN
      RAISE EXCEPTION 'create construction in progress from Fixed Assets → Construction in progress' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;
  IF (OLD.status IN ('construction', 'capitalized') OR NEW.status IN ('construction', 'capitalized'))
     AND (NEW.status IS DISTINCT FROM OLD.status
       OR NEW.acquisition_cost IS DISTINCT FROM OLD.acquisition_cost
       OR NEW.asset_account_id IS DISTINCT FROM OLD.asset_account_id
       OR NEW.subsidiary_id IS DISTINCT FROM OLD.subsidiary_id) THEN
    RAISE EXCEPTION 'construction-in-progress cost moves only through linked costs and governed capitalization' USING ERRCODE = '23514';
  END IF;
  IF (NEW.acquisition_cost IS DISTINCT FROM OLD.acquisition_cost
      OR NEW.category_id IS DISTINCT FROM OLD.category_id
      OR NEW.asset_account_id IS DISTINCT FROM OLD.asset_account_id
      OR NEW.subsidiary_id IS DISTINCT FROM OLD.subsidiary_id)
     AND (EXISTS (SELECT 1 FROM public.asset_proposal_allocations al
                    JOIN public.asset_proposal_acceptances ac ON ac.org_id = al.org_id AND ac.id = al.acceptance_id
                   WHERE al.org_id = OLD.org_id AND al.asset_id = OLD.id AND al.cip_cost_id IS NULL AND ac.status = 'posted')
       OR EXISTS (SELECT 1 FROM public.asset_cip_capitalization_lines cl
                    JOIN public.asset_cip_capitalizations k ON k.org_id = cl.org_id AND k.id = cl.capitalization_id
                   WHERE cl.org_id = OLD.org_id AND cl.asset_id = OLD.id AND k.status = 'posted')) THEN
    RAISE EXCEPTION 'this asset''s cost was capitalized from posted transactions; reverse the acceptance or capitalization to change its cost, category, account or legal entity' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fixed_asset_component_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fixed_asset_component_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  parent record;
BEGIN
  IF coalesce(current_setting('openbooks.amend', true), 'off') = 'on' THEN
    RETURN NEW;
  END IF;
  IF NEW.parent_asset_id IS NOT NULL THEN
    SELECT p.id, p.subsidiary_id, p.parent_asset_id, p.status INTO parent
      FROM public.fixed_assets p
     WHERE p.org_id = NEW.org_id AND p.id = NEW.parent_asset_id
       FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'the parent asset does not exist in this organization' USING ERRCODE = '23503';
    END IF;
    IF parent.parent_asset_id IS NOT NULL THEN
      RAISE EXCEPTION 'a component cannot own components; attach it to the top-level parent asset' USING ERRCODE = '23514';
    END IF;
    IF parent.subsidiary_id IS DISTINCT FROM NEW.subsidiary_id THEN
      RAISE EXCEPTION 'a component must belong to the same legal entity as its parent asset' USING ERRCODE = '23514';
    END IF;
    IF parent.status IN ('construction', 'capitalized') OR NEW.status IN ('construction', 'capitalized') THEN
      RAISE EXCEPTION 'construction-in-progress records cannot own or be components' USING ERRCODE = '23514';
    END IF;
    IF (TG_OP = 'INSERT' OR NEW.parent_asset_id IS DISTINCT FROM OLD.parent_asset_id)
       AND parent.status IN ('disposed', 'written_off') THEN
      RAISE EXCEPTION 'components cannot be added to a disposed or written-off asset' USING ERRCODE = '23514';
    END IF;
    IF EXISTS (SELECT 1 FROM public.fixed_assets c WHERE c.org_id = NEW.org_id AND c.parent_asset_id = NEW.id) THEN
      RAISE EXCEPTION 'an asset that owns components cannot itself become a component' USING ERRCODE = '23514';
    END IF;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.subsidiary_id IS DISTINCT FROM OLD.subsidiary_id
     AND EXISTS (SELECT 1 FROM public.fixed_assets c WHERE c.org_id = NEW.org_id AND c.parent_asset_id = NEW.id) THEN
    RAISE EXCEPTION 'an asset with components cannot change legal entity; detach or transfer its components first' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fixed_asset_configuration_org_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fixed_asset_configuration_org_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  method_id uuid;
  account_ids uuid[];
begin
  if tg_table_name = 'asset_categories' then
    method_id := new.default_depreciation_method_id;
  elsif tg_table_name = 'fixed_assets' then
    method_id := new.depreciation_method_id;
    account_ids := array_remove(array[new.asset_account_id, new.accumulated_depreciation_account_id, new.depreciation_expense_account_id], null);
  elsif tg_table_name in ('depreciation_schedules', 'depreciation_book_policies') then
    method_id := new.depreciation_method_id;
  end if;
  if method_id is not null and not exists (
    select 1 from depreciation_methods m where m.id = method_id and m.org_id = new.org_id and m.is_active
  ) then
    raise exception 'depreciation method must be active and belong to the tenant';
  end if;
  if cardinality(account_ids) > 0 and exists (
    select 1 from unnest(account_ids) wanted(id)
     where not exists (select 1 from accounts a where a.id = wanted.id and a.org_id = new.org_id and a.is_active and not a.is_summary)
  ) then
    raise exception 'fixed asset account override must be an active postable account in the tenant';
  end if;
  return new;
end $$;


--
-- Name: flow_clone_evidence(jsonb, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flow_clone_evidence(value jsonb, seed uuid, field_name text DEFAULT ''::text, target_org uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE result jsonb; item record; scalar text; identity_field boolean;
BEGIN
 IF value IS NULL THEN RETURN NULL; END IF;
 IF jsonb_typeof(value)='string' THEN
  scalar:=value#>>'{}';
  IF field_name='intent' THEN
   BEGIN RETURN to_jsonb(public.production_canonical_json(public.flow_clone_evidence(scalar::jsonb,seed,'',target_org)));
   EXCEPTION WHEN invalid_text_representation THEN RETURN value; END;
  END IF;
  identity_field:=field_name='id' OR field_name~'(Id|Ids|_id|_ids|By|_by)$'
    OR field_name IN('requestKey','subcontract_consumption_key');
  IF identity_field AND field_name NOT IN('nodeId','node_id')
    AND scalar~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
   IF field_name IN('orgId','org_id') AND target_org IS NOT NULL THEN RETURN to_jsonb(target_org::text); END IF;
   RETURN to_jsonb(public.ob_rebase(scalar::uuid,seed)::text);
  END IF;
 ELSIF jsonb_typeof(value)='array' THEN
  SELECT coalesce(jsonb_agg(public.flow_clone_evidence(element,seed,field_name,target_org) ORDER BY ordinal),'[]'::jsonb)
    INTO result FROM jsonb_array_elements(value) WITH ORDINALITY entries(element,ordinal);
  RETURN result;
 ELSIF jsonb_typeof(value)='object' THEN
  result:='{}'::jsonb;
  FOR item IN SELECT key,entry FROM jsonb_each(value) entries(key,entry) LOOP
   result:=result||jsonb_build_object(CASE WHEN field_name='material_usage_variance_delta_by_component'
     AND item.key~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     THEN public.ob_rebase(item.key::uuid,seed)::text ELSE item.key END,CASE
    WHEN item.key IN('id','source','target') AND field_name IN('nodes','edges') THEN item.entry
    WHEN item.key='custom' THEN item.entry
    ELSE public.flow_clone_evidence(item.entry,seed,item.key,target_org) END);
  END LOOP;
  RETURN result;
 END IF;
 RETURN value;
END $_$;


--
-- Name: flow_command_authorized(uuid, text, uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flow_command_authorized(organization uuid, kind text, subject uuid, actor uuid, fingerprint text, expected_command jsonb DEFAULT NULL::jsonb) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 SELECT EXISTS(SELECT 1 FROM public.flow_submissions s WHERE s.org_id=organization AND s.subject_kind=kind AND s.subject_id=subject
   AND s.context->>'approvalFingerprint'=fingerprint AND (expected_command IS NULL OR s.context->'command' @> expected_command)
   AND NOT EXISTS(SELECT 1 FROM public.flow_submissions newer WHERE newer.org_id=s.org_id AND newer.subject_kind=s.subject_kind
     AND newer.subject_id=s.subject_id AND (newer.created_at,newer.id)>(s.created_at,s.id))
   AND NOT EXISTS(SELECT 1 FROM public.flow_gates g WHERE g.org_id=s.org_id AND g.subject_kind=s.subject_kind
     AND g.subject_id=s.subject_id AND g.status IN('pending','escalated'))
   AND ((s.policy->>'kind'='ungated' AND public.flow_ungated_submission_authorized(s.org_id,s.subject_kind,s.subject_id,actor))
    OR (s.policy->>'kind'='gated' AND public.flow_submission_approved(s.org_id,s.subject_kind,s.subject_id,s.id) AND EXISTS(SELECT 1 FROM public.flow_gates g JOIN public.flow_runs r ON r.org_id=g.org_id AND r.id=g.run_id
      WHERE g.org_id=s.org_id AND g.subject_kind=s.subject_kind AND g.subject_id=s.subject_id AND s.policy->'runIds' ? r.id::text
        AND g.status='approved' AND g.decided_by=actor AND r.context->>'approvalFingerprint'=fingerprint
        AND (actor<>s.actor_id OR EXISTS(SELECT 1 FROM jsonb_array_elements(r.context->'submissionPolicy'->'graph'->'nodes') node
          WHERE node->>'id'=g.node_id AND node->'data'->>'kind'='gate' AND node->'data'->'gate'->'preventSelfApproval'='false'::jsonb))))))
$$;


--
-- Name: flow_command_record_fingerprint(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flow_command_record_fingerprint(record jsonb, dependencies jsonb DEFAULT NULL::jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 SELECT encode(sha256(convert_to(((record-ARRAY['status','lifecycle','approval_status','updated_at','updated_by',
   'approved_at','approved_by','submitted_at','submitted_by'])||jsonb_build_object('dependencies',dependencies))::text,'UTF8')),'hex')
$$;


--
-- Name: flow_gate_escalation_lineage_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flow_gate_escalation_lineage_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' THEN
  IF ROW(NEW.id,NEW.org_id,NEW.flow_id,NEW.run_id,NEW.node_id,NEW.subject_kind,NEW.subject_id,
      NEW.group_key,NEW.quorum,NEW.signature_required,NEW.created_by,NEW.created_at,NEW.escalated_from_gate_id)
     IS DISTINCT FROM ROW(OLD.id,OLD.org_id,OLD.flow_id,OLD.run_id,OLD.node_id,OLD.subject_kind,OLD.subject_id,
      OLD.group_key,OLD.quorum,OLD.signature_required,OLD.created_by,OLD.created_at,OLD.escalated_from_gate_id) THEN
   RAISE EXCEPTION 'A gate retains its submitted policy, subject and escalation lineage.' USING ERRCODE='23514';
  END IF;
  IF OLD.decided_at IS NOT NULL AND ROW(NEW.status,NEW.decided_by,NEW.decided_at,NEW.signature,NEW.comment,NEW.on_behalf_of_user_id)
     IS DISTINCT FROM ROW(OLD.status,OLD.decided_by,OLD.decided_at,OLD.signature,OLD.comment,OLD.on_behalf_of_user_id) THEN
   RAISE EXCEPTION 'A recorded gate decision is immutable.' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.flow_runs r,
    LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(r.context #> '{submissionPolicy,graph,nodes}')='array'
      THEN r.context #> '{submissionPolicy,graph,nodes}' ELSE '[]'::jsonb END) node
   WHERE r.org_id=NEW.org_id AND r.id=NEW.run_id AND r.flow_id=NEW.flow_id
    AND r.subject_kind=NEW.subject_kind AND r.subject_id=NEW.subject_id
    AND r.context #>> '{submissionPolicy,flowId}'=r.flow_id::text
    AND node->>'id'=NEW.node_id AND node->'data'->>'kind'='gate'
    AND node #>> '{data,gate,mode}'=NEW.quorum
    AND coalesce((node #>> '{data,gate,signatureRequired}')::boolean,false)=NEW.signature_required
    AND NEW.group_key=NEW.run_id::text || ':' || NEW.node_id) THEN
  RAISE EXCEPTION 'The approval gate must match its frozen Flow policy and subject.' USING ERRCODE='23514';
 END IF;
 IF NEW.escalated_from_gate_id IS NOT NULL AND NOT EXISTS(
   SELECT 1 FROM public.flow_gates parent WHERE parent.org_id=NEW.org_id AND parent.id=NEW.escalated_from_gate_id
     AND parent.run_id=NEW.run_id AND parent.flow_id=NEW.flow_id AND parent.node_id=NEW.node_id
     AND parent.group_key=NEW.group_key AND parent.quorum=NEW.quorum AND parent.status='escalated') THEN
  RAISE EXCEPTION 'An escalation replacement must retain its native gate group and replaced decision.';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: flow_portal_return_source_valid(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flow_portal_return_source_valid(target_org uuid, target_document uuid, request jsonb) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 PERFORM l.id FROM public.documents d
 JOIN public.customer_portal_links l ON l.org_id=d.org_id AND l.party_id=d.party_id
   AND l.id::text=request->>'linkId'
 WHERE d.org_id=target_org AND d.id=target_document AND d.kind='rma'
   AND d.custom->'portalRequest' IS NOT DISTINCT FROM request
   AND request->>'partyId'=d.party_id::text
   AND l.purpose='session' AND l.consumed_at IS NULL AND l.expires_at>now()
 FOR SHARE OF l;
 RETURN FOUND;
END $$;


--
-- Name: flow_run_policy_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flow_run_policy_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF ROW(NEW.id,NEW.org_id,NEW.flow_id,NEW.subject_kind,NEW.subject_id,NEW.trigger,
    NEW.created_by,NEW.created_at,NEW.started_at,NEW.occurrence_key)
   IS DISTINCT FROM ROW(OLD.id,OLD.org_id,OLD.flow_id,OLD.subject_kind,OLD.subject_id,OLD.trigger,
    OLD.created_by,OLD.created_at,OLD.started_at,OLD.occurrence_key)
   OR (NEW.context-ARRAY['approvalContinuation','submissionRouting','event_source'])
     IS DISTINCT FROM (OLD.context-ARRAY['approvalContinuation','submissionRouting','event_source']) THEN
  RAISE EXCEPTION 'The submitted Flow identity, policy and record facts are immutable. Withdraw and resubmit the record to change them.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: flow_subject_decision_authorized(uuid, text, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flow_subject_decision_authorized(organization uuid, kind text, subject uuid, actor uuid, fingerprint text, outcome text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 SELECT EXISTS(SELECT 1 FROM public.flow_submissions s WHERE s.org_id=organization AND s.subject_kind=kind AND s.subject_id=subject
  AND s.context->>'approvalFingerprint'=fingerprint
  AND NOT EXISTS(SELECT 1 FROM public.flow_submissions newer WHERE newer.org_id=s.org_id AND newer.subject_kind=s.subject_kind
    AND newer.subject_id=s.subject_id AND (newer.created_at,newer.id)>(s.created_at,s.id))
  AND NOT EXISTS(SELECT 1 FROM public.flow_gates g WHERE g.org_id=s.org_id AND g.subject_kind=s.subject_kind AND g.subject_id=s.subject_id AND g.status IN('pending','escalated'))
  AND ((outcome='approved' AND s.policy->>'kind'='ungated' AND public.flow_ungated_submission_authorized(s.org_id,s.subject_kind,s.subject_id,actor))
   OR (s.policy->>'kind'='gated' AND (outcome='rejected' OR outcome='approved' AND public.flow_submission_approved(s.org_id,s.subject_kind,s.subject_id,s.id))
    AND EXISTS(SELECT 1 FROM public.flow_gates g JOIN public.flow_runs r ON r.org_id=g.org_id AND r.id=g.run_id
     WHERE g.org_id=s.org_id AND g.subject_kind=s.subject_kind AND g.subject_id=s.subject_id AND s.policy->'runIds' ? r.id::text
       AND g.status=outcome AND g.decided_by=actor AND r.status IN('waiting','completed') AND r.error IS NULL
       AND (actor<>s.actor_id OR EXISTS(SELECT 1 FROM jsonb_array_elements(r.context->'submissionPolicy'->'graph'->'nodes') node
        WHERE node->>'id'=g.node_id AND node->'data'->>'kind'='gate' AND node->'data'->'gate'->'preventSelfApproval'='false'::jsonb))))))
$$;


--
-- Name: flow_submission_approved(uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flow_submission_approved(organization uuid, kind text, subject uuid, submission uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 SELECT EXISTS(SELECT 1 FROM public.flow_submissions s WHERE s.org_id=organization AND s.subject_kind=kind
  AND s.subject_id=subject AND s.id=submission AND s.policy->>'kind'='gated'
  AND public.flow_submission_runs_valid(s.org_id,s.subject_kind,s.subject_id,s.id)
  AND NOT EXISTS(SELECT 1 FROM public.flow_submissions newer WHERE newer.org_id=s.org_id AND newer.subject_kind=s.subject_kind
    AND newer.subject_id=s.subject_id AND (newer.created_at,newer.id)>(s.created_at,s.id))
  AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(s.policy->'runIds') run_ref(value) WHERE NOT EXISTS(
    SELECT 1 FROM public.flow_runs r WHERE r.org_id=s.org_id AND r.id::text=run_ref.value AND r.subject_kind=s.subject_kind
      AND r.subject_id=s.subject_id AND r.status IN('waiting','completed') AND r.error IS NULL))
  AND NOT EXISTS(SELECT 1 FROM public.flow_gates g WHERE g.org_id=s.org_id AND s.policy->'runIds' ? g.run_id::text
    AND g.status IN('pending','escalated','rejected'))
  AND NOT EXISTS(SELECT 1 FROM public.flow_gates g WHERE g.org_id=s.org_id AND s.policy->'runIds' ? g.run_id::text
    GROUP BY g.run_id,g.group_key HAVING CASE
      WHEN bool_and(g.quorum='all') THEN NOT bool_and(g.status='approved'
        OR (g.status='cancelled' AND EXISTS(SELECT 1 FROM public.flow_gates replacement
          WHERE replacement.org_id=g.org_id AND replacement.escalated_from_gate_id=g.id
            AND replacement.run_id=g.run_id AND replacement.group_key=g.group_key AND replacement.status='approved')))
      WHEN bool_and(g.quorum='any') THEN NOT bool_or(g.status='approved') ELSE true END)
  AND EXISTS(SELECT 1 FROM public.flow_gates g WHERE g.org_id=s.org_id AND s.policy->'runIds' ? g.run_id::text AND g.status='approved'))
$$;


--
-- Name: flow_submission_policy_valid(uuid, text, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flow_submission_policy_valid(organization uuid, subject_kind text, subject_id uuid, actor uuid, policy jsonb) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 SELECT coalesce(
  policy->'version'='1'::jsonb AND policy->>'trigger' IN('on_submit','on_create','on_update') AND policy->>'kind' IN('gated','ungated')
  AND policy-ARRAY['version','trigger','kind','flowIds','runIds']='{}'::jsonb
  AND jsonb_typeof(policy->'flowIds')='array' AND jsonb_typeof(policy->'runIds')='array'
  AND policy->'flowIds'=(SELECT coalesce(jsonb_agg(f.id::text ORDER BY f.id),'[]'::jsonb)
    FROM public.flows f WHERE f.org_id=organization AND f.subject_kind=flow_submission_policy_valid.subject_kind AND f.enabled)
  AND (SELECT count(*) FROM jsonb_array_elements(policy->'runIds'))=
      (SELECT count(DISTINCT value) FROM jsonb_array_elements(policy->'runIds'))
  AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(policy->'runIds') run_id
    WHERE NOT EXISTS(SELECT 1 FROM public.flow_runs r WHERE r.org_id=organization
      AND r.id::text=run_id AND r.subject_kind=flow_submission_policy_valid.subject_kind
      AND r.subject_id=flow_submission_policy_valid.subject_id AND r.trigger=policy->>'trigger'
      AND r.created_by IS NOT DISTINCT FROM actor AND r.error IS NULL AND r.status IN('completed','waiting')
      AND policy->'flowIds' ? r.flow_id::text))
  AND CASE WHEN policy->>'kind'='gated' THEN EXISTS(SELECT 1 FROM public.flow_gates g
    WHERE g.org_id=organization AND policy->'runIds' ? g.run_id::text AND g.status IN('pending','escalated'))
   ELSE NOT EXISTS(SELECT 1 FROM public.flow_gates g WHERE g.org_id=organization
      AND ((g.subject_kind=flow_submission_policy_valid.subject_kind AND g.subject_id=flow_submission_policy_valid.subject_id
        AND g.status IN('pending','escalated')) OR policy->'runIds' ? g.run_id::text))
    AND NOT EXISTS(SELECT 1 FROM public.flow_runs r WHERE r.org_id=organization
      AND policy->'runIds' ? r.id::text AND r.status<>'completed') END,
 false);
$$;


--
-- Name: flow_submission_receipt_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flow_submission_receipt_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
BEGIN
 IF TG_OP='DELETE' THEN
  IF tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD))
    OR public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'Flow submission evidence is immutable.';
 END IF;
 IF TG_OP='UPDATE' THEN RAISE EXCEPTION 'Flow submission evidence is immutable.'; END IF;
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF NEW.actor_id IS NOT NULL THEN
  IF NOT EXISTS(SELECT 1 FROM public.users u WHERE u.org_id=NEW.org_id AND u.id=NEW.actor_id AND u.is_active) THEN
   IF coalesce(NEW.context->>'submissionActorHomeOrgId','') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN
    RAISE EXCEPTION 'The Flow submission requires its established active acting identity.' USING ERRCODE='23514';
   END IF;
   PERFORM public.lock_actor_home_identity(NEW.org_id,NEW.actor_id,(NEW.context->>'submissionActorHomeOrgId')::uuid);
  END IF;
 END IF;
 IF (NEW.actor_id IS NULL AND NOT (
     NEW.context->>'event_source' IS NOT DISTINCT FROM 'schedule'
     OR (NEW.context->>'event_source' IS NOT DISTINCT FROM 'portal'
       AND NEW.subject_kind='rma' AND public.flow_portal_return_source_valid(NEW.org_id,NEW.subject_id,NEW.context->'portalRequest'))
     OR (NEW.context->>'event_source' IS NOT DISTINCT FROM 'sync'
       AND NEW.subject_kind IN ('cash_sale','cash_refund')
       AND EXISTS(SELECT 1 FROM public.documents d JOIN public.sales_channels c
         ON c.org_id=d.org_id AND c.id=d.source_channel_id AND c.kind=d.external_source
         WHERE d.org_id=NEW.org_id AND d.id=NEW.subject_id AND d.kind=NEW.subject_kind
           AND nullif(btrim(d.external_ref),'') IS NOT NULL AND c.status='active'))
   ))
   OR NOT public.flow_submission_policy_valid(NEW.org_id,NEW.subject_kind,NEW.subject_id,NEW.actor_id,NEW.policy)
   OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(NEW.policy->'runIds') claimed(id)
     WHERE NOT EXISTS(SELECT 1 FROM public.flow_runs r,
       LATERAL jsonb_array_elements(NEW.graphs) snapshot
       WHERE r.org_id=NEW.org_id AND r.id::text=claimed.id
        AND r.context #>> '{submissionPolicy,flowId}'=r.flow_id::text
        AND snapshot->>'id'=r.flow_id::text
        AND snapshot->'graph'=r.context #> '{submissionPolicy,graph}'))
   OR NEW.graphs IS DISTINCT FROM (SELECT coalesce(jsonb_agg(jsonb_build_object('id',f.id,'graph',f.graph) ORDER BY f.id),'[]'::jsonb)
     FROM public.flows f WHERE f.org_id=NEW.org_id AND f.subject_kind=NEW.subject_kind AND f.enabled) THEN
  RAISE EXCEPTION 'The Flow submission requires complete routing evidence and the current graph snapshots.';
 END IF;
 RETURN NEW;
END $_$;


--
-- Name: flow_submission_runs_valid(uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flow_submission_runs_valid(organization uuid, kind text, subject uuid, submission uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 SELECT EXISTS(SELECT 1 FROM public.flow_submissions s WHERE s.org_id=organization
  AND s.subject_kind=kind AND s.subject_id=subject AND s.id=submission
  AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(s.policy->'runIds') claimed(id)
    WHERE NOT EXISTS(SELECT 1 FROM public.flow_runs r,
      LATERAL jsonb_array_elements(s.graphs) snapshot
      WHERE r.org_id=s.org_id AND r.id::text=claimed.id AND r.subject_kind=s.subject_kind
       AND r.subject_id=s.subject_id AND r.trigger=s.policy->>'trigger'
       AND r.created_by IS NOT DISTINCT FROM s.actor_id
       AND s.policy->'flowIds' ? r.flow_id::text
       AND r.context #>> '{submissionPolicy,flowId}'=r.flow_id::text
       AND snapshot->>'id'=r.flow_id::text
       AND snapshot->'graph'=r.context #> '{submissionPolicy,graph}')))
$$;


--
-- Name: flow_ungated_submission_authorized(uuid, text, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flow_ungated_submission_authorized(organization uuid, kind text, subject uuid, actor uuid, expected_context jsonb DEFAULT '{}'::jsonb) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT 1 FROM public.flow_submissions s WHERE s.org_id=organization AND s.subject_kind=kind
   AND s.subject_id=subject AND s.actor_id IS NOT DISTINCT FROM actor AND s.policy->>'kind'='ungated' AND s.context @> expected_context
   AND public.flow_submission_runs_valid(s.org_id,s.subject_kind,s.subject_id,s.id)
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(s.policy->'runIds') run_id WHERE NOT EXISTS(
     SELECT 1 FROM public.flow_runs r WHERE r.org_id=s.org_id AND r.id::text=run_id
       AND r.subject_kind=s.subject_kind AND r.subject_id=s.subject_id AND r.status='completed' AND r.error IS NULL))
   AND NOT EXISTS(SELECT 1 FROM public.flow_gates g WHERE g.org_id=s.org_id AND s.policy->'runIds' ? g.run_id::text)
   AND NOT EXISTS(SELECT 1 FROM public.flow_submissions later WHERE later.org_id=s.org_id AND later.subject_kind=s.subject_kind
     AND later.subject_id=s.subject_id AND (later.created_at,later.id)>(s.created_at,s.id))
   AND NOT EXISTS(SELECT 1 FROM public.flow_gates g WHERE g.org_id=s.org_id AND g.subject_kind=s.subject_kind
     AND g.subject_id=s.subject_id AND g.status IN('pending','escalated')));
$$;


--
-- Name: fulfillment_documents_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fulfillment_documents_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  document_kind text;
  document_status text;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    SELECT status INTO document_status
      FROM public.documents WHERE id = OLD.document_id AND org_id = OLD.org_id;
    IF document_status IS NULL OR document_status = 'draft' THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'fulfilment detail of a % document cannot be deleted; void the document instead', document_status
      USING ERRCODE = 'object_not_in_prerequisite_state';
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.stage = 'done' THEN
    RAISE EXCEPTION 'a completed pick list or shipment is final and cannot be changed'
      USING ERRCODE = 'object_not_in_prerequisite_state';
  END IF;
  SELECT kind INTO document_kind
    FROM public.documents WHERE id = NEW.document_id AND org_id = NEW.org_id;
  IF document_kind IS DISTINCT FROM 'pick_list' AND document_kind IS DISTINCT FROM 'shipment' THEN
    RAISE EXCEPTION 'fulfilment detail belongs to a pick list or shipment, not a %', coalesce(document_kind, 'missing document')
      USING ERRCODE = 'check_violation';
  END IF;
  IF document_kind = 'pick_list' AND (
       NEW.carrier_id IS NOT NULL OR NEW.carrier_service IS NOT NULL OR NEW.tracking_number IS NOT NULL
       OR NEW.ship_to_address IS NOT NULL OR NEW.sales_fulfillment_id IS NOT NULL) THEN
    RAISE EXCEPTION 'a pick list carries no carrier, tracking, ship-to address or fulfilment; those belong to its shipment'
      USING ERRCODE = 'check_violation';
  END IF;
  IF document_kind = 'shipment' AND NEW.stage = 'done' AND (
       NEW.carrier_id IS NULL OR NEW.carrier_service IS NULL OR NEW.sales_fulfillment_id IS NULL) THEN
    RAISE EXCEPTION 'a completed shipment names its carrier, service and sales fulfilment'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: fulfillment_execution_policy_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fulfillment_execution_policy_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF NEW.execution_required IS DISTINCT FROM OLD.execution_required THEN
  RAISE EXCEPTION 'Fulfillment execution policy is captured at creation and cannot reinterpret existing work';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: fulfillment_lines_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fulfillment_lines_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  line_document uuid;
  document_kind text;
  document_status text;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    SELECT status INTO document_status
      FROM public.documents WHERE id = OLD.document_id AND org_id = OLD.org_id;
    IF document_status IS NULL OR document_status = 'draft'
       OR NOT EXISTS (SELECT 1 FROM public.document_lines WHERE id = OLD.line_id AND org_id = OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'fulfilment line detail of a % document cannot be deleted; void the document instead', document_status
      USING ERRCODE = 'object_not_in_prerequisite_state';
  END IF;
  SELECT d.kind, d.status INTO document_kind, document_status
    FROM public.documents d WHERE d.id = NEW.document_id AND d.org_id = NEW.org_id;
  IF TG_OP = 'UPDATE' THEN
    IF (NEW.line_id, NEW.org_id, NEW.document_id, NEW.sales_order_line_id, NEW.pick_line_id, NEW.lot_id, NEW.serial_id)
       IS DISTINCT FROM
       (OLD.line_id, OLD.org_id, OLD.document_id, OLD.sales_order_line_id, OLD.pick_line_id, OLD.lot_id, OLD.serial_id) THEN
      RAISE EXCEPTION 'only the carton of a fulfilment line can change'
        USING ERRCODE = 'object_not_in_prerequisite_state';
    END IF;
    IF NEW.carton IS DISTINCT FROM OLD.carton AND document_status IS DISTINCT FROM 'draft' THEN
      RAISE EXCEPTION 'cartons can change only while the shipment is a draft'
        USING ERRCODE = 'object_not_in_prerequisite_state';
    END IF;
    RETURN NEW;
  END IF;
  SELECT document_id INTO line_document
    FROM public.document_lines WHERE id = NEW.line_id AND org_id = NEW.org_id;
  IF line_document IS DISTINCT FROM NEW.document_id THEN
    RAISE EXCEPTION 'fulfilment line detail must sit on the line''s own document'
      USING ERRCODE = 'check_violation';
  END IF;
  IF document_kind = 'pick_list' AND (NEW.pick_line_id IS NOT NULL OR NEW.carton IS NOT NULL) THEN
    RAISE EXCEPTION 'a pick-list line names no pick line and no carton'
      USING ERRCODE = 'check_violation';
  END IF;
  IF document_kind = 'shipment' AND NEW.pick_line_id IS NULL THEN
    RAISE EXCEPTION 'a shipment line names the pick line it ships'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: funds_restriction_class_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.funds_restriction_class_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_line_count bigint;
  v_code text;
begin
  if new.restriction_class is distinct from old.restriction_class then
    select count(*) into v_line_count
      from public.journal_lines l
      join public.journal_entries e on e.org_id = l.org_id and e.id = l.entry_id
     where l.org_id = old.org_id and l.extra_dims->>'fund' = old.id::text
       and e.status is distinct from 'draft';
    if v_line_count > 0 then
      select code into v_code from public.segment_values
       where org_id = old.org_id and id = old.id;
      raise exception 'fund % restriction class cannot change while % posted journal lines carry it',
        coalesce(v_code, old.id::text), v_line_count using errcode = '23514';
    end if;
  end if;
  return new;
end $$;


--
-- Name: funds_segment_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.funds_segment_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_code text;
begin
  select sv.code into v_code
    from public.segment_values sv
    join public.segment_definitions sd
      on sd.org_id = sv.org_id and sd.id = sv.segment_id
   where sv.org_id = new.org_id and sv.id = new.id and sd.key = 'fund'
     and sd.source_kind = 'custom';
  if not found or v_code is null or btrim(v_code) = '' then
    raise exception 'fund % must reference a coded value in the fund segment', new.id
      using errcode = '23514';
  end if;
  return new;
end $$;


--
-- Name: fx_rate_age_policy_history_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fx_rate_age_policy_history_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF public.app_bypass_rls_active() AND coalesce(current_setting('openbooks.amend',true),'off')='on' THEN
   IF TG_OP='DELETE' THEN RETURN OLD; END IF;
   RETURN NEW;
 END IF;
 RAISE EXCEPTION 'FX rate age policy history is preserved; create a new policy with its effective date in Setup → FX Rate Age Policies'
   USING ERRCODE = '23514';
END $$;


--
-- Name: fx_revaluation_rate_evidence_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fx_revaluation_rate_evidence_audit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 -- A copied row's provenance is its exact source match, not a new recording.
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id)
 VALUES (NEW.org_id, 'fx_revaluation_rate_evidence', NEW.id, 'insert',
   jsonb_build_object(
     'before', (SELECT to_jsonb(previous) FROM public.fx_revaluation_rate_evidence previous
                 WHERE previous.org_id = NEW.org_id AND previous.id = NEW.supersedes_id),
     'after', to_jsonb(NEW), 'reason', NEW.reason), NEW.created_by);
 RETURN NEW;
END
$$;


--
-- Name: fx_revaluation_rate_evidence_clone_matches(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fx_revaluation_rate_evidence_clone_matches(candidate jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  target record;
  original jsonb;
  expected jsonb;
  column_row record;
BEGIN
  IF NOT public.openbooks_clone_authority() THEN RETURN false; END IF;
  SELECT org.sandbox_of, org.sandbox_seed, sandbox.masked
    INTO target
    FROM public.orgs org
    JOIN public.sandboxes sandbox
      ON sandbox.org_id = org.id AND sandbox.production_org_id = org.sandbox_of
    JOIN public.orgs production ON production.id = org.sandbox_of AND production.id <> org.id
   WHERE org.id = (candidate->>'org_id')::uuid
     AND org.env_kind = 'sandbox'
     AND org.sandbox_seed IS NOT NULL
     AND sandbox.status IN ('provisioning', 'refreshing');
  IF NOT FOUND THEN RETURN false; END IF;

  SELECT to_jsonb(source)
    INTO original
    FROM public.fx_revaluation_rate_evidence source
   WHERE source.org_id = target.sandbox_of
     AND public.ob_rebase(source.id, target.sandbox_seed) = (candidate->>'id')::uuid;
  IF original IS NULL THEN RETURN false; END IF;

  expected := original;
  FOR column_row IN
    SELECT attribute.attname, attribute.atttypid
      FROM pg_catalog.pg_attribute attribute
     WHERE attribute.attrelid = 'public.fx_revaluation_rate_evidence'::regclass
       AND attribute.attnum > 0 AND NOT attribute.attisdropped
  LOOP
    IF column_row.attname = 'org_id' THEN
      expected := jsonb_set(expected, ARRAY[column_row.attname], to_jsonb((candidate->>'org_id')::uuid));
    ELSIF column_row.atttypid = 'uuid'::regtype
      AND jsonb_typeof(original->column_row.attname) = 'string' THEN
      expected := jsonb_set(expected, ARRAY[column_row.attname], to_jsonb(public.ob_rebase(
        (original->>column_row.attname)::uuid, target.sandbox_seed
      )));
    END IF;
    IF target.masked AND column_row.attname IN ('source', 'reason')
      AND jsonb_typeof(original->column_row.attname) = 'string' THEN
      expected := jsonb_set(expected, ARRAY[column_row.attname], to_jsonb('REDACTED'::text));
    END IF;
  END LOOP;
  RETURN candidate = expected;
END
$$;


--
-- Name: fx_revaluation_rate_evidence_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fx_revaluation_rate_evidence_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
 period_row public.accounting_periods%ROWTYPE;
 predecessor public.fx_revaluation_rate_evidence%ROWTYPE;
 measured text;
BEGIN
 IF TG_OP = 'INSERT' AND public.fx_revaluation_rate_evidence_clone_matches(to_jsonb(NEW)) THEN
  RETURN NEW;
 END IF;
 IF TG_OP = 'DELETE' THEN
  IF tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD))
     OR public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
   RETURN OLD;
  END IF;
  RAISE EXCEPTION 'Closing exchange rate evidence is append-only; record a successor version with its reason instead of deleting a quote'
   USING ERRCODE = '23514';
 END IF;
 IF TG_OP = 'UPDATE' THEN
  RAISE EXCEPTION 'Closing exchange rate evidence is append-only; record a successor version with its reason instead of replacing a quote'
   USING ERRCODE = '23514';
 END IF;
 -- One writer at a time per exact position, so root creation and successor
 -- appends cannot interleave into two current versions.
 PERFORM pg_advisory_xact_lock(hashtextextended(
  'fx-revaluation-evidence:' || NEW.org_id::text || ':' || NEW.book_id::text || ':'
  || NEW.subsidiary_id::text || ':' || NEW.period_id::text || ':' || NEW.account_id::text || ':'
  || NEW.transaction_currency, 0));
 IF NOT EXISTS (SELECT 1 FROM public.accounting_books
   WHERE org_id = NEW.org_id AND id = NEW.book_id AND is_active AND posts_gl) THEN
  RAISE EXCEPTION 'Closing exchange rate evidence requires an active posting book in this organization'
   USING ERRCODE = '23514';
 END IF;
 IF NOT EXISTS (SELECT 1 FROM public.subsidiaries
   WHERE org_id = NEW.org_id AND id = NEW.subsidiary_id AND is_active AND NOT is_elimination) THEN
  RAISE EXCEPTION 'Closing exchange rate evidence requires an active legal entity in this organization'
   USING ERRCODE = '23514';
 END IF;
 SELECT * INTO period_row FROM public.accounting_periods
  WHERE org_id = NEW.org_id AND id = NEW.period_id;
 IF period_row.id IS NULL THEN
  RAISE EXCEPTION 'Closing exchange rate evidence requires an assigned accounting period in this organization'
   USING ERRCODE = '23514';
 END IF;
 IF period_row.ends_on IS DISTINCT FROM NEW.rate_date THEN
  RAISE EXCEPTION 'The closing exchange rate must be dated %, the final day of its assigned period', period_row.ends_on
   USING ERRCODE = '23514';
 END IF;
 IF NOT EXISTS (SELECT 1 FROM public.accounts a
   WHERE a.org_id = NEW.org_id AND a.id = NEW.account_id AND a.is_active AND NOT a.is_summary
     AND (CASE
       WHEN a.monetary IS FALSE THEN false
       WHEN a.monetary IS TRUE THEN a.type NOT IN
         ('income', 'income_other', 'cogs', 'expense', 'expense_other', 'expense_deferred', 'equity')
       ELSE a.type IN ('asset_bank', 'asset_receivable', 'liability_payable')
     END)) THEN
  RAISE EXCEPTION 'Closing exchange rate evidence requires an active monetary account in this organization'
   USING ERRCODE = '23514';
 END IF;
 measured := public.accounting_book_currency(NEW.org_id, NEW.book_id, NEW.subsidiary_id);
 IF measured IS NULL OR measured IS DISTINCT FROM NEW.measurement_currency THEN
  RAISE EXCEPTION 'The closing exchange rate must convert into %, the currency this book measures the legal entity in', measured
   USING ERRCODE = '23514';
 END IF;
 IF NEW.supersedes_id IS NULL THEN
  IF EXISTS (SELECT 1 FROM public.fx_revaluation_rate_evidence
    WHERE org_id = NEW.org_id AND book_id = NEW.book_id AND subsidiary_id = NEW.subsidiary_id
      AND period_id = NEW.period_id AND account_id = NEW.account_id
      AND transaction_currency = NEW.transaction_currency) THEN
   RAISE EXCEPTION 'This closing position already has recorded rate evidence; append a successor to its current version'
    USING ERRCODE = '23514';
  END IF;
 ELSE
  SELECT * INTO predecessor FROM public.fx_revaluation_rate_evidence
   WHERE org_id = NEW.org_id AND id = NEW.supersedes_id;
  IF predecessor.id IS NULL
     OR (predecessor.book_id, predecessor.subsidiary_id, predecessor.period_id, predecessor.account_id,
         predecessor.transaction_currency)
        IS DISTINCT FROM
        (NEW.book_id, NEW.subsidiary_id, NEW.period_id, NEW.account_id,
         NEW.transaction_currency)
     OR NEW.version <> predecessor.version + 1 THEN
   RAISE EXCEPTION 'A successor closing rate must keep its predecessor''s exact book, legal entity, period, account and transaction currency, and add one version'
    USING ERRCODE = '23514';
  END IF;
  IF EXISTS (SELECT 1 FROM public.fx_revaluation_rate_evidence
    WHERE org_id = NEW.org_id AND supersedes_id = NEW.supersedes_id) THEN
   RAISE EXCEPTION 'This closing rate version already has a successor; append to the current version instead'
    USING ERRCODE = '23514';
  END IF;
 END IF;
 RETURN NEW;
END
$$;


--
-- Name: gl_audit_number_assignment_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gl_audit_number_assignment_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE policy gl_audit_number_policies%ROWTYPE; period accounting_periods%ROWTYPE; expected_scope text;
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN
  IF public.financial_history_native_clone_matches(TG_RELID,to_jsonb(NEW)) THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'Financial history clone admission requires the exact registered source row, seed and destination parents.' USING ERRCODE='23514';
 END IF;
 PERFORM period_posting_fence(NEW.org_id,NEW.period_id,NEW.book_id);
 IF NOT public.period_module_blocks_write(NEW.org_id,NEW.period_id,NEW.book_id,NEW.subsidiary_id,'gl',false) THEN
  RAISE EXCEPTION 'GL audit numbers require a closed entity accounting period.' USING ERRCODE='23514'; END IF;
 SELECT * INTO STRICT period FROM accounting_periods WHERE org_id=NEW.org_id AND id=NEW.period_id;
 SELECT * INTO policy FROM gl_audit_number_policies WHERE org_id=NEW.org_id AND subsidiary_id=NEW.subsidiary_id AND effective_from<=period.ends_on ORDER BY effective_from DESC LIMIT 1;
 expected_scope:=CASE policy.reset_rule WHEN 'period' THEN 'period:'||period.id WHEN 'fiscal_year' THEN 'year:'||period.fiscal_calendar_id||':'||period.fiscal_year ELSE 'all' END;
 IF policy.id IS NULL OR NEW.policy_id<>policy.id OR NEW.scope_key<>expected_scope OR
    NEW.audit_number<>policy.prefix||'-'||replace(expected_scope,':','-')||'-'||lpad(NEW.ordinal::text,greatest(6,length(NEW.ordinal::text)),'0') THEN
  RAISE EXCEPTION 'GL audit numbers retain the effective entity policy and canonical sequence format.' USING ERRCODE='23514'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('gl-audit:'||NEW.org_id||':'||NEW.book_id||':'||NEW.subsidiary_id||':'||expected_scope,0));
 IF NOT EXISTS(SELECT 1 FROM journal_entries e JOIN journal_lines l ON l.org_id=e.org_id AND l.entry_id=e.id
   WHERE e.org_id=NEW.org_id AND e.id=NEW.entry_id AND e.book_id=NEW.book_id AND e.status IN('posted','reversed')
    AND l.subsidiary_id=NEW.subsidiary_id AND coalesce(l.period_id,e.period_id)=NEW.period_id) THEN
  RAISE EXCEPTION 'An audit number must identify a posted entry in its own entity, period and book.' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM gl_audit_number_assignments WHERE org_id=NEW.org_id AND book_id=NEW.book_id
  AND subsidiary_id=NEW.subsidiary_id AND scope_key=NEW.scope_key AND ordinal>=NEW.ordinal) OR
  NEW.ordinal<>(SELECT coalesce(max(ordinal),0)+1 FROM gl_audit_number_assignments WHERE org_id=NEW.org_id AND book_id=NEW.book_id
   AND subsidiary_id=NEW.subsidiary_id AND scope_key=NEW.scope_key) THEN
  RAISE EXCEPTION 'GL audit numbers are allocated without gaps in their native sequence.' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: gl_audit_number_policy_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gl_audit_number_policy_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN
  IF public.financial_history_native_clone_matches(TG_RELID,to_jsonb(NEW)) THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'Financial history clone admission requires the exact registered source row, seed and destination parents.' USING ERRCODE='23514';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('openbooks:ledger-setup:'||NEW.org_id,0));
 IF EXISTS(SELECT 1 FROM gl_audit_number_assignments n JOIN accounting_periods p ON p.org_id=n.org_id AND p.id=n.period_id
   WHERE n.org_id=NEW.org_id AND n.subsidiary_id=NEW.subsidiary_id AND p.ends_on>=NEW.effective_from) THEN
  RAISE EXCEPTION 'Audit numbering policy changes start after the latest numbered period.' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: goods_tax_registration_history_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.goods_tax_registration_history_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF public.app_bypass_rls_active() AND coalesce(current_setting('openbooks.amend',true),'off')='on' THEN
    IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
  END IF;
  IF EXISTS(SELECT 1 FROM public.document_goods_tax_snapshots proof JOIN public.document_lines l ON l.org_id=proof.org_id AND l.id=proof.document_line_id
    JOIN public.documents d ON d.org_id=l.org_id AND d.id=l.document_id
    WHERE proof.org_id=OLD.org_id AND proof.registration_ids ? OLD.id::text AND d.status IN('posted','voided')
      AND (TG_OP='DELETE' OR (NEW.org_id,NEW.subsidiary_id,NEW.jurisdiction_id,NEW.registration_number,NEW.effective_from)
        IS DISTINCT FROM (OLD.org_id,OLD.subsidiary_id,OLD.jurisdiction_id,OLD.registration_number,OLD.effective_from)
        OR (NEW.effective_to IS NOT NULL AND NEW.effective_to<d.document_date)))
    THEN RAISE EXCEPTION 'used tax registration identity and coverage are immutable; close its future effective window and create a new dated registration'; END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;


--
-- Name: goods_tax_snapshot_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.goods_tax_snapshot_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE document_state text; owner uuid; current_org uuid;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF public.app_bypass_rls_active() AND coalesce(current_setting('openbooks.amend',true),'off')='on' THEN
    IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
  END IF;
  IF TG_OP='UPDATE' THEN RAISE EXCEPTION 'goods tax calculation evidence is immutable; replace the draft line through its native document editor'; END IF;
  IF TG_OP='DELETE' THEN
    SELECT d.status INTO document_state FROM public.document_lines l JOIN public.documents d ON d.org_id=l.org_id AND d.id=l.document_id
      WHERE l.org_id=OLD.org_id AND l.id=OLD.document_line_id;
    IF document_state='draft' OR document_state IS NULL THEN RETURN OLD; END IF;
    RAISE EXCEPTION 'posted goods tax evidence cannot be deleted; use the controlled document reversal workflow';
  END IF;
  SELECT d.status,d.subsidiary_id,d.org_id INTO document_state,owner,current_org FROM public.document_lines l JOIN public.documents d ON d.org_id=l.org_id AND d.id=l.document_id
    WHERE l.org_id=NEW.org_id AND l.id=NEW.document_line_id;
  IF document_state<>'draft' OR owner IS DISTINCT FROM NEW.subsidiary_id OR current_org IS DISTINCT FROM NEW.org_id
    OR NEW.snapshot->>'subsidiaryId'<>NEW.subsidiary_id::text OR NEW.snapshot->>'fingerprint'<>NEW.fingerprint
    OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(NEW.registration_ids) wanted(id) WHERE NOT EXISTS(SELECT 1 FROM public.tax_registrations r
      WHERE r.org_id=NEW.org_id AND r.id=wanted.id::uuid AND r.subsidiary_id=NEW.subsidiary_id))
    THEN RAISE EXCEPTION 'native goods tax evidence must bind to its draft invoice, selling entity and registrations'; END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_recognition_schedule_line_financial_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_recognition_schedule_line_financial_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.journal_entry_id is not null then
    if new.schedule_id is distinct from old.schedule_id
       or new.period_id is distinct from old.period_id
       or new.sequence is distinct from old.sequence
       or new.planned_amount is distinct from old.planned_amount
       or new.recognized_amount is distinct from old.recognized_amount
       or new.journal_entry_id is distinct from old.journal_entry_id then
      raise exception
        'posted revenue-recognition schedule line financial history is immutable';
    end if;
  end if;

  if old.reversal_journal_entry_id is not null
     and new.reversal_journal_entry_id is distinct from old.reversal_journal_entry_id then
    raise exception
      'revenue-recognition reversal lineage is immutable';
  end if;
  return new;
end;
$$;


--
-- Name: handling_unit_content_history_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handling_unit_content_history_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' THEN
  IF public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'Assigned carton contents cannot be deleted'; END IF;
 IF OLD.confirmed_at IS NOT NULL OR (to_jsonb(NEW)-ARRAY['confirmed_at','confirmed_by','confirmation_task_id']) IS DISTINCT FROM
   (to_jsonb(OLD)-ARRAY['confirmed_at','confirmed_by','confirmation_task_id']) OR NEW.confirmed_at IS NULL THEN
  RAISE EXCEPTION 'Carton content identity and confirmed history are immutable'; END IF;
 RETURN NEW;
END $$;


--
-- Name: handling_unit_lifecycle_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handling_unit_lifecycle_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' THEN
  IF public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'Handling-unit history cannot be deleted'; END IF;
 IF (to_jsonb(NEW)-ARRAY['status','current_stock_location_id','content_version','updated_at','updated_by']) IS DISTINCT FROM
   (to_jsonb(OLD)-ARRAY['status','current_stock_location_id','content_version','updated_at','updated_by']) THEN
  RAISE EXCEPTION 'Handling-unit shipment, warehouse and identity are immutable'; END IF;
 IF OLD.status IN('shipped','voided') OR NOT((OLD.status=NEW.status) OR (OLD.status='open' AND NEW.status='packed')
   OR (OLD.status='packed' AND NEW.status='shipped') OR (OLD.status IN('open','packed') AND NEW.status='voided')) THEN RAISE EXCEPTION 'Handling-unit lifecycle transition is not supported'; END IF;
 IF NEW.current_stock_location_id IS DISTINCT FROM OLD.current_stock_location_id AND (OLD.status<>'packed' OR NEW.status<>'packed') THEN
  RAISE EXCEPTION 'Only a packed handling unit can move as one identity'; END IF;
 IF NEW.content_version<OLD.content_version OR NEW.content_version>OLD.content_version+1 THEN
  RAISE EXCEPTION 'Handling-unit content version must advance one confirmed operation at a time'; END IF;
 IF EXISTS(SELECT 1 FROM public.shipment_labels label WHERE label.org_id=OLD.org_id AND label.handling_unit_id=OLD.id AND label.status='purchased')
   AND (NEW.content_version,NEW.current_stock_location_id) IS DISTINCT FROM (OLD.content_version,OLD.current_stock_location_id) THEN
  RAISE EXCEPTION 'Void the handling-unit label before changing its physical contents or position'; END IF;
 RETURN NEW;
END $$;


--
-- Name: handling_unit_posted_state_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handling_unit_posted_state_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE current_unit public.handling_units%ROWTYPE;
BEGIN
 SELECT * INTO current_unit FROM public.handling_units WHERE org_id=NEW.org_id AND id=NEW.id;
 IF NOT FOUND THEN RETURN NEW; END IF;
 IF current_unit.status IN('packed','shipped') AND (NOT EXISTS(SELECT 1 FROM public.handling_unit_contents WHERE org_id=NEW.org_id AND handling_unit_id=NEW.id)
   OR EXISTS(SELECT 1 FROM public.handling_unit_contents content
     LEFT JOIN public.document_lines line ON line.org_id=content.org_id AND line.id=content.shipment_line_id
     LEFT JOIN public.fulfillment_lines fl ON fl.org_id=content.org_id AND fl.line_id=content.shipment_line_id
     WHERE content.org_id=NEW.org_id AND content.handling_unit_id=NEW.id AND (content.confirmed_at IS NULL OR line.id IS NULL OR fl.line_id IS NULL
       OR line.document_id IS DISTINCT FROM NEW.shipment_document_id OR line.item_id IS DISTINCT FROM content.item_id OR line.quantity IS DISTINCT FROM content.document_quantity
       OR line.stock_location_id IS DISTINCT FROM current_unit.current_stock_location_id OR fl.pick_line_id IS DISTINCT FROM content.pick_line_id
       OR fl.carton IS DISTINCT FROM NEW.code OR fl.lot_id IS DISTINCT FROM content.lot_id OR fl.serial_id IS DISTINCT FROM content.serial_id))) THEN
  RAISE EXCEPTION 'Packed handling unit must retain its exact confirmed shipment contents'; END IF;
 IF current_unit.status='shipped' AND NOT EXISTS(SELECT 1 FROM public.documents doc JOIN public.fulfillment_documents fd
    ON fd.org_id=doc.org_id AND fd.document_id=doc.id WHERE doc.org_id=NEW.org_id AND doc.id=NEW.shipment_document_id
    AND doc.kind='shipment' AND doc.status='approved' AND fd.stage='done') THEN
  RAISE EXCEPTION 'A handling unit ships only with its posted shipment'; END IF;
 IF TG_OP='UPDATE' AND NEW.current_stock_location_id IS DISTINCT FROM OLD.current_stock_location_id THEN
  IF NEW.content_version<>OLD.content_version+1 OR NOT EXISTS(SELECT 1 FROM public.handling_unit_moves move
    WHERE move.org_id=NEW.org_id AND move.handling_unit_id=NEW.id AND move.from_stock_location_id=OLD.current_stock_location_id
      AND move.to_stock_location_id=NEW.current_stock_location_id AND move.xmin=(txid_current()%4294967296)::text::xid
      AND public.warehouse_execution_transfer_matches(NEW.org_id,NEW.id,OLD.current_stock_location_id,NEW.current_stock_location_id,move.movements)) THEN
   RAISE EXCEPTION 'Handling-unit position requires its exact current native transfers and movement history'; END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: historical_translation_basis_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.historical_translation_basis_audit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 BEGIN
  INSERT INTO public.audit_log(org_id,table_name,row_id,action,changes,actor_id)
    VALUES(NEW.org_id,'historical_translation_contributions',NEW.id,'insert',
      jsonb_build_object('before',NULL,'after',to_jsonb(NEW),'reason',(SELECT reason FROM public.financial_changes WHERE org_id=NEW.org_id AND id=NEW.change_id)),NEW.created_by);
  RETURN NEW;
 END $$;


--
-- Name: historical_translation_basis_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.historical_translation_basis_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 DECLARE proposal public.financial_changes%ROWTYPE; physical public.journal_lines%ROWTYPE;
         entry public.journal_entries%ROWTYPE; instruction jsonb;
 BEGIN
  IF TG_OP<>'INSERT' THEN
   IF TG_OP='DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD))
     OR public.openbooks_sandbox_wipe_allowed(OLD.org_id)) THEN RETURN OLD; END IF;
   RAISE EXCEPTION 'Approved historical contribution evidence is immutable; preserve it and use governed source reversals.';
  END IF;
  SELECT * INTO STRICT physical FROM public.journal_lines WHERE org_id=NEW.org_id AND id=NEW.source_line_id FOR UPDATE;
  SELECT * INTO STRICT entry FROM public.journal_entries WHERE org_id=NEW.org_id AND id=physical.entry_id FOR SHARE;
  SELECT * INTO STRICT proposal FROM public.financial_changes WHERE org_id=NEW.org_id AND id=NEW.change_id FOR SHARE;
  instruction:=NEW.evidence->'instruction';
  IF EXISTS(SELECT 1 FROM public.historical_translation_contributions WHERE org_id=NEW.org_id AND source_line_id=NEW.source_line_id
    AND measurement_currency<>NEW.measurement_currency) THEN
   RAISE EXCEPTION 'An exact physical source cannot have contradictory measurement currencies across presentation certificates.';
  END IF;
  IF proposal.domain<>'consolidation' OR proposal.operation<>'historical_translation_contribution'
    OR proposal.status<>'approved' OR proposal.approved_by IS NULL
    OR (proposal.approved_by=proposal.submitted_by AND NOT public.financial_change_self_decision_authorized(NEW.org_id,proposal.id,proposal.submitted_by))
    OR proposal.subject_id IS DISTINCT FROM NEW.source_line_id OR proposal.subsidiary_id IS DISTINCT FROM NEW.subsidiary_id
    OR proposal.effective_on IS DISTINCT FROM NEW.posting_date OR proposal.payload->'evidence' IS DISTINCT FROM NEW.evidence
    OR proposal.payload->>'evidenceHash' IS DISTINCT FROM NEW.evidence_hash
    OR proposal.payload->'requiredSubsidiaryIds' IS DISTINCT FROM jsonb_build_array(NEW.subsidiary_id::text)
    OR proposal.before_state IS DISTINCT FROM jsonb_build_object('sourceFingerprint',NEW.evidence->'sourceFingerprint',
      'originalLayerStates',NEW.evidence->'originalLayerStates') THEN
   RAISE EXCEPTION 'Historical contributions require the exact native approved source assessment and retained evidence.';
  END IF;
  IF entry.status NOT IN('posted','reversed') OR physical.entry_id IS DISTINCT FROM NEW.source_entry_id
    OR entry.book_id IS DISTINCT FROM NEW.book_id OR physical.account_id IS DISTINCT FROM NEW.account_id
    OR physical.subsidiary_id IS DISTINCT FROM NEW.subsidiary_id OR physical.amount IS DISTINCT FROM NEW.source_amount
    OR entry.posting_date IS DISTINCT FROM NEW.posting_date
    OR NOT EXISTS(SELECT 1 FROM public.accounts WHERE org_id=NEW.org_id AND id=NEW.account_id AND type='equity')
    OR NEW.evidence->'sourceFingerprint' IS DISTINCT FROM public.historical_translation_source_fingerprint(NEW.org_id,NEW.source_line_id)
    OR instruction->>'sourceLineId' IS DISTINCT FROM NEW.source_line_id::text
    OR instruction->>'measurementCurrency' IS DISTINCT FROM NEW.measurement_currency
    OR instruction->>'presentationCurrency' IS DISTINCT FROM NEW.presentation_currency
    OR instruction->>'kind' IS DISTINCT FROM NEW.kind
    OR jsonb_typeof(instruction->'layers') IS DISTINCT FROM 'array'
    OR jsonb_typeof(NEW.evidence->'retainedSources') IS DISTINCT FROM 'array'
    OR jsonb_typeof(NEW.evidence->'translatedAmounts') IS DISTINCT FROM 'array'
    OR jsonb_typeof(NEW.evidence->'originalLayerStates') IS DISTINCT FROM 'array'
    OR jsonb_array_length(instruction->'layers') NOT BETWEEN 1 AND 200
    OR jsonb_array_length(NEW.evidence->'retainedSources')<>jsonb_array_length(instruction->'layers')
    OR jsonb_array_length(NEW.evidence->'translatedAmounts')<>jsonb_array_length(instruction->'layers')
    OR jsonb_array_length(NEW.evidence->'originalLayerStates')<>(CASE WHEN NEW.kind='correction' THEN jsonb_array_length(instruction->'layers') ELSE 0 END)
    OR (NEW.kind='contribution' AND jsonb_array_length(instruction->'layers')<>1)
    OR (NEW.kind='opening' AND entry.origin NOT IN('opening','book_opening','migration'))
    OR (entry.reverses_entry_id IS NOT NULL AND NEW.kind<>'correction') THEN
   RAISE EXCEPTION 'Historical evidence must bind the exact posted equity line, book, entity, amount, date and explicit layer composition.';
  END IF;
  RETURN NEW;
 END $$;


--
-- Name: historical_translation_completeness(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.historical_translation_completeness() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 DECLARE target uuid; basis public.historical_translation_contributions%ROWTYPE; count_layers integer; total numeric; proposal public.financial_changes%ROWTYPE;
 BEGIN
  IF TG_TABLE_NAME='historical_translation_contributions' THEN target:=NEW.id; ELSE target:=NEW.basis_id; END IF;
  SELECT * INTO STRICT basis FROM public.historical_translation_contributions WHERE org_id=NEW.org_id AND id=target;
  SELECT count(*),sum(amount) INTO count_layers,total FROM public.historical_translation_layers WHERE org_id=NEW.org_id AND basis_id=target;
  SELECT * INTO STRICT proposal FROM public.financial_changes WHERE org_id=NEW.org_id AND id=basis.change_id;
  IF count_layers<>jsonb_array_length(basis.evidence->'instruction'->'layers') OR total IS DISTINCT FROM basis.source_amount
    OR proposal.status<>'applied' OR proposal.result IS DISTINCT FROM jsonb_build_object('basisId',basis.id::text) THEN
   RAISE EXCEPTION 'Record every exact approved historical layer and complete its native approval atomically.';
  END IF;
  RETURN NULL;
 END $$;


--
-- Name: historical_translation_file_retention(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.historical_translation_file_retention() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 DECLARE source_org uuid; source_version uuid;
 BEGIN
  IF TG_TABLE_NAME='file_versions' THEN
   source_version:=OLD.id;
   SELECT org_id INTO source_org FROM public.files WHERE id=OLD.file_id;
  ELSE
   source_version:=OLD.version_id;
   SELECT file.org_id INTO source_org FROM public.file_versions version JOIN public.files file ON file.id=version.file_id
    WHERE version.id=source_version;
  END IF;
  IF EXISTS(SELECT 1 FROM public.historical_translation_layers WHERE org_id=source_org AND source_version_id=source_version) THEN
   IF TG_OP='DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD))
     OR public.openbooks_sandbox_wipe_allowed(source_org)) THEN RETURN OLD; END IF;
   RAISE EXCEPTION 'Retain the immutable Cabinet version and original bytes supporting approved historical contribution evidence.';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
 END $$;


--
-- Name: historical_translation_layer_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.historical_translation_layer_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 DECLARE basis public.historical_translation_contributions%ROWTYPE; original public.historical_translation_layers%ROWTYPE;
   original_basis public.historical_translation_contributions%ROWTYPE; approved_layer jsonb; retained jsonb; used numeric;
 BEGIN
  IF TG_OP<>'INSERT' THEN
   IF TG_OP='DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD))
     OR public.openbooks_sandbox_wipe_allowed(OLD.org_id)) THEN RETURN OLD; END IF;
   RAISE EXCEPTION 'Approved historical translation layers are immutable.';
  END IF;
  SELECT * INTO STRICT basis FROM public.historical_translation_contributions WHERE org_id=NEW.org_id AND id=NEW.basis_id FOR SHARE;
  approved_layer:=basis.evidence->'instruction'->'layers'->(NEW.layer_number-1);
  retained:=basis.evidence->'retainedSources'->(NEW.layer_number-1);
  IF approved_layer IS DISTINCT FROM jsonb_build_object('amount',NEW.amount::text,'rate',NEW.rate::text,
     'historicalDate',NEW.historical_date::text,'provenance',NEW.provenance,'originalLayerId',NEW.original_layer_id::text,
     'source',jsonb_build_object('fileId',NEW.source_file_id::text,'versionId',NEW.source_version_id::text,'contentHash',NEW.source_hash))
    OR retained IS DISTINCT FROM jsonb_build_object('fileId',NEW.source_file_id::text,'versionId',NEW.source_version_id::text,
      'contentHash',NEW.source_hash,'versionNumber',NEW.source_version_number)
    OR basis.evidence->'translatedAmounts'->>(NEW.layer_number-1) IS DISTINCT FROM NEW.translated_amount::text
    OR sign(NEW.amount)<>sign(basis.source_amount) OR NEW.historical_date>basis.posting_date
    OR (basis.measurement_currency=basis.presentation_currency AND NEW.rate<>1)
    OR (basis.kind='correction') IS DISTINCT FROM (NEW.original_layer_id IS NOT NULL)
    OR NOT EXISTS(SELECT 1 FROM public.files file JOIN public.file_versions version ON version.file_id=file.id
      WHERE file.org_id=NEW.org_id AND file.id=NEW.source_file_id AND version.id=NEW.source_version_id
        AND version.content_hash=NEW.source_hash AND version.version_number=NEW.source_version_number) THEN
   RAISE EXCEPTION 'Every historical layer must retain its exact approved amount, genuine rate, date, provenance and tenant-owned Cabinet version.';
  END IF;
  IF NEW.original_layer_id IS NOT NULL THEN
   SELECT * INTO STRICT original FROM public.historical_translation_layers WHERE org_id=NEW.org_id AND id=NEW.original_layer_id FOR UPDATE;
   SELECT * INTO STRICT original_basis FROM public.historical_translation_contributions WHERE org_id=NEW.org_id AND id=original.basis_id FOR SHARE;
   IF original_basis.posting_date>basis.posting_date OR original_basis.book_id<>basis.book_id OR original_basis.account_id<>basis.account_id
     OR original_basis.subsidiary_id<>basis.subsidiary_id OR original_basis.measurement_currency<>basis.measurement_currency
     OR original_basis.presentation_currency<>basis.presentation_currency OR original.rate<>NEW.rate
     OR original.historical_date<>NEW.historical_date OR original.provenance<>NEW.provenance
     OR original.source_file_id<>NEW.source_file_id OR original.source_version_id<>NEW.source_version_id
     OR original.source_hash<>NEW.source_hash OR original.source_version_number<>NEW.source_version_number
     OR sign(original.amount)=sign(NEW.amount)
     OR NOT EXISTS(SELECT 1 FROM public.financial_changes WHERE org_id=NEW.org_id AND id=original_basis.change_id AND status='applied')
     OR EXISTS(SELECT 1 FROM public.journal_entries entry WHERE entry.org_id=NEW.org_id AND entry.id=basis.source_entry_id
       AND entry.reverses_entry_id IS NOT NULL AND entry.reverses_entry_id<>original_basis.source_entry_id) THEN
    RAISE EXCEPTION 'A correction must explicitly bind an applied parent layer and preserve its genuine rate and source.';
   END IF;
   SELECT coalesce(sum(abs(amount)),0) INTO used FROM public.historical_translation_layers WHERE org_id=NEW.org_id AND original_layer_id=original.id;
   IF used+abs(NEW.amount)>abs(original.amount) THEN RAISE EXCEPTION 'Correction exceeds the remaining applied parent layer.'; END IF;
   IF basis.evidence->'originalLayerStates'->(NEW.layer_number-1) IS DISTINCT FROM
      jsonb_build_object('originalLayerId',original.id::text,'consumedAmount',used::numeric(19,4)::text)
     OR NEW.translated_amount IS DISTINCT FROM NEW.amount*NEW.rate THEN
    RAISE EXCEPTION 'Correction must retain its reviewed original allocation state and exact unrounded original-rate product.';
   END IF;
  ELSIF NEW.translated_amount IS DISTINCT FROM NEW.amount*NEW.rate THEN
   RAISE EXCEPTION 'A contribution layer must retain its exact genuine-rate translated amount.';
  END IF;
  RETURN NEW;
 END $$;


--
-- Name: historical_translation_source_fingerprint(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.historical_translation_source_fingerprint(source_org uuid, source_line uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 SELECT jsonb_build_object('orgId',line.org_id::text,'lineId',line.id::text,'entryId',line.entry_id::text,
   'bookId',entry.book_id::text,'accountId',line.account_id::text,'subsidiaryId',line.subsidiary_id::text,
   'amount',line.amount::text,'transactionCurrency',line.currency,'transactionAmount',line.txn_amount::text,
   'transactionRate',line.fx_rate::text,'postingDate',entry.posting_date::text,'origin',entry.origin,
   'reversesEntryId',entry.reverses_entry_id::text)
 FROM public.journal_lines line JOIN public.journal_entries entry ON entry.org_id=line.org_id AND entry.id=line.entry_id
 WHERE line.org_id=source_org AND line.id=source_line
 $$;


--
-- Name: historical_translation_source_retention(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.historical_translation_source_retention() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 BEGIN
  IF TG_OP='DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD))
    OR public.openbooks_sandbox_wipe_allowed(OLD.org_id)) THEN RETURN OLD; END IF;
  IF TG_TABLE_NAME='journal_lines' THEN
   IF EXISTS(SELECT 1 FROM public.historical_translation_contributions WHERE org_id=OLD.org_id AND source_line_id=OLD.id)
    AND (TG_OP='DELETE' OR ROW(NEW.org_id,NEW.id,NEW.entry_id,NEW.account_id,NEW.subsidiary_id,NEW.amount,NEW.currency,NEW.txn_amount,NEW.fx_rate)
     IS DISTINCT FROM ROW(OLD.org_id,OLD.id,OLD.entry_id,OLD.account_id,OLD.subsidiary_id,OLD.amount,OLD.currency,OLD.txn_amount,OLD.fx_rate)) THEN
    RAISE EXCEPTION 'Retain the physical historical contribution source; correct it through governed reversals.';
   END IF;
  ELSE
   IF EXISTS(SELECT 1 FROM public.historical_translation_contributions WHERE org_id=OLD.org_id AND source_entry_id=OLD.id)
    AND (TG_OP='DELETE' OR ROW(NEW.org_id,NEW.id,NEW.book_id,NEW.posting_date,NEW.origin,NEW.reverses_entry_id)
     IS DISTINCT FROM ROW(OLD.org_id,OLD.id,OLD.book_id,OLD.posting_date,OLD.origin,OLD.reverses_entry_id)
     OR NEW.status NOT IN('posted','reversed')) THEN
    RAISE EXCEPTION 'Retain the posted historical contribution entry identity and measurement date.';
   END IF;
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
 END $$;


--
-- Name: holiday_clone_json(jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.holiday_clone_json(value jsonb, kind text, seed uuid) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE result jsonb:=value; paths jsonb; item jsonb; path text[]; entries jsonb;
BEGIN
 IF value IS NULL THEN RETURN NULL; END IF;
 CASE kind
 WHEN 'evidence' THEN paths:='[["instruction","employeePartyId"],["source","fileId"],["source","versionId"]]'::jsonb;
 WHEN 'payload' THEN
  paths:='[["employmentId"]]'::jsonb;
  IF result ? 'evidence' THEN result:=jsonb_set(result,'{evidence}',public.holiday_clone_json(result->'evidence','evidence',seed)); END IF;
  IF jsonb_typeof(result->'requiredSubsidiaryIds')='array' THEN
   SELECT coalesce(jsonb_agg(to_jsonb(public.ob_rebase(a.value::uuid,seed)::text) ORDER BY a.ordinal),'[]'::jsonb)
    INTO entries FROM jsonb_array_elements_text(result->'requiredSubsidiaryIds') WITH ORDINALITY AS a(value,ordinal);
   result:=jsonb_set(result,'{requiredSubsidiaryIds}',entries);
  END IF;
 WHEN 'before_state' THEN
  paths:='[["employment","id"],["employment","worker_party_id"],["employment","employer_subsidiary_id"],["profile","id"],["profile","employment_id"],["profile","pay_schedule_id"]]'::jsonb;
  IF jsonb_typeof(result->'datedEmployment')='array' THEN
   SELECT coalesce(jsonb_agg(CASE WHEN jsonb_typeof(a.value->'id')='string'
    THEN jsonb_set(a.value,'{id}',to_jsonb(public.ob_rebase((a.value->>'id')::uuid,seed)::text)) ELSE a.value END ORDER BY a.ordinal),'[]'::jsonb)
    INTO entries FROM jsonb_array_elements(result->'datedEmployment') WITH ORDINALITY AS a(value,ordinal);
   result:=jsonb_set(result,'{datedEmployment}',entries);
  END IF;
 WHEN 'result' THEN paths:='[["obligationId"]]'::jsonb;
 WHEN 'source_snapshot' THEN
  paths:='[["wage","source","id"],["wage","fx","id"]]'::jsonb;
  IF result ? 'obligation' THEN result:=jsonb_set(result,'{obligation}',public.holiday_clone_json(result->'obligation','evidence',seed)); END IF;
 ELSE RAISE EXCEPTION 'Unknown holiday evidence projection.';
 END CASE;
 FOR item IN SELECT jsonb_array_elements(paths) LOOP
  SELECT array_agg(v ORDER BY ord) INTO path FROM jsonb_array_elements_text(item) WITH ORDINALITY a(v,ord);
  IF jsonb_typeof(result #> path)='string' THEN
   result:=jsonb_set(result,path,to_jsonb(public.ob_rebase((result #>> path)::uuid,seed)::text));
  END IF;
 END LOOP;
 RETURN result;
END $$;


--
-- Name: holiday_historical_clone_matches(regclass, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.holiday_historical_clone_matches(relation regclass, candidate jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE target record; original jsonb; expected jsonb; column_row record; projection text;
BEGIN
 IF NOT public.openbooks_clone_authority() OR relation NOT IN (
  'public.payroll_holiday_obligations'::regclass,'public.payroll_holiday_occurrences'::regclass,
  'public.pay_run_holiday_allocations'::regclass) THEN RETURN false; END IF;
 SELECT o.id,o.sandbox_of,o.sandbox_seed,s.masked INTO target FROM public.orgs o
 JOIN public.sandboxes s ON s.org_id=o.id AND s.production_org_id=o.sandbox_of
 WHERE o.id=(candidate->>'org_id')::uuid AND o.env_kind='sandbox' AND o.sandbox_seed IS NOT NULL;
 IF NOT FOUND THEN RETURN false; END IF;
 IF relation='public.payroll_holiday_occurrences'::regclass THEN
  SELECT to_jsonb(source) INTO original FROM public.payroll_holiday_occurrences source
   WHERE source.org_id=target.sandbox_of AND public.ob_rebase(source.obligation_id,target.sandbox_seed)=(candidate->>'obligation_id')::uuid
    AND source.holiday_date=(candidate->>'holiday_date')::date;
 ELSE
  EXECUTE format('SELECT to_jsonb(source) FROM %s source WHERE source.org_id=$1 AND public.ob_rebase(source.id,$2)=$3',relation)
   INTO original USING target.sandbox_of,target.sandbox_seed,(candidate->>'id')::uuid;
 END IF;
 IF original IS NULL THEN RETURN false; END IF;
 expected:=original;
 FOR column_row IN SELECT attname,atttypid,attnotnull FROM pg_catalog.pg_attribute
  WHERE attrelid=relation AND attnum>0 AND NOT attisdropped LOOP
  IF column_row.attname='org_id' THEN expected:=jsonb_set(expected,ARRAY[column_row.attname],to_jsonb(target.id));
  ELSIF column_row.atttypid='uuid'::regtype AND jsonb_typeof(original->column_row.attname)='string' THEN
   expected:=jsonb_set(expected,ARRAY[column_row.attname],to_jsonb(public.ob_rebase((original->>column_row.attname)::uuid,target.sandbox_seed)));
  ELSIF (relation='public.payroll_holiday_obligations'::regclass AND column_row.attname='evidence') OR
        (relation='public.pay_run_holiday_allocations'::regclass AND column_row.attname='source_snapshot') THEN
   projection:=column_row.attname;
   expected:=jsonb_set(expected,ARRAY[projection],public.holiday_clone_json(original->projection,projection,target.sandbox_seed));
   IF target.masked AND EXISTS(SELECT 1 FROM public.masking_policies p WHERE p.org_id=target.sandbox_of
    AND p.table_name=CASE relation WHEN 'public.payroll_holiday_obligations'::regclass THEN 'payroll_holiday_obligations' ELSE 'pay_run_holiday_allocations' END
    AND p.column_name=projection AND p.is_active AND p.transform='null_out') THEN
    expected:=jsonb_set(expected,ARRAY[projection],'{}'::jsonb);
   END IF;
  END IF;
 END LOOP;
 RETURN candidate=expected;
END $_$;


--
-- Name: hrm_absence_immutable_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hrm_absence_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF coalesce(current_setting('openbooks.amend', true), 'off') = 'on' THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION
    'HRM absence % is immutable evidence — record a reversing absence row instead of updating it.', OLD.id;
END;
$$;


