--
-- Name: hrm_allowance_payroll_input_void_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hrm_allowance_payroll_input_void_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.status = 'voided' AND OLD.consumed_by_run_document_id IS NOT NULL
     AND NEW.consumed_by_run_document_id IS DISTINCT FROM OLD.consumed_by_run_document_id THEN
    RAISE EXCEPTION
      'HRM allowance payroll input % was consumed by pay run % — voiding keeps that link so the stale run stays visible; recalculate the run instead of unlinking it.',
      OLD.id, OLD.consumed_by_run_document_id;
  END IF;
  IF NEW.status = 'pending' AND OLD.status = 'voided' THEN
    RAISE EXCEPTION
      'HRM allowance payroll input % is voided and stays voided — regenerate the day for a revised amount.',
      OLD.id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: hrm_application_events_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hrm_application_events_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE'
     AND coalesce(current_setting('openbooks.amend', true), 'off') = 'on' THEN
    RETURN OLD;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'hrm_application_events: funnel events are append-only evidence — they are never deleted'
      USING ERRCODE = '23514';
  END IF;
  RAISE EXCEPTION 'hrm_application_events: funnel events are append-only evidence — record a new event instead of editing one'
    USING ERRCODE = '23514';
END $$;


--
-- Name: FUNCTION hrm_application_events_immutable(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.hrm_application_events_immutable() IS 'openbooks:hrm_application_events_immutable:v1 - funnel events append-only; updates refused on every path, deletes only on the governed amend path';


