--

CREATE FUNCTION public.hrm_payroll_input_void_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.status = 'voided' AND OLD.consumed_by_run_document_id IS NOT NULL
     AND NEW.consumed_by_run_document_id IS DISTINCT FROM OLD.consumed_by_run_document_id THEN
    RAISE EXCEPTION
      'HRM payroll input % was consumed by pay run % — voiding keeps that link so the stale run stays visible; recalculate the run instead of unlinking it.',
      OLD.id, OLD.consumed_by_run_document_id;
  END IF;
  IF NEW.status = 'pending' AND OLD.status = 'voided' THEN
    RAISE EXCEPTION
      'HRM payroll input % is voided and stays voided — release never resurrects a voided row; file a new request for a revised absence.',
      OLD.id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: hrm_pipeline_template_no_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hrm_pipeline_template_no_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE live_count integer;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  SELECT count(*)::int INTO live_count FROM public.hrm_requisitions
   WHERE org_id = OLD.org_id AND pipeline_template_id = OLD.id;
  IF live_count > 0 THEN
    RAISE EXCEPTION 'HRM pipeline template % opened % requisition(s) and is retained as history — set is_active = false to retire it instead of deleting it.', OLD.id, live_count
      USING ERRCODE = '23514';
  END IF;
  RETURN OLD;
END $$;


