     AND to_jsonb(NEW) - ARRAY['updated_at','updated_by']
       <> to_jsonb(OLD) - ARRAY['updated_at','updated_by'] THEN
    RAISE EXCEPTION 'hrm_scorecards: a submitted scorecard is immutable — the verdict stands as recorded'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


