--
-- Name: hrm_training_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hrm_training_audit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 INSERT INTO public.audit_log(org_id,table_name,row_id,action,actor_id,changes)
 VALUES(NEW.org_id,TG_TABLE_NAME,NEW.id,lower(TG_OP),CASE WHEN public.openbooks_clone_authority() THEN NULL ELSE coalesce(to_jsonb(NEW)->>'updated_by',to_jsonb(NEW)->>'created_by')::uuid END,
  jsonb_build_object('before',CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE NULL END,'after',to_jsonb(NEW),
   'reason',CASE WHEN public.openbooks_clone_authority() THEN 'Preserve training evidence during controlled sandbox cloning.' ELSE coalesce(to_jsonb(NEW)->>'reason','Participant training feedback.') END));
 RETURN NEW;
END $$;


--
-- Name: hrm_training_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hrm_training_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE session_row public.hrm_training_sessions; course_row public.hrm_training_courses;
 author_person uuid; decision_person uuid; employer uuid; qualification_status text; passed boolean;
 validity integer; evidence_required boolean; qualification_issued date;
BEGIN
 IF TG_OP='DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD)) THEN RETURN OLD; END IF;
 IF TG_OP='DELETE' THEN
  IF public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'Training history cannot be deleted; retire a course, cancel a session or void a participant outcome with a reason.';
 END IF;
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' THEN
  IF TG_TABLE_NAME='hrm_training_feedback' THEN RAISE EXCEPTION 'Training feedback is immutable; append a corrected feedback entry with the previous entry as its predecessor.'; END IF;
  IF ROW(NEW.id,NEW.org_id,NEW.created_at,NEW.created_by,NEW.request_hash) IS DISTINCT FROM ROW(OLD.id,OLD.org_id,OLD.created_at,OLD.created_by,OLD.request_hash) THEN
   RAISE EXCEPTION 'Training ownership and creation evidence are immutable; create a successor record.';
  END IF;
  IF NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION 'Training revision changed; reload the record before saving.'; END IF;
 END IF;
 IF TG_TABLE_NAME='hrm_training_courses' THEN
  IF TG_OP='INSERT' THEN
   IF NEW.status<>'draft' THEN RAISE EXCEPTION 'Create a course draft before submission through Flows.'; END IF;
   SELECT party_id INTO author_person FROM public.users WHERE org_id=NEW.org_id AND id=NEW.created_by AND is_active;
   IF author_person IS NULL OR author_person IS DISTINCT FROM NEW.author_party_id THEN RAISE EXCEPTION 'Course authorship needs a native person identity; link the author to their person record before creating the course.'; END IF;
   IF NEW.qualification_type_id IS NOT NULL THEN
    SELECT validity_months,requires_evidence INTO validity,evidence_required FROM public.hrm_qualification_types WHERE org_id=NEW.org_id AND id=NEW.qualification_type_id AND is_active FOR SHARE;
    IF NOT FOUND OR NEW.qualification_validity_months IS DISTINCT FROM validity OR NEW.qualification_requires_evidence IS DISTINCT FROM evidence_required THEN
     RAISE EXCEPTION 'Qualification policy changed; reload the native qualification type before creating the course draft.';
    END IF;
   END IF;
  ELSE
   IF (to_jsonb(NEW)-ARRAY['status','decided_by','decided_at','revision','reason','updated_at','updated_by']) IS DISTINCT FROM
      (to_jsonb(OLD)-ARRAY['status','decided_by','decided_at','revision','reason','updated_at','updated_by']) THEN
    RAISE EXCEPTION 'A course definition is immutable; create an effective-dated successor version.';
   END IF;
   IF NOT ((OLD.status='draft' AND NEW.status IN ('approved','cancelled')) OR (OLD.status='approved' AND NEW.status='retired')) THEN
    RAISE EXCEPTION 'This course transition is unavailable; reload the course and choose an action for its current state.';
   END IF;
   IF NEW.status='approved' THEN
    IF NEW.decided_by IS DISTINCT FROM NEW.updated_by OR NOT public.flow_command_authorized(NEW.org_id,'training_course',NEW.id,NEW.decided_by,
      public.flow_command_record_fingerprint(to_jsonb(OLD)),jsonb_build_object('expectedRevision',OLD.revision,'reason',NEW.reason)) THEN
     RAISE EXCEPTION 'Release this course revision through its complete native tenant Flow submission.';
    END IF;
   ELSIF ROW(NEW.decided_by,NEW.decided_at) IS DISTINCT FROM ROW(OLD.decided_by,OLD.decided_at) THEN
    RAISE EXCEPTION 'Course approval evidence is immutable; create a successor course version.';
   END IF;
  END IF;
 ELSIF TG_TABLE_NAME='hrm_training_sessions' THEN
  SELECT * INTO course_row FROM public.hrm_training_courses WHERE org_id=NEW.org_id AND id=NEW.course_id FOR SHARE;
  IF NOT FOUND OR course_row.subsidiary_id<>NEW.subsidiary_id THEN RAISE EXCEPTION 'The course is unavailable for this employer; select an approved course in this employer scope.'; END IF;
  IF NEW.starts_on<>(NEW.starts_at AT TIME ZONE NEW.time_zone)::date OR NEW.ends_on<>(NEW.ends_at AT TIME ZONE NEW.time_zone)::date THEN
   RAISE EXCEPTION 'Session dates do not match their time zone; choose exact session times again.';
  END IF;
  IF TG_OP='INSERT' THEN
   IF NEW.status<>'draft' OR course_row.status<>'approved' OR NEW.starts_on<course_row.effective_from OR (course_row.effective_to IS NOT NULL AND NEW.ends_on>course_row.effective_to) THEN
    RAISE EXCEPTION 'Create a draft session within an approved course effective window; select a matching course version.';
   END IF;
  ELSE
   IF (to_jsonb(NEW)-ARRAY['status','revision','reason','updated_at','updated_by']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','revision','reason','updated_at','updated_by']) THEN
    RAISE EXCEPTION 'Session delivery details are immutable; cancel it and create a corrected session.';
   END IF;
   IF NOT ((OLD.status='draft' AND NEW.status IN ('scheduled','cancelled')) OR (OLD.status='scheduled' AND NEW.status IN ('in_progress','cancelled')) OR (OLD.status='in_progress' AND NEW.status IN ('completed','cancelled'))) THEN
    RAISE EXCEPTION 'This session transition is unavailable; reload the session and choose an action for its current state.';
   END IF;
   IF NEW.status='scheduled' AND course_row.status<>'approved' THEN RAISE EXCEPTION 'The course is retired; cancel this draft and create a session for an approved successor.'; END IF;
   IF NEW.status='in_progress' AND NEW.starts_at>now() THEN RAISE EXCEPTION 'The scheduled session has not started; start it at or after its recorded start time.'; END IF;
   IF NEW.status='completed' AND NEW.ends_at>now() THEN RAISE EXCEPTION 'The session has not ended; record final delivery after its recorded end time.'; END IF;
   IF NEW.status='completed' AND EXISTS(SELECT 1 FROM public.hrm_training_participants WHERE org_id=NEW.org_id AND session_id=NEW.id AND status IN ('invited','accepted')) THEN
    RAISE EXCEPTION 'Participant outcomes are unfinished; record each result or decline/cancel the invitation before closing the session.';
   END IF;
   IF NEW.status='completed' AND NOT EXISTS(SELECT 1 FROM public.hrm_training_participants WHERE org_id=NEW.org_id AND session_id=NEW.id AND status IN ('completed','failed')) THEN
    RAISE EXCEPTION 'This session has no completed participant results; record a delivered result or cancel the unused session.';
   END IF;
   IF NEW.status='cancelled' AND EXISTS(SELECT 1 FROM public.hrm_training_participants WHERE org_id=NEW.org_id AND session_id=NEW.id AND status NOT IN ('declined','cancelled','voided')) THEN
    RAISE EXCEPTION 'Session participants still have active invitations or outcomes; cancel invitations and void outcomes before cancelling the session.';
   END IF;
  END IF;
 ELSIF TG_TABLE_NAME='hrm_training_participants' THEN
  SELECT * INTO session_row FROM public.hrm_training_sessions WHERE org_id=NEW.org_id AND id=NEW.session_id FOR UPDATE;
  IF NOT FOUND OR session_row.subsidiary_id<>NEW.subsidiary_id THEN RAISE EXCEPTION 'The training session is unavailable; choose a visible employer session.'; END IF;
  SELECT employer_subsidiary_id INTO employer FROM public.worker_employments WHERE org_id=NEW.org_id AND id=NEW.employment_id FOR UPDATE;
  IF TG_OP='INSERT' OR NEW.status IN ('completed','failed') THEN
   IF employer IS DISTINCT FROM NEW.subsidiary_id THEN RAISE EXCEPTION 'The participant employment belongs to a different employer; choose an employment for the session employer.'; END IF;
   IF NOT EXISTS(SELECT employment_id FROM public.worker_employment_versions WHERE org_id=NEW.org_id AND employment_id=NEW.employment_id AND recorded_until IS NULL AND status IN ('active','on_leave')
    GROUP BY employment_id HAVING range_agg(daterange(effective_from,effective_to,'[)')) @> daterange(session_row.starts_on,session_row.ends_on,'[]')) THEN
    RAISE EXCEPTION 'Employment history does not cover the session; choose a covered session or record verified employment history through its native workflow.';
   END IF;
  END IF;
  SELECT * INTO course_row FROM public.hrm_training_courses WHERE org_id=NEW.org_id AND id=session_row.course_id FOR SHARE;
  IF NEW.qualification_type_id IS DISTINCT FROM course_row.qualification_type_id THEN RAISE EXCEPTION 'Participant qualification policy differs from its approved course; reload the course definition.'; END IF;
  IF TG_OP='INSERT' THEN
   IF NEW.status<>'invited' OR session_row.status<>'scheduled' THEN RAISE EXCEPTION 'Schedule the session before inviting participants.'; END IF;
   IF (SELECT count(*) FROM public.hrm_training_participants WHERE org_id=NEW.org_id AND session_id=NEW.session_id AND status NOT IN ('declined','cancelled'))>=session_row.capacity THEN
    RAISE EXCEPTION 'The training session is full; choose another session or decline an unused invitation.';
   END IF;
  ELSE
   IF ROW(NEW.session_id,NEW.employment_id,NEW.subsidiary_id,NEW.qualification_type_id) IS DISTINCT FROM ROW(OLD.session_id,OLD.employment_id,OLD.subsidiary_id,OLD.qualification_type_id) THEN
    RAISE EXCEPTION 'Participant ownership is immutable; create a new invitation for the correct employment.';
   END IF;
   IF NOT ((OLD.status='invited' AND NEW.status IN ('accepted','declined','cancelled','completed','failed')) OR
    (OLD.status='accepted' AND NEW.status IN ('declined','cancelled','completed','failed')) OR
    (OLD.status IN ('completed','failed') AND NEW.status='voided')) THEN
    RAISE EXCEPTION 'This participant transition is unavailable; reload the participant and choose an action for its current state.';
   END IF;
   IF NEW.status IN ('completed','failed') THEN
    IF session_row.status<>'in_progress' THEN RAISE EXCEPTION 'Start the training session before recording participant results.'; END IF;
    IF session_row.ends_at>now() THEN RAISE EXCEPTION 'The session has not ended; record final attendance and assessment after its end time.'; END IF;
    IF NEW.attendance_seconds IS NULL OR NEW.attendance_seconds>session_row.duration_seconds OR
     ((course_row.passing_score IS NOT NULL)<>(NEW.score IS NOT NULL)) THEN RAISE EXCEPTION 'Attendance or assessment is incomplete; record valid attendance and the declared assessment score.'; END IF;
    passed := NEW.attendance_seconds::bigint*100>=session_row.duration_seconds::bigint*course_row.minimum_attendance_percent
     AND (course_row.passing_score IS NULL OR NEW.score>=course_row.passing_score);
    IF (NEW.status='completed')<>passed THEN RAISE EXCEPTION 'The outcome differs from the approved course thresholds; calculate the result from recorded attendance and assessment.'; END IF;
    IF NEW.status='completed' AND course_row.qualification_type_id IS NOT NULL AND NEW.qualification_id IS NULL THEN
     RAISE EXCEPTION 'A passing course outcome needs its native qualification evidence; record or link the matching qualification before completing.';
    END IF;
    IF NEW.qualification_id IS NOT NULL THEN
     SELECT issued_on,status INTO qualification_issued,qualification_status FROM public.hrm_worker_qualifications WHERE org_id=NEW.org_id AND id=NEW.qualification_id;
     IF qualification_issued IS DISTINCT FROM session_row.ends_on OR qualification_status='revoked' THEN RAISE EXCEPTION 'The qualification does not match the completion date or is revoked; choose matching non-revoked qualification evidence.'; END IF;
    END IF;
   ELSIF NEW.status='voided' THEN
    IF (to_jsonb(NEW)-ARRAY['status','revision','reason','updated_at','updated_by']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','revision','reason','updated_at','updated_by']) THEN
     RAISE EXCEPTION 'Training results are immutable; void the unchanged outcome with a reason.';
    END IF;
    IF NEW.qualification_created THEN
     SELECT status INTO qualification_status FROM public.hrm_worker_qualifications WHERE org_id=NEW.org_id AND id=NEW.qualification_id;
     IF qualification_status IS DISTINCT FROM 'revoked' THEN RAISE EXCEPTION 'The training-issued qualification is still active; revoke it with the same correction reason before voiding the outcome.'; END IF;
    END IF;
   ELSE
    IF ROW(NEW.attendance_seconds,NEW.score,NEW.evidence_file_id,NEW.notes,NEW.qualification_id,NEW.qualification_created,NEW.completion_hash) IS DISTINCT FROM
       ROW(OLD.attendance_seconds,OLD.score,OLD.evidence_file_id,OLD.notes,OLD.qualification_id,OLD.qualification_created,OLD.completion_hash) THEN
     RAISE EXCEPTION 'Invitation changes cannot rewrite a training result; use the participant completion action.';
    END IF;
   END IF;
  END IF;
 ELSIF TG_TABLE_NAME='hrm_training_feedback' THEN
  IF NOT EXISTS(SELECT 1 FROM public.hrm_training_participants WHERE org_id=NEW.org_id AND id=NEW.participant_id AND status IN ('completed','failed')) THEN
   RAISE EXCEPTION 'Training feedback needs a completed participant result; complete the participant before recording feedback.';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: initialize_payroll_compensation_configuration(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.initialize_payroll_compensation_configuration() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE previous_org text;
BEGIN
 -- Organization creation is authorized by its own policy; initialize the new
 -- tenant's derived counter under that tenant without weakening table isolation.
 previous_org := current_setting('app.current_org',true);
 PERFORM set_config('app.current_org',NEW.id::text,true);
 INSERT INTO public.payroll_compensation_configuration(org_id) VALUES(NEW.id);
 PERFORM set_config('app.current_org',coalesce(previous_org,''),true);
 RETURN NEW;
END $$;


--
-- Name: intercompany_fulfillment_charge_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.intercompany_fulfillment_charge_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD))
     OR public.openbooks_sandbox_wipe_allowed(OLD.org_id)) THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'cross-subsidiary fulfillment charges are append-only; a return records the reversal';
END;
$$;


--
-- Name: intercompany_fund_transfer_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.intercompany_fund_transfer_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD))
       OR public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'intercompany fund transfers are retained; reverse a transfer instead';
  END IF;
  IF NOT (OLD.status = 'posted' AND NEW.status = 'reversed')
     OR to_jsonb(NEW) - 'status' - 'reversal_entry_id' - 'reversal_date' - 'reverse_reason' - 'reversed_by' - 'reversed_at' - 'updated_at'
        IS DISTINCT FROM
        to_jsonb(OLD) - 'status' - 'reversal_entry_id' - 'reversal_date' - 'reverse_reason' - 'reversed_by' - 'reversed_at' - 'updated_at' THEN
    RAISE EXCEPTION 'a posted intercompany fund transfer changes only by reversal';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: intercompany_netting_line_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.intercompany_netting_line_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_status text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD))
       OR public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'intercompany netting lines are retained with their run';
  END IF;
  SELECT r.status INTO v_status FROM public.intercompany_netting_runs r
   WHERE r.org_id = NEW.org_id AND r.id = NEW.run_id;
  IF TG_OP = 'INSERT' THEN
    IF v_status IS DISTINCT FROM 'proposed' THEN
      RAISE EXCEPTION 'intercompany netting lines are written with the run proposal';
    END IF;
    RETURN NEW;
  END IF;
  -- Settlement evidence is stamped once, while the run posts.
  IF to_jsonb(NEW) - 'settlement_entry_id' - 'settlement_line_id' - 'application_id'
     IS DISTINCT FROM to_jsonb(OLD) - 'settlement_entry_id' - 'settlement_line_id' - 'application_id'
     OR (OLD.settlement_entry_id IS NOT NULL AND NEW.settlement_entry_id IS DISTINCT FROM OLD.settlement_entry_id)
     OR (OLD.settlement_line_id IS NOT NULL AND NEW.settlement_line_id IS DISTINCT FROM OLD.settlement_line_id)
     OR (OLD.application_id IS NOT NULL AND NEW.application_id IS DISTINCT FROM OLD.application_id)
     OR v_status IS DISTINCT FROM 'approved' THEN
    RAISE EXCEPTION 'intercompany netting lines are immutable; settlement evidence is recorded once when the run posts';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: intercompany_netting_run_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.intercompany_netting_run_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD))
       OR public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'intercompany netting runs are retained; cancel a proposal or reverse a posted run instead';
  END IF;
  IF (NEW.org_id, NEW.run_number, NEW.as_of_date, NEW.book_id, NEW.period_id, NEW.subsidiary_ids,
      NEW.settle_cash, NEW.bank_accounts, NEW.computation, NEW.fingerprint, NEW.reason,
      NEW.idempotency_key, NEW.proposed_by, NEW.proposed_at)
     IS DISTINCT FROM
     (OLD.org_id, OLD.run_number, OLD.as_of_date, OLD.book_id, OLD.period_id, OLD.subsidiary_ids,
      OLD.settle_cash, OLD.bank_accounts, OLD.computation, OLD.fingerprint, OLD.reason,
      OLD.idempotency_key, OLD.proposed_by, OLD.proposed_at) THEN
    RAISE EXCEPTION 'an intercompany netting run keeps the terms it was proposed with; cancel it and propose a new run';
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
       (OLD.status = 'proposed' AND NEW.status IN ('pending_approval', 'approved', 'cancelled'))
    OR (OLD.status = 'pending_approval' AND NEW.status IN ('approved', 'rejected', 'cancelled'))
    OR (OLD.status = 'approved' AND NEW.status IN ('posted', 'cancelled'))
    OR (OLD.status = 'posted' AND NEW.status = 'reversed')
  ) THEN
    RAISE EXCEPTION 'an intercompany netting run cannot move from % to %', OLD.status, NEW.status;
  END IF;
  IF OLD.status IN ('posted', 'reversed', 'cancelled', 'rejected') AND NEW.status = OLD.status
     AND to_jsonb(NEW) - 'updated_at' IS DISTINCT FROM to_jsonb(OLD) - 'updated_at' THEN
    RAISE EXCEPTION 'a % intercompany netting run is closed history', OLD.status;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: intercompany_pair_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.intercompany_pair_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_from_type text;
  v_to_type text;
  v_control record;
begin
  if new.from_subsidiary_id = new.to_subsidiary_id then
    raise exception 'intercompany subsidiaries must be different' using errcode = '23514';
  end if;
  if (select count(*) from subsidiaries s
       where s.org_id = new.org_id and s.id in (new.from_subsidiary_id, new.to_subsidiary_id)
         and s.is_active and not s.is_elimination) <> 2 then
    raise exception 'intercompany subsidiaries are invalid' using errcode = '23514';
  end if;
  select type into v_from_type from accounts
   where id = new.due_from_account_id and org_id = new.org_id
     and is_active and not is_summary and eliminate;
  select type into v_to_type from accounts
   where id = new.due_to_account_id and org_id = new.org_id
     and is_active and not is_summary and eliminate;
  if v_from_type is null or v_from_type not like 'asset\_%' escape '\' then
    raise exception 'due-from account must be an eliminable asset' using errcode = '23514';
  end if;
  if v_to_type is null or v_to_type not like 'liability\_%' escape '\' then
    raise exception 'due-to account must be an eliminable liability' using errcode = '23514';
  end if;
  -- Intercompany receivable and payable control accounts are optional; when
  -- set they must be eliminated posting accounts of the control type.
  for v_control in
    select account_id, expected, label from (values
      (new.from_receivable_account_id, 'asset_receivable', 'from-side intercompany receivable'),
      (new.to_receivable_account_id, 'asset_receivable', 'to-side intercompany receivable'),
      (new.from_payable_account_id, 'liability_payable', 'from-side intercompany payable'),
      (new.to_payable_account_id, 'liability_payable', 'to-side intercompany payable')
    ) as controls(account_id, expected, label)
    where account_id is not null
  loop
    if not exists (
      select 1 from accounts a
       where a.org_id = new.org_id and a.id = v_control.account_id
         and a.is_active and not a.is_summary and a.eliminate and a.type = v_control.expected
    ) then
      raise exception '% account must be an active eliminated % account', v_control.label, v_control.expected
        using errcode = '23514';
    end if;
  end loop;
  return new;
end $$;


--
-- Name: intercompany_representing_party_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.intercompany_representing_party_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_root uuid;
  v_role record;
BEGIN
  IF TG_OP = 'INSERT' AND public.openbooks_clone_authority() THEN
    RETURN NEW;
  END IF;
  IF NOT NEW.is_active THEN
    RETURN NEW;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.subsidiaries s
     WHERE s.org_id = NEW.org_id AND s.id = NEW.subsidiary_id AND s.is_active AND NOT s.is_elimination
  ) THEN
    RAISE EXCEPTION 'a representing party must represent an active operating subsidiary' USING errcode = '23514';
  END IF;
  SELECT s.id INTO v_root FROM public.subsidiaries s WHERE s.org_id = NEW.org_id AND s.parent_id IS NULL;
  FOR v_role IN
    SELECT party_id, role FROM (VALUES (NEW.customer_party_id, 'customer'), (NEW.vendor_party_id, 'vendor')) AS r(party_id, role)
     WHERE party_id IS NOT NULL
  LOOP
    IF v_role.role = 'customer' AND NOT EXISTS (
      SELECT 1 FROM public.customer_roles r JOIN public.parties p ON p.org_id = r.org_id AND p.id = r.party_id
       WHERE r.org_id = NEW.org_id AND r.party_id = v_role.party_id AND r.is_active AND p.is_active
    ) THEN
      RAISE EXCEPTION 'the representing customer must be an active customer' USING errcode = '23514';
    END IF;
    IF v_role.role = 'vendor' AND NOT EXISTS (
      SELECT 1 FROM public.vendor_roles r JOIN public.parties p ON p.org_id = r.org_id AND p.id = r.party_id
       WHERE r.org_id = NEW.org_id AND r.party_id = v_role.party_id AND r.is_active AND p.is_active
    ) THEN
      RAISE EXCEPTION 'the representing vendor must be an active vendor' USING errcode = '23514';
    END IF;
    -- A subsidiary cannot trade with itself: the representing party must not
    -- transact with the entity it represents.
    IF EXISTS (
      SELECT 1 FROM public.parties p
       WHERE p.org_id = NEW.org_id AND p.id = v_role.party_id
         AND coalesce(p.subsidiary_id, v_root) = NEW.subsidiary_id
    ) OR EXISTS (
      SELECT 1 FROM public.party_subsidiaries ps
       WHERE ps.org_id = NEW.org_id AND ps.party_id = v_role.party_id AND ps.subsidiary_id = NEW.subsidiary_id
    ) THEN
      RAISE EXCEPTION 'the representing % transacts with the subsidiary it represents; a subsidiary cannot be its own customer or vendor', v_role.role
        USING errcode = '23514';
    END IF;
  END LOOP;
  RETURN NEW;
END;
$$;


--
-- Name: intercompany_transaction_pair_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.intercompany_transaction_pair_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_root uuid;
  v_seller record;
  v_buyer record;
  v_seller_kind text;
  v_buyer_kind text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD))
       OR public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'intercompany pairing history is retained; unlink the pair instead';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF NOT (OLD.status = 'linked' AND NEW.status = 'unlinked')
       OR to_jsonb(NEW) - 'status' - 'unlinked_by' - 'unlinked_at' - 'unlink_reason' - 'updated_at'
          IS DISTINCT FROM
          to_jsonb(OLD) - 'status' - 'unlinked_by' - 'unlinked_at' - 'unlink_reason' - 'updated_at' THEN
      RAISE EXCEPTION 'an intercompany pair changes only by unlinking it';
    END IF;
    RETURN NEW;
  END IF;
  IF public.openbooks_clone_authority() THEN
    RETURN NEW;
  END IF;
  v_seller_kind := CASE NEW.pair_kind WHEN 'order' THEN 'sales_order' WHEN 'invoice' THEN 'customer_invoice' ELSE 'customer_credit' END;
  v_buyer_kind := CASE NEW.pair_kind WHEN 'order' THEN 'purchase_order' WHEN 'invoice' THEN 'vendor_bill' ELSE 'vendor_credit' END;
  SELECT s.id INTO v_root FROM public.subsidiaries s WHERE s.org_id = NEW.org_id AND s.parent_id IS NULL;
  SELECT d.kind, coalesce(d.subsidiary_id, v_root) AS subsidiary_id, d.status INTO v_seller
    FROM public.documents d WHERE d.org_id = NEW.org_id AND d.id = NEW.seller_document_id;
  SELECT d.kind, coalesce(d.subsidiary_id, v_root) AS subsidiary_id, d.status INTO v_buyer
    FROM public.documents d WHERE d.org_id = NEW.org_id AND d.id = NEW.buyer_document_id;
  IF v_seller.kind IS DISTINCT FROM v_seller_kind OR v_buyer.kind IS DISTINCT FROM v_buyer_kind THEN
    RAISE EXCEPTION 'an intercompany % pair links a % to a %', NEW.pair_kind, v_seller_kind, v_buyer_kind
      USING errcode = '23514';
  END IF;
  IF v_seller.subsidiary_id IS DISTINCT FROM NEW.seller_subsidiary_id
     OR v_buyer.subsidiary_id IS DISTINCT FROM NEW.buyer_subsidiary_id THEN
    RAISE EXCEPTION 'intercompany pair documents must belong to the pair''s selling and buying subsidiaries'
      USING errcode = '23514';
  END IF;
  IF v_seller.status = 'voided' OR v_buyer.status = 'voided' THEN
    RAISE EXCEPTION 'a voided document cannot be paired' USING errcode = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: intercompany_transfer_pricing_policy_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.intercompany_transfer_pricing_policy_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_last date;
  v_account record;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD))
       OR public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    IF EXISTS (SELECT 1 FROM public.intercompany_fulfillment_charges c WHERE c.org_id = OLD.org_id AND c.policy_id = OLD.id) THEN
      RAISE EXCEPTION 'this transfer pricing policy has priced charges; end its window instead of deleting it';
    END IF;
    RETURN OLD;
  END IF;
  IF TG_OP = 'INSERT' AND public.openbooks_clone_authority() THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    SELECT max(c.charge_date) INTO v_last FROM public.intercompany_fulfillment_charges c
     WHERE c.org_id = OLD.org_id AND c.policy_id = OLD.id;
    IF v_last IS NOT NULL THEN
      IF (NEW.code, NEW.seller_subsidiary_id, NEW.buyer_subsidiary_id, NEW.method, NEW.price_level_id,
          NEW.markup_percent, NEW.revenue_account_id, NEW.cost_account_id, NEW.effective_from)
         IS DISTINCT FROM
         (OLD.code, OLD.seller_subsidiary_id, OLD.buyer_subsidiary_id, OLD.method, OLD.price_level_id,
          OLD.markup_percent, OLD.revenue_account_id, OLD.cost_account_id, OLD.effective_from) THEN
        RAISE EXCEPTION 'this transfer pricing policy has priced charges and keeps its terms; end it and create a new dated policy';
      END IF;
      IF NEW.effective_to IS NOT NULL AND NEW.effective_to < v_last THEN
        RAISE EXCEPTION 'this transfer pricing policy priced a charge on %; its window cannot end before that date', v_last;
      END IF;
    END IF;
    -- Ending or deactivating a policy never re-validates terms it already holds.
    IF (NEW.seller_subsidiary_id, NEW.buyer_subsidiary_id, NEW.revenue_account_id, NEW.cost_account_id)
       IS NOT DISTINCT FROM
       (OLD.seller_subsidiary_id, OLD.buyer_subsidiary_id, OLD.revenue_account_id, OLD.cost_account_id) THEN
      RETURN NEW;
    END IF;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.subsidiaries s
     WHERE s.org_id = NEW.org_id AND s.id = NEW.seller_subsidiary_id AND s.is_active AND NOT s.is_elimination
  ) OR (NEW.buyer_subsidiary_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.subsidiaries s
     WHERE s.org_id = NEW.org_id AND s.id = NEW.buyer_subsidiary_id AND s.is_active AND NOT s.is_elimination
  )) THEN
    RAISE EXCEPTION 'transfer pricing applies between active operating subsidiaries' USING errcode = '23514';
  END IF;
  FOR v_account IN
    SELECT account_id, types, label FROM (VALUES
      (NEW.revenue_account_id, ARRAY['income', 'income_other'], 'intercompany revenue'),
      (NEW.cost_account_id, ARRAY['cogs', 'expense', 'expense_other'], 'intercompany cost')
    ) AS a(account_id, types, label)
  LOOP
    IF NOT EXISTS (
      SELECT 1 FROM public.accounts a
       WHERE a.org_id = NEW.org_id AND a.id = v_account.account_id
         AND a.is_active AND NOT a.is_summary AND a.eliminate AND a.type = ANY (v_account.types)
    ) THEN
      RAISE EXCEPTION 'the % account must be an active eliminated posting account of type %', v_account.label, array_to_string(v_account.types, ', ')
        USING errcode = '23514';
    END IF;
  END LOOP;
  RETURN NEW;
END;
$$;


--
-- Name: internal_billing_rules_history_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.internal_billing_rules_history_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF public.app_bypass_rls_active() AND coalesce(current_setting('openbooks.amend', true), 'off') = 'on' THEN
   IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
   RETURN NEW;
 END IF;
 IF TG_OP = 'DELETE' THEN
   RAISE EXCEPTION 'Internal billing rule history is preserved; deactivate the version instead of deleting it in Setup → Internal billing'
   USING ERRCODE = '23514';
 END IF;
 IF ROW(OLD.org_id, OLD.id, OLD.code, OLD.method, OLD.debit_account_id, OLD.credit_account_id,
        OLD.effective_from, OLD.created_at, OLD.created_by)
    IS DISTINCT FROM
    ROW(NEW.org_id, NEW.id, NEW.code, NEW.method, NEW.debit_account_id, NEW.credit_account_id,
        NEW.effective_from, NEW.created_at, NEW.created_by) THEN
   RAISE EXCEPTION 'Internal billing rule versions keep their accounting treatment; close the window and add a new version in Setup → Internal billing'
   USING ERRCODE = '23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: inv_move_fill_subsidiary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inv_move_fill_subsidiary() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  owner uuid;
BEGIN
  IF NEW.subsidiary_id IS NOT NULL THEN
    RETURN NEW;
  END IF;
  SELECT je.subsidiary_id INTO owner
    FROM public.journal_entries je
   WHERE je.id = NEW.journal_entry_id
     AND je.org_id = NEW.org_id;
  IF owner IS NULL THEN
    SELECT s.id INTO owner
      FROM public.subsidiaries s
     WHERE s.org_id = NEW.org_id
       AND s.parent_id IS NULL
     ORDER BY s.created_at
     LIMIT 1;
  END IF;
  IF owner IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = 'check_violation',
      MESSAGE = 'inventory movement requires a legal-entity owner',
      DETAIL = 'No subsidiary could be derived from the movement''s journal entry or organization root.',
      HINT = 'Supply subsidiary_id explicitly or configure a root subsidiary first.';
  END IF;
  NEW.subsidiary_id := owner;
  RETURN NEW;
END;
$$;


--
-- Name: inv_move_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inv_move_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  if tg_op = 'DELETE' then
    if old.status = 'posted' and not openbooks_sandbox_wipe_allowed(old.org_id) then
      raise exception 'inventory movement % is posted and cannot be deleted', old.id;
    end if;
    return old;
  end if;
  if old.status = 'posted' and new.status = 'posted' then
    raise exception 'inventory movement % is posted and immutable', old.id;
  end if;
  return new;
end $$;


--
-- Name: inv_provisional_fill_subsidiary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inv_provisional_fill_subsidiary() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  owner uuid;
BEGIN
  IF NEW.subsidiary_id IS NOT NULL THEN
    RETURN NEW;
  END IF;
  SELECT m.subsidiary_id INTO owner
    FROM public.inventory_movements m
   WHERE m.id = NEW.issue_movement_id
     AND m.org_id = NEW.org_id;
  IF owner IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = 'check_violation',
      MESSAGE = 'inventory provisional cost requires the legal entity of its issue movement',
      DETAIL = 'The issue movement was not found, so ownership could not be derived.',
      HINT = 'Create the issue movement before recording its provisional cost.';
  END IF;
  NEW.subsidiary_id := owner;
  RETURN NEW;
END;
$$;


--
-- Name: inventory_consumed_original_cost_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_consumed_original_cost_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF ROW(NEW.org_id,NEW.subsidiary_id,NEW.cost_layer_id,NEW.issue_movement_id,NEW.quantity,NEW.unit_cost,NEW.original_cost)
     IS DISTINCT FROM ROW(OLD.org_id,OLD.subsidiary_id,OLD.cost_layer_id,OLD.issue_movement_id,OLD.quantity,OLD.unit_cost,OLD.original_cost) THEN
    RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='inventory_consumed_original_cost_immutable',
      MESSAGE='inventory consumption cost evidence is immutable; use controlled reversal';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: inventory_count_policy_history_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_count_policy_history_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 IF OLD.effective_from<=current_date THEN
  IF TG_OP='UPDATE' AND (NEW.org_id,NEW.subsidiary_id,NEW.abc_class,NEW.interval_days,NEW.variance_tolerance,NEW.effective_from)
   IS NOT DISTINCT FROM (OLD.org_id,OLD.subsidiary_id,OLD.abc_class,OLD.interval_days,OLD.variance_tolerance,OLD.effective_from)
   AND NEW.effective_to IS NOT NULL AND NEW.effective_to>=current_date AND (OLD.effective_to IS NULL OR NEW.effective_to<=OLD.effective_to) THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'Effective cycle-count policies are immutable; close the policy and add a successor';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $$;


--
-- Name: inventory_inspection_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_inspection_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Inspection evidence is immutable.' USING ERRCODE='23514'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'pending' OR NEW.disposition IS NOT NULL OR NEW.inspected_by IS NOT NULL THEN RAISE EXCEPTION 'Inspections start pending.' USING ERRCODE='23514'; END IF;
  IF NEW.operation_id IS NOT NULL THEN
   PERFORM id FROM mfg_wo_operations WHERE org_id=NEW.org_id AND id=NEW.operation_id FOR UPDATE;
   SELECT coalesce(max(inspection_sequence),0)+1 INTO NEW.inspection_sequence FROM inventory_inspections WHERE org_id=NEW.org_id AND operation_id=NEW.operation_id;
  END IF;
  IF NEW.receipt_movement_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM inventory_movements source WHERE source.org_id=NEW.org_id AND source.id=NEW.receipt_movement_id AND source.status='posted' AND source.reverses_movement_id IS NULL AND source.quantity=NEW.quantity AND source.quantity>0 AND source.item_id=NEW.item_id AND source.subsidiary_id=NEW.subsidiary_id AND source.stock_location_id=NEW.stock_location_id AND source.lot_id IS NOT DISTINCT FROM NEW.lot_id AND source.serial_id IS NOT DISTINCT FROM NEW.serial_id) THEN RAISE EXCEPTION 'Receipt inspection must bind its exact native stock receipt.' USING ERRCODE='23514'; END IF;
  IF NEW.operation_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM mfg_wo_operations operation JOIN mfg_work_orders work ON work.org_id=operation.org_id AND work.id=operation.work_order_id WHERE operation.org_id=NEW.org_id AND operation.id=NEW.operation_id AND work.id=NEW.work_order_id AND work.subsidiary_id=NEW.subsidiary_id AND work.produced_item_id=NEW.item_id AND operation.status IN('pending','running','paused') AND operation.inspection_plan_snapshot=NEW.plan_snapshot) THEN RAISE EXCEPTION 'Operation inspection must bind its released work and frozen plan.' USING ERRCODE='23514'; END IF;
 ELSE
  IF (to_jsonb(NEW)-ARRAY['quantity','lot_id','serial_id','status','measurements','reason','inspected_at','inspected_by','disposition','disposition_reason','disposition_result','disposed_at','disposed_by','rework_work_order_id','rework_operation_id','rework_completed_at','scrap_movement_id','updated_at','updated_by']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['quantity','lot_id','serial_id','status','measurements','reason','inspected_at','inspected_by','disposition','disposition_reason','disposition_result','disposed_at','disposed_by','rework_work_order_id','rework_operation_id','rework_completed_at','scrap_movement_id','updated_at','updated_by']) THEN RAISE EXCEPTION 'Inspection subject and plan are immutable.' USING ERRCODE='23514'; END IF;
  IF OLD.status<>'pending' AND (NEW.quantity,NEW.lot_id,NEW.serial_id,NEW.status,NEW.measurements,NEW.reason,NEW.inspected_at,NEW.inspected_by) IS DISTINCT FROM (OLD.quantity,OLD.lot_id,OLD.serial_id,OLD.status,OLD.measurements,OLD.reason,OLD.inspected_at,OLD.inspected_by) THEN RAISE EXCEPTION 'Recorded inspection results are immutable.' USING ERRCODE='23514'; END IF;
  IF NEW.receipt_movement_id IS NOT NULL AND NEW.quantity IS DISTINCT FROM OLD.quantity THEN RAISE EXCEPTION 'Receipt inspection quantity retains its stock source.' USING ERRCODE='23514'; END IF;
  IF OLD.status='pending' AND NEW.status NOT IN ('pending','pass','fail') THEN RAISE EXCEPTION 'Invalid inspection result.' USING ERRCODE='23514'; END IF;
  IF OLD.disposition IS NOT NULL AND (NEW.disposition,NEW.disposition_reason,NEW.disposition_result,NEW.disposed_at,NEW.disposed_by,NEW.rework_work_order_id,NEW.rework_operation_id,NEW.scrap_movement_id) IS DISTINCT FROM (OLD.disposition,OLD.disposition_reason,OLD.disposition_result,OLD.disposed_at,OLD.disposed_by,OLD.rework_work_order_id,OLD.rework_operation_id,OLD.scrap_movement_id) THEN RAISE EXCEPTION 'Recorded quality dispositions are immutable.' USING ERRCODE='23514'; END IF;
  IF OLD.scrap_movement_id IS NOT NULL AND NEW.scrap_movement_id IS DISTINCT FROM OLD.scrap_movement_id THEN RAISE EXCEPTION 'Quality scrap has one immutable inventory effect.' USING ERRCODE='23514'; END IF;
  IF OLD.rework_completed_at IS NOT NULL AND NEW.rework_completed_at IS DISTINCT FROM OLD.rework_completed_at THEN RAISE EXCEPTION 'Rework completion is immutable.' USING ERRCODE='23514'; END IF;
 END IF;
 IF (NEW.disposition='rework' AND NEW.receipt_movement_id IS NOT NULL) IS DISTINCT FROM (NEW.rework_work_order_id IS NOT NULL) AND NEW.disposition IS NOT NULL THEN RAISE EXCEPTION 'Receipt rework requires its native repair order.' USING ERRCODE='23514'; END IF;
 IF NEW.rework_work_order_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM mfg_work_orders repair WHERE repair.org_id=NEW.org_id AND repair.id=NEW.rework_work_order_id AND repair.receipt_rework_inspection_id=NEW.id) THEN RAISE EXCEPTION 'The repair order must retain this exact failed inspection.' USING ERRCODE='23514'; END IF;
 IF NEW.operation_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM mfg_wo_operations WHERE org_id=NEW.org_id AND id=NEW.operation_id AND work_order_id=NEW.work_order_id AND NEW.quantity<=quantity_planned) THEN RAISE EXCEPTION 'Operation inspection cannot exceed its released planned quantity.' USING ERRCODE='23514'; END IF;
 IF NEW.status<>'pending' THEN
  IF NEW.operation_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM item_inventory_profiles profile WHERE profile.org_id=NEW.org_id AND profile.item_id=NEW.item_id AND
    ((profile.tracking='none' AND NEW.lot_id IS NULL AND NEW.serial_id IS NULL) OR (profile.tracking='lot' AND NEW.lot_id IS NOT NULL AND NEW.serial_id IS NULL) OR (profile.tracking='serial' AND NEW.serial_id IS NOT NULL AND NEW.lot_id IS NULL AND NEW.quantity=1) OR (profile.tracking='lot_serial' AND NEW.lot_id IS NOT NULL AND NEW.serial_id IS NOT NULL AND NEW.quantity=1))) THEN
    RAISE EXCEPTION 'Operation inspection identifiers must match the produced item tracking policy.' USING ERRCODE='23514';
  END IF;
  IF jsonb_typeof(NEW.measurements)<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(NEW.measurements) supplied(key) WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.plan_snapshot->'measures') measure WHERE measure->>'key'=supplied.key))
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.plan_snapshot->'measures') measure WHERE (measure->>'required')::boolean AND coalesce(NEW.measurements->> (measure->>'key'),'')='')
   OR EXISTS(SELECT 1 FROM jsonb_each_text(NEW.measurements) reading WHERE reading.value<>'' AND reading.value !~ '^-?[0-9]+([.][0-9]{1,4})?$')
   OR EXISTS(SELECT 1 FROM jsonb_each_text(NEW.measurements) reading WHERE CASE WHEN reading.value ~ '^-?[0-9]+([.][0-9]{1,4})?$' THEN abs(reading.value::numeric)>999999999999999.9999 ELSE false END) THEN
   RAISE EXCEPTION 'Inspection result requires exact known measurements and every required reading.' USING ERRCODE='23514';
  END IF;
  IF NEW.status='pass' AND EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.plan_snapshot->'measures') measure WHERE nullif(NEW.measurements->>(measure->>'key'),'') IS NOT NULL
    AND ((measure->>'minimum' IS NOT NULL AND (NEW.measurements->>(measure->>'key'))::numeric<(measure->>'minimum')::numeric)
      OR (measure->>'maximum' IS NOT NULL AND (NEW.measurements->>(measure->>'key'))::numeric>(measure->>'maximum')::numeric))) THEN
    RAISE EXCEPTION 'An out-of-range frozen measurement cannot pass inspection.' USING ERRCODE='23514';
  END IF;
 END IF;
 IF NEW.lot_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM lots WHERE org_id=NEW.org_id AND id=NEW.lot_id AND item_id=NEW.item_id) THEN RAISE EXCEPTION 'Inspection lot must identify its item.' USING ERRCODE='23514'; END IF;
 IF NEW.serial_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM serials WHERE org_id=NEW.org_id AND id=NEW.serial_id AND item_id=NEW.item_id AND (NEW.lot_id IS NULL OR lot_id IS NOT DISTINCT FROM NEW.lot_id)) THEN RAISE EXCEPTION 'Inspection serial must identify its item and lot.' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $_$;


--
-- Name: inventory_inspection_plan_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_inspection_plan_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Inspection plans retain their history; end the effective window.' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' AND NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION 'Inspection plan changes require the next revision.' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' AND (EXISTS(SELECT 1 FROM inventory_inspections WHERE org_id=OLD.org_id AND plan_id=OLD.id) OR EXISTS(SELECT 1 FROM mfg_wo_operations WHERE org_id=OLD.org_id AND inspection_plan_snapshot->>'id'=OLD.id::text)) AND
  ((to_jsonb(NEW)-ARRAY['effective_to','revision','reason','updated_at','updated_by']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['effective_to','revision','reason','updated_at','updated_by']) OR NEW.effective_to IS NULL OR NEW.effective_to<(SELECT (now() AT TIME ZONE coalesce(nullif(settings->>'timeZone',''),'UTC'))::date FROM orgs WHERE id=NEW.org_id) OR (OLD.effective_to IS NOT NULL AND NEW.effective_to>OLD.effective_to)) THEN
  RAISE EXCEPTION 'Used inspection plans retain their content and historical effective window.' USING ERRCODE='23514';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtext('inventory.inspection.plan'),hashtext(NEW.org_id::text||NEW.item_id::text||NEW.point||coalesce(NEW.operation_sequence::text,'')));
 IF EXISTS(SELECT 1 FROM inventory_inspection_plans WHERE org_id=NEW.org_id AND item_id=NEW.item_id AND point=NEW.point AND operation_sequence IS NOT DISTINCT FROM NEW.operation_sequence AND id<>NEW.id AND daterange(effective_from,effective_to,'[)') && daterange(NEW.effective_from,NEW.effective_to,'[)')) THEN
  RAISE EXCEPTION 'Inspection plan effective windows overlap.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: inventory_inspection_rework_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_inspection_rework_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF NEW.rework_completed_at IS NOT NULL AND OLD.rework_completed_at IS NULL AND NOT (
  NEW.rework_work_order_id IS NOT NULL AND EXISTS(SELECT 1 FROM mfg_work_orders repair JOIN inventory_movements receipt ON receipt.org_id=repair.org_id JOIN journal_entries entry ON entry.org_id=receipt.org_id AND entry.id=receipt.journal_entry_id WHERE repair.org_id=NEW.org_id AND repair.id=NEW.rework_work_order_id AND repair.receipt_rework_inspection_id=NEW.id AND repair.quantity_completed>=NEW.quantity AND receipt.kind='assembly_build' AND receipt.quantity=NEW.quantity AND receipt.lot_id IS NOT DISTINCT FROM NEW.lot_id AND receipt.serial_id IS NOT DISTINCT FROM NEW.serial_id AND receipt.item_id=NEW.item_id AND receipt.status='posted' AND entry.status='posted' AND entry.custom->>'work_order_number'=repair.number)
  OR NEW.rework_work_order_id IS NOT NULL AND EXISTS(SELECT 1 FROM mfg_work_orders repair JOIN financial_changes loss ON loss.org_id=repair.org_id AND loss.id=repair.loss_change_id WHERE repair.org_id=NEW.org_id AND repair.id=NEW.rework_work_order_id AND repair.receipt_rework_inspection_id=NEW.id AND repair.status='cancelled' AND repair.quantity_completed=0 AND repair.quantity_scrapped=NEW.quantity AND loss.status='applied' AND loss.domain='manufacturing' AND loss.operation='work_order_loss_disposition' AND loss.subject_id=repair.id)
  OR EXISTS(
  SELECT 1 FROM mfg_wo_operations operation JOIN inventory_inspections repaired ON repaired.org_id=operation.org_id AND repaired.operation_id=operation.id
   WHERE operation.org_id=NEW.org_id AND operation.id=NEW.rework_operation_id AND operation.status='done' AND operation.quantity_done>=NEW.quantity
     AND repaired.status='pass' AND repaired.quantity>=NEW.quantity AND repaired.lot_id IS NOT DISTINCT FROM NEW.lot_id AND repaired.serial_id IS NOT DISTINCT FROM NEW.serial_id
     AND NOT EXISTS(SELECT 1 FROM inventory_inspections newer WHERE newer.org_id=repaired.org_id AND newer.operation_id=repaired.operation_id
       AND newer.lot_id IS NOT DISTINCT FROM repaired.lot_id AND newer.serial_id IS NOT DISTINCT FROM repaired.serial_id AND newer.inspection_sequence>repaired.inspection_sequence)
 )) THEN RAISE EXCEPTION 'Rework completion requires accepted evidence for the same stock and quantity.' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: inventory_inspection_scrap_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_inspection_scrap_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE inspection inventory_inspections;
BEGIN
 IF public.openbooks_clone_authority() THEN RETURN NULL; END IF;
 SELECT * INTO inspection FROM inventory_inspections WHERE org_id=NEW.org_id AND id=NEW.id;
 IF inspection.scrap_movement_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM inventory_movements movement JOIN journal_entries entry ON entry.org_id=movement.org_id AND entry.id=movement.journal_entry_id WHERE movement.org_id=inspection.org_id AND movement.id=inspection.scrap_movement_id AND movement.status='posted' AND entry.status='posted' AND movement.item_id=inspection.item_id AND movement.subsidiary_id=inspection.subsidiary_id AND movement.stock_location_id=inspection.stock_location_id AND movement.lot_id IS NOT DISTINCT FROM inspection.lot_id AND movement.serial_id IS NOT DISTINCT FROM inspection.serial_id AND movement.quantity=-inspection.quantity AND inspection.disposition='scrap' AND inspection.disposition_result->>'movementId'=movement.id::text) THEN RAISE EXCEPTION 'Quality scrap requires its exact posted inventory disposition.' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $$;


--
-- Name: inventory_lot_identity_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_lot_identity_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
    RAISE EXCEPTION 'lot identity and recall evidence cannot be deleted';
  END IF;
  IF NEW.org_id IS DISTINCT FROM OLD.org_id
     OR NEW.item_id IS DISTINCT FROM OLD.item_id
     OR NEW.lot_number IS DISTINCT FROM OLD.lot_number
     OR (OLD.expires_on IS NOT NULL
         AND NEW.expires_on IS DISTINCT FROM OLD.expires_on) THEN
    RAISE EXCEPTION 'lot identity is immutable; only a missing expiry may be completed';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: inventory_movement_tracking_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_movement_tracking_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE tracking_mode text; serial_lot uuid;
BEGIN
 SELECT tracking INTO tracking_mode FROM public.item_inventory_profiles WHERE org_id=NEW.org_id AND item_id=NEW.item_id;
 IF tracking_mode IS NULL OR tracking_mode NOT IN('none','lot','serial','lot_serial') THEN
  RAISE EXCEPTION 'Inventory movement requires a supported tenant-owned profile' USING ERRCODE='23514';
 END IF;
 IF tracking_mode='none' AND num_nonnulls(NEW.lot_id,NEW.serial_id)>0 THEN
  RAISE EXCEPTION 'Untracked stock cannot carry identifiers' USING ERRCODE='23514';
 END IF;
 IF tracking_mode IN('lot','lot_serial') THEN
  IF NEW.lot_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.lots WHERE org_id=NEW.org_id AND id=NEW.lot_id AND item_id=NEW.item_id) THEN
   RAISE EXCEPTION 'Lot tracking requires the item and tenant lot' USING ERRCODE='23514';
  END IF;
 ELSIF NEW.lot_id IS NOT NULL THEN RAISE EXCEPTION 'This profile does not track lots' USING ERRCODE='23514'; END IF;
 IF tracking_mode IN('serial','lot_serial') THEN
  IF NEW.serial_id IS NULL OR abs(NEW.quantity)<>1 OR NOT EXISTS(SELECT 1 FROM public.serials WHERE org_id=NEW.org_id AND id=NEW.serial_id AND item_id=NEW.item_id) THEN
   RAISE EXCEPTION 'Serial tracking requires exactly one unit of the item and tenant serial' USING ERRCODE='23514';
  END IF;
  SELECT lot_id INTO serial_lot FROM public.serials WHERE org_id=NEW.org_id AND id=NEW.serial_id;
  IF tracking_mode='lot_serial' AND serial_lot IS DISTINCT FROM NEW.lot_id THEN
   RAISE EXCEPTION 'Serial must belong to the movement lot' USING ERRCODE='23514';
  END IF;
 ELSIF NEW.serial_id IS NOT NULL THEN RAISE EXCEPTION 'This profile does not track serials' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: inventory_original_cost_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_original_cost_audit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' OR NEW.remaining_original_cost IS DISTINCT FROM OLD.remaining_original_cost THEN
    INSERT INTO public.audit_log (org_id,table_name,row_id,action,changes,actor_id)
    VALUES (NEW.org_id,'cost_layers',NEW.id,lower(TG_OP),
      jsonb_build_object('reason',CASE WHEN TG_OP='UPDATE' AND
          current_setting('openbooks.inventory_original_cost_writer',true) IS DISTINCT FROM 'basis-v1'
          AND OLD.remaining_original_cost IS NOT NULL AND NEW.remaining_original_cost IS NULL
        THEN 'Original-cost provenance invalidated by an unversioned inventory writer'
        ELSE 'Inventory original-cost balance change' END,
        'before',CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE NULL END,'after',to_jsonb(NEW)),
      CASE WHEN TG_OP='INSERT' THEN NEW.created_by
        WHEN current_setting('openbooks.inventory_original_cost_writer',true)='basis-v1' THEN NEW.updated_by ELSE NULL END);
  END IF;
  RETURN NEW;
END $$;


--
-- Name: inventory_original_cost_writer_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_original_cost_writer_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF current_setting('openbooks.inventory_original_cost_writer',true) IS DISTINCT FROM 'basis-v1'
     AND ROW(NEW.original_quantity,NEW.remaining_quantity,NEW.unit_cost,NEW.source_movement_id,
             NEW.org_id,NEW.subsidiary_id,NEW.item_id,NEW.stock_location_id)
       IS DISTINCT FROM ROW(OLD.original_quantity,OLD.remaining_quantity,OLD.unit_cost,OLD.source_movement_id,
             OLD.org_id,OLD.subsidiary_id,OLD.item_id,OLD.stock_location_id) THEN
    NEW.remaining_original_cost := NULL;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: inventory_owned_position_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_owned_position_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE ownership text;
BEGIN
 SELECT inventory_ownership INTO ownership FROM public.stock_locations WHERE org_id=NEW.org_id AND id=NEW.stock_location_id FOR SHARE;
 IF ownership IS DISTINCT FROM 'owned' THEN RAISE EXCEPTION 'Valued inventory requires an owned stock location; use the custody command'; END IF;
 IF NEW.serial_id IS NOT NULL THEN
  PERFORM id FROM public.serials WHERE org_id=NEW.org_id AND id=NEW.serial_id FOR UPDATE;
  IF NEW.quantity>0 AND EXISTS(SELECT 1 FROM public.consignment_stock WHERE org_id=NEW.org_id AND serial_id=NEW.serial_id AND remaining_quantity>0) THEN
   RAISE EXCEPTION 'Serial is externally owned; take ownership through the custody command';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: inventory_provisional_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_provisional_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  if tg_op = 'DELETE' and public.openbooks_sandbox_wipe_allowed(old.org_id) then
    return old;
  end if;
  raise exception 'inventory provisional evidence is immutable';
end $$;


--
-- Name: stock_count_lines; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.stock_count_lines (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    stock_count_id uuid NOT NULL,
    item_id uuid NOT NULL,
    stock_location_id uuid NOT NULL,
    lot_id uuid,
    expected_quantity numeric(19,4) NOT NULL,
    counted_quantity numeric(19,4),
    adjustment_movement_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    is_pre_guard_legacy boolean DEFAULT false NOT NULL,
    serial_id uuid,
    variance_tolerance numeric(19,4),
    first_counted_quantity numeric(19,4),
    second_counted_quantity numeric(19,4),
    first_counted_by uuid,
    second_counted_by uuid,
    second_counted_at timestamp with time zone,
    CONSTRAINT stock_count_lines_counted_nonnegative CHECK (((counted_quantity IS NULL) OR (counted_quantity >= (0)::numeric) OR is_pre_guard_legacy)),
    CONSTRAINT stock_count_lines_first_counted_quantity_check CHECK ((first_counted_quantity >= (0)::numeric)),
    CONSTRAINT stock_count_lines_second_counted_quantity_check CHECK ((second_counted_quantity >= (0)::numeric)),
    CONSTRAINT stock_count_lines_variance_tolerance_check CHECK ((variance_tolerance >= (0)::numeric))
);

ALTER TABLE ONLY public.stock_count_lines FORCE ROW LEVEL SECURITY;


--
-- Name: COLUMN stock_count_lines.is_pre_guard_legacy; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.stock_count_lines.is_pre_guard_legacy IS 'True for lines that predate the duplicate-subject and non-negative guards on an immutable (posted or cancelled) count and are preserved as evidence: exempt from the duplicate-subject unique index and the non-negative CHECK. Never set on new writes.';


--
-- Name: CONSTRAINT stock_count_lines_counted_nonnegative ON stock_count_lines; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT stock_count_lines_counted_nonnegative ON public.stock_count_lines IS 'A physical count is never negative: an empty bin counts 0. A negative count would post a phantom negative variance; rows marked is_pre_guard_legacy predate the guard on an immutable count and are preserved as evidence (provenance in upgrade_legacy_provenance).';


--
-- Name: inventory_serial_count_clone_line_matches(public.stock_count_lines); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_serial_count_clone_line_matches(candidate public.stock_count_lines) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT 1 FROM public.orgs target
  JOIN public.sandboxes control ON control.org_id=target.id AND control.production_org_id=target.sandbox_of
  JOIN public.stock_count_lines source ON source.org_id=target.sandbox_of
  WHERE public.openbooks_clone_authority() AND target.id=(candidate).org_id
   AND target.env_kind='sandbox' AND target.sandbox_seed IS NOT NULL
   AND public.ob_rebase(source.id,target.sandbox_seed)=(candidate).id
   AND (public.ob_rebase(source.stock_count_id,target.sandbox_seed),public.ob_rebase(source.item_id,target.sandbox_seed),
     public.ob_rebase(source.stock_location_id,target.sandbox_seed),public.ob_rebase(source.lot_id,target.sandbox_seed),
     public.ob_rebase(source.serial_id,target.sandbox_seed),public.ob_rebase(source.adjustment_movement_id,target.sandbox_seed),
     source.expected_quantity,source.counted_quantity,source.variance_tolerance,source.first_counted_quantity,
     source.second_counted_quantity,source.second_counted_at,public.ob_rebase(source.first_counted_by,target.sandbox_seed),
     public.ob_rebase(source.second_counted_by,target.sandbox_seed)) IS NOT DISTINCT FROM
    ((candidate).stock_count_id,(candidate).item_id,(candidate).stock_location_id,(candidate).lot_id,
     (candidate).serial_id,(candidate).adjustment_movement_id,(candidate).expected_quantity,(candidate).counted_quantity,
     (candidate).variance_tolerance,(candidate).first_counted_quantity,(candidate).second_counted_quantity,
     (candidate).second_counted_at,(candidate).first_counted_by,(candidate).second_counted_by)
 );
$$;


--
-- Name: serials; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.serials (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    item_id uuid NOT NULL,
    serial_number text NOT NULL,
    status text DEFAULT 'in_stock'::text NOT NULL,
    current_stock_location_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    hold_reason text,
    lot_id uuid,
    current_missing_count_movement_id uuid,
    CONSTRAINT serial_missing_count_state CHECK (((current_missing_count_movement_id IS NULL) OR ((status = 'shipped'::text) AND (current_stock_location_id IS NULL)))),
    CONSTRAINT serials_hold_reason_check CHECK (((hold_reason IS NULL) OR ((length(btrim(hold_reason)) >= 5) AND (length(btrim(hold_reason)) <= 500)))),
    CONSTRAINT serials_status_location CHECK ((((status = 'in_stock'::text) AND (current_stock_location_id IS NOT NULL)) OR ((status <> 'in_stock'::text) AND (current_stock_location_id IS NULL))))
);

ALTER TABLE ONLY public.serials FORCE ROW LEVEL SECURITY;


--
-- Name: inventory_serial_count_clone_marker_matches(public.serials); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_serial_count_clone_marker_matches(candidate public.serials) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT 1 FROM public.orgs target
  JOIN public.sandboxes control ON control.org_id=target.id AND control.production_org_id=target.sandbox_of
  JOIN public.serials source ON source.org_id=target.sandbox_of
  WHERE public.openbooks_clone_authority() AND target.id=(candidate).org_id
   AND target.env_kind='sandbox' AND target.sandbox_seed IS NOT NULL
   AND public.ob_rebase(source.id,target.sandbox_seed)=(candidate).id
   AND (public.ob_rebase(source.item_id,target.sandbox_seed),public.ob_rebase(source.lot_id,target.sandbox_seed),
     public.ob_rebase(source.current_stock_location_id,target.sandbox_seed),source.status,
     public.ob_rebase(source.current_missing_count_movement_id,target.sandbox_seed)) IS NOT DISTINCT FROM
    ((candidate).item_id,(candidate).lot_id,(candidate).current_stock_location_id,(candidate).status,
     (candidate).current_missing_count_movement_id)
 );
$$;


--
-- Name: inventory_serial_count_history_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_serial_count_history_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 IF OLD.serial_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.stock_counts count
   WHERE count.org_id=OLD.org_id AND count.id=OLD.stock_count_id AND count.status='posted') THEN
  RAISE EXCEPTION 'Posted serial count observations and movement associations are immutable; record a new count';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $$;


--
-- Name: inventory_serial_count_line_matches(uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_serial_count_line_matches(subject_org uuid, subject_line uuid, subject_movement uuid, require_posted boolean) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
 SELECT EXISTS(
  SELECT 1 FROM public.stock_count_lines line
  JOIN public.stock_counts count ON count.org_id=line.org_id AND count.id=line.stock_count_id
  JOIN public.inventory_movements movement ON movement.org_id=line.org_id AND movement.id=line.adjustment_movement_id
  JOIN public.journal_entries entry ON entry.org_id=movement.org_id AND entry.id=movement.journal_entry_id
  JOIN public.serials serial ON serial.org_id=line.org_id AND serial.id=line.serial_id
  JOIN public.users actor ON actor.org_id=movement.org_id AND actor.id=movement.created_by
  WHERE line.org_id=subject_org AND line.id=subject_line AND movement.id=subject_movement
   AND count.status=CASE WHEN require_posted THEN 'posted' ELSE 'review' END
   AND movement.status='posted' AND movement.kind IN('receipt','issue')
   AND movement.item_id=line.item_id AND movement.stock_location_id=line.stock_location_id
   AND movement.subsidiary_id=count.subsidiary_id AND movement.serial_id=line.serial_id
   AND movement.lot_id IS NOT DISTINCT FROM line.lot_id
   AND serial.item_id=line.item_id AND serial.lot_id IS NOT DISTINCT FROM line.lot_id
   AND movement.moved_at::date=count.counted_on AND movement.quantity=line.counted_quantity-line.expected_quantity
   AND ((movement.kind='receipt' AND line.expected_quantity=0 AND line.counted_quantity=1 AND movement.quantity=1)
     OR (movement.kind='issue' AND line.expected_quantity=1 AND line.counted_quantity=0 AND movement.quantity=-1))
   AND line.first_counted_quantity IS NOT NULL AND line.first_counted_by IS NOT NULL
   AND line.first_counted_quantity IN(0,1) AND line.variance_tolerance IS NOT NULL
   AND EXISTS(SELECT 1 FROM public.users observer WHERE observer.org_id=line.org_id AND observer.id=line.first_counted_by)
   AND (abs(line.first_counted_quantity-line.expected_quantity)<=line.variance_tolerance
     OR (line.second_counted_quantity=line.counted_quantity AND line.second_counted_at IS NOT NULL
       AND EXISTS(SELECT 1 FROM public.users observer WHERE observer.org_id=line.org_id AND observer.id=line.second_counted_by)))
   AND entry.status='posted' AND entry.origin='inventory' AND entry.subsidiary_id=count.subsidiary_id
   AND entry.posting_date=count.counted_on AND entry.posted_by=movement.created_by
   AND line.updated_by=movement.created_by
   AND (require_posted OR movement.xmin=(pg_current_xact_id()::text::bigint % 4294967296)::text::xid)

 );
$$;


--
-- Name: inventory_serial_count_marker_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_serial_count_marker_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.current_missing_count_movement_id IS NULL OR public.inventory_serial_count_clone_marker_matches(NEW) THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'Serial missing-count identity requires its native posted transition';
 END IF;
 IF NEW.current_missing_count_movement_id IS DISTINCT FROM OLD.current_missing_count_movement_id
    AND NEW.current_missing_count_movement_id IS NOT NULL THEN
  IF OLD.status='in_stock' AND NEW.status='shipped' AND NEW.current_stock_location_id IS NULL AND EXISTS(
   SELECT 1 FROM public.stock_count_lines line JOIN public.inventory_movements movement
    ON movement.org_id=line.org_id AND movement.id=line.adjustment_movement_id
   WHERE line.org_id=NEW.org_id AND movement.id=NEW.current_missing_count_movement_id
    AND movement.kind='issue' AND movement.serial_id=NEW.id AND movement.item_id=NEW.item_id
    AND movement.stock_location_id=OLD.current_stock_location_id AND movement.lot_id IS NOT DISTINCT FROM NEW.lot_id
    AND public.inventory_serial_count_line_matches(NEW.org_id,line.id,movement.id,false)
  ) THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'Serial missing-count identity must match its exact current count issue';
 END IF;
 IF (NEW.status,NEW.current_stock_location_id) IS DISTINCT FROM (OLD.status,OLD.current_stock_location_id) THEN
  NEW.current_missing_count_movement_id=NULL;
  RETURN NEW;
 END IF;
 IF NEW.current_missing_count_movement_id IS DISTINCT FROM OLD.current_missing_count_movement_id THEN
  RAISE EXCEPTION 'Serial missing-count identity cannot change without its lifecycle transition';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: inventory_serial_count_posted_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_serial_count_posted_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF NEW.serial_id IS NULL OR NEW.adjustment_movement_id IS NULL THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN
  IF public.inventory_serial_count_clone_line_matches(NEW) THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'Copied serial count evidence must retain its exact registered source identity and observations';
 END IF;
 IF TG_OP='UPDATE' AND NEW.adjustment_movement_id IS NOT DISTINCT FROM OLD.adjustment_movement_id THEN RETURN NEW; END IF;
 IF NOT public.inventory_serial_count_line_matches(NEW.org_id,NEW.id,NEW.adjustment_movement_id,true)
    OR NOT EXISTS(
     SELECT 1 FROM public.stock_count_lines line
     JOIN public.stock_counts count ON count.org_id=line.org_id AND count.id=line.stock_count_id
     JOIN public.inventory_movements movement ON movement.org_id=line.org_id AND movement.id=line.adjustment_movement_id
     JOIN public.audit_log audit ON audit.org_id=count.org_id AND audit.table_name='stock_counts' AND audit.row_id=count.id
     WHERE line.org_id=NEW.org_id AND line.id=NEW.id AND movement.id=NEW.adjustment_movement_id
      AND movement.xmin=(pg_current_xact_id()::text::bigint % 4294967296)::text::xid
      AND audit.xmin=movement.xmin AND audit.changes->>'operation'='post'
      AND audit.actor_id=movement.created_by AND audit.changes->'review'->>'postedBy'=audit.actor_id::text
      AND count.updated_by=audit.actor_id AND count.review_released
      AND audit.changes->'review'->'policy'=count.submission_policy
      AND EXISTS(SELECT 1 FROM public.flow_submissions submission
        WHERE submission.org_id=count.org_id AND submission.subject_kind='stock_count'
          AND submission.subject_id=count.id AND submission.policy=count.submission_policy
          AND ((submission.policy->>'kind'='ungated' AND
            public.flow_ungated_submission_authorized(submission.org_id,submission.subject_kind,submission.subject_id,count.submitted_by))
           OR (submission.policy->>'kind'='gated' AND
            public.flow_submission_approved(submission.org_id,submission.subject_kind,submission.subject_id,submission.id))))
    ) THEN
  RAISE EXCEPTION 'Serial count adjustment requires exact posted count, journal and tenant Flow review evidence';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: inventory_serial_count_restoration_matches(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_serial_count_restoration_matches(subject_org uuid, subject_serial uuid, missing_movement uuid, destination uuid, receipt_movement uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
 SELECT EXISTS(
  SELECT 1 FROM public.inventory_movements missing
  JOIN public.stock_count_lines missing_line ON missing_line.org_id=missing.org_id AND missing_line.adjustment_movement_id=missing.id
  JOIN public.inventory_movements receipt ON receipt.org_id=missing.org_id
  JOIN public.stock_count_lines found_line ON found_line.org_id=receipt.org_id AND found_line.adjustment_movement_id=receipt.id
  WHERE missing.org_id=subject_org AND missing.id=missing_movement AND missing.serial_id=subject_serial
   AND missing.kind='issue' AND receipt.id=receipt_movement AND receipt.kind='receipt'
   AND receipt.serial_id=missing.serial_id AND receipt.item_id=missing.item_id
   AND receipt.subsidiary_id=missing.subsidiary_id AND receipt.stock_location_id=missing.stock_location_id
   AND receipt.stock_location_id=destination AND receipt.lot_id IS NOT DISTINCT FROM missing.lot_id
   AND public.inventory_serial_count_line_matches(subject_org,missing_line.id,missing.id,true)
   AND public.inventory_serial_count_line_matches(subject_org,found_line.id,receipt.id,false)
   AND NOT EXISTS(SELECT 1 FROM public.inventory_movements reversal
     WHERE reversal.org_id=missing.org_id AND reversal.reverses_movement_id=missing.id)
 );
$$;


--
-- Name: inventory_serial_lifecycle_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_serial_lifecycle_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;
  IF TG_OP = 'DELETE' THEN
    IF openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
    RAISE EXCEPTION 'serial identity and movement evidence cannot be deleted';
  END IF;
  IF NEW.org_id IS DISTINCT FROM OLD.org_id
     OR NEW.item_id IS DISTINCT FROM OLD.item_id
     OR NEW.serial_number IS DISTINCT FROM OLD.serial_number THEN
    RAISE EXCEPTION 'serial identity is immutable';
  END IF;
  IF NEW.status IS NOT DISTINCT FROM OLD.status
     AND NEW.current_stock_location_id IS NOT DISTINCT FROM OLD.current_stock_location_id THEN
    RETURN NEW;
  END IF;

  IF OLD.status = 'registered' AND NEW.status = 'in_stock'
     AND NEW.current_stock_location_id IS NOT NULL
     AND EXISTS (
       SELECT 1 FROM inventory_movements movement
        WHERE movement.org_id = OLD.org_id
          AND movement.serial_id = OLD.id
          AND movement.kind IN ('receipt', 'assembly_build')
          AND movement.quantity = 1
          AND movement.stock_location_id = NEW.current_stock_location_id
          AND movement.status = 'posted'
     ) THEN
    RETURN NEW;
  END IF;

  IF OLD.status = 'in_stock' AND NEW.status = 'shipped'
     AND NEW.current_stock_location_id IS NULL
     AND EXISTS (
       SELECT 1 FROM inventory_movements movement
        WHERE movement.org_id = OLD.org_id
          AND movement.serial_id = OLD.id
          AND movement.kind = 'issue'
          AND movement.quantity = -1
          AND movement.stock_location_id = OLD.current_stock_location_id
          AND movement.status = 'posted'
          AND NOT EXISTS (
            SELECT 1 FROM inventory_movements reversal
             WHERE reversal.org_id = movement.org_id
               AND reversal.reverses_movement_id = movement.id
          )
     ) THEN
    RETURN NEW;
  END IF;

  IF OLD.status = 'in_stock' AND NEW.status = 'in_stock'
     AND NEW.current_stock_location_id IS DISTINCT FROM OLD.current_stock_location_id
     AND (
       EXISTS (
         SELECT 1
           FROM inventory_movements outbound
           JOIN inventory_movements inbound
             ON inbound.org_id = outbound.org_id
            AND inbound.paired_movement_id = outbound.id
          WHERE outbound.org_id = OLD.org_id
            AND outbound.serial_id = OLD.id
            AND inbound.serial_id = OLD.id
            AND outbound.kind = 'transfer_out'
            AND inbound.kind = 'transfer_in'
            AND outbound.stock_location_id = OLD.current_stock_location_id
            AND inbound.stock_location_id = NEW.current_stock_location_id
            AND outbound.status = 'posted'
            AND inbound.status = 'posted'
       )
       OR EXISTS (
         SELECT 1
           FROM inventory_movements source_out
           JOIN inventory_movements source_in
             ON source_in.org_id = source_out.org_id
            AND source_in.paired_movement_id = source_out.id
           JOIN inventory_movements reversal_out
             ON reversal_out.org_id = source_out.org_id
            AND reversal_out.reverses_movement_id = source_out.id
           JOIN inventory_movements reversal_in
             ON reversal_in.org_id = source_in.org_id
            AND reversal_in.reverses_movement_id = source_in.id
          WHERE source_out.org_id = OLD.org_id
            AND source_out.serial_id = OLD.id
            AND source_in.serial_id = OLD.id
            AND source_in.stock_location_id = OLD.current_stock_location_id
            AND source_out.stock_location_id = NEW.current_stock_location_id
       )
     ) THEN
    RETURN NEW;
  END IF;

  IF OLD.status = 'shipped' AND NEW.status = 'in_stock'
     AND NEW.current_stock_location_id IS NOT NULL
     AND EXISTS (
       SELECT 1
         FROM inventory_movements source
         JOIN inventory_movements reversal
           ON reversal.org_id = source.org_id
          AND reversal.reverses_movement_id = source.id
        WHERE source.org_id = OLD.org_id
          AND source.serial_id = OLD.id
          AND source.kind IN ('issue', 'assembly_consume')
          AND source.stock_location_id = NEW.current_stock_location_id
          AND reversal.serial_id = OLD.id
          AND reversal.status = 'posted'
     ) THEN
    RETURN NEW;
  END IF;

  IF OLD.status = 'in_stock' AND NEW.status = 'returned'
     AND NEW.current_stock_location_id IS NULL
     AND EXISTS (
       SELECT 1
         FROM inventory_movements source
         JOIN inventory_movements reversal
           ON reversal.org_id = source.org_id
          AND reversal.reverses_movement_id = source.id
        WHERE source.org_id = OLD.org_id
          AND source.serial_id = OLD.id
          AND source.kind = 'receipt'
          AND source.stock_location_id = OLD.current_stock_location_id
          AND reversal.serial_id = OLD.id
          AND reversal.status = 'posted'
     ) THEN
    RETURN NEW;
  END IF;

  IF OLD.status = 'shipped' AND NEW.status = 'in_stock'
     AND OLD.current_missing_count_movement_id IS NOT NULL
     AND NEW.current_stock_location_id IS NOT NULL
     AND EXISTS (
       SELECT 1 FROM public.inventory_movements receipt
        WHERE receipt.org_id=OLD.org_id AND receipt.serial_id=OLD.id AND receipt.kind='receipt'
          AND public.inventory_serial_count_restoration_matches(OLD.org_id,OLD.id,
            OLD.current_missing_count_movement_id,NEW.current_stock_location_id,receipt.id)
     ) THEN
    RETURN NEW;
  END IF;

  -- A serial component leaves stock only after its valued manufacturing issue.
  IF OLD.status = 'in_stock' AND NEW.status = 'shipped'
     AND NEW.current_stock_location_id IS NULL
     AND EXISTS (
       SELECT 1 FROM public.inventory_movements movement
       JOIN public.journal_entries entry ON entry.org_id=movement.org_id AND entry.id=movement.journal_entry_id
       JOIN public.mfg_work_orders work ON work.org_id=entry.org_id AND work.number=entry.custom->>'work_order_number'
        WHERE movement.org_id=OLD.org_id AND movement.item_id=OLD.item_id AND movement.serial_id=OLD.id
          AND movement.kind='assembly_consume' AND movement.quantity=-1 AND movement.status='posted'
          AND movement.stock_location_id=OLD.current_stock_location_id
          AND entry.origin='manufacturing' AND entry.status='posted' AND entry.reverses_entry_id IS NULL
          AND movement.subsidiary_id=work.subsidiary_id AND entry.subsidiary_id=work.subsidiary_id
          AND work.status IN ('released','in_progress') AND work.bom_revision IS NOT NULL AND work.routing_version IS NOT NULL
          AND EXISTS (SELECT 1 FROM public.mfg_wo_materials material WHERE material.org_id=work.org_id AND material.work_order_id=work.id AND material.component_item_id=OLD.item_id)
          AND NOT EXISTS (SELECT 1 FROM public.inventory_movements reversal WHERE reversal.org_id=movement.org_id AND reversal.reverses_movement_id=movement.id)
     )
     AND (SELECT coalesce(sum(quantity),0) FROM public.inventory_movements WHERE org_id=OLD.org_id AND item_id=OLD.item_id AND serial_id=OLD.id AND status='posted')=0 THEN
    RETURN NEW;
  END IF;

  -- Repair returns the original serial after its exact issue and latest accepted operation inspection.
  IF OLD.status = 'shipped' AND NEW.status = 'in_stock'
     AND NEW.current_stock_location_id IS NOT NULL
     AND EXISTS (
       SELECT 1 FROM public.inventory_movements receipt
       JOIN public.journal_entries entry ON entry.org_id=receipt.org_id AND entry.id=receipt.journal_entry_id
       JOIN public.mfg_work_orders work ON work.org_id=entry.org_id AND work.number=entry.custom->>'work_order_number'
       JOIN public.inventory_inspections failed ON failed.org_id=work.org_id AND failed.id=work.receipt_rework_inspection_id
       JOIN public.inventory_movements original ON original.org_id=failed.org_id AND original.id=failed.receipt_movement_id
        WHERE receipt.org_id=OLD.org_id AND receipt.item_id=OLD.item_id AND receipt.serial_id=OLD.id
          AND receipt.kind='assembly_build' AND receipt.quantity=1 AND receipt.status='posted'
          AND receipt.stock_location_id=NEW.current_stock_location_id
          AND receipt.subsidiary_id=work.subsidiary_id AND entry.subsidiary_id=work.subsidiary_id
          AND entry.origin='manufacturing' AND entry.status='posted' AND entry.reverses_entry_id IS NULL
          AND work.produced_item_id=OLD.item_id AND work.status IN ('released','in_progress')
          AND failed.item_id=OLD.item_id AND failed.serial_id=OLD.id AND failed.quantity=1
          AND failed.status='fail' AND failed.disposition='rework' AND failed.rework_work_order_id=work.id
          AND original.item_id=OLD.item_id AND original.serial_id=OLD.id AND original.status='posted'
          AND NOT EXISTS (SELECT 1 FROM public.inventory_movements reversal WHERE reversal.org_id=original.org_id AND reversal.reverses_movement_id=original.id)
          AND NOT EXISTS (SELECT 1 FROM public.inventory_movements reversal WHERE reversal.org_id=receipt.org_id AND reversal.reverses_movement_id=receipt.id)
          AND EXISTS (
            SELECT 1 FROM public.inventory_movements issued
            JOIN public.journal_entries issue_entry ON issue_entry.org_id=issued.org_id AND issue_entry.id=issued.journal_entry_id
            JOIN public.cost_layer_consumptions consumption ON consumption.org_id=issued.org_id AND consumption.issue_movement_id=issued.id
            JOIN public.cost_layers layer ON layer.org_id=consumption.org_id AND layer.id=consumption.cost_layer_id
             WHERE issued.org_id=work.org_id AND issued.item_id=OLD.item_id AND issued.serial_id=OLD.id
               AND issued.kind='assembly_consume' AND issued.quantity=-1 AND issued.status='posted'
               AND issued.stock_location_id=failed.stock_location_id AND issued.subsidiary_id=work.subsidiary_id
               AND issue_entry.origin='manufacturing' AND issue_entry.status='posted' AND issue_entry.reverses_entry_id IS NULL
               AND issue_entry.custom->>'work_order_number'=work.number
               AND layer.source_movement_id=original.id AND consumption.quantity=1
               AND NOT EXISTS (SELECT 1 FROM public.inventory_movements reversal WHERE reversal.org_id=issued.org_id AND reversal.reverses_movement_id=issued.id)
          )
          AND EXISTS (
            SELECT 1 FROM public.mfg_wo_operations operation
            JOIN public.inventory_inspections accepted ON accepted.org_id=operation.org_id AND accepted.operation_id=operation.id
             WHERE operation.org_id=work.org_id AND operation.work_order_id=work.id AND operation.sequence=work.receipt_rework_sequence
               AND operation.status='done' AND operation.quantity_done>=1
               AND accepted.item_id=OLD.item_id AND accepted.serial_id=OLD.id AND accepted.quantity>=1 AND accepted.status='pass'
               AND NOT EXISTS (SELECT 1 FROM public.inventory_inspections newer WHERE newer.org_id=accepted.org_id AND newer.operation_id=accepted.operation_id AND newer.serial_id=OLD.id AND newer.inspection_sequence>accepted.inspection_sequence)
          )
     )
     AND (SELECT coalesce(sum(quantity),0) FROM public.inventory_movements WHERE org_id=OLD.org_id AND item_id=OLD.item_id AND serial_id=OLD.id AND status='posted')=1 THEN
    RETURN NEW;
  END IF;

  -- A posted mirror receipt reversal removes stock while preserving its reusable serial identity.
  IF OLD.status = 'in_stock' AND NEW.status = 'registered'
     AND NEW.current_stock_location_id IS NULL
     AND EXISTS (
       SELECT 1 FROM public.inventory_movements source
       JOIN public.inventory_movements reversal ON reversal.org_id=source.org_id AND reversal.reverses_movement_id=source.id
       JOIN public.journal_entries entry ON entry.org_id=source.org_id AND entry.id=source.journal_entry_id
       JOIN public.journal_entries mirror ON mirror.org_id=reversal.org_id AND mirror.id=reversal.journal_entry_id AND mirror.reverses_entry_id=entry.id
       JOIN public.mfg_work_orders work ON work.org_id=entry.org_id AND work.number=entry.custom->>'work_order_number'
        WHERE source.org_id=OLD.org_id AND source.item_id=OLD.item_id AND source.serial_id=OLD.id
          AND source.kind='assembly_build' AND source.quantity=1 AND source.status='posted'
          AND source.stock_location_id=OLD.current_stock_location_id
          AND reversal.item_id=OLD.item_id AND reversal.serial_id=OLD.id AND reversal.kind='return' AND reversal.quantity=-1 AND reversal.status='posted'
          AND reversal.stock_location_id=source.stock_location_id AND reversal.subsidiary_id=source.subsidiary_id
          AND entry.origin='manufacturing' AND entry.status='reversed' AND mirror.status='posted'
          AND mirror.book_id=entry.book_id AND mirror.subsidiary_id=entry.subsidiary_id
          AND source.subsidiary_id=work.subsidiary_id AND entry.subsidiary_id=work.subsidiary_id
     )
     AND (SELECT coalesce(sum(quantity),0) FROM public.inventory_movements WHERE org_id=OLD.org_id AND item_id=OLD.item_id AND serial_id=OLD.id AND status='posted')=0 THEN
    RETURN NEW;
  END IF;

  -- Reversing a receipt-rework completion restores the serial to its issued state.
  IF OLD.status = 'in_stock' AND NEW.status = 'shipped'
     AND NEW.current_stock_location_id IS NULL
     AND EXISTS (
       SELECT 1
         FROM public.inventory_movements receipt
         JOIN public.journal_entries completion
           ON completion.org_id = receipt.org_id
          AND completion.id = receipt.journal_entry_id
         JOIN public.mfg_work_orders work
           ON work.org_id = completion.org_id
          AND work.number = completion.custom->>'work_order_number'
         JOIN public.inventory_inspections failed
           ON failed.org_id = work.org_id
          AND failed.id = work.receipt_rework_inspection_id
         JOIN public.inventory_movements original
           ON original.org_id = failed.org_id
          AND original.id = failed.receipt_movement_id
         JOIN public.inventory_movements reversal
           ON reversal.org_id = receipt.org_id
          AND reversal.reverses_movement_id = receipt.id
         JOIN public.journal_entries reversal_entry
           ON reversal_entry.org_id = reversal.org_id
          AND reversal_entry.id = reversal.journal_entry_id
        WHERE receipt.org_id = OLD.org_id
          AND receipt.item_id = OLD.item_id
          AND receipt.serial_id = OLD.id
          AND receipt.kind = 'assembly_build'
          AND receipt.quantity = 1
          AND receipt.status = 'posted'
          AND receipt.stock_location_id = OLD.current_stock_location_id
          AND receipt.subsidiary_id = work.subsidiary_id
          AND completion.origin = 'manufacturing'
          AND completion.status = 'reversed'
          AND completion.reverses_entry_id IS NULL
          AND work.produced_item_id = OLD.item_id
          AND work.receipt_rework_inspection_id IS NOT NULL
          AND work.status IN ('released', 'in_progress', 'on_hold')
          AND failed.item_id = OLD.item_id
          AND failed.serial_id = OLD.id
          AND failed.quantity = 1
          AND failed.status = 'fail'
          AND failed.disposition = 'rework'
          AND failed.rework_work_order_id = work.id
          AND original.item_id = OLD.item_id
          AND original.serial_id = OLD.id
          AND original.status = 'posted'
          AND NOT EXISTS (
            SELECT 1 FROM public.inventory_movements original_reversal
             WHERE original_reversal.org_id = original.org_id
               AND original_reversal.reverses_movement_id = original.id
          )
          AND reversal.item_id = OLD.item_id
          AND reversal.serial_id = OLD.id
          AND reversal.kind = 'return'
          AND reversal.quantity = -1
          AND reversal.status = 'posted'
          AND reversal.stock_location_id = receipt.stock_location_id
          AND reversal.subsidiary_id = receipt.subsidiary_id
          AND reversal_entry.origin = 'manufacturing'
          AND reversal_entry.status = 'posted'
          AND reversal_entry.reverses_entry_id = completion.id
          AND EXISTS (
            SELECT 1
              FROM public.inventory_movements issued
              JOIN public.journal_entries issue_entry
                ON issue_entry.org_id = issued.org_id
               AND issue_entry.id = issued.journal_entry_id
             WHERE issued.org_id = work.org_id
               AND issued.item_id = work.produced_item_id
               AND issued.serial_id = OLD.id
               AND issued.kind = 'assembly_consume'
               AND issued.quantity = -1
               AND issued.status = 'posted'
               AND issued.stock_location_id = failed.stock_location_id
               AND issued.subsidiary_id = work.subsidiary_id
               AND issue_entry.origin = 'manufacturing'
               AND issue_entry.status = 'posted'
               AND issue_entry.reverses_entry_id IS NULL
               AND issue_entry.custom->>'work_order_number' = work.number
               AND NOT EXISTS (
                 SELECT 1 FROM public.inventory_movements issue_reversal
                  WHERE issue_reversal.org_id = issued.org_id
                    AND issue_reversal.reverses_movement_id = issued.id
               )
          )
     )
     AND (SELECT coalesce(sum(quantity), 0)
            FROM public.inventory_movements
           WHERE org_id = OLD.org_id
             AND item_id = OLD.item_id
             AND serial_id = OLD.id
             AND status = 'posted') = 0 THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'serial lifecycle transition lacks matching posted inventory evidence';
END
$$;


--
-- Name: inventory_serial_lot_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_serial_lot_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='UPDATE' AND OLD.lot_id IS NOT NULL AND NEW.lot_id IS DISTINCT FROM OLD.lot_id THEN RAISE EXCEPTION 'Serial lot identity is immutable'; END IF;
 IF NEW.lot_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.lots WHERE org_id=NEW.org_id AND id=NEW.lot_id AND item_id=NEW.item_id) THEN RAISE EXCEPTION 'Serial lot must belong to its item and tenant'; END IF;
 RETURN NEW;
END $$;


--
-- Name: item_pricing_customer_role_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.item_pricing_customer_role_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.customer_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.customer_roles role
     WHERE role.org_id = NEW.org_id AND role.party_id = NEW.customer_id AND role.is_active
  ) THEN
    RAISE EXCEPTION 'Pricing customer % is not an active customer in this organization', NEW.customer_id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: item_pricing_level_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.item_pricing_level_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.price_level_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.price_levels level
     WHERE level.org_id = NEW.org_id AND level.id = NEW.price_level_id AND level.is_active
  ) THEN
    RAISE EXCEPTION 'Pricing level % is not active in this organization', NEW.price_level_id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: je_check_adjustment_period_date(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.je_check_adjustment_period_date() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_window record;
begin
  if TG_OP = 'INSERT' and public.openbooks_clone_authority() then return new; end if;
  select * into v_window
    from public.accounting_period_posting_window(new.org_id, new.period_id);
  if not found or not v_window.is_adjustment then return new; end if;
  if new.posting_date < v_window.window_start or new.posting_date > v_window.window_end then
    raise exception 'journal entry % is dated % but names adjustment period "%" of fiscal year % (% to %): an adjustment period takes postings dated inside its own fiscal year; date the entry inside that year or post it to the period that covers %',
      new.entry_number, new.posting_date, v_window.period_name, v_window.fiscal_year,
      v_window.window_start, v_window.window_end, new.posting_date
      using errcode = '23514';
  end if;
  return new;
end $$;


--
-- Name: je_check_posted_balance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.je_check_posted_balance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ 
declare
  v_sum numeric(19,4);
  v_bad record;
  v_fx record;
begin
  if new.status <> 'posted' then return null; end if;
  select coalesce(sum(amount), 0) into v_sum
    from journal_lines
   where entry_id = new.id and org_id = new.org_id;
  if v_sum <> 0 then
    raise exception 'posted journal entry % does not balance (sum = %)', new.id, v_sum
      using errcode = '23514';
  end if;
  select subsidiary_id, sum(amount) as total into v_bad
    from journal_lines
   where entry_id = new.id and org_id = new.org_id
   group by subsidiary_id having sum(amount) <> 0 limit 1;
  if found then
    raise exception 'posted journal entry % does not balance for subsidiary % (sum = %)',
      new.id, v_bad.subsidiary_id, v_bad.total using errcode = '23514';
  end if;
  select subsidiary_id,
         sum(case when is_currency_adjustment then 0 else abs(amount - round(txn_amount * fx_rate, 4)) end) as deviation,
         count(*) as lines,
         count(*) * 0.00005 as bound into v_fx
    from journal_lines
   where entry_id = new.id and org_id = new.org_id
   group by subsidiary_id
  having sum(case when is_currency_adjustment then 0 else abs(amount - round(txn_amount * fx_rate, 4)) end) > count(*) * 0.00005 limit 1;
  -- This gate fires when an entry becomes posted: inserted posted, or a
  -- draft flipped to posted. Either way nothing has been posted yet.
  if found then
    raise exception 'posted journal entry % exceeds the per-entry FX rounding bound for subsidiary % (stored deviation % over % lines, bound %): nothing was posted; correct the line exchange rates or functional amounts so each amount is its transaction amount times its rate, then post again',
      new.id, v_fx.subsidiary_id, v_fx.deviation, v_fx.lines, v_fx.bound using errcode = '23514';
  end if;
  if (select count(*) from journal_lines where entry_id = new.id and org_id = new.org_id) < 2
     and not exists(select 1 from journal_lines l join accounts a on a.org_id=l.org_id and a.id=l.account_id where l.org_id=new.org_id and l.entry_id=new.id and a.type='statistical' and l.quantity<>0 and length(btrim(l.unit))>0) then
    raise exception 'posted journal entry % must contain at least two lines', new.id
      using errcode = '23514';
  end if;
  return null;
end  $$;


--
-- Name: je_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.je_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_module text;
  v_replay_auth uuid;
begin
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  if tg_op = 'DELETE' and public.openbooks_sandbox_wipe_allowed(old.org_id) then
    return old;
  end if;
  if tg_op = 'DELETE' then
    if old.status <> 'draft' then
      raise exception 'journal entry % is % and cannot be deleted', old.id, old.status;
    end if;
    perform period_posting_fence(old.org_id, old.period_id, old.book_id);
    if period_module_blocks_write(old.org_id, old.period_id, old.book_id,
         nullif(to_jsonb(old)->>'subsidiary_id', '')::uuid, 'gl',
         coalesce(current_setting('openbooks.migration', true), 'off') = 'on') then
      raise exception 'period is closed for GL posting';
    end if;
    return old;
  end if;

  if old.status = 'posted' and new.status = 'posted' then
    raise exception 'journal entry % is posted and immutable: corrections append a reversal through the ledger API instead of editing history', old.id;
  end if;
  if old.status = 'posted' and new.status <> 'reversed' then
    raise exception 'journal entry % is posted and can only be reversed, not set to %', old.id, new.status;
  end if;
  if old.status = 'posted' and new.status = 'reversed' then
    if to_jsonb(old) - 'status' - 'updated_at' - 'updated_by' - 'posted_at'
       is distinct from
       to_jsonb(new) - 'status' - 'updated_at' - 'updated_by' - 'posted_at' then
      raise exception 'journal entry % is posted and can only be reversed without other changes', old.id;
    end if;
    if not exists (
      select 1
        from journal_entries reversal
       where reversal.org_id = old.org_id
         and reversal.book_id = old.book_id
         and reversal.reverses_entry_id = old.id
         and reversal.status = 'posted'
         and public.openbooks_reversal_mirrors(old.org_id, old.id, reversal.id)
    ) then
      raise exception 'journal entry % cannot be reversed without a posted mirror reversal in the same book', old.id;
    end if;
    return new;
  end if;
  if old.status = 'reversed' then
    raise exception 'journal entry % is reversed and immutable', old.id;
  end if;

  if old.status = 'draft' and new.status = 'posted' then
    perform period_posting_fence(new.org_id, new.period_id, new.book_id);
    if period_module_blocks_write(new.org_id, new.period_id, new.book_id,
         nullif(to_jsonb(new)->>'subsidiary_id', '')::uuid, 'gl',
         coalesce(current_setting('openbooks.migration', true), 'off') = 'on')
       or exists (
         select 1 from journal_lines l
          where l.entry_id = new.id
            and l.org_id = new.org_id
            and period_module_blocks_write(new.org_id, new.period_id, new.book_id,
              nullif(to_jsonb(l)->>'subsidiary_id', '')::uuid, 'gl',
              coalesce(current_setting('openbooks.migration', true), 'off') = 'on')
       ) then
      begin
        v_replay_auth := nullif(current_setting('openbooks.connector_replay_authorization', true), '')::uuid;
      exception when invalid_text_representation then
        v_replay_auth := null;
      end;
      if not public.openbooks_connector_replay_authorized(new.org_id, v_replay_auth, new.period_id) then
        raise exception 'period is closed for GL posting';
      end if;
    end if;
    if new.source_document_id is not null then
      select public.document_close_module(d.kind) into v_module
        from public.documents d
       where d.id = new.source_document_id;
      if v_module is not null and v_module <> 'gl'
         and (period_module_blocks_write(new.org_id, new.period_id, new.book_id,
                nullif(to_jsonb(new)->>'subsidiary_id', '')::uuid, v_module,
                coalesce(current_setting('openbooks.migration', true), 'off') = 'on')
              or exists (
                select 1 from journal_lines l
                 where l.entry_id = new.id
                   and l.org_id = new.org_id
                   and period_module_blocks_write(new.org_id, new.period_id, new.book_id,
                     nullif(to_jsonb(l)->>'subsidiary_id', '')::uuid, v_module,
                     coalesce(current_setting('openbooks.migration', true), 'off') = 'on')
              )) then
        begin
          v_replay_auth := nullif(current_setting('openbooks.connector_replay_authorization', true), '')::uuid;
        exception when invalid_text_representation then
          v_replay_auth := null;
        end;
        if not public.openbooks_connector_replay_authorized(new.org_id, v_replay_auth, new.period_id)
           or not public.connector_historical_replay_authorized(new.org_id) then
          raise exception 'period is closed for % posting', upper(v_module);
        end if;
      end if;
    end if;
    new.posted_at := now();
  end if;
  return new;
end $$;


--
-- Name: FUNCTION je_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.je_guard() IS 'openbooks:je_guard:v7 - append-only kernel guard for journal entry mutations with the reversal-evidence branch and the soft-close-aware delete fence; amend escapes are refused by design';


--
-- Name: jl_check_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jl_check_account() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_summary boolean;
  v_active boolean;
  v_ccy text;
  v_merged_into uuid;
begin
  -- Evidence-only stamps (0236) are not postings. The line satisfied the
  -- posting rules below when it was posted; recording cleared/reconciled
  -- evidence changes no posting-relevant field, so the question is not
  -- re-opened. The column set matches jl_guard() exactly: any UPDATE that
  -- touches anything else falls through to the full checks. Whether the
  -- stamp itself is a legal append-only transition stays jl_guard's call.
  if tg_op = 'UPDATE'
     and to_jsonb(new) - 'reconciled_at' - 'reconciliation_id' - 'source_cleared_date' - 'source_cleared_connector'
       = to_jsonb(old) - 'reconciled_at' - 'reconciliation_id' - 'source_cleared_date' - 'source_cleared_connector'
  then
    return new;
  end if;
  select is_summary, is_active, currency_restriction, merged_into_id
    into v_summary, v_active, v_ccy, v_merged_into
   from accounts
   where id = new.account_id and org_id = new.org_id
     for share;
  if not found then
    raise exception 'account % does not exist in organization %', new.account_id, new.org_id
      using errcode = '23503';
  end if;
  if v_summary then
    raise exception 'account % is a summary account and cannot be posted to', new.account_id;
  end if;
  if v_merged_into is not null then
    raise exception 'account % was merged into account % — post to the surviving account instead', new.account_id, v_merged_into
      using errcode = '23514';
  end if;
  if not v_active and coalesce(current_setting('openbooks.migration', true), 'off') <> 'on' then
    raise exception 'account % is inactive — reactivate the account or map the posting to an active account instead of posting to a deactivated one', new.account_id;
  end if;
  if v_ccy is not null and new.currency <> v_ccy then
    raise exception 'account % only accepts % postings', new.account_id, v_ccy;
  end if;
  return new;
end $$;


--
-- Name: FUNCTION jl_check_account(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.jl_check_account() IS 'openbooks:jl_check_account:v6 - locks the tenant-coherent account row before validating a direct journal-line write; evidence-only stamps are not re-validated as postings; the inactive-account refusal names the remedy; a merged account refuses every posting and names its survivor';


--
-- Name: jl_check_required_dimensions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jl_check_required_dimensions() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare v_key text; v_required jsonb;
begin
  select required_dimensions into v_required from accounts
   where id = new.account_id and org_id = new.org_id;
  for v_key in select jsonb_array_elements_text(coalesce(v_required, '[]'::jsonb)) loop
    if (case v_key
      when 'subsidiary' then new.subsidiary_id is null
      when 'department' then new.department_id is null
      when 'project' then new.project_id is null
      when 'location' then new.location_id is null
      when 'class' then new.class_id is null
      when 'party' then new.party_id is null
      else nullif(coalesce(new.extra_dims, '{}'::jsonb)->>v_key, '') is null
    end) then
      raise exception 'account % requires segment %', new.account_id, v_key using errcode = '23514';
    end if;
  end loop;
  return new;
end $$;


--
-- Name: jl_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jl_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_status text;
  v_org uuid;
  v_period uuid;
  v_book uuid;
  v_old_status text;
  v_old_org uuid;
  v_old_period uuid;
  v_old_book uuid;
  v_line_org uuid;
  v_entry uuid;
  v_recon_same boolean;
  v_recon_statement_stamp boolean;
  v_recon_source_stamp boolean;
  v_source_same boolean;
  v_source_stamp boolean;
  v_recon_withdrawal boolean;
begin
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  if tg_op = 'DELETE' and openbooks_sandbox_wipe_allowed(old.org_id) then
    return old;
  end if;
  -- Tenant coherence (restored from 0038 in 0159): a line may only ever
  -- reference a journal entry of its OWN organization. On UPDATE the
  -- ORIGINAL parent is resolved too: the destination alone cannot vouch for
  -- the history the line leaves behind. A miss raises the foreign-key class
  -- error the ledger guards and the kernel-constraints canary rely on.
  if tg_op = 'DELETE' then
    v_line_org := old.org_id;
    v_entry := old.entry_id;
  else
    v_line_org := new.org_id;
    v_entry := new.entry_id;
  end if;
  select status, org_id, period_id, book_id
    into v_status, v_org, v_period, v_book
    from journal_entries
   where id = v_entry and org_id = v_line_org;
  if not found then
    raise exception 'journal entry % does not exist in organization %', v_entry, v_line_org
      using errcode = '23503';
  end if;
  if tg_op = 'UPDATE' then
    select status, org_id, period_id, book_id
      into v_old_status, v_old_org, v_old_period, v_old_book
      from journal_entries
     where id = old.entry_id and org_id = old.org_id;
    if not found then
      raise exception 'journal entry % does not exist in organization %', old.entry_id, old.org_id
        using errcode = '23503';
    end if;
    -- Original-parent immutability (0165, hardened in 0380): a line that
    -- leaves posted or reversed history for a different entry or
    -- organization is refused, with no session-flag escape. Evidence-only
    -- stamps never move lines, so any such move is a history rewrite.
    if v_old_status is distinct from 'draft'
       and (new.entry_id is distinct from old.entry_id
            or new.org_id is distinct from old.org_id) then
      raise exception 'lines of a % journal entry are immutable', v_old_status;
    end if;
  end if;
  if v_status is distinct from 'draft' then
    -- Branch: clone-authority-insert (0316, restored in 0400). The
    -- deterministic clone replays posted history verbatim into target
    -- periods that may already be closed there; the immutability raise
    -- below would refuse the copy even though the history was valid where
    -- it was written. Under the clone authority an INSERT carries that
    -- history across, still subject to the tenant-coherent parent lookup
    -- above and to every balance and account guard. UPDATE and DELETE fall
    -- through and stay blocked exactly as before. This needs no amend
    -- escape: the authority is the conjunction of four GUCs only the clone
    -- transaction holds.
    if tg_op = 'INSERT' and public.openbooks_clone_authority() then
      return new;
    end if;
    -- Bank-reconciliation sign-off stamps reconciled_at / reconciliation_id
    -- on posted lines. That is bookkeeping metadata, but it is still
    -- financial-control evidence: it may transition from entirely unset to an
    -- extant unsigned reconciliation that already claims the line, and clear
    -- only through the governed sign-off withdrawal below. Retargeting or
    -- partially stamping the evidence is forbidden.
    -- Source-cleared evidence (0158) follows the same append-only rule: the
    -- mirror records the source system's cleared marker once, and a
    -- source-evidenced sign-off stamps only lines already carrying it.
    if tg_op = 'UPDATE'
       and to_jsonb(new) - 'reconciled_at' - 'reconciliation_id' - 'source_cleared_date' - 'source_cleared_connector'
         = to_jsonb(old) - 'reconciled_at' - 'reconciliation_id' - 'source_cleared_date' - 'source_cleared_connector'
    then
      v_recon_same := new.reconciled_at is not distinct from old.reconciled_at
        and new.reconciliation_id is not distinct from old.reconciliation_id;
      v_source_same := new.source_cleared_date is not distinct from old.source_cleared_date
        and new.source_cleared_connector is not distinct from old.source_cleared_connector;
      if v_recon_same and v_source_same then
        return new;
      end if;
      v_recon_statement_stamp :=
        old.reconciled_at is null
        and old.reconciliation_id is null
        and new.reconciled_at is not null
        and new.reconciliation_id is not null
        and exists (
          select 1
            from reconciliations r
           where r.id = new.reconciliation_id
             and r.org_id = new.org_id
             and r.status <> 'signed_off'
        )
        and exists (
          select 1
            from reconciliation_matches m
           where m.reconciliation_id = new.reconciliation_id
             and m.journal_line_id = new.id
             and m.org_id = new.org_id
        );
      v_recon_source_stamp :=
        old.reconciled_at is null
        and old.reconciliation_id is null
        and new.reconciled_at is not null
        and new.reconciliation_id is not null
        and new.source_cleared_date is not null
        and exists (
          select 1
            from reconciliations r
           where r.id = new.reconciliation_id
             and r.org_id = new.org_id
             and r.status <> 'signed_off'
             and r.evidence_kind = 'source'
        );
      v_source_stamp :=
        old.source_cleared_date is null
        and old.source_cleared_connector is null
        and new.source_cleared_date is not null
        and new.source_cleared_connector is not null
        and length(btrim(new.source_cleared_connector)) > 0;
      -- Governed sign-off withdrawal (0669): the engine has already returned
      -- the reconciliation to an unsigned state under the account lock and
      -- names it in a transaction-scoped marker. Only that reconciliation's
      -- stamp may clear, wholly, and the audit row lands in the same
      -- transaction.
      v_recon_withdrawal :=
        old.reconciled_at is not null
        and old.reconciliation_id is not null
        and new.reconciled_at is null
        and new.reconciliation_id is null
        and current_setting('app.reconciliation_withdrawal', true) = old.reconciliation_id::text
        and exists (
          select 1
            from reconciliations r
           where r.id = old.reconciliation_id
             and r.org_id = old.org_id
             and r.status <> 'signed_off'
        );
      if (v_recon_same or v_recon_statement_stamp or v_recon_source_stamp or v_recon_withdrawal)
         and (v_source_same or v_source_stamp) then
        return new;
      end if;
      raise exception 'journal-line reconciliation evidence is append-only';
    end if;
    -- Party-attribution moves (0380): the governed party-merge path
    -- re-points an absorbed party on posted lines. That changes NO amount,
    -- account, subsidiary, currency, or memo — party_id is the only column
    -- that may differ — and the move is refused when the period is closed
    -- for GL posting. There is no session-flag escape.
    if tg_op = 'UPDATE'
       and to_jsonb(new) - 'party_id' = to_jsonb(old) - 'party_id'
       and new.party_id is distinct from old.party_id
    then
      if period_module_blocks_write(v_org, v_period, v_book,
           nullif(to_jsonb(new)->>'subsidiary_id', '')::uuid, 'gl',
           coalesce(current_setting('openbooks.migration', true), 'off') = 'on') then
        raise exception 'period is closed for GL posting';
      end if;
      return new;
    end if;
    -- Append-only (0380): the amend re-materialization branch is gone. A
    -- posted or reversed line admits clone replay, reconciliation-evidence
    -- stamps and party-attribution moves above; everything else is immutable.
    raise exception 'lines of a % journal entry are immutable', v_status;
  end if;
  return coalesce(new, old);
end $$;


--
-- Name: jl_stamp_balancing_defaults(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jl_stamp_balancing_defaults() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_segment record;
begin
  for v_segment in
    select key, default_value_id
      from public.segment_definitions
     where org_id = new.org_id and source_kind = 'custom'
       and is_balancing and default_value_id is not null
     order by key
  loop
    if not (coalesce(new.extra_dims, '{}'::jsonb) ? v_segment.key) then
      new.extra_dims := jsonb_set(
        coalesce(new.extra_dims, '{}'::jsonb),
        array[v_segment.key],
        to_jsonb(v_segment.default_value_id::text),
        true
      );
    end if;
  end loop;
  return new;
end $$;


--
-- Name: journal_entity_period_post_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_entity_period_post_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE leg record; source_module text;
BEGIN
 IF NEW.status<>'posted' OR OLD.status='posted' THEN RETURN NEW; END IF;
 SELECT public.document_close_module(kind) INTO source_module FROM documents WHERE org_id=NEW.org_id AND id=NEW.source_document_id;
 FOR leg IN SELECT DISTINCT subsidiary_id,coalesce(period_id,NEW.period_id) as period_id FROM journal_lines WHERE org_id=NEW.org_id AND entry_id=NEW.id LOOP
  PERFORM period_posting_fence(NEW.org_id,leg.period_id,NEW.book_id);
  IF period_module_blocks_write(NEW.org_id,leg.period_id,NEW.book_id,leg.subsidiary_id,'gl',public.connector_historical_replay_authorized(NEW.org_id))
   OR (source_module IS NOT NULL AND source_module<>'gl' AND period_module_blocks_write(NEW.org_id,leg.period_id,NEW.book_id,leg.subsidiary_id,source_module,public.connector_historical_replay_authorized(NEW.org_id))) THEN
   RAISE EXCEPTION 'The entity accounting period is closed for this posting module.' USING ERRCODE='23514'; END IF;
 END LOOP;
 RETURN NEW;
END $$;


--
-- Name: journal_generic_segment_balance_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_generic_segment_balance_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE bad record;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM journal_entries WHERE org_id=NEW.org_id AND id=NEW.id AND status IN('posted','reversed')) THEN RETURN NULL; END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('openbooks:ledger-setup:'||NEW.org_id,0));
 SELECT d.key,l.subsidiary_id,sum(l.amount) AS total INTO bad FROM journal_lines l
 JOIN segment_definitions d ON d.org_id=l.org_id AND d.is_active AND d.is_balancing
 WHERE l.org_id=NEW.org_id AND l.entry_id=NEW.id
 GROUP BY d.key,l.subsidiary_id,CASE d.storage_column WHEN 'subsidiary_id' THEN l.subsidiary_id::text
  WHEN 'department_id' THEN l.department_id::text WHEN 'project_id' THEN l.project_id::text
  WHEN 'location_id' THEN l.location_id::text WHEN 'class_id' THEN l.class_id::text ELSE l.extra_dims->>d.key END
 HAVING sum(l.amount)<>0 LIMIT 1;
 IF FOUND THEN RAISE EXCEPTION 'The journal must balance per entity and value of balancing segment %.',bad.key USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $$;


--
-- Name: journal_instruction_financial_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_instruction_financial_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF OLD.status<>'draft' AND (NEW.journal_mode IS DISTINCT FROM OLD.journal_mode OR NEW.journal_reverse_on IS DISTINCT FROM OLD.journal_reverse_on
   OR NEW.journal_fx_rate_explicit IS DISTINCT FROM OLD.journal_fx_rate_explicit) THEN
  RAISE EXCEPTION 'Approved journal mode, stated-rate intent and reversal date are immutable. Withdraw a pending submission or create a separate correcting journal.' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: journal_instruction_line_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_instruction_line_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
<<instruction_line>>
DECLARE head journal_entries%ROWTYPE; chosen_calendar uuid; chosen_period uuid; v_book_currency text; reversal_line journal_lines%ROWTYPE;
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN
  IF public.financial_history_native_clone_matches(TG_RELID,to_jsonb(NEW)) THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'Financial history clone admission requires the exact registered source row, seed and destination parents.' USING ERRCODE='23514';
 END IF;
 SELECT * INTO STRICT head FROM journal_entries WHERE org_id=NEW.org_id AND id=NEW.entry_id;
 IF public.connector_historical_replay_authorized(NEW.org_id) THEN
  NEW.period_id:=head.period_id;
 ELSE
 chosen_calendar:=public.subsidiary_posting_calendar(NEW.org_id,NEW.subsidiary_id,head.posting_date);
 SELECT id INTO chosen_period FROM accounting_periods WHERE org_id=NEW.org_id AND id=head.period_id AND fiscal_calendar_id=chosen_calendar;
 IF chosen_period IS NULL THEN SELECT id INTO chosen_period FROM accounting_periods WHERE org_id=NEW.org_id AND fiscal_calendar_id=chosen_calendar
  AND NOT is_adjustment AND starts_on<=head.posting_date AND ends_on>=head.posting_date ORDER BY starts_on,ends_on,id LIMIT 1; END IF;
 IF chosen_period IS NULL THEN RAISE EXCEPTION 'Generate the entity accounting period covering this posting date.' USING ERRCODE='23514'; END IF;
 IF NEW.period_id IS NOT NULL AND NEW.period_id<>chosen_period THEN RAISE EXCEPTION 'A journal line must use its entity accounting period.' USING ERRCODE='23514'; END IF;
 NEW.period_id:=chosen_period;
 END IF;
 IF EXISTS(SELECT 1 FROM accounts WHERE org_id=NEW.org_id AND id=NEW.account_id AND type='statistical') THEN
  IF NEW.amount<>0 OR NEW.txn_amount<>0 OR NEW.quantity IS NULL OR NEW.quantity=0 OR coalesce(length(btrim(NEW.unit)),0)=0 OR NEW.is_open_item OR NEW.is_currency_adjustment THEN
   RAISE EXCEPTION 'Statistical accounts carry nonzero quantities with a unit and zero money.' USING ERRCODE='23514'; END IF;
 END IF;
 IF NEW.is_currency_adjustment THEN
  IF NEW.txn_amount<>0 OR NEW.amount=0 OR NEW.is_open_item OR head.origin<>'currency_adjustment' THEN
   RAISE EXCEPTION 'Typed currency adjustments carry only a base amount and zero foreign transaction value.' USING ERRCODE='23514'; END IF;
  IF head.reverses_entry_id IS NOT NULL THEN
   SELECT * INTO reversal_line FROM journal_lines WHERE org_id=NEW.org_id AND entry_id=head.reverses_entry_id AND line_number=NEW.line_number;
   IF NOT FOUND OR NOT reversal_line.is_currency_adjustment OR reversal_line.account_id<>NEW.account_id OR reversal_line.subsidiary_id<>NEW.subsidiary_id OR reversal_line.amount<>-NEW.amount OR reversal_line.currency<>NEW.currency OR reversal_line.fx_rate<>NEW.fx_rate OR reversal_line.txn_amount<>-NEW.txn_amount THEN
    RAISE EXCEPTION 'A currency adjustment reversal must mirror its original recorded line.' USING ERRCODE='23514'; END IF;
  ELSIF NOT EXISTS(SELECT 1 FROM documents WHERE org_id=NEW.org_id AND id=head.source_document_id AND kind='journal' AND journal_mode='currency_adjustment') THEN
   RAISE EXCEPTION 'A currency adjustment requires its native governed journal instruction.' USING ERRCODE='23514';
  END IF;
  IF head.reverses_entry_id IS NULL THEN
   PERFORM pg_advisory_xact_lock(hashtextextended('openbooks:ledger-setup:' || NEW.org_id::text,0));
   v_book_currency:=public.accounting_book_currency(NEW.org_id,head.book_id,NEW.subsidiary_id);
   IF NEW.currency=instruction_line.v_book_currency OR NOT EXISTS(SELECT 1 FROM journal_lines f JOIN journal_entries e ON e.org_id=f.org_id AND e.id=f.entry_id
      WHERE f.org_id=NEW.org_id AND e.book_id=head.book_id AND e.status IN('posted','reversed') AND e.posting_date<=head.posting_date
      AND f.subsidiary_id=NEW.subsidiary_id AND f.account_id=NEW.account_id AND f.currency=NEW.currency) OR EXISTS(SELECT 1 FROM journal_lines f JOIN journal_entries e ON e.org_id=f.org_id AND e.id=f.entry_id
    WHERE f.org_id=NEW.org_id AND e.book_id=head.book_id AND e.status IN('posted','reversed') AND e.posting_date<=head.posting_date
      AND f.subsidiary_id=NEW.subsidiary_id AND f.account_id=NEW.account_id AND f.currency<>instruction_line.v_book_currency
    GROUP BY f.currency HAVING sum(f.txn_amount)<>0) OR
    NEW.amount<>-(SELECT coalesce(sum(f.amount),0) FROM journal_lines f JOIN journal_entries e ON e.org_id=f.org_id AND e.id=f.entry_id
      WHERE f.org_id=NEW.org_id AND e.book_id=head.book_id AND e.status IN('posted','reversed') AND e.posting_date<=head.posting_date
      AND f.subsidiary_id=NEW.subsidiary_id AND f.account_id=NEW.account_id) THEN
    RAISE EXCEPTION 'A currency adjustment clears the exact book residual only after every foreign currency balance is zero.' USING ERRCODE='23514';
   END IF;
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: journal_line_measurement_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_line_measurement_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE account_type text;
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN
  IF public.financial_history_native_clone_matches(TG_RELID,to_jsonb(NEW)) THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'Financial history clone admission requires the exact registered source row, seed and destination parents.' USING ERRCODE='23514';
 END IF;
 SELECT a.type INTO account_type FROM accounts a WHERE a.org_id=NEW.org_id AND a.id=NEW.account_id;
 IF NOT FOUND THEN
  RAISE EXCEPTION 'Choose a posting account owned by the journal organization.' USING ERRCODE='23514';
 END IF;
 IF account_type='statistical' THEN
  IF NEW.amount<>0 OR NEW.txn_amount<>0 OR NEW.quantity IS NULL OR NEW.quantity=0 OR NEW.quantity<>trunc(NEW.quantity,4) OR
    coalesce(length(btrim(NEW.unit)),0)=0 OR NEW.is_open_item OR NEW.is_currency_adjustment THEN
   RAISE EXCEPTION 'Statistical accounts carry nonzero quantities with a unit and zero money.' USING ERRCODE='23514';
  END IF;
 ELSIF NEW.amount=0 THEN
  RAISE EXCEPTION 'Zero-money journal lines require a statistical account with a nonzero quantity and unit.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: journal_lines_check_balanced_entries(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_lines_check_balanced_entries(p_entry_ids uuid[]) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_bad_entry uuid;
  v_bad_subsidiary uuid;
  v_bad_total numeric(19,4);
  v_whole_entry integer;
  v_bad_segment text;
  v_bad_value text;
BEGIN
  IF coalesce(cardinality(p_entry_ids),0)=0 THEN
    RETURN;
  END IF;

  -- GROUPING distinguishes the whole-entry subtotal from a subsidiary group,
  -- including any retained NULL subsidiary. Whole-entry refusals take priority
  -- across the complete set, just as when the two checks ran separately.
  SELECT e.id,l.subsidiary_id,sum(l.amount),grouping(l.subsidiary_id)
    INTO v_bad_entry,v_bad_subsidiary,v_bad_total,v_whole_entry
    FROM public.journal_entries e
    JOIN public.journal_lines l ON l.entry_id=e.id AND l.org_id=e.org_id
   WHERE e.id=ANY(p_entry_ids) AND e.status IS DISTINCT FROM 'draft'
   GROUP BY GROUPING SETS ((e.id),(e.id,l.subsidiary_id))
  HAVING sum(l.amount)<>0
   ORDER BY grouping(l.subsidiary_id) DESC,e.id,l.subsidiary_id
   LIMIT 1;
  IF FOUND THEN
    IF v_whole_entry=1 THEN
      RAISE EXCEPTION 'journal entry % does not balance (sum = %)',v_bad_entry,v_bad_total
        USING ERRCODE='23514';
    ELSE
      RAISE EXCEPTION 'journal entry % does not balance for subsidiary % (sum = %)',
        v_bad_entry,v_bad_subsidiary,v_bad_total USING ERRCODE='23514';
    END IF;
  END IF;

  -- Avoid another journal-line scan when none of these headers belongs to an
  -- organization with a configured custom balancing segment. A segment in a
  -- different organization cannot enable or satisfy this check.
  IF EXISTS (
    SELECT 1 FROM public.segment_definitions sd
    JOIN public.journal_entries e ON e.org_id=sd.org_id
    WHERE sd.source_kind='custom' AND sd.is_balancing
      AND e.id=ANY(p_entry_ids) AND e.status IS DISTINCT FROM 'draft'
  ) THEN
    SELECT e.id,sd.key,l.extra_dims->>sd.key,sum(l.amount)
      INTO v_bad_entry,v_bad_segment,v_bad_value,v_bad_total
      FROM public.journal_entries e
      JOIN public.journal_lines l ON l.entry_id=e.id AND l.org_id=e.org_id
      JOIN public.segment_definitions sd ON sd.org_id=e.org_id
        AND sd.source_kind='custom' AND sd.is_balancing
     WHERE e.id=ANY(p_entry_ids) AND e.status IS DISTINCT FROM 'draft'
     GROUP BY e.id,sd.key,l.extra_dims->>sd.key
    HAVING sum(l.amount)<>0
     ORDER BY e.id,sd.key,l.extra_dims->>sd.key
     LIMIT 1;
    IF FOUND THEN
      RAISE EXCEPTION 'journal entry % does not balance for segment % value % (sum = %)',
        v_bad_entry,v_bad_segment,coalesce(v_bad_value,'<missing>'),v_bad_total
        USING ERRCODE='23514';
    END IF;
  END IF;
END $$;


--
-- Name: journal_lines_check_balanced_stmt_del(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_lines_check_balanced_stmt_del() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  perform public.journal_lines_check_balanced_entries(
    array(select distinct entry_id from old_lines));
  return null;
end $$;


--
-- Name: journal_lines_check_balanced_stmt_ins(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_lines_check_balanced_stmt_ins() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  perform public.journal_lines_check_balanced_entries(
    array(select distinct entry_id from new_lines));
  return null;
end $$;


--
-- Name: journal_lines_check_balanced_stmt_upd(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_lines_check_balanced_stmt_upd() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  perform public.journal_lines_check_balanced_entries(
    array(select distinct entry_id from new_lines
          union
          select distinct entry_id from old_lines));
  return null;
end $$;


--
-- Name: journal_lines_check_fx_residual_entries(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_lines_check_fx_residual_entries(p_entry_ids uuid[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
begin
  perform public.journal_lines_check_fx_residual_entries(p_entry_ids, false);
end $$;


--
-- Name: journal_lines_check_fx_residual_entries(uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_lines_check_fx_residual_entries(p_entry_ids uuid[], p_new_posting boolean) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
  v_bad_org uuid;
  v_bad_entry uuid;
  v_bad_subsidiary uuid;
  v_bad_deviation numeric(19, 4);
  v_bad_lines integer;
  v_bad_bound numeric;
begin
  -- Membership bounds the ledger lookup before aggregation. Multiplicity
  -- retains the original result even when a caller repeats an entry ID.
  -- Drafts continue to post through the entry-level balance gate.
  with entry_counts as materialized (
    select entry_id,count(*) as repetitions
      from unnest(p_entry_ids) as touched(entry_id)
     group by entry_id
  )
  select l.org_id, l.entry_id, l.subsidiary_id,
         sum((case when l.is_currency_adjustment then 0 else abs(l.amount - round(l.txn_amount * l.fx_rate, 4)) end) * touched.repetitions),
         sum(touched.repetitions),sum(touched.repetitions) * 0.00005
    into v_bad_org, v_bad_entry, v_bad_subsidiary, v_bad_deviation, v_bad_lines, v_bad_bound
    from public.journal_entries e
    join public.journal_lines l on l.entry_id=e.id
    join entry_counts touched on touched.entry_id=e.id
   where e.id=any(p_entry_ids) and e.status is distinct from 'draft'
   group by l.org_id, l.entry_id, l.subsidiary_id
  having sum((case when l.is_currency_adjustment then 0 else abs(l.amount - round(l.txn_amount * l.fx_rate, 4)) end) * touched.repetitions) > sum(touched.repetitions) * 0.00005
   limit 1;
  if found and p_new_posting then
    raise exception 'journal entry % in organization % exceeds the per-entry FX rounding bound for subsidiary % (stored deviation % over % lines, bound %): nothing was posted; correct the line exchange rates or functional amounts so each amount is its transaction amount times its rate, then post again',
      v_bad_entry, v_bad_org, v_bad_subsidiary, v_bad_deviation, v_bad_lines, v_bad_bound
      using errcode = '23514';
  elsif found then
    raise exception 'journal entry % in organization % exceeds the per-entry FX rounding bound for subsidiary % (stored deviation % over % lines, bound %): posted lines cannot be amended; correct through the ledger API by posting a reversal and reposting instead of editing history',
      v_bad_entry, v_bad_org, v_bad_subsidiary, v_bad_deviation, v_bad_lines, v_bad_bound
      using errcode = '23514';
  end if;
end $$;


--
-- Name: journal_lines_check_fx_residual_stmt_del(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_lines_check_fx_residual_stmt_del() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  perform public.journal_lines_check_fx_residual_entries(
    array(select distinct entry_id from old_lines));
  return null;
end $$;


--
-- Name: journal_lines_check_fx_residual_stmt_ins(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_lines_check_fx_residual_stmt_ins() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  perform public.journal_lines_check_fx_residual_entries(
    array(select n.entry_id from new_lines n group by n.entry_id
           having count(*) = (select count(*) from public.journal_lines l where l.entry_id = n.entry_id)),
    true);
  perform public.journal_lines_check_fx_residual_entries(
    array(select n.entry_id from new_lines n group by n.entry_id
           having count(*) <> (select count(*) from public.journal_lines l where l.entry_id = n.entry_id)),
    false);
  return null;
end $$;


--
-- Name: journal_lines_check_fx_residual_stmt_upd(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_lines_check_fx_residual_stmt_upd() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  perform public.journal_lines_check_fx_residual_entries(
    array(select distinct entry_id from new_lines
          union
          select distinct entry_id from old_lines));
  return null;
end $$;


--
-- Name: journal_lines_lock_nonprofit_framework(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_lines_lock_nonprofit_framework() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if coalesce(new.extra_dims, '{}'::jsonb) ? 'fund' then
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended('openbooks:nonprofit-framework:' || new.org_id::text, 0)
    );
  end if;
  return new;
end $$;


--
-- Name: journal_primary_book_history_fence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_primary_book_history_fence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  primary_ids uuid[];
BEGIN
  IF coalesce(current_setting('openbooks.migration', true), 'off') = 'on' THEN
    RETURN new;
  END IF;
  SELECT array_agg(id) INTO primary_ids FROM (
    SELECT id FROM public.accounting_books WHERE org_id = new.org_id AND is_primary
      ORDER BY id FOR SHARE
  ) authority;
  -- A concurrent empty-org promotion can demote the row seen by the first
  -- statement while its lock waits. Take a fresh READ COMMITTED snapshot to
  -- resolve the successor, instead of proceeding without an authority fence.
  IF coalesce(cardinality(primary_ids), 0) = 0 THEN
    SELECT array_agg(id) INTO primary_ids FROM (
      SELECT id FROM public.accounting_books WHERE org_id = new.org_id AND is_primary
        ORDER BY id FOR SHARE
    ) authority;
  END IF;
  IF coalesce(cardinality(primary_ids), 0) <> 1 THEN
    RAISE EXCEPTION 'accounting history creation requires exactly one primary accounting book'
      USING ERRCODE = '23514';
  END IF;
  RETURN new;
END;
$$;


--
-- Name: FUNCTION journal_primary_book_history_fence(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.journal_primary_book_history_fence() IS 'openbooks:journal_primary_book_history_fence:v1 - first journal creation retains the primary book row through commit, serializing SQL and secondary-book history with book reassignment';


--
-- Name: journal_reversal_instruction_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_reversal_instruction_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN
  IF tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD)) OR public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'Scheduled reversal instructions are retained history.' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' AND ((to_jsonb(NEW)-ARRAY['status','reversal_entry_id','last_error','updated_at','updated_by']) IS DISTINCT FROM
    (to_jsonb(OLD)-ARRAY['status','reversal_entry_id','last_error','updated_at','updated_by']) OR OLD.status IN('completed','cancelled')) THEN
  RAISE EXCEPTION 'An approved reversal instruction retains its source, actor and date; only its execution state can advance.' USING ERRCODE='23514'; END IF;
 IF NEW.status='completed' AND NOT EXISTS(SELECT 1 FROM journal_entries WHERE org_id=NEW.org_id AND id=NEW.reversal_entry_id
   AND status='posted' AND reverses_entry_id=NEW.source_entry_id AND posting_date=NEW.reverse_on) THEN
  RAISE EXCEPTION 'Completion identifies the exact posted reversal of the approved instruction.' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT 1 FROM documents d JOIN journal_entries e ON e.org_id=d.org_id AND e.source_document_id=d.id
  WHERE d.org_id=NEW.org_id AND d.id=NEW.document_id AND e.id=NEW.source_entry_id AND d.kind='journal' AND d.journal_reverse_on=NEW.reverse_on AND NEW.reverse_on>e.posting_date) THEN
  RAISE EXCEPTION 'A scheduled reversal must match its posted journal instruction.' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: landed_cost_allocation_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.landed_cost_allocation_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
    RAISE EXCEPTION 'landed-cost allocation evidence is append-only';
  END IF;
  IF OLD.journal_entry_id IS NULL
     AND NEW.journal_entry_id IS NOT NULL
     AND (to_jsonb(NEW) - 'journal_entry_id' - 'updated_at' - 'updated_by')
       = (to_jsonb(OLD) - 'journal_entry_id' - 'updated_at' - 'updated_by') THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'landed-cost allocation evidence is immutable';
END
$$;


--
-- Name: landed_cost_voucher_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.landed_cost_voucher_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF OLD.status = 'draft'
       OR openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'posted landed-cost vouchers cannot be deleted';
  END IF;
  IF OLD.status = 'draft' THEN RETURN NEW; END IF;
  IF OLD.status = 'posted'
     AND NEW.status = 'void'
     AND NEW.org_id = OLD.org_id
     AND NEW.document_number = OLD.document_number
     AND NEW.amount = OLD.amount
     AND NEW.basis = OLD.basis
     AND NEW.freight_account_id = OLD.freight_account_id
     AND NEW.source_document_line_id IS NOT DISTINCT FROM OLD.source_document_line_id
     AND NEW.subsidiary_id = OLD.subsidiary_id
     AND NEW.voucher_date = OLD.voucher_date
     AND NEW.journal_entry_id = OLD.journal_entry_id
     AND NEW.memo IS NOT DISTINCT FROM OLD.memo
     AND NEW.created_at = OLD.created_at
     AND NEW.created_by IS NOT DISTINCT FROM OLD.created_by
     AND NEW.reversal_journal_entry_id IS NOT NULL
     AND NEW.voided_at IS NOT NULL
     AND NEW.voided_by IS NOT NULL
     AND length(btrim(NEW.void_reason)) BETWEEN 5 AND 500 THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'posted and void landed-cost vouchers are immutable';
END
$$;


--
-- Name: landed_cost_voucher_target_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.landed_cost_voucher_target_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  parent_status text;
  parent_org uuid;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  SELECT status, org_id
    INTO parent_status, parent_org
    FROM landed_cost_vouchers
   WHERE id = coalesce(NEW.voucher_id, OLD.voucher_id);
  IF TG_OP = 'DELETE' AND parent_status IS NULL THEN RETURN OLD; END IF;
  IF parent_status IS NULL
     OR parent_org IS DISTINCT FROM coalesce(NEW.org_id, OLD.org_id) THEN
    RAISE EXCEPTION 'landed-cost target must reference a tenant-owned voucher';
  END IF;
  IF parent_status <> 'draft' THEN
    IF TG_OP = 'DELETE'
       AND openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'targets of a posted landed-cost voucher are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END
$$;


--
-- Name: layer_consumption_fill_subsidiary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.layer_consumption_fill_subsidiary() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  owner uuid;
BEGIN
  IF NEW.subsidiary_id IS NOT NULL THEN
    RETURN NEW;
  END IF;
  SELECT m.subsidiary_id INTO owner
    FROM public.inventory_movements m
   WHERE m.id = NEW.issue_movement_id
     AND m.org_id = NEW.org_id;
  IF owner IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = 'check_violation',
      MESSAGE = 'cost layer consumption requires the legal entity of its issue movement',
      DETAIL = 'The issue movement was not found, so ownership could not be derived.',
      HINT = 'Create the issue movement before recording its consumptions.';
  END IF;
  NEW.subsidiary_id := owner;
  RETURN NEW;
END;
$$;


--
-- Name: lease_agreement_revision_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_agreement_revision_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP='DELETE' THEN
    IF OLD.status<>'draft' THEN RAISE EXCEPTION 'commenced lease agreements are retained; use a termination or correcting change'; END IF;
    RETURN OLD;
  END IF;
  IF OLD.org_id<>NEW.org_id OR OLD.subsidiary_id<>NEW.subsidiary_id OR OLD.id<>NEW.id THEN
    RAISE EXCEPTION 'lease organization and legal entity are immutable';
  END IF;
  IF OLD.status='draft' THEN RETURN NEW; END IF;
  IF (to_jsonb(NEW)-ARRAY['description','custom','updated_at','updated_by']) IS NOT DISTINCT FROM
     (to_jsonb(OLD)-ARRAY['description','custom','updated_at','updated_by']) THEN RETURN NEW; END IF;
  IF NEW.revision<>OLD.revision+1 OR NEW.last_change_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM financial_changes c WHERE c.id=NEW.last_change_id AND c.org_id=NEW.org_id
      AND c.domain='lease' AND c.subject_id=NEW.id AND c.status='approved') THEN
    RAISE EXCEPTION 'changing a commenced lease requires an approved accounting change and a new revision';
  END IF;
  IF NEW.initial_liability IS DISTINCT FROM OLD.initial_liability OR NEW.initial_rou_asset IS DISTINCT FROM OLD.initial_rou_asset
     OR NEW.commencement_entry_id IS DISTINCT FROM OLD.commencement_entry_id OR NEW.commencement_on<>OLD.commencement_on
     OR NEW.book_id IS DISTINCT FROM OLD.book_id OR NEW.currency IS DISTINCT FROM OLD.currency THEN
    RAISE EXCEPTION 'lease commencement history is immutable';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: lease_charges_base_rent_repair(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_charges_base_rent_repair() RETURNS TABLE(windows_closed integer, shadows_deleted integer, lines_cancelled integer)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_conflict record;
  v_older_billed integer;
  v_newer_billed integer;
  v_windows_closed integer := 0;
  v_shadows_deleted integer := 0;
  v_lines_cancelled integer := 0;
BEGIN
  -- Resolve one chronologically-first conflict per pass so every decision
  -- sees the state the previous one produced (0051 ownership-repair pattern).
  LOOP
    SELECT first_charge.id AS older_id, second_charge.id AS newer_id,
           second_charge.effective_from AS newer_from,
           second_charge.effective_from > first_charge.effective_from AS distinct_start
      INTO v_conflict
      FROM public.lease_charges first_charge
      JOIN public.lease_charges second_charge
        ON second_charge.org_id = first_charge.org_id
       AND second_charge.lease_id = first_charge.lease_id
       AND second_charge.charge_type = 'base_rent'
       AND (second_charge.effective_from, second_charge.id) > (first_charge.effective_from, first_charge.id)
     WHERE first_charge.charge_type = 'base_rent'
       AND coalesce(first_charge.effective_to, 'infinity'::date) >= second_charge.effective_from
     ORDER BY first_charge.lease_id, second_charge.effective_from, second_charge.id, first_charge.id
     LIMIT 1;
    EXIT WHEN NOT FOUND;

    IF v_conflict.distinct_start THEN
      -- Distinct starts: the successor supersedes.  Close the older window the
      -- day before the successor begins — exactly what applying an escalation
      -- already does to the canon.
      UPDATE public.lease_charges
         SET effective_to = v_conflict.newer_from - 1, updated_at = now()
       WHERE id = v_conflict.older_id;
      v_windows_closed := v_windows_closed + 1;

      -- Retire the older row's unbilled future coverage that no longer has a
      -- contractual window, keeping every invoiced line as history.
      WITH cancelled AS (
        UPDATE public.lease_schedule_lines s
           SET status = 'cancelled', updated_at = now()
          FROM public.lease_charges c
         WHERE c.id = v_conflict.older_id
           AND s.org_id = c.org_id
           AND s.charge_id = c.id
           AND s.status = 'scheduled'
           AND s.period_starts_on >= v_conflict.newer_from
        RETURNING s.id
      )
      -- This is the corrective behavior: each conflict contributes to the
      -- running total instead of replacing the prior pass's count.
      SELECT v_lines_cancelled + count(*) INTO v_lines_cancelled FROM cancelled;

      UPDATE public.lease_schedule_lines s
         SET period_ends_on = v_conflict.newer_from - 1,
             amount = round((s.amount * ((v_conflict.newer_from - 1 - s.period_starts_on + 1)::numeric
                                         / (s.period_ends_on - s.period_starts_on + 1))), 4),
             updated_at = now()
       WHERE s.charge_id = v_conflict.older_id
         AND s.org_id = (SELECT org_id FROM public.lease_charges WHERE id = v_conflict.older_id)
         AND s.status = 'scheduled'
         AND s.period_starts_on < v_conflict.newer_from
         AND s.period_ends_on >= v_conflict.newer_from;
    ELSE
      -- Same-start duplicates: only one row may own the shared window. Billed
      -- history always wins; ties fall to the newest row (uuidv7 ids sort by
      -- creation time), as 0051 kept shadow duplicates.
      SELECT
        count(*) FILTER (WHERE s.status IN ('invoiced', 'credited') AND c.id = v_conflict.older_id),
        count(*) FILTER (WHERE s.status IN ('invoiced', 'credited') AND c.id = v_conflict.newer_id)
        INTO v_older_billed, v_newer_billed
        FROM (VALUES (v_conflict.older_id), (v_conflict.newer_id)) AS pair(id)
        JOIN public.lease_charges c ON c.id = pair.id
        LEFT JOIN public.lease_schedule_lines s ON s.charge_id = c.id AND s.org_id = c.org_id;

      DECLARE
        v_loser uuid := CASE WHEN v_older_billed > v_newer_billed THEN v_conflict.newer_id ELSE v_conflict.older_id END;
        v_loser_lines integer;
      BEGIN
        SELECT count(*) INTO v_loser_lines
          FROM public.lease_schedule_lines
         WHERE charge_id = v_loser
           AND org_id = (SELECT org_id FROM public.lease_charges WHERE id = v_loser);
        IF v_loser_lines > 0 THEN
          RAISE EXCEPTION 'lease_charges repair: base-rent rows % and % share effective_from % and both hold schedule-line history — resolve them manually before migrating',
            v_conflict.older_id, v_conflict.newer_id, v_conflict.newer_from;
        END IF;
        DELETE FROM public.lease_charges WHERE id = v_loser;
        v_shadows_deleted := v_shadows_deleted + 1;
      END;
    END IF;
  END LOOP;

  RAISE NOTICE 'lease_charges repair: % overlapping window(s) closed before successor, % orphanless duplicate(s) deleted, % future scheduled line(s) cancelled',
    v_windows_closed, v_shadows_deleted, v_lines_cancelled;
  windows_closed := v_windows_closed;
  shadows_deleted := v_shadows_deleted;
  lines_cancelled := v_lines_cancelled;
  RETURN NEXT;
END
$$;


--
-- Name: FUNCTION lease_charges_base_rent_repair(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lease_charges_base_rent_repair() IS 'openbooks:lease_charges_base_rent_repair:v2 - explicit, idempotent maintenance repair for overlapping base-rent charges; it is never invoked automatically, and each conflict contributes to the cumulative cancelled-line total while billed evidence remains untouched';


--
-- Name: lease_schedule_history_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_schedule_history_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'lease schedules are retained; supersede future rows through an approved change'; END IF;
  IF (to_jsonb(NEW) - ARRAY['payment_entry_id','amortization_entry_id','posted_at','payment_posted_at','accrual_posted_at','superseded_by_change_id','updated_at','updated_by'])
     IS DISTINCT FROM
     (to_jsonb(OLD) - ARRAY['payment_entry_id','amortization_entry_id','posted_at','payment_posted_at','accrual_posted_at','superseded_by_change_id','updated_at','updated_by']) THEN
    RAISE EXCEPTION 'lease schedule measurements are immutable; append a revision';
  END IF;
  IF NEW.superseded_by_change_id IS DISTINCT FROM OLD.superseded_by_change_id THEN
    IF OLD.accrual_posted_at IS NOT NULL OR NOT EXISTS (
      SELECT 1 FROM financial_changes c WHERE c.id=NEW.superseded_by_change_id AND c.org_id=OLD.org_id
        AND c.subject_id=OLD.lease_id AND c.domain='lease' AND c.status='approved') THEN
      RAISE EXCEPTION 'only unaccrued rows may be superseded by an approved change to this lease';
    END IF;
  END IF;
  IF (OLD.payment_posted_at IS NOT NULL AND (NEW.payment_posted_at IS DISTINCT FROM OLD.payment_posted_at OR NEW.payment_entry_id IS DISTINCT FROM OLD.payment_entry_id))
    OR (OLD.accrual_posted_at IS NOT NULL AND (NEW.accrual_posted_at IS DISTINCT FROM OLD.accrual_posted_at OR NEW.amortization_entry_id IS DISTINCT FROM OLD.amortization_entry_id))
    OR (OLD.superseded_by_change_id IS NOT NULL AND NEW IS DISTINCT FROM OLD) THEN
    RAISE EXCEPTION 'completed lease events cannot be changed';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: hrm_leave_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hrm_leave_requests (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    employment_id uuid NOT NULL,
    leave_type_id uuid NOT NULL,
    starts_on date NOT NULL,
    ends_on date NOT NULL,
    hours numeric(9,2) NOT NULL,
    reason text,
    status text DEFAULT 'draft'::text NOT NULL,
    decided_by uuid,
    decided_at timestamp with time zone,
    decision_reason text,
    flow_instance_id uuid,
    attachment_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT hrm_leave_requests_decision CHECK ((((status = ANY (ARRAY['approved'::text, 'rejected'::text])) AND (decided_by IS NOT NULL) AND (decided_at IS NOT NULL) AND (decision_reason IS NOT NULL) AND (char_length(btrim(decision_reason)) > 0)) OR ((status = ANY (ARRAY['draft'::text, 'submitted'::text, 'withdrawn'::text, 'cancelled'::text])) AND (decided_by IS NULL) AND (decided_at IS NULL)))),
    CONSTRAINT hrm_leave_requests_finite_time CHECK (((starts_on >= '0001-01-01'::date) AND (starts_on <= '9999-12-31'::date) AND ((ends_on >= '0001-01-01'::date) AND (ends_on <= '9999-12-31'::date)))),
    CONSTRAINT hrm_leave_requests_hours CHECK ((hours > (0)::numeric)),
    CONSTRAINT hrm_leave_requests_range CHECK ((ends_on >= starts_on)),
    CONSTRAINT hrm_leave_requests_status CHECK ((status = ANY (ARRAY['draft'::text, 'submitted'::text, 'approved'::text, 'rejected'::text, 'withdrawn'::text, 'cancelled'::text])))
);

ALTER TABLE ONLY public.hrm_leave_requests FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE hrm_leave_requests; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.hrm_leave_requests IS 'HRM leave requests: lifecycle draft/submitted/approved/rejected/withdrawn/cancelled. Approved requests never overlap per employment (storage exclusion); the service refuses overlapping submits first.';


--
-- Name: leave_request_approval_fingerprint(public.hrm_leave_requests); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.leave_request_approval_fingerprint(r public.hrm_leave_requests) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 SELECT public.flow_command_record_fingerprint(to_jsonb(r)-ARRAY['flow_instance_id','decided_by','decided_at','decision_reason'])
$$;


--
-- Name: lock_actor_home_identity(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lock_actor_home_identity(p_org uuid, p_actor uuid, p_home uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  original_scope text := current_setting('app.current_org', true);
  target_member boolean;
  locked public.users%rowtype;
BEGIN
  IF p_org IS NULL OR original_scope IS DISTINCT FROM p_org::text OR p_actor IS NULL OR p_home IS NULL THEN
    RAISE EXCEPTION 'Actor command tenant scope does not match its organization';
  END IF;
  PERFORM a.id FROM public.role_assignments a
    JOIN public.app_roles r ON r.org_id=a.org_id AND r.id=a.role_id
    WHERE a.org_id=p_org AND a.user_id=p_actor
    ORDER BY a.id FOR SHARE OF a,r;
  target_member := FOUND;
  BEGIN
    PERFORM set_config('app.current_org', p_home::text, true);
    SELECT u.* INTO locked FROM public.users u
      WHERE u.id=p_actor AND u.org_id=p_home FOR SHARE;
    IF NOT FOUND OR NOT locked.is_active OR (NOT locked.is_super_admin AND NOT target_member) THEN
      RAISE EXCEPTION 'Actor is not eligible to command this organization';
    END IF;
    PERFORM set_config('app.current_org', original_scope, true);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('app.current_org', original_scope, true);
    RAISE;
  END;
END;
$$;


--
-- Name: FUNCTION lock_actor_home_identity(p_org uuid, p_actor uuid, p_home uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lock_actor_home_identity(p_org uuid, p_actor uuid, p_home uuid) IS 'Invoker-only actor and membership share locks retained by the caller transaction; tenant scope is restored before returning.';


--
-- Name: manufacturing_completion_trace_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manufacturing_completion_trace_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE work_number text; source_quantity numeric; assigned_quantity numeric;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Completion trace evidence is immutable; reverse its receipt to correct the batch.' USING ERRCODE='23514'; END IF;
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 SELECT number INTO work_number FROM mfg_work_orders WHERE org_id=NEW.org_id AND id=NEW.work_order_id FOR SHARE;
 IF work_number IS NULL OR NOT EXISTS(SELECT 1 FROM journal_entries WHERE org_id=NEW.org_id AND id=NEW.completion_entry_id AND origin='manufacturing' AND status='posted' AND reverses_entry_id IS NULL AND custom->>'work_order_number'=work_number AND custom ? 'completion_quantity') THEN
  RAISE EXCEPTION 'Completion evidence requires the posted receipt of its work order.' USING ERRCODE='23514';
 END IF;
 IF TG_TABLE_NAME='mfg_completion_batches' THEN
  IF NOT EXISTS(SELECT 1 FROM journal_entries WHERE org_id=NEW.org_id AND id=NEW.completion_entry_id AND (custom->>'completion_quantity')::numeric=NEW.quantity) THEN RAISE EXCEPTION 'Batch quantity must match its native receipt.' USING ERRCODE='23514'; END IF;
 ELSE
  SELECT -movement.quantity INTO source_quantity FROM inventory_movements movement JOIN journal_entries entry ON entry.org_id=movement.org_id AND entry.id=movement.journal_entry_id
   WHERE movement.org_id=NEW.org_id AND movement.id=NEW.input_movement_id AND movement.kind='assembly_consume' AND movement.status='posted' AND movement.reverses_movement_id IS NULL
    AND entry.origin='manufacturing' AND entry.status='posted' AND entry.custom->>'work_order_number'=work_number
    AND NOT EXISTS(SELECT 1 FROM inventory_movements reversal WHERE reversal.org_id=movement.org_id AND reversal.reverses_movement_id=movement.id AND reversal.status='posted') FOR UPDATE OF movement;
  SELECT coalesce(sum(allocation.quantity),0) INTO assigned_quantity FROM mfg_completion_inputs allocation JOIN journal_entries receipt ON receipt.org_id=allocation.org_id AND receipt.id=allocation.completion_entry_id
   WHERE allocation.org_id=NEW.org_id AND allocation.input_movement_id=NEW.input_movement_id AND receipt.status='posted' AND receipt.reverses_entry_id IS NULL;
  IF source_quantity IS NULL OR NEW.quantity+assigned_quantity>source_quantity THEN RAISE EXCEPTION 'Completion inputs must use unassigned native issues from the same work order.' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: manufacturing_inspected_output_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manufacturing_inspected_output_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE movement inventory_movements; work mfg_work_orders; operation mfg_wo_operations; accepted inventory_inspections; total_goods numeric; identifier_goods numeric;
BEGIN
 IF public.openbooks_clone_authority() THEN RETURN NULL; END IF;
 SELECT * INTO movement FROM inventory_movements WHERE org_id=NEW.org_id AND id=NEW.id;
 IF movement.kind<>'assembly_build' OR movement.quantity<=0 OR movement.status<>'posted' OR movement.reverses_movement_id IS NOT NULL THEN RETURN NULL; END IF;
 SELECT order_row.* INTO work FROM mfg_work_orders order_row JOIN journal_entries entry
   ON entry.org_id=order_row.org_id AND entry.custom->>'work_order_number'=order_row.number
   WHERE entry.org_id=movement.org_id AND entry.id=movement.journal_entry_id AND entry.origin='manufacturing'
     AND entry.status='posted' AND entry.reverses_entry_id IS NULL AND order_row.produced_item_id=movement.item_id;
 IF work.id IS NULL THEN RETURN NULL; END IF;
 SELECT coalesce(sum(receipt.quantity),0),coalesce(sum(receipt.quantity) FILTER(WHERE receipt.lot_id IS NOT DISTINCT FROM movement.lot_id AND receipt.serial_id IS NOT DISTINCT FROM movement.serial_id),0)
   INTO total_goods,identifier_goods FROM inventory_movements receipt JOIN journal_entries entry ON entry.org_id=receipt.org_id AND entry.id=receipt.journal_entry_id
   WHERE receipt.org_id=work.org_id AND receipt.item_id=work.produced_item_id AND receipt.kind='assembly_build' AND receipt.quantity>0
     AND receipt.status='posted' AND receipt.reverses_movement_id IS NULL AND entry.origin='manufacturing' AND entry.status='posted'
     AND entry.reverses_entry_id IS NULL AND entry.custom->>'work_order_number'=work.number;
 FOR operation IN SELECT * FROM mfg_wo_operations WHERE org_id=work.org_id AND work_order_id=work.id AND inspection_plan_snapshot IS NOT NULL LOOP
  IF operation.status<>'done' OR total_goods>operation.quantity_done OR EXISTS(SELECT 1 FROM inventory_inspections inspection
    WHERE inspection.org_id=work.org_id AND inspection.operation_id=operation.id AND (inspection.status='pending'
      OR inspection.status='fail' AND (inspection.disposition IS NULL OR inspection.disposition='rework' AND inspection.rework_completed_at IS NULL))) THEN
   RAISE EXCEPTION 'Finished output requires completed operations and resolved inspections covering its quantity.' USING ERRCODE='23514';
  END IF;
  SELECT * INTO accepted FROM inventory_inspections inspection WHERE inspection.org_id=work.org_id AND inspection.operation_id=operation.id
    AND inspection.lot_id IS NOT DISTINCT FROM movement.lot_id AND inspection.serial_id IS NOT DISTINCT FROM movement.serial_id
    ORDER BY inspection.inspection_sequence DESC LIMIT 1;
  IF accepted.id IS NULL OR identifier_goods>accepted.quantity OR NOT coalesce(accepted.status='pass' OR accepted.disposition='use_as_is' OR accepted.disposition='rework' AND accepted.rework_completed_at IS NOT NULL,false) THEN
   RAISE EXCEPTION 'Finished output identifiers and quantity must match accepted operation inspections.' USING ERRCODE='23514';
  END IF;
 END LOOP;
 RETURN NULL;
END $$;


--
-- Name: manufacturing_loss_completion_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manufacturing_loss_completion_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE event mfg_scrap_events; change financial_changes; work mfg_work_orders; balance numeric;
BEGIN
 IF public.openbooks_clone_authority() THEN RETURN NULL; END IF;
 SELECT * INTO event FROM mfg_scrap_events WHERE org_id=NEW.org_id AND id=NEW.id;
 IF event.disposition_change_id IS NULL THEN RETURN NULL; END IF;
 SELECT * INTO change FROM financial_changes WHERE org_id=event.org_id AND id=event.disposition_change_id;
 SELECT * INTO work FROM mfg_work_orders WHERE org_id=event.org_id AND id=event.work_order_id;
 SELECT coalesce(sum(line.amount),0) INTO balance FROM journal_lines line JOIN journal_entries entry ON entry.org_id=line.org_id AND entry.id=line.entry_id WHERE line.org_id=event.org_id AND line.account_id::text=change.before_state->>'wipAccountId' AND entry.origin='manufacturing' AND entry.custom->>'work_order_number'=work.number AND entry.status IN('posted','reversed');
 IF change.status IS DISTINCT FROM 'applied' OR change.result->>'eventId' IS DISTINCT FROM event.id::text OR change.result->>'entryId' IS DISTINCT FROM event.posted_entry_id::text OR work.loss_change_id IS DISTINCT FROM change.id OR work.status<>'cancelled' OR work.quantity_completed<>0 OR balance<>0 THEN
  RAISE EXCEPTION 'Loss disposition must finish its governed order, exact journal and zero remaining WIP atomically.' USING ERRCODE='23514';
 END IF;
 RETURN NULL;
END $$;


--
-- Name: manufacturing_loss_event_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manufacturing_loss_event_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE change financial_changes; work mfg_work_orders; balance numeric;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='DELETE' THEN
  IF OLD.disposition_change_id IS NOT NULL THEN RAISE EXCEPTION 'Approved loss evidence is immutable.' USING ERRCODE='23514'; END IF;
  RETURN OLD;
 END IF;
 IF TG_OP='UPDATE' THEN
  IF NEW.disposition_change_id IS DISTINCT FROM OLD.disposition_change_id OR (OLD.disposition_change_id IS NOT NULL AND (to_jsonb(NEW)-ARRAY['updated_at','updated_by']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['updated_at','updated_by'])) THEN RAISE EXCEPTION 'Approved loss evidence is immutable.' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 IF NEW.disposition_change_id IS NULL THEN RETURN NEW; END IF;
 SELECT * INTO change FROM financial_changes WHERE org_id=NEW.org_id AND id=NEW.disposition_change_id FOR SHARE;
 SELECT * INTO work FROM mfg_work_orders WHERE org_id=NEW.org_id AND id=NEW.work_order_id FOR UPDATE;
 IF change.id IS NULL OR work.id IS NULL OR change.domain<>'manufacturing' OR change.operation<>'work_order_loss_disposition' OR change.status<>'approved'
   OR change.subject_id<>work.id OR change.subsidiary_id IS DISTINCT FROM work.subsidiary_id OR work.status<>'on_hold' OR work.quantity_completed<>0
   OR NEW.classification<>'abnormal' OR NEW.treatment<>'operation' OR NEW.approval_required IS DISTINCT FROM true
   OR NEW.quantity<=0 OR NEW.quantity>work.quantity_ordered-work.quantity_scrapped
   OR NEW.quantity IS DISTINCT FROM (change.before_state->>'quantity')::numeric OR NEW.frozen_value IS DISTINCT FROM (change.before_state->>'value')::numeric
   OR NEW.frozen_unit_cost IS DISTINCT FROM round(NEW.frozen_value/NEW.quantity,4)
   OR NEW.operation_id::text IS DISTINCT FROM change.payload->'input'->>'operationId' OR NEW.reason_id::text IS DISTINCT FROM change.payload->'input'->>'reasonId'
   OR (NEW.frozen_value=0) IS DISTINCT FROM (NEW.posted_entry_id IS NULL)
   OR change.approved_by IS NULL OR NOT(change.approved_by<>change.submitted_by OR public.financial_change_self_decision_authorized(change.org_id,change.id,change.submitted_by)) THEN
   RAISE EXCEPTION 'Loss evidence requires its exact approved work, quantity, value and independent decision.' USING ERRCODE='23514';
 END IF;
 SELECT coalesce(sum(line.amount),0) INTO balance FROM journal_lines line JOIN journal_entries entry ON entry.org_id=line.org_id AND entry.id=line.entry_id
   WHERE line.org_id=NEW.org_id AND line.account_id::text=change.before_state->>'wipAccountId' AND entry.origin='manufacturing'
     AND entry.custom->>'work_order_number'=work.number AND entry.status IN('posted','reversed') AND entry.id IS DISTINCT FROM NEW.posted_entry_id;
 IF balance IS DISTINCT FROM NEW.frozen_value THEN RAISE EXCEPTION 'Loss recognizes all actual remaining WIP, including consumed conversion.' USING ERRCODE='23514'; END IF;
 IF NEW.posted_entry_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM journal_entries entry WHERE entry.org_id=NEW.org_id AND entry.id=NEW.posted_entry_id AND entry.status='posted'
   AND entry.origin='manufacturing' AND entry.subsidiary_id=work.subsidiary_id AND entry.custom->>'loss_change_id'=change.id::text AND entry.custom->>'scrap_event_id'=NEW.id::text
   AND (SELECT coalesce(sum(amount),0) FROM journal_lines WHERE org_id=NEW.org_id AND entry_id=entry.id AND account_id::text=change.before_state->>'wipAccountId')=-NEW.frozen_value
   AND (SELECT coalesce(sum(amount),0) FROM journal_lines WHERE org_id=NEW.org_id AND entry_id=entry.id AND account_id::text=change.before_state->>'lossAccountId')=NEW.frozen_value
   AND (SELECT count(*) FROM journal_lines WHERE org_id=NEW.org_id AND entry_id=entry.id)=2) THEN
   RAISE EXCEPTION 'Loss requires its exact balanced native write-off journal.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: manufacturing_loss_journal_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manufacturing_loss_journal_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND OLD.status='posted' AND NEW.status IS DISTINCT FROM OLD.status AND EXISTS(SELECT 1 FROM mfg_work_orders work WHERE work.org_id=OLD.org_id AND work.number=OLD.custom->>'work_order_number' AND work.loss_change_id IS NOT NULL) THEN
  RAISE EXCEPTION 'A disposed production loss retains its journal. Record an approved adjusting journal for a financial correction; discarded stock and work cannot be recreated by reversal.' USING ERRCODE='23514';
 END IF;
 IF TG_OP='INSERT' AND NEW.reverses_entry_id IS NOT NULL AND EXISTS(SELECT 1 FROM journal_entries source JOIN mfg_work_orders work ON work.org_id=source.org_id AND work.number=source.custom->>'work_order_number' WHERE source.org_id=NEW.org_id AND source.id=NEW.reverses_entry_id AND work.loss_change_id IS NOT NULL) THEN
  RAISE EXCEPTION 'A disposed production loss requires an adjusting journal rather than a reversal that would recreate WIP.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: manufacturing_loss_order_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manufacturing_loss_order_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.loss_change_id IS NOT NULL THEN RAISE EXCEPTION 'A production order starts without a loss disposition.' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 IF OLD.loss_change_id IS NOT NULL THEN
  IF (NEW.status,NEW.quantity_completed,NEW.quantity_scrapped,NEW.loss_change_id,NEW.cancel_reason) IS DISTINCT FROM (OLD.status,OLD.quantity_completed,OLD.quantity_scrapped,OLD.loss_change_id,OLD.cancel_reason) THEN RAISE EXCEPTION 'A disposed order retains its terminal loss evidence.' USING ERRCODE='23514'; END IF;
 ELSIF NEW.loss_change_id IS NOT NULL THEN
  IF OLD.status<>'on_hold' OR NEW.status<>'cancelled' OR NEW.quantity_completed<>0 OR NOT EXISTS(SELECT 1 FROM financial_changes change JOIN mfg_scrap_events event ON event.org_id=change.org_id AND event.disposition_change_id=change.id
   WHERE change.org_id=NEW.org_id AND change.id=NEW.loss_change_id AND change.subject_id=NEW.id AND change.domain='manufacturing' AND change.operation='work_order_loss_disposition' AND change.status='approved'
   AND event.work_order_id=NEW.id AND event.quantity=NEW.quantity_scrapped-OLD.quantity_scrapped AND NEW.cancel_reason=change.reason) THEN
   RAISE EXCEPTION 'Closing as loss requires its approved actual scrap and WIP evidence.' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: manufacturing_material_formula_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manufacturing_material_formula_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF (to_jsonb(NEW)->'quantity_per',to_jsonb(NEW)->'scrap_pct',NEW.quantity_basis,NEW.formula_output_quantity,to_jsonb(NEW)->'output_cost_weight',to_jsonb(NEW)->'standard_cost_snapshot') IS DISTINCT FROM (to_jsonb(OLD)->'quantity_per',to_jsonb(OLD)->'scrap_pct',OLD.quantity_basis,OLD.formula_output_quantity,to_jsonb(OLD)->'output_cost_weight',to_jsonb(OLD)->'standard_cost_snapshot') THEN RAISE EXCEPTION 'Released material and output quantities retain their recipe, cost weights and standard snapshots.' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: manufacturing_operation_inspection_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manufacturing_operation_inspection_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF NEW.inspection_plan_snapshot IS DISTINCT FROM OLD.inspection_plan_snapshot THEN
  RAISE EXCEPTION 'Released operations keep their inspection plan.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: manufacturing_receipt_rework_link_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manufacturing_receipt_rework_link_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE work mfg_work_orders; failed inventory_inspections;
BEGIN
 IF public.openbooks_clone_authority() THEN RETURN NULL; END IF;
 SELECT * INTO work FROM mfg_work_orders WHERE org_id=NEW.org_id AND id=NEW.id;
 IF work.receipt_rework_inspection_id IS NULL THEN RETURN NULL; END IF;
 SELECT * INTO failed FROM inventory_inspections WHERE org_id=work.org_id AND id=work.receipt_rework_inspection_id;
 IF failed.disposition IS DISTINCT FROM 'rework' OR failed.rework_work_order_id IS DISTINCT FROM work.id OR failed.disposition_result->>'workOrderId' IS DISTINCT FROM work.id::text THEN
  RAISE EXCEPTION 'A receipt repair and its failed-stock disposition must be linked atomically.' USING ERRCODE='23514';
 END IF;
 IF work.status NOT IN('draft','cancelled') AND (SELECT count(*) FROM mfg_wo_operations operation WHERE operation.org_id=work.org_id AND operation.work_order_id=work.id AND operation.sequence=work.receipt_rework_sequence AND operation.backflush_at='none' AND operation.inspection_plan_snapshot=failed.plan_snapshot||jsonb_build_object('point','operation','operationSequence',work.receipt_rework_sequence))<>1 THEN
  RAISE EXCEPTION 'A released repair requires its selected operation, original frozen acceptance plan and manual stock issue.' USING ERRCODE='23514';
 END IF;
 RETURN NULL;
END $$;


--
-- Name: manufacturing_receipt_rework_movement_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manufacturing_receipt_rework_movement_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE movement inventory_movements; work mfg_work_orders; failed inventory_inspections;
BEGIN
 IF public.openbooks_clone_authority() THEN RETURN NULL; END IF;
 SELECT * INTO movement FROM inventory_movements WHERE org_id=NEW.org_id AND id=NEW.id;
 IF movement.kind NOT IN('assembly_consume','assembly_build') THEN RETURN NULL; END IF;
 SELECT order_row.* INTO work FROM mfg_work_orders order_row JOIN journal_entries entry ON entry.org_id=order_row.org_id AND entry.custom->>'work_order_number'=order_row.number WHERE entry.org_id=movement.org_id AND entry.id=movement.journal_entry_id AND entry.origin='manufacturing' AND order_row.receipt_rework_inspection_id IS NOT NULL;
 IF work.id IS NULL THEN RETURN NULL; END IF;
 SELECT * INTO failed FROM inventory_inspections WHERE org_id=work.org_id AND id=work.receipt_rework_inspection_id;
 IF movement.item_id<>failed.item_id OR movement.subsidiary_id<>failed.subsidiary_id OR movement.lot_id IS DISTINCT FROM failed.lot_id OR movement.serial_id IS DISTINCT FROM failed.serial_id OR abs(movement.quantity)<>failed.quantity OR movement.status<>'posted' THEN
  RAISE EXCEPTION 'Repair movements retain the original inspected item, entity, identifier and full quantity.' USING ERRCODE='23514';
 END IF;
 IF movement.kind='assembly_consume' AND (movement.stock_location_id<>failed.stock_location_id OR
   (SELECT coalesce(sum(consumption.quantity),0) FROM cost_layer_consumptions consumption JOIN cost_layers layer ON layer.org_id=consumption.org_id AND layer.id=consumption.cost_layer_id WHERE consumption.org_id=movement.org_id AND consumption.issue_movement_id=movement.id AND layer.source_movement_id=failed.receipt_movement_id)<>failed.quantity OR
   EXISTS(SELECT 1 FROM cost_layer_consumptions consumption JOIN cost_layers layer ON layer.org_id=consumption.org_id AND layer.id=consumption.cost_layer_id WHERE consumption.org_id=movement.org_id AND consumption.issue_movement_id=movement.id AND layer.source_movement_id IS DISTINCT FROM failed.receipt_movement_id)) THEN
  RAISE EXCEPTION 'Repair consumption requires the exact original receipt cost layers.' USING ERRCODE='23514';
 END IF;
 IF movement.kind='assembly_build' AND (movement.stock_location_id<>work.receipt_location_id OR NOT EXISTS(
   SELECT 1 FROM mfg_wo_operations operation JOIN inventory_inspections accepted ON accepted.org_id=operation.org_id AND accepted.operation_id=operation.id WHERE operation.org_id=work.org_id AND operation.work_order_id=work.id AND operation.sequence=work.receipt_rework_sequence AND operation.status='done' AND operation.quantity_done>=failed.quantity AND accepted.status='pass' AND accepted.quantity>=failed.quantity AND accepted.lot_id IS NOT DISTINCT FROM failed.lot_id AND accepted.serial_id IS NOT DISTINCT FROM failed.serial_id)) THEN
  RAISE EXCEPTION 'Repair output requires its passed frozen inspection and original stock identity.' USING ERRCODE='23514';
 END IF;
 RETURN NULL;
END $$;


--
-- Name: manufacturing_receipt_rework_order_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manufacturing_receipt_rework_order_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE failed inventory_inspections;
BEGIN
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND OLD.receipt_rework_inspection_id IS NOT NULL AND
  (NEW.receipt_rework_inspection_id,NEW.receipt_rework_sequence,NEW.produced_item_id,NEW.subsidiary_id,NEW.quantity_ordered,NEW.issue_location_id) IS DISTINCT FROM
  (OLD.receipt_rework_inspection_id,OLD.receipt_rework_sequence,OLD.produced_item_id,OLD.subsidiary_id,OLD.quantity_ordered,OLD.issue_location_id) THEN
  RAISE EXCEPTION 'A repair retains its inspected item, entity, source location, quantity and operation.' USING ERRCODE='23514';
 END IF;
 IF NEW.receipt_rework_inspection_id IS NULL THEN RETURN NEW; END IF;
 SELECT * INTO failed FROM inventory_inspections WHERE org_id=NEW.org_id AND id=NEW.receipt_rework_inspection_id FOR SHARE;
 IF failed.id IS NULL OR failed.status<>'fail' OR failed.receipt_movement_id IS NULL OR failed.item_id<>NEW.produced_item_id OR failed.subsidiary_id<>NEW.subsidiary_id OR failed.stock_location_id<>NEW.issue_location_id OR failed.quantity<>NEW.quantity_ordered THEN
  RAISE EXCEPTION 'A repair requires its exact failed receipt and original stock identity.' USING ERRCODE='23514';
 END IF;
 IF NEW.status='cancelled' AND NEW.loss_change_id IS NULL THEN RAISE EXCEPTION 'Resolve a received-stock repair through completion or approved loss; its original stock remains held.' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: manufacturing_released_revision_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manufacturing_released_revision_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF OLD.released_at IS NOT NULL AND (NEW.produced_item_id,NEW.routing_id,NEW.routing_version,NEW.bom_revision,NEW.standard_cost_snapshot,NEW.unit,NEW.quantity_ordered,NEW.subsidiary_id,NEW.released_at,NEW.production_mode,NEW.campaign_reference,CASE WHEN NEW.production_mode='continuous' THEN NEW.planned_start END,CASE WHEN NEW.production_mode='continuous' THEN NEW.planned_end END)
  IS DISTINCT FROM (OLD.produced_item_id,OLD.routing_id,OLD.routing_version,OLD.bom_revision,OLD.standard_cost_snapshot,OLD.unit,OLD.quantity_ordered,OLD.subsidiary_id,OLD.released_at,OLD.production_mode,OLD.campaign_reference,CASE WHEN OLD.production_mode='continuous' THEN OLD.planned_start END,CASE WHEN OLD.production_mode='continuous' THEN OLD.planned_end END) THEN
  RAISE EXCEPTION 'Released work retains its production revision, quantity and cost evidence.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: manufacturing_routing_operation_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manufacturing_routing_operation_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE parent_org uuid; parent_id uuid; parent_status text;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 parent_org:=CASE WHEN TG_OP='DELETE' THEN OLD.org_id ELSE NEW.org_id END;
 parent_id:=CASE WHEN TG_OP='DELETE' THEN OLD.routing_id ELSE NEW.routing_id END;
 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(parent_org) THEN RETURN OLD; END IF;
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND (NEW.org_id,NEW.routing_id) IS DISTINCT FROM (OLD.org_id,OLD.routing_id) THEN RAISE EXCEPTION 'Routing operations cannot move between revisions.' USING ERRCODE='23514'; END IF;
 SELECT status INTO parent_status FROM mfg_routings WHERE org_id=parent_org AND id=parent_id FOR SHARE;
 IF parent_status IS DISTINCT FROM 'draft' THEN RAISE EXCEPTION 'Approved routing operations are immutable; edit a new revision.' USING ERRCODE='23514'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $$;


--
-- Name: manufacturing_routing_revision_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manufacturing_routing_revision_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'draft' OR NEW.activation_change_id IS NOT NULL THEN RAISE EXCEPTION 'Routing revisions start as unapproved drafts.' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 IF OLD.status='draft' AND NEW.status='active' THEN
  IF NEW.activation_change_id IS NULL OR NOT EXISTS(SELECT 1 FROM financial_changes change
   WHERE change.org_id=NEW.org_id AND change.id=NEW.activation_change_id AND change.subject_id=NEW.id
    AND change.domain='manufacturing' AND change.operation='routing_revision_activation' AND change.status='approved'
    AND change.approved_by IS NOT NULL AND (change.approved_by<>change.submitted_by OR public.financial_change_self_decision_authorized(change.org_id,change.id,change.submitted_by)
     OR (change.approved_by=change.submitted_by
      AND COALESCE(change.payload->'decision'->>'mode','')='automatic'
      AND COALESCE(change.payload->'decision'->'policy'->>'flowConfigured','')='false'
      AND NOT EXISTS(SELECT 1 FROM flows f WHERE f.org_id=change.org_id AND f.subject_kind='financial_change' AND f.enabled)
      AND NOT EXISTS(SELECT 1 FROM flow_runs r WHERE r.org_id=change.org_id AND r.subject_kind='financial_change' AND r.subject_id=change.id)))
    AND ((change.before_state->'candidate')-ARRAY['operations','locations'])=jsonb_build_object(
      'id',OLD.id,'orgId',OLD.org_id,'producedItemId',OLD.produced_item_id,'code',OLD.code,'name',OLD.name,'version',OLD.version,'status','draft',
      'effectiveFrom',OLD.effective_from::text,'effectiveTo',OLD.effective_to::text,'defaultIssueLocationId',OLD.default_issue_location_id,'defaultReceiptLocationId',OLD.default_receipt_location_id,'overheadBasis',OLD.overhead_basis)
    AND change.before_state->'candidate'->'operations'=(SELECT coalesce(jsonb_agg(jsonb_build_object('id',operation.id,'orgId',operation.org_id,'routingId',operation.routing_id,'sequence',operation.sequence,'name',operation.name,'workCenterId',operation.work_center_id,
      'setupMinutes',operation.setup_minutes::text,'runMinutesPerUnit',operation.run_minutes_per_unit::text,'laborMinutesPerUnit',operation.labor_minutes_per_unit::text,'laborTimeSource',operation.labor_time_source,'backflushAt',operation.backflush_at,'qualityGate',operation.quality_gate,'workCenterSubsidiaryId',center.subsidiary_id) ORDER BY operation.sequence),'[]'::jsonb)
      FROM mfg_routing_operations operation JOIN mfg_work_centers center ON center.org_id=operation.org_id AND center.id=operation.work_center_id WHERE operation.org_id=OLD.org_id AND operation.routing_id=OLD.id))
    OR (NEW.produced_item_id,NEW.code,NEW.name,NEW.version,NEW.effective_from,NEW.effective_to,NEW.default_issue_location_id,NEW.default_receipt_location_id,NEW.overhead_basis)
      IS DISTINCT FROM (OLD.produced_item_id,OLD.code,OLD.name,OLD.version,OLD.effective_from,OLD.effective_to,OLD.default_issue_location_id,OLD.default_receipt_location_id,OLD.overhead_basis) THEN
   RAISE EXCEPTION 'Routing activation requires its unchanged approved revision proposal.' USING ERRCODE='23514';
  END IF;
 ELSIF NEW.activation_change_id IS DISTINCT FROM OLD.activation_change_id THEN
  RAISE EXCEPTION 'Routing activation evidence is immutable.' USING ERRCODE='23514';
 END IF;
 IF OLD.status<>'draft' THEN
  IF (NEW.produced_item_id,NEW.code,NEW.name,NEW.version,NEW.effective_from,NEW.default_issue_location_id,NEW.default_receipt_location_id,NEW.overhead_basis)
    IS DISTINCT FROM (OLD.produced_item_id,OLD.code,OLD.name,OLD.version,OLD.effective_from,OLD.default_issue_location_id,OLD.default_receipt_location_id,OLD.overhead_basis)
    OR NEW.status NOT IN ('active','archived') THEN RAISE EXCEPTION 'Approved routing content is immutable; create a new revision.' USING ERRCODE='23514'; END IF;
  IF NEW.effective_to IS DISTINCT FROM OLD.effective_to AND NOT EXISTS(
    SELECT 1 FROM financial_changes change JOIN mfg_routings candidate ON candidate.org_id=change.org_id AND candidate.id=change.subject_id
    WHERE change.org_id=NEW.org_id AND change.domain='manufacturing' AND change.operation='routing_revision_activation'
      AND change.status='approved' AND candidate.status='draft' AND candidate.produced_item_id=NEW.produced_item_id
      AND candidate.effective_from=NEW.effective_to AND change.approved_by IS NOT NULL
      AND (change.approved_by<>change.submitted_by OR public.financial_change_self_decision_authorized(change.org_id,change.id,change.submitted_by)
       OR (change.approved_by=change.submitted_by
        AND COALESCE(change.payload->'decision'->>'mode','')='automatic'
        AND COALESCE(change.payload->'decision'->'policy'->>'flowConfigured','')='false'
        AND NOT EXISTS(SELECT 1 FROM flows f WHERE f.org_id=change.org_id AND f.subject_kind='financial_change' AND f.enabled)
        AND NOT EXISTS(SELECT 1 FROM flow_runs r WHERE r.org_id=change.org_id AND r.subject_kind='financial_change' AND r.subject_id=change.id)))
      AND EXISTS(SELECT 1 FROM jsonb_array_elements(change.payload->'supersedes') prior
        WHERE prior->>'id'=OLD.id::text AND prior->>'effectiveTo' IS NOT DISTINCT FROM OLD.effective_to::text)) THEN
    RAISE EXCEPTION 'Changing a prior effective window requires an approved successor revision.' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: manufacturing_run_profile_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manufacturing_run_profile_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF NEW.production_mode<>'order' AND NOT EXISTS(SELECT 1 FROM operating_profile_versions profile WHERE profile.org_id=NEW.org_id AND profile.id=NEW.operating_profile_version_id AND profile.family='production' AND profile.definition->>'physicalModel'='process') THEN
  RAISE EXCEPTION 'Batch and continuous runs require their pinned process workflow.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: manufacturing_snapshot_addition_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manufacturing_snapshot_addition_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE work mfg_work_orders;
BEGIN
 IF public.openbooks_clone_authority() THEN RETURN NULL; END IF;
 SELECT * INTO work FROM mfg_work_orders WHERE org_id=NEW.org_id AND id=NEW.work_order_id;
 IF work.id IS NULL OR work.released_at IS NULL OR work.released_at>=transaction_timestamp() THEN RETURN NULL; END IF;
 IF TG_TABLE_NAME='mfg_wo_operations' AND EXISTS(SELECT 1 FROM inventory_inspections failed
   JOIN mfg_wo_operations operation ON operation.org_id=failed.org_id AND operation.id=failed.rework_operation_id
   JOIN mfg_wo_operations original ON original.org_id=failed.org_id AND original.id=failed.operation_id
   WHERE failed.org_id=NEW.org_id AND failed.work_order_id=NEW.work_order_id AND failed.status='fail' AND failed.disposition='rework'
     AND operation.id=NEW.id AND operation.work_order_id=work.id AND operation.quantity_planned=failed.quantity
     AND operation.work_center_id=original.work_center_id AND operation.inspection_plan_snapshot=failed.plan_snapshot
     AND operation.backflush_at='none' AND operation.labor_time_source=original.labor_time_source
     AND (to_jsonb(operation)-ARRAY['id','sequence','name','quantity_planned','backflush_at','status','quantity_done','quantity_scrapped_here','measured_qty','actual_setup_minutes','actual_run_minutes','actual_labor_minutes','operator_user_id','started_at','completed_at','pause_reason','created_at','created_by','updated_at','updated_by'])
       =(to_jsonb(original)-ARRAY['id','sequence','name','quantity_planned','backflush_at','status','quantity_done','quantity_scrapped_here','measured_qty','actual_setup_minutes','actual_run_minutes','actual_labor_minutes','operator_user_id','started_at','completed_at','pause_reason','created_at','created_by','updated_at','updated_by'])) THEN RETURN NULL; END IF;
 RAISE EXCEPTION 'A released production definition accepts new operations only through its recorded inspection rework disposition.' USING ERRCODE='23514';
END $$;


--
-- Name: manufacturing_snapshot_configuration_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manufacturing_snapshot_configuration_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE mutable_fields text[];
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Released production snapshots cannot be deleted.' USING ERRCODE='23514'; END IF;
 mutable_fields:=CASE TG_TABLE_NAME
  WHEN 'mfg_wo_operations' THEN ARRAY['status','quantity_done','quantity_scrapped_here','measured_qty','actual_setup_minutes','actual_run_minutes','actual_labor_minutes','operator_user_id','started_at','completed_at','pause_reason','updated_at','updated_by']
  WHEN 'mfg_wo_materials' THEN ARRAY['issued_qty','backflush_qty','waived_at','waived_by','waive_reason','updated_at','updated_by']
  ELSE ARRAY['updated_at','updated_by'] END;
 IF (to_jsonb(NEW)-mutable_fields) IS DISTINCT FROM (to_jsonb(OLD)-mutable_fields) THEN
  RAISE EXCEPTION 'Released operations keep their labor, material, output and revision configuration.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: mfg_scrap_snapshot_immutable_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mfg_scrap_snapshot_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (NEW.work_order_id IS DISTINCT FROM OLD.work_order_id)
    OR (NEW.operation_id IS DISTINCT FROM OLD.operation_id)
    OR (NEW.component_item_id IS DISTINCT FROM OLD.component_item_id)
    OR (NEW.quantity IS DISTINCT FROM OLD.quantity)
    OR (NEW.reason_id IS DISTINCT FROM OLD.reason_id)
    OR (NEW.classification IS DISTINCT FROM OLD.classification)
  THEN
    RAISE EXCEPTION 'scrap event % for work order % carries frozen lineage that cannot be re-pointed; file a new event instead', NEW.id, NEW.work_order_id
      USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.treatment IS NOT NULL OR NEW.treatment IS NULL THEN
    IF (NEW.treatment IS DISTINCT FROM OLD.treatment)
      OR (NEW.frozen_value IS DISTINCT FROM OLD.frozen_value)
      OR (NEW.frozen_unit_cost IS DISTINCT FROM OLD.frozen_unit_cost)
      OR (NEW.lot_id IS DISTINCT FROM OLD.lot_id)
      OR (NEW.serial_id IS DISTINCT FROM OLD.serial_id)
      OR (NEW.plan_fingerprint IS DISTINCT FROM OLD.plan_fingerprint)
      OR (NEW.approval_required IS DISTINCT FROM OLD.approval_required)
    THEN
      RAISE EXCEPTION 'scrap event % for work order % carries a frozen valuation snapshot that cannot be rewritten; normalize a legacy event only through a controlled restatement proposal', NEW.id, NEW.work_order_id
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF OLD.posted_entry_id IS NOT NULL
    AND NEW.posted_entry_id IS DISTINCT FROM OLD.posted_entry_id
  THEN
    RAISE EXCEPTION 'scrap event % is already linked to posted entry %; posting linkage cannot be rewritten or cleared, correct through reversal or an adjusting entry', NEW.id, OLD.posted_entry_id
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: mfg_wo_snapshot_immutable_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mfg_wo_snapshot_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (NEW.standard_labor_wage_id IS DISTINCT FROM OLD.standard_labor_wage_id)
    OR (NEW.standard_labor_effective_from IS DISTINCT FROM OLD.standard_labor_effective_from)
    OR (NEW.standard_labor_rate IS DISTINCT FROM OLD.standard_labor_rate)
    OR (NEW.standard_labor_currency IS DISTINCT FROM OLD.standard_labor_currency)
    OR (NEW.standard_labor_basis IS DISTINCT FROM OLD.standard_labor_basis)
    OR (NEW.standard_labor_annual_hours IS DISTINCT FROM OLD.standard_labor_annual_hours)
    OR (NEW.standard_labor_final_rate IS DISTINCT FROM OLD.standard_labor_final_rate)
    OR (NEW.standard_labor_functional_currency IS DISTINCT FROM OLD.standard_labor_functional_currency)
    OR (NEW.standard_labor_burden IS DISTINCT FROM OLD.standard_labor_burden)
    OR (NEW.standard_labor_burden_hash IS DISTINCT FROM OLD.standard_labor_burden_hash)
    OR (NEW.standard_labor_fx_class IS DISTINCT FROM OLD.standard_labor_fx_class)
    OR (NEW.standard_labor_fx_rate IS DISTINCT FROM OLD.standard_labor_fx_rate)
    OR (NEW.standard_labor_fx_row_id IS DISTINCT FROM OLD.standard_labor_fx_row_id)
    OR (NEW.standard_labor_fx_date IS DISTINCT FROM OLD.standard_labor_fx_date)
    OR (NEW.standard_labor_fx_source IS DISTINCT FROM OLD.standard_labor_fx_source)
    OR (NEW.standard_labor_fx_direction IS DISTINCT FROM OLD.standard_labor_fx_direction)
    OR (NEW.overhead_snapshot IS DISTINCT FROM OLD.overhead_snapshot)
    OR (NEW.overhead_snapshot_hash IS DISTINCT FROM OLD.overhead_snapshot_hash)
  THEN
    RAISE EXCEPTION 'operation % for work order % carries release-frozen snapshots that cannot be rewritten; correct through reversal or an adjusting entry', NEW.id, NEW.work_order_id
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: multibook_evidence_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.multibook_evidence_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;
  IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'Multi-book replication evidence is append-only history'
    USING ERRCODE = '23514';
END;
$$;


--
-- Name: native_command_approval_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.native_command_approval_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE dependencies jsonb; command jsonb; fingerprint text; approval_statuses text[]:=string_to_array(TG_ARGV[1],'|'); subject_kind text:=TG_ARGV[0]; released_fields text[]:=ARRAY['status','updated_at','updated_by','approved_at','approved_by'];
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' THEN
  IF (to_jsonb(NEW)->>'status')=ANY(approval_statuses) THEN RAISE EXCEPTION 'Create a native draft before submitting its approval command through Flows.'; END IF;
  RETURN NEW;
 END IF;
 IF NOT coalesce((to_jsonb(NEW)->>'status')=ANY(approval_statuses),false) OR coalesce((to_jsonb(OLD)->>'status')=ANY(approval_statuses),false) THEN RETURN NEW; END IF;
 -- Restoring a settled claim retains its original approval and immutable stamp.
 IF TG_ARGV[0]='rebate_claim' AND to_jsonb(OLD)->>'status'='settled'
  AND to_jsonb(OLD)->>'approved_at' IS NOT NULL AND jsonb_build_array(to_jsonb(NEW)->'approved_at',to_jsonb(NEW)->'approved_by') IS NOT DISTINCT FROM jsonb_build_array(to_jsonb(OLD)->'approved_at',to_jsonb(OLD)->'approved_by') THEN RETURN NEW; END IF;
 IF TG_ARGV[0] IN('customer_change_order','subcontract_change_order') THEN released_fields:=released_fields||ARRAY['approved_on']; END IF;
 IF TG_ARGV[0]='bank_reconciliation_sign_off' THEN released_fields:=released_fields||ARRAY['signed_off_at','signed_off_by']; END IF;
 IF TG_ARGV[0]='headcount_plan_line' THEN released_fields:=released_fields||ARRAY['revision','requisition_id','reason']; END IF;
 IF TG_ARGV[0]='headcount_plan' THEN released_fields:=released_fields||ARRAY['revision']; END IF;
 IF TG_ARGV[0]='compensation_cycle_line' THEN released_fields:=released_fields||ARRAY['revision','approver_party_id','decided_at','reason']; END IF;
 -- Stored generated projections are computed after BEFORE triggers. Their
 -- base columns remain sealed; derived values cannot be supplied by a write.
 SELECT released_fields||coalesce(array_agg(a.attname::text),ARRAY[]::text[])
   INTO released_fields FROM pg_catalog.pg_attribute a
  WHERE a.attrelid=TG_RELID AND a.attnum>0 AND NOT a.attisdropped AND a.attgenerated<>'';
 -- Releasing a generated bill or invoice restores the existing approved
 -- economic terms; it neither makes a new decision nor changes its evidence.
 IF subject_kind IN('customer_pay_application','vendor_pay_application')
  AND to_jsonb(NEW)->>'status'='approved'
  AND to_jsonb(OLD)->>'status'=ANY(CASE WHEN subject_kind='customer_pay_application' THEN ARRAY['invoiced','posted'] ELSE ARRAY['billed'] END) THEN
  DECLARE document_column text:=CASE WHEN subject_kind='customer_pay_application' THEN 'invoice_document_id' ELSE 'vendor_bill_document_id' END;
          source_document uuid; original_decider uuid;
  BEGIN
   source_document:=(to_jsonb(OLD)->>document_column)::uuid;
   original_decider:=(to_jsonb(OLD)->>'approved_by')::uuid;
   IF source_document IS NULL OR original_decider IS NULL OR to_jsonb(OLD)->>'approved_at' IS NULL
    OR to_jsonb(NEW)->>document_column IS NOT NULL OR to_jsonb(NEW)->>'updated_by' IS NULL
    OR (to_jsonb(NEW)-ARRAY['status','updated_at','updated_by',document_column])
       IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','updated_at','updated_by',document_column]) THEN
    RAISE EXCEPTION 'Releasing billing cannot change approved payment application terms. Review the current application and submit changed terms through Flows.' USING ERRCODE='23514';
   END IF;
   IF NOT EXISTS(SELECT 1 FROM public.documents d WHERE d.org_id=OLD.org_id AND d.id=source_document
     AND d.kind=CASE WHEN subject_kind='customer_pay_application' THEN 'customer_invoice' ELSE 'vendor_bill' END
     AND ((d.status='draft' AND d.posted_entry_id IS NULL)
       OR (d.status='posted' AND d.void_requested_at IS NOT NULL AND d.void_reason IS NOT NULL
         AND d.void_requested_by::text=to_jsonb(NEW)->>'updated_by'
         AND EXISTS(SELECT 1 FROM public.journal_entries original WHERE original.org_id=d.org_id
           AND original.id=d.posted_entry_id AND original.status='reversed'
           AND EXISTS(SELECT 1 FROM public.journal_entries reversal WHERE reversal.org_id=original.org_id
             AND reversal.reverses_entry_id=original.id AND reversal.status='posted'))))) THEN
    RAISE EXCEPTION 'Discard the draft or complete the native invoice or bill reversal before releasing its payment application.' USING ERRCODE='23514';
   END IF;
   IF subject_kind='customer_pay_application' THEN
    SELECT coalesce(jsonb_agg(to_jsonb(l) ORDER BY l.id),'[]'::jsonb) INTO dependencies FROM public.pay_application_lines l WHERE l.org_id=OLD.org_id AND l.pay_application_id=OLD.id;
   ELSE
    SELECT coalesce(jsonb_agg(to_jsonb(l) ORDER BY l.id),'[]'::jsonb) INTO dependencies FROM public.vendor_pay_application_lines l WHERE l.org_id=OLD.org_id AND l.pay_application_id=OLD.id;
   END IF;
   fingerprint:=public.flow_command_record_fingerprint(to_jsonb(NEW),dependencies);
   IF NOT public.flow_subject_decision_authorized(NEW.org_id,subject_kind,NEW.id,original_decider,fingerprint,'approved') THEN
    RAISE EXCEPTION 'The payment application has no retained approval for these exact terms. Review and resubmit it through Flows.' USING ERRCODE='23514';
   END IF;
   RETURN NEW;
  END;
 END IF;
 IF (to_jsonb(NEW)-released_fields) IS DISTINCT FROM (to_jsonb(OLD)-released_fields) THEN
  RAISE EXCEPTION 'A Flow decision cannot replace the submitted record terms.';
 END IF;
 CASE TG_ARGV[0]
  WHEN 'bank_reconciliation_sign_off' THEN dependencies:=public.reconciliation_approval_dependencies(OLD.org_id,OLD.id);
  WHEN 'customer_change_order' THEN
    SELECT jsonb_build_object('contractValue',(SELECT p.contract_value::text FROM projects p WHERE p.org_id=OLD.org_id AND p.id=OLD.project_id),
      'schedule',(SELECT coalesce(jsonb_agg(to_jsonb(l) ORDER BY l.id),'[]'::jsonb) FROM sov_lines l WHERE l.org_id=OLD.org_id AND l.project_id=OLD.project_id)) INTO dependencies;
    command:=jsonb_build_object('approvedOn',NEW.approved_on::text);
  WHEN 'headcount_plan_line' THEN dependencies:=NULL;
  WHEN 'headcount_plan' THEN SELECT coalesce(jsonb_agg(to_jsonb(l) ORDER BY l.id),'[]'::jsonb) INTO dependencies FROM hrm_headcount_plan_lines l WHERE l.org_id=OLD.org_id AND l.plan_id=OLD.id;
  WHEN 'compensation_cycle_line' THEN dependencies:=NULL;
  WHEN 'per_diem_entry' THEN dependencies:=NULL;
  WHEN 'travel_pay_entry' THEN dependencies:=NULL;
  WHEN 'sandbox_change_set' THEN SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY i.id),'[]'::jsonb) INTO dependencies FROM change_set_items i WHERE i.org_id=OLD.org_id AND i.change_set_id=OLD.id;
  WHEN 'rebate_agreement' THEN dependencies:=NULL;
  WHEN 'rebate_claim' THEN SELECT to_jsonb(a) INTO dependencies FROM rebate_agreements a WHERE a.org_id=OLD.org_id AND a.id=OLD.agreement_id;
  WHEN 'subcontract' THEN SELECT coalesce(jsonb_agg(to_jsonb(l) ORDER BY l.id),'[]'::jsonb) INTO dependencies FROM subcontract_sov_lines l WHERE l.org_id=OLD.org_id AND l.subcontract_id=OLD.id;
  WHEN 'subcontract_change_order' THEN dependencies:=public.subcontract_change_approval_dependencies(OLD.org_id,OLD.subcontract_id);command:=jsonb_build_object('approvedOn',NEW.approved_on::text);
  WHEN 'vendor_pay_application' THEN SELECT coalesce(jsonb_agg(to_jsonb(l) ORDER BY l.id),'[]'::jsonb) INTO dependencies FROM vendor_pay_application_lines l WHERE l.org_id=OLD.org_id AND l.pay_application_id=OLD.id;
  WHEN 'customer_pay_application' THEN SELECT coalesce(jsonb_agg(to_jsonb(l) ORDER BY l.id),'[]'::jsonb) INTO dependencies FROM pay_application_lines l WHERE l.org_id=OLD.org_id AND l.pay_application_id=OLD.id;
  ELSE RAISE EXCEPTION 'This native command has no registered approval evidence contract.';
 END CASE;
 IF subject_kind='rebate_agreement' THEN subject_kind:=OLD.side||'_rebate_agreement';
 ELSIF subject_kind='rebate_claim' THEN subject_kind:=(dependencies->>'side')||'_rebate_claim'; END IF;
 fingerprint:=public.flow_command_record_fingerprint(to_jsonb(OLD),dependencies);
 IF NOT public.flow_command_authorized(NEW.org_id,subject_kind,NEW.id,coalesce(to_jsonb(NEW)->>'approved_by',to_jsonb(NEW)->>'updated_by')::uuid,fingerprint,command) THEN
  RAISE EXCEPTION 'Complete native tenant Flow routing for this exact record and command before release.';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: native_command_pending_terms_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.native_command_pending_terms_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE before_row jsonb; after_row jsonb; candidate jsonb; subject_key uuid; organization uuid;
BEGIN
 IF TG_OP='DELETE' THEN
  IF tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD))
    OR public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 END IF;
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP<>'INSERT' THEN before_row:=to_jsonb(OLD); END IF;
 IF TG_OP<>'DELETE' THEN after_row:=to_jsonb(NEW); END IF;
 IF TG_OP='UPDATE' AND (after_row-ARRAY['updated_at','updated_by']) IS NOT DISTINCT FROM
   (before_row-ARRAY['updated_at','updated_by']) THEN RETURN NEW; END IF;
 -- Both old and new ownership matter when a child is moved between parents.
 FOR candidate IN SELECT value FROM jsonb_array_elements(jsonb_build_array(before_row,after_row)) WHERE value<>'null'::jsonb LOOP
  organization:=(candidate->>'org_id')::uuid;
  subject_key:=coalesce((candidate->>nullif(TG_ARGV[1],''))::uuid,(candidate->>'id')::uuid);
  IF EXISTS(SELECT 1 FROM public.flow_gates g JOIN public.flow_runs r ON r.org_id=g.org_id AND r.id=g.run_id
    WHERE g.org_id=organization AND g.subject_kind=ANY(string_to_array(TG_ARGV[0],'|')) AND g.subject_id=subject_key
      AND r.context ? 'command' AND g.status IN('pending','escalated')) THEN
   RAISE EXCEPTION 'Recall the pending native Flow submission before changing these terms.';
  END IF;
 END LOOP;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END
$$;


--
-- Name: native_request_flow_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.native_request_flow_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE kind text:=TG_ARGV[0];fingerprint text; allowed text[]:=ARRAY['status','flow_instance_id','decided_by','decided_at','decision_reason','decision_comment','updated_at','updated_by'];
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'draft' THEN RAISE EXCEPTION 'File a draft request before native submission.'; END IF;
  RETURN NEW;
 END IF;
 IF OLD.status<>'draft' AND (to_jsonb(NEW)-allowed) IS DISTINCT FROM (to_jsonb(OLD)-allowed) THEN
  RAISE EXCEPTION 'Submitted request terms are immutable. Cancel or withdraw the request and file the replacement.';
 END IF;
 IF kind='hrm_leave_request' THEN fingerprint:=public.flow_command_record_fingerprint(to_jsonb(OLD)-ARRAY['flow_instance_id','decided_by','decided_at','decision_reason']);
 ELSE fingerprint:=public.flow_command_record_fingerprint(to_jsonb(OLD)-ARRAY['flow_instance_id','decided_by','decided_at','decision_comment']); END IF;
 IF OLD.status='draft' AND NEW.status='submitted' THEN
  IF NOT EXISTS(SELECT 1 FROM public.flow_submissions s WHERE s.org_id=NEW.org_id AND s.subject_kind=kind AND s.subject_id=NEW.id
    AND s.actor_id=NEW.updated_by AND s.context->>'approvalFingerprint'=fingerprint
    AND NOT EXISTS(SELECT 1 FROM public.flow_submissions newer WHERE newer.org_id=s.org_id AND newer.subject_kind=s.subject_kind
      AND newer.subject_id=s.subject_id AND (newer.created_at,newer.id)>(s.created_at,s.id))) THEN
   RAISE EXCEPTION 'Submit the exact request through native Flow routing.';
  END IF;
 END IF;
 IF NEW.status IN('approved','rejected') AND NEW.status IS DISTINCT FROM OLD.status THEN
  IF OLD.status<>'submitted' OR NOT public.flow_subject_decision_authorized(NEW.org_id,kind,NEW.id,NEW.updated_by,fingerprint,NEW.status) THEN
   RAISE EXCEPTION 'Complete this request through its current native Flow submission.';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: net_investment_configuration_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.net_investment_configuration_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF public.app_bypass_rls_active() AND coalesce(current_setting('openbooks.amend',true),'off')='on' THEN
    IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
  END IF;
  IF TG_TABLE_NAME='subsidiary_ownership_interests' THEN
    IF EXISTS(SELECT 1 FROM public.net_investment_entries c WHERE c.org_id=OLD.org_id AND c.interest_id=OLD.id) AND
      (TG_OP='DELETE' OR (NEW.subsidiary_id,NEW.parent_subsidiary_id,NEW.method,NEW.ownership_percent,NEW.effective_from)
        IS DISTINCT FROM (OLD.subsidiary_id,OLD.parent_subsidiary_id,OLD.method,OLD.ownership_percent,OLD.effective_from)
       OR (NEW.effective_to IS DISTINCT FROM OLD.effective_to AND NOT EXISTS(SELECT 1 FROM public.financial_changes f
         WHERE f.org_id=OLD.org_id AND f.id=NEW.last_change_id AND f.subject_id=OLD.id AND f.domain='consolidation'
           AND f.status='approved' AND f.operation IN('loss_of_control','reversal'))))
      THEN RAISE EXCEPTION 'used net-investment ownership identity is immutable; use the controlled loss-of-control workflow to close its reporting window'; END IF;
  ELSIF TG_TABLE_NAME='intercompany_pairs' THEN
    IF EXISTS(SELECT 1 FROM public.net_investment_entries c JOIN public.financial_changes f ON f.org_id=c.org_id AND f.id=c.change_id
      WHERE c.org_id=OLD.org_id AND f.payload->>'pairId'=OLD.id::text) AND
      (TG_OP='DELETE' OR (NEW.from_subsidiary_id,NEW.to_subsidiary_id,NEW.due_from_account_id,NEW.due_to_account_id)
        IS DISTINCT FROM (OLD.from_subsidiary_id,OLD.to_subsidiary_id,OLD.due_from_account_id,OLD.due_to_account_id))
      THEN RAISE EXCEPTION 'used net-investment loan pairing is immutable; configure a new pair for a changed financing arrangement'; END IF;
  ELSIF TG_TABLE_NAME='consolidated_fx_rates' THEN
    IF (TG_OP='DELETE' OR NEW.average_rate IS DISTINCT FROM OLD.average_rate) AND EXISTS(
      SELECT 1 FROM public.net_investment_entries c JOIN public.financial_changes f ON f.org_id=c.org_id AND f.id=c.change_id,
        jsonb_array_elements(f.before_state->'sources') source,
        jsonb_array_elements(f.before_state->'entities') holder
      WHERE c.org_id=OLD.org_id AND c.period_id=OLD.period_id AND c.reversed_by_change_id IS NULL
        AND holder->>'id'=source->>'subsidiary_id' AND holder->>'base_currency'=OLD.from_currency
        AND f.before_state->'elimination'->>'base_currency'=OLD.to_currency)
      THEN RAISE EXCEPTION 'the average rate supports an approved net-investment OCI assessment; reverse that assessment through Accounting changes before correcting its translation rate'; END IF;
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;


--
-- Name: net_investment_evidence_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.net_investment_evidence_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP<>'INSERT' THEN
    IF public.app_bypass_rls_active() AND coalesce(current_setting('openbooks.amend',true),'off')='on' THEN
      IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
    END IF;
    IF TG_OP='UPDATE' AND OLD.reversed_by_change_id IS NULL AND NEW.reversed_by_change_id IS NOT NULL
      AND (to_jsonb(NEW)-'reversed_by_change_id') IS NOT DISTINCT FROM (to_jsonb(OLD)-'reversed_by_change_id')
      AND EXISTS(SELECT 1 FROM public.financial_changes f WHERE f.org_id=OLD.org_id AND f.id=NEW.reversed_by_change_id
        AND f.domain='consolidation' AND f.operation='net_investment_oci_reversal' AND f.status='approved'
        AND f.payload->>'sourceChangeId'=OLD.change_id::text) THEN RETURN NEW; END IF;
    RAISE EXCEPTION 'net-investment evidence is immutable; use its independently approved correction in Accounting changes';
  END IF;
  IF TG_TABLE_NAME='net_investment_entries' THEN
    IF NOT EXISTS(SELECT 1 FROM public.financial_changes f JOIN public.subsidiary_ownership_interests i ON i.org_id=f.org_id AND i.id=f.subject_id
      JOIN public.accounting_books b ON b.org_id=f.org_id AND b.id=NEW.book_id
      JOIN public.accounting_periods p ON p.org_id=b.org_id AND p.id=NEW.period_id
      JOIN public.subsidiaries e ON e.org_id=f.org_id AND e.id=NEW.elimination_subsidiary_id AND e.is_elimination
      WHERE f.org_id=NEW.org_id AND f.id=NEW.change_id AND f.domain='consolidation' AND f.operation='net_investment_oci' AND f.status='approved'
        AND f.subject_id=NEW.interest_id AND f.subsidiary_id=e.id AND f.payload->>'bookId'=b.id::text
        AND f.effective_on BETWEEN p.starts_on AND p.ends_on)
      OR (NEW.journal_entry_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.journal_entries e
        WHERE e.org_id=NEW.org_id AND e.id=NEW.journal_entry_id AND e.book_id=NEW.book_id AND e.period_id=NEW.period_id
          AND e.subsidiary_id=NEW.elimination_subsidiary_id AND e.status='posted' AND e.origin='net_investment_oci'))
      THEN RAISE EXCEPTION 'net-investment journal must bind to its approved ownership, book, period and elimination entity'; END IF;
  ELSE
    IF NOT EXISTS(SELECT 1 FROM public.net_investment_entries c JOIN public.financial_changes f ON f.org_id=c.org_id AND f.id=c.change_id
      JOIN public.journal_lines l ON l.org_id=c.org_id AND l.id=NEW.source_line_id
      JOIN public.journal_entries e ON e.org_id=l.org_id AND e.id=l.entry_id
      WHERE c.org_id=NEW.org_id AND c.change_id=NEW.change_id AND f.status='approved' AND e.origin='fx_revaluation'
        AND e.book_id=c.book_id AND e.period_id=c.period_id AND e.status IN('posted','reversed') AND l.amount=NEW.amount
        AND EXISTS(SELECT 1 FROM jsonb_array_elements(f.before_state->'sources') proof
          WHERE proof->>'id'=NEW.source_line_id::text AND (proof->>'translated')::numeric=NEW.translated_amount
            AND (proof->>'averageRate')::numeric=NEW.average_rate))
      THEN RAISE EXCEPTION 'net-investment source must match the independently approved native FX evidence'; END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: nonprofit_frameworks_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nonprofit_frameworks_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_line_count bigint;
  v_org_id uuid;
begin
  IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  if tg_op = 'DELETE' and pg_catalog.pg_trigger_depth() > 1 then
    return old;
  end if;

  v_org_id := case when tg_op = 'DELETE' then old.org_id else new.org_id end;
  if tg_op = 'UPDATE' and new.org_id is distinct from old.org_id then
    raise exception 'a nonprofit framework cannot be moved to another organization'
      using errcode = '23514';
  end if;

  -- Fund line inserts use the same transaction lock, so a framework change
  -- cannot pass its history check while a fund posting is still in flight.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('openbooks:nonprofit-framework:' || v_org_id::text, 0)
  );

  if tg_op = 'DELETE' or (tg_op = 'UPDATE' and new.framework is distinct from old.framework) then
    select count(*) into v_line_count
      from public.journal_lines jl
      join public.journal_entries je
        on je.org_id = jl.org_id and je.id = jl.entry_id
     where jl.org_id = v_org_id
       and jl.extra_dims ? 'fund'
       and je.status is distinct from 'draft';
    if v_line_count > 0 then
      raise exception 'nonprofit framework cannot change or be removed while % posted fund-tagged journal lines exist; continue with the current framework or use a separate organization',
        v_line_count
        using errcode = '23514',
              constraint = 'nonprofit_frameworks_history_guard';
    end if;
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end $$;


--
-- Name: normalization_request_flow_authorized(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalization_request_flow_authorized(organization uuid, subject uuid, actor uuid, outcome text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 SELECT EXISTS(SELECT 1 FROM public.saas_metrics_normalization_requests q WHERE q.org_id=organization AND q.id=subject AND (
   (outcome='approved' AND actor=q.requested_by AND public.flow_ungated_submission_authorized(organization,'metrics_normalization',subject,actor,
     jsonb_build_object('requestHash',q.request_hash)))
   OR (EXISTS(SELECT 1 FROM public.flow_gates g JOIN public.flow_runs r ON r.org_id=g.org_id AND r.id=g.run_id
     WHERE g.org_id=organization AND g.subject_kind='metrics_normalization' AND g.subject_id=subject AND g.status=outcome
       AND g.decided_by=actor AND r.context->>'requestHash'=q.request_hash
       AND r.context->'submissionPolicy'->>'flowId'=r.flow_id::text
       AND (actor<>q.requested_by OR EXISTS(
         SELECT 1 FROM jsonb_array_elements(r.context->'submissionPolicy'->'graph'->'nodes') node
          WHERE node->>'id'=g.node_id AND node->'data'->>'kind'='gate'
           AND node->'data'->'gate'->'preventSelfApproval'='false'::jsonb)))
     AND NOT EXISTS(SELECT 1 FROM public.flow_gates g WHERE g.org_id=organization
       AND g.subject_kind='metrics_normalization' AND g.subject_id=subject AND g.status IN('pending','escalated')))))
$$;


--
-- Name: number_sequences_allocation_watermark(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.number_sequences_allocation_watermark() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.allocated_through := GREATEST(NEW.allocated_through, NEW.next_number);
  RETURN NEW;
END
$$;


--
-- Name: FUNCTION number_sequences_allocation_watermark(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.number_sequences_allocation_watermark() IS 'openbooks:document_number_watermark:v1 - every counter advance raises the allocation watermark';


--
-- Name: number_sequences_monotonic_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.number_sequences_monotonic_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.allocated_through > 0 THEN
    IF NEW.next_number < OLD.allocated_through THEN
      RAISE EXCEPTION
        'document sequence % for kind % has already allocated through %; a used counter cannot move backward — advance it forward instead',
        OLD.prefix, OLD.document_kind, OLD.allocated_through;
    END IF;
    IF NEW.prefix IS DISTINCT FROM OLD.prefix
       OR NEW.padding IS DISTINCT FROM OLD.padding
       OR NEW.document_kind IS DISTINCT FROM OLD.document_kind THEN
      RAISE EXCEPTION
        'document sequence % for kind % has already issued numbers; its prefix, padding and kind are frozen once used',
        OLD.prefix, OLD.document_kind;
    END IF;
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: FUNCTION number_sequences_monotonic_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.number_sequences_monotonic_guard() IS 'openbooks:document_number_monotonic_guard:v1 - a used sequence cannot decrease into an occupied output range or change the format it issued; applies to setup edits, imports and direct writes alike';


--
-- Name: ob_rebase(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ob_rebase(old uuid, seed uuid) RETURNS uuid
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
    select md5(seed::text || ':' || old::text)::uuid
$$;


--
-- Name: hrm_offers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hrm_offers (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    application_id uuid NOT NULL,
    position_id uuid,
    employer_subsidiary_id uuid NOT NULL,
    department_id uuid,
    job_title text NOT NULL,
    employment_kind text,
    proposed_start_on date NOT NULL,
    compensation_amount numeric NOT NULL,
    compensation_currency character(3) NOT NULL,
    compensation_basis text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    sent_at timestamp with time zone,
    expires_on date,
    responded_at timestamp with time zone,
    decline_reason text,
    approved_change_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    template_id uuid,
    version integer DEFAULT 1 NOT NULL,
    rendered_file_id uuid,
    signature_status text,
    signed_at timestamp with time zone,
    signed_evidence jsonb,
    signing_token_hash text,
    approval_status text DEFAULT 'none'::text NOT NULL,
    approval_version integer,
    submitted_by uuid,
    submission_policy jsonb,
    CONSTRAINT hrm_offers_approval_status_check CHECK ((approval_status = ANY (ARRAY['none'::text, 'pending'::text, 'approved'::text, 'rejected'::text]))),
    CONSTRAINT hrm_offers_approved_change_paired CHECK (((status = 'accepted'::text) = (approved_change_id IS NOT NULL))),
    CONSTRAINT hrm_offers_compensation_amount CHECK ((compensation_amount > (0)::numeric)),
    CONSTRAINT hrm_offers_compensation_basis CHECK ((compensation_basis = ANY (ARRAY['hourly'::text, 'annual'::text]))),
    CONSTRAINT hrm_offers_decline_reason CHECK (((status = 'declined'::text) = ((decline_reason IS NOT NULL) AND (char_length(btrim(decline_reason)) > 0)))),
    CONSTRAINT hrm_offers_employment_kind CHECK (((employment_kind IS NULL) OR (char_length(btrim(employment_kind)) > 0))),
    CONSTRAINT hrm_offers_finite_time CHECK (((proposed_start_on >= '0001-01-01'::date) AND (proposed_start_on <= '9999-12-31'::date) AND ((expires_on IS NULL) OR ((expires_on >= '0001-01-01'::date) AND (expires_on <= '9999-12-31'::date))) AND ((sent_at IS NULL) OR ((sent_at >= '0001-01-01 00:00:00+00'::timestamp with time zone) AND (sent_at < '10000-01-01 00:00:00+00'::timestamp with time zone))) AND ((responded_at IS NULL) OR ((responded_at >= '0001-01-01 00:00:00+00'::timestamp with time zone) AND (responded_at < '10000-01-01 00:00:00+00'::timestamp with time zone))))),
    CONSTRAINT hrm_offers_responded_paired CHECK (((status = ANY (ARRAY['accepted'::text, 'declined'::text])) = (responded_at IS NOT NULL))),
    CONSTRAINT hrm_offers_sent_paired CHECK (((status <> ALL (ARRAY['sent'::text, 'accepted'::text, 'declined'::text])) OR (sent_at IS NOT NULL))),
    CONSTRAINT hrm_offers_signature_status CHECK (((signature_status IS NULL) OR (signature_status = ANY (ARRAY['unsigned'::text, 'sent'::text, 'viewed'::text, 'signed'::text, 'declined'::text, 'voided'::text])))),
    CONSTRAINT hrm_offers_signed_finite CHECK (((signed_at IS NULL) OR ((signed_at >= '0001-01-01 00:00:00+00'::timestamp with time zone) AND (signed_at < '10000-01-01 00:00:00+00'::timestamp with time zone)))),
    CONSTRAINT hrm_offers_signed_paired CHECK (((signature_status = 'signed'::text) = ((signed_at IS NOT NULL) AND (signed_evidence IS NOT NULL)))),
    CONSTRAINT hrm_offers_status CHECK ((status = ANY (ARRAY['draft'::text, 'sent'::text, 'accepted'::text, 'declined'::text, 'withdrawn'::text, 'expired'::text]))),
    CONSTRAINT hrm_offers_title_not_blank CHECK ((char_length(btrim(job_title)) > 0)),
    CONSTRAINT hrm_offers_version CHECK ((version >= 1))
);

ALTER TABLE ONLY public.hrm_offers FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE hrm_offers; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.hrm_offers IS 'HRM proposed terms: at most one live offer per application (partial unique index), with send/respond evidence and the hire change request link. Terminal rows immutable; deletes only on the governed amend path.';


--
-- Name: offer_approval_fingerprint(public.hrm_offers); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.offer_approval_fingerprint(offer public.hrm_offers) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 SELECT encode(sha256(convert_to(jsonb_build_array(offer.id,offer.org_id,offer.application_id,offer.employer_subsidiary_id,
   offer.position_id,offer.department_id,offer.job_title,offer.employment_kind,offer.proposed_start_on::text,
   offer.compensation_amount::text,offer.compensation_currency,offer.compensation_basis,offer.expires_on::text,
   offer.version,offer.rendered_file_id,(SELECT v.payload FROM public.hrm_offer_versions v
    WHERE v.org_id=offer.org_id AND v.offer_id=offer.id AND v.version=offer.version))::text,'UTF8')),'hex')
$$;


--
-- Name: openbooks_bank_rule_criteria_is_valid(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_bank_rule_criteria_is_valid(value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    AS $_$
DECLARE
  account_id text;
BEGIN
  IF jsonb_typeof(value) <> 'object'
     OR value->>'version' <> '2'
     OR octet_length(value::text) > 100000
     OR NOT public.openbooks_bank_rule_group_is_valid(value->'match') THEN
    RETURN false;
  END IF;
  IF value ? 'accountScope' THEN
    IF jsonb_typeof(value->'accountScope') <> 'array' THEN
      RETURN false;
    END IF;
    FOR account_id IN SELECT entry FROM jsonb_array_elements_text(value->'accountScope') AS entries(entry)
    LOOP
      IF account_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RETURN false;
      END IF;
    END LOOP;
    IF (SELECT count(*) <> count(DISTINCT entry) FROM jsonb_array_elements_text(value->'accountScope') AS entries(entry)) THEN
      RETURN false;
    END IF;
  END IF;
  RETURN true;
EXCEPTION WHEN OTHERS THEN
  RETURN false;
END;
$_$;


--
-- Name: openbooks_bank_rule_group_is_valid(jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_bank_rule_group_is_valid(value jsonb, depth integer DEFAULT 0) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    AS $_$
DECLARE
  rule jsonb;
  field_name text;
  operator_name text;
  scalar_value text;
  numeric_value numeric;
  lower_bound numeric;
  upper_bound numeric;
BEGIN
  IF depth > 4
     OR jsonb_typeof(value) <> 'object'
     OR value->>'combinator' NOT IN ('and', 'or')
     OR jsonb_typeof(value->'rules') <> 'array'
     OR jsonb_array_length(value->'rules') NOT BETWEEN 1 AND 40 THEN
    RETURN false;
  END IF;

  FOR rule IN SELECT element FROM jsonb_array_elements(value->'rules') AS elements(element)
  LOOP
    IF jsonb_typeof(rule) <> 'object' THEN
      RETURN false;
    END IF;
    IF rule ? 'rules' THEN
      IF NOT public.openbooks_bank_rule_group_is_valid(rule, depth + 1) THEN
        RETURN false;
      END IF;
      CONTINUE;
    END IF;

    field_name := rule->>'field';
    operator_name := rule->>'op';
    scalar_value := rule->>'value';

    IF field_name IN ('description', 'payee', 'anyText', 'reference') THEN
      IF operator_name NOT IN ('contains', 'notContains', 'equals', 'startsWith', 'endsWith', 'isBlank')
         OR (operator_name <> 'isBlank' AND (jsonb_typeof(rule->'value') <> 'string' OR btrim(scalar_value) = '' OR length(scalar_value) > 200)) THEN
        RETURN false;
      END IF;
    ELSIF field_name = 'flow' THEN
      IF operator_name <> 'is' OR scalar_value NOT IN ('in', 'out', 'any') THEN
        RETURN false;
      END IF;
    ELSIF field_name = 'source' THEN
      IF operator_name <> 'equals' OR jsonb_typeof(rule->'value') <> 'string'
         OR btrim(scalar_value) = '' OR length(scalar_value) > 40 THEN
        RETURN false;
      END IF;
    ELSIF field_name = 'amount' THEN
      IF operator_name NOT IN ('eq', 'ne', 'gt', 'gte', 'lt', 'lte', 'between') THEN
        RETURN false;
      END IF;
      IF operator_name = 'between' THEN
        IF jsonb_typeof(rule->'value') <> 'array'
           OR jsonb_array_length(rule->'value') <> 2
           OR jsonb_typeof(rule->'value'->0) <> 'number'
           OR jsonb_typeof(rule->'value'->1) <> 'number' THEN
          RETURN false;
        END IF;
        lower_bound := (rule->'value'->>0)::numeric;
        upper_bound := (rule->'value'->>1)::numeric;
        IF lower_bound < 0 OR upper_bound < lower_bound THEN
          RETURN false;
        END IF;
      ELSE
        IF jsonb_typeof(rule->'value') <> 'number' THEN
          RETURN false;
        END IF;
        numeric_value := scalar_value::numeric;
        IF numeric_value < 0 THEN
          RETURN false;
        END IF;
      END IF;
    ELSIF field_name = 'date' THEN
      IF operator_name = 'withinDays' THEN
        IF jsonb_typeof(rule->'value') <> 'number' OR scalar_value::numeric <= 0 THEN
          RETURN false;
        END IF;
      ELSIF operator_name IN ('on', 'before', 'after') THEN
        IF jsonb_typeof(rule->'value') <> 'string'
           OR scalar_value !~ '^\d{4}-\d{2}-\d{2}$'
           OR to_char(scalar_value::date, 'YYYY-MM-DD') <> scalar_value THEN
          RETURN false;
        END IF;
      ELSE
        RETURN false;
      END IF;
    ELSE
      RETURN false;
    END IF;
  END LOOP;
  RETURN true;
EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow OR numeric_value_out_of_range THEN
  RETURN false;
END;
$_$;


--
-- Name: openbooks_bank_rule_outcome_is_valid(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_bank_rule_outcome_is_valid(value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    AS $_$
DECLARE
  line jsonb;
  portion jsonb;
  optional_id text;
  remainder_count integer := 0;
BEGIN
  IF jsonb_typeof(value) <> 'object' OR octet_length(value::text) > 100000 THEN
    RETURN false;
  END IF;
  IF value->>'action' = 'exclude' THEN
    RETURN value = '{"action":"exclude"}'::jsonb;
  END IF;
  IF value->>'action' <> 'categorize'
     OR value->>'version' <> '2'
     OR value->>'mode' NOT IN ('auto', 'suggest')
     OR jsonb_typeof(value->'lines') <> 'array'
     OR jsonb_array_length(value->'lines') NOT BETWEEN 1 AND 20 THEN
    RETURN false;
  END IF;

  IF value ? 'partyId' AND coalesce(value->>'partyId', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RETURN false;
  END IF;
  IF value ? 'memo' AND (jsonb_typeof(value->'memo') <> 'string' OR btrim(value->>'memo') = '' OR length(value->>'memo') > 300) THEN
    RETURN false;
  END IF;

  FOR line IN SELECT element FROM jsonb_array_elements(value->'lines') AS elements(element)
  LOOP
    IF jsonb_typeof(line) <> 'object'
       OR coalesce(line->>'accountId', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR jsonb_typeof(line->'portion') <> 'object' THEN
      RETURN false;
    END IF;
    portion := line->'portion';
    IF portion->>'kind' = 'remainder' THEN
      remainder_count := remainder_count + 1;
    ELSIF portion->>'kind' = 'percent' THEN
      IF jsonb_typeof(portion->'value') <> 'number'
         OR (portion->>'value')::numeric <= 0
         OR (portion->>'value')::numeric > 100 THEN
        RETURN false;
      END IF;
    ELSIF portion->>'kind' = 'fixed' THEN
      IF jsonb_typeof(portion->'value') <> 'number' OR (portion->>'value')::numeric <= 0 THEN
        RETURN false;
      END IF;
    ELSE
      RETURN false;
    END IF;

    FOREACH optional_id IN ARRAY ARRAY['partyId', 'departmentId', 'projectId', 'locationId', 'classId', 'taxCodeId']
    LOOP
      IF line ? optional_id
         AND coalesce(line->>optional_id, '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RETURN false;
      END IF;
    END LOOP;
    IF line ? 'description'
       AND (jsonb_typeof(line->'description') <> 'string' OR btrim(line->>'description') = '' OR length(line->>'description') > 200) THEN
      RETURN false;
    END IF;
  END LOOP;
  RETURN remainder_count <= 1;
EXCEPTION WHEN OTHERS THEN
  RETURN false;
END;
$_$;


--
-- Name: openbooks_bank_statement_line_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_bank_statement_line_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF tg_op = 'DELETE' THEN
    IF openbooks_sandbox_wipe_allowed(old.org_id) THEN
      RETURN old;
    END IF;
    -- Governed import deletion: the engine holds the account lock, rechecks
    -- the untouched-import fence, and writes the per-row and header audit in
    -- this same transaction.
    IF current_setting('app.statement_import_delete', true) = old.statement_id::text THEN
      RETURN old;
    END IF;
    RAISE EXCEPTION 'imported bank statement lines are immutable';
  END IF;
  IF tg_op = 'INSERT' THEN
    RETURN new;
  END IF;
  IF to_jsonb(new)
       - 'match_status' - 'exclusion_reason' - 'excluded_at' - 'excluded_by'
       - 'possible_duplicate_of'
       - 'updated_at' - 'updated_by'
     <> to_jsonb(old)
       - 'match_status' - 'exclusion_reason' - 'excluded_at' - 'excluded_by'
       - 'possible_duplicate_of'
       - 'updated_at' - 'updated_by' THEN
    -- Governed line correction: the engine holds the line lock, rechecks
    -- unmatched state and the signed-off cutoff, and writes the before/after
    -- audit row in this same transaction.
    IF current_setting('app.statement_correction_line', true) IS DISTINCT FROM old.id::text THEN
      RAISE EXCEPTION 'imported bank statement content is immutable';
    END IF;
  END IF;
  IF EXISTS (
    SELECT 1
      FROM reconciliation_matches m
      JOIN reconciliations r ON r.id = m.reconciliation_id
     WHERE m.statement_line_id = old.id
       AND m.org_id = old.org_id
       AND r.status = 'signed_off'
  ) OR EXISTS (
    SELECT 1
      FROM reconciliations r
     WHERE r.org_id = old.org_id
       AND r.account_id = old.account_id
       AND r.currency = old.currency
       AND r.status = 'signed_off'
       AND r.through_date >= old.posted_on
       AND old.match_status = 'excluded'
  ) THEN
    RAISE EXCEPTION 'signed-off bank statement evidence is immutable';
  END IF;
  IF new.match_status = 'matched'
     AND NOT EXISTS (
       SELECT 1 FROM reconciliation_matches m
        WHERE m.statement_line_id = new.id AND m.org_id = new.org_id
     ) THEN
    RAISE EXCEPTION 'matched bank statement line requires reconciliation-match evidence';
  END IF;
  IF new.match_status <> 'matched'
     AND EXISTS (
       SELECT 1 FROM reconciliation_matches m
        WHERE m.statement_line_id = new.id AND m.org_id = new.org_id
     ) THEN
    RAISE EXCEPTION 'bank statement line with match evidence must remain matched';
  END IF;
  RETURN new;
END;
$$;


--
-- Name: openbooks_bump_revision_seq(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_bump_revision_seq() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Every committed UPDATE is a new revision, even one that backdates the
  -- display timestamp: the counter only moves forward, so a stale
  -- revision-seq token can never compare equal against newer content.
  NEW.revision_seq := OLD.revision_seq + 1;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION openbooks_bump_revision_seq(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.openbooks_bump_revision_seq() IS 'openbooks:revision_seq:v1 - strictly increasing optimistic-concurrency counter; bumped on every UPDATE of a revisioned row (documents, wip_prebill_lines, ap_capture_items, custom_records, crm_opportunities), independent of the editable updated_at display timestamp';


--
-- Name: openbooks_clone_authority(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_clone_authority() RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select coalesce(current_setting('openbooks.clone', true), 'off') = 'on'
     and coalesce(current_setting('openbooks.migration', true), 'off') = 'on'
     and coalesce(current_setting('openbooks.amend', true), 'off') = 'on'
     and (public.app_bypass_rls_active()
          or exists (select 1
                       from pg_catalog.pg_roles
                      where rolname = current_user and rolbypassrls))
$$;


--
-- Name: FUNCTION openbooks_clone_authority(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.openbooks_clone_authority() IS 'True only inside the deterministic clone transaction: openbooks.clone, openbooks.migration and openbooks.amend asserted together with an unscoped maintenance context (public.app_bypass_rls_active() or a BYPASSRLS login). Guards honour it for INSERT of posted history only; it never permits UPDATE, DELETE, or tenant-transaction writes.';


--
-- Name: openbooks_connector_replay_authorized(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_connector_replay_authorized(p_org uuid, p_authorization uuid, p_period uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select exists (
    select 1
      from connector_replay_authorizations auth
      join accounting_periods from_period
        on from_period.id = auth.period_from_id
       and from_period.org_id = auth.org_id
      join accounting_periods to_period
        on to_period.id = auth.period_to_id
       and to_period.org_id = auth.org_id
      join accounting_periods target
        on target.id = p_period
       and target.org_id = p_org
     where auth.id = p_authorization
       and auth.org_id = p_org
       and auth.authorized_at <= now()
       and auth.expires_at > now()
       and target.starts_on >= least(from_period.starts_on, to_period.starts_on)
       and target.ends_on <= greatest(from_period.ends_on, to_period.ends_on)
  )
$$;


--
-- Name: FUNCTION openbooks_connector_replay_authorized(p_org uuid, p_authorization uuid, p_period uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.openbooks_connector_replay_authorized(p_org uuid, p_authorization uuid, p_period uuid) IS 'Live-grant check for closed-period connector replay: the named connector_replay_authorizations row belongs to the posting organization, its window is open, and its period range covers the entry period. Fail-closed: anything else is false.';


--
-- Name: openbooks_default_budget_subsidiary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_default_budget_subsidiary() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.subsidiary_id IS NULL THEN
    SELECT s.id
      INTO NEW.subsidiary_id
      FROM public.subsidiaries s
     WHERE s.org_id = NEW.org_id
       AND s.parent_id IS NULL
       AND s.is_active
       AND NOT s.is_elimination
     ORDER BY s.created_at, s.id
     LIMIT 1;
    IF NEW.subsidiary_id IS NULL THEN
      RAISE EXCEPTION 'budget line requires an active root subsidiary for organization %', NEW.org_id
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION openbooks_default_budget_subsidiary(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.openbooks_default_budget_subsidiary() IS 'openbooks:budget_subsidiary:v1 - resolves legacy omitted budget entities to the tenant root before the not-null and tenant-coherent FK checks';


--
-- Name: openbooks_gl_activity_apply(uuid, uuid, date, uuid, numeric, numeric, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_gl_activity_apply(p_org uuid, p_account uuid, p_month date, p_subsidiary uuid, p_debit numeric, p_credit numeric, p_count bigint) RETURNS void
    LANGUAGE sql
    AS $$
  insert into gl_month_activity as g (org_id, account_id, month, subsidiary_id, debit_total, credit_total, line_count)
  values (p_org, p_account, p_month, p_subsidiary, p_debit, p_credit, p_count)
  on conflict (org_id, account_id, month, subsidiary_id) do update
    set debit_total = g.debit_total + excluded.debit_total,
        credit_total = g.credit_total + excluded.credit_total,
        line_count = g.line_count + excluded.line_count;
$$;


--
-- Name: openbooks_gl_activity_apply(uuid, uuid, uuid, date, uuid, numeric, numeric, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_gl_activity_apply(p_org uuid, p_account uuid, p_book uuid, p_month date, p_subsidiary uuid, p_debit numeric, p_credit numeric, p_count bigint) RETURNS void
    LANGUAGE sql
    AS $$
  insert into gl_month_activity as g (org_id, account_id, book_id, month, subsidiary_id, debit_total, credit_total, line_count)
  values (p_org, p_account, p_book, p_month, p_subsidiary, p_debit, p_credit, p_count)
  on conflict (org_id, account_id, book_id, month, subsidiary_id) do update
    set debit_total = g.debit_total + excluded.debit_total,
        credit_total = g.credit_total + excluded.credit_total,
        line_count = g.line_count + excluded.line_count;
$$;


--
-- Name: openbooks_gl_activity_entry(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_gl_activity_entry() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_old_in boolean;
  v_new_in boolean;
  v_old_month date;
  v_new_month date;
  v_old_book uuid;
  v_new_book uuid;
begin
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  if tg_op = 'DELETE' and public.openbooks_sandbox_wipe_allowed(old.org_id) then
    return null;
  end if;
  if tg_op = 'INSERT' then
    if new.status in ('posted', 'reversed') then
      perform openbooks_gl_activity_entry_delta(new.id, new.org_id, date_trunc('month', new.posting_date)::date, 1);
    end if;
    return null;
  end if;
  if tg_op = 'DELETE' then
    if old.status in ('posted', 'reversed') then
      perform openbooks_gl_activity_entry_delta(old.id, old.org_id, date_trunc('month', old.posting_date)::date, -1);
    end if;
    return null;
  end if;
  v_old_in := old.status in ('posted', 'reversed');
  v_new_in := new.status in ('posted', 'reversed');
  v_old_month := date_trunc('month', old.posting_date)::date;
  v_new_month := date_trunc('month', new.posting_date)::date;
  v_old_book := old.book_id;
  v_new_book := new.book_id;
  if v_old_in and not v_new_in then
    perform openbooks_gl_activity_entry_delta(old.id, old.org_id, v_old_month, -1);
  elsif v_new_in and not v_old_in then
    perform openbooks_gl_activity_entry_delta(new.id, new.org_id, v_new_month, 1);
  elsif v_old_in and v_new_in and (v_old_month <> v_new_month or v_old_book is distinct from v_new_book) then
    perform openbooks_gl_activity_entry_delta(old.id, old.org_id, v_old_month, -1, v_old_book);
    perform openbooks_gl_activity_entry_delta(new.id, new.org_id, v_new_month, 1);
  end if;
  return null;
end $$;


--
-- Name: openbooks_gl_activity_entry_delta(uuid, uuid, date, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_gl_activity_entry_delta(p_entry uuid, p_org uuid, p_month date, p_sign integer, p_book uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE sql
    AS $$
  insert into gl_month_activity as g (org_id, account_id, book_id, month, subsidiary_id, debit_total, credit_total, line_count)
  select p_org, l.account_id, coalesce(p_book, e.book_id), p_month, l.subsidiary_id,
         p_sign * coalesce(sum(case when l.amount > 0 then l.amount else 0 end), 0),
         p_sign * coalesce(sum(case when l.amount < 0 then -l.amount else 0 end), 0),
         p_sign * count(*)
    from journal_lines l
    join journal_entries e on e.id = l.entry_id and e.org_id = l.org_id
   where l.entry_id = p_entry and l.org_id = p_org and e.org_id = p_org
   group by l.account_id, coalesce(p_book, e.book_id), l.subsidiary_id
   order by l.account_id, coalesce(p_book, e.book_id), l.subsidiary_id
  on conflict (org_id, account_id, book_id, month, subsidiary_id) do update
    set debit_total = g.debit_total + excluded.debit_total,
        credit_total = g.credit_total + excluded.credit_total,
        line_count = g.line_count + excluded.line_count;
$$;


--
-- Name: openbooks_gl_activity_insert_statement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_gl_activity_insert_statement() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  INSERT INTO public.gl_month_activity AS g
    (org_id,account_id,book_id,month,subsidiary_id,debit_total,credit_total,line_count)
  SELECT e.org_id,l.account_id,e.book_id,date_trunc('month',e.posting_date)::date,l.subsidiary_id,
    sum(greatest(l.amount,0)),sum(greatest(-l.amount,0)),count(*)
  FROM inserted_journal_lines l
  JOIN public.journal_entries e ON e.id=l.entry_id AND e.org_id=l.org_id
  WHERE e.status IN ('posted','reversed')
  GROUP BY e.org_id,l.account_id,e.book_id,date_trunc('month',e.posting_date)::date,l.subsidiary_id
  -- Acquire grouped summary keys in a deterministic order.
  ORDER BY e.org_id,l.account_id,e.book_id,date_trunc('month',e.posting_date)::date,l.subsidiary_id
  ON CONFLICT (org_id,account_id,book_id,month,subsidiary_id) DO UPDATE
    SET debit_total=g.debit_total+excluded.debit_total,
        credit_total=g.credit_total+excluded.credit_total,
        line_count=g.line_count+excluded.line_count;
  RETURN NULL;
END $$;


--
-- Name: openbooks_gl_activity_line(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_gl_activity_line() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_status text;
  v_date date;
  v_org uuid;
  v_book uuid;
  v_month date;
  v_entry uuid;
  v_line_org uuid;
begin
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  if tg_op = 'DELETE' and public.openbooks_sandbox_wipe_allowed(old.org_id) then
    return null;
  end if;
  if tg_op = 'UPDATE'
     and (new.entry_id, new.org_id) is distinct from (old.entry_id, old.org_id) then
    select status, posting_date, org_id, book_id
      into v_status, v_date, v_org, v_book
      from journal_entries
     where id = old.entry_id and org_id = old.org_id;
    if v_status in ('posted', 'reversed') then
      v_month := date_trunc('month', v_date)::date;
      perform openbooks_gl_activity_apply(v_org, old.account_id, v_book, v_month, old.subsidiary_id,
        -greatest(old.amount, 0), -greatest(-old.amount, 0), -1);
    end if;
    select status, posting_date, org_id, book_id
      into v_status, v_date, v_org, v_book
      from journal_entries
     where id = new.entry_id and org_id = new.org_id;
    if v_status in ('posted', 'reversed') then
      v_month := date_trunc('month', v_date)::date;
      perform openbooks_gl_activity_apply(v_org, new.account_id, v_book, v_month, new.subsidiary_id,
        greatest(new.amount, 0), greatest(-new.amount, 0), 1);
    end if;
    return null;
  end if;
  if tg_op = 'DELETE' then
    v_entry := old.entry_id;
    v_line_org := old.org_id;
  else
    v_entry := new.entry_id;
    v_line_org := new.org_id;
  end if;
  select status, posting_date, org_id, book_id
    into v_status, v_date, v_org, v_book
    from journal_entries
   where id = v_entry and org_id = v_line_org;
  if v_status is null or v_status not in ('posted', 'reversed') then
    return null;
  end if;
  v_month := date_trunc('month', v_date)::date;
  if tg_op in ('UPDATE', 'DELETE') then
    perform openbooks_gl_activity_apply(v_org, old.account_id, v_book, v_month, old.subsidiary_id,
      -greatest(old.amount, 0), -greatest(-old.amount, 0), -1);
  end if;
  if tg_op in ('INSERT', 'UPDATE') then
    perform openbooks_gl_activity_apply(v_org, new.account_id, v_book, v_month, new.subsidiary_id,
      greatest(new.amount, 0), greatest(-new.amount, 0), 1);
  end if;
  return null;
end $$;


--
-- Name: openbooks_gl_activity_rebuild(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_gl_activity_rebuild(p_org uuid) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare
  v_count bigint;
begin
  delete from gl_month_activity where org_id = p_org;
  insert into gl_month_activity (org_id, account_id, book_id, month, subsidiary_id, debit_total, credit_total, line_count)
  select e.org_id, l.account_id, e.book_id, date_trunc('month', e.posting_date)::date, l.subsidiary_id,
         coalesce(sum(case when l.amount > 0 then l.amount else 0 end), 0),
         coalesce(sum(case when l.amount < 0 then -l.amount else 0 end), 0),
         count(*)
    from journal_lines l
    join journal_entries e on e.id = l.entry_id and e.org_id = l.org_id
   where e.org_id = p_org and l.org_id = p_org and e.status in ('posted', 'reversed')
   group by e.org_id, l.account_id, e.book_id, date_trunc('month', e.posting_date)::date, l.subsidiary_id;
  get diagnostics v_count = row_count;
  return v_count;
end $$;


--
-- Name: openbooks_gl_activity_verify(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_gl_activity_verify(p_org uuid) RETURNS TABLE(account_id uuid, book_id uuid, month date, subsidiary_id uuid, summary_debit numeric, ledger_debit numeric, summary_credit numeric, ledger_credit numeric)
    LANGUAGE sql
    AS $$
  with ledger as (
    select l.account_id, e.book_id, date_trunc('month', e.posting_date)::date as month, l.subsidiary_id,
           coalesce(sum(case when l.amount > 0 then l.amount else 0 end), 0) as debit_total,
           coalesce(sum(case when l.amount < 0 then -l.amount else 0 end), 0) as credit_total
      from journal_lines l
      join journal_entries e on e.id = l.entry_id and e.org_id = l.org_id
     where e.org_id = p_org and l.org_id = p_org and e.status in ('posted', 'reversed')
     group by 1, 2, 3, 4
  ), summary as (
    select g.account_id, g.book_id, g.month, g.subsidiary_id, g.debit_total, g.credit_total
      from gl_month_activity g where g.org_id = p_org
       and (g.debit_total <> 0 or g.credit_total <> 0 or g.line_count <> 0)
  )
  select coalesce(l.account_id, s.account_id), coalesce(l.book_id, s.book_id),
         coalesce(l.month, s.month), coalesce(l.subsidiary_id, s.subsidiary_id),
         coalesce(s.debit_total, 0), coalesce(l.debit_total, 0),
         coalesce(s.credit_total, 0), coalesce(l.credit_total, 0)
    from ledger l
    full outer join summary s
      on s.account_id = l.account_id and s.book_id = l.book_id
     and s.month = l.month and s.subsidiary_id = l.subsidiary_id
   where coalesce(s.debit_total, 0) <> coalesce(l.debit_total, 0)
      or coalesce(s.credit_total, 0) <> coalesce(l.credit_total, 0);
$$;


--
-- Name: openbooks_guard_ap_capture_evidence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_ap_capture_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  RAISE EXCEPTION 'AP capture evidence is append-only';
END;
$$;


--
-- Name: openbooks_guard_ap_capture_source_blob(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_ap_capture_source_blob() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF EXISTS (
    SELECT 1 FROM file_versions fv
    JOIN ap_capture_items ci ON ci.file_id = fv.file_id
    WHERE fv.id = OLD.version_id
  ) THEN
    RAISE EXCEPTION 'AP capture source blobs are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: openbooks_guard_ap_capture_source_file(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_ap_capture_source_file() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF EXISTS (SELECT 1 FROM ap_capture_items WHERE file_id = OLD.id) THEN
    RAISE EXCEPTION 'AP capture source files are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: openbooks_guard_ap_capture_source_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_ap_capture_source_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE target_file_id uuid;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  target_file_id := CASE WHEN TG_OP = 'INSERT' THEN NEW.file_id ELSE OLD.file_id END;
  IF EXISTS (SELECT 1 FROM ap_capture_items WHERE file_id = target_file_id) THEN
    RAISE EXCEPTION 'AP capture source versions are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: openbooks_guard_budget_line(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_budget_line() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  row_data budget_lines%rowtype;
  scenario_org uuid;
  scenario_year integer;
  scenario_status text;
begin
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  row_data := case when tg_op = 'DELETE' then old else new end;
  select org_id, fiscal_year, status
    into scenario_org, scenario_year, scenario_status
    from budget_scenarios where id = row_data.scenario_id;
  -- During an ON DELETE CASCADE, PostgreSQL removes the parent scenario before
  -- firing the child row's delete trigger. The line was already protected by
  -- the scenario's draft-only delete guard, so allow that cascade to finish.
  if tg_op = 'DELETE' and scenario_org is null then return old; end if;
  if scenario_org is null or scenario_org <> row_data.org_id then
    raise exception 'budget line scenario must belong to the tenant';
  end if;
  if scenario_status <> 'draft' then
    raise exception 'budget lines are immutable outside draft status';
  end if;
  if tg_op = 'DELETE' then return old; end if;

  if not exists (
    select 1 from accounts a
     where a.id = new.account_id and a.org_id = new.org_id and a.is_active and not a.is_summary
  ) then
    raise exception 'budget account must be an active posting account in the tenant';
  end if;
  -- Budgets plan the profit and loss only: the six P&L types of the single
  -- PNL_TYPES definition (engine records/account-types), the same set the
  -- worksheet, the import, the variances and the prior-actuals copy filter
  -- on. Refuse a balance-sheet account by name rather than writing a line
  -- the worksheet hides but the totals count.
  if not exists (
    select 1 from accounts a
     where a.id = new.account_id and a.org_id = new.org_id
       and a.type in ('income', 'income_other', 'cogs', 'expense', 'expense_other', 'expense_deferred')
  ) then
    raise exception 'budget account must be a profit-and-loss posting account in the tenant (income, income_other, cogs, expense, expense_other, expense_deferred)';
  end if;
  if not exists (
    select 1 from accounting_periods p
     where p.id = new.period_id and p.org_id = new.org_id
       and p.fiscal_year = scenario_year and not p.is_adjustment
  ) then
    raise exception 'budget period must belong to the scenario fiscal year and tenant';
  end if;
  -- A budget is pinned to one calendar: the org default. The worksheet, the
  -- totals, the import resolver and the copy mapping all read that calendar,
  -- so a line on any other calendar would be hidden yet counted.
  if not exists (
    select 1 from accounting_periods p
      join fiscal_calendars fc on fc.id = p.fiscal_calendar_id and fc.org_id = p.org_id
     where p.id = new.period_id and p.org_id = new.org_id
       and p.fiscal_year = scenario_year and not p.is_adjustment and fc.is_default
  ) then
    raise exception 'budget period must belong to the scenario fiscal year on the default fiscal calendar of the tenant';
  end if;
  if new.department_id is not null and not exists (
    select 1 from departments d where d.id = new.department_id and d.org_id = new.org_id
  ) then raise exception 'budget department must belong to the tenant'; end if;
  if new.project_id is not null and not exists (
    select 1 from projects p where p.id = new.project_id and p.org_id = new.org_id
  ) then raise exception 'budget project must belong to the tenant'; end if;
  if new.location_id is not null and not exists (
    select 1 from locations l where l.id = new.location_id and l.org_id = new.org_id
  ) then raise exception 'budget location must belong to the tenant'; end if;
  if new.class_id is not null and not exists (
    select 1 from classes c where c.id = new.class_id and c.org_id = new.org_id
  ) then raise exception 'budget class must belong to the tenant'; end if;
  return new;
end;
$$;


--
-- Name: openbooks_guard_budget_scenario(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_budget_scenario() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  if tg_op = 'DELETE' then
    if old.status <> 'draft' then
      raise exception 'only draft budget scenarios may be deleted';
    end if;
    return old;
  end if;

  if not exists (
    select 1 from accounting_books b
     where b.id = new.book_id and b.org_id = new.org_id and b.is_active
  ) then
    raise exception 'budget scenario book must be active and belong to the tenant';
  end if;

  if tg_op = 'UPDATE' then
    if new.revision <> old.revision + 1 then
      raise exception 'budget scenario revision must increment by exactly one';
    end if;
    if old.status <> 'draft' and (
      new.name is distinct from old.name or
      new.description is distinct from old.description or
      new.book_id is distinct from old.book_id or
      new.fiscal_year is distinct from old.fiscal_year or
      new.kind is distinct from old.kind
    ) then
      raise exception 'only draft budget metadata may be edited';
    end if;
    -- The book and fiscal year pin the plan to one ledger and one period
    -- set: changing either under existing lines would silently reinterpret
    -- the whole plan. Refuse here as well as in the route so writers
    -- bypassing the API meet the same refusal.
    if (new.book_id is distinct from old.book_id or new.fiscal_year is distinct from old.fiscal_year)
       and exists (select 1 from budget_lines bl where bl.scenario_id = new.id and bl.org_id = new.org_id)
    then
      raise exception 'budget book and fiscal year are fixed once the budget has lines';
    end if;
    if new.status is distinct from old.status and not (
      (old.status = 'draft' and new.status in ('pending_approval', 'archived')) or
      (old.status = 'pending_approval' and new.status in ('draft', 'approved', 'archived')) or
      (old.status = 'approved' and new.status = 'archived')
    ) then
      raise exception 'invalid budget status transition: % -> %', old.status, new.status;
    end if;
  end if;

  if new.status in ('pending_approval', 'approved') and not exists (
    select 1 from budget_lines bl
     where bl.scenario_id = new.id and bl.org_id = new.org_id and bl.amount <> 0
  ) then
    raise exception 'a submitted or approved budget must contain at least one non-zero line';
  end if;
  if new.submitted_by is not null and not exists (
    select 1 from users u where u.id = new.submitted_by and u.org_id = new.org_id
  ) then raise exception 'budget submitter must belong to the tenant'; end if;
  if new.approved_by is not null and not exists (
    select 1 from users u where u.id = new.approved_by and u.org_id = new.org_id
  ) then raise exception 'budget approver must belong to the tenant'; end if;
  return new;
end;
$$;


--
-- Name: openbooks_guard_depreciation_evidence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_depreciation_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  posted boolean;
begin
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  if tg_op = 'DELETE' and public.openbooks_sandbox_wipe_allowed(old.org_id) then
    return old;
  end if;
  if tg_op = 'DELETE' then
    raise exception 'depreciation input evidence is append-preserved';
  end if;

  select exists (
    select 1 from depreciation_schedule_lines
     where input_id = old.id and posted_amount is not null
  ) into posted;
  if posted then
    raise exception 'posted depreciation input evidence is immutable';
  end if;

  if old.voided_at is not null
     or new.voided_at is null
     or new.voided_by is null
     or new.org_id is distinct from old.org_id
     or new.schedule_id is distinct from old.schedule_id
     or new.period_id is distinct from old.period_id
     or new.kind is distinct from old.kind
     or new.manual_amount is distinct from old.manual_amount
     or new.production_units is distinct from old.production_units
     or new.memo is distinct from old.memo
     or new.evidence_file_id is distinct from old.evidence_file_id
     or new.supersedes_input_id is distinct from old.supersedes_input_id
     or new.created_at is distinct from old.created_at
     or new.created_by is distinct from old.created_by then
    raise exception 'depreciation input evidence may only be voided before posting';
  end if;
  return new;
end;
$$;


--
-- Name: openbooks_guard_finished_ap_capture_run(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_finished_ap_capture_run() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' OR OLD.status <> 'running' THEN
    RAISE EXCEPTION 'Finished AP capture runs are immutable';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: openbooks_guard_pay_run_bank_file(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_pay_run_bank_file() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'payroll bank files are immutable evidence and cannot be deleted';
  END IF;
  IF NEW.id <> OLD.id
     OR NEW.org_id <> OLD.org_id
     OR NEW.pay_run_document_id <> OLD.pay_run_document_id
     OR NEW.payment_bank_profile_id <> OLD.payment_bank_profile_id
     OR NEW.format <> OLD.format
     OR NEW.sequence_number <> OLD.sequence_number
     OR NEW.file_number <> OLD.file_number
     OR NEW.sequence_value <> OLD.sequence_value
     OR NEW.file_creation_number IS DISTINCT FROM OLD.file_creation_number
     OR NEW.file_id_modifier IS DISTINCT FROM OLD.file_id_modifier
     OR NEW.filename <> OLD.filename
     OR NEW.content_hash <> OLD.content_hash
     OR NEW.size_bytes <> OLD.size_bytes
     OR NEW.file_id <> OLD.file_id
     OR NEW.file_version_id <> OLD.file_version_id
     OR NEW.entry_count <> OLD.entry_count
     OR NEW.control_total <> OLD.control_total
     OR NEW.currency <> OLD.currency
     OR NEW.excluded_cheque::text <> OLD.excluded_cheque::text
     OR NEW.excluded_total <> OLD.excluded_total
     OR NEW.generated_at <> OLD.generated_at THEN
    RAISE EXCEPTION 'payroll bank file % is immutable: regenerate to produce a new artifact', OLD.file_number;
  END IF;
  IF NEW.release_count < OLD.release_count THEN
    RAISE EXCEPTION 'payroll bank file release history cannot be rewound';
  END IF;
  IF OLD.status = 'superseded' AND NEW.status <> 'superseded' THEN
    RAISE EXCEPTION 'a superseded payroll bank file cannot be reinstated';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: openbooks_guard_payroll_bank_file_blob(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_payroll_bank_file_blob() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.pay_run_bank_files f WHERE f.file_version_id = OLD.version_id
  ) THEN
    RAISE EXCEPTION 'payroll bank file blobs are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: openbooks_guard_payroll_bank_file_file(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_payroll_bank_file_file() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF EXISTS (SELECT 1 FROM public.pay_run_bank_files f WHERE f.file_id = OLD.id) THEN
    IF TG_OP = 'DELETE' THEN
      RAISE EXCEPTION 'payroll bank files cannot be deleted from the cabinet';
    END IF;
    -- Renaming, moving, retiring or re-pointing the current version would all
    -- change what a later download returns.
    IF NEW.name <> OLD.name OR NEW.folder_id <> OLD.folder_id
       OR NEW.content_hash IS DISTINCT FROM OLD.content_hash
       OR NEW.current_version_id IS DISTINCT FROM OLD.current_version_id
       OR NEW.is_inactive <> OLD.is_inactive THEN
      RAISE EXCEPTION 'payroll bank files are immutable';
    END IF;
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: openbooks_guard_payroll_bank_file_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_payroll_bank_file_version() RETURNS trigger
