-- Name: position_changes_stamp_txid(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.position_changes_stamp_txid() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.change_txid := txid_current();
  RETURN NEW;
END $$;


--
-- Name: FUNCTION position_changes_stamp_txid(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.position_changes_stamp_txid() IS 'openbooks:position_changes_stamp_txid:v1 - every position evidence event carries its writing top-level transaction id, immutable forever';


--
-- Name: position_closure_evidence_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.position_closure_evidence_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
  ev_txid bigint;
  ev_array jsonb;
  succ_at timestamptz;
  succ_n integer;
  elem jsonb;
  elem_n integer;
  expected_before jsonb;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.superseded_by IS NULL THEN
      RETURN NULL;
    END IF;
  ELSIF OLD.superseded_by IS NOT NULL OR NEW.superseded_by IS NULL THEN
    RETURN NULL;
  END IF;
  IF NEW.closed_by_change_id IS NULL THEN
    RAISE EXCEPTION 'position_versions: closing a version requires closed_by_change_id (the aggregate evidence event)'
      USING ERRCODE = '23514';
  END IF;
  -- Real adjacent successor: exists, strictly newer, starts exactly here.
  -- PL/pgSQL EXECUTE never sets FOUND, so the presence check reads
  -- ROW_COUNT (the 0184 guard's documented rule, repeated here because the
  -- wrong check compiles and silently proves nothing).
  EXECUTE
    'SELECT recorded_at FROM public.position_versions WHERE org_id = $1 AND position_id = $2 AND version_no = $3'
    INTO succ_at
    USING NEW.org_id, NEW.position_id, NEW.superseded_by;
  GET DIAGNOSTICS succ_n = ROW_COUNT;
  IF succ_n = 0 THEN
    RAISE EXCEPTION 'position_versions: superseded_by must name a real version_no of the same position (no dangling pointers)'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.superseded_by <= NEW.version_no THEN
    RAISE EXCEPTION 'position_versions: successor version_no must be strictly newer (rejects self and backwards)'
      USING ERRCODE = '23514';
  END IF;
  IF succ_at IS DISTINCT FROM NEW.recorded_until THEN
    RAISE EXCEPTION 'position_versions: successor recorded_at must equal the closed recorded_until (seamless handoff, no gap or overlap)'
      USING ERRCODE = '23514';
  END IF;
  -- Same-transaction aggregate event naming this exact closure. Plain
  -- SELECT ... INTO sets FOUND (unlike EXECUTE above), so IF NOT FOUND is
  -- correct here.
  SELECT c.change_txid, c.closed_versions INTO ev_txid, ev_array
    FROM public.position_changes c
   WHERE c.id = NEW.closed_by_change_id AND c.org_id = NEW.org_id
     AND c.position_id = NEW.position_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'position_versions: closed_by_change_id must name an evidence event for the same position'
      USING ERRCODE = '23514';
  END IF;
  IF ev_txid IS DISTINCT FROM txid_current() THEN
    RAISE EXCEPTION 'position_versions: closure evidence must be written in the same transaction (change_txid must equal txid_current())'
      USING ERRCODE = '23514';
  END IF;
  -- Exactly one element must name this closure: zero means the event does
  -- not evidence this close; two or more means the array double-counts one
  -- row and no single before-image can be authoritative.
  SELECT count(*) INTO elem_n FROM jsonb_array_elements(ev_array) AS e
   WHERE e @> jsonb_build_object(
      'table', 'position_versions', 'identity', NEW.position_id::text,
      'version_no', NEW.version_no, 'row_id', NEW.id::text);
  IF elem_n = 0 THEN
    RAISE EXCEPTION 'position_versions: evidence event must name this exact closure (table, identity, version_no, row_id) in closed_versions'
      USING ERRCODE = '23514';
  ELSIF elem_n > 1 THEN
    RAISE EXCEPTION 'position_versions: evidence event names this closure more than once (duplicate closed_versions entries)'
      USING ERRCODE = '23514';
  END IF;
  SELECT e INTO elem FROM jsonb_array_elements(ev_array) AS e
   WHERE e @> jsonb_build_object(
      'table', 'position_versions', 'identity', NEW.position_id::text,
      'version_no', NEW.version_no, 'row_id', NEW.id::text)
   LIMIT 1;
  -- Exact prior image, full row, no column subtracted: on UPDATE the element
  -- must carry OLD as it stood before this close; on INSERT of an
  -- already-closed row it must carry NEW as written.
  IF TG_OP = 'INSERT' THEN
    expected_before := to_jsonb(NEW);
  ELSE
    expected_before := to_jsonb(OLD);
  END IF;
  IF NOT (elem ? 'before') OR (elem->'before' IS DISTINCT FROM expected_before) THEN
    RAISE EXCEPTION 'position_versions: evidence event must carry the exact before-image of this closure in closed_versions[].before'
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END $_$;


--
-- Name: FUNCTION position_closure_evidence_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.position_closure_evidence_guard() IS 'openbooks:position_closure_evidence_guard:v1 - deferred proof per closure: adjacent strictly-newer successor (ROW_COUNT presence) plus same-transaction aggregate position_changes event (txid-stamped) naming the exact row with its exact before-image';


--
-- Name: position_evidence_closure_reverse_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.position_evidence_closure_reverse_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  elem jsonb;
  tbl text;
  row_n integer;
BEGIN
  -- Governed amend path (fixture teardown, historical replay): the existing
  -- house mechanism, never a production bypass.
  IF coalesce(current_setting('openbooks.amend', true), 'off') = 'on' THEN
    RETURN NULL;
  END IF;
  FOR elem IN SELECT * FROM jsonb_array_elements(NEW.closed_versions) LOOP
    tbl := elem->>'table';
    IF tbl IS DISTINCT FROM 'position_versions' THEN
      RAISE EXCEPTION 'position_changes: closed_versions element names an unknown closure table %', tbl
        USING ERRCODE = '23514';
    END IF;
    IF jsonb_typeof(elem->'before') IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION 'position_changes: closed_versions element for % must carry a before-image object', tbl
        USING ERRCODE = '23514';
    END IF;
    -- count(*) always returns exactly one row, so INTO needs no FOUND dance.
    SELECT count(*) INTO row_n FROM public.position_versions
     WHERE id = (elem->>'row_id')::uuid AND org_id = NEW.org_id
       AND position_id = (elem->>'identity')::uuid
       AND version_no = (elem->>'version_no')::int
       AND position_id = NEW.position_id
       AND superseded_by IS NOT NULL AND closed_by_change_id = NEW.id;
    IF row_n <> 1 THEN
      RAISE EXCEPTION 'position_changes: closed_versions element must name a real closed row of this position linked back to this event (identity %)', elem->>'identity'
        USING ERRCODE = '23514';
    END IF;
  END LOOP;
  RETURN NULL;
END $$;


--
-- Name: FUNCTION position_evidence_closure_reverse_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.position_evidence_closure_reverse_guard() IS 'openbooks:position_evidence_closure_reverse_guard:v1 - deferred reverse proof per event: every closed_versions element names exactly one really-closed row of this position linked back to this event';


--
-- Name: position_versions_closure_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.position_versions_closure_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  -- Governed amend path (fixture teardown, historical replay, native merge):
  -- the existing house mechanism, not a new bypass. Production paths never
  -- set openbooks.amend; scratch teardown does, or cascade deletes of a
  -- dropped scratch org could never complete.
  IF TG_OP = 'DELETE'
     AND coalesce(current_setting('openbooks.amend', true), 'off') = 'on' THEN
    RETURN OLD;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'position_versions: rows are never deleted; close with a superseding version'
      USING ERRCODE = '23514';
  END IF;
  IF OLD.superseded_by IS NOT NULL THEN
    RAISE EXCEPTION 'position_versions: closed versions are immutable'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.superseded_by IS NULL AND NEW.recorded_until IS NULL
     AND NEW.closed_by_change_id IS NULL
     AND to_jsonb(NEW) - ARRAY['updated_at','updated_by']
       = to_jsonb(OLD) - ARRAY['updated_at','updated_by'] THEN
    RETURN NEW;
  END IF;
  IF NEW.superseded_by IS NULL OR NEW.recorded_until IS NULL THEN
    RAISE EXCEPTION 'position_versions: live rows are append-only; the only allowed UPDATE is the closing transition (recorded_until + superseded_by) or a pure audit touch'
      USING ERRCODE = '23514';
  END IF;
  -- Explicit allowlist: ONLY recorded_until, superseded_by,
  -- closed_by_change_id, and the audit touch (updated_at/updated_by) may
  -- differ. The successor reference and its evidence are validated deferred
  -- at commit (position_closure_evidence_guard).
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.org_id IS DISTINCT FROM OLD.org_id
     OR NEW.position_id IS DISTINCT FROM OLD.position_id
     OR NEW.version_no IS DISTINCT FROM OLD.version_no
     OR NEW.title IS DISTINCT FROM OLD.title
     OR NEW.department_id IS DISTINCT FROM OLD.department_id
     OR NEW.location_id IS DISTINCT FROM OLD.location_id
     OR NEW.employer_subsidiary_id IS DISTINCT FROM OLD.employer_subsidiary_id
     OR NEW.job_grade IS DISTINCT FROM OLD.job_grade
     OR NEW.planned_fte IS DISTINCT FROM OLD.planned_fte
     OR NEW.status IS DISTINCT FROM OLD.status
     OR NEW.effective_from IS DISTINCT FROM OLD.effective_from
     OR NEW.effective_to IS DISTINCT FROM OLD.effective_to
     OR NEW.recorded_at IS DISTINCT FROM OLD.recorded_at
     OR NEW.created_at IS DISTINCT FROM OLD.created_at
     OR NEW.created_by IS DISTINCT FROM OLD.created_by THEN
    RAISE EXCEPTION 'position_versions: closure sets recorded_until + superseded_by + closed_by_change_id (plus audit touch) only'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: FUNCTION position_versions_closure_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.position_versions_closure_guard() IS 'openbooks:position_versions_closure_guard:v1 - closed rows immutable; live rows accept only the closing transition or a pure audit touch; successor + evidence proven deferred by position_closure_evidence_guard';


--
-- Name: positions_identity_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.positions_identity_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.org_id IS DISTINCT FROM OLD.org_id
     OR NEW.position_code IS DISTINCT FROM OLD.position_code THEN
    RAISE EXCEPTION 'positions: org_id and position_code are immutable (close the position and open a new one, never move it)'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: FUNCTION positions_identity_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.positions_identity_guard() IS 'openbooks:positions_identity_guard:v1 - stable establishment identity; parent keys immutable so version and funding provenance proofs cannot be invalidated';


--
-- Name: posted_document_financial_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.posted_document_financial_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' and public.openbooks_sandbox_wipe_allowed(old.org_id) then
    return old;
  end if;
  if coalesce(current_setting('openbooks.amend', true), 'off') <> 'on' then
    raise exception 'document % is % — its financial identity (totals, dates, currency, party, kind, number) is immutable outside the governed amend path', old.id, old.status;
  end if;
  return new;
end $$;


--
-- Name: posted_document_status_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.posted_document_status_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  -- Only the hardened per-org check admits a sandbox wipe; a raw session
  -- GUC is settable by any session and would reopen posted -> draft.
  if public.openbooks_sandbox_wipe_allowed(old.org_id) then
    return new;
  end if;
  -- The controlled void writes its evidence (voided_at, voided_by,
  -- void_reason) in the same statement that flips the status; the row CHECK
  -- documents_void_reason_required enforces the same triple at commit.
  if new.status = 'voided'
     and new.voided_at is not null
     and new.voided_by is not null
     and new.void_reason is not null then
    return new;
  end if;
  if coalesce(current_setting('openbooks.amend', true), 'off') = 'on' then
    return new;
  end if;
  raise exception 'document % is posted and immutable — void it through the controlled void path instead of changing its status to %', old.id, new.status;
end $$;


--
-- Name: prebill_event_append_only_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prebill_event_append_only_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'Prebill events are append-only';
END $$;


--
-- Name: prebill_source_reservation_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prebill_source_reservation_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE parent_status text; source_key uuid;
BEGIN
  SELECT status INTO parent_status FROM public.prebills WHERE org_id=NEW.org_id AND id=NEW.prebill_id;
  IF parent_status NOT IN ('draft','review','approved','customer_review') THEN RETURN NEW; END IF;
  source_key := coalesce(NEW.time_entry_id, NEW.document_line_id);
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.org_id::text||':'||NEW.source_type||':'||source_key::text,0));
  IF EXISTS (SELECT 1 FROM public.prebill_lines line JOIN public.prebills worksheet
               ON worksheet.org_id=line.org_id AND worksheet.id=line.prebill_id
              WHERE line.org_id=NEW.org_id AND line.id<>NEW.id AND line.source_type=NEW.source_type
                AND coalesce(line.time_entry_id,line.document_line_id)=source_key
                AND worksheet.status IN ('draft','review','approved','customer_review'))
  THEN RAISE EXCEPTION 'Source is already reserved by an active prebill'; END IF;
  RETURN NEW;
END $$;


--
-- Name: prepaid_breakage_change_binding(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepaid_breakage_change_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.domain='revenue' AND NEW.operation='expected_breakage_estimate' AND NOT EXISTS(
    SELECT 1 FROM public.usage_prepaid_grants g
      JOIN public.document_lines line ON line.org_id=g.org_id AND line.id=g.source_document_line_id
      JOIN public.documents document ON document.org_id=line.org_id AND document.id=line.document_id
      JOIN public.performance_obligations obligation ON obligation.org_id=line.org_id AND obligation.document_line_id=line.id
      JOIN public.revenue_contracts contract ON contract.org_id=obligation.org_id AND contract.id=obligation.contract_id
    WHERE g.org_id=NEW.org_id AND g.id=(NEW.payload->>'grantId')::uuid AND contract.id=NEW.subject_id
      AND coalesce(contract.subsidiary_id,line.subsidiary_id,document.subsidiary_id)=NEW.subsidiary_id
      AND NEW.payload->'requiredSubsidiaryIds'=jsonb_build_array(NEW.subsidiary_id::text)
      AND jsonb_typeof(NEW.before_state->'estimates')='array'
  ) THEN RAISE EXCEPTION 'breakage estimate must bind to its prepaid grant, revenue contract and legal entity'; END IF;
  RETURN NEW;
END $$;


--
-- Name: preserve_historical_compensation_cycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preserve_historical_compensation_cycle() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF OLD.status = 'historical' THEN
    RAISE EXCEPTION 'Historical compensation source records are immutable; import a new source version to correct the evidence';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: preserve_vendor_retainage_source_allocations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preserve_vendor_retainage_source_allocations() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.source_bill_allocations IS DISTINCT FROM OLD.source_bill_allocations THEN
  RAISE EXCEPTION 'Retainage source allocations are immutable; cancel the release through its native workflow and create a replacement';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: price_level_activation_maintenance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.price_level_activation_maintenance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- Clone replay copies the source activation periods immediately after the
    -- price levels; creating a new period here would duplicate that evidence.
    IF public.openbooks_clone_authority() THEN
      RETURN NEW;
    END IF;
    -- A level born inactive was never offered: no period until activated.
    -- Otherwise the standing offer opens at -infinity (see 0327).
    IF NEW.is_active THEN
      INSERT INTO public.price_level_activation_history (org_id, price_level_id, active_from, opened_at)
      VALUES (NEW.org_id, NEW.id, '-infinity'::date, now());
    END IF;
    RETURN NEW;
  END IF;
  IF OLD.is_active AND NOT NEW.is_active THEN
    UPDATE public.price_level_activation_history
       SET active_to = current_date, closed_at = now(), updated_at = now()
     WHERE org_id = NEW.org_id AND price_level_id = NEW.id AND active_to IS NULL;
  ELSIF NOT OLD.is_active AND NEW.is_active THEN
    INSERT INTO public.price_level_activation_history (org_id, price_level_id, active_from, opened_at)
    SELECT NEW.org_id, NEW.id, current_date, now()
     WHERE NOT EXISTS (
       SELECT 1 FROM public.price_level_activation_history h
        WHERE h.org_id = NEW.org_id AND h.price_level_id = NEW.id AND h.active_to IS NULL
     );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: primary_book_history_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.primary_book_history_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  source_org uuid;
  target_org uuid;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF coalesce(current_setting('openbooks.migration', true), 'off') = 'on' THEN
    IF tg_op = 'DELETE' THEN RETURN old; END IF;
    RETURN new;
  END IF;
  IF tg_op = 'DELETE' THEN
    IF NOT old.is_primary OR public.openbooks_sandbox_wipe_allowed(old.org_id) THEN
      RETURN old;
    END IF;
    source_org := old.org_id;
  ELSIF tg_op = 'INSERT' THEN
    IF NOT new.is_primary THEN RETURN new; END IF;
    target_org := new.org_id;
  ELSE
    -- A name, code, activation, or posting-policy edit does not change which
    -- book is authoritative. Keep those existing lifecycle controls intact.
    IF new.is_primary = old.is_primary AND new.org_id = old.org_id AND new.id = old.id THEN
      RETURN new;
    END IF;
    IF old.is_primary THEN source_org := old.org_id; END IF;
    IF new.is_primary THEN target_org := new.org_id; END IF;
  END IF;
  -- A pre-existing REPEATABLE READ snapshot could miss a first journal that
  -- committed before we acquired the book lock (SHARE did not change its row).
  -- These rare configuration writes require fresh statement snapshots.
  IF current_setting('transaction_isolation') NOT IN ('read committed', 'read uncommitted') THEN
    RAISE EXCEPTION 'Primary book identity changes require READ COMMITTED isolation; retry the configuration in a new READ COMMITTED transaction'
      USING ERRCODE = '25000';
  END IF;
  -- SQL callers may already hold the target book row when this trigger runs.
  -- Never wait in the inverse target -> authority order: contention fails
  -- closed and the caller can retry the whole transaction. The setup service
  -- acquires authority first, so its ordinary wait/recheck path is unchanged.
  PERFORM id FROM public.accounting_books
    WHERE org_id IN (source_org, target_org) AND is_primary
    ORDER BY id FOR UPDATE NOWAIT;
  IF EXISTS (SELECT 1 FROM public.journal_entries WHERE org_id IN (source_org, target_org))
     OR EXISTS (SELECT 1 FROM public.reconciliations WHERE org_id IN (source_org, target_org)) THEN
    RAISE EXCEPTION 'Cannot reassign the primary book while journal entries or bank reconciliation sessions/history exist; a controlled book conversion is required'
      USING ERRCODE = '23514';
  END IF;
  IF tg_op = 'DELETE' THEN RETURN old; END IF;
  RETURN new;
END;
$$;


--
-- Name: FUNCTION primary_book_history_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.primary_book_history_guard() IS 'openbooks:primary_book_history_guard:v1 - primary book identity is frozen by accounting or reconciliation history; migration and controlled sandbox-delete exemptions';


--
-- Name: production_bom_line_evidence(jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.production_bom_line_evidence(value jsonb, stored boolean) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF stored THEN
  RETURN jsonb_build_object('componentItemId',value->>'component_item_id','quantityPer',(value->>'quantity_per')::numeric,'sortOrder',(value->>'sort_order')::integer,
   'effectiveFrom',value->>'effective_from','effectiveTo',value->>'effective_to','operationSeq',(value->>'operation_seq')::integer,'scrapPct',coalesce((value->>'scrap_pct')::numeric,0),
   'isByproduct',(value->>'is_byproduct')::boolean,'quantityBasis',value->>'quantity_basis','formulaOutputQuantity',(value->>'formula_output_quantity')::numeric,'outputCostWeight',(value->>'output_cost_weight')::numeric);
 END IF;
 RETURN jsonb_build_object('componentItemId',value->>'componentItemId','quantityPer',(value->>'quantityPer')::numeric,'sortOrder',(value->>'sortOrder')::integer,
  'effectiveFrom',value->>'effectiveFrom','effectiveTo',value->>'effectiveTo','operationSeq',(value->>'operationSeq')::integer,'scrapPct',coalesce((value->>'scrapPct')::numeric,0),
  'isByproduct',(value->>'isByproduct')::boolean,'quantityBasis',value->>'quantityBasis','formulaOutputQuantity',(value->>'formulaOutputQuantity')::numeric,'outputCostWeight',(value->>'outputCostWeight')::numeric);
END $$;


--
-- Name: production_bom_revision_complete_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.production_bom_revision_complete_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE subject_org uuid;subject_item uuid;change_key text;proposal public.financial_changes%ROWTYPE;actual jsonb;expected jsonb;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' THEN
  IF public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN NULL; END IF;
  subject_org:=OLD.org_id;subject_item:=OLD.assembly_item_id;
 ELSE
  IF public.openbooks_clone_authority() THEN RETURN NULL; END IF;
  subject_org:=NEW.org_id;subject_item:=NEW.assembly_item_id;
 END IF;
 change_key:=nullif(current_setting('openbooks.production_bom_changes',true),'')::jsonb->>(subject_org::text||':'||subject_item::text);
 IF change_key IS NULL OR change_key='' THEN RETURN NULL; END IF;
 SELECT * INTO proposal FROM public.financial_changes WHERE org_id=subject_org AND id=change_key::uuid AND subject_id=subject_item
  AND domain='manufacturing' AND operation='bom_revision_activation' AND status='applied';
 IF NOT FOUND THEN RAISE EXCEPTION 'The approved recipe replacement must finish in its native accounting event transaction.' USING ERRCODE='23514'; END IF;
 SELECT coalesce(jsonb_agg(public.production_bom_line_evidence(to_jsonb(component),true) ORDER BY component.sort_order,component.component_item_id),'[]'::jsonb) INTO actual
  FROM public.bom_components component WHERE component.org_id=subject_org AND component.assembly_item_id=subject_item;
 SELECT coalesce(jsonb_agg(public.production_bom_line_evidence(component,false) ORDER BY (component->>'sortOrder')::integer,component->>'componentItemId'),'[]'::jsonb) INTO expected
  FROM jsonb_array_elements(proposal.payload->'components') component;
 IF actual IS DISTINCT FROM expected OR proposal.result->>'assemblyItemId' IS DISTINCT FROM subject_item::text THEN
  RAISE EXCEPTION 'The stored current recipe must equal its applied approved revision.' USING ERRCODE='23514';
 END IF;
 RETURN NULL;
END $$;


--
-- Name: production_bom_revision_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.production_bom_revision_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE subject_org uuid;subject_item uuid;change_key text;proposal public.financial_changes%ROWTYPE;governed boolean;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' THEN
  IF public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
  subject_org:=OLD.org_id;subject_item:=OLD.assembly_item_id;
 ELSE
  IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
  subject_org:=NEW.org_id;subject_item:=NEW.assembly_item_id;
 END IF;
 IF TG_OP='UPDATE' AND (NEW.org_id,NEW.assembly_item_id) IS DISTINCT FROM (OLD.org_id,OLD.assembly_item_id) THEN
  RAISE EXCEPTION 'A recipe line cannot change its organization or assembly.' USING ERRCODE='23514';
 END IF;
 IF TG_OP='UPDATE' AND to_jsonb(NEW)-ARRAY['updated_at','updated_by'] IS NOT DISTINCT FROM to_jsonb(OLD)-ARRAY['updated_at','updated_by'] THEN RETURN NEW; END IF;
 governed:=EXISTS(SELECT 1 FROM public.mfg_work_orders WHERE org_id=subject_org AND produced_item_id=subject_item AND released_at IS NOT NULL)
  OR EXISTS(SELECT 1 FROM public.mfg_routings WHERE org_id=subject_org AND produced_item_id=subject_item AND activation_change_id IS NOT NULL)
  OR EXISTS(SELECT 1 FROM public.financial_changes WHERE org_id=subject_org AND subject_id=subject_item AND domain='manufacturing' AND operation='bom_revision_activation');
 IF NOT governed THEN IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END IF;
 change_key:=nullif(current_setting('openbooks.production_bom_changes',true),'')::jsonb->>(subject_org::text||':'||subject_item::text);
 IF change_key IS NULL OR change_key!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
  RAISE EXCEPTION 'This production recipe requires an approved revision; open its BOM editor and submit the revision for approval.' USING ERRCODE='23514';
 END IF;
 SELECT * INTO proposal FROM public.financial_changes WHERE org_id=subject_org AND id=change_key::uuid AND subject_id=subject_item
  AND domain='manufacturing' AND operation='bom_revision_activation' AND status='approved' FOR SHARE;
 IF NOT FOUND OR proposal.approved_by IS NULL OR (proposal.approved_by=proposal.submitted_by AND NOT public.financial_change_self_decision_authorized(proposal.org_id,proposal.id,proposal.submitted_by))
  AND NOT (COALESCE(proposal.payload->'decision'->>'mode','')='automatic'
   AND COALESCE(proposal.payload->'decision'->'policy'->>'flowConfigured','')='false'
   AND NOT EXISTS(SELECT 1 FROM flows f WHERE f.org_id=proposal.org_id AND f.subject_kind='financial_change' AND f.enabled)
   AND NOT EXISTS(SELECT 1 FROM flow_runs r WHERE r.org_id=proposal.org_id AND r.subject_kind='financial_change' AND r.subject_id=proposal.id)) THEN
  RAISE EXCEPTION 'A current recipe requires its permitted approval decision.' USING ERRCODE='23514';
 END IF;
 IF TG_OP='DELETE' THEN
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(proposal.before_state->'lines') previous WHERE previous->>'id'=OLD.id::text
    AND public.production_bom_line_evidence(previous,false)=public.production_bom_line_evidence(to_jsonb(OLD),true)) THEN
   RAISE EXCEPTION 'The recipe changed after approval; propose its current revision again.' USING ERRCODE='23514';
  END IF;
  RETURN OLD;
 ELSIF TG_OP='UPDATE' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(proposal.payload->'components') component
   WHERE public.production_bom_line_evidence(component,false)=public.production_bom_line_evidence(to_jsonb(NEW),true)) THEN
  RAISE EXCEPTION 'Apply the exact approved recipe replacement; direct line changes are refused.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $_$;


--
-- Name: production_canonical_json(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.production_canonical_json(value jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE result text;
BEGIN
 IF value IS NULL THEN RETURN NULL; END IF;
 IF jsonb_typeof(value)='object' THEN
  SELECT '{'||coalesce(string_agg(to_json(key)::text||':'||public.production_canonical_json(item),',' ORDER BY key COLLATE "C"),'')||'}' INTO result FROM jsonb_each(value) object(key,item);RETURN result;
 ELSIF jsonb_typeof(value)='array' THEN
  SELECT '['||coalesce(string_agg(public.production_canonical_json(item),',' ORDER BY ordinal),'')||']' INTO result FROM jsonb_array_elements(value) WITH ORDINALITY array_item(item,ordinal);RETURN result;
 ELSIF jsonb_typeof(value)='number' AND position('.' IN value::text)>0 THEN
  RETURN trim(trailing '.' FROM trim(trailing '0' FROM value::text));
 END IF;
 RETURN value::text;
END $$;


--
-- Name: production_clone_evidence(jsonb, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.production_clone_evidence(value jsonb, seed uuid, field_name text DEFAULT ''::text, target_org uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE result jsonb; entry record; next_key text; scalar text; identity_field boolean;
BEGIN
 IF value IS NULL THEN RETURN NULL; END IF;
 identity_field:=field_name='id' OR field_name~'(Id|Ids|_id|_ids)$' OR field_name IN('subcontract_consumption_key','requestKey','requestId');
 IF jsonb_typeof(value)='string' AND field_name='intent' THEN
  BEGIN RETURN to_jsonb(public.production_canonical_json(public.production_clone_evidence((value#>>'{}')::jsonb,seed,'',target_org))); EXCEPTION WHEN invalid_text_representation THEN RETURN value; END;
 END IF;
 IF jsonb_typeof(value)='string' AND identity_field THEN
  scalar:=value#>>'{}';
  IF scalar~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
   IF field_name IN('orgId','org_id') AND target_org IS NOT NULL THEN RETURN to_jsonb(target_org::text); END IF;
   RETURN to_jsonb(public.ob_rebase(scalar::uuid,seed)::text);
  END IF;
 ELSIF jsonb_typeof(value)='array' THEN
  SELECT coalesce(jsonb_agg(public.production_clone_evidence(element,seed,field_name,target_org) ORDER BY ordinal),'[]'::jsonb) INTO result FROM jsonb_array_elements(value) WITH ORDINALITY a(element,ordinal);
  RETURN result;
 ELSIF jsonb_typeof(value)='object' THEN
  result:='{}'::jsonb;
  FOR entry IN SELECT key,item FROM jsonb_each(value) a(key,item) LOOP
   next_key:=entry.key;
   IF field_name='material_usage_variance_delta_by_component' AND next_key~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN next_key:=public.ob_rebase(next_key::uuid,seed)::text; END IF;
   result:=result||jsonb_build_object(next_key,CASE WHEN entry.key='custom' THEN entry.item ELSE public.production_clone_evidence(entry.item,seed,entry.key,target_org) END);
  END LOOP;
  RETURN result;
 END IF;
 RETURN value;
END $_$;


--
-- Name: production_clone_journal_evidence(jsonb, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.production_clone_journal_evidence(value jsonb, seed uuid, target_org uuid, masked boolean) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE selected jsonb;
BEGIN
 IF value IS NULL THEN RETURN NULL; END IF;
 IF NOT masked THEN RETURN public.production_clone_evidence(value,seed,'custom',target_org); END IF;
 -- Native accounting and trace links survive masking; arbitrary tenant fields and free text do not.
 SELECT coalesce(jsonb_object_agg(key,item),'{}'::jsonb) INTO selected FROM jsonb_each(value) object(key,item)
 WHERE key=ANY(ARRAY['work_order_number','bom_revision','routing_version','settlement_scope','operation_id','operation_sequence','conversion_labor_amount','conversion_overhead_amount','conversion_disposition','conversion','time_entry_id','time_entry_ids','labor_minutes_delta','labor_amount_delta','overhead_amount_delta','completion_quantity','completed_quantity','material_usage_variance_cumulative','material_usage_variance_delta_by_component','relieved_labor','relieved_overhead','labor_variance','overhead_variance','scrap_event_id','loss_change_id','loss_quantity','loss_value','subcontract_id','subcontract_consumption_key','subcontract_service_claim_id','subcontract_service_bill_id','subcontract_source_entry_id','subcontract_service_amount','subcontract_service_reversal_of','source_bill_entry_id','source_expenses','amends_time_entry_id','corrects_time_entry_id','byproductNrv','jointOutputCosts']);
 RETURN public.production_mask_evidence(public.production_clone_evidence(selected,seed,'custom',target_org));
END $$;


--
-- Name: production_clone_safe_evidence(jsonb, uuid, text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.production_clone_safe_evidence(value jsonb, seed uuid, field_name text, target_org uuid, masked boolean) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE result jsonb;
BEGIN
 result:=public.production_clone_evidence(value,seed,field_name,target_org);
 RETURN CASE WHEN masked THEN public.production_mask_evidence(result) ELSE result END;
END $$;


--
-- Name: production_mask_evidence(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.production_mask_evidence(value jsonb, field_name text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE result jsonb; entry record;
BEGIN
 IF value IS NULL THEN RETURN NULL; END IF;
 IF jsonb_typeof(value)='string' AND field_name='intent' THEN
  BEGIN RETURN to_jsonb(public.production_canonical_json(public.production_mask_evidence((value#>>'{}')::jsonb))); EXCEPTION WHEN invalid_text_representation THEN RETURN to_jsonb('REDACTED'::text); END;
 END IF;
 IF jsonb_typeof(value)='string' AND field_name IN('requestKey','requestId') AND (value#>>'{}')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RETURN to_jsonb('masked-'||md5(value#>>'{}')); END IF;
 IF jsonb_typeof(value)='string' AND lower(field_name)=ANY(ARRAY['reason','name','label','description','notes','memo','subjectlabel','finishreason','shortclosereason','singular','plural']) THEN RETURN to_jsonb('REDACTED'::text); END IF;
 IF jsonb_typeof(value)='object' THEN
  result:='{}'::jsonb;
  FOR entry IN SELECT key,item FROM jsonb_each(value) object(key,item) LOOP
   result:=result||jsonb_build_object(entry.key,CASE WHEN entry.key='custom' THEN '{}'::jsonb ELSE public.production_mask_evidence(entry.item,entry.key) END);
  END LOOP;
  RETURN result;
 ELSIF jsonb_typeof(value)='array' THEN
  SELECT coalesce(jsonb_agg(public.production_mask_evidence(item,field_name) ORDER BY ordinal),'[]'::jsonb) INTO result FROM jsonb_array_elements(value) WITH ORDINALITY array_item(item,ordinal);RETURN result;
 END IF;
 RETURN value;
END $_$;


--
-- Name: production_mrp_run_evidence_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.production_mrp_run_evidence_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' THEN
  IF public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
  IF OLD.status<>'draft' THEN RAISE EXCEPTION 'Completed planning evidence is retained; supersede it with a new run.' USING ERRCODE='23514'; END IF;
  RETURN OLD;
 END IF;
 IF (NEW.org_id,NEW.id) IS DISTINCT FROM (OLD.org_id,OLD.id) THEN RAISE EXCEPTION 'A planning run retains its organization and identity.' USING ERRCODE='23514'; END IF;
 IF OLD.status<>'draft' AND ((NEW.number,NEW.horizon_start,NEW.horizon_end,NEW.parameters,NEW.run_by,NEW.ran_at) IS DISTINCT FROM (OLD.number,OLD.horizon_start,OLD.horizon_end,OLD.parameters,OLD.run_by,OLD.ran_at) OR NEW.status NOT IN('complete','superseded') OR OLD.status='superseded' AND NEW.status<>'superseded') THEN
  RAISE EXCEPTION 'Completed planning inputs and capacity evidence are immutable.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: production_operation_time_snapshot_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.production_operation_time_snapshot_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF (NEW.labor_time_source,NEW.labor_minutes_per_unit) IS DISTINCT FROM (OLD.labor_time_source,OLD.labor_minutes_per_unit) THEN
  RAISE EXCEPTION 'Released operations keep their labor capture and standard minutes; release a replacement order.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: production_receipt_rework_loss_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.production_receipt_rework_loss_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE repair public.mfg_work_orders%ROWTYPE;failed public.inventory_inspections%ROWTYPE;issued numeric;
BEGIN
 IF public.openbooks_clone_authority() THEN RETURN NULL; END IF;
 SELECT * INTO repair FROM public.mfg_work_orders WHERE org_id=NEW.org_id AND id=NEW.id;
 IF NOT FOUND OR repair.receipt_rework_inspection_id IS NULL OR repair.loss_change_id IS NULL THEN RETURN NULL; END IF;
 SELECT * INTO failed FROM public.inventory_inspections WHERE org_id=repair.org_id AND id=repair.receipt_rework_inspection_id;
 SELECT coalesce(sum(-movement.quantity),0) INTO issued FROM public.inventory_movements movement JOIN public.journal_entries entry ON entry.org_id=movement.org_id AND entry.id=movement.journal_entry_id
  WHERE movement.org_id=repair.org_id AND entry.origin='manufacturing' AND entry.custom->>'work_order_number'=repair.number AND entry.status='posted' AND entry.reverses_entry_id IS NULL AND movement.kind='assembly_consume' AND movement.item_id=failed.item_id AND movement.lot_id IS NOT DISTINCT FROM failed.lot_id AND movement.serial_id IS NOT DISTINCT FROM failed.serial_id;
 IF failed.id IS NULL OR failed.rework_work_order_id IS DISTINCT FROM repair.id OR repair.status<>'cancelled' OR repair.quantity_completed<>0 OR repair.quantity_scrapped IS DISTINCT FROM failed.quantity OR issued IS DISTINCT FROM failed.quantity THEN
  RAISE EXCEPTION 'A received-stock repair loss must dispose its complete original inspected stock through a native issue and approved loss.' USING ERRCODE='23514';
 END IF;
 RETURN NULL;
END $$;


--
-- Name: production_service_bill_status_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.production_service_bill_status_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF (NEW.status,NEW.posted_entry_id,NEW.party_id,NEW.subsidiary_id) IS DISTINCT FROM (OLD.status,OLD.posted_entry_id,OLD.party_id,OLD.subsidiary_id)
   AND EXISTS(SELECT 1 FROM public.mfg_subcontract_service_bills claim JOIN public.journal_entries cost ON cost.org_id=claim.org_id AND cost.id=claim.capitalization_entry_id
     WHERE claim.org_id=OLD.org_id AND claim.bill_id=OLD.id AND cost.status='posted' AND claim.reversal_entry_id IS NULL) THEN
  RAISE EXCEPTION 'Reverse the production service capitalization before correcting its vendor bill.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: production_service_reversal_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.production_service_reversal_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE order_number text;
BEGIN
 IF NEW.reverses_entry_id IS NULL OR public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF EXISTS(SELECT 1 FROM public.mfg_subcontract_service_bills claim JOIN public.journal_entries cost ON cost.org_id=claim.org_id AND cost.id=claim.capitalization_entry_id
    WHERE claim.org_id=NEW.org_id AND claim.source_entry_id=NEW.reverses_entry_id AND cost.status='posted' AND claim.reversal_entry_id IS NULL) THEN
  RAISE EXCEPTION 'Reverse the production service capitalization before reversing its bill journal.' USING ERRCODE='23514';
 END IF;
 SELECT w.number INTO order_number FROM public.mfg_subcontract_service_bills claim JOIN public.mfg_subcontracts s ON s.org_id=claim.org_id AND s.id=claim.subcontract_id
    JOIN public.mfg_work_orders w ON w.org_id=s.org_id AND w.id=s.work_order_id WHERE claim.org_id=NEW.org_id AND claim.capitalization_entry_id=NEW.reverses_entry_id;
 IF order_number IS NOT NULL AND EXISTS(SELECT 1 FROM public.journal_entries e WHERE e.org_id=NEW.org_id AND e.origin='manufacturing' AND e.status='posted' AND e.reverses_entry_id IS NULL AND e.custom->>'work_order_number'=order_number AND e.custom ? 'completion_quantity') THEN
  RAISE EXCEPTION 'Reverse completed goods before reversing their production service cost.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: production_subcontract_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.production_subcontract_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' THEN
  IF public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'Production subcontracts retain their history.' USING ERRCODE='23514';
 END IF;
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND (NEW.id,NEW.org_id,NEW.work_order_id,NEW.operation_id,NEW.vendor_id,NEW.custody_location_id,NEW.quantity_expected,NEW.request_snapshot,NEW.created_at,NEW.created_by)
  IS DISTINCT FROM (OLD.id,OLD.org_id,OLD.work_order_id,OLD.operation_id,OLD.vendor_id,OLD.custody_location_id,OLD.quantity_expected,OLD.request_snapshot,OLD.created_at,OLD.created_by) THEN
  RAISE EXCEPTION 'Production subcontract subject and vendor are immutable.' USING ERRCODE='23514';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.mfg_wo_operations o JOIN public.stock_locations l ON l.org_id=o.org_id
  WHERE o.org_id=NEW.org_id AND o.id=NEW.operation_id AND o.work_order_id=NEW.work_order_id
    AND o.quantity_planned=NEW.quantity_expected AND o.backflush_at='none'
    AND l.id=NEW.custody_location_id AND l.kind='subcontract' AND l.inventory_ownership='owned' AND l.custodian_party_id=NEW.vendor_id) THEN
  RAISE EXCEPTION 'Use the released operation and its matching company-owned vendor custody location.' USING ERRCODE='23514';
 END IF;
 IF TG_OP='UPDATE' AND NEW.status IS DISTINCT FROM OLD.status AND NOT (
   (OLD.status='ready' AND NEW.status IN('sent','received','cancelled')) OR (OLD.status='sent' AND NEW.status='received')) THEN
  RAISE EXCEPTION 'Invalid production subcontract transition.' USING ERRCODE='23514';
 END IF;
 IF NEW.status='received' AND NOT EXISTS(SELECT 1 FROM public.mfg_wo_operations o WHERE o.org_id=NEW.org_id AND o.id=NEW.operation_id AND o.status='done'
   AND o.quantity_done=(SELECT coalesce(sum(quantity),0) FROM public.mfg_subcontract_returns WHERE org_id=NEW.org_id AND subcontract_id=NEW.id)
   AND EXISTS(SELECT 1 FROM public.mfg_subcontract_returns WHERE org_id=NEW.org_id AND subcontract_id=NEW.id AND request_snapshot->>'finish'='true')) THEN
  RAISE EXCEPTION 'Finish the actual returned vendor operation before closing its subcontract.' USING ERRCODE='23514';
 END IF;
 IF NEW.status='cancelled' AND (length(btrim(NEW.cancel_reason)) NOT BETWEEN 5 AND 500
   OR EXISTS(SELECT 1 FROM public.mfg_subcontract_shipments WHERE org_id=NEW.org_id AND subcontract_id=NEW.id)
   OR EXISTS(SELECT 1 FROM public.mfg_subcontract_returns WHERE org_id=NEW.org_id AND subcontract_id=NEW.id)
   OR EXISTS(SELECT 1 FROM public.mfg_subcontract_service_bills WHERE org_id=NEW.org_id AND subcontract_id=NEW.id AND reversal_entry_id IS NULL)) THEN
  RAISE EXCEPTION 'Only a subcontract without physical or active cost activity may be cancelled, with a reason.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: production_subcontract_material_return_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.production_subcontract_material_return_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Component returns retain their native transfer evidence.' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.mfg_subcontract_shipments shipment
  JOIN public.mfg_subcontracts contract ON contract.org_id=shipment.org_id AND contract.id=shipment.subcontract_id
  JOIN public.mfg_work_orders work ON work.org_id=contract.org_id AND work.id=contract.work_order_id
  JOIN public.inventory_movements delivered ON delivered.org_id=shipment.org_id AND delivered.id=shipment.to_movement_id
  JOIN public.inventory_movements outbound ON outbound.org_id=shipment.org_id AND outbound.id=NEW.from_movement_id
  JOIN public.inventory_movements inbound ON inbound.org_id=shipment.org_id AND inbound.id=NEW.to_movement_id
  WHERE shipment.org_id=NEW.org_id AND shipment.id=NEW.shipment_id AND contract.id=NEW.subcontract_id
   AND delivered.status='posted' AND outbound.status='posted' AND inbound.status='posted'
   AND outbound.kind='transfer_out' AND inbound.kind='transfer_in' AND inbound.paired_movement_id=outbound.id
   AND outbound.stock_location_id=contract.custody_location_id AND inbound.stock_location_id=shipment.source_location_id
   AND outbound.item_id=delivered.item_id AND inbound.item_id=delivered.item_id
   AND outbound.subsidiary_id=work.subsidiary_id AND inbound.subsidiary_id=work.subsidiary_id
   AND outbound.lot_id IS NOT DISTINCT FROM delivered.lot_id AND inbound.lot_id IS NOT DISTINCT FROM delivered.lot_id
   AND outbound.serial_id IS NOT DISTINCT FROM delivered.serial_id AND inbound.serial_id IS NOT DISTINCT FROM delivered.serial_id
   AND outbound.quantity=-NEW.quantity AND inbound.quantity=NEW.quantity AND outbound.total_value=-NEW.value AND inbound.total_value=NEW.value
   AND (SELECT coalesce(sum(consumption.quantity),0) FROM public.cost_layer_consumptions consumption JOIN public.cost_layers layer ON layer.org_id=consumption.org_id AND layer.id=consumption.cost_layer_id
     WHERE consumption.org_id=NEW.org_id AND consumption.issue_movement_id=outbound.id AND layer.source_movement_id=delivered.id)=NEW.quantity
   AND NOT EXISTS(SELECT 1 FROM public.cost_layer_consumptions consumption JOIN public.cost_layers layer ON layer.org_id=consumption.org_id AND layer.id=consumption.cost_layer_id
     WHERE consumption.org_id=NEW.org_id AND consumption.issue_movement_id=outbound.id AND layer.source_movement_id IS DISTINCT FROM delivered.id)) THEN
  RAISE EXCEPTION 'Return unused stock through its actual original shipment and valued paired transfer.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: production_subcontract_return_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.production_subcontract_return_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE expected numeric; previous numeric; losses numeric; contract_status text;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Vendor deliveries retain their physical return evidence.' USING ERRCODE='23514'; END IF;
 SELECT s.quantity_expected,s.status,o.quantity_scrapped_here INTO expected,contract_status,losses
 FROM public.mfg_subcontracts s JOIN public.mfg_wo_operations o ON o.org_id=s.org_id AND o.id=s.operation_id
 JOIN public.mfg_work_orders w ON w.org_id=s.org_id AND w.id=s.work_order_id
 WHERE s.org_id=NEW.org_id AND s.id=NEW.subcontract_id AND w.status IN('released','in_progress') AND o.status='running'
 FOR UPDATE OF s,o,w;
 IF expected IS NULL OR contract_status NOT IN('ready','sent') THEN RAISE EXCEPTION 'Record a delivery on the open vendor operation.' USING ERRCODE='23514'; END IF;
 SELECT coalesce(sum(quantity),0) INTO previous FROM public.mfg_subcontract_returns WHERE org_id=NEW.org_id AND subcontract_id=NEW.subcontract_id;
 IF previous+NEW.quantity+losses>expected OR NEW.request_snapshot->>'id' IS DISTINCT FROM NEW.id::text
  OR NEW.request_snapshot->>'subcontractId' IS DISTINCT FROM NEW.subcontract_id::text
  OR (NEW.request_snapshot->>'quantity')::numeric IS DISTINCT FROM NEW.quantity
  OR jsonb_typeof(NEW.request_snapshot->'finish') IS DISTINCT FROM 'boolean'
  OR NEW.request_snapshot->>'finishReason' IS DISTINCT FROM NEW.finish_reason THEN
  RAISE EXCEPTION 'Vendor return quantity and its recorded request must agree with the remaining operation.' USING ERRCODE='23514';
 END IF;
 IF NEW.request_snapshot->>'finish'='true' AND previous+NEW.quantity+losses<expected AND NEW.finish_reason IS NULL THEN
  RAISE EXCEPTION 'Finishing a vendor operation short requires a retained reason.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: production_subcontract_service_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.production_subcontract_service_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE cost numeric; actual_expenses jsonb; wo_number text;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Posted production service costs retain their history.' USING ERRCODE='23514'; END IF;
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' THEN
  IF (NEW.id,NEW.org_id,NEW.subcontract_id,NEW.bill_id,NEW.source_entry_id,NEW.capitalization_entry_id,NEW.wip_account_id,NEW.amount,NEW.expense_snapshot,NEW.created_at,NEW.created_by)
   IS DISTINCT FROM (OLD.id,OLD.org_id,OLD.subcontract_id,OLD.bill_id,OLD.source_entry_id,OLD.capitalization_entry_id,OLD.wip_account_id,OLD.amount,OLD.expense_snapshot,OLD.created_at,OLD.created_by)
   OR OLD.reversal_entry_id IS NOT NULL THEN RAISE EXCEPTION 'Production service cost is immutable; record a governed reversal.' USING ERRCODE='23514'; END IF;
  IF NEW.reversal_entry_id IS NULL OR length(btrim(NEW.reversal_reason)) NOT BETWEEN 5 AND 500
    OR NOT EXISTS(SELECT 1 FROM public.journal_entries e WHERE e.org_id=NEW.org_id AND e.id=NEW.reversal_entry_id AND e.reverses_entry_id=OLD.capitalization_entry_id AND e.status='posted') THEN
   RAISE EXCEPTION 'Use the actual posted service-cost reversal and its reason.' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.mfg_subcontracts s JOIN public.mfg_work_orders w ON w.org_id=s.org_id AND w.id=s.work_order_id
   JOIN public.documents d ON d.org_id=s.org_id AND d.id=NEW.bill_id
   JOIN public.journal_entries e ON e.org_id=d.org_id AND e.id=d.posted_entry_id
   WHERE s.org_id=NEW.org_id AND s.id=NEW.subcontract_id AND s.status IN('ready','sent','received')
     AND d.kind='vendor_bill' AND d.status='posted' AND d.party_id=s.vendor_id AND d.subsidiary_id=w.subsidiary_id
     AND e.id=NEW.source_entry_id AND e.source_document_id=d.id AND e.subsidiary_id=w.subsidiary_id AND e.status='posted' AND e.reverses_entry_id IS NULL) THEN
  RAISE EXCEPTION 'Production service cost requires its actual vendor bill and posted source journal.' USING ERRCODE='23514';
 END IF;
 SELECT coalesce(sum(l.amount),0),coalesce(jsonb_agg(jsonb_build_object('accountId',l.account_id::text,'amount',l.amount::text,'departmentId',l.department_id,'locationId',l.location_id) ORDER BY l.line_number),'[]'::jsonb) INTO cost,actual_expenses
  FROM public.journal_lines l JOIN public.accounts a ON a.org_id=l.org_id AND a.id=l.account_id
  WHERE l.org_id=NEW.org_id AND l.entry_id=NEW.source_entry_id AND a.type IN('cogs','expense','expense_other');
 IF actual_expenses='[]'::jsonb OR NEW.amount<>cost OR NEW.expense_snapshot<>actual_expenses THEN
  RAISE EXCEPTION 'Capitalize the bill’s actual functional-currency service expense lines.' USING ERRCODE='23514';
 END IF;
 SELECT w.number INTO wo_number FROM public.mfg_subcontracts s JOIN public.mfg_work_orders w ON w.org_id=s.org_id AND w.id=s.work_order_id WHERE s.org_id=NEW.org_id AND s.id=NEW.subcontract_id;
 IF NEW.amount>0 AND (NOT EXISTS(SELECT 1 FROM public.journal_entries e WHERE e.org_id=NEW.org_id AND e.id=NEW.capitalization_entry_id AND e.origin='manufacturing' AND e.status='posted' AND e.reverses_entry_id IS NULL
    AND e.custom->>'work_order_number'=wo_number AND e.custom->>'subcontract_id'=NEW.subcontract_id::text AND e.custom->>'subcontract_service_bill_id'=NEW.bill_id::text AND e.custom->>'subcontract_service_claim_id'=NEW.id::text AND e.custom->>'source_bill_entry_id'=NEW.source_entry_id::text)
   OR (SELECT coalesce(sum(amount),0) FROM public.journal_lines WHERE org_id=NEW.org_id AND entry_id=NEW.capitalization_entry_id AND account_id=NEW.wip_account_id)<>NEW.amount) THEN
  RAISE EXCEPTION 'Use the balanced native manufacturing service-capitalization journal.' USING ERRCODE='23514';
 END IF;
 IF NEW.amount>0 AND EXISTS (
  WITH expected AS (SELECT l.account_id,l.subsidiary_id,l.department_id,l.location_id,sum(l.amount) AS amount
   FROM public.journal_lines l JOIN public.accounts a ON a.org_id=l.org_id AND a.id=l.account_id
   WHERE l.org_id=NEW.org_id AND l.entry_id=NEW.source_entry_id AND a.type IN('cogs','expense','expense_other')
   GROUP BY l.account_id,l.subsidiary_id,l.department_id,l.location_id),
  actual AS (SELECT account_id,subsidiary_id,department_id,location_id,sum(-amount) AS amount FROM public.journal_lines
   WHERE org_id=NEW.org_id AND entry_id=NEW.capitalization_entry_id AND account_id<>NEW.wip_account_id
   GROUP BY account_id,subsidiary_id,department_id,location_id)
  SELECT 1 FROM expected e FULL JOIN actual a ON a.account_id=e.account_id AND a.subsidiary_id IS NOT DISTINCT FROM e.subsidiary_id
   AND a.department_id IS NOT DISTINCT FROM e.department_id AND a.location_id IS NOT DISTINCT FROM e.location_id
  WHERE e.account_id IS NULL OR a.account_id IS NULL OR e.amount<>a.amount
 ) THEN RAISE EXCEPTION 'Production capitalization must reverse the bill’s exact expense accounts and dimensions.' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: production_subcontract_shipment_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.production_subcontract_shipment_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Posted production shipments are immutable; return stock through native transfers.' USING ERRCODE='23514'; END IF;
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.mfg_subcontracts s
   JOIN public.mfg_work_orders w ON w.org_id=s.org_id AND w.id=s.work_order_id
   JOIN public.mfg_wo_materials material ON material.org_id=w.org_id AND material.work_order_id=w.id AND material.id=NEW.material_id
   JOIN public.inventory_movements outbound ON outbound.org_id=s.org_id AND outbound.id=NEW.from_movement_id
   JOIN public.inventory_movements inbound ON inbound.org_id=s.org_id AND inbound.id=NEW.to_movement_id
   WHERE s.org_id=NEW.org_id AND s.id=NEW.subcontract_id AND s.status IN('ready','sent')
     AND outbound.status='posted' AND inbound.status='posted' AND outbound.kind='transfer_out' AND inbound.kind='transfer_in'
     AND outbound.subsidiary_id=w.subsidiary_id AND inbound.subsidiary_id=w.subsidiary_id
     AND outbound.item_id=material.component_item_id AND inbound.item_id=material.component_item_id
     AND outbound.stock_location_id=NEW.source_location_id AND inbound.stock_location_id=s.custody_location_id
     AND inbound.paired_movement_id=outbound.id AND outbound.quantity=-NEW.quantity AND inbound.quantity=NEW.quantity
     AND outbound.total_value=-NEW.value AND inbound.total_value=NEW.value
     AND outbound.lot_id IS NOT DISTINCT FROM inbound.lot_id AND outbound.serial_id IS NOT DISTINCT FROM inbound.serial_id
     AND NOT EXISTS(SELECT 1 FROM public.inventory_movements reversal WHERE reversal.org_id=s.org_id AND reversal.reverses_movement_id IN(outbound.id,inbound.id) AND reversal.status='posted')) THEN
  RAISE EXCEPTION 'A production shipment requires its actual valued native transfer, operation material and vendor custody.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: production_time_history_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.production_time_history_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF OLD.production_consumed_operation_id IS NULL THEN IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END IF;
 IF TG_OP='DELETE' THEN
  IF public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'Consumed production time is immutable; record a governed time correction.' USING ERRCODE='23514';
 END IF;
 IF to_jsonb(NEW)-ARRAY['updated_at','updated_by','payroll_batch_ref'] IS DISTINCT FROM to_jsonb(OLD)-ARRAY['updated_at','updated_by','payroll_batch_ref'] THEN
  RAISE EXCEPTION 'Consumed production time is immutable; record a governed time correction.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: production_work_center_cost_identity_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.production_work_center_cost_identity_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF (NEW.kind,NEW.absorbs_overhead) IS DISTINCT FROM (OLD.kind,OLD.absorbs_overhead)
  AND EXISTS(SELECT 1 FROM public.mfg_wo_operations WHERE org_id=OLD.org_id AND work_center_id=OLD.id) THEN
  RAISE EXCEPTION 'Create a new work center for a changed kind or overhead treatment; released operations retain their cost classification.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: project_delivery_evidence_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.project_delivery_evidence_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF public.app_bypass_rls_active() AND coalesce(current_setting('openbooks.amend', true), 'off') = 'on' THEN
   IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
   RETURN NEW;
 END IF;
 RAISE EXCEPTION '% is retained as recorded; append a correcting record instead of changing or deleting it', TG_TABLE_NAME
   USING ERRCODE = '23514';
END $$;


--
-- Name: project_financial_adjustment_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.project_financial_adjustment_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF tg_op = 'DELETE'
     AND openbooks_sandbox_wipe_allowed(old.org_id)
  THEN
    RETURN old;
  END IF;
  IF tg_op IN ('UPDATE', 'DELETE') THEN
    RAISE EXCEPTION
      'project financial adjustments are append-only; post a reversing adjustment';
  END IF;
  IF NOT EXISTS (
    SELECT 1
      FROM projects p
     WHERE p.id = new.project_id
       AND p.org_id = new.org_id
  ) THEN
    RAISE EXCEPTION
      'project financial adjustment must belong to the project organization';
  END IF;
  IF new.reverses_adjustment_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
      FROM project_financial_adjustments original
     WHERE original.id = new.reverses_adjustment_id
       AND original.org_id = new.org_id
       AND original.project_id = new.project_id
       AND original.measure = new.measure
       AND original.amount = -new.amount
  ) THEN
    RAISE EXCEPTION
      'a reversing project financial adjustment must exactly offset the same project and measure';
  END IF;
  RETURN new;
END;
$$;


--
-- Name: project_financial_profile_version_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.project_financial_profile_version_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  publish_mode boolean :=
    coalesce(current_setting('openbooks.publish_project_profile', true), 'off') = 'on';
  correction_mode boolean :=
    coalesce(current_setting('openbooks.correct_project_profile', true), 'off') = 'on';
  correction_reason text :=
    coalesce(current_setting('openbooks.project_profile_correction_reason', true), '');
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF tg_op = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(old.org_id) THEN
    RETURN old;
  END IF;
  IF tg_op <> 'DELETE' AND NOT EXISTS (
    SELECT 1
      FROM project_types pt
     WHERE pt.id = new.project_type_id
       AND pt.org_id = new.org_id
  ) THEN
    RAISE EXCEPTION
      'project financial profile version must belong to the project type organization';
  END IF;

  IF tg_op = 'DELETE' THEN
    RAISE EXCEPTION 'published project financial profile versions are immutable';
  END IF;

  IF tg_op = 'UPDATE' THEN
    IF correction_mode THEN
      IF length(btrim(correction_reason)) < 8
         OR (to_jsonb(new) - 'financial_profile' - 'updated_at' - 'updated_by')
            IS DISTINCT FROM
            (to_jsonb(old) - 'financial_profile' - 'updated_at' - 'updated_by')
      THEN
        RAISE EXCEPTION
          'controlled project financial profile correction may change only policy JSON and requires a reason';
      END IF;
    ELSIF NOT publish_mode
       OR (to_jsonb(new) - 'effective_to' - 'updated_at' - 'updated_by')
          IS DISTINCT FROM
          (to_jsonb(old) - 'effective_to' - 'updated_at' - 'updated_by')
    THEN
      RAISE EXCEPTION 'published project financial profile versions are immutable';
    END IF;
  END IF;

  -- Effective-range exclusivity is owned by the
  -- project_financial_profile_versions_no_overlap exclusion constraint
  -- (0051). Publish-mode window closing and correction-mode immutability
  -- above are unchanged.
  RETURN new;
END;
$$;


--
-- Name: FUNCTION project_financial_profile_version_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.project_financial_profile_version_guard() IS 'openbooks:project_financial_profile_version_guard:v3 - authorized sandbox teardown; publish/correct-mode immutability for project financial profile versions; effective-range exclusivity moved to the project_financial_profile_versions_no_overlap exclusion constraint';


--
-- Name: project_overhead_adjustment_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.project_overhead_adjustment_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF tg_op = 'DELETE'
     AND openbooks_sandbox_wipe_allowed(old.org_id)
  THEN
    RETURN old;
  END IF;
  IF tg_op IN ('UPDATE', 'DELETE') THEN
    RAISE EXCEPTION
      'project overhead adjustments are append-only; post a reversing adjustment';
  END IF;
  IF NOT EXISTS (
    SELECT 1
      FROM projects p
     WHERE p.id = new.project_id
       AND p.org_id = new.org_id
  ) THEN
    RAISE EXCEPTION
      'project overhead adjustment must belong to the project organization';
  END IF;
  IF new.reverses_adjustment_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
      FROM project_overhead_adjustments original
     WHERE original.id = new.reverses_adjustment_id
       AND original.org_id = new.org_id
       AND original.project_id = new.project_id
       AND original.amount = -new.amount
  ) THEN
    RAISE EXCEPTION
      'a reversing overhead adjustment must exactly offset the same project';
  END IF;
  RETURN new;
END;
$$;


--
-- Name: projects_internal_flag_locked(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.projects_internal_flag_locked() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.is_internal IS DISTINCT FROM NEW.is_internal AND EXISTS (
    SELECT 1 FROM time_entries WHERE org_id = NEW.org_id AND project_id = NEW.id
  ) THEN
    RAISE EXCEPTION 'project % has booked time and its internal flag is immutable', NEW.id
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: property_financial_evidence_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.property_financial_evidence_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF openbooks_sandbox_wipe_allowed(CASE WHEN TG_OP='DELETE' THEN OLD.org_id ELSE NEW.org_id END) THEN
    RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
  END IF;
  RAISE EXCEPTION 'property financial evidence is append-only';
END $$;


--
-- Name: protect_application_idempotency_key(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_application_idempotency_key() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF OLD.expires_at <= now()
       OR public.app_bypass_rls_active() THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'unexpired application idempotency evidence cannot be deleted';
  END IF;

  IF OLD.completed_at IS NULL
     AND NEW.completed_at IS NOT NULL
     AND NEW.response IS NOT NULL
     AND NEW.org_id = OLD.org_id
     AND NEW.actor_id = OLD.actor_id
     AND NEW.source = OLD.source
     AND NEW.operation = OLD.operation
     AND NEW.idempotency_key = OLD.idempotency_key
     AND NEW.request_hash = OLD.request_hash
     AND NEW.created_at = OLD.created_at
     AND NEW.expires_at = OLD.expires_at THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'application idempotency evidence is immutable after creation';
END;
$$;


--
-- Name: protect_country_tax_pack_installation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_country_tax_pack_installation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'country tax pack installation evidence is immutable';
  END IF;
  IF OLD.status = 'active'
     AND NEW.status = 'superseded'
     AND NEW.org_id = OLD.org_id
     AND NEW.pack_code = OLD.pack_code
     AND NEW.country = OLD.country
     AND NEW.version = OLD.version
     AND NEW.content_hash = OLD.content_hash
     AND NEW.manifest = OLD.manifest
     AND NEW.installed_at = OLD.installed_at
     AND NEW.installed_by IS NOT DISTINCT FROM OLD.installed_by
     AND NEW.superseded_at IS NOT NULL THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'country tax pack installation may only transition from active to superseded';
END;
$$;


--
-- Name: protect_org_base_price_level(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_org_base_price_level() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    IF OLD.is_base THEN
      RAISE EXCEPTION 'The organization base price level must remain active; edit its name or add another price level instead';
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.customer_price_level_assignments assignment
       WHERE assignment.org_id = OLD.org_id AND assignment.price_level_id = OLD.id AND assignment.is_active
      UNION ALL
      SELECT 1 FROM public.item_price_schedules schedule
       WHERE schedule.org_id = OLD.org_id AND schedule.price_level_id = OLD.id AND schedule.is_active
    ) THEN
      RAISE EXCEPTION 'Price level % is still in use; deactivate its customer assignments and item pricing schedules first', OLD.id;
    END IF;
    RETURN OLD;
  END IF;
  IF OLD.is_base AND (NOT NEW.is_base OR NOT NEW.is_active OR NEW.org_id <> OLD.org_id) THEN
    RAISE EXCEPTION 'The organization base price level must remain active; edit its name or add another price level instead';
  END IF;
  IF OLD.is_active AND NOT NEW.is_active AND EXISTS (
    SELECT 1 FROM public.customer_price_level_assignments assignment
     WHERE assignment.org_id = OLD.org_id AND assignment.price_level_id = OLD.id AND assignment.is_active
    UNION ALL
    SELECT 1 FROM public.item_price_schedules schedule
     WHERE schedule.org_id = OLD.org_id AND schedule.price_level_id = OLD.id AND schedule.is_active
  ) THEN
    RAISE EXCEPTION 'Price level % is still in use; deactivate its customer assignments and item pricing schedules first', OLD.id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: protect_pricing_customer_role(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_pricing_customer_role() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    IF OLD.is_active AND EXISTS (
      SELECT 1 FROM public.customer_price_level_assignments assignment
       WHERE assignment.org_id = OLD.org_id AND assignment.customer_id = OLD.party_id AND assignment.is_active
      UNION ALL
      SELECT 1 FROM public.item_price_schedules schedule
       WHERE schedule.org_id = OLD.org_id AND schedule.customer_id = OLD.party_id AND schedule.is_active
    ) THEN
      RAISE EXCEPTION 'Customer % has active pricing; deactivate its price-level assignments and item pricing schedules first', OLD.party_id;
    END IF;
    RETURN OLD;
  END IF;
  IF OLD.is_active AND NOT NEW.is_active AND EXISTS (
    SELECT 1 FROM public.customer_price_level_assignments assignment
     WHERE assignment.org_id = OLD.org_id AND assignment.customer_id = OLD.party_id AND assignment.is_active
    UNION ALL
    SELECT 1 FROM public.item_price_schedules schedule
     WHERE schedule.org_id = OLD.org_id AND schedule.customer_id = OLD.party_id AND schedule.is_active
  ) THEN
    RAISE EXCEPTION 'Customer % has active pricing; deactivate its price-level assignments and item pricing schedules first', OLD.party_id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: protect_report_run_authorization(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_report_run_authorization() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  old_snapshot jsonb;
  old_renders jsonb;
  new_renders jsonb;
  entry jsonb;
  reach jsonb;
BEGIN
  IF NEW.authorization_snapshot IS NOT DISTINCT FROM OLD.authorization_snapshot THEN
    RETURN NEW;
  END IF;
  -- A missing snapshot behaves like an empty one: it may gain only the
  -- recorded keys below.
  old_snapshot := coalesce(OLD.authorization_snapshot, '{}'::jsonb);
  IF jsonb_typeof(old_snapshot) <> 'object' OR jsonb_typeof(NEW.authorization_snapshot) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'report run authorization_snapshot evidence is immutable';
  END IF;
  -- Every key other than the two recorded ones is identical.
  IF (NEW.authorization_snapshot - 'requiredPermissions' - 'renders')
     IS DISTINCT FROM (old_snapshot - 'requiredPermissions' - 'renders') THEN
    RAISE EXCEPTION 'report run authorization_snapshot evidence is immutable';
  END IF;
  -- The content-permission key is recorded once, as an array, and never moves.
  IF old_snapshot ? 'requiredPermissions' THEN
    IF NEW.authorization_snapshot->'requiredPermissions' IS DISTINCT FROM old_snapshot->'requiredPermissions' THEN
      RAISE EXCEPTION 'report run authorization_snapshot evidence is immutable';
    END IF;
  ELSIF NEW.authorization_snapshot ? 'requiredPermissions'
        AND jsonb_typeof(NEW.authorization_snapshot->'requiredPermissions') <> 'array' THEN
    RAISE EXCEPTION 'report run authorization_snapshot evidence is immutable';
  END IF;
  -- Render evidence is append-only: the earlier entries unchanged, plus at
  -- most one new, well-formed entry per write.
  IF old_snapshot ? 'renders' AND NOT NEW.authorization_snapshot ? 'renders' THEN
    RAISE EXCEPTION 'report run authorization_snapshot evidence is immutable';
  END IF;
  old_renders := coalesce(old_snapshot->'renders', '[]'::jsonb);
  new_renders := coalesce(NEW.authorization_snapshot->'renders', '[]'::jsonb);
  IF jsonb_typeof(old_renders) <> 'array' OR jsonb_typeof(new_renders) <> 'array' THEN
    RAISE EXCEPTION 'report run authorization_snapshot evidence is immutable';
  END IF;
  IF new_renders IS DISTINCT FROM old_renders THEN
    IF jsonb_array_length(new_renders) <> jsonb_array_length(old_renders) + 1
       OR (new_renders - (jsonb_array_length(new_renders) - 1)) IS DISTINCT FROM old_renders THEN
      RAISE EXCEPTION 'report run render evidence is append-only';
    END IF;
    entry := new_renders->(jsonb_array_length(new_renders) - 1);
    reach := entry->'expenseRows';
    IF jsonb_typeof(entry) <> 'object'
       OR (entry - 'renderedAt' - 'expenseRows' - 'contentHash') <> '{}'::jsonb
       OR jsonb_typeof(entry->'renderedAt') IS DISTINCT FROM 'string'
       OR NOT entry ? 'expenseRows'
       OR (entry ? 'contentHash' AND jsonb_typeof(entry->'contentHash') <> 'string')
       OR NOT (
         jsonb_typeof(reach) = 'null'
         OR (jsonb_typeof(reach) = 'object' AND reach IN ('{"scope":"all"}'::jsonb, '{"scope":"none"}'::jsonb))
         OR (jsonb_typeof(reach) = 'object' AND reach->>'scope' = 'own'
             AND jsonb_typeof(reach->'userId') = 'string' AND (reach - 'scope' - 'userId') = '{}'::jsonb)
       ) THEN
      RAISE EXCEPTION 'report run render evidence entry is malformed';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: protect_tax_provision_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_tax_provision_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE'
     AND openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF OLD.status <> 'draft' THEN
      RAISE EXCEPTION
        'finalized income-tax provision runs are append-only (run %, status %)',
        OLD.id, OLD.status;
    END IF;
    RETURN OLD;
  END IF;

  IF OLD.status IN ('discarded', 'superseded') THEN
    RAISE EXCEPTION
      'finalized income-tax provision runs are immutable (run %, status %)',
      OLD.id, OLD.status;
  END IF;

  IF OLD.status = 'posted' AND NEW.status <> 'superseded' THEN
    RAISE EXCEPTION
      'posted income-tax provision runs may only transition to superseded (run %)',
      OLD.id;
  END IF;

  IF OLD.status = 'posted' AND (
    NEW.org_id IS DISTINCT FROM OLD.org_id
    OR NEW.fiscal_year IS DISTINCT FROM OLD.fiscal_year
    OR NEW.period_from IS DISTINCT FROM OLD.period_from
    OR NEW.period_to IS DISTINCT FROM OLD.period_to
    OR NEW.version IS DISTINCT FROM OLD.version
    OR NEW.snapshot_hash IS DISTINCT FROM OLD.snapshot_hash
    OR NEW.payload IS DISTINCT FROM OLD.payload
    OR NEW.journal_entry_id IS DISTINCT FROM OLD.journal_entry_id
    OR NEW.posted_at IS DISTINCT FROM OLD.posted_at
    OR NEW.posted_by IS DISTINCT FROM OLD.posted_by
    OR NEW.created_at IS DISTINCT FROM OLD.created_at
    OR NEW.created_by IS DISTINCT FROM OLD.created_by
  ) THEN
    RAISE EXCEPTION
      'posted income-tax provision evidence is immutable (run %)',
      OLD.id;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: protect_temporary_difference_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_temporary_difference_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  target_org_id uuid;
  target_run_id uuid;
  target_status text;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  target_org_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.org_id ELSE NEW.org_id END;
  IF TG_OP = 'DELETE'
     AND openbooks_sandbox_wipe_allowed(target_org_id) THEN
    RETURN OLD;
  END IF;

  target_run_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.run_id ELSE NEW.run_id END;
  SELECT status
    INTO target_status
    FROM tax_provision_runs
   WHERE id = target_run_id
     AND org_id = target_org_id;

  IF target_status IS NULL THEN
    RAISE EXCEPTION 'temporary difference must reference a tenant-owned provision run';
  END IF;
  IF target_status <> 'draft' THEN
    RAISE EXCEPTION
      'temporary differences are immutable after provision finalization (run %, status %)',
      target_run_id, target_status;
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: provider_return_approval_fingerprint(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.provider_return_approval_fingerprint(organization uuid, subject uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
 SELECT public.flow_command_record_fingerprint(to_jsonb(d)-ARRAY['status_history','reason'],jsonb_build_object(
  'refundSource',(SELECT entry->'refundSource' FROM jsonb_array_elements(d.status_history) WITH ORDINALITY e(entry,ord) WHERE entry ? 'refundSource' ORDER BY ord DESC LIMIT 1),
  'pendingAction',(SELECT entry->'pendingAction' FROM jsonb_array_elements(d.status_history) WITH ORDINALITY e(entry,ord) WHERE entry ? 'pendingAction' ORDER BY ord DESC LIMIT 1),
  'pendingEvent',(SELECT entry->'event' FROM jsonb_array_elements(d.status_history) WITH ORDINALITY e(entry,ord) WHERE entry ? 'pendingAction' ORDER BY ord DESC LIMIT 1)))
 FROM public.payment_disputes d WHERE d.org_id=organization AND d.id=subject
$$;


--
-- Name: provider_return_command_approved(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.provider_return_command_approved(organization uuid, subject uuid, action text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT 1 FROM public.flow_submissions s WHERE s.org_id=organization
  AND s.subject_kind='payment_dispute_review' AND s.subject_id=subject AND s.policy->>'kind'='gated'
  AND s.context->>'approvalFingerprint'=public.provider_return_approval_fingerprint(organization,subject)
  AND s.context->'command'=jsonb_build_object('action',action)
  AND public.flow_submission_approved(organization,'payment_dispute_review',subject,s.id))
$$;


--
-- Name: provision_change_binding_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.provision_change_binding_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.domain='provision' AND NOT EXISTS (
    SELECT 1 FROM public.provision_obligations p WHERE p.org_id=NEW.org_id
      AND p.id=NEW.subject_id AND p.subsidiary_id=NEW.subsidiary_id
      AND NEW.operation='provision_assessment'
      AND NEW.payload->'requiredSubsidiaryIds'=jsonb_build_array(p.subsidiary_id::text)
  ) THEN
    RAISE EXCEPTION 'provision assessment must bind to its organization and legal entity';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: provision_identity_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.provision_identity_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF public.app_bypass_rls_active() AND coalesce(current_setting('openbooks.amend',true),'off')='on' THEN
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'provision accounting identity is immutable; release the old obligation through an approved assessment and create the corrected obligation';
END
$$;


--
-- Name: provision_project_binding(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.provision_project_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.project_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.projects p WHERE p.org_id=NEW.org_id
    AND p.id=NEW.project_id AND p.subsidiary_id=NEW.subsidiary_id) THEN
    RAISE EXCEPTION 'construction loss provision must bind to the project legal entity';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: putaway_rules_target_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.putaway_rules_target_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  target_code text;
  warehouse_code text;
BEGIN
  IF public.stock_location_warehouse(NEW.org_id, NEW.target_location_id) IS DISTINCT FROM NEW.warehouse_id THEN
    SELECT code INTO target_code FROM public.stock_locations WHERE id = NEW.target_location_id AND org_id = NEW.org_id;
    SELECT code INTO warehouse_code FROM public.stock_locations WHERE id = NEW.warehouse_id AND org_id = NEW.org_id;
    RAISE EXCEPTION 'putaway target % is not inside warehouse %; choose a bin or zone under that warehouse',
      coalesce(target_code, NEW.target_location_id::text), coalesce(warehouse_code, NEW.warehouse_id::text)
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: rate_adjustment_target_version_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rate_adjustment_target_version_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_status text;
  v_org_id uuid;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  SELECT version.status, adjustment.org_id
    INTO v_status, v_org_id
    FROM labor_rate_adjustments adjustment
    JOIN item_rate_versions version
      ON version.id = adjustment.version_id
     AND version.org_id = adjustment.org_id
   WHERE adjustment.id = coalesce(NEW.adjustment_id, OLD.adjustment_id);
  IF v_status IS NULL
     OR v_org_id IS DISTINCT FROM coalesce(NEW.org_id, OLD.org_id) THEN
    RAISE EXCEPTION 'adjustment target must reference a tenant-owned rate version'
      USING ERRCODE = '23514';
  END IF;
  IF v_status <> 'draft' THEN
    IF TG_OP = 'DELETE'
       AND openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'targets of an activated or retired rate version are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END
$$;


--
-- Name: rate_book_currency_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rate_book_currency_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
    IF EXISTS (
      SELECT 1 FROM item_rate_versions version
       WHERE version.rate_book_id = OLD.id
    ) THEN
      RAISE EXCEPTION 'a rate book with version history cannot be deleted';
    END IF;
    RETURN OLD;
  END IF;
  IF NEW.org_id IS DISTINCT FROM OLD.org_id THEN
    RAISE EXCEPTION 'rate book organization is immutable';
  END IF;
  IF NEW.currency IS DISTINCT FROM OLD.currency
     AND EXISTS (
       SELECT 1 FROM item_rate_versions version
        WHERE version.rate_book_id = OLD.id
     ) THEN
    RAISE EXCEPTION 'rate book currency cannot change after version history exists';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: rate_version_book_lock_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rate_version_book_lock_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM 1
    FROM public.item_rate_books book
   WHERE book.id = NEW.rate_book_id
     AND book.org_id = NEW.org_id
     FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'rate version must reference a tenant-owned rate book'
      USING ERRCODE = '23503';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: FUNCTION rate_version_book_lock_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rate_version_book_lock_guard() IS 'openbooks:rate_version_book_lock_guard:v1 - holds a FOR SHARE lock on the tenant-owned rate book from before a version insert until commit, so a concurrent currency change cannot pass the history check while first-version creation is in flight';


--
-- Name: rate_version_child_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rate_version_child_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_status text;
  v_org_id uuid;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  SELECT status, org_id
    INTO v_status, v_org_id
    FROM public.item_rate_versions
   WHERE id = coalesce(NEW.version_id, OLD.version_id);
  IF v_status IS NULL
     OR v_org_id IS DISTINCT FROM coalesce(NEW.org_id, OLD.org_id) THEN
    RAISE EXCEPTION 'rate-version child must reference a tenant-owned version'
      USING ERRCODE = '23514';
  END IF;
  IF v_status <> 'draft' THEN
    -- The native clone copies the immutable source snapshot into a sandbox.
    -- Its privileged, transaction-local authority permits INSERT only.
    IF TG_OP = 'INSERT' AND public.openbooks_clone_authority()
       AND EXISTS (SELECT 1 FROM public.orgs
                    WHERE id = NEW.org_id AND env_kind = 'sandbox'
                      AND sandbox_of IS NOT NULL) THEN
      RETURN NEW;
    END IF;
    IF TG_OP = 'DELETE'
       AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'children of an activated or retired rate version are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: rate_version_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rate_version_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF OLD.status = 'draft'
       OR openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'activated and retired rate versions cannot be deleted';
  END IF;
  IF OLD.status = 'draft' THEN RETURN NEW; END IF;

  IF OLD.status = 'active' AND NEW.status = 'active'
     AND NEW.org_id = OLD.org_id
     AND NEW.rate_book_id = OLD.rate_book_id
     AND NEW.effective_from = OLD.effective_from
     AND NEW.custom IS NOT DISTINCT FROM OLD.custom
     AND NEW.effective_to IS NOT NULL
     AND NEW.effective_to >= OLD.effective_from
     AND (OLD.effective_to IS NULL OR NEW.effective_to <= OLD.effective_to) THEN
    RETURN NEW;
  END IF;
  IF OLD.status = 'active' AND NEW.status = 'retired'
     AND NEW.org_id = OLD.org_id
     AND NEW.rate_book_id = OLD.rate_book_id
     AND NEW.effective_from = OLD.effective_from
     AND NEW.effective_to IS NOT DISTINCT FROM OLD.effective_to
     AND NEW.custom IS NOT DISTINCT FROM OLD.custom THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'activated and retired rate versions are immutable';
END
$$;


--
-- Name: rebate_agreement_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rebate_agreement_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE tier jsonb; last_threshold numeric; threshold numeric; rate numeric;
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN
  IF public.financial_history_native_clone_matches(TG_RELID,to_jsonb(NEW)) THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'Financial history clone admission requires the exact registered source row, seed and destination parents.' USING ERRCODE='23514';
 END IF;
 IF TG_OP='DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD)) OR public.openbooks_sandbox_wipe_allowed(OLD.org_id)) THEN RETURN OLD; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Rebate agreements are retained for audit'; END IF;
 IF TG_OP='UPDATE' AND OLD.status='approved' THEN RAISE EXCEPTION 'Approved rebate terms are immutable; create a successor dated agreement'; END IF;
 IF TG_OP='UPDATE' AND ROW(NEW.id,NEW.org_id,NEW.created_by) IS DISTINCT FROM ROW(OLD.id,OLD.org_id,OLD.created_by) THEN RAISE EXCEPTION 'Rebate agreement identity is immutable'; END IF;
 IF jsonb_array_length(NEW.tiers)>100 OR (NEW.method IN ('percent','per_unit') AND jsonb_array_length(NEW.tiers)=0) THEN RAISE EXCEPTION 'Configure one through one hundred rebate tiers'; END IF;
 FOR tier IN SELECT value FROM jsonb_array_elements(NEW.tiers) LOOP
  IF jsonb_typeof(tier->'threshold') IS DISTINCT FROM 'string' OR jsonb_typeof(tier->'rate') IS DISTINCT FROM 'string'
    OR (tier->>'threshold') !~ '^[0-9]+(\.[0-9]{1,4})?$' OR (tier->>'rate') !~ '^[0-9]+(\.[0-9]{1,4})?$' THEN RAISE EXCEPTION 'Rebate tiers require exact non-negative threshold and rate strings'; END IF;
  threshold:=(tier->>'threshold')::numeric; rate:=(tier->>'rate')::numeric;
  IF (last_threshold IS NOT NULL AND threshold<=last_threshold) OR (NEW.method='percent' AND rate>100) THEN RAISE EXCEPTION 'Rebate thresholds must increase and percentages cannot exceed one hundred'; END IF;
  last_threshold:=threshold;
 END LOOP;
 IF NOT EXISTS(SELECT 1 FROM public.accounts a WHERE a.org_id=NEW.org_id AND a.id=NEW.accrual_account_id AND a.is_active AND NOT a.is_summary AND a.type=CASE NEW.side WHEN 'customer' THEN 'liability_current_other' ELSE 'asset_current_other' END)
  THEN RAISE EXCEPTION 'Select a postable rebate liability or receivable account for this side'; END IF;
 IF EXISTS(SELECT 1 FROM unnest(ARRAY[NEW.offset_account_id,NEW.fx_account_id]) target(id) WHERE NOT EXISTS(SELECT 1 FROM public.accounts a WHERE a.org_id=NEW.org_id AND a.id=target.id AND a.is_active AND NOT a.is_summary AND a.type IN ('expense','expense_other','cogs','income','income_other')))
  THEN RAISE EXCEPTION 'Select postable income or expense offset and FX accounts'; END IF;
 IF NEW.party_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.parties p WHERE p.org_id=NEW.org_id AND p.id=NEW.party_id AND p.is_active AND (p.subsidiary_id IS NULL OR p.subsidiary_id=NEW.subsidiary_id)
  AND CASE NEW.side WHEN 'customer' THEN EXISTS(SELECT 1 FROM public.customer_roles r WHERE r.org_id=p.org_id AND r.party_id=p.id AND r.is_active) ELSE EXISTS(SELECT 1 FROM public.vendor_roles r WHERE r.org_id=p.org_id AND r.party_id=p.id AND r.is_active) END)
  THEN RAISE EXCEPTION 'Agreement counterparty must hold the active customer or vendor role in this legal entity'; END IF;
 IF NEW.status='approved' AND EXISTS(SELECT 1 FROM public.rebate_agreements a WHERE a.org_id=NEW.org_id AND a.id<>NEW.id AND a.status='approved' AND a.subsidiary_id=NEW.subsidiary_id AND a.side=NEW.side
  AND a.party_id IS NOT DISTINCT FROM NEW.party_id AND a.selection_group=NEW.selection_group AND a.stacking='best' AND NEW.stacking='best'
  AND daterange(a.effective_from,a.effective_to,'[]') && daterange(NEW.effective_from,NEW.effective_to,'[]') AND a.currency<>NEW.currency)
  THEN RAISE EXCEPTION 'Competing best-deal agreements must use the same currency'; END IF;
 RETURN NEW;
END $_$;


--
-- Name: rebate_claim_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rebate_claim_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD)) OR public.openbooks_sandbox_wipe_allowed(OLD.org_id)) THEN RETURN OLD; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Rebate claim evidence is retained'; END IF;
 IF ROW(NEW.id,NEW.org_id,NEW.agreement_id,NEW.party_id,NEW.amount,NEW.base_amount,NEW.cutoff_on,NEW.basis,NEW.created_by,NEW.reason)
  IS DISTINCT FROM ROW(OLD.id,OLD.org_id,OLD.agreement_id,OLD.party_id,OLD.amount,OLD.base_amount,OLD.cutoff_on,OLD.basis,OLD.created_by,OLD.reason) THEN RAISE EXCEPTION 'Rebate claim terms are immutable'; END IF;
 IF NOT ((OLD.status='draft' AND NEW.status IN ('approved','cancelled')) OR (OLD.status='approved' AND NEW.status IN ('document_pending','settled','cancelled')) OR (OLD.status='document_pending' AND NEW.status IN ('settled','approved')) OR (OLD.status='settled' AND NEW.status='approved'))
  THEN RAISE EXCEPTION 'Invalid rebate claim transition'; END IF;
 IF OLD.approved_by IS NOT NULL AND ROW(NEW.approved_by,NEW.approved_at) IS DISTINCT FROM ROW(OLD.approved_by,OLD.approved_at) THEN RAISE EXCEPTION 'Claim approval evidence is immutable'; END IF;
 RETURN NEW;
END $$;


