    effective_to date,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT account_localizations_localized_name_check CHECK (((localized_name IS NULL) OR ((length(btrim(localized_name)) >= 1) AND (length(btrim(localized_name)) <= 200)))),
    CONSTRAINT account_localizations_localized_number_check CHECK (((localized_number IS NULL) OR ((localized_number = btrim(localized_number)) AND ((length(localized_number) >= 1) AND (length(localized_number) <= 40))))),
    CONSTRAINT account_localizations_value CHECK (((localized_number IS NOT NULL) OR (localized_name IS NOT NULL))),
    CONSTRAINT account_localizations_window CHECK (((effective_to IS NULL) OR (effective_to >= effective_from)))
);

