    CONSTRAINT account_merges_preview_digest_check CHECK ((preview_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT account_merges_reason_check CHECK (((length(btrim(reason)) >= 8) AND (length(btrim(reason)) <= 1000))),
    CONSTRAINT account_merges_result_check CHECK ((jsonb_typeof(result) = 'object'::text))
);

ALTER TABLE ONLY public.account_merges FORCE ROW LEVEL SECURITY;


