--
-- Name: accounting_book_replication_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.accounting_book_replication_runs (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    book_id uuid NOT NULL,
    kind text NOT NULL,
    mode_before text NOT NULL,
    mode_after text NOT NULL,
    replication_from date,
    opening_strategy text,
    opening_entry_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    replicated_count integer DEFAULT 0 NOT NULL,
    excluded_count integer DEFAULT 0 NOT NULL,
    settings jsonb DEFAULT '{}'::jsonb NOT NULL,
    reason text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    created_txid bigint DEFAULT txid_current() NOT NULL,
    CONSTRAINT accounting_book_replication_runs_activation_basis CHECK (((kind <> 'activation'::text) OR ((replication_from IS NOT NULL) AND (opening_strategy IS NOT NULL) AND (mode_after = 'full'::text)))),
    CONSTRAINT accounting_book_replication_runs_counts_check CHECK (((replicated_count >= 0) AND (excluded_count >= 0))),
    CONSTRAINT accounting_book_replication_runs_kind_check CHECK ((kind = ANY (ARRAY['activation'::text, 'catch_up'::text, 'deactivation'::text, 'settings'::text]))),
    CONSTRAINT accounting_book_replication_runs_modes_check CHECK (((mode_before = ANY (ARRAY['adjustment_only'::text, 'full'::text])) AND (mode_after = ANY (ARRAY['adjustment_only'::text, 'full'::text])))),
    CONSTRAINT accounting_book_replication_runs_reason_text CHECK (((length(btrim(reason)) >= 8) AND (length(btrim(reason)) <= 500))),
    CONSTRAINT accounting_book_replication_runs_settings_object CHECK ((jsonb_typeof(settings) = 'object'::text)),
    CONSTRAINT accounting_book_replication_runs_strategy_check CHECK (((opening_strategy IS NULL) OR (opening_strategy = ANY (ARRAY['full_history'::text, 'opening_balances'::text]))))
);

ALTER TABLE ONLY public.accounting_book_replication_runs FORCE ROW LEVEL SECURITY;


