   FROM public.accounting_book_replication_runs
  WHERE (org_id = public.openbooks_query_org_id());


--
-- Name: accounting_books; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.accounting_books (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    is_primary boolean DEFAULT false NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    posts_gl boolean DEFAULT true NOT NULL,
    replication_mode text DEFAULT 'adjustment_only'::text NOT NULL,
    replication_from date,
    currency_difference_account_id uuid,
    CONSTRAINT accounting_books_full_replication_start CHECK (((replication_mode = 'adjustment_only'::text) OR (replication_from IS NOT NULL))),
    CONSTRAINT accounting_books_primary_is_source CHECK (((NOT is_primary) OR (replication_mode = 'adjustment_only'::text))),
    CONSTRAINT accounting_books_replication_mode_check CHECK ((replication_mode = ANY (ARRAY['adjustment_only'::text, 'full'::text])))
);

ALTER TABLE ONLY public.accounting_books FORCE ROW LEVEL SECURITY;


--
-- Name: COLUMN accounting_books.replication_mode; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.accounting_books.replication_mode IS 'adjustment_only: the book receives only book-specific and generated entries. full: every replicable primary-book posting dated on or after replication_from is replicated into the book.';


--
-- Name: COLUMN accounting_books.replication_from; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.accounting_books.replication_from IS 'First posting date full replication covers. Fixed once set; earlier history enters through the activation''s opening strategy.';


--
-- Name: COLUMN accounting_books.currency_difference_account_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.accounting_books.currency_difference_account_id IS 'Receives currency differences that remain when a mixed-currency posting translates into the book currency, and opening-balance differences on activation.';


--
-- Name: accounting_books; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.accounting_books WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    code,
    name,
    is_primary,
    is_active,
    created_at,
    created_by,
    updated_at,
    updated_by,
    posts_gl,
    replication_mode,
    replication_from,
    currency_difference_account_id
   FROM public.accounting_books
  WHERE (org_id = public.openbooks_query_org_id());


