--
-- Name: accounts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.accounts (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    parent_id uuid,
    number text,
    name text NOT NULL,
    type text NOT NULL,
    description text,
    is_summary boolean DEFAULT false NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    currency_restriction text,
    eliminate boolean DEFAULT false NOT NULL,
    reconcilable boolean DEFAULT false NOT NULL,
    required_dimensions jsonb DEFAULT '[]'::jsonb NOT NULL,
    custom jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    subsidiary_id uuid,
    subsidiary_include_children boolean DEFAULT true NOT NULL,
    monetary boolean,
    merged_into_id uuid,
    merged_at timestamp with time zone,
    merged_by uuid,
    merge_reason text,
    CONSTRAINT accounts_merge_state CHECK ((((merged_into_id IS NULL) AND (merged_at IS NULL) AND (merged_by IS NULL) AND (merge_reason IS NULL)) OR ((merged_into_id IS NOT NULL) AND (merged_into_id <> id) AND (merged_at IS NOT NULL) AND (merged_by IS NOT NULL) AND (merge_reason IS NOT NULL) AND ((length(btrim(merge_reason)) >= 8) AND (length(btrim(merge_reason)) <= 1000)) AND (NOT is_active)))),
    CONSTRAINT accounts_reconcilable_currency_required CHECK (((NOT reconcilable) OR (currency_restriction IS NOT NULL)))
);

ALTER TABLE ONLY public.accounts FORCE ROW LEVEL SECURITY;


--
-- Name: COLUMN accounts.monetary; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.accounts.monetary IS 'IAS 21 monetary-item override for FX retranslation: null = infer from type (bank/receivable/payable), true = retranslate (balance-sheet types only), false = exclude.';


--
-- Name: COLUMN accounts.merged_into_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.accounts.merged_into_id IS 'Surviving account this account was merged into; set once by the account merge command and permanent.';


--
-- Name: accounts; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.accounts WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    parent_id,
    number,
    name,
    type,
    description,
    is_summary,
    is_active,
    currency_restriction,
    eliminate,
    reconcilable,
    required_dimensions,
    custom,
    created_at,
    created_by,
    updated_at,
    updated_by,
    subsidiary_id,
    subsidiary_include_children,
    monetary,
    merged_into_id,
    merged_at,
    merged_by,
    merge_reason
   FROM public.accounts
  WHERE (org_id = public.openbooks_query_org_id());


--
-- Name: addresses; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.addresses (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    party_id uuid NOT NULL,
    label text,
    line1 text,
    line2 text,
    city text,
    region text,
    postal_code text,
    country text,
    is_default_billing boolean DEFAULT false NOT NULL,
    is_default_shipping boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    custom jsonb DEFAULT '{}'::jsonb NOT NULL,
    longitude numeric(10,7),
    latitude numeric(10,7),
    location_verified_at timestamp with time zone,
    location_verified_by uuid,
    CONSTRAINT address_geographic_coordinates CHECK ((((longitude IS NULL) = (latitude IS NULL)) AND ((longitude IS NULL) OR ((longitude >= ('-180'::integer)::numeric) AND (longitude <= (180)::numeric))) AND ((latitude IS NULL) OR ((latitude >= ('-90'::integer)::numeric) AND (latitude <= (90)::numeric)))))
);

ALTER TABLE ONLY public.addresses FORCE ROW LEVEL SECURITY;


--
-- Name: addresses; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.addresses WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    party_id,
    label,
    line1,
    line2,
    city,
    region,
    postal_code,
