    item_id uuid,
    vendor_party_id uuid,
    department_id uuid,
    project_id uuid,
    location_id uuid,
    description text,
    quantity numeric(28,8),
    amount numeric(19,4) NOT NULL,
    currency text NOT NULL,
    posting_date date NOT NULL,
    suggested_category_id uuid,
    status text DEFAULT 'pending'::text NOT NULL,
    acceptance_id uuid,
    resolved_at timestamp with time zone,
    resolved_by uuid,
    resolution_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT asset_proposals_amount CHECK ((amount > (0)::numeric)),
    CONSTRAINT asset_proposals_origin CHECK ((origin = ANY (ARRAY['rule'::text, 'manual'::text]))),
    CONSTRAINT asset_proposals_origin_shape CHECK (((origin = 'rule'::text) = (rule_id IS NOT NULL))),
    CONSTRAINT asset_proposals_quantity CHECK (((quantity IS NULL) OR (quantity > (0)::numeric))),
    CONSTRAINT asset_proposals_status CHECK ((status = ANY (ARRAY['pending'::text, 'accepted'::text, 'rejected'::text, 'voided'::text]))),
    CONSTRAINT asset_proposals_status_shape CHECK ((((status = 'pending'::text) AND (acceptance_id IS NULL) AND (resolved_at IS NULL) AND (resolved_by IS NULL) AND (resolution_reason IS NULL)) OR ((status = 'accepted'::text) AND (acceptance_id IS NOT NULL) AND (resolved_at IS NOT NULL) AND (resolved_by IS NOT NULL)) OR ((status = 'rejected'::text) AND (acceptance_id IS NULL) AND (resolved_at IS NOT NULL) AND (resolved_by IS NOT NULL) AND (resolution_reason IS NOT NULL) AND (length(btrim(resolution_reason)) > 0)) OR ((status = 'voided'::text) AND (acceptance_id IS NULL) AND (resolved_at IS NOT NULL) AND (resolution_reason IS NOT NULL) AND (length(btrim(resolution_reason)) > 0))))
);

