-- Name: charge_rate_components; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.charge_rate_components (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    document_line_id uuid NOT NULL,
    role text NOT NULL,
    rate_line_id uuid,
    unit_code text NOT NULL,
    unit_name text NOT NULL,
    quantity numeric(28,8) NOT NULL,
    rate numeric(19,4) NOT NULL,
    amount numeric(19,4) NOT NULL,
    sequence integer NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    quantity_ratio jsonb,
    CONSTRAINT charge_rate_components_amount_check CHECK ((amount >= (0)::numeric)),
    CONSTRAINT charge_rate_components_quantity_check CHECK ((quantity > (0)::numeric)),
    CONSTRAINT charge_rate_components_rate_check CHECK ((rate >= (0)::numeric)),
    CONSTRAINT charge_rate_components_role_check CHECK ((role = ANY (ARRAY['cost'::text, 'bill'::text]))),
    CONSTRAINT charge_rate_fraction_shape CHECK (((quantity_ratio IS NULL) OR COALESCE(((jsonb_typeof(quantity_ratio) = 'object'::text) AND (jsonb_typeof((quantity_ratio -> 'numerator'::text)) = 'string'::text) AND (jsonb_typeof((quantity_ratio -> 'denominator'::text)) = 'string'::text) AND ((quantity_ratio ->> 'numerator'::text) ~ '^[1-9][0-9]*$'::text) AND ((quantity_ratio ->> 'denominator'::text) ~ '^[1-9][0-9]*$'::text) AND (quantity_ratio ? 'numerator'::text) AND (quantity_ratio ? 'denominator'::text)), false)))
);

