--
-- Name: COLUMN close_automation_executions.lease_token; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.close_automation_executions.lease_token IS 'Random per-claim fencing token; effect checkpoints and terminal transitions must match the active running claim.';


--
-- Name: COLUMN close_automation_executions.locked_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.close_automation_executions.locked_at IS 'When the active claim took the execution row; claims older than the stale window are reclaimed by the next firing.';


--
-- Name: COLUMN close_automation_executions.attempt_count; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.close_automation_executions.attempt_count IS 'Number of claims this execution has served (initial attempt plus crash recoveries); observability, not a retry ceiling.';


--
-- Name: COLUMN close_automation_executions.stages; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.close_automation_executions.stages IS 'Per-effect completion checkpoints; each non-idempotent unit effect commits in the same transaction as its stage key so a resumed attempt converges on exactly once.';


--
-- Name: close_automation_executions; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.close_automation_executions WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    rule_id,
    run_id,
    task_id,
    trigger,
    event_key,
    status,
    error,
    executed_at,
    created_at,
    created_by,
    updated_at,
    updated_by,
    lease_token,
    locked_at,
    attempt_count,
    stages
   FROM public.close_automation_executions
  WHERE (org_id = public.openbooks_query_org_id());


