--
-- Name: customer_roles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.customer_roles (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    party_id uuid NOT NULL,
    ar_account_id uuid,
    payment_terms_id uuid,
    credit_limit numeric(19,4),
    currency text,
    sales_rep_id uuid,
    tax_code_id uuid,
    is_active boolean DEFAULT true NOT NULL,
    custom jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    is_on_hold boolean DEFAULT false NOT NULL,
    hold_reason text,
    held_at timestamp with time zone,
    held_by uuid,
    einvoice_profile text,
    einvoice_address text,
    einvoice_address_scheme text,
    einvoice_buyer_reference text,
    einvoice_legal_registration_id text,
    einvoice_legal_registration_scheme text,
    CONSTRAINT customer_roles_einvoice_address_check CHECK (((length(btrim(einvoice_address)) >= 1) AND (length(btrim(einvoice_address)) <= 200))),
    CONSTRAINT customer_roles_einvoice_address_pair CHECK (((einvoice_address IS NULL) = (einvoice_address_scheme IS NULL))),
    CONSTRAINT customer_roles_einvoice_address_scheme_check CHECK ((einvoice_address_scheme ~ '^([0-9]{4}|[A-Z]{2})$'::text)),
    CONSTRAINT customer_roles_einvoice_buyer_reference_check CHECK (((length(btrim(einvoice_buyer_reference)) >= 1) AND (length(btrim(einvoice_buyer_reference)) <= 200))),
    CONSTRAINT customer_roles_einvoice_legal_registration_id_check CHECK (((length(btrim(einvoice_legal_registration_id)) >= 1) AND (length(btrim(einvoice_legal_registration_id)) <= 100))),
    CONSTRAINT customer_roles_einvoice_legal_registration_scheme_check CHECK ((einvoice_legal_registration_scheme ~ '^[0-9]{4}$'::text)),
    CONSTRAINT customer_roles_einvoice_profile_check CHECK ((einvoice_profile = ANY (ARRAY['en16931-cii'::text, 'en16931-ubl'::text, 'xrechnung-cii'::text, 'xrechnung-ubl'::text, 'facturx'::text, 'peppol-bis'::text, 'nlcius'::text, 'ehf'::text, 'peppol-aunz'::text, 'peppol-sg'::text, 'pint-aunz'::text, 'pint-sg'::text]))),
    CONSTRAINT customer_roles_einvoice_registration_scheme CHECK (((einvoice_legal_registration_scheme IS NULL) OR (einvoice_legal_registration_id IS NOT NULL))),
    CONSTRAINT customer_roles_hold_evidence CHECK (((is_on_hold = false) OR ((hold_reason IS NOT NULL) AND ((length(btrim(hold_reason)) >= 5) AND (length(btrim(hold_reason)) <= 500)) AND (held_at IS NOT NULL) AND (held_by IS NOT NULL))))
);

ALTER TABLE ONLY public.customer_roles FORCE ROW LEVEL SECURITY;


--
-- Name: COLUMN customer_roles.einvoice_profile; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.customer_roles.einvoice_profile IS 'E-invoice format the customer receives; null means the customer is invoiced without a structured e-invoice.';


--
-- Name: COLUMN customer_roles.einvoice_address; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.customer_roles.einvoice_address IS 'Buyer electronic address (BT-49), such as a Peppol participant identifier, under einvoice_address_scheme (EAS).';


--
-- Name: COLUMN customer_roles.einvoice_buyer_reference; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.customer_roles.einvoice_buyer_reference IS 'Default buyer reference (BT-10), such as a German Leitweg-ID; an issued invoice may state its own.';


