CREATE TABLE public.depreciation_schedule_lines (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    schedule_id uuid NOT NULL,
    period_id uuid NOT NULL,
    sequence integer NOT NULL,
    planned_amount numeric(19,4) NOT NULL,
    posted_amount numeric(19,4),
    journal_entry_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    source text DEFAULT 'formula'::text NOT NULL,
    input_id uuid,
    non_gl_recognized_at timestamp with time zone,
    reverses_line_id uuid,
    reversal_reason text,
    CONSTRAINT depr_lines_amount_direction CHECK (((source = ANY (ARRAY['manual'::text, 'production_usage'::text, 'reversal'::text])) OR ((planned_amount >= (0)::numeric) AND ((posted_amount IS NULL) OR (posted_amount >= (0)::numeric))))),
    CONSTRAINT depr_lines_input_provenance CHECK ((((source = ANY (ARRAY['formula'::text, 'imported'::text, 'reversal'::text])) AND (input_id IS NULL)) OR ((source = ANY (ARRAY['manual'::text, 'production_usage'::text])) AND (input_id IS NOT NULL)))),
    CONSTRAINT depr_lines_non_gl_recognition CHECK (((non_gl_recognized_at IS NULL) OR ((posted_amount IS NOT NULL) AND (journal_entry_id IS NULL) AND (source <> 'imported'::text)))),
    CONSTRAINT depr_lines_posting_evidence_pair CHECK ((((posted_amount IS NULL) AND (journal_entry_id IS NULL)) OR ((posted_amount IS NOT NULL) AND ((posted_amount = (0)::numeric) OR (journal_entry_id IS NOT NULL) OR (source = 'imported'::text) OR (non_gl_recognized_at IS NOT NULL))))),
    CONSTRAINT depr_lines_source_check CHECK ((source = ANY (ARRAY['formula'::text, 'manual'::text, 'production_usage'::text, 'imported'::text, 'reversal'::text]))),
    CONSTRAINT depreciation_reversal_shape CHECK ((((source = 'reversal'::text) AND (reverses_line_id IS NOT NULL) AND (reverses_line_id <> id) AND (reversal_reason IS NOT NULL) AND ((length(btrim(reversal_reason)) >= 8) AND (length(btrim(reversal_reason)) <= 500)) AND (posted_amount IS NOT NULL) AND (posted_amount = planned_amount) AND (journal_entry_id IS NOT NULL) AND (non_gl_recognized_at IS NULL)) OR ((source <> 'reversal'::text) AND (reverses_line_id IS NULL) AND (reversal_reason IS NULL))))
);

