--
-- Name: document_lines; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.document_lines (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    document_id uuid NOT NULL,
    line_number integer NOT NULL,
    item_id uuid,
    account_id uuid,
    description text,
    quantity numeric(28,8) DEFAULT '1'::numeric NOT NULL,
    unit text,
    unit_price numeric(28,8) DEFAULT '0'::numeric NOT NULL,
    amount numeric(19,4) NOT NULL,
    tax_code_id uuid,
    tax_amount numeric(19,4) DEFAULT '0'::numeric NOT NULL,
    department_id uuid,
    project_id uuid,
    location_id uuid,
    class_id uuid,
    employee_id uuid,
    time_entry_id uuid,
    time_type_id uuid,
    cost_multiplier numeric(19,4),
    is_billable boolean DEFAULT false NOT NULL,
    billed_by_line_id uuid,
    quantity_fulfilled numeric(28,8) DEFAULT '0'::numeric NOT NULL,
    quantity_billed numeric(28,8) DEFAULT '0'::numeric NOT NULL,
    custom jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    tax_overridden boolean DEFAULT false NOT NULL,
    subsidiary_id uuid,
    extra_dims jsonb DEFAULT '{}'::jsonb NOT NULL,
    stock_location_id uuid,
    party_id uuid,
    equipment_unit_id uuid,
    rate_version_id uuid,
    rate_presentation text,
    base_quantity numeric(19,4),
    base_unit text,
    cost_rate numeric(19,4),
    bill_rate numeric(19,4),
    cost_amount numeric(19,4),
    bill_amount numeric(19,4),
    recovery_account_id uuid,
    tax_group_id uuid,
    tax_input_amount numeric(19,4),
    field_ticket_id uuid,
    markup_percent numeric(19,4),
    distribution_group_id uuid,
    distribution_rule_id uuid,
    distribution_version_id uuid,
    distribution_locked boolean DEFAULT false NOT NULL,
    settlement_type text,
    price_basis jsonb,
    quantity_cancelled numeric(28,8) DEFAULT 0 NOT NULL,
    promotion_id uuid,
    marketplace_facilitator text,
    service_party_id uuid,
    project_task_id uuid,
    work_from date,
    work_to date,
    withholding_treatment text,
    withholding_materials_cost numeric(19,4),
    amortization_template_id uuid,
    amortization_start_on date,
    amortization_end_on date,
    journal_currency text,
    journal_fx_rate numeric(19,10),
    journal_eliminate boolean DEFAULT false NOT NULL,
    original_currency text,
    original_amount numeric(19,4),
    original_tax_amount numeric(19,4),
    original_fx_rate numeric(19,10),
    original_fx_evidence jsonb,
    CONSTRAINT doc_lines_one_tax_profile CHECK ((num_nonnulls(tax_code_id, tax_group_id) <= 1)),
    CONSTRAINT doc_lines_target CHECK (((item_id IS NOT NULL) OR (account_id IS NOT NULL))),
    CONSTRAINT document_lines_amortization_dates_need_template CHECK (((amortization_template_id IS NOT NULL) OR ((amortization_start_on IS NULL) AND (amortization_end_on IS NULL)))),
    CONSTRAINT document_lines_amortization_window_check CHECK (((amortization_start_on IS NULL) OR (amortization_end_on IS NULL) OR (amortization_end_on >= amortization_start_on))),
    CONSTRAINT document_lines_check CHECK (((withholding_materials_cost >= (0)::numeric) AND (withholding_materials_cost <= amount))),
    CONSTRAINT document_lines_journal_fx_rate_check CHECK ((journal_fx_rate > (0)::numeric)),
    CONSTRAINT document_lines_original_currency_evidence CHECK ((((original_currency IS NULL) AND (original_amount IS NULL) AND (original_tax_amount IS NULL) AND (original_fx_rate IS NULL) AND (original_fx_evidence IS NULL)) OR COALESCE(((original_currency ~ '^[A-Z]{3}$'::text) AND (original_amount IS NOT NULL) AND (original_fx_rate > (0)::numeric) AND (jsonb_typeof(original_fx_evidence) = 'object'::text) AND (original_fx_evidence ?& ARRAY['version'::text, 'method'::text, 'rate'::text, 'fromCurrency'::text, 'toCurrency'::text, 'rateDate'::text, 'source'::text, 'reason'::text, 'rateType'::text, 'observationId'::text, 'observationDate'::text, 'digest'::text, 'billedAmount'::text]) AND ((original_fx_evidence - ARRAY['version'::text, 'method'::text, 'rate'::text, 'fromCurrency'::text, 'toCurrency'::text, 'rateDate'::text, 'source'::text, 'reason'::text, 'rateType'::text, 'observationId'::text, 'observationDate'::text, 'digest'::text, 'billedAmount'::text]) = '{}'::jsonb) AND ((original_fx_evidence -> 'version'::text) = '1'::jsonb) AND ((original_fx_evidence ->> 'method'::text) = ANY (ARRAY['rate_table'::text, 'override'::text, 'billed_amount'::text])) AND
CASE
    WHEN ((original_fx_evidence ->> 'rate'::text) ~ '^[0-9]{1,9}(\.[0-9]{1,10})?$'::text) THEN (((original_fx_evidence ->> 'rate'::text))::numeric = original_fx_rate)
    ELSE false
END AND ((original_fx_evidence ->> 'fromCurrency'::text) = original_currency) AND ((original_fx_evidence ->> 'toCurrency'::text) ~ '^[A-Z]{3}$'::text) AND ((original_fx_evidence ->> 'toCurrency'::text) <> original_currency) AND ((original_fx_evidence ->> 'rateDate'::text) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'::text) AND ((char_length(COALESCE((original_fx_evidence ->> 'source'::text), ''::text)) >= 1) AND (char_length(COALESCE((original_fx_evidence ->> 'source'::text), ''::text)) <= 120)) AND
CASE (original_fx_evidence ->> 'method'::text)
    WHEN 'rate_table'::text THEN ((jsonb_typeof((original_fx_evidence -> 'rateType'::text)) = 'string'::text) AND (jsonb_typeof((original_fx_evidence -> 'observationId'::text)) = 'string'::text) AND ((original_fx_evidence ->> 'observationDate'::text) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'::text) AND ((original_fx_evidence ->> 'digest'::text) ~ '^[a-f0-9]{64}$'::text) AND (jsonb_typeof((original_fx_evidence -> 'reason'::text)) = 'null'::text) AND (jsonb_typeof((original_fx_evidence -> 'billedAmount'::text)) = 'null'::text))
    WHEN 'override'::text THEN (((char_length(COALESCE((original_fx_evidence ->> 'reason'::text), ''::text)) >= 8) AND (char_length(COALESCE((original_fx_evidence ->> 'reason'::text), ''::text)) <= 500)) AND ((original_fx_evidence ->> 'reason'::text) = btrim((original_fx_evidence ->> 'reason'::text))) AND (jsonb_typeof((original_fx_evidence -> 'billedAmount'::text)) = 'null'::text))
    ELSE (((original_fx_evidence ->> 'billedAmount'::text) ~ '^-?[0-9]{1,15}(\.[0-9]{1,4})?$'::text) AND (jsonb_typeof((original_fx_evidence -> 'reason'::text)) = 'null'::text))
END), false))),
    CONSTRAINT document_lines_quantity_cancelled_check CHECK (((quantity_cancelled >= (0)::numeric) AND ((quantity_cancelled = (0)::numeric) OR ((quantity_fulfilled + quantity_cancelled) <= quantity)))),
    CONSTRAINT document_lines_rate_presentation_check CHECK (((rate_presentation IS NULL) OR (rate_presentation = ANY (ARRAY['summary'::text, 'rate_components'::text])))),
    CONSTRAINT document_lines_settlement_type CHECK ((settlement_type = ANY (ARRAY['out_of_pocket'::text, 'company_paid'::text, 'personal'::text]))),
    CONSTRAINT document_lines_withholding_treatment_check CHECK ((withholding_treatment = ANY (ARRAY['labour'::text, 'materials'::text, 'excluded'::text]))),
    CONSTRAINT document_lines_work_period_order CHECK (((work_from IS NULL) OR (work_to IS NULL) OR (work_to >= work_from)))
);

ALTER TABLE ONLY public.document_lines FORCE ROW LEVEL SECURITY;


--
-- Name: COLUMN document_lines.quantity_fulfilled; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.document_lines.quantity_fulfilled IS 'Commercial quantity fulfilled against this order line, preserved to eight decimal places.';


--
-- Name: COLUMN document_lines.quantity_billed; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.document_lines.quantity_billed IS 'Commercial quantity billed or converted from this order line, preserved to eight decimal places.';


--
-- Name: COLUMN document_lines.settlement_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.document_lines.settlement_type IS 'Who fronted the money for this expense line: out_of_pocket = employee paid, company owes a person; company_paid = company-liability card, company owes the issuer; personal = non-business charge on the company card, employee owes the company (receivable, never an expense). NULL = settlement not recorded (all pre-0171 history); the repost path treats NULL as out_of_pocket legacy math';


--
-- Name: COLUMN document_lines.price_basis; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.document_lines.price_basis IS 'Pricing provenance stamped at pricing time: {kind, scheduleId, levelId, assignmentId, unitPrice, resolvedAt}. Null for hand-priced lines.';


--
-- Name: COLUMN document_lines.quantity_cancelled; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.document_lines.quantity_cancelled IS 'Order quantity cancelled and no longer owed to the customer; the sum of the line''s order_line_cancellations rows. Open quantity is quantity - quantity_fulfilled - quantity_cancelled.';


--
-- Name: COLUMN document_lines.withholding_treatment; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.document_lines.withholding_treatment IS 'How a bill line counts toward contractor withholding: labour, materials the subcontractor supplied, or a supply outside the scheme. Unset lines are classified from the item.';


--
-- Name: COLUMN document_lines.withholding_materials_cost; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.document_lines.withholding_materials_cost IS 'Subcontractor direct materials cost in document currency, entered explicitly for CIS; selling-price markup remains subject to withholding.';


--
-- Name: COLUMN document_lines.original_currency; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.document_lines.original_currency IS 'Currency an expense line was spent in when it differs from its report; null for a line in the report currency.';


--
-- Name: COLUMN document_lines.original_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.document_lines.original_amount IS 'The line amount in its original currency, before conversion into the report currency.';


--
-- Name: COLUMN document_lines.original_tax_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.document_lines.original_tax_amount IS 'The line tax shown on the receipt in its original currency; null when the tax is computed in the report currency.';


--
-- Name: COLUMN document_lines.original_fx_rate; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.document_lines.original_fx_rate IS 'Rate that converted the original amounts into the report currency.';


--
-- Name: COLUMN document_lines.original_fx_evidence; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.document_lines.original_fx_evidence IS 'How the conversion rate was obtained: the dated exchange-rate observation, an operator rate with its reason, or the billed report-currency amount it was derived from.';


