-- Name: einvoice_settings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.einvoice_settings (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    subsidiary_id uuid NOT NULL,
    default_profile text NOT NULL,
    address_line1 text,
    address_line2 text,
    city text,
    postcode text,
    subdivision text,
    trading_name text,
    legal_registration_id text,
    legal_registration_scheme text,
    tax_number text,
    contact_name text,
    contact_phone text,
    contact_email text,
    electronic_address text,
    electronic_address_scheme text,
    payment_means_code text DEFAULT '30'::text NOT NULL,
    payee_account_id text,
    payee_account_name text,
    payee_bic text,
    untaxed_line_category text,
    untaxed_exemption_reason_code text,
    untaxed_exemption_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    updated_by uuid NOT NULL,
    CONSTRAINT einvoice_settings_address_line1_check CHECK (((length(btrim(address_line1)) >= 1) AND (length(btrim(address_line1)) <= 200))),
    CONSTRAINT einvoice_settings_address_line2_check CHECK (((length(btrim(address_line2)) >= 1) AND (length(btrim(address_line2)) <= 200))),
    CONSTRAINT einvoice_settings_check CHECK (((electronic_address IS NULL) = (electronic_address_scheme IS NULL))),
    CONSTRAINT einvoice_settings_check1 CHECK (((legal_registration_scheme IS NULL) OR (legal_registration_id IS NOT NULL))),
    CONSTRAINT einvoice_settings_check2 CHECK (((untaxed_line_category IS NOT NULL) OR ((untaxed_exemption_reason_code IS NULL) AND (untaxed_exemption_reason IS NULL)))),
    CONSTRAINT einvoice_settings_check3 CHECK (((untaxed_line_category IS DISTINCT FROM 'Z'::text) OR ((untaxed_exemption_reason_code IS NULL) AND (untaxed_exemption_reason IS NULL)))),
    CONSTRAINT einvoice_settings_city_check CHECK (((length(btrim(city)) >= 1) AND (length(btrim(city)) <= 100))),
    CONSTRAINT einvoice_settings_contact_email_check CHECK (((length(btrim(contact_email)) >= 3) AND (length(btrim(contact_email)) <= 320))),
    CONSTRAINT einvoice_settings_contact_name_check CHECK (((length(btrim(contact_name)) >= 1) AND (length(btrim(contact_name)) <= 200))),
    CONSTRAINT einvoice_settings_contact_phone_check CHECK (((length(btrim(contact_phone)) >= 1) AND (length(btrim(contact_phone)) <= 50))),
    CONSTRAINT einvoice_settings_default_profile_check CHECK ((default_profile = ANY (ARRAY['en16931-cii'::text, 'en16931-ubl'::text, 'xrechnung-cii'::text, 'xrechnung-ubl'::text, 'facturx'::text, 'peppol-bis'::text, 'nlcius'::text, 'ehf'::text, 'peppol-aunz'::text, 'peppol-sg'::text, 'pint-aunz'::text, 'pint-sg'::text]))),
    CONSTRAINT einvoice_settings_electronic_address_check CHECK (((length(btrim(electronic_address)) >= 1) AND (length(btrim(electronic_address)) <= 200))),
    CONSTRAINT einvoice_settings_electronic_address_scheme_check CHECK ((electronic_address_scheme ~ '^([0-9]{4}|[A-Z]{2})$'::text)),
    CONSTRAINT einvoice_settings_legal_registration_id_check CHECK (((length(btrim(legal_registration_id)) >= 1) AND (length(btrim(legal_registration_id)) <= 100))),
    CONSTRAINT einvoice_settings_legal_registration_scheme_check CHECK ((legal_registration_scheme ~ '^[0-9]{4}$'::text)),
    CONSTRAINT einvoice_settings_payee_account_id_check CHECK (((length(btrim(payee_account_id)) >= 1) AND (length(btrim(payee_account_id)) <= 64))),
    CONSTRAINT einvoice_settings_payee_account_name_check CHECK (((length(btrim(payee_account_name)) >= 1) AND (length(btrim(payee_account_name)) <= 200))),
    CONSTRAINT einvoice_settings_payee_bic_check CHECK ((regexp_replace(payee_bic, '[[:space:]-]'::text, ''::text, 'g'::text) ~ '^[A-Za-z0-9]{4,35}$'::text)),
    CONSTRAINT einvoice_settings_payment_means_code_check CHECK ((payment_means_code ~ '^([0-9]{1,2}|ZZZ)$'::text)),
    CONSTRAINT einvoice_settings_postcode_check CHECK (((length(btrim(postcode)) >= 1) AND (length(btrim(postcode)) <= 20))),
    CONSTRAINT einvoice_settings_subdivision_check CHECK (((length(btrim(subdivision)) >= 1) AND (length(btrim(subdivision)) <= 100))),
    CONSTRAINT einvoice_settings_tax_number_check CHECK (((length(btrim(tax_number)) >= 1) AND (length(btrim(tax_number)) <= 50))),
    CONSTRAINT einvoice_settings_trading_name_check CHECK (((length(btrim(trading_name)) >= 1) AND (length(btrim(trading_name)) <= 200))),
    CONSTRAINT einvoice_settings_untaxed_exemption_reason_check CHECK (((length(btrim(untaxed_exemption_reason)) >= 1) AND (length(btrim(untaxed_exemption_reason)) <= 1000))),
    CONSTRAINT einvoice_settings_untaxed_exemption_reason_code_check CHECK ((untaxed_exemption_reason_code ~ '^VATEX-[A-Z0-9-]{1,40}$'::text)),
    CONSTRAINT einvoice_settings_untaxed_line_category_check CHECK ((untaxed_line_category = ANY (ARRAY['Z'::text, 'E'::text, 'O'::text])))
);

ALTER TABLE ONLY public.einvoice_settings FORCE ROW LEVEL SECURITY;


