    br_dependentes integer,
    br_pensao_mensal numeric(19,4),
    sui_exempt boolean DEFAULT false NOT NULL,
    br_salario_familia_filhos integer,
    es_contrato_temporal text,
    statutory_occupation_class text,
    wcb_exempt boolean DEFAULT false NOT NULL,
    wcb_exempt_reason text,
    CONSTRAINT employee_payroll_profiles_allowances CHECK (((w4_allowances IS NULL) OR (w4_allowances >= 0))),
    CONSTRAINT employee_payroll_profiles_br_dependentes CHECK (((br_dependentes IS NULL) OR (br_dependentes >= 0))),
    CONSTRAINT employee_payroll_profiles_br_salario_familia CHECK (((br_salario_familia_filhos IS NULL) OR (br_salario_familia_filhos >= 0))),
    CONSTRAINT employee_payroll_profiles_country CHECK ((country ~ '^[A-Z]{2}$'::text)),
    CONSTRAINT employee_payroll_profiles_es_ano CHECK (((es_ano_nacimiento IS NULL) OR ((es_ano_nacimiento >= 1906) AND (es_ano_nacimiento <= 2026)))),
    CONSTRAINT employee_payroll_profiles_es_contrato CHECK (((es_contrato_temporal IS NULL) OR (es_contrato_temporal = ANY (ARRAY['true'::text, 'false'::text])))),
    CONSTRAINT employee_payroll_profiles_es_grupo CHECK (((es_grupo_cotizacion IS NULL) OR ((es_grupo_cotizacion >= 1) AND (es_grupo_cotizacion <= 11)))),
    CONSTRAINT employee_payroll_profiles_es_situacion CHECK (((es_situacion_laboral IS NULL) OR (es_situacion_laboral = ANY (ARRAY['activo'::text, 'pensionista'::text, 'desempleado'::text])))),
    CONSTRAINT employee_payroll_profiles_fed_code CHECK (((federal_claim_code IS NULL) OR ((federal_claim_code >= 0) AND (federal_claim_code <= 10)))),
    CONSTRAINT employee_payroll_profiles_filing_status CHECK (((filing_status IS NULL) OR (filing_status = ANY (ARRAY['single'::text, 'married_joint'::text, 'head_household'::text])))),
    CONSTRAINT employee_payroll_profiles_jp_kaigo CHECK (((jp_kaigo_dainigou IS NULL) OR (jp_kaigo_dainigou = ANY (ARRAY['true'::text, 'false'::text])))),
    CONSTRAINT employee_payroll_profiles_pay_basis CHECK ((pay_basis = ANY (ARRAY['hourly'::text, 'salary'::text]))),
    CONSTRAINT employee_payroll_profiles_payment_method CHECK (((payment_method IS NULL) OR (payment_method = ANY (ARRAY['eft'::text, 'cheque'::text])))),
    CONSTRAINT employee_payroll_profiles_prov_code CHECK (((provincial_claim_code IS NULL) OR ((provincial_claim_code >= 0) AND (provincial_claim_code <= 10)))),
    CONSTRAINT employee_payroll_profiles_stub_delivery CHECK ((stub_delivery = ANY (ARRAY['email'::text, 'print'::text, 'both'::text]))),
    CONSTRAINT employee_payroll_profiles_vacation CHECK (((vacation_percent IS NULL) OR (vacation_percent >= (0)::numeric))),
    CONSTRAINT employee_payroll_profiles_vacation_method CHECK ((vacation_method = ANY (ARRAY['accrue'::text, 'pay_each_period'::text]))),
    CONSTRAINT employee_payroll_profiles_wcb_exempt_reason CHECK (((wcb_exempt = false) OR ((wcb_exempt_reason IS NOT NULL) AND (btrim(wcb_exempt_reason) <> ''::text))))
);

ALTER TABLE ONLY public.employee_payroll_profiles FORCE ROW LEVEL SECURITY;


--
-- Name: COLUMN employee_payroll_profiles.country; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.employee_payroll_profiles.country IS 'Statutory country pack this employee runs under: no default — an unset country is refused by NOT NULL rather than silently becoming Canada. Historical rows carrying ''CA'' may have been defaulted; they are left untouched because a defaulted row is indistinguishable from a chosen one.';


--
-- Name: COLUMN employee_payroll_profiles.residence_region; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.employee_payroll_profiles.residence_region IS 'Region the employee RESIDES in, when it differs from the region of employment (province). Null means not recorded, which withholding resolution treats as the work region and reports as an assumption. Drives reciprocity, resident sub-region levies (New York City, Philadelphia) and residence-region withholding. Codes are the pack''s own region vocabulary; validated at the API boundary against the country pack, never by a CHECK naming one country''s codes.';


--
-- Name: COLUMN employee_payroll_profiles.paid_on_commission; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.employee_payroll_profiles.paid_on_commission IS 'Whether the employee is paid in whole or in part on commission, for statutory-holiday rules that read it. Null = unanswered: the engine fails closed exactly as a missing per-request entry does. Never default this to false — a silent false answers for the operator and reintroduces the inference payroll-holidays.ts:700-707 refuses to make.';


--
-- Name: COLUMN employee_payroll_profiles.pl_rok_urodzenia; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.employee_payroll_profiles.pl_rok_urodzenia IS 'Employee birth year for the PL FP age bar: PESEL-derived with a declared fallback for employees without a PESEL; null = unknown, never guessed.';


--
-- Name: COLUMN employee_payroll_profiles.es_ano_nacimiento; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.employee_payroll_profiles.es_ano_nacimiento IS 'Employee birth year feeding the ES age-banded rule, AÑOPER; null = unknown, never guessed.';


--
-- Name: COLUMN employee_payroll_profiles.es_grupo_cotizacion; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.employee_payroll_profiles.es_grupo_cotizacion IS 'ES Seguridad Social contribution group 1–11, Orden PJC/297/2026 art. 33; null = undeclared, never group 1 by fallthrough.';


--
-- Name: COLUMN employee_payroll_profiles.es_situacion_laboral; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.employee_payroll_profiles.es_situacion_laboral IS 'ES employment situation SITUPER: activo, pensionista or desempleado; null = undeclared, never defaulted.';


--
-- Name: COLUMN employee_payroll_profiles.jp_hyojun_hoshu; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.employee_payroll_profiles.jp_hyojun_hoshu IS 'Employee 標準報酬月額 grade value in whole yen, copied off the JPS notice; null = undeclared, never priced off raw pay.';


--
-- Name: COLUMN employee_payroll_profiles.jp_kaigo_dainigou; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.employee_payroll_profiles.jp_kaigo_dainigou IS 'Whether the employee is a 介護保険第2号被保険者, as "true"/"false" text; null = undeclared, never defaulted into the cheaper premium.';


--
-- Name: COLUMN employee_payroll_profiles.br_dependentes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.employee_payroll_profiles.br_dependentes IS 'Dependent count for the R$ 189,59 IRRF deduction, from the eSocial cadastro; null = unknown, never defaulted.';


--
-- Name: COLUMN employee_payroll_profiles.br_pensao_mensal; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.employee_payroll_profiles.br_pensao_mensal IS 'Court-ordered monthly alimony reducing the IRRF base; null = none ordered, never zero-filled.';


--
-- Name: COLUMN employee_payroll_profiles.sui_exempt; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.employee_payroll_profiles.sui_exempt IS 'State unemployment insurance exemption for this employment; independent of federal FUTA exemption.';


--
-- Name: COLUMN employee_payroll_profiles.br_salario_familia_filhos; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.employee_payroll_profiles.br_salario_familia_filhos IS 'Qualifying children for salário-família (<14 or disabled), from the eSocial cadastro; null = none declared, never defaulted.';


--
-- Name: COLUMN employee_payroll_profiles.es_contrato_temporal; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.employee_payroll_profiles.es_contrato_temporal IS 'ES contract type for the Seguridad Social desempleo split: "true" prices the temporary-contract 8,30% rate, "false" the indefinite 7,05% (Orden PJC/297/2026 art. 33.2.a); null = undeclared, never indefinite by fallthrough.';


--
-- Name: COLUMN employee_payroll_profiles.statutory_occupation_class; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.employee_payroll_profiles.statutory_occupation_class IS 'Statutory occupation class for rules that price by occupation (New Brunswick route salesperson, ESA s. 21(2)). Null = unrecorded; validated against the country pack at the profile boundary.';


--
-- Name: COLUMN employee_payroll_profiles.wcb_exempt; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.employee_payroll_profiles.wcb_exempt IS 'True when this employment is genuinely excluded from workers-compensation coverage (for example an owner or director the employer account does not cover). False means covered by a rate class, or uncovered and refused at calculate time.';


--
-- Name: COLUMN employee_payroll_profiles.wcb_exempt_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.employee_payroll_profiles.wcb_exempt_reason IS 'Reason for the workers-compensation exclusion, required whenever wcb_exempt is true.';


--
-- Name: CONSTRAINT employee_payroll_profiles_country ON employee_payroll_profiles; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT employee_payroll_profiles_country ON public.employee_payroll_profiles IS 'Pack-country shape check: two uppercase letters. Deliberately NOT an enumeration — packs declare which countries exist (engine/src/payroll/packs.ts), the database only rejects malformed codes.';


