--
-- Name: entitlement_plans; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.entitlement_plans (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    system_key text,
    unit text DEFAULT 'money'::text NOT NULL,
    direction text DEFAULT 'accrue'::text NOT NULL,
    accrual_method text DEFAULT 'manual'::text NOT NULL,
    accrual_value numeric(19,4),
    accrual_component_id uuid,
    payout_component_id uuid,
    liability_account_id uuid,
    cap_behavior text DEFAULT 'warn'::text NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    deposit_component_id uuid,
    allow_negative_balance boolean DEFAULT false NOT NULL,
    CONSTRAINT entitlement_plans_accrual_method CHECK ((accrual_method = ANY (ARRAY['percent_of_earnings'::text, 'per_hour_worked'::text, 'fixed_per_period'::text, 'manual'::text]))),
    CONSTRAINT entitlement_plans_accrual_nonnegative CHECK (((accrual_value IS NULL) OR (accrual_value >= (0)::numeric))),
    CONSTRAINT entitlement_plans_accrual_value CHECK (((accrual_method = 'manual'::text) OR (accrual_value IS NOT NULL))),
    CONSTRAINT entitlement_plans_alternate_shape CHECK (((system_key IS DISTINCT FROM 'stat_holiday_alternate'::text) OR ((unit = 'hours'::text) AND (accrual_method = 'manual'::text) AND (direction = 'accrue'::text)))),
    CONSTRAINT entitlement_plans_cap_behavior CHECK ((cap_behavior = ANY (ARRAY['warn'::text, 'block'::text, 'auto_payout'::text]))),
    CONSTRAINT entitlement_plans_direction CHECK ((direction = ANY (ARRAY['accrue'::text, 'owe'::text]))),
    CONSTRAINT entitlement_plans_hours_no_percent_accrual CHECK (((unit <> 'hours'::text) OR (accrual_method <> 'percent_of_earnings'::text))),
    CONSTRAINT entitlement_plans_system_key CHECK (((system_key IS NULL) OR (system_key = ANY (ARRAY['vacation'::text, 'stat_holiday_alternate'::text])))),
    CONSTRAINT entitlement_plans_unit CHECK ((unit = ANY (ARRAY['money'::text, 'hours'::text])))
);

ALTER TABLE ONLY public.entitlement_plans FORCE ROW LEVEL SECURITY;


--
-- Name: CONSTRAINT entitlement_plans_alternate_shape ON entitlement_plans; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT entitlement_plans_alternate_shape ON public.entitlement_plans IS 'The alternate-day binding is hours-denominated, manual (granted by the holiday rule, never accrued), and accrue-direction.';


--
-- Name: CONSTRAINT entitlement_plans_hours_no_percent_accrual ON entitlement_plans; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT entitlement_plans_hours_no_percent_accrual ON public.entitlement_plans IS 'An hours-denominated plan cannot accrue a percent of (money) earnings: the dollars would be stored as hours. Accrue per_hour_worked or fixed_per_period, or bank money.';


--
-- Name: CONSTRAINT entitlement_plans_system_key ON entitlement_plans; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT entitlement_plans_system_key ON public.entitlement_plans IS 'Engine bindings a plan may claim: vacation, or the statutory alternate-day-off bank granted by work-triggered holiday rules.';


