    CONSTRAINT equipment_units_nonnegative_purchase CHECK ((purchase_price >= (0)::numeric)),
    CONSTRAINT equipment_units_positive_capacity CHECK (((capacity_quantity IS NULL) OR (capacity_quantity > (0)::numeric))),
    CONSTRAINT equipment_units_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'inactive'::text, 'retired'::text]))),
    CONSTRAINT equipment_units_valid_dates CHECK (((acquired_on IS NULL) OR (in_service_on IS NULL) OR (in_service_on >= acquired_on)))
);

