--
-- Name: equity_action_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.equity_action_requests (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    subsidiary_id uuid NOT NULL,
    action text NOT NULL,
    subject_id uuid,
    subject_label text NOT NULL,
    effective_on date NOT NULL,
    reason text,
    payload jsonb NOT NULL,
    summary jsonb DEFAULT '{}'::jsonb NOT NULL,
    status text NOT NULL,
    released_without_approval boolean DEFAULT false NOT NULL,
    requested_by uuid NOT NULL,
    decided_by uuid,
    decided_at timestamp with time zone,
    decision_comment text,
    result jsonb,
    applied_at timestamp with time zone,
    idempotency_key text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT equity_action_requests_action CHECK ((action = ANY (ARRAY['void'::text, 'reverse'::text, 'repurchase'::text, 'repay'::text, 'cancel_convertible'::text, 'class_amendment'::text, 'split'::text, 'reserve_change'::text, 'mfn_election'::text, 'mfn_reversal'::text, 'compensation_run'::text, 'interest_run'::text, 'account_policy'::text, 'round_amendment'::text, 'round_void'::text]))),
    CONSTRAINT equity_action_requests_decision CHECK ((((status = 'pending_approval'::text) AND (decided_by IS NULL) AND (decided_at IS NULL) AND (applied_at IS NULL) AND (result IS NULL) AND (NOT released_without_approval)) OR ((status = 'applied'::text) AND (applied_at IS NOT NULL) AND (result IS NOT NULL) AND ((released_without_approval AND (decided_by IS NULL) AND (decided_at IS NULL)) OR ((NOT released_without_approval) AND (decided_by IS NOT NULL) AND (decided_at IS NOT NULL)))) OR ((status = 'rejected'::text) AND (decided_by IS NOT NULL) AND (decided_at IS NOT NULL) AND ((length(btrim(decision_comment)) >= 1) AND (length(btrim(decision_comment)) <= 2000)) AND (applied_at IS NULL) AND (NOT released_without_approval)) OR ((status = 'withdrawn'::text) AND (decided_by IS NOT NULL) AND (decided_by = requested_by) AND (decided_at IS NOT NULL) AND (decision_comment IS NOT NULL) AND ((length(btrim(decision_comment)) >= 5) AND (length(btrim(decision_comment)) <= 2000)) AND (applied_at IS NULL) AND (result IS NULL) AND (NOT released_without_approval)))),
    CONSTRAINT equity_action_requests_label CHECK (((length(btrim(subject_label)) >= 1) AND (length(btrim(subject_label)) <= 200))),
    CONSTRAINT equity_action_requests_payload CHECK (((jsonb_typeof(payload) = 'object'::text) AND (jsonb_typeof(summary) = 'object'::text))),
    CONSTRAINT equity_action_requests_reason CHECK (((reason IS NULL) OR (length(reason) <= 2000))),
    CONSTRAINT equity_action_requests_status CHECK ((status = ANY (ARRAY['pending_approval'::text, 'applied'::text, 'rejected'::text, 'withdrawn'::text])))
);

ALTER TABLE ONLY public.equity_action_requests FORCE ROW LEVEL SECURITY;


--
-- Name: equity_action_requests; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.equity_action_requests WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    subsidiary_id,
    action,
    subject_id,
    subject_label,
    effective_on,
    reason,
    payload,
    summary,
    status,
    released_without_approval,
    requested_by,
    decided_by,
    decided_at,
    decision_comment,
    result,
    applied_at,
    idempotency_key,
    created_at
   FROM public.equity_action_requests
  WHERE (org_id = public.openbooks_query_org_id());


