--
-- Name: equity_securities; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.equity_securities (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    subsidiary_id uuid NOT NULL,
    security_number text NOT NULL,
    kind text NOT NULL,
    holder_party_id uuid NOT NULL,
    share_class_id uuid,
    plan_id uuid,
    round_id uuid,
    source_security_id uuid,
    issue_date date NOT NULL,
    quantity bigint,
    price_per_share numeric(28,10),
    consideration_amount numeric(19,4),
    currency text NOT NULL,
    consideration_account_id uuid,
    vesting_start date,
    vesting_months integer,
    cliff_months integer,
    vesting_frequency text,
    vesting_tranches jsonb,
    acceleration text DEFAULT 'none'::text NOT NULL,
    acceleration_percent numeric(9,4),
    expiration_date date,
    option_type text,
    early_exercise boolean DEFAULT false NOT NULL,
    safe_type text,
    valuation_cap numeric(19,4),
    discount_percent numeric(9,4),
    interest_rate_percent numeric(9,4),
    interest_basis text,
    maturity_date date,
    valuation_method text,
    valuation_share_price numeric(28,10),
    volatility_percent numeric(9,4),
    risk_free_rate_percent numeric(9,4),
    expected_term_years numeric(9,4),
    dividend_yield_percent numeric(9,4),
    fair_value_per_unit numeric(28,10),
    expense_attribution text,
    memo text,
    journal_entry_id uuid,
    idempotency_key text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    mfn boolean DEFAULT false NOT NULL,
    interest_day_count text,
    unvested_repurchase_basis text,
    fx_rate numeric(19,10) DEFAULT 1 NOT NULL,
    CONSTRAINT equity_securities_acceleration CHECK ((acceleration = ANY (ARRAY['none'::text, 'single'::text, 'double'::text]))),
    CONSTRAINT equity_securities_acceleration_percent CHECK ((((acceleration = 'none'::text) AND (acceleration_percent IS NULL)) OR ((acceleration <> 'none'::text) AND (acceleration_percent > (0)::numeric) AND (acceleration_percent <= (100)::numeric)))),
    CONSTRAINT equity_securities_attribution CHECK (((expense_attribution IS NULL) OR (expense_attribution = ANY (ARRAY['straight_line'::text, 'graded'::text])))),
    CONSTRAINT equity_securities_cap CHECK (((valuation_cap IS NULL) OR (valuation_cap > (0)::numeric))),
    CONSTRAINT equity_securities_compensatory_valuation CHECK ((((kind = 'option'::text) AND (valuation_method = 'black_scholes'::text) AND (valuation_share_price > (0)::numeric) AND (volatility_percent > (0)::numeric) AND (risk_free_rate_percent IS NOT NULL) AND (expected_term_years > (0)::numeric) AND (dividend_yield_percent >= (0)::numeric) AND (fair_value_per_unit >= (0)::numeric) AND (expense_attribution IS NOT NULL)) OR ((kind = 'rsu'::text) AND (valuation_method = 'share_price'::text) AND (valuation_share_price > (0)::numeric) AND (fair_value_per_unit >= (0)::numeric) AND (expense_attribution IS NOT NULL)) OR ((kind <> ALL (ARRAY['option'::text, 'rsu'::text])) AND (valuation_method IS NULL) AND (fair_value_per_unit IS NULL) AND (expense_attribution IS NULL)))),
    CONSTRAINT equity_securities_consideration CHECK (((consideration_amount IS NULL) OR (consideration_amount >= (0)::numeric))),
    CONSTRAINT equity_securities_convertible_terms CHECK (((kind = ANY (ARRAY['safe'::text, 'note'::text])) OR ((valuation_cap IS NULL) AND (discount_percent IS NULL)))),
    CONSTRAINT equity_securities_discount CHECK (((discount_percent IS NULL) OR ((discount_percent >= (0)::numeric) AND (discount_percent < (100)::numeric)))),
    CONSTRAINT equity_securities_early_exercise CHECK (((NOT early_exercise) OR (kind = 'option'::text))),
    CONSTRAINT equity_securities_exercise_price CHECK (((kind <> ALL (ARRAY['option'::text, 'warrant'::text])) OR (price_per_share IS NOT NULL))),
    CONSTRAINT equity_securities_fx_rate CHECK ((fx_rate > (0)::numeric)),
    CONSTRAINT equity_securities_kind CHECK ((kind = ANY (ARRAY['share'::text, 'option'::text, 'rsu'::text, 'warrant'::text, 'safe'::text, 'note'::text]))),
    CONSTRAINT equity_securities_memo CHECK (((memo IS NULL) OR (length(memo) <= 2000))),
    CONSTRAINT equity_securities_mfn CHECK (((NOT mfn) OR (kind = 'safe'::text))),
    CONSTRAINT equity_securities_note_terms CHECK ((((kind = 'note'::text) AND (interest_rate_percent >= (0)::numeric) AND (interest_basis = ANY (ARRAY['simple'::text, 'compound_annual'::text, 'compound_semiannual'::text, 'compound_quarterly'::text, 'compound_monthly'::text])) AND (interest_day_count = ANY (ARRAY['actual_365'::text, 'actual_360'::text, 'thirty_360'::text, 'actual_actual'::text]))) OR ((kind <> 'note'::text) AND (interest_rate_percent IS NULL) AND (interest_basis IS NULL) AND (maturity_date IS NULL) AND (interest_day_count IS NULL)))),
    CONSTRAINT equity_securities_number CHECK (((length(btrim(security_number)) >= 1) AND (length(btrim(security_number)) <= 40))),
    CONSTRAINT equity_securities_option_type CHECK ((((kind = 'option'::text) AND (option_type = ANY (ARRAY['iso'::text, 'nso'::text]))) OR ((kind <> 'option'::text) AND (option_type IS NULL)))),
    CONSTRAINT equity_securities_plan_kind CHECK (((plan_id IS NULL) OR (kind = ANY (ARRAY['option'::text, 'rsu'::text])))),
    CONSTRAINT equity_securities_price CHECK (((price_per_share IS NULL) OR (price_per_share >= (0)::numeric))),
    CONSTRAINT equity_securities_quantity_shape CHECK ((((kind = ANY (ARRAY['share'::text, 'option'::text, 'rsu'::text, 'warrant'::text])) AND (quantity > 0) AND (share_class_id IS NOT NULL)) OR ((kind = ANY (ARRAY['safe'::text, 'note'::text])) AND (quantity IS NULL) AND (consideration_amount > (0)::numeric)))),
    CONSTRAINT equity_securities_repurchase_basis CHECK (((unvested_repurchase_basis IS NULL) OR ((kind = 'option'::text) AND early_exercise AND (unvested_repurchase_basis = ANY (ARRAY['cost'::text, 'lower_of_cost_or_fmv'::text]))))),
    CONSTRAINT equity_securities_safe_terms CHECK ((((kind = 'safe'::text) AND (safe_type = ANY (ARRAY['pre_money'::text, 'post_money'::text]))) OR ((kind <> 'safe'::text) AND (safe_type IS NULL)))),
    CONSTRAINT equity_securities_valuation_method CHECK (((valuation_method IS NULL) OR (valuation_method = ANY (ARRAY['black_scholes'::text, 'share_price'::text])))),
    CONSTRAINT equity_securities_vesting_exclusive CHECK (((vesting_tranches IS NULL) OR ((vesting_months IS NULL) AND (jsonb_typeof(vesting_tranches) = 'array'::text)))),
    CONSTRAINT equity_securities_vesting_frequency CHECK (((vesting_frequency IS NULL) OR (vesting_frequency = ANY (ARRAY['monthly'::text, 'quarterly'::text, 'annual'::text])))),
    CONSTRAINT equity_securities_vesting_kind CHECK (((kind = ANY (ARRAY['share'::text, 'option'::text, 'rsu'::text])) OR ((vesting_months IS NULL) AND (vesting_tranches IS NULL)))),
    CONSTRAINT equity_securities_vesting_shape CHECK ((((vesting_months IS NULL) AND (cliff_months IS NULL) AND (vesting_frequency IS NULL)) OR (((vesting_months >= 1) AND (vesting_months <= 600)) AND ((cliff_months >= 0) AND (cliff_months <= vesting_months)) AND (vesting_frequency IS NOT NULL) AND (vesting_start IS NOT NULL))))
);

ALTER TABLE ONLY public.equity_securities FORCE ROW LEVEL SECURITY;


--
-- Name: equity_securities; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.equity_securities WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    subsidiary_id,
    security_number,
    kind,
    holder_party_id,
    share_class_id,
    plan_id,
    round_id,
    source_security_id,
    issue_date,
    quantity,
    price_per_share,
    consideration_amount,
    currency,
    consideration_account_id,
    vesting_start,
    vesting_months,
    cliff_months,
    vesting_frequency,
    vesting_tranches,
    acceleration,
    acceleration_percent,
    expiration_date,
    option_type,
    early_exercise,
    safe_type,
    valuation_cap,
    discount_percent,
    interest_rate_percent,
    interest_basis,
    maturity_date,
    valuation_method,
    valuation_share_price,
    volatility_percent,
    risk_free_rate_percent,
    expected_term_years,
    dividend_yield_percent,
    fair_value_per_unit,
    expense_attribution,
    memo,
    journal_entry_id,
    idempotency_key,
    created_at,
    created_by,
    mfn,
    interest_day_count,
    unvested_repurchase_basis,
    fx_rate
   FROM public.equity_securities
  WHERE (org_id = public.openbooks_query_org_id());


--
-- Name: equity_security_amendments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.equity_security_amendments (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    subsidiary_id uuid NOT NULL,
    security_id uuid NOT NULL,
    kind text NOT NULL,
    effective_on date NOT NULL,
    source_security_id uuid NOT NULL,
    valuation_cap numeric(19,4),
    discount_percent numeric(9,4),
    safe_type text NOT NULL,
    reason text NOT NULL,
    idempotency_key text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    reverses_amendment_id uuid,
    CONSTRAINT equity_security_amendments_cap CHECK (((valuation_cap IS NULL) OR (valuation_cap > (0)::numeric))),
    CONSTRAINT equity_security_amendments_discount CHECK (((discount_percent IS NULL) OR ((discount_percent >= (0)::numeric) AND (discount_percent < (100)::numeric)))),
    CONSTRAINT equity_security_amendments_kind CHECK ((kind = ANY (ARRAY['mfn_election'::text, 'mfn_reversal'::text]))),
    CONSTRAINT equity_security_amendments_reason CHECK (((length(btrim(reason)) >= 5) AND (length(btrim(reason)) <= 2000))),
    CONSTRAINT equity_security_amendments_safe_type CHECK ((safe_type = ANY (ARRAY['pre_money'::text, 'post_money'::text]))),
    CONSTRAINT equity_security_amendments_source CHECK ((source_security_id <> security_id)),
    CONSTRAINT equity_security_amendments_terms CHECK ((((kind = 'mfn_election'::text) AND (reverses_amendment_id IS NULL) AND ((valuation_cap IS NOT NULL) OR (discount_percent IS NOT NULL))) OR ((kind = 'mfn_reversal'::text) AND (reverses_amendment_id IS NOT NULL) AND (reverses_amendment_id IS DISTINCT FROM id))))
);

ALTER TABLE ONLY public.equity_security_amendments FORCE ROW LEVEL SECURITY;


--
-- Name: equity_security_amendments; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.equity_security_amendments WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    subsidiary_id,
    security_id,
    kind,
    effective_on,
    source_security_id,
    valuation_cap,
    discount_percent,
    safe_type,
    reason,
    idempotency_key,
    created_at,
    created_by,
    reverses_amendment_id
   FROM public.equity_security_amendments
  WHERE (org_id = public.openbooks_query_org_id());


--
-- Name: equity_security_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.equity_security_events (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    subsidiary_id uuid NOT NULL,
    security_id uuid NOT NULL,
    kind text NOT NULL,
    effective_on date NOT NULL,
    quantity bigint,
    price_per_share numeric(28,10),
    amount numeric(19,4),
    resulting_security_id uuid,
    round_id uuid,
    consideration_account_id uuid,
    journal_entry_id uuid,
    reversal_entry_id uuid,
    reason text,
    idempotency_key text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    reverses_event_id uuid,
    interest_amount numeric(19,4),
    interest_accrued_amount numeric(19,4),
    interest_accrued_functional numeric(19,4),
    interest_accrual_entry_id uuid,
    deposit_amount numeric(19,4),
    fair_market_value numeric(28,10),
    fx_rate numeric(19,10),
    CONSTRAINT equity_security_events_amount CHECK (((amount IS NULL) OR (amount >= (0)::numeric))),
    CONSTRAINT equity_security_events_deposit CHECK (((deposit_amount IS NULL) OR ((deposit_amount >= (0)::numeric) AND (kind = ANY (ARRAY['exercise'::text, 'repurchase'::text]))))),
    CONSTRAINT equity_security_events_fair_market_value CHECK (((fair_market_value IS NULL) OR ((fair_market_value >= (0)::numeric) AND (kind = 'repurchase'::text)))),
    CONSTRAINT equity_security_events_fx_rate CHECK (((fx_rate IS NULL) OR (fx_rate > (0)::numeric))),
    CONSTRAINT equity_security_events_interest CHECK ((((interest_amount IS NULL) OR (interest_amount >= (0)::numeric)) AND ((interest_accrued_amount IS NULL) = (interest_accrued_functional IS NULL)) AND ((interest_accrual_entry_id IS NULL) OR (interest_accrued_amount IS NOT NULL)))),
    CONSTRAINT equity_security_events_kind CHECK ((kind = ANY (ARRAY['exercise'::text, 'settle'::text, 'forfeit'::text, 'expire'::text, 'cancel'::text, 'repurchase'::text, 'transfer'::text, 'convert'::text, 'void'::text, 'repay'::text, 'reverse'::text, 'election_83b'::text]))),
    CONSTRAINT equity_security_events_price CHECK (((price_per_share IS NULL) OR (price_per_share >= (0)::numeric))),
    CONSTRAINT equity_security_events_quantity CHECK (((quantity IS NULL) OR (quantity > 0))),
    CONSTRAINT equity_security_events_quantity_required CHECK ((((kind = ANY (ARRAY['exercise'::text, 'settle'::text, 'forfeit'::text, 'expire'::text, 'transfer'::text, 'repurchase'::text])) AND (quantity IS NOT NULL)) OR ((kind = 'cancel'::text) AND ((quantity IS NULL) <> (amount IS NULL))) OR ((kind = 'repay'::text) AND (quantity IS NULL) AND (amount IS NOT NULL)) OR ((kind = ANY (ARRAY['reverse'::text, 'election_83b'::text])) AND (quantity IS NULL) AND (amount IS NULL)) OR (kind = ANY (ARRAY['void'::text, 'convert'::text])))),
    CONSTRAINT equity_security_events_reason CHECK ((((kind = ANY (ARRAY['forfeit'::text, 'expire'::text, 'cancel'::text, 'repurchase'::text, 'void'::text, 'reverse'::text])) AND ((length(btrim(reason)) >= 5) AND (length(btrim(reason)) <= 2000))) OR ((kind <> ALL (ARRAY['forfeit'::text, 'expire'::text, 'cancel'::text, 'repurchase'::text, 'void'::text, 'reverse'::text])) AND ((reason IS NULL) OR (length(reason) <= 2000))))),
    CONSTRAINT equity_security_events_result CHECK ((((kind = ANY (ARRAY['exercise'::text, 'settle'::text, 'transfer'::text, 'convert'::text])) AND (resulting_security_id IS NOT NULL)) OR ((kind <> ALL (ARRAY['exercise'::text, 'settle'::text, 'transfer'::text, 'convert'::text])) AND (resulting_security_id IS NULL)))),
    CONSTRAINT equity_security_events_reversal CHECK ((((kind = 'reverse'::text) = (reverses_event_id IS NOT NULL)) AND (reverses_event_id IS DISTINCT FROM id)))
);

ALTER TABLE ONLY public.equity_security_events FORCE ROW LEVEL SECURITY;


--
-- Name: equity_security_events; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.equity_security_events WITH (security_barrier='true') AS
 SELECT id,
    org_id,
