    quantity,
    price_per_share,
    amount,
    resulting_security_id,
    round_id,
    consideration_account_id,
    journal_entry_id,
    reversal_entry_id,
    reason,
    idempotency_key,
    created_at,
    created_by,
    reverses_event_id,
    interest_amount,
    interest_accrued_amount,
    interest_accrued_functional,
    interest_accrual_entry_id,
    deposit_amount,
    fair_market_value,
    fx_rate
   FROM public.equity_security_events
  WHERE (org_id = public.openbooks_query_org_id());


--
-- Name: equity_share_classes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.equity_share_classes (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    subsidiary_id uuid NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    kind text NOT NULL,
    effective_on date NOT NULL,
    initial_authorized_shares bigint NOT NULL,
    par_value numeric(28,10) NOT NULL,
    original_issue_price numeric(28,10),
    initial_conversion_price numeric(28,10),
    liquidation_multiple numeric(10,4),
    participation text DEFAULT 'none'::text NOT NULL,
    participation_cap_multiple numeric(10,4),
    seniority integer DEFAULT 0 NOT NULL,
    anti_dilution text DEFAULT 'none'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    conversion_share_class_id uuid,
    conversion_adjusts_for_splits boolean DEFAULT true NOT NULL,
    liquidation_preference_basis text DEFAULT 'amount_paid'::text NOT NULL,
    CONSTRAINT equity_share_classes_anti_dilution CHECK ((anti_dilution = ANY (ARRAY['none'::text, 'broad_based'::text, 'narrow_based'::text, 'full_ratchet'::text]))),
    CONSTRAINT equity_share_classes_authorized CHECK ((initial_authorized_shares > 0)),
    CONSTRAINT equity_share_classes_cap CHECK ((((participation = 'capped'::text) AND (participation_cap_multiple IS NOT NULL) AND (participation_cap_multiple > COALESCE(liquidation_multiple, (0)::numeric))) OR ((participation <> 'capped'::text) AND (participation_cap_multiple IS NULL)))),
    CONSTRAINT equity_share_classes_code CHECK (((length(btrim(code)) >= 1) AND (length(btrim(code)) <= 40))),
    CONSTRAINT equity_share_classes_conversion_class CHECK (((conversion_share_class_id IS NULL) OR ((kind = 'preferred'::text) AND (conversion_share_class_id <> id)))),
    CONSTRAINT equity_share_classes_kind CHECK ((kind = ANY (ARRAY['common'::text, 'preferred'::text]))),
    CONSTRAINT equity_share_classes_name CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 200))),
    CONSTRAINT equity_share_classes_par CHECK ((par_value >= (0)::numeric)),
    CONSTRAINT equity_share_classes_participation CHECK ((participation = ANY (ARRAY['none'::text, 'full'::text, 'capped'::text]))),
    CONSTRAINT equity_share_classes_preference_basis CHECK ((liquidation_preference_basis = ANY (ARRAY['original_issue_price'::text, 'amount_paid'::text]))),
    CONSTRAINT equity_share_classes_preferred_terms CHECK ((((kind = 'common'::text) AND (original_issue_price IS NULL) AND (initial_conversion_price IS NULL) AND (liquidation_multiple IS NULL) AND (participation = 'none'::text) AND (participation_cap_multiple IS NULL) AND (anti_dilution = 'none'::text)) OR ((kind = 'preferred'::text) AND (original_issue_price > (0)::numeric) AND (initial_conversion_price > (0)::numeric) AND (liquidation_multiple >= (0)::numeric))))
);

ALTER TABLE ONLY public.equity_share_classes FORCE ROW LEVEL SECURITY;


--
-- Name: equity_share_classes; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.equity_share_classes WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    subsidiary_id,
    code,
    name,
    kind,
    effective_on,
    initial_authorized_shares,
    par_value,
    original_issue_price,
    initial_conversion_price,
    liquidation_multiple,
    participation,
    participation_cap_multiple,
    seniority,
    anti_dilution,
    created_at,
    created_by,
    conversion_share_class_id,
    conversion_adjusts_for_splits,
    liquidation_preference_basis
   FROM public.equity_share_classes
  WHERE (org_id = public.openbooks_query_org_id());


--
-- Name: equity_splits; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.equity_splits (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    subsidiary_id uuid NOT NULL,
    share_class_id uuid NOT NULL,
    effective_on date NOT NULL,
    ratio_numerator bigint NOT NULL,
    ratio_denominator bigint NOT NULL,
    reason text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT equity_splits_ratio CHECK (((ratio_numerator > 0) AND (ratio_denominator > 0) AND (ratio_numerator <> ratio_denominator))),
    CONSTRAINT equity_splits_reason CHECK (((length(btrim(reason)) >= 5) AND (length(btrim(reason)) <= 2000)))
);

ALTER TABLE ONLY public.equity_splits FORCE ROW LEVEL SECURITY;


--
-- Name: equity_splits; Type: VIEW; Schema: openbooks_query; Owner: -
