CREATE VIEW openbooks_query.equity_splits WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    subsidiary_id,
    share_class_id,
    effective_on,
    ratio_numerator,
    ratio_denominator,
    reason,
    created_at,
    created_by
   FROM public.equity_splits
  WHERE (org_id = public.openbooks_query_org_id());


--
-- Name: expense_amortization_schedule_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.expense_amortization_schedule_events (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    schedule_id uuid NOT NULL,
    kind text NOT NULL,
    effective_period_on date,
    effective_on date NOT NULL,
    balance_delta numeric(19,4) DEFAULT 0 NOT NULL,
    reason text NOT NULL,
    before_state jsonb,
    after_state jsonb NOT NULL,
    journal_entry_id uuid,
    related_document_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT expense_amortization_schedule_events_kind_check CHECK ((kind = ANY (ARRAY['created'::text, 'activated'::text, 'held'::text, 'resumed'::text, 'term_changed'::text, 'destination_changed'::text, 'reduced'::text, 'cancelled'::text, 'source_voided'::text, 'completed'::text]))),
    CONSTRAINT expense_amortization_schedule_events_period_check CHECK (((effective_period_on IS NULL) OR (effective_period_on = (date_trunc('month'::text, (effective_period_on)::timestamp with time zone))::date))),
    CONSTRAINT expense_amortization_schedule_events_reason_check CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 2000))),
    CONSTRAINT expense_amortization_schedule_events_state_check CHECK (((jsonb_typeof(after_state) = 'object'::text) AND ((before_state IS NULL) OR (jsonb_typeof(before_state) = 'object'::text))))
);

ALTER TABLE ONLY public.expense_amortization_schedule_events FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE expense_amortization_schedule_events; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.expense_amortization_schedule_events IS 'Append-only schedule history: every lifecycle change with its reason and before/after state.';


--
-- Name: COLUMN expense_amortization_schedule_events.balance_delta; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.expense_amortization_schedule_events.balance_delta IS 'Change to the unamortized balance on effective_on, besides posted plan lines; the subledger balance as of a date is the sum of deltas less posted lines through that date.';


--
-- Name: expense_amortization_schedule_events; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.expense_amortization_schedule_events WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    schedule_id,
    kind,
    effective_period_on,
    effective_on,
    balance_delta,
    reason,
    before_state,
    after_state,
    journal_entry_id,
    related_document_id,
    created_at,
    created_by
   FROM public.expense_amortization_schedule_events
  WHERE (org_id = public.openbooks_query_org_id());


--
-- Name: expense_amortization_schedule_lines; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.expense_amortization_schedule_lines (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    schedule_id uuid NOT NULL,
    plan_revision integer NOT NULL,
    period_start date NOT NULL,
    period_end date NOT NULL,
    weight bigint NOT NULL,
    planned_amount numeric(19,4) NOT NULL,
    destination_account_id uuid NOT NULL,
    status text DEFAULT 'planned'::text NOT NULL,
    journal_entry_id uuid,
    posted_at timestamp with time zone,
    posted_by uuid,
    closed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT expense_amortization_schedule_lines_amount_check CHECK (((planned_amount >= (0)::numeric) AND (weight >= 0))),
    CONSTRAINT expense_amortization_schedule_lines_period_check CHECK (((period_start = (date_trunc('month'::text, (period_start)::timestamp with time zone))::date) AND (period_end = ((date_trunc('month'::text, (period_start)::timestamp with time zone) + '1 mon -1 days'::interval))::date))),
    CONSTRAINT expense_amortization_schedule_lines_posted_check CHECK ((((status = 'posted'::text) = (journal_entry_id IS NOT NULL)) AND ((status = 'posted'::text) = (posted_at IS NOT NULL)) AND ((status = ANY (ARRAY['superseded'::text, 'cancelled'::text])) = (closed_at IS NOT NULL)))),
    CONSTRAINT expense_amortization_schedule_lines_revision_check CHECK ((plan_revision >= 1)),
    CONSTRAINT expense_amortization_schedule_lines_status_check CHECK ((status = ANY (ARRAY['planned'::text, 'posted'::text, 'superseded'::text, 'cancelled'::text])))
);

