--
-- Name: expense_amortization_schedules; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.expense_amortization_schedules (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    schedule_number text NOT NULL,
    status text NOT NULL,
    source_kind text NOT NULL,
    source_document_id uuid,
    source_line_id uuid,
    source_entry_id uuid,
    template_id uuid NOT NULL,
    method text NOT NULL,
    term_source text NOT NULL,
    period_offset integer NOT NULL,
    subsidiary_id uuid NOT NULL,
    book_id uuid NOT NULL,
    currency text NOT NULL,
    total_amount numeric(19,4) NOT NULL,
    opening_amortized_amount numeric(19,4) DEFAULT 0 NOT NULL,
    reversed_amount numeric(19,4) DEFAULT 0 NOT NULL,
    service_start_on date NOT NULL,
    service_end_on date NOT NULL,
    first_period_on date NOT NULL,
    deferral_account_id uuid NOT NULL,
    destination_account_id uuid NOT NULL,
    department_id uuid,
    project_id uuid,
    location_id uuid,
    class_id uuid,
    extra_dims jsonb DEFAULT '{}'::jsonb NOT NULL,
    memo text,
    hold_reason text,
    revision integer DEFAULT 1 NOT NULL,
    completed_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT expense_amortization_schedules_accounts_distinct CHECK ((destination_account_id <> deferral_account_id)),
    CONSTRAINT expense_amortization_schedules_amounts_check CHECK (((total_amount > (0)::numeric) AND (opening_amortized_amount >= (0)::numeric) AND (reversed_amount >= (0)::numeric) AND (opening_amortized_amount <= total_amount))),
    CONSTRAINT expense_amortization_schedules_draft_manual_check CHECK (((status <> 'draft'::text) OR (source_kind = 'manual'::text))),
    CONSTRAINT expense_amortization_schedules_first_period_check CHECK ((first_period_on = (date_trunc('month'::text, (first_period_on)::timestamp with time zone))::date)),
    CONSTRAINT expense_amortization_schedules_hold_check CHECK (((status = 'on_hold'::text) = (hold_reason IS NOT NULL))),
    CONSTRAINT expense_amortization_schedules_method_check CHECK ((method = ANY (ARRAY['straight_line'::text, 'prorated_first_last'::text, 'exact_days'::text, 'variable'::text]))),
    CONSTRAINT expense_amortization_schedules_revision_check CHECK ((revision >= 1)),
    CONSTRAINT expense_amortization_schedules_source_check CHECK ((((source_kind = 'manual'::text) = (source_document_id IS NULL)) AND ((source_document_id IS NULL) = (source_line_id IS NULL)) AND ((source_document_id IS NULL) = (source_entry_id IS NULL)))),
    CONSTRAINT expense_amortization_schedules_source_kind_check CHECK ((source_kind = ANY (ARRAY['vendor_bill'::text, 'journal'::text, 'expense_report'::text, 'manual'::text]))),
    CONSTRAINT expense_amortization_schedules_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'on_hold'::text, 'completed'::text, 'cancelled'::text]))),
    CONSTRAINT expense_amortization_schedules_term_source_check CHECK ((term_source = ANY (ARRAY['template'::text, 'service_dates'::text]))),
    CONSTRAINT expense_amortization_schedules_window_check CHECK ((service_end_on >= service_start_on))
);

