--
-- Name: expense_amortization_templates; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.expense_amortization_templates (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    description text,
    effective_from date NOT NULL,
    method text NOT NULL,
    term_source text NOT NULL,
    period_count integer,
    percentages jsonb,
    deferral_account_id uuid NOT NULL,
    destination_account_id uuid,
    period_offset integer DEFAULT 0 NOT NULL,
    rounding text DEFAULT 'remainder_last_period'::text NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT expense_amortization_templates_accounts_distinct CHECK (((destination_account_id IS NULL) OR (destination_account_id <> deferral_account_id))),
    CONSTRAINT expense_amortization_templates_code_check CHECK (((length(btrim(code)) >= 1) AND (length(btrim(code)) <= 64))),
    CONSTRAINT expense_amortization_templates_method_check CHECK ((method = ANY (ARRAY['straight_line'::text, 'prorated_first_last'::text, 'exact_days'::text, 'variable'::text]))),
    CONSTRAINT expense_amortization_templates_name_check CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 200))),
    CONSTRAINT expense_amortization_templates_offset_check CHECK (((period_offset >= 0) AND (period_offset <= 120))),
    CONSTRAINT expense_amortization_templates_period_count_check CHECK (((period_count IS NULL) OR ((period_count >= 1) AND (period_count <= 600)))),
    CONSTRAINT expense_amortization_templates_rounding_check CHECK ((rounding = 'remainder_last_period'::text)),
    CONSTRAINT expense_amortization_templates_term_check CHECK (((term_source <> 'template'::text) OR (period_count IS NOT NULL))),
    CONSTRAINT expense_amortization_templates_term_source_check CHECK ((term_source = ANY (ARRAY['template'::text, 'service_dates'::text]))),
    CONSTRAINT expense_amortization_templates_variable_check CHECK ((((method = 'variable'::text) = (percentages IS NOT NULL)) AND ((method <> 'variable'::text) OR ((term_source = 'template'::text) AND (jsonb_typeof(percentages) = 'array'::text) AND (jsonb_array_length(percentages) = period_count)))))
);

