-- Name: fair_value_prices; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.fair_value_prices (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    item_id uuid NOT NULL,
    currency text NOT NULL,
    unit_price numeric(19,4) NOT NULL,
    low_value numeric(19,4),
    high_value numeric(19,4),
    effective_from date,
    effective_to date,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    calculation_method text DEFAULT 'fixed'::text NOT NULL,
    formula_percent numeric(19,4),
    list_price numeric(19,4),
    unit_cost numeric(19,4),
    CONSTRAINT fair_value_formula_check CHECK (((calculation_method = ANY (ARRAY['fixed'::text, 'percent_of_list'::text, 'cost_plus'::text])) AND (unit_price >= (0)::numeric) AND ((calculation_method = 'fixed'::text) OR ((formula_percent >= (0)::numeric) AND (formula_percent IS NOT NULL) AND
CASE calculation_method
    WHEN 'percent_of_list'::text THEN ((list_price >= (0)::numeric) AND (list_price IS NOT NULL))
    ELSE ((unit_cost >= (0)::numeric) AND (unit_cost IS NOT NULL))
END))))
);

