-- Name: financial_changes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.financial_changes (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    subsidiary_id uuid NOT NULL,
    domain text NOT NULL,
    subject_id uuid NOT NULL,
    operation text NOT NULL,
    effective_on date NOT NULL,
    reason text NOT NULL,
    idempotency_key text NOT NULL,
    payload jsonb NOT NULL,
    before_state jsonb NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    submitted_by uuid NOT NULL,
    approved_by uuid,
    approved_at timestamp with time zone,
    result jsonb,
    applied_by uuid,
    applied_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    submission_policy jsonb,
    CONSTRAINT financial_change_result_only_applied CHECK (((status = 'applied'::text) OR ((result IS NULL) AND (applied_by IS NULL) AND (applied_at IS NULL)))),
    CONSTRAINT financial_changes_before_state_check CHECK ((jsonb_typeof(before_state) = 'object'::text)),
    CONSTRAINT financial_changes_check1 CHECK (((status <> ALL (ARRAY['approved'::text, 'applied'::text])) OR ((approved_by IS NOT NULL) AND (approved_at IS NOT NULL)))),
    CONSTRAINT financial_changes_check2 CHECK (((status = 'applied'::text) = ((applied_at IS NOT NULL) AND (applied_by IS NOT NULL) AND (result IS NOT NULL)))),
    CONSTRAINT financial_changes_domain_check CHECK ((domain = ANY (ARRAY['lease'::text, 'revenue'::text, 'asset'::text, 'consolidation'::text, 'manufacturing'::text, 'provision'::text, 'sales'::text, 'payroll'::text, 'ledger'::text]))),
    CONSTRAINT financial_changes_effective_on_check CHECK (((effective_on >= '0001-01-01'::date) AND (effective_on <= '9999-12-31'::date))),
    CONSTRAINT financial_changes_idempotency_key_check CHECK (((length(idempotency_key) >= 1) AND (length(idempotency_key) <= 120))),
    CONSTRAINT financial_changes_payload_check CHECK ((jsonb_typeof(payload) = 'object'::text)),
    CONSTRAINT financial_changes_reason_check CHECK (((length(btrim(reason)) >= 8) AND (length(btrim(reason)) <= 1000))),
    CONSTRAINT financial_changes_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'pending'::text, 'approved'::text, 'rejected'::text, 'applied'::text])))
);

