    CONSTRAINT fund_releases_satisfaction_ref_nonblank CHECK ((length(btrim(satisfaction_ref)) > 0)),
    CONSTRAINT fund_releases_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'pending_approval'::text, 'posted'::text, 'void'::text])))
);

