    CONSTRAINT gifts_tribute_fields_check CHECK ((((tribute_kind = 'none'::text) AND (tribute_name IS NULL) AND (tribute_notify_party_id IS NULL)) OR ((tribute_kind <> 'none'::text) AND (tribute_name IS NOT NULL) AND (btrim(tribute_name) <> ''::text)))),
    CONSTRAINT gifts_tribute_kind_check CHECK ((tribute_kind = ANY (ARRAY['none'::text, 'in_honor_of'::text, 'in_memory_of'::text])))
);

