--
-- Name: grants; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.grants (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    sponsor_party_id uuid NOT NULL,
    sponsor_kind text NOT NULL,
    determination text NOT NULL,
    barrier text,
    barrier_met_at timestamp with time zone,
    barrier_evidence text,
    right_of_return boolean DEFAULT false NOT NULL,
    award_amount numeric(19,4) NOT NULL,
    period_from date NOT NULL,
    period_to date NOT NULL,
    indirect_rate numeric(20,10) DEFAULT 0 NOT NULL,
    indirect_base text DEFAULT 'direct_costs'::text NOT NULL,
    cost_share_required boolean DEFAULT false NOT NULL,
    cost_share_amount numeric(19,4) DEFAULT 0 NOT NULL,
    fund_id uuid NOT NULL,
    allowable_account_group_id uuid NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    award_entry_id uuid,
    version integer DEFAULT 1 NOT NULL,
    supersedes_id uuid,
    custom jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    mtdc_exclusion_account_group_id uuid,
    mtdc_subaward_account_group_id uuid,
    mtdc_subaward_threshold numeric(19,4),
    CONSTRAINT grants_amount_check CHECK ((award_amount > (0)::numeric)),
    CONSTRAINT grants_barrier_evidence_pair_check CHECK ((((barrier_met_at IS NULL) = (barrier_evidence IS NULL)) AND ((barrier_evidence IS NULL) OR (length(btrim(barrier_evidence)) > 0)))),
    CONSTRAINT grants_conditional_terms_check CHECK (((determination <> 'contribution_conditional'::text) OR ((length(btrim(COALESCE(barrier, ''::text))) > 0) AND right_of_return))),
    CONSTRAINT grants_cost_share_check CHECK (((cost_share_amount >= (0)::numeric) AND (cost_share_required OR (cost_share_amount = (0)::numeric)))),
    CONSTRAINT grants_determination_check CHECK ((determination = ANY (ARRAY['contribution_unconditional'::text, 'contribution_conditional'::text, 'exchange'::text]))),
    CONSTRAINT grants_indirect_base_check CHECK ((indirect_base = ANY (ARRAY['direct_costs'::text, 'modified_total_direct'::text]))),
    CONSTRAINT grants_indirect_rate_check CHECK ((indirect_rate >= (0)::numeric)),
    CONSTRAINT grants_mtdc_config_base_check CHECK (((indirect_base = 'modified_total_direct'::text) OR ((mtdc_exclusion_account_group_id IS NULL) AND (mtdc_subaward_account_group_id IS NULL)))),
    CONSTRAINT grants_mtdc_subaward_pair_check CHECK ((((mtdc_subaward_account_group_id IS NULL) = (mtdc_subaward_threshold IS NULL)) AND ((mtdc_subaward_threshold IS NULL) OR (mtdc_subaward_threshold >= (0)::numeric)))),
    CONSTRAINT grants_not_self_superseded_check CHECK (((supersedes_id IS NULL) OR (supersedes_id <> id))),
    CONSTRAINT grants_period_check CHECK ((period_to >= period_from)),
    CONSTRAINT grants_sponsor_kind_check CHECK ((sponsor_kind = ANY (ARRAY['government'::text, 'foundation'::text, 'corporate'::text]))),
    CONSTRAINT grants_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'awarded'::text, 'active'::text, 'closed_out'::text, 'closed'::text, 'void'::text]))),
    CONSTRAINT grants_version_check CHECK ((((version = 1) AND (supersedes_id IS NULL)) OR ((version > 1) AND (supersedes_id IS NOT NULL))))
);

ALTER TABLE ONLY public.grants FORCE ROW LEVEL SECURITY;


--
-- Name: grants; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.grants WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    code,
    name,
    sponsor_party_id,
    sponsor_kind,
    determination,
    barrier,
    barrier_met_at,
    barrier_evidence,
    right_of_return,
    award_amount,
    period_from,
    period_to,
    indirect_rate,
    indirect_base,
    cost_share_required,
    cost_share_amount,
    fund_id,
    allowable_account_group_id,
    status,
    award_entry_id,
    version,
    supersedes_id,
    custom,
    created_at,
    created_by,
    updated_at,
    updated_by,
    mtdc_exclusion_account_group_id,
    mtdc_subaward_account_group_id,
    mtdc_subaward_threshold
   FROM public.grants
  WHERE (org_id = public.openbooks_query_org_id());


