    item_id uuid NOT NULL,
    stock_location_id uuid NOT NULL,
    movement_id uuid NOT NULL,
    quantity numeric(28,8) NOT NULL,
    cost_amount numeric(19,4) NOT NULL,
    cost_currency text NOT NULL,
    transfer_currency text NOT NULL,
    transfer_unit_price numeric(28,8) NOT NULL,
    transfer_amount numeric(19,4) NOT NULL,
    entry_id uuid NOT NULL,
    charge_date date NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT intercompany_fulfillment_charges_amounts CHECK (((cost_amount >= (0)::numeric) AND (transfer_amount >= (0)::numeric) AND (transfer_unit_price >= (0)::numeric))),
    CONSTRAINT intercompany_fulfillment_charges_currencies CHECK (((cost_currency ~ '^[A-Z]{3}$'::text) AND (transfer_currency ~ '^[A-Z]{3}$'::text))),
    CONSTRAINT intercompany_fulfillment_charges_entities CHECK ((selling_subsidiary_id <> fulfilling_subsidiary_id)),
    CONSTRAINT intercompany_fulfillment_charges_kind CHECK ((kind = ANY (ARRAY['fulfillment'::text, 'return'::text]))),
    CONSTRAINT intercompany_fulfillment_charges_quantity CHECK ((quantity > (0)::numeric)),
    CONSTRAINT intercompany_fulfillment_charges_return_source CHECK (((kind = 'return'::text) = ((reverses_charge_id IS NOT NULL) AND (credit_document_id IS NOT NULL))))
);

ALTER TABLE ONLY public.intercompany_fulfillment_charges FORCE ROW LEVEL SECURITY;


