    CONSTRAINT intercompany_netting_runs_cancel_evidence CHECK (((status <> 'cancelled'::text) OR ((cancelled_by IS NOT NULL) AND (cancelled_at IS NOT NULL) AND (length(btrim(COALESCE(cancel_reason, ''::text))) > 0)))),
    CONSTRAINT intercompany_netting_runs_computation CHECK ((jsonb_typeof(computation) = 'object'::text)),
    CONSTRAINT intercompany_netting_runs_fingerprint CHECK ((fingerprint ~ '^[0-9a-f]{64}$'::text)),
