    CONSTRAINT intercompany_netting_runs_scope CHECK ((cardinality(subsidiary_ids) >= 2)),
    CONSTRAINT intercompany_netting_runs_status CHECK ((status = ANY (ARRAY['proposed'::text, 'pending_approval'::text, 'approved'::text, 'rejected'::text, 'posted'::text, 'cancelled'::text, 'reversed'::text])))
);

