    CONSTRAINT inspection_plan_measures CHECK (((jsonb_typeof(measures) = 'array'::text) AND (jsonb_array_length(measures) <= 100))),
    CONSTRAINT inspection_plan_point CHECK ((((point = 'receipt'::text) AND (operation_sequence IS NULL)) OR ((point = 'operation'::text) AND (operation_sequence > 0)))),
    CONSTRAINT inspection_plan_revision CHECK (((revision > 0) AND ((length(btrim(reason)) >= 5) AND (length(btrim(reason)) <= 500)))),
    CONSTRAINT inspection_plan_window CHECK (((effective_to IS NULL) OR (effective_to > effective_from)))
);

