    created_by,
    updated_by
   FROM public.inventory_inspection_plans
  WHERE (org_id = public.openbooks_query_org_id());


--
-- Name: inventory_inspections; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.inventory_inspections (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    plan_id uuid NOT NULL,
    plan_snapshot jsonb NOT NULL,
    item_id uuid NOT NULL,
    subsidiary_id uuid NOT NULL,
    stock_location_id uuid,
    receipt_movement_id uuid,
    work_order_id uuid,
    operation_id uuid,
    inspection_sequence integer,
    lot_id uuid,
    serial_id uuid,
    quantity numeric(19,4) NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    measurements jsonb DEFAULT '{}'::jsonb NOT NULL,
    reason text,
    inspected_at timestamp with time zone,
    inspected_by uuid,
    disposition text,
    disposition_reason text,
    disposition_result jsonb,
    disposed_at timestamp with time zone,
    disposed_by uuid,
    rework_operation_id uuid,
    rework_completed_at timestamp with time zone,
    scrap_movement_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    rework_work_order_id uuid,
    CONSTRAINT inspection_disposition CHECK ((((disposition IS NULL) AND (disposed_at IS NULL) AND (disposed_by IS NULL)) OR ((status = 'fail'::text) AND (disposition = ANY (ARRAY['use_as_is'::text, 'scrap'::text, 'rework'::text])) AND (disposed_at IS NOT NULL) AND (disposed_by IS NOT NULL) AND (disposition_reason IS NOT NULL) AND (disposition_result IS NOT NULL)))),
    CONSTRAINT inspection_operation_sequence CHECK ((((operation_id IS NULL) = (inspection_sequence IS NULL)) AND ((inspection_sequence IS NULL) OR (inspection_sequence > 0)))),
    CONSTRAINT inspection_quantity CHECK ((quantity > (0)::numeric)),
    CONSTRAINT inspection_result CHECK ((((status = 'pending'::text) AND (inspected_at IS NULL) AND (inspected_by IS NULL) AND (disposition IS NULL)) OR ((status = ANY (ARRAY['pass'::text, 'fail'::text])) AND (inspected_at IS NOT NULL) AND (inspected_by IS NOT NULL)))),
    CONSTRAINT inspection_subject CHECK ((((receipt_movement_id IS NOT NULL) AND (operation_id IS NULL) AND (stock_location_id IS NOT NULL)) OR ((receipt_movement_id IS NULL) AND (operation_id IS NOT NULL) AND (work_order_id IS NOT NULL)))),
    CONSTRAINT inspection_tracking CHECK (((lot_id IS NOT NULL) OR (serial_id IS NOT NULL) OR (operation_id IS NOT NULL)))
);

ALTER TABLE ONLY public.inventory_inspections FORCE ROW LEVEL SECURITY;


--
-- Name: inventory_inspections; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.inventory_inspections WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    plan_id,
