    measurements,
    reason,
    inspected_at,
    inspected_by,
    disposition,
    disposition_reason,
    disposition_result,
    disposed_at,
    disposed_by,
    rework_operation_id,
    rework_completed_at,
    scrap_movement_id,
    created_at,
    updated_at,
    created_by,
    updated_by,
    rework_work_order_id
   FROM public.inventory_inspections
  WHERE (org_id = public.openbooks_query_org_id());


--
-- Name: inventory_movements; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.inventory_movements (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    item_id uuid NOT NULL,
    kind text NOT NULL,
    moved_at timestamp with time zone NOT NULL,
    stock_location_id uuid NOT NULL,
    lot_id uuid,
    serial_id uuid,
    quantity numeric(19,4) NOT NULL,
    unit_cost numeric(19,4),
    total_value numeric(19,4),
    document_line_id uuid,
    journal_entry_id uuid,
    paired_movement_id uuid,
    status text DEFAULT 'pending'::text NOT NULL,
    memo text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    reverses_movement_id uuid,
    reversal_reason text,
    idempotency_key text,
    subsidiary_id uuid NOT NULL,
    assembly_disassembly_id uuid,
    CONSTRAINT inv_moves_qty_nonzero CHECK ((quantity <> (0)::numeric)),
    CONSTRAINT inv_moves_reversal_evidence CHECK ((((reverses_movement_id IS NULL) AND (reversal_reason IS NULL)) OR ((reverses_movement_id IS NOT NULL) AND (reverses_movement_id <> id) AND (reversal_reason IS NOT NULL) AND ((length(btrim(reversal_reason)) >= 5) AND (length(btrim(reversal_reason)) <= 500)) AND (created_by IS NOT NULL)))),
    CONSTRAINT inventory_disassembly_identity CHECK ((((kind = ANY (ARRAY['assembly_disassembly'::text, 'assembly_recovery'::text])) AND (assembly_disassembly_id IS NOT NULL)) OR ((kind = 'return'::text) AND (reverses_movement_id IS NOT NULL)) OR ((kind <> ALL (ARRAY['assembly_disassembly'::text, 'assembly_recovery'::text])) AND (assembly_disassembly_id IS NULL)))),
    CONSTRAINT inventory_movements_idempotency_key CHECK (((idempotency_key IS NULL) OR ((length(btrim(idempotency_key)) >= 1) AND (length(btrim(idempotency_key)) <= 500))))
);

