    CONSTRAINT item_inventory_provisional_cost CHECK (((provisional_unit_cost IS NULL) OR (provisional_unit_cost >= (0)::numeric))),
    CONSTRAINT item_inventory_standard_cost CHECK (((negative_cost_basis <> 'standard'::text) OR (standard_cost IS NOT NULL)))
);

