    CONSTRAINT item_price_schedule_dates CHECK (((effective_to IS NULL) OR (effective_to >= effective_from))),
    CONSTRAINT item_price_schedule_quantity_basis CHECK ((quantity_basis = ANY (ARRAY['line_quantity'::text, 'overall_item_quantity'::text]))),
    CONSTRAINT item_price_schedule_reason_present CHECK (((change_reason IS NULL) OR (char_length(btrim(change_reason)) > 0))),
    CONSTRAINT item_price_schedule_revision_nonnegative CHECK ((revision >= 0)),
    CONSTRAINT item_price_schedule_scope CHECK ((((customer_id IS NULL) AND (price_level_id IS NOT NULL)) OR ((customer_id IS NOT NULL) AND (price_level_id IS NULL)))),
