-- Name: journal_lines; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.journal_lines (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    entry_id uuid NOT NULL,
    line_number integer NOT NULL,
    account_id uuid NOT NULL,
    amount numeric(19,4) NOT NULL,
    currency text NOT NULL,
    txn_amount numeric(19,4) NOT NULL,
    fx_rate numeric(19,10) DEFAULT '1'::numeric NOT NULL,
    memo text,
    party_id uuid,
    department_id uuid,
    project_id uuid,
    location_id uuid,
    class_id uuid,
    payment_card_id uuid,
    extra_dims jsonb DEFAULT '{}'::jsonb NOT NULL,
    posting_date date,
    quantity numeric(19,4),
    unit text,
    due_date date,
    is_open_item boolean DEFAULT false NOT NULL,
    tax_code_id uuid,
    reconciled_at timestamp with time zone,
    reconciliation_id uuid,
    custom jsonb DEFAULT '{}'::jsonb NOT NULL,
    subsidiary_id uuid NOT NULL,
    equipment_unit_id uuid,
    source_cleared_date date,
    source_cleared_connector text,
    contributor_kind text,
    contributor_ref uuid,
    period_id uuid,
    eliminate boolean DEFAULT false NOT NULL,
    is_currency_adjustment boolean DEFAULT false NOT NULL,
    CONSTRAINT jl_fx_consistent CHECK (((is_currency_adjustment AND (txn_amount = (0)::numeric)) OR ((NOT is_currency_adjustment) AND (abs((amount - round((txn_amount * fx_rate), 4))) <= 0.005)))),
    CONSTRAINT jl_nonzero CHECK (((amount <> (0)::numeric) OR ((txn_amount = (0)::numeric) AND (quantity IS NOT NULL) AND (quantity <> (0)::numeric) AND (quantity = trunc(quantity, 4)) AND (COALESCE(length(btrim(unit)), 0) > 0) AND (NOT is_open_item) AND (NOT is_currency_adjustment)))),
    CONSTRAINT journal_lines_contributor_kind_check CHECK (((contributor_kind IS NULL) OR (contributor_kind = ANY (ARRAY['rule'::text, 'script'::text, 'app'::text, 'intercompany'::text, 'contract_cost_asset'::text])))),
    CONSTRAINT journal_lines_source_cleared_evidence CHECK ((((source_cleared_date IS NULL) AND (source_cleared_connector IS NULL)) OR ((source_cleared_date IS NOT NULL) AND (source_cleared_connector IS NOT NULL) AND (length(btrim(source_cleared_connector)) > 0))))
);

