    custom jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT mfg_work_centers_capacity_nonnegative CHECK ((capacity_hours_per_day >= (0)::numeric)),
    CONSTRAINT mfg_work_centers_department_required CHECK (((kind <> ALL (ARRAY['labor'::text, 'cell'::text])) OR (department_id IS NOT NULL))),
    CONSTRAINT mfg_work_centers_efficiency_pct CHECK (((efficiency_pct >= (0)::numeric) AND (efficiency_pct <= (100)::numeric))),
    CONSTRAINT mfg_work_centers_kind_check CHECK ((kind = ANY (ARRAY['machine'::text, 'labor'::text, 'cell'::text]))),
    CONSTRAINT mfg_work_centers_labels_nonempty CHECK (((length(btrim(code)) > 0) AND (length(btrim(name)) > 0)))
);

