--
-- Name: mfg_work_orders; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.mfg_work_orders (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    number text NOT NULL,
    produced_item_id uuid NOT NULL,
    routing_id uuid,
    bom_revision text,
    routing_version integer,
    quantity_ordered numeric(19,4) NOT NULL,
    quantity_completed numeric(19,4) DEFAULT 0 NOT NULL,
    quantity_scrapped numeric(19,4) DEFAULT 0 NOT NULL,
    unit text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    priority text DEFAULT 'normal'::text NOT NULL,
    source text DEFAULT 'manual'::text NOT NULL,
    source_ref_id uuid,
    parent_wo_id uuid,
    short_close_reason text,
    subsidiary_id uuid,
    issue_location_id uuid,
    receipt_location_id uuid,
    planned_start date,
    planned_end date,
    released_at timestamp with time zone,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    closed_at timestamp with time zone,
    hold_reason text,
    cancel_reason text,
    standard_cost_snapshot numeric(19,4),
    cost_collected numeric(19,4) DEFAULT 0 NOT NULL,
    custom jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    hold_prior_status text,
    operating_profile_version_id uuid,
    operating_department_id uuid,
    production_mode text DEFAULT 'order'::text NOT NULL,
    campaign_reference text,
    loss_change_id uuid,
    receipt_rework_inspection_id uuid,
    receipt_rework_sequence integer,
    CONSTRAINT mfg_campaign_reference CHECK (((campaign_reference IS NULL) OR ((length(btrim(campaign_reference)) >= 1) AND (length(btrim(campaign_reference)) <= 100)))),
    CONSTRAINT mfg_production_mode CHECK (((production_mode = ANY (ARRAY['order'::text, 'batch'::text, 'continuous'::text])) AND ((production_mode <> 'continuous'::text) OR ((planned_start IS NOT NULL) AND (planned_end IS NOT NULL))))),
    CONSTRAINT mfg_receipt_rework_pair CHECK ((((receipt_rework_inspection_id IS NULL) AND (receipt_rework_sequence IS NULL)) OR ((receipt_rework_inspection_id IS NOT NULL) AND (receipt_rework_sequence > 0)))),
    CONSTRAINT mfg_work_orders_costs_nonnegative CHECK (((cost_collected >= (0)::numeric) AND ((standard_cost_snapshot IS NULL) OR (standard_cost_snapshot >= (0)::numeric)))),
    CONSTRAINT mfg_work_orders_dates_ordered CHECK (((planned_end IS NULL) OR (planned_start IS NULL) OR (planned_end >= planned_start))),
    CONSTRAINT mfg_work_orders_hold_prior_status_check CHECK (((hold_prior_status IS NULL) OR (hold_prior_status = ANY (ARRAY['released'::text, 'in_progress'::text])))),
    CONSTRAINT mfg_work_orders_hold_prior_status_state_check CHECK (((status = 'on_hold'::text) = (hold_prior_status IS NOT NULL))),
    CONSTRAINT mfg_work_orders_hold_reason CHECK (((status <> 'on_hold'::text) OR ((hold_reason IS NOT NULL) AND (length(btrim(hold_reason)) > 0)))),
    CONSTRAINT mfg_work_orders_labels_nonempty CHECK (((length(btrim(number)) > 0) AND (length(btrim(unit)) > 0))),
    CONSTRAINT mfg_work_orders_parent_reference CHECK ((((source = 'parent'::text) AND (parent_wo_id IS NOT NULL)) OR ((source <> 'parent'::text) AND (parent_wo_id IS NULL)))),
    CONSTRAINT mfg_work_orders_priority_check CHECK ((priority = ANY (ARRAY['low'::text, 'normal'::text, 'high'::text, 'rush'::text]))),
    CONSTRAINT mfg_work_orders_quantities_nonnegative CHECK (((quantity_ordered >= (0)::numeric) AND (quantity_completed >= (0)::numeric) AND (quantity_scrapped >= (0)::numeric))),
    CONSTRAINT mfg_work_orders_routing_version_positive CHECK (((routing_version IS NULL) OR (routing_version > 0))),
    CONSTRAINT mfg_work_orders_short_close_reason CHECK (((status <> 'closed'::text) OR (quantity_completed >= quantity_ordered) OR ((short_close_reason IS NOT NULL) AND (length(btrim(short_close_reason)) > 0)))),
    CONSTRAINT mfg_work_orders_source_check CHECK ((source = ANY (ARRAY['manual'::text, 'mrp'::text, 'sales_order'::text, 'parent'::text]))),
    CONSTRAINT mfg_work_orders_source_reference CHECK ((((source = 'manual'::text) AND (source_ref_id IS NULL)) OR ((source <> 'manual'::text) AND (source_ref_id IS NOT NULL)))),
    CONSTRAINT mfg_work_orders_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'released'::text, 'in_progress'::text, 'on_hold'::text, 'done'::text, 'closed'::text, 'cancelled'::text])))
);

ALTER TABLE ONLY public.mfg_work_orders FORCE ROW LEVEL SECURITY;


--
-- Name: mfg_work_orders; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.mfg_work_orders WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    number,
    produced_item_id,
    routing_id,
