    quantity_ordered,
    quantity_completed,
    quantity_scrapped,
    unit,
    status,
    priority,
    source,
    source_ref_id,
    parent_wo_id,
    short_close_reason,
    subsidiary_id,
    issue_location_id,
    receipt_location_id,
    planned_start,
    planned_end,
    released_at,
    started_at,
    completed_at,
    closed_at,
    hold_reason,
    cancel_reason,
    standard_cost_snapshot,
