--
-- Name: org_business_calendars; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.org_business_calendars (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    subsidiary_id uuid,
    week_starts_on smallint NOT NULL,
    weekend_days smallint[] NOT NULL,
    holiday_country character(2),
    holiday_region text,
    effective_from date NOT NULL,
    effective_to date,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT org_business_calendars_country_check CHECK (((holiday_country IS NULL) OR (holiday_country ~ '^[A-Z]{2}$'::text))),
    CONSTRAINT org_business_calendars_effective_from_range CHECK (((effective_from >= '0001-01-01'::date) AND (effective_from <= '9999-12-31'::date))),
    CONSTRAINT org_business_calendars_region_check CHECK (((holiday_region IS NULL) OR ((holiday_region <> ''::text) AND ((length(holiday_region) >= 1) AND (length(holiday_region) <= 16))))),
    CONSTRAINT org_business_calendars_region_needs_country CHECK (((holiday_region IS NULL) OR (holiday_country IS NOT NULL))),
    CONSTRAINT org_business_calendars_week_start_check CHECK (((week_starts_on >= 1) AND (week_starts_on <= 7))),
    CONSTRAINT org_business_calendars_weekend_days_check CHECK (public.business_calendar_weekend_valid(weekend_days)),
    CONSTRAINT org_business_calendars_window_valid CHECK (((effective_to IS NULL) OR ((effective_to >= effective_from) AND (effective_to <= '9999-12-31'::date))))
);

ALTER TABLE ONLY public.org_business_calendars FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE org_business_calendars; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.org_business_calendars IS 'Effective-dated business calendar per organization or subsidiary: ISO week start (1=Monday..7=Sunday), weekend days as ISO weekdays, and the country plus optional region whose statutory holidays apply. The row with the latest effective_from on or before a date governs that date.';


