--
-- Name: pay_components; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.pay_components (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    kind text NOT NULL,
    system_key text,
    basis text DEFAULT 'fixed_amount'::text NOT NULL,
    value numeric(19,4),
    taxable boolean DEFAULT true NOT NULL,
    pensionable boolean DEFAULT true NOT NULL,
    insurable boolean DEFAULT true NOT NULL,
    vacationable boolean DEFAULT true NOT NULL,
    non_periodic boolean DEFAULT false NOT NULL,
    tax_treatment text DEFAULT 'none'::text NOT NULL,
    expense_account_id uuid,
    liability_account_id uuid,
    remittance_party_id uuid,
    sequence integer DEFAULT 100 NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    country text,
    protection_base text DEFAULT 'none'::text NOT NULL,
    protection_max_percent numeric(7,4),
    protection_priority integer DEFAULT 100 NOT NULL,
    include_in_disposable_earnings boolean DEFAULT true NOT NULL,
    basis_cap_hours_per_period numeric(12,2),
    basis_cap_amount_per_period numeric(19,4),
    basis_cap_amount_per_year numeric(19,4),
    payment_kind text DEFAULT 'cash'::text NOT NULL,
    non_cash_account_id uuid,
    unit_of_measure text DEFAULT 'hours'::text NOT NULL,
    protection_class text,
    CONSTRAINT pay_components_basis CHECK ((basis = ANY (ARRAY['fixed_amount'::text, 'per_hour'::text, 'percent_of_gross'::text]))),
    CONSTRAINT pay_components_basis_cap_order CHECK (((basis_cap_amount_per_period IS NULL) OR (basis_cap_amount_per_year IS NULL) OR (basis_cap_amount_per_period <= basis_cap_amount_per_year))),
    CONSTRAINT pay_components_basis_caps_nonnegative CHECK ((((basis_cap_hours_per_period IS NULL) OR (basis_cap_hours_per_period >= (0)::numeric)) AND ((basis_cap_amount_per_period IS NULL) OR (basis_cap_amount_per_period >= (0)::numeric)) AND ((basis_cap_amount_per_year IS NULL) OR (basis_cap_amount_per_year >= (0)::numeric)))),
    CONSTRAINT pay_components_country CHECK (((country IS NULL) OR (country ~ '^[A-Z]{2}$'::text))),
    CONSTRAINT pay_components_kind CHECK ((kind = ANY (ARRAY['earning'::text, 'deduction'::text, 'employer_contribution'::text, 'credit'::text]))),
    CONSTRAINT pay_components_non_cash_shape CHECK ((((payment_kind = 'cash'::text) AND (non_cash_account_id IS NULL)) OR ((payment_kind = 'non_cash'::text) AND (kind = 'earning'::text) AND (system_key IS NULL) AND (non_cash_account_id IS NOT NULL)))),
    CONSTRAINT pay_components_payment_kind CHECK ((payment_kind = ANY (ARRAY['cash'::text, 'non_cash'::text]))),
    CONSTRAINT pay_components_per_hour_hours CHECK (((basis <> 'per_hour'::text) OR (unit_of_measure = 'hours'::text))),
    CONSTRAINT pay_components_protection_base_check CHECK ((protection_base = ANY (ARRAY['none'::text, 'net_pay'::text, 'disposable_earnings'::text, 'gross'::text]))),
    CONSTRAINT pay_components_protection_class CHECK (((protection_class IS NULL) OR ((protection_base <> 'none'::text) AND (protection_class ~ '^[a-z][a-z0-9_]{0,63}$'::text)))),
    CONSTRAINT pay_components_protection_deduction_only CHECK (((protection_base = 'none'::text) OR (kind = 'deduction'::text))),
    CONSTRAINT pay_components_protection_percent CHECK (((protection_max_percent IS NULL) OR ((protection_max_percent >= (0)::numeric) AND (protection_max_percent <= (100)::numeric)))),
    CONSTRAINT pay_components_protection_priority CHECK ((protection_priority >= 0)),
    CONSTRAINT pay_components_protection_shape CHECK (((protection_base = 'none'::text) OR (protection_max_percent IS NOT NULL))),
    CONSTRAINT pay_components_system_key CHECK (((system_key IS NULL) OR (system_key ~ '^[a-z][a-z0-9_]{0,63}$'::text))),
    CONSTRAINT pay_components_tax_treatment CHECK ((tax_treatment ~ '^[a-z][a-z0-9_]{0,63}$'::text)),
    CONSTRAINT pay_components_unit_of_measure CHECK ((unit_of_measure = ANY (ARRAY['hours'::text, 'quantity'::text])))
);

ALTER TABLE ONLY public.pay_components FORCE ROW LEVEL SECURITY;


--
-- Name: COLUMN pay_components.vacationable; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pay_components.vacationable IS 'Creation-only initial vacation-base default. Payroll resolves vacation-base inclusion from pay_component_statutory_treatments at pay date.';


--
-- Name: COLUMN pay_components.protection_class; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pay_components.protection_class IS 'Country-pack-declared class of protected order (creditor garnishment, support order) selecting its statutory limit; null applies the configured percentage alone.';


--
-- Name: CONSTRAINT pay_components_country ON pay_components; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT pay_components_country ON public.pay_components IS 'Pack-country shape check: NULL (shared component) or two uppercase letters. Deliberately NOT an enumeration — packs declare which countries exist (engine/src/payroll/packs.ts), the database only rejects malformed codes.';


--
-- Name: CONSTRAINT pay_components_kind ON pay_components; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT pay_components_kind ON public.pay_components IS 'Component kinds: earning, deduction, employer_contribution, credit. Credit pays a refundable employment credit the employer reclaims from the tax authority (engine/src/payroll/packs.ts).';


--
-- Name: CONSTRAINT pay_components_tax_treatment ON pay_components; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT pay_components_tax_treatment ON public.pay_components IS 'Treatment shape check: non-empty lower-snake identifier. Deliberately NOT an enumeration — packs declare which treatments exist (PayrollCountryPack.deductionTreatments, enforced at the API boundary by payComponentTreatmentProblem); the database only rejects malformed values.';


