    note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    employment_id uuid,
    earned_from date,
    earned_to date,
    CONSTRAINT pay_run_adjustments_earned_dates CHECK ((((earned_from IS NULL) AND (earned_to IS NULL)) OR ((adjustment_type = 'line'::text) AND (earned_from IS NOT NULL) AND (earned_to IS NOT NULL) AND (earned_from <= earned_to)))),
    CONSTRAINT pay_run_adjustments_line_shape CHECK (((adjustment_type <> 'line'::text) OR ((component_id IS NOT NULL) AND (amount IS NOT NULL)))),
    CONSTRAINT pay_run_adjustments_type CHECK ((adjustment_type = ANY (ARRAY['line'::text, 'exclude'::text])))
);

