--
-- Name: pay_stub_lines; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.pay_stub_lines (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    stub_id uuid NOT NULL,
    component_id uuid,
    kind text NOT NULL,
    description text NOT NULL,
    hours numeric(12,2),
    rate numeric(19,4),
    amount numeric(19,4) NOT NULL,
    project_id uuid,
    department_id uuid,
    time_type_id uuid,
    sequence integer DEFAULT 100 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    liability_account_id uuid,
    liability_account_source text DEFAULT 'unknown'::text NOT NULL,
    liability_account_evidence jsonb,
    item_id uuid,
    expense_account_id uuid,
    expense_account_source text DEFAULT 'unknown'::text NOT NULL,
    expense_account_evidence jsonb,
    remittance_party_id uuid,
    earned_from date,
    earned_to date,
    statutory_reporting_code jsonb,
    payment_kind text DEFAULT 'cash'::text NOT NULL,
    non_cash_account_id uuid,
    derived_quantity numeric(24,4),
    derived_rule_code text,
    CONSTRAINT pay_stub_lines_derived_quantity_evidence CHECK ((((derived_quantity IS NULL) AND (derived_rule_code IS NULL)) OR ((derived_quantity IS NOT NULL) AND (derived_quantity > (0)::numeric) AND (derived_quantity <> 'NaN'::numeric) AND (derived_rule_code IS NOT NULL) AND (length(btrim(derived_rule_code)) > 0) AND (derived_rule_code = btrim(derived_rule_code)) AND (kind = 'earning'::text) AND (hours IS NULL)))),
    CONSTRAINT pay_stub_lines_earning_dates_pair CHECK ((((earned_from IS NULL) AND (earned_to IS NULL)) OR ((earned_from IS NOT NULL) AND (earned_to IS NOT NULL) AND (earned_from <= earned_to)))),
    CONSTRAINT pay_stub_lines_expense_account_evidence CHECK ((((expense_account_source = 'unknown'::text) AND (expense_account_id IS NULL) AND (expense_account_evidence IS NULL)) OR ((expense_account_source = ANY (ARRAY['item'::text, 'component'::text, 'department'::text, 'org_default'::text, 'entitlement_plan'::text])) AND (expense_account_id IS NOT NULL) AND (expense_account_evidence IS NOT NULL) AND (jsonb_typeof(expense_account_evidence) = 'object'::text)))),
    CONSTRAINT pay_stub_lines_kind CHECK ((kind = ANY (ARRAY['earning'::text, 'deduction'::text, 'employer_contribution'::text, 'credit'::text]))),
    CONSTRAINT pay_stub_lines_liability_account_evidence CHECK ((((liability_account_source = 'unknown'::text) AND (liability_account_id IS NULL) AND (liability_account_evidence IS NULL)) OR ((liability_account_source = ANY (ARRAY['commit'::text, 'legacy_component'::text])) AND (liability_account_id IS NOT NULL) AND (liability_account_evidence IS NULL)) OR ((liability_account_source = 'reconciled'::text) AND (liability_account_id IS NOT NULL) AND (liability_account_evidence IS NOT NULL) AND (jsonb_typeof(liability_account_evidence) = 'object'::text) AND COALESCE((jsonb_typeof((liability_account_evidence -> 'reason'::text)) = 'string'::text), false) AND COALESCE((jsonb_typeof((liability_account_evidence -> 'reference'::text)) = 'string'::text), false) AND (length(TRIM(BOTH FROM (liability_account_evidence ->> 'reason'::text))) > 0) AND (length(TRIM(BOTH FROM (liability_account_evidence ->> 'reference'::text))) > 0)))),
    CONSTRAINT pay_stub_lines_non_cash_shape CHECK ((((payment_kind = 'cash'::text) AND (non_cash_account_id IS NULL)) OR ((payment_kind = 'non_cash'::text) AND (kind = 'earning'::text) AND (non_cash_account_id IS NOT NULL)))),
    CONSTRAINT pay_stub_lines_payment_kind CHECK ((payment_kind = ANY (ARRAY['cash'::text, 'non_cash'::text]))),
    CONSTRAINT pay_stub_lines_statutory_reporting_code_shape CHECK (((statutory_reporting_code IS NULL) OR ((jsonb_typeof(statutory_reporting_code) = 'object'::text) AND (statutory_reporting_code ?& ARRAY['formCode'::text, 'boxCode'::text, 'code'::text, 'label'::text]) AND (jsonb_typeof((statutory_reporting_code -> 'formCode'::text)) = 'string'::text) AND (jsonb_typeof((statutory_reporting_code -> 'boxCode'::text)) = 'string'::text) AND (jsonb_typeof((statutory_reporting_code -> 'code'::text)) = 'string'::text) AND (jsonb_typeof((statutory_reporting_code -> 'label'::text)) = 'string'::text))))
);

ALTER TABLE ONLY public.pay_stub_lines FORCE ROW LEVEL SECURITY;


--
-- Name: COLUMN pay_stub_lines.liability_account_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pay_stub_lines.liability_account_id IS 'Liability account this deduction/employer contribution was credited to at commit. Remittances debit this account, never the component''s current setup.';


--
-- Name: COLUMN pay_stub_lines.liability_account_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pay_stub_lines.liability_account_source IS 'commit = stamped by the committing engine; legacy_component = backfilled from the component''s account for a line committed before the engine stamped one; unknown = such a line whose component named no account (resolves through the pack''s legacy slot).';


--
-- Name: COLUMN pay_stub_lines.liability_account_evidence; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pay_stub_lines.liability_account_evidence IS 'Original posting evidence reference and reason for a one-time audited resolution of an unknown historical liability account.';


--
-- Name: COLUMN pay_stub_lines.item_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pay_stub_lines.item_id IS 'Service item the hours on this line were worked on, carried from the time entry like project_id/time_type_id. Null for lines with no operational item (salary, bonus, per diem).';


--
-- Name: COLUMN pay_stub_lines.expense_account_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pay_stub_lines.expense_account_id IS 'Expense account this earning line was costed to at calculate. Posting debits this account, never the component''s or item''s current setup.';


--
-- Name: COLUMN pay_stub_lines.expense_account_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pay_stub_lines.expense_account_source IS 'item = the line''s item declared an account; department = the component''s department mapping for the line''s department answered; component = fell through to the pay component''s expense account; org_default = fell through to the org wage/burden default; entitlement_plan = the line settles an entitlement bank and posts to the plan''s liability account; unknown = unstamped history resolving live as before.';


--
-- Name: COLUMN pay_stub_lines.remittance_party_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pay_stub_lines.remittance_party_id IS 'Remittance destination this deduction/employer contribution/credit accrued to at commit. Remittances route by this, never the component''s current vendor.';


--
-- Name: COLUMN pay_stub_lines.statutory_reporting_code; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pay_stub_lines.statutory_reporting_code IS 'Tax form reporting code resolved by the country pack at payroll calculation; immutable stub history must not follow later component setup edits.';


--
-- Name: CONSTRAINT pay_stub_lines_kind ON pay_stub_lines; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT pay_stub_lines_kind ON public.pay_stub_lines IS 'Stub line kinds: mirrors pay_components_kind so every seedable component kind is payable.';


--
-- Name: pay_stub_lines; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.pay_stub_lines WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    stub_id,
    component_id,
    kind,
    description,
    hours,
    rate,
    amount,
    project_id,
    department_id,
    time_type_id,
    sequence,
    created_at,
    created_by,
    updated_at,
    updated_by,
    liability_account_id,
    liability_account_source,
    liability_account_evidence,
    item_id,
    expense_account_id,
    expense_account_source,
    expense_account_evidence,
    remittance_party_id,
    earned_from,
    earned_to,
    statutory_reporting_code,
    payment_kind,
    non_cash_account_id,
    derived_quantity,
    derived_rule_code
   FROM public.pay_stub_lines
  WHERE (org_id = public.openbooks_query_org_id());


--
-- Name: pay_stubs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.pay_stubs (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    pay_run_document_id uuid NOT NULL,
    employee_party_id uuid NOT NULL,
    province text NOT NULL,
    periods_per_year integer NOT NULL,
    pay_date date NOT NULL,
    tax_year integer NOT NULL,
    federal_claim numeric(19,4) DEFAULT 0 NOT NULL,
    provincial_claim numeric(19,4) DEFAULT 0 NOT NULL,
    currency_code text NOT NULL,
    gross numeric(19,4) DEFAULT 0 NOT NULL,
    pensionable_earnings numeric(19,4) DEFAULT 0 NOT NULL,
    insurable_earnings numeric(19,4) DEFAULT 0 NOT NULL,
    net_pay numeric(19,4) DEFAULT 0 NOT NULL,
    employer_cost numeric(19,4) DEFAULT 0 NOT NULL,
    vacation_accrued numeric(19,4) DEFAULT 0 NOT NULL,
    factors jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    payment_method text,
    cheque_number text,
    country text,
    country_source text DEFAULT 'unknown'::text NOT NULL,
    filing_account_id uuid,
    filing_account_source text DEFAULT 'unknown'::text NOT NULL,
    filing_account_evidence jsonb,
    employment_id uuid NOT NULL,
    CONSTRAINT pay_stubs_cheque_number_method CHECK (((cheque_number IS NULL) OR (payment_method = 'cheque'::text))),
    CONSTRAINT pay_stubs_country_evidence CHECK ((((country IS NULL) AND (country_source = 'unknown'::text)) OR ((country IS NOT NULL) AND (country ~ '^[A-Z]{2}$'::text) AND (country_source = ANY (ARRAY['calculation'::text, 'legacy_region'::text]))))),
    CONSTRAINT pay_stubs_filing_account_evidence CHECK ((((filing_account_source = 'unknown'::text) AND (filing_account_id IS NULL) AND (filing_account_evidence IS NULL)) OR ((filing_account_source = ANY (ARRAY['calculation'::text, 'insertion'::text])) AND (filing_account_evidence IS NULL)) OR ((filing_account_source = 'reconciled'::text) AND (filing_account_evidence IS NOT NULL) AND (jsonb_typeof(filing_account_evidence) = 'object'::text) AND COALESCE((jsonb_typeof((filing_account_evidence -> 'reason'::text)) = 'string'::text), false) AND COALESCE((jsonb_typeof((filing_account_evidence -> 'reference'::text)) = 'string'::text), false) AND (length(TRIM(BOTH FROM (filing_account_evidence ->> 'reason'::text))) > 0) AND (length(TRIM(BOTH FROM (filing_account_evidence ->> 'reference'::text))) > 0)))),
    CONSTRAINT pay_stubs_net_nonnegative CHECK ((net_pay >= (0)::numeric)),
    CONSTRAINT pay_stubs_payment_method CHECK (((payment_method IS NULL) OR (payment_method = ANY (ARRAY['eft'::text, 'cheque'::text]))))
);

ALTER TABLE ONLY public.pay_stubs FORCE ROW LEVEL SECURITY;


--
-- Name: COLUMN pay_stubs.country; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pay_stubs.country IS 'Country of the statutory pack that calculated this stub; independent of the current employee profile.';


--
-- Name: COLUMN pay_stubs.country_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pay_stubs.country_source IS 'calculation = captured directly; legacy_region = derived from the existing disjoint province/state snapshot; unknown = requires review before year-end reporting.';


--
-- Name: COLUMN pay_stubs.filing_account_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pay_stubs.filing_account_id IS 'Filing identity captured for this payroll. A captured null is explicitly unassigned; never resolve it from a later profile/default.';


--
-- Name: COLUMN pay_stubs.filing_account_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pay_stubs.filing_account_source IS 'calculation = new engine; insertion = rolling old writer; unknown = legacy evidence required; reconciled = original evidence recorded with actor and immutable audit.';


--
-- Name: COLUMN pay_stubs.filing_account_evidence; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pay_stubs.filing_account_evidence IS 'Original payroll evidence reference and reconciliation reason; required only for a one-time resolution of unknown legacy attribution.';


--
-- Name: pay_stubs; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.pay_stubs WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    pay_run_document_id,
    employee_party_id,
    province,
    periods_per_year,
    pay_date,
    tax_year,
    federal_claim,
    provincial_claim,
    currency_code,
    gross,
    pensionable_earnings,
    insurable_earnings,
    net_pay,
    employer_cost,
    vacation_accrued,
    factors,
    created_at,
    created_by,
    updated_at,
    updated_by,
    payment_method,
    cheque_number,
    country,
    country_source,
    filing_account_id,
    filing_account_source,
    filing_account_evidence,
    employment_id
   FROM public.pay_stubs
  WHERE (org_id = public.openbooks_query_org_id());


--
-- Name: payment_disputes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payment_disputes (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    provider text NOT NULL,
    provider_event_id text NOT NULL,
    kind text NOT NULL,
    status text NOT NULL,
    attempt_id uuid,
    receipt_document_id uuid,
    invoice_document_id uuid,
    currency text NOT NULL,
    amount numeric(19,4) NOT NULL,
    fee_amount numeric(19,4) DEFAULT 0 NOT NULL,
    provider_ref text,
    reason text,
    status_history jsonb DEFAULT '[]'::jsonb NOT NULL,
    documents_posted jsonb DEFAULT '[]'::jsonb NOT NULL,
    reviewed_by uuid,
    reviewed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT payment_disputes_amount_nonnegative CHECK ((amount >= (0)::numeric)),
    CONSTRAINT payment_disputes_event_nonblank CHECK ((length(btrim(provider_event_id)) > 0)),
    CONSTRAINT payment_disputes_fee_nonnegative CHECK ((fee_amount >= (0)::numeric)),
    CONSTRAINT payment_disputes_kind_chk CHECK ((kind = ANY (ARRAY['refund'::text, 'dispute'::text]))),
