    org_id uuid NOT NULL,
    run_number text NOT NULL,
    bank_account_id uuid NOT NULL,
    method text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    scheduled_for date,
    exported_file_ref text,
    exported_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    payment_bank_profile_id uuid,
    subsidiary_id uuid,
    source_schedule_id uuid,
    parent_payment_run_id uuid,
    direction text DEFAULT 'outbound'::text NOT NULL,
    purpose text DEFAULT 'vendor_payments'::text NOT NULL,
    currency text,
    selection_criteria jsonb DEFAULT '{}'::jsonb NOT NULL,
    payment_count integer DEFAULT 0 NOT NULL,
    total_amount numeric(19,4) DEFAULT '0'::numeric NOT NULL,
    submitted_at timestamp with time zone,
    submitted_by uuid,
    approved_at timestamp with time zone,
    approved_by uuid,
    rejected_at timestamp with time zone,
    rejected_by uuid,
    rejection_reason text,
    settled_at timestamp with time zone,
    posting_claim_token uuid,
    posting_claimed_at timestamp with time zone,
    posting_claimed_by uuid,
    file_created_at timestamp with time zone,
    file_id_modifier text,
    CONSTRAINT payment_runs_file_id_modifier_shape CHECK (((file_id_modifier IS NULL) OR (file_id_modifier ~ '^[A-Z0-9]$'::text)))
);

ALTER TABLE ONLY public.payment_runs FORCE ROW LEVEL SECURITY;


--
-- Name: COLUMN payment_runs.posting_claim_token; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payment_runs.posting_claim_token IS 'Random per-claim posting lease; instruction and completion writes must match the token currently stored on the run.';


--
-- Name: COLUMN payment_runs.posting_claimed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payment_runs.posting_claimed_at IS 'When the current posting claim was taken or last made progress; a claim older than the staleness window may be recovered by a new poster.';


--
-- Name: COLUMN payment_runs.posting_claimed_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payment_runs.posting_claimed_by IS 'User that took the current posting claim.';


--
-- Name: COLUMN payment_runs.file_created_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payment_runs.file_created_at IS 'Instant the run''s first bank file was created. Stamped once via coalesce on first generation and reused by every later render, so re-downloads reproduce byte-identical files and the bank''s duplicate-file detection still recognizes an accidental re-upload of the same run.';


--
-- Name: COLUMN payment_runs.file_id_modifier; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payment_runs.file_id_modifier IS 'NACHA File ID Modifier (single character A-Z, 0-9) allocated for this run''s bank file. Pinned once per bank profile per creation day (lowest free letter) so two files generated the same day never share the bank''s same-day duplicate-file identity; null means allocated before this migration and readers fall back to the legacy run-number derivation.';


--
-- Name: payment_runs; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.payment_runs WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    run_number,
    bank_account_id,
    method,
    status,
    scheduled_for,
    exported_file_ref,
    exported_at,
    created_at,
    created_by,
    updated_at,
    updated_by,
    payment_bank_profile_id,
    subsidiary_id,
    source_schedule_id,
    parent_payment_run_id,
    direction,
    purpose,
    currency,
    selection_criteria,
    payment_count,
    total_amount,
    submitted_at,
    submitted_by,
    approved_at,
    approved_by,
    rejected_at,
    rejected_by,
    rejection_reason,
    settled_at,
    posting_claim_token,
    posting_claimed_at,
    posting_claimed_by,
    file_created_at,
    file_id_modifier
   FROM public.payment_runs
  WHERE (org_id = public.openbooks_query_org_id());


