    name,
    rule_kind,
    rule_month,
    rule_day,
    rule_weekday,
    rule_nth,
    rule_offset,
    observed_on,
    observance,
    is_observed,
    is_paid,
    effective_from,
    effective_to,
    created_at,
    created_by,
    updated_at,
    updated_by
   FROM public.payroll_holidays
  WHERE (org_id = public.openbooks_query_org_id());


