    CONSTRAINT payroll_opening_balances_ca_avg_income_check CHECK ((ca_avg_income >= (0)::numeric)),
    CONSTRAINT payroll_opening_balances_ca_avg_pe_check CHECK ((ca_avg_pe >= (0)::numeric)),
    CONSTRAINT payroll_opening_balances_ca_avg_pension_f_check CHECK ((ca_avg_pension_f >= (0)::numeric)),
