--
-- Name: payroll_statutory_rates; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payroll_statutory_rates (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    country text NOT NULL,
    rate_key text NOT NULL,
    region text,
    filing_account_id uuid,
    tax_year integer NOT NULL,
    rate_values jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    sub_region text,
    superseded_on date,
    source_citation text,
    reason text,
    CONSTRAINT payroll_statutory_rates_account_region CHECK (((filing_account_id IS NULL) OR (region IS NOT NULL))),
    CONSTRAINT payroll_statutory_rates_reason_nonblank CHECK (((reason IS NULL) OR (btrim(reason) <> ''::text))),
    CONSTRAINT payroll_statutory_rates_source_citation_nonblank CHECK (((source_citation IS NULL) OR (btrim(source_citation) <> ''::text))),
    CONSTRAINT payroll_statutory_rates_sub_region CHECK (((sub_region IS NULL) OR (region IS NOT NULL))),
    CONSTRAINT payroll_statutory_rates_values CHECK ((jsonb_typeof(rate_values) = 'object'::text)),
    CONSTRAINT payroll_statutory_rates_year CHECK (((tax_year >= 2000) AND (tax_year <= 2100)))
);

ALTER TABLE ONLY public.payroll_statutory_rates FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE payroll_statutory_rates; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.payroll_statutory_rates IS 'Tenant half of a country pack''s statutory rates: the ones no publication can supply (experience-rated SUI per filing account), or that are published per region per year (the FUTA credit reduction, provincial employer health levies). Scope columns carry the pack-declared scope; tax_year is the effective dimension, so re-running a prior period reproduces that period''s rate. Published constants live in the pack''s edition modules and are never stored here.';


--
-- Name: COLUMN payroll_statutory_rates.sub_region; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payroll_statutory_rates.sub_region IS 'The taxing unit below the region, for pack slots declared at `sub_region` scope (a PA Act 32 PSD code, an Ohio municipality). Null for every other scope.';


--
-- Name: COLUMN payroll_statutory_rates.superseded_on; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payroll_statutory_rates.superseded_on IS 'The date this row stopped being the current rate for its scope point (org, country, rate key, tax year, region, sub-region, filing account). Null while the row is current. A re-save stamps the open row and inserts its successor in one transaction; a remove stamps it with no successor. Prior-period reads resolve the row in force on the pay date, so history is never rewritten (see migration 0183).';


--
-- Name: COLUMN payroll_statutory_rates.source_citation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payroll_statutory_rates.source_citation IS 'The published source the entered figures were taken from (for example the ESD premium announcement for the year). Null for rows recorded before this change; required by the write boundary on every new or changed row.';


--
-- Name: COLUMN payroll_statutory_rates.reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payroll_statutory_rates.reason IS 'Why the row was entered or changed, in the operator''s own words. Null for rows recorded before this change; required by the write boundary on every new or changed row.';


--
-- Name: payroll_statutory_rates; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.payroll_statutory_rates WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    country,
    rate_key,
    region,
    filing_account_id,
    tax_year,
    rate_values,
    created_at,
    created_by,
    updated_at,
    updated_by,
    sub_region,
    superseded_on,
    source_citation,
    reason
   FROM public.payroll_statutory_rates
  WHERE (org_id = public.openbooks_query_org_id());


--
-- Name: performance_obligations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.performance_obligations (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    contract_id uuid NOT NULL,
    document_line_id uuid,
    item_id uuid,
    description text NOT NULL,
    recognition_rule_id uuid NOT NULL,
    booked_amount numeric(19,4),
    standalone_selling_price numeric(19,4),
    allocated_price numeric(19,4) NOT NULL,
    percent_complete numeric(19,4),
    recognition_starts_on date,
    recognition_ends_on date,
    deferred_account_id uuid,
    recognized_account_id uuid,
    status text DEFAULT 'open'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    fair_value_flag text,
    fair_value_low numeric(19,4),
    fair_value_high numeric(19,4),
    cancellation_reason text,
    cancelled_at timestamp with time zone,
    cancelled_by uuid,
    idempotency_key text,
    last_change_id uuid,
    legacy_reconciled_at timestamp with time zone,
    legacy_reconciled_by uuid,
    legacy_reconciliation_reason text,
    recognition_held boolean DEFAULT false NOT NULL,
    hold_reason text,
    control_revision integer DEFAULT 1 NOT NULL,
    delivered_on date,
    delivery_bundle_document_id uuid,
    allocation_basis jsonb,
    CONSTRAINT obligation_hold_reason_check CHECK (((NOT recognition_held) OR (length(btrim(hold_reason)) >= 8))),
    CONSTRAINT obligations_status_check CHECK ((status = ANY (ARRAY['open'::text, 'satisfied'::text, 'cancelled'::text]))),
    CONSTRAINT performance_obligation_cancellation_shape CHECK ((((status = 'cancelled'::text) AND (cancellation_reason IS NOT NULL) AND ((length(btrim(cancellation_reason)) >= 5) AND (length(btrim(cancellation_reason)) <= 500)) AND (cancelled_at IS NOT NULL) AND (cancelled_by IS NOT NULL)) OR ((status <> 'cancelled'::text) AND (cancellation_reason IS NULL) AND (cancelled_at IS NULL) AND (cancelled_by IS NULL)))),
    CONSTRAINT performance_obligations_idempotency_key CHECK (((idempotency_key IS NULL) OR ((length(btrim(idempotency_key)) >= 1) AND (length(btrim(idempotency_key)) <= 500)))),
    CONSTRAINT performance_obligations_legacy_reconciliation_shape CHECK ((((legacy_reconciled_at IS NULL) AND (legacy_reconciled_by IS NULL) AND (legacy_reconciliation_reason IS NULL)) OR ((legacy_reconciled_at IS NOT NULL) AND (legacy_reconciled_by IS NOT NULL) AND (legacy_reconciliation_reason IS NOT NULL) AND ((char_length(btrim(legacy_reconciliation_reason)) >= 5) AND (char_length(btrim(legacy_reconciliation_reason)) <= 500)))))
);

ALTER TABLE ONLY public.performance_obligations FORCE ROW LEVEL SECURITY;


--
-- Name: COLUMN performance_obligations.idempotency_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.performance_obligations.idempotency_key IS 'Stable source-effect key; unique per organization when present.';


--
-- Name: COLUMN performance_obligations.legacy_reconciled_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.performance_obligations.legacy_reconciled_at IS 'When the operator attested this obligation''s existing schedule against the policy actually in force at its creation, lifting the legacy-rebuild refusal. NULL until reconciled.';


--
-- Name: COLUMN performance_obligations.legacy_reconciled_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.performance_obligations.legacy_reconciled_by IS 'Actor who recorded the legacy reconciliation.';


--
-- Name: COLUMN performance_obligations.legacy_reconciliation_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.performance_obligations.legacy_reconciliation_reason IS 'Why the operator trusts the existing schedule (e.g. the signed policy memo it was verified against). Required when reconciled.';


