--
-- Name: period_end_journal_entries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.period_end_journal_entries (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    set_id uuid NOT NULL,
    kind text NOT NULL,
    entry_id uuid NOT NULL,
    reversal_entry_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT period_end_journal_entries_kind CHECK ((kind = ANY (ARRAY['income_statement'::text, 'income_summary'::text, 'balance_sheet'::text, 'opening'::text]))),
    CONSTRAINT period_end_journal_entries_reversal_distinct CHECK ((reversal_entry_id IS DISTINCT FROM entry_id))
);

ALTER TABLE ONLY public.period_end_journal_entries FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE period_end_journal_entries; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.period_end_journal_entries IS 'The journal entries of a period-end journal generation by kind, each linked to its reversal once reversed.';


--
-- Name: period_end_journal_entries; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.period_end_journal_entries WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    set_id,
    kind,
    entry_id,
    reversal_entry_id,
    created_at
   FROM public.period_end_journal_entries
  WHERE (org_id = public.openbooks_query_org_id());


--
-- Name: period_end_journal_policies; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.period_end_journal_policies (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    effective_from date NOT NULL,
    closing_method text NOT NULL,
    retained_earnings_account_id uuid NOT NULL,
    income_summary_account_id uuid,
    balance_sheet_journals boolean DEFAULT false NOT NULL,
    posting_period text DEFAULT 'last_period'::text NOT NULL,
    preserve_departments boolean DEFAULT false NOT NULL,
    preserve_classes boolean DEFAULT false NOT NULL,
    preserve_locations boolean DEFAULT false NOT NULL,
    preserve_projects boolean DEFAULT false NOT NULL,
    preserve_segments boolean DEFAULT false NOT NULL,
    reason text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT period_end_journal_policies_closing_method CHECK ((closing_method = ANY (ARRAY['retained_earnings'::text, 'income_summary'::text]))),
    CONSTRAINT period_end_journal_policies_distinct_accounts CHECK ((income_summary_account_id IS DISTINCT FROM retained_earnings_account_id)),
    CONSTRAINT period_end_journal_policies_income_summary CHECK (((closing_method = 'income_summary'::text) = (income_summary_account_id IS NOT NULL))),
    CONSTRAINT period_end_journal_policies_posting_period CHECK ((posting_period = ANY (ARRAY['last_period'::text, 'adjustment_period'::text]))),
    CONSTRAINT period_end_journal_policies_reason CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 2000)))
);

ALTER TABLE ONLY public.period_end_journal_policies FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE period_end_journal_policies; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.period_end_journal_policies IS 'Effective-dated period-end journal policy. The row with the latest effective_from on or before a fiscal year end governs the journals generated for that year; versions are append-only.';


--
-- Name: period_end_journal_policies; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.period_end_journal_policies WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    effective_from,
    closing_method,
    retained_earnings_account_id,
    income_summary_account_id,
    balance_sheet_journals,
    posting_period,
    preserve_departments,
    preserve_classes,
    preserve_locations,
    preserve_projects,
    preserve_segments,
    reason,
    created_at,
    created_by,
    updated_at,
    updated_by
   FROM public.period_end_journal_policies
  WHERE (org_id = public.openbooks_query_org_id());


--
-- Name: period_end_journal_sets; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.period_end_journal_sets (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    book_id uuid NOT NULL,
    subsidiary_id uuid NOT NULL,
    fiscal_calendar_id uuid NOT NULL,
    fiscal_year integer NOT NULL,
    year_starts_on date NOT NULL,
    year_ends_on date NOT NULL,
    closing_period_id uuid NOT NULL,
    opening_period_id uuid,
    generation integer NOT NULL,
    policy_id uuid NOT NULL,
    policy_snapshot jsonb NOT NULL,
    content_hash text NOT NULL,
    currency text NOT NULL,
    fiscal_year_earnings numeric(19,4) NOT NULL,
    prior_unclosed_earnings numeric(19,4) NOT NULL,
    status text DEFAULT 'posted'::text NOT NULL,
    reason text NOT NULL,
    generated_at timestamp with time zone DEFAULT now() NOT NULL,
    generated_by uuid,
    reversed_at timestamp with time zone,
    reversed_by uuid,
    reversal_reason text,
    reopen_request_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT period_end_journal_sets_content_hash CHECK ((content_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT period_end_journal_sets_generation CHECK ((generation >= 1)),
    CONSTRAINT period_end_journal_sets_reason CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 2000))),
    CONSTRAINT period_end_journal_sets_reversal CHECK ((((status = 'posted'::text) AND (reversed_at IS NULL) AND (reversed_by IS NULL) AND (reversal_reason IS NULL) AND (reopen_request_id IS NULL)) OR ((status = 'reversed'::text) AND (reversed_at IS NOT NULL) AND ((length(btrim(COALESCE(reversal_reason, ''::text))) >= 1) AND (length(btrim(COALESCE(reversal_reason, ''::text))) <= 2000))))),
    CONSTRAINT period_end_journal_sets_snapshot CHECK ((jsonb_typeof(policy_snapshot) = 'object'::text)),
    CONSTRAINT period_end_journal_sets_status CHECK ((status = ANY (ARRAY['posted'::text, 'reversed'::text]))),
    CONSTRAINT period_end_journal_sets_year CHECK ((year_starts_on <= year_ends_on))
);

ALTER TABLE ONLY public.period_end_journal_sets FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE period_end_journal_sets; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.period_end_journal_sets IS 'One generation of a fiscal year''s period-end journals for one accounting book and legal entity. Posted generations seal the ledger through year_ends_on; a generation only moves to reversed, never deleted.';


--
-- Name: period_end_journal_sets; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.period_end_journal_sets WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    book_id,
    subsidiary_id,
    fiscal_calendar_id,
    fiscal_year,
    year_starts_on,
    year_ends_on,
    closing_period_id,
    opening_period_id,
    generation,
    policy_id,
    policy_snapshot,
    content_hash,
    currency,
    fiscal_year_earnings,
    prior_unclosed_earnings,
    status,
    reason,
    generated_at,
    generated_by,
    reversed_at,
    reversed_by,
    reversal_reason,
    reopen_request_id,
    created_at,
    created_by,
    updated_at,
    updated_by
   FROM public.period_end_journal_sets
  WHERE (org_id = public.openbooks_query_org_id());


