--
-- Name: pledges; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.pledges (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    subsidiary_id uuid NOT NULL,
    pledge_number text NOT NULL,
    donor_party_id uuid NOT NULL,
    fund_id uuid NOT NULL,
    total_amount numeric(19,4) NOT NULL,
    discount_rate numeric(19,10) DEFAULT 0 NOT NULL,
    present_value numeric(19,4),
    allowance_amount numeric(19,4) DEFAULT 0 NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    booked_on date,
    booking_entry_id uuid,
    custom jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT pledges_amounts_check CHECK (((total_amount > (0)::numeric) AND (discount_rate >= (0)::numeric) AND (allowance_amount >= (0)::numeric) AND (allowance_amount <= total_amount) AND ((present_value IS NULL) OR ((present_value > (0)::numeric) AND (present_value <= total_amount))))),
    CONSTRAINT pledges_booking_state_check CHECK ((((status = 'draft'::text) AND (booked_on IS NULL) AND (booking_entry_id IS NULL) AND (present_value IS NULL)) OR ((status <> 'draft'::text) AND (booked_on IS NOT NULL) AND (booking_entry_id IS NOT NULL) AND (present_value IS NOT NULL)))),
    CONSTRAINT pledges_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'booked'::text, 'collecting'::text, 'fulfilled'::text, 'written_off'::text, 'cancelled'::text])))
);

ALTER TABLE ONLY public.pledges FORCE ROW LEVEL SECURITY;


