CREATE TABLE public.pos_sessions (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    register_id uuid NOT NULL,
    subsidiary_id uuid NOT NULL,
    session_number integer NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    business_date date NOT NULL,
    currency text NOT NULL,
    opening_float_minor bigint NOT NULL,
    opening_count jsonb DEFAULT '[]'::jsonb NOT NULL,
    opened_at timestamp with time zone DEFAULT now() NOT NULL,
    opened_by uuid NOT NULL,
    closed_at timestamp with time zone,
    closed_by uuid,
    expected_cash_minor bigint,
    counted_cash_minor bigint,
    over_short_minor bigint,
    closing_count jsonb,
    over_short_entry_id uuid,
    close_note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT pos_sessions_close_note_check CHECK (((close_note IS NULL) OR (char_length(close_note) <= 1000))),
    CONSTRAINT pos_sessions_closing_count_check CHECK (((closing_count IS NULL) OR (jsonb_typeof(closing_count) = 'array'::text))),
    CONSTRAINT pos_sessions_counted_cash_minor_check CHECK (((counted_cash_minor IS NULL) OR (counted_cash_minor >= 0))),
    CONSTRAINT pos_sessions_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT pos_sessions_lifecycle CHECK ((((status = 'open'::text) AND (closed_at IS NULL) AND (closed_by IS NULL) AND (expected_cash_minor IS NULL) AND (counted_cash_minor IS NULL) AND (over_short_minor IS NULL) AND (closing_count IS NULL) AND (over_short_entry_id IS NULL)) OR ((status = 'closed'::text) AND (closed_at IS NOT NULL) AND (closed_by IS NOT NULL) AND (expected_cash_minor IS NOT NULL) AND (counted_cash_minor IS NOT NULL) AND (over_short_minor IS NOT NULL) AND (closing_count IS NOT NULL) AND (over_short_minor = (counted_cash_minor - expected_cash_minor)) AND ((over_short_minor = 0) = (over_short_entry_id IS NULL))))),
    CONSTRAINT pos_sessions_opening_count_check CHECK ((jsonb_typeof(opening_count) = 'array'::text)),
    CONSTRAINT pos_sessions_opening_float_minor_check CHECK ((opening_float_minor >= 0)),
    CONSTRAINT pos_sessions_session_number_check CHECK ((session_number > 0)),
    CONSTRAINT pos_sessions_status_check CHECK ((status = ANY (ARRAY['open'::text, 'closed'::text])))
);

ALTER TABLE ONLY public.pos_sessions FORCE ROW LEVEL SECURITY;


--
-- Name: pos_sessions; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.pos_sessions WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    register_id,
    subsidiary_id,
    session_number,
    status,
    business_date,
    currency,
    opening_float_minor,
    opening_count,
    opened_at,
    opened_by,
    closed_at,
    closed_by,
    expected_cash_minor,
    counted_cash_minor,
    over_short_minor,
    closing_count,
    over_short_entry_id,
    close_note,
    created_at,
    created_by,
    updated_at,
    updated_by
   FROM public.pos_sessions
  WHERE (org_id = public.openbooks_query_org_id());


--
-- Name: pos_transactions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.pos_transactions (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    session_id uuid NOT NULL,
    register_id uuid NOT NULL,
    kind text NOT NULL,
    document_id uuid NOT NULL,
    refund_of_document_id uuid,
    total_minor bigint NOT NULL,
    cash_applied_minor bigint DEFAULT 0 NOT NULL,
    cash_tendered_minor bigint DEFAULT 0 NOT NULL,
    change_minor bigint DEFAULT 0 NOT NULL,
    pricing jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    CONSTRAINT pos_transactions_cash_applied_minor_check CHECK ((cash_applied_minor >= 0)),
    CONSTRAINT pos_transactions_cash_change CHECK (((change_minor = (cash_tendered_minor - cash_applied_minor)) AND ((kind = 'sale'::text) OR ((cash_tendered_minor = 0) AND (change_minor = 0))))),
    CONSTRAINT pos_transactions_cash_tendered_minor_check CHECK ((cash_tendered_minor >= 0)),
    CONSTRAINT pos_transactions_change_minor_check CHECK ((change_minor >= 0)),
    CONSTRAINT pos_transactions_kind_check CHECK ((kind = ANY (ARRAY['sale'::text, 'refund'::text]))),
    CONSTRAINT pos_transactions_pricing_check CHECK ((jsonb_typeof(pricing) = 'object'::text)),
    CONSTRAINT pos_transactions_refund_link CHECK (((kind = 'refund'::text) = (refund_of_document_id IS NOT NULL))),
    CONSTRAINT pos_transactions_total_minor_check CHECK ((total_minor >= 0))
);

ALTER TABLE ONLY public.pos_transactions FORCE ROW LEVEL SECURITY;


--
-- Name: pos_transactions; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.pos_transactions WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    session_id,
    register_id,
    kind,
    document_id,
    refund_of_document_id,
    total_minor,
    cash_applied_minor,
    cash_tendered_minor,
    change_minor,
    pricing,
    created_at,
    created_by
   FROM public.pos_transactions
  WHERE (org_id = public.openbooks_query_org_id());


