    CONSTRAINT prebill_holds_reason_chk CHECK ((length(btrim(reason)) > 0)),
    CONSTRAINT prebill_holds_release_chk CHECK ((((released_at IS NULL) AND (released_by IS NULL) AND (release_reason IS NULL)) OR ((released_at IS NOT NULL) AND (released_by IS NOT NULL) AND (NULLIF(btrim(release_reason), ''::text) IS NOT NULL)))),
    CONSTRAINT prebill_holds_source_type_chk CHECK ((source_type = ANY (ARRAY['time_entry'::text, 'document_line'::text])))
);

