    line_number integer NOT NULL,
    source_type text NOT NULL,
    time_entry_id uuid,
    document_line_id uuid,
    source_document_id uuid,
    source_date date NOT NULL,
    description text,
    quantity numeric(19,4) DEFAULT 1 NOT NULL,
    unit text,
    item_id uuid,
    income_account_id uuid,
    tax_code_id uuid,
    employee_party_id uuid,
    time_type_id uuid,
    department_id uuid,
    cost_amount numeric(19,4) DEFAULT 0 NOT NULL,
    original_bill_amount numeric(19,4) DEFAULT 0 NOT NULL,
    proposed_bill_amount numeric(19,4) DEFAULT 0 NOT NULL,
    adjustment_amount numeric(19,4) DEFAULT 0 NOT NULL,
    adjustment_reason text,
    adjustment_evidence jsonb DEFAULT '[]'::jsonb NOT NULL,
    disposition text DEFAULT 'bill'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    pricing_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    revision_seq bigint DEFAULT 0 NOT NULL,
    customer_dispute_note text,
    CONSTRAINT prebill_lines_adjustment_support_chk CHECK (((adjustment_amount = (0)::numeric) OR ((NULLIF(btrim(adjustment_reason), ''::text) IS NOT NULL) AND (jsonb_array_length(adjustment_evidence) > 0)))),
    CONSTRAINT prebill_lines_amounts_chk CHECK (((quantity > (0)::numeric) AND (cost_amount >= (0)::numeric) AND (original_bill_amount >= (0)::numeric) AND (proposed_bill_amount >= (0)::numeric) AND (adjustment_amount = (proposed_bill_amount - original_bill_amount)))),
    CONSTRAINT prebill_lines_disposition_chk CHECK ((disposition = ANY (ARRAY['bill'::text, 'hold'::text]))),
    CONSTRAINT prebill_lines_evidence_array_chk CHECK ((jsonb_typeof(adjustment_evidence) = 'array'::text)),
    CONSTRAINT prebill_lines_source_shape_chk CHECK ((((source_type = 'time_entry'::text) AND (time_entry_id IS NOT NULL) AND (document_line_id IS NULL)) OR ((source_type = 'document_line'::text) AND (document_line_id IS NOT NULL) AND (time_entry_id IS NULL)))),
    CONSTRAINT prebill_lines_source_type_chk CHECK ((source_type = ANY (ARRAY['time_entry'::text, 'document_line'::text])))
);

