--
-- Name: prebills; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.prebills (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    project_id uuid NOT NULL,
    worksheet_number text NOT NULL,
    period_start date,
    period_end date NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    notes text,
    original_bill_amount numeric(19,4) DEFAULT 0 NOT NULL,
    proposed_bill_amount numeric(19,4) DEFAULT 0 NOT NULL,
    cost_amount numeric(19,4) DEFAULT 0 NOT NULL,
    adjustment_amount numeric(19,4) DEFAULT 0 NOT NULL,
    billing_request_id uuid,
    invoice_document_id uuid,
    submitted_at timestamp with time zone,
    submitted_by uuid,
    approved_at timestamp with time zone,
    approved_by uuid,
    converted_at timestamp with time zone,
    converted_by uuid,
    voided_at timestamp with time zone,
    voided_by uuid,
    void_reason text,
    custom jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    customer_review_sent_at timestamp with time zone,
    customer_review_sent_by uuid,
    customer_review_digest text,
    customer_decision text,
    customer_decided_at timestamp with time zone,
    customer_signer_name text,
    customer_decision_note text,
    customer_po_number text,
    customer_viewed_at timestamp with time zone,
    delivered_at timestamp with time zone,
    delivered_by uuid,
    CONSTRAINT prebills_amounts_chk CHECK (((original_bill_amount >= (0)::numeric) AND (proposed_bill_amount >= (0)::numeric) AND (cost_amount >= (0)::numeric) AND (adjustment_amount = (proposed_bill_amount - original_bill_amount)))),
    CONSTRAINT prebills_conversion_chk CHECK (((status = 'converted'::text) = ((billing_request_id IS NOT NULL) AND (invoice_document_id IS NOT NULL) AND (converted_at IS NOT NULL) AND (converted_by IS NOT NULL)))),
    CONSTRAINT prebills_customer_acceptance_chk CHECK (((customer_decision IS DISTINCT FROM 'accepted'::text) OR ((customer_decided_at IS NOT NULL) AND (NULLIF(btrim(customer_signer_name), ''::text) IS NOT NULL)))),
    CONSTRAINT prebills_customer_decision_chk CHECK (((customer_decision IS NULL) OR (customer_decision = ANY (ARRAY['accepted'::text, 'disputed'::text])))),
    CONSTRAINT prebills_customer_review_chk CHECK (((status <> 'customer_review'::text) OR ((customer_review_sent_at IS NOT NULL) AND (NULLIF(btrim(customer_review_digest), ''::text) IS NOT NULL)))),
    CONSTRAINT prebills_delivery_chk CHECK (((delivered_at IS NULL) OR ((status = 'converted'::text) AND (delivered_by IS NOT NULL)))),
    CONSTRAINT prebills_period_chk CHECK (((period_start IS NULL) OR (period_end >= period_start))),
    CONSTRAINT prebills_status_chk CHECK ((status = ANY (ARRAY['draft'::text, 'review'::text, 'approved'::text, 'customer_review'::text, 'converted'::text, 'void'::text]))),
    CONSTRAINT prebills_void_chk CHECK (((status <> 'void'::text) OR ((voided_at IS NOT NULL) AND (voided_by IS NOT NULL) AND (NULLIF(btrim(void_reason), ''::text) IS NOT NULL))))
);

