    billing_request_id,
    invoice_document_id,
    submitted_at,
    submitted_by,
    approved_at,
    approved_by,
    converted_at,
    converted_by,
    voided_at,
    voided_by,
    void_reason,
    custom,
    created_at,
    created_by,
    updated_at,
    updated_by,
    customer_review_sent_at,
    customer_review_sent_by,
    customer_review_digest,
    customer_decision,
    customer_decided_at,
    customer_signer_name,
    customer_decision_note,
    customer_po_number,
    customer_viewed_at,
    delivered_at,
    delivered_by
   FROM public.prebills
  WHERE (org_id = public.openbooks_query_org_id());


