    schedule_actual_start date,
    schedule_actual_end date,
    estimated_price numeric(19,4),
    budget_quantity numeric(28,8),
    budget_unit text,
    CONSTRAINT project_tasks_budget_quantity_positive CHECK (((budget_quantity IS NULL) OR (budget_quantity > (0)::numeric))),
    CONSTRAINT project_tasks_budget_quantity_unit_pair CHECK (((budget_quantity IS NULL) = (budget_unit IS NULL))),
    CONSTRAINT project_tasks_budget_unit_text CHECK (((budget_unit IS NULL) OR ((budget_unit = btrim(budget_unit)) AND ((length(budget_unit) >= 1) AND (length(budget_unit) <= 32))))),
    CONSTRAINT project_tasks_estimated_price_nonnegative CHECK (((estimated_price IS NULL) OR (estimated_price >= (0)::numeric))),
    CONSTRAINT project_tasks_schedule_constraint_type_chk CHECK ((schedule_constraint_type = ANY (ARRAY['asap'::text, 'alap'::text, 'snet'::text, 'snlt'::text, 'fnet'::text, 'fnlt'::text, 'mso'::text, 'mfo'::text]))),
    CONSTRAINT project_tasks_schedule_dates_chk CHECK (((schedule_start IS NULL) OR (schedule_end IS NULL) OR (schedule_end >= schedule_start))),
    CONSTRAINT project_tasks_schedule_progress_chk CHECK (((schedule_progress >= (0)::numeric) AND (schedule_progress <= (1)::numeric))),
    CONSTRAINT project_tasks_schedule_status_chk CHECK ((schedule_status = ANY (ARRAY['not_started'::text, 'in_progress'::text, 'complete'::text, 'on_hold'::text]))),
    CONSTRAINT project_tasks_schedule_task_type_chk CHECK ((schedule_task_type = ANY (ARRAY['task'::text, 'milestone'::text, 'summary'::text])))
);

