    updated_by uuid,
    CONSTRAINT project_types_billing_procedure_control CHECK ((((invoicing_profile ->> 'billingProcedure'::text) = 'standard'::text) OR (((invoicing_profile ->> 'billingProcedure'::text) = 'application_for_payment'::text) AND (billing_method = 'fixed_price'::text) AND ((invoicing_profile -> 'allowedBases'::text) = '["draw_amount"]'::jsonb) AND ((invoicing_profile ->> 'defaultBasis'::text) = 'draw_amount'::text) AND ((invoicing_profile ->> 'lineBuilder'::text) = 'draw'::text)))),
    CONSTRAINT project_types_billing_procedure_required CHECK (((invoicing_profile ->> 'billingProcedure'::text) = ANY (ARRAY['standard'::text, 'application_for_payment'::text])))
);

