--
-- Name: promotions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.promotions (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    description text,
    kind text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    percent_value numeric(9,4),
    amount_minor bigint,
    currency character(3),
    buy_quantity integer,
    get_quantity integer,
    starts_at timestamp with time zone,
    ends_at timestamp with time zone,
    channel_scope_id uuid,
    usage_limit integer,
    usage_count integer DEFAULT 0 NOT NULL,
    discount_account_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT promotions_amount_value_valid CHECK ((((kind = 'amount'::text) AND (amount_minor IS NOT NULL) AND (amount_minor > 0) AND (currency IS NOT NULL) AND (buy_quantity IS NULL) AND (get_quantity IS NULL)) OR ((kind <> 'amount'::text) AND (amount_minor IS NULL) AND ((kind = 'free_shipping'::text) OR (currency IS NULL))))),
    CONSTRAINT promotions_bogo_valid CHECK ((((kind = 'buy_x_get_y'::text) AND (buy_quantity IS NOT NULL) AND (buy_quantity > 0) AND (get_quantity IS NOT NULL) AND (get_quantity > 0) AND (currency IS NULL)) OR ((kind <> 'buy_x_get_y'::text) AND (buy_quantity IS NULL) AND (get_quantity IS NULL)))),
    CONSTRAINT promotions_currency_valid CHECK (((currency IS NULL) OR (currency ~ '^[A-Z]{3}$'::text))),
    CONSTRAINT promotions_free_shipping_bare CHECK (((kind <> 'free_shipping'::text) OR (currency IS NULL))),
    CONSTRAINT promotions_kind_valid CHECK ((kind = ANY (ARRAY['percent'::text, 'amount'::text, 'free_shipping'::text, 'buy_x_get_y'::text]))),
    CONSTRAINT promotions_percent_value_valid CHECK ((((kind = 'percent'::text) AND (percent_value IS NOT NULL) AND (percent_value > (0)::numeric) AND (percent_value <= (100)::numeric) AND (amount_minor IS NULL) AND (buy_quantity IS NULL) AND (get_quantity IS NULL)) OR ((kind <> 'percent'::text) AND (percent_value IS NULL)))),
    CONSTRAINT promotions_status_valid CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'archived'::text]))),
    CONSTRAINT promotions_usage_count_valid CHECK ((usage_count >= 0)),
    CONSTRAINT promotions_usage_limit_valid CHECK (((usage_limit IS NULL) OR (usage_limit > 0))),
    CONSTRAINT promotions_window_valid CHECK (((starts_at IS NULL) OR (ends_at IS NULL) OR (ends_at > starts_at)))
);

ALTER TABLE ONLY public.promotions FORCE ROW LEVEL SECURITY;


--
-- Name: promotions; Type: VIEW; Schema: openbooks_query; Owner: -
--

