    currency,
    buy_quantity,
    get_quantity,
    starts_at,
    ends_at,
    channel_scope_id,
    usage_limit,
    usage_count,
    discount_account_id,
    created_at,
    created_by,
    updated_at,
    updated_by
   FROM public.promotions
  WHERE (org_id = public.openbooks_query_org_id());


