--
-- Name: rebate_agreements; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.rebate_agreements (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    subsidiary_id uuid NOT NULL,
    side text NOT NULL,
    activity text NOT NULL,
    party_id uuid,
    class_id uuid,
    item_id uuid,
    currency text NOT NULL,
    effective_from date NOT NULL,
    effective_to date NOT NULL,
    method text NOT NULL,
    tier_basis text NOT NULL,
    tiers jsonb NOT NULL,
    target_unit_cost numeric(19,4),
    margin_percent numeric(19,4),
    stacking text NOT NULL,
    selection_group text NOT NULL,
    accrual_account_id uuid NOT NULL,
    offset_account_id uuid NOT NULL,
    fx_account_id uuid NOT NULL,
    tax_treatment text NOT NULL,
    settlement_tax_code_id uuid,
    reason text NOT NULL,
    approved_by uuid,
    approved_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT rebate_agreements_activity_check CHECK ((activity = ANY (ARRAY['sale'::text, 'purchase'::text, 'downstream_sale'::text]))),
    CONSTRAINT rebate_agreements_check CHECK ((effective_to >= effective_from)),
    CONSTRAINT rebate_agreements_check1 CHECK ((((tax_treatment = 'outside_scope'::text) AND (settlement_tax_code_id IS NULL)) OR ((tax_treatment = 'taxable'::text) AND (settlement_tax_code_id IS NOT NULL)))),
    CONSTRAINT rebate_agreements_check2 CHECK ((((side = 'customer'::text) AND (activity = 'sale'::text) AND ((party_id IS NOT NULL) OR (class_id IS NOT NULL))) OR ((side = 'vendor'::text) AND (activity = ANY (ARRAY['purchase'::text, 'downstream_sale'::text])) AND (party_id IS NOT NULL)))),
    CONSTRAINT rebate_agreements_check3 CHECK (((activity <> 'downstream_sale'::text) OR (item_id IS NOT NULL))),
    CONSTRAINT rebate_agreements_check4 CHECK (((method <> 'fixed_cost'::text) OR ((target_unit_cost IS NOT NULL) AND (target_unit_cost >= (0)::numeric)))),
    CONSTRAINT rebate_agreements_check5 CHECK (((method <> 'guaranteed_margin'::text) OR ((margin_percent IS NOT NULL) AND (margin_percent >= (0)::numeric) AND (margin_percent < (100)::numeric)))),
    CONSTRAINT rebate_agreements_check6 CHECK (((accrual_account_id <> offset_account_id) AND (fx_account_id <> accrual_account_id))),
    CONSTRAINT rebate_agreements_check7 CHECK ((((status = 'draft'::text) AND (approved_by IS NULL) AND (approved_at IS NULL)) OR ((status = 'approved'::text) AND (approved_by IS NOT NULL) AND (approved_at IS NOT NULL) AND true))),
    CONSTRAINT rebate_agreements_method_check CHECK ((method = ANY (ARRAY['percent'::text, 'per_unit'::text, 'fixed_cost'::text, 'guaranteed_margin'::text]))),
    CONSTRAINT rebate_agreements_reason_check CHECK ((length(btrim(reason)) >= 8)),
    CONSTRAINT rebate_agreements_selection_group_check CHECK ((length(btrim(selection_group)) > 0)),
    CONSTRAINT rebate_agreements_side_check CHECK ((side = ANY (ARRAY['customer'::text, 'vendor'::text]))),
    CONSTRAINT rebate_agreements_stacking_check CHECK ((stacking = ANY (ARRAY['stack'::text, 'best'::text]))),
    CONSTRAINT rebate_agreements_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'approved'::text]))),
    CONSTRAINT rebate_agreements_tax_treatment_check CHECK ((tax_treatment = ANY (ARRAY['outside_scope'::text, 'taxable'::text]))),
    CONSTRAINT rebate_agreements_tier_basis_check CHECK ((tier_basis = ANY (ARRAY['amount'::text, 'quantity'::text]))),
    CONSTRAINT rebate_agreements_tiers_check CHECK ((jsonb_typeof(tiers) = 'array'::text))
);

ALTER TABLE ONLY public.rebate_agreements FORCE ROW LEVEL SECURITY;


