    party_id,
    class_id,
    item_id,
    currency,
    effective_from,
    effective_to,
    method,
    tier_basis,
    tiers,
    target_unit_cost,
    margin_percent,
    stacking,
    selection_group,
    accrual_account_id,
    offset_account_id,
    fx_account_id,
    tax_treatment,
    settlement_tax_code_id,
    reason,
    approved_by,
    approved_at,
    created_at,
    created_by,
    updated_at,
    updated_by
   FROM public.rebate_agreements
  WHERE (org_id = public.openbooks_query_org_id());


