CREATE TABLE public.rebate_claims (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    agreement_id uuid NOT NULL,
    party_id uuid NOT NULL,
    amount numeric(19,4) NOT NULL,
    base_amount numeric(19,4) NOT NULL,
    cutoff_on date NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    reason text NOT NULL,
    basis jsonb NOT NULL,
    approved_by uuid,
    approved_at timestamp with time zone,
    settlement_document_id uuid,
    settlement_entry_id uuid,
    settlement_on date,
    settlement_basis jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT rebate_claims_amount_check CHECK ((amount <> (0)::numeric)),
    CONSTRAINT rebate_claims_check CHECK (((status = ANY (ARRAY['draft'::text, 'cancelled'::text])) OR ((approved_by IS NOT NULL) AND (approved_at IS NOT NULL) AND true))),
    CONSTRAINT rebate_claims_check1 CHECK (((status <> 'settled'::text) OR ((settlement_entry_id IS NOT NULL) AND (settlement_on IS NOT NULL)))),
    CONSTRAINT rebate_claims_reason_check CHECK ((length(btrim(reason)) >= 8)),
    CONSTRAINT rebate_claims_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'approved'::text, 'document_pending'::text, 'settled'::text, 'cancelled'::text])))
);

ALTER TABLE ONLY public.rebate_claims FORCE ROW LEVEL SECURITY;


--
-- Name: rebate_claims; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.rebate_claims WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    agreement_id,
    party_id,
    amount,
    base_amount,
    cutoff_on,
    status,
    reason,
    basis,
    approved_by,
    approved_at,
    settlement_document_id,
    settlement_entry_id,
    settlement_on,
    settlement_basis,
    created_at,
    created_by,
    updated_at,
    updated_by
   FROM public.rebate_claims
  WHERE (org_id = public.openbooks_query_org_id());


