--
-- Name: reconciliations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.reconciliations (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    account_id uuid NOT NULL,
    through_date date NOT NULL,
    statement_balance numeric(19,4) NOT NULL,
    status text DEFAULT 'in_progress'::text NOT NULL,
    signed_off_by uuid,
    signed_off_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    currency text NOT NULL,
    evidence_kind text DEFAULT 'statement'::text NOT NULL,
    evidence_connector text,
    CONSTRAINT reconciliations_evidence_kind CHECK ((evidence_kind = ANY (ARRAY['statement'::text, 'source'::text]))),
    CONSTRAINT reconciliations_signoff_evidence CHECK ((((status = 'signed_off'::text) AND (signed_off_by IS NOT NULL) AND (signed_off_at IS NOT NULL)) OR ((status <> 'signed_off'::text) AND (signed_off_by IS NULL) AND (signed_off_at IS NULL)))),
    CONSTRAINT reconciliations_source_evidence CHECK ((((evidence_kind = 'source'::text) AND (evidence_connector IS NOT NULL) AND (length(btrim(evidence_connector)) > 0)) OR ((evidence_kind = 'statement'::text) AND (evidence_connector IS NULL))))
);

ALTER TABLE ONLY public.reconciliations FORCE ROW LEVEL SECURITY;


--
-- Name: COLUMN reconciliations.evidence_kind; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.reconciliations.evidence_kind IS 'What the sign-off stands on: statement = matched imported statement lines; source = the connector-mirrored cleared evidence, with no statement lines invented.';


--
-- Name: COLUMN reconciliations.evidence_connector; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.reconciliations.evidence_connector IS 'Stable connector key (the connection source key) for source-evidenced sign-offs; null for statement sign-offs.';


--
-- Name: reconciliations; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.reconciliations WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    account_id,
    through_date,
    statement_balance,
    status,
    signed_off_by,
    signed_off_at,
    created_at,
    created_by,
    updated_at,
    updated_by,
    currency,
    evidence_kind,
    evidence_connector
   FROM public.reconciliations
  WHERE (org_id = public.openbooks_query_org_id());


--
-- Name: recurring_schedules; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.recurring_schedules (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    template_document_id uuid NOT NULL,
    cadence text NOT NULL,
    cron text,
    next_run_on date NOT NULL,
    ends_on date,
    auto_post boolean DEFAULT false NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    last_run_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    name text,
    run_count integer DEFAULT 0 NOT NULL,
    last_document_id uuid,
    last_error text,
    anchor_day smallint,
    max_occurrences integer,
    skipped_run_ons date[] DEFAULT '{}'::date[] NOT NULL,
    CONSTRAINT recurring_schedules_anchor_day_range CHECK (((anchor_day IS NULL) OR ((anchor_day >= 1) AND (anchor_day <= 31)))),
    CONSTRAINT recurring_schedules_max_occurrences_range CHECK (((max_occurrences IS NULL) OR (max_occurrences >= 1)))
);

ALTER TABLE ONLY public.recurring_schedules FORCE ROW LEVEL SECURITY;


--
-- Name: COLUMN recurring_schedules.anchor_day; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.recurring_schedules.anchor_day IS 'Day-of-month the schedule cadence pins to. Each next run date advances the year-month and clamps this day into the target month, so month-end starts do not drift. Null behaves as the next run date''s day.';


--
-- Name: COLUMN recurring_schedules.max_occurrences; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.recurring_schedules.max_occurrences IS 'Maximum documents this schedule generates. The scheduler tick, catch-up runs, and run-now stop once run_count reaches it and deactivate the schedule, exactly as the end date does. Null means unlimited.';


--
-- Name: COLUMN recurring_schedules.skipped_run_ons; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.recurring_schedules.skipped_run_ons IS 'Period dates this schedule never bills. A due occurrence whose date is listed advances past it with no document and no counter, so out-of-season periods stay silent; the dates remain visible in the editor. Empty means nothing skipped.';


--
-- Name: recurring_schedules; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.recurring_schedules WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    template_document_id,
    cadence,
    cron,
    next_run_on,
    ends_on,
    auto_post,
    is_active,
    last_run_at,
    created_at,
    created_by,
    updated_at,
    updated_by,
    name,
    run_count,
    last_document_id,
    last_error,
    anchor_day,
    max_occurrences,
    skipped_run_ons
   FROM public.recurring_schedules
  WHERE (org_id = public.openbooks_query_org_id());


