    updated_by uuid,
    CONSTRAINT res_assignments_booking CHECK ((booking = ANY (ARRAY['soft'::text, 'hard'::text]))),
    CONSTRAINT res_assignments_job_title_nonblank CHECK (((job_title IS NULL) OR (length(btrim(job_title)) > 0))),
    CONSTRAINT res_assignments_planned_hours_range CHECK (((planned_hours > (0)::numeric) AND (planned_hours <= (168)::numeric))),
    CONSTRAINT res_assignments_source CHECK ((source = ANY (ARRAY['manual'::text, 'request'::text, 'pipeline'::text]))),
    CONSTRAINT res_assignments_state CHECK ((state = ANY (ARRAY['active'::text, 'released'::text]))),
    CONSTRAINT res_assignments_subject CHECK ((num_nonnulls(employee_party_id, job_title) = 1)),
    CONSTRAINT res_assignments_week_start_sunday CHECK ((EXTRACT(dow FROM week_start) = (0)::numeric))
);

ALTER TABLE ONLY public.res_assignments FORCE ROW LEVEL SECURITY;


--
-- Name: res_assignments; Type: VIEW; Schema: openbooks_query; Owner: -
