    CONSTRAINT saas_metrics_monthly_norm_complete CHECK ((((reporting_currency IS NULL) AND (denomination_version IS NULL) AND (normalization_evidence IS NULL)) OR ((reporting_currency IS NOT NULL) AND (denomination_version IS NOT NULL) AND (normalization_evidence IS NOT NULL)))),
    CONSTRAINT saas_metrics_monthly_norm_shape CHECK (((reporting_currency IS NULL) OR ((reporting_currency ~ '^[A-Z]{3}$'::text) AND (denomination_version ~ '^v[0-9]+$'::text) AND (char_length(denomination_version) <= 64) AND (jsonb_typeof(normalization_evidence) = 'object'::text) AND ((normalization_evidence ->> 'inputs_hash'::text) ~ '^[0-9a-f]{64}$'::text))))
);

