    CONSTRAINT saas_metrics_normalization_requests_reason_nonblank CHECK (((char_length(btrim(reason)) >= 8) AND (char_length(btrim(reason)) <= 1000))),
    CONSTRAINT saas_metrics_normalization_requests_request_hash_digest CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT saas_metrics_normalization_requests_status_valid CHECK ((status = ANY (ARRAY['pending'::text, 'running'::text, 'succeeded'::text, 'failed'::text, 'cancelled'::text])))
);

