    entry_id uuid NOT NULL,
    board_id uuid NOT NULL,
    policy_id uuid,
    subsidiary_id uuid,
    worker_party_id uuid NOT NULL,
    employment_id uuid,
    status text NOT NULL,
    complete_through timestamp with time zone,
    first_in timestamp with time zone,
    last_out timestamp with time zone,
    presence_milliseconds bigint,
    break_milliseconds bigint,
    late boolean,
    left_early boolean,
    over_break boolean,
    source_evidence jsonb NOT NULL,
    evidence_hash text NOT NULL,
    supersedes_id uuid,
    reason text NOT NULL,
    request_hash text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    CONSTRAINT schedule_attendance_observations_break_milliseconds_check CHECK ((break_milliseconds >= 0)),
    CONSTRAINT schedule_attendance_observations_evidence_hash_check CHECK ((evidence_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT schedule_attendance_observations_outcome CHECK ((((status = ANY (ARRAY['waiting_for_sync'::text, 'voided'::text])) AND (presence_milliseconds IS NULL) AND (break_milliseconds IS NULL) AND (late IS NULL) AND (left_early IS NULL) AND (over_break IS NULL) AND (first_in IS NULL) AND (last_out IS NULL)) OR ((status = 'absent'::text) AND (presence_milliseconds = 0) AND (break_milliseconds = 0) AND (late = false) AND (left_early = false) AND (over_break = false) AND (first_in IS NULL) AND (last_out IS NULL)) OR ((status = 'present'::text) AND (presence_milliseconds IS NOT NULL) AND (break_milliseconds IS NOT NULL) AND (late IS NOT NULL) AND (left_early IS NOT NULL) AND (over_break IS NOT NULL) AND (first_in IS NOT NULL) AND (last_out > first_in) AND (((presence_milliseconds + break_milliseconds))::numeric <= (EXTRACT(epoch FROM (last_out - first_in)) * (1000)::numeric))))),
    CONSTRAINT schedule_attendance_observations_policy CHECK (((status = 'voided'::text) OR (policy_id IS NOT NULL))),
    CONSTRAINT schedule_attendance_observations_presence_milliseconds_check CHECK ((presence_milliseconds >= 0)),
    CONSTRAINT schedule_attendance_observations_reason_check CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 2000))),
    CONSTRAINT schedule_attendance_observations_request_hash_check CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT schedule_attendance_observations_source_evidence_check CHECK ((jsonb_typeof(source_evidence) = 'object'::text)),
    CONSTRAINT schedule_attendance_observations_status_check CHECK ((status = ANY (ARRAY['waiting_for_sync'::text, 'absent'::text, 'present'::text, 'voided'::text])))
);

