--
-- Name: schedule_boards; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.schedule_boards (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    description text,
    row_kind text NOT NULL,
    subsidiary_id uuid,
    department_id uuid,
    location_id uuid,
    project_id uuid,
    grain text DEFAULT 'day'::text NOT NULL,
    views text[] NOT NULL,
    default_view text NOT NULL,
    range_days smallint DEFAULT 14 NOT NULL,
    week_starts_on smallint DEFAULT 0 NOT NULL,
    show_weekends boolean DEFAULT true NOT NULL,
    time_zone text NOT NULL,
    day_starts time without time zone DEFAULT '07:00:00'::time without time zone NOT NULL,
    day_ends time without time zone DEFAULT '15:30:00'::time without time zone NOT NULL,
    day_break_minutes smallint DEFAULT 30 NOT NULL,
    publish_policy text DEFAULT 'live'::text NOT NULL,
    prefill_timesheets boolean DEFAULT false NOT NULL,
    prefill_crew_time boolean DEFAULT false NOT NULL,
    prefill_field_tickets boolean DEFAULT false NOT NULL,
    notify_assignees boolean DEFAULT false NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    resource_kind text,
    cell_color_rules jsonb DEFAULT '[]'::jsonb NOT NULL,
    show_totals boolean DEFAULT false NOT NULL,
    weekend_days text[] DEFAULT ARRAY['6'::text, '7'::text] NOT NULL,
    day_policy_known boolean DEFAULT true NOT NULL,
    show_hours_column boolean DEFAULT true NOT NULL,
    distribution_visibility text DEFAULT 'personal'::text NOT NULL,
    automatic_delivery_policy jsonb,
    board_type text NOT NULL,
    governed_from date,
    CONSTRAINT schedule_boards_automatic_delivery_policy_check CHECK (((automatic_delivery_policy IS NULL) OR (jsonb_typeof(automatic_delivery_policy) = 'object'::text))),
    CONSTRAINT schedule_boards_cell_color_rules CHECK (public.schedule_cell_color_rules_valid(cell_color_rules)),
    CONSTRAINT schedule_boards_code_check CHECK ((code ~ '^[A-Za-z0-9][A-Za-z0-9_.-]{0,39}$'::text)),
    CONSTRAINT schedule_boards_day_break_minutes_check CHECK (((day_break_minutes >= 0) AND (day_break_minutes <= 240))),
    CONSTRAINT schedule_boards_day_span CHECK (((day_ends > day_starts) AND (EXTRACT(epoch FROM (day_ends - day_starts)) > ((day_break_minutes * 60))::numeric))),
    CONSTRAINT schedule_boards_default_view_listed CHECK ((default_view = ANY (views))),
    CONSTRAINT schedule_boards_description_check CHECK (((description IS NULL) OR (length(description) <= 2000))),
    CONSTRAINT schedule_boards_distribution_entity CHECK (((distribution_visibility <> 'board'::text) OR (subsidiary_id IS NOT NULL))),
    CONSTRAINT schedule_boards_distribution_visibility_check CHECK ((distribution_visibility = ANY (ARRAY['personal'::text, 'board'::text]))),
    CONSTRAINT schedule_boards_governed_from CHECK ((((publish_policy = 'governed'::text) = (governed_from IS NOT NULL)) AND ((governed_from IS NULL) OR ((governed_from >= '0001-01-01'::date) AND (governed_from <= '9999-12-31'::date))))),
    CONSTRAINT schedule_boards_grain_check CHECK ((grain = ANY (ARRAY['day'::text, 'timed'::text]))),
    CONSTRAINT schedule_boards_name_check CHECK ((((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 120)) AND (name = btrim(name)))),
    CONSTRAINT schedule_boards_people_settings CHECK (((row_kind = 'people'::text) OR (NOT (prefill_timesheets OR prefill_crew_time OR prefill_field_tickets OR notify_assignees)))),
    CONSTRAINT schedule_boards_publish_policy_check CHECK ((publish_policy = ANY (ARRAY['live'::text, 'staged'::text]))),
    CONSTRAINT schedule_boards_range_days_check CHECK ((range_days = ANY (ARRAY[1, 3, 7, 14, 21, 28, 35, 42]))),
    CONSTRAINT schedule_boards_resource_kind CHECK ((((row_kind = 'resources'::text) AND COALESCE((resource_kind = ANY (ARRAY['equipment'::text, 'location'::text])), false) AND (department_id IS NULL) AND ((resource_kind = 'location'::text) OR (location_id IS NULL))) OR ((row_kind <> 'resources'::text) AND (resource_kind IS NULL)))),
    CONSTRAINT schedule_boards_row_kind_check CHECK ((row_kind = ANY (ARRAY['people'::text, 'tasks'::text, 'resources'::text]))),
    CONSTRAINT schedule_boards_time_zone_check CHECK (((length(time_zone) >= 1) AND (length(time_zone) <= 128))),
    CONSTRAINT schedule_boards_views_valid CHECK (public.schedule_board_views_valid(row_kind, views)),
    CONSTRAINT schedule_boards_week_starts_on_check CHECK (((week_starts_on >= 0) AND (week_starts_on <= 6))),
    CONSTRAINT schedule_boards_weekend_days CHECK (((COALESCE(array_ndims(weekend_days), 1) = 1) AND (weekend_days <@ ARRAY['1'::text, '2'::text, '3'::text, '4'::text, '5'::text, '6'::text, '7'::text])))
);

