--
-- Name: schedule_entry_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.schedule_entry_requests (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    board_id uuid NOT NULL,
    entry_id uuid NOT NULL,
    entry_revision integer NOT NULL,
    worker_party_id uuid NOT NULL,
    subsidiary_id uuid,
    kind text NOT NULL,
    proposed_starts_at timestamp with time zone,
    proposed_ends_at timestamp with time zone,
    proposed_break_minutes smallint,
    counterpart_entry_id uuid,
    counterpart_entry_revision integer,
    counterpart_party_id uuid,
    counterpart_responded_by uuid,
    counterpart_responded_at timestamp with time zone,
    status text NOT NULL,
    flow_run_id uuid,
    decided_by uuid,
    decided_at timestamp with time zone,
    decision_reason text,
    reason text NOT NULL,
    request_hash text NOT NULL,
    revision integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid NOT NULL,
    released_without_approval boolean DEFAULT false NOT NULL,
    CONSTRAINT schedule_entry_requests_counterpart_entry_revision_check CHECK ((counterpart_entry_revision > 0)),
    CONSTRAINT schedule_entry_requests_counterpart_response CHECK ((((counterpart_responded_by IS NULL) = (counterpart_responded_at IS NULL)) AND ((status <> 'awaiting_counterpart'::text) OR (kind = 'swap'::text)) AND ((kind <> 'swap'::text) OR (status <> ALL (ARRAY['pending'::text, 'approved'::text])) OR (counterpart_responded_by IS NOT NULL)) AND ((kind = 'swap'::text) OR (counterpart_responded_by IS NULL)))),
    CONSTRAINT schedule_entry_requests_decision CHECK ((((decided_by IS NULL) OR (decided_at IS NOT NULL)) AND ((status = ANY (ARRAY['approved'::text, 'declined'::text])) = ((decided_at IS NOT NULL) AND (decision_reason IS NOT NULL))) AND ((status <> ALL (ARRAY['approved'::text, 'declined'::text])) OR (decided_by IS NOT NULL) OR released_without_approval) AND ((NOT released_without_approval) OR ((status = 'approved'::text) AND (decided_by IS NULL) AND (flow_run_id IS NULL))))),
    CONSTRAINT schedule_entry_requests_decision_reason_check CHECK (((decision_reason IS NULL) OR ((length(btrim(decision_reason)) >= 1) AND (length(btrim(decision_reason)) <= 2000)))),
    CONSTRAINT schedule_entry_requests_entry_revision_check CHECK ((entry_revision > 0)),
    CONSTRAINT schedule_entry_requests_kind_check CHECK ((kind = ANY (ARRAY['release'::text, 'change'::text, 'swap'::text]))),
    CONSTRAINT schedule_entry_requests_proposed_break_minutes_check CHECK (((proposed_break_minutes >= 0) AND (proposed_break_minutes <= 240))),
    CONSTRAINT schedule_entry_requests_reason_check CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 2000))),
    CONSTRAINT schedule_entry_requests_request_hash_check CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT schedule_entry_requests_revision_check CHECK ((revision > 0)),
    CONSTRAINT schedule_entry_requests_shape CHECK ((((kind = 'release'::text) AND (proposed_starts_at IS NULL) AND (proposed_ends_at IS NULL) AND (proposed_break_minutes IS NULL) AND (counterpart_entry_id IS NULL) AND (counterpart_entry_revision IS NULL) AND (counterpart_party_id IS NULL)) OR ((kind = 'change'::text) AND (proposed_starts_at IS NOT NULL) AND (proposed_ends_at > proposed_starts_at) AND ((proposed_ends_at - proposed_starts_at) <= '48:00:00'::interval) AND (proposed_break_minutes IS NOT NULL) AND (((proposed_break_minutes * 60))::numeric < EXTRACT(epoch FROM (proposed_ends_at - proposed_starts_at))) AND (proposed_starts_at = date_trunc('milliseconds'::text, proposed_starts_at)) AND (proposed_ends_at = date_trunc('milliseconds'::text, proposed_ends_at)) AND (counterpart_entry_id IS NULL) AND (counterpart_entry_revision IS NULL) AND (counterpart_party_id IS NULL)) OR ((kind = 'swap'::text) AND (proposed_starts_at IS NULL) AND (proposed_ends_at IS NULL) AND (proposed_break_minutes IS NULL) AND (counterpart_entry_id IS NOT NULL) AND (counterpart_entry_revision IS NOT NULL) AND (counterpart_party_id IS NOT NULL) AND (counterpart_entry_id <> entry_id) AND (counterpart_party_id <> worker_party_id)))),
    CONSTRAINT schedule_entry_requests_status_check CHECK ((status = ANY (ARRAY['awaiting_counterpart'::text, 'pending'::text, 'approved'::text, 'declined'::text, 'withdrawn'::text])))
);

ALTER TABLE ONLY public.schedule_entry_requests FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE schedule_entry_requests; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.schedule_entry_requests IS 'Employee requests to release, change or swap their own published booking. A swap first needs the colleague''s acceptance; an independent approver decides, and approval applies the outcome in the same transaction.';


