  WHERE (org_id = public.openbooks_query_org_id());


--
-- Name: schedule_pattern_assignments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.schedule_pattern_assignments (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    board_id uuid NOT NULL,
    pattern_id uuid NOT NULL,
    worker_party_id uuid NOT NULL,
    employment_id uuid,
    subsidiary_id uuid,
    effective_from date NOT NULL,
    effective_to date,
    status text DEFAULT 'active'::text NOT NULL,
    generated_through date,
    last_generation jsonb,
    reason text NOT NULL,
    request_hash text NOT NULL,
    revision integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid NOT NULL,
    CONSTRAINT schedule_pattern_assignments_check CHECK (((effective_to > effective_from) AND (effective_to <= '9999-12-31'::date))),
    CONSTRAINT schedule_pattern_assignments_effective_from_check CHECK (((effective_from >= '0001-01-01'::date) AND (effective_from <= '9999-12-31'::date))),
    CONSTRAINT schedule_pattern_assignments_ended CHECK (((status <> 'ended'::text) OR (effective_to IS NOT NULL))),
    CONSTRAINT schedule_pattern_assignments_last_generation_check CHECK (((last_generation IS NULL) OR (jsonb_typeof(last_generation) = 'object'::text))),
    CONSTRAINT schedule_pattern_assignments_reason_check CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 2000))),
    CONSTRAINT schedule_pattern_assignments_request_hash_check CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT schedule_pattern_assignments_revision_check CHECK ((revision > 0)),
    CONSTRAINT schedule_pattern_assignments_status_check CHECK ((status = ANY (ARRAY['active'::text, 'ended'::text, 'cancelled'::text])))
);

