--
-- Name: schedule_pattern_exceptions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.schedule_pattern_exceptions (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    assignment_id uuid NOT NULL,
    occurs_on date NOT NULL,
    slot_index smallint NOT NULL,
    kind text NOT NULL,
    starts_at timestamp with time zone,
    ends_at timestamp with time zone,
    reason text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    revoked_at timestamp with time zone,
    revoked_by uuid,
    revoke_reason text,
    CONSTRAINT schedule_pattern_exceptions_kind CHECK ((((kind = 'omit'::text) AND (starts_at IS NULL) AND (ends_at IS NULL)) OR ((kind = 'select_instant'::text) AND (starts_at IS NOT NULL) AND (ends_at > starts_at) AND ((ends_at - starts_at) <= '48:00:00'::interval) AND (starts_at = date_trunc('milliseconds'::text, starts_at)) AND (ends_at = date_trunc('milliseconds'::text, ends_at))))),
    CONSTRAINT schedule_pattern_exceptions_kind_check CHECK ((kind = ANY (ARRAY['omit'::text, 'select_instant'::text]))),
    CONSTRAINT schedule_pattern_exceptions_occurs_on_check CHECK (((occurs_on >= '0001-01-01'::date) AND (occurs_on <= '9999-12-31'::date))),
    CONSTRAINT schedule_pattern_exceptions_reason_check CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 2000))),
    CONSTRAINT schedule_pattern_exceptions_revocation CHECK ((((revoked_at IS NULL) AND (revoked_by IS NULL) AND (revoke_reason IS NULL)) OR ((revoked_at IS NOT NULL) AND (revoked_by IS NOT NULL) AND ((length(btrim(revoke_reason)) >= 1) AND (length(btrim(revoke_reason)) <= 2000))))),
    CONSTRAINT schedule_pattern_exceptions_slot_index_check CHECK (((slot_index >= 0) AND (slot_index <= 999)))
);

