--
-- Name: schedule_patterns; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.schedule_patterns (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    subsidiary_id uuid,
    code text NOT NULL,
    name text NOT NULL,
    description text,
    time_zone text NOT NULL,
    cycle_days smallint NOT NULL,
    cycle_anchor date NOT NULL,
    slots jsonb NOT NULL,
    target_kind text,
    customer_party_id uuid,
    project_id uuid,
    project_task_id uuid,
    location_id uuid,
    schedule_code_id uuid,
    department_id uuid,
    detail text,
    horizon_days smallint DEFAULT 28 NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    reason text NOT NULL,
    revision integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid NOT NULL,
    CONSTRAINT schedule_patterns_code_check CHECK ((((length(code) >= 1) AND (length(code) <= 64)) AND (code = btrim(code)))),
    CONSTRAINT schedule_patterns_cycle_anchor_check CHECK (((cycle_anchor >= '0001-01-01'::date) AND (cycle_anchor <= '9999-12-31'::date))),
    CONSTRAINT schedule_patterns_description_check CHECK (((description IS NULL) OR (length(description) <= 2000))),
    CONSTRAINT schedule_patterns_detail_check CHECK (((detail IS NULL) OR (((length(btrim(detail)) >= 1) AND (length(btrim(detail)) <= 120)) AND (detail = btrim(detail))))),
    CONSTRAINT schedule_patterns_horizon_days_check CHECK (((horizon_days >= 1) AND (horizon_days <= 366))),
    CONSTRAINT schedule_patterns_name_check CHECK ((((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 160)) AND (name = btrim(name)))),
    CONSTRAINT schedule_patterns_reason_check CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 2000))),
    CONSTRAINT schedule_patterns_revision_check CHECK ((revision > 0)),
    CONSTRAINT schedule_patterns_slots CHECK (public.schedule_pattern_slots_valid(slots, (cycle_days)::integer)),
    CONSTRAINT schedule_patterns_target CHECK ((((target_kind IS NULL) AND (customer_party_id IS NULL) AND (project_id IS NULL) AND (location_id IS NULL) AND (schedule_code_id IS NULL)) OR ((target_kind = 'customer'::text) AND (customer_party_id IS NOT NULL) AND (project_id IS NULL) AND (location_id IS NULL) AND (schedule_code_id IS NULL)) OR ((target_kind = 'project'::text) AND (project_id IS NOT NULL) AND (customer_party_id IS NULL) AND (location_id IS NULL) AND (schedule_code_id IS NULL)) OR ((target_kind = 'location'::text) AND (location_id IS NOT NULL) AND (customer_party_id IS NULL) AND (project_id IS NULL) AND (schedule_code_id IS NULL)) OR ((target_kind = 'code'::text) AND (schedule_code_id IS NOT NULL) AND (customer_party_id IS NULL) AND (project_id IS NULL) AND (location_id IS NULL)))),
    CONSTRAINT schedule_patterns_target_kind_check CHECK ((target_kind = ANY (ARRAY['customer'::text, 'project'::text, 'location'::text, 'code'::text]))),
    CONSTRAINT schedule_patterns_task_needs_project CHECK (((project_task_id IS NULL) OR (project_id IS NOT NULL))),
    CONSTRAINT schedule_patterns_time_zone_check CHECK (((length(time_zone) >= 1) AND (length(time_zone) <= 128)))
);

