   FROM public.schedule_patterns
  WHERE (org_id = public.openbooks_query_org_id());


--
-- Name: schedule_publications; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.schedule_publications (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    board_id uuid NOT NULL,
    subsidiary_id uuid,
    from_date date NOT NULL,
    through_date date NOT NULL,
    entry_ids uuid[] NOT NULL,
    entry_revisions integer[] NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    flow_run_id uuid,
    released_without_approval boolean DEFAULT false NOT NULL,
    decided_by uuid,
    decided_at timestamp with time zone,
    decision_reason text,
    reason text NOT NULL,
    request_hash text NOT NULL,
    revision integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid NOT NULL,
    CONSTRAINT schedule_publications_decision CHECK ((((decided_by IS NULL) OR (decided_at IS NOT NULL)) AND ((status = ANY (ARRAY['approved'::text, 'declined'::text])) = ((decided_at IS NOT NULL) AND (decision_reason IS NOT NULL))) AND ((status <> ALL (ARRAY['approved'::text, 'declined'::text])) OR (decided_by IS NOT NULL) OR released_without_approval) AND ((NOT released_without_approval) OR ((status = 'approved'::text) AND (decided_by IS NULL) AND (flow_run_id IS NULL))))),
    CONSTRAINT schedule_publications_decision_reason_check CHECK (((decision_reason IS NULL) OR ((length(btrim(decision_reason)) >= 1) AND (length(btrim(decision_reason)) <= 2000)))),
    CONSTRAINT schedule_publications_entries CHECK (((COALESCE(array_ndims(entry_ids), 1) = 1) AND ((cardinality(entry_ids) >= 1) AND (cardinality(entry_ids) <= 5000)) AND (cardinality(entry_revisions) = cardinality(entry_ids)))),
    CONSTRAINT schedule_publications_from_date_check CHECK (((from_date >= '0001-01-01'::date) AND (from_date <= '9999-12-31'::date))),
    CONSTRAINT schedule_publications_reason_check CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 2000))),
    CONSTRAINT schedule_publications_request_hash_check CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT schedule_publications_revision_check CHECK ((revision > 0)),
    CONSTRAINT schedule_publications_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'declined'::text, 'withdrawn'::text]))),
    CONSTRAINT schedule_publications_through_date_check CHECK (((through_date >= '0001-01-01'::date) AND (through_date <= '9999-12-31'::date))),
    CONSTRAINT schedule_publications_window CHECK (((through_date >= from_date) AND ((through_date - from_date) <= 366)))
);

