    CONSTRAINT schedule_source_records_check CHECK (((disposition = 'exception'::text) OR ((board_id IS NOT NULL) AND (worker_party_id IS NOT NULL) AND (on_date IS NOT NULL)))),
    CONSTRAINT schedule_source_records_check1 CHECK (((disposition = 'linked'::text) = (linked_entry_id IS NOT NULL))),
    CONSTRAINT schedule_source_records_disposition_check CHECK ((disposition = ANY (ARRAY['recorded'::text, 'linked'::text, 'exception'::text]))),
    CONSTRAINT schedule_source_records_label_check CHECK (((label IS NULL) OR (length(label) <= 1000))),
    CONSTRAINT schedule_source_records_reason_check CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 2000))),
    CONSTRAINT schedule_source_records_source_dataset_check CHECK (((length(source_dataset) >= 1) AND (length(source_dataset) <= 200))),
    CONSTRAINT schedule_source_records_source_hash_check CHECK ((source_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT schedule_source_records_source_key_check CHECK (((length(source_key) >= 1) AND (length(source_key) <= 200))),
    CONSTRAINT schedule_source_records_source_notes_check CHECK (((source_notes IS NULL) OR (length(source_notes) <= 2000))),
    CONSTRAINT schedule_source_records_source_payload_check CHECK ((jsonb_typeof(source_payload) = 'object'::text)),
    CONSTRAINT schedule_source_records_source_result_check CHECK (((source_result IS NULL) OR (length(source_result) <= 1000))),
    CONSTRAINT schedule_source_records_source_system_check CHECK (((length(source_system) >= 1) AND (length(source_system) <= 200)))
);

