-- Name: service_agreement_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.service_agreement_versions (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    agreement_id uuid NOT NULL,
    effective_from date NOT NULL,
    recurrence jsonb NOT NULL,
    window_starts time without time zone NOT NULL,
    window_ends time without time zone NOT NULL,
    estimated_minutes smallint NOT NULL,
    priority text NOT NULL,
    required_qualification_type_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    instructions text,
    reason text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    CONSTRAINT service_agreement_versions_estimated_minutes_check CHECK (((estimated_minutes >= 5) AND (estimated_minutes <= 1440))),
    CONSTRAINT service_agreement_versions_instructions_check CHECK (((instructions IS NULL) OR (length(instructions) <= 4000))),
    CONSTRAINT service_agreement_versions_priority_check CHECK ((priority = ANY (ARRAY['low'::text, 'normal'::text, 'high'::text, 'urgent'::text]))),
    CONSTRAINT service_agreement_versions_reason_check CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 2000))),
    CONSTRAINT service_agreement_versions_recurrence CHECK (((jsonb_typeof(recurrence) = 'object'::text) AND ((recurrence ->> 'repeat'::text) = ANY (ARRAY['daily'::text, 'weekly'::text, 'monthly'::text, 'yearly'::text])) AND (jsonb_typeof((recurrence -> 'interval'::text)) = 'number'::text) AND ((recurrence ->> 'interval'::text) ~ '^[0-9]{1,2}$'::text) AND ((((recurrence ->> 'interval'::text))::integer >= 1) AND (((recurrence ->> 'interval'::text))::integer <= 52)))),
    CONSTRAINT service_agreement_versions_required_qualification_type_id_check CHECK (((COALESCE(array_ndims(required_qualification_type_ids), 1) = 1) AND (COALESCE(array_length(required_qualification_type_ids, 1), 0) <= 100))),
    CONSTRAINT service_agreement_versions_window CHECK ((window_ends > window_starts))
);

