    request_id uuid,
    quote_document_id uuid,
    agreement_id uuid,
    title text NOT NULL,
    description text,
    priority text NOT NULL,
    required_qualification_type_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    estimated_minutes smallint NOT NULL,
    sla_due_at timestamp with time zone,
    billing_mode text NOT NULL,
    labor_item_id uuid,
    labor_unit_price numeric(28,8),
    currency text NOT NULL,
    deposit_required numeric(19,4) DEFAULT 0 NOT NULL,
    status text NOT NULL,
    completed_at timestamp with time zone,
    completed_by uuid,
    close_reason text,
    revision integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid NOT NULL,
    CONSTRAINT service_jobs_agreement CHECK (((agreement_id IS NULL) OR (billing_mode = ANY (ARRAY['per_visit'::text, 'not_billable'::text])))),
    CONSTRAINT service_jobs_billing_mode_check CHECK ((billing_mode = ANY (ARRAY['per_job'::text, 'per_visit'::text, 'not_billable'::text]))),
    CONSTRAINT service_jobs_close_reason_check CHECK (((close_reason IS NULL) OR ((length(btrim(close_reason)) >= 1) AND (length(btrim(close_reason)) <= 2000)))),
    CONSTRAINT service_jobs_completion CHECK ((((status = 'completed'::text) = ((completed_at IS NOT NULL) AND (completed_by IS NOT NULL))) AND ((status = 'cancelled'::text) = (close_reason IS NOT NULL)))),
    CONSTRAINT service_jobs_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT service_jobs_deposit_required_check CHECK ((deposit_required >= (0)::numeric)),
    CONSTRAINT service_jobs_description_check CHECK (((description IS NULL) OR (length(description) <= 8000))),
    CONSTRAINT service_jobs_estimated_minutes_check CHECK (((estimated_minutes >= 5) AND (estimated_minutes <= 1440))),
    CONSTRAINT service_jobs_job_number_check CHECK (((length(btrim(job_number)) >= 1) AND (length(btrim(job_number)) <= 40))),
    CONSTRAINT service_jobs_labor CHECK (((labor_item_id IS NULL) = (labor_unit_price IS NULL))),
    CONSTRAINT service_jobs_labor_unit_price_check CHECK (((labor_unit_price IS NULL) OR (labor_unit_price >= (0)::numeric))),
    CONSTRAINT service_jobs_priority_check CHECK ((priority = ANY (ARRAY['low'::text, 'normal'::text, 'high'::text, 'urgent'::text]))),
    CONSTRAINT service_jobs_required_qualification_type_ids_check CHECK (((COALESCE(array_ndims(required_qualification_type_ids), 1) = 1) AND (COALESCE(array_length(required_qualification_type_ids, 1), 0) <= 100))),
    CONSTRAINT service_jobs_revision_check CHECK ((revision > 0)),
    CONSTRAINT service_jobs_status_check CHECK ((status = ANY (ARRAY['open'::text, 'completed'::text, 'cancelled'::text]))),
    CONSTRAINT service_jobs_title_check CHECK (((length(btrim(title)) >= 1) AND (length(btrim(title)) <= 200)))
);

