    CONSTRAINT service_quotes_decision CHECK ((((status = ANY (ARRAY['accepted'::text, 'declined'::text])) = ((decided_at IS NOT NULL) AND (decided_name IS NOT NULL))) AND ((status = 'accepted'::text) = ((accepted_total IS NOT NULL) AND (deposit_due IS NOT NULL))) AND ((status = 'draft'::text) OR ((sent_at IS NOT NULL) AND (signature_request_id IS NOT NULL))))),
    CONSTRAINT service_quotes_deposit CHECK ((((deposit_basis = 'none'::text) = (deposit_value = (0)::numeric)) AND ((deposit_basis <> 'percent'::text) OR (deposit_value <= (100)::numeric)))),
    CONSTRAINT service_quotes_deposit_basis_check CHECK ((deposit_basis = ANY (ARRAY['none'::text, 'percent'::text, 'amount'::text]))),
    CONSTRAINT service_quotes_deposit_value_check CHECK ((deposit_value >= (0)::numeric)),
    CONSTRAINT service_quotes_revision_check CHECK ((revision > 0)),
    CONSTRAINT service_quotes_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'sent'::text, 'accepted'::text, 'declined'::text])))
);

