    CONSTRAINT service_requests_status_check CHECK ((status = ANY (ARRAY['new'::text, 'assessment_scheduled'::text, 'assessed'::text, 'quoted'::text, 'converted'::text, 'declined'::text, 'cancelled'::text]))),
