--
-- Name: service_visits; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.service_visits (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    subsidiary_id uuid NOT NULL,
    kind text NOT NULL,
    request_id uuid,
    job_id uuid,
    sequence smallint NOT NULL,
    agreement_id uuid,
    agreement_version_id uuid,
    occurs_on date,
    status text NOT NULL,
    cancel_kind text,
    priority text NOT NULL,
    required_qualification_type_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    estimated_minutes smallint NOT NULL,
    preferred_on date,
    window_starts_at timestamp with time zone,
    window_ends_at timestamp with time zone,
    sla_due_at timestamp with time zone,
    instructions text,
    work_notes text,
    outcome_reason text,
    dispatched_at timestamp with time zone,
    en_route_at timestamp with time zone,
    arrived_at timestamp with time zone,
    completed_at timestamp with time zone,
    completed_by uuid,
    review_status text,
    review_flow_run_id uuid,
    review_decided_by uuid,
    review_decided_at timestamp with time zone,
    review_reason text,
    revision integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT service_visits_cancel CHECK ((((status = 'cancelled'::text) = (cancel_kind IS NOT NULL)) AND ((cancel_kind IS NULL) OR (outcome_reason IS NOT NULL)) AND ((cancel_kind IS DISTINCT FROM 'skipped'::text) OR (agreement_id IS NOT NULL)) AND ((cancel_kind IS DISTINCT FROM 'superseded'::text) OR (agreement_id IS NOT NULL)))),
    CONSTRAINT service_visits_cancel_kind_check CHECK ((cancel_kind = ANY (ARRAY['cancelled'::text, 'skipped'::text, 'superseded'::text]))),
    CONSTRAINT service_visits_completion CHECK ((((status = 'completed'::text) = ((completed_at IS NOT NULL) AND (completed_by IS NOT NULL) AND (work_notes IS NOT NULL) AND (length(btrim(work_notes)) > 0))) AND ((status <> 'unable_to_complete'::text) OR (outcome_reason IS NOT NULL)) AND ((review_status IS NULL) = ((status <> 'completed'::text) AND (review_decided_at IS NULL))) AND (((review_status = ANY (ARRAY['approved'::text, 'rejected'::text])) AND (review_decided_by IS NOT NULL)) = ((review_decided_at IS NOT NULL) AND (review_reason IS NOT NULL))))),
    CONSTRAINT service_visits_estimated_minutes_check CHECK (((estimated_minutes >= 5) AND (estimated_minutes <= 1440))),
    CONSTRAINT service_visits_instructions_check CHECK (((instructions IS NULL) OR (length(instructions) <= 4000))),
    CONSTRAINT service_visits_kind_check CHECK ((kind = ANY (ARRAY['assessment'::text, 'service'::text]))),
    CONSTRAINT service_visits_occurrence CHECK ((((agreement_id IS NULL) = (agreement_version_id IS NULL)) AND ((agreement_id IS NULL) = (occurs_on IS NULL)) AND ((agreement_id IS NULL) OR (kind = 'service'::text)))),
    CONSTRAINT service_visits_outcome_reason_check CHECK (((outcome_reason IS NULL) OR ((length(btrim(outcome_reason)) >= 1) AND (length(btrim(outcome_reason)) <= 2000)))),
    CONSTRAINT service_visits_parent CHECK ((((kind = 'assessment'::text) AND (request_id IS NOT NULL) AND (job_id IS NULL)) OR ((kind = 'service'::text) AND (job_id IS NOT NULL) AND (request_id IS NULL)))),
    CONSTRAINT service_visits_priority_check CHECK ((priority = ANY (ARRAY['low'::text, 'normal'::text, 'high'::text, 'urgent'::text]))),
    CONSTRAINT service_visits_required_qualification_type_ids_check CHECK (((COALESCE(array_ndims(required_qualification_type_ids), 1) = 1) AND (COALESCE(array_length(required_qualification_type_ids, 1), 0) <= 100))),
    CONSTRAINT service_visits_review_reason_check CHECK (((review_reason IS NULL) OR ((length(btrim(review_reason)) >= 1) AND (length(btrim(review_reason)) <= 2000)))),
    CONSTRAINT service_visits_review_status_check CHECK ((review_status = ANY (ARRAY['not_required'::text, 'pending'::text, 'approved'::text, 'rejected'::text]))),
    CONSTRAINT service_visits_revision_check CHECK ((revision > 0)),
    CONSTRAINT service_visits_sequence_check CHECK (((sequence >= 1) AND (sequence <= 9999))),
    CONSTRAINT service_visits_status_check CHECK ((status = ANY (ARRAY['unscheduled'::text, 'scheduled'::text, 'dispatched'::text, 'en_route'::text, 'on_site'::text, 'completed'::text, 'unable_to_complete'::text, 'cancelled'::text]))),
