    CONSTRAINT subscriptions_period_valid CHECK (((start_on <= next_bill_on) AND ((current_period_start IS NULL) OR ((current_period_start >= start_on) AND (current_period_start <= next_bill_on))))),
    CONSTRAINT subscriptions_pricing_valid CHECK (((quantity > (0)::numeric) AND ((price_override IS NULL) OR (price_override >= (0)::numeric)))),
    CONSTRAINT subscriptions_status CHECK ((status = ANY (ARRAY['active'::text, 'paused'::text, 'suspended'::text, 'canceled'::text])))
);

