    ownership_percent numeric(19,10) NOT NULL,
    method text DEFAULT 'full'::text NOT NULL,
    acquisition_date date NOT NULL,
    acquisition_cost numeric(19,4) DEFAULT 0 NOT NULL,
    fair_value_net_assets numeric(19,4) DEFAULT 0 NOT NULL,
    acquisition_rate numeric(19,10) DEFAULT 1 NOT NULL,
    nci_measurement text DEFAULT 'proportionate'::text NOT NULL,
    nci_fair_value numeric(19,4),
    investment_account_id uuid NOT NULL,
    equity_income_account_id uuid NOT NULL,
    distribution_account_id uuid,
    distribution_income_account_id uuid,
    nci_equity_account_id uuid,
    nci_income_account_id uuid,
    goodwill_account_id uuid,
    fair_value_adjustment_account_id uuid,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    last_change_id uuid,
    CONSTRAINT subsidiary_ownership_acquisition CHECK ((acquisition_date <= effective_from)),
    CONSTRAINT subsidiary_ownership_dates CHECK (((effective_to IS NULL) OR (effective_to >= effective_from))),
    CONSTRAINT subsidiary_ownership_distinct CHECK ((parent_subsidiary_id <> subsidiary_id)),
    CONSTRAINT subsidiary_ownership_method CHECK ((method = ANY (ARRAY['full'::text, 'proportionate'::text, 'equity'::text]))),
    CONSTRAINT subsidiary_ownership_nci_fair_value CHECK (((nci_measurement <> 'fair_value'::text) OR (nci_fair_value IS NOT NULL))),
    CONSTRAINT subsidiary_ownership_nci_method CHECK ((nci_measurement = ANY (ARRAY['proportionate'::text, 'fair_value'::text]))),
    CONSTRAINT subsidiary_ownership_percent CHECK (((ownership_percent > (0)::numeric) AND (ownership_percent <= (100)::numeric))),
    CONSTRAINT subsidiary_ownership_positive_values CHECK (((acquisition_cost >= (0)::numeric) AND (fair_value_net_assets >= (0)::numeric) AND (acquisition_rate > (0)::numeric) AND ((nci_fair_value IS NULL) OR (nci_fair_value >= (0)::numeric))))
);

