--

CREATE TABLE public.tax_codes (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    country text,
    region text,
    applies_to text DEFAULT 'both'::text NOT NULL,
    collected_account_id uuid,
    paid_account_id uuid,
    recoverable_percent numeric(19,4) DEFAULT '100'::numeric NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    custom jsonb DEFAULT '{}'::jsonb NOT NULL,
    jurisdiction_id uuid,
    calculation_type text DEFAULT 'standard'::text NOT NULL,
    withholding_account_id uuid,
    price_includes_tax boolean DEFAULT false NOT NULL,
    compound_on_previous boolean DEFAULT false NOT NULL,
    rounding_scale integer DEFAULT 2 NOT NULL,
    einvoice_effective_from date,
    einvoice_category text,
    einvoice_exemption_reason_code text,
    einvoice_exemption_reason text,
    CONSTRAINT tax_codes_calculation_type_check CHECK ((calculation_type = ANY (ARRAY['standard'::text, 'withholding'::text, 'reverse_charge'::text]))),
    CONSTRAINT tax_codes_einvoice_category_check CHECK ((einvoice_category = ANY (ARRAY['S'::text, 'Z'::text, 'E'::text, 'AE'::text, 'K'::text, 'G'::text, 'O'::text, 'L'::text, 'M'::text, 'SR'::text, 'SRCA-S'::text, 'SRCA-C'::text, 'ZR'::text, 'ES33'::text, 'ESN33'::text, 'DS'::text, 'OS'::text, 'NA'::text, 'NG'::text, 'SRRC'::text, 'SROVR-RS'::text, 'SROVR-LVG'::text, 'SRLVG'::text]))),
    CONSTRAINT tax_codes_einvoice_effective_date CHECK (((einvoice_category IS NULL) OR (einvoice_effective_from IS NOT NULL))),
    CONSTRAINT tax_codes_einvoice_exemption_category CHECK ((((einvoice_exemption_reason_code IS NULL) AND (einvoice_exemption_reason IS NULL)) OR (einvoice_category = ANY (ARRAY['E'::text, 'AE'::text, 'K'::text, 'G'::text, 'O'::text, 'ES33'::text, 'ESN33'::text, 'OS'::text, 'NA'::text, 'NG'::text, 'SRRC'::text])))),
    CONSTRAINT tax_codes_einvoice_exemption_reason_check CHECK (((length(btrim(einvoice_exemption_reason)) >= 1) AND (length(btrim(einvoice_exemption_reason)) <= 1000))),
    CONSTRAINT tax_codes_einvoice_exemption_reason_code_check CHECK ((einvoice_exemption_reason_code ~ '^VATEX-[A-Z0-9-]{1,40}$'::text)),
    CONSTRAINT tax_codes_rounding_scale_check CHECK (((rounding_scale >= 0) AND (rounding_scale <= 4)))
);

ALTER TABLE ONLY public.tax_codes FORCE ROW LEVEL SECURITY;


--
-- Name: COLUMN tax_codes.einvoice_category; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tax_codes.einvoice_category IS 'EN 16931 VAT category (UNTDID 5305) an e-invoice states for lines carrying this code; unset codes refuse e-invoicing rather than being guessed.';


--
-- Name: COLUMN tax_codes.einvoice_exemption_reason_code; Type: COMMENT; Schema: public; Owner: -
