    superseded_by uuid,
    CONSTRAINT tax_country_pack_installations_identity_chk CHECK (((pack_code <> ''::text) AND (country ~ '^[A-Z]{2}$'::text) AND (version ~ '^[0-9]{4}\.[0-9]{2}\.[0-9]{2}$'::text) AND (content_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT tax_country_pack_installations_lifecycle_chk CHECK ((((status = 'active'::text) AND (superseded_at IS NULL) AND (superseded_by IS NULL)) OR ((status = 'superseded'::text) AND (superseded_at IS NOT NULL)))),
    CONSTRAINT tax_country_pack_installations_manifest_chk CHECK (((jsonb_typeof(manifest) = 'object'::text) AND ((manifest ->> 'code'::text) = pack_code) AND ((manifest ->> 'country'::text) = country) AND ((manifest ->> 'version'::text) = version))),
    CONSTRAINT tax_country_pack_installations_status_chk CHECK ((status = ANY (ARRAY['active'::text, 'superseded'::text])))
);

