    submission_channel,
    boxes,
    adjustments,
    snapshot_hash,
    filing_reference,
    filed_at,
    created_at,
    created_by,
    updated_at,
    updated_by,
    functional_currency,
    presentation_currency,
    translation,
    subsidiary_ids,
    registration_id,
    registration_number,
    snapshot_version
   FROM public.tax_filings
  WHERE (org_id = public.openbooks_query_org_id());


