--
-- Name: time_entries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.time_entries (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    employee_party_id uuid NOT NULL,
    worked_on date NOT NULL,
    hours numeric(19,4) NOT NULL,
    time_type_id uuid,
    item_id uuid,
    project_id uuid,
    project_task_id uuid,
    department_id uuid,
    memo text,
    memo_is_private boolean DEFAULT false NOT NULL,
    is_billable boolean DEFAULT false NOT NULL,
    cost_rate numeric(19,4),
    bill_rate numeric(19,4),
    status text DEFAULT 'draft'::text NOT NULL,
    approved_by uuid,
    approved_at timestamp with time zone,
    cost_journal_entry_id uuid,
    invoiced_by_line_id uuid,
    payroll_batch_ref text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    custom jsonb DEFAULT '{}'::jsonb NOT NULL,
    overhead_journal_entry_id uuid,
    field_ticket_id uuid,
    labor_cost_rate_id uuid,
    wage_rate numeric(19,4),
    wage_currency text,
    wage_fx_rate numeric(19,10),
    cost_rate_currency text,
    cost_rate_subsidiary_id uuid,
    bill_rate_source_rate numeric(19,4),
    bill_rate_source_currency text,
    bill_rate_fx_rate numeric(19,10),
    bill_rate_currency text,
    bill_rate_book_id uuid,
    bill_rate_version_id uuid,
    bill_rate_line_id uuid,
    billing_status text DEFAULT 'unbilled'::text NOT NULL,
    costing_basis text DEFAULT 'actual'::text NOT NULL,
    started_at timestamp with time zone,
    rejection_reason text,
    amends_entry_id uuid,
    equipment_id uuid,
    equipment_hours numeric(19,4),
    crew_batch_line_id uuid,
    clock_pair_id uuid,
    cost_code_ref text,
    work_region text,
    work_subregion text,
    work_region_source text,
    work_region_reason text,
    work_order_id uuid,
    wo_operation_id uuid,
    production_consumed_operation_id uuid,
    corrects_entry_id uuid,
    service_visit_id uuid,
    CONSTRAINT time_correction_kind_chk CHECK (((corrects_entry_id IS NULL) OR ((amends_entry_id IS NULL) AND (hours >= (0)::numeric)))),
    CONSTRAINT time_entries_billing_status_valid CHECK ((billing_status = ANY (ARRAY['unbilled'::text, 'billed'::text]))),
    CONSTRAINT time_entries_costing_basis_check CHECK ((costing_basis = ANY (ARRAY['actual'::text, 'estimated'::text]))),
    CONSTRAINT time_entries_equipment_hours CHECK (((equipment_hours IS NULL) OR (equipment_hours > (0)::numeric))),
    CONSTRAINT time_entries_equipment_pair CHECK ((((equipment_id IS NULL) AND (equipment_hours IS NULL)) OR ((equipment_id IS NOT NULL) AND (equipment_hours IS NOT NULL)))),
    CONSTRAINT time_entries_invoice_link_is_billed CHECK (((invoiced_by_line_id IS NULL) OR (billing_status = 'billed'::text))),
    CONSTRAINT time_entries_one_cost_object_check CHECK ((num_nonnulls(project_id, work_order_id, service_visit_id) <= 1)),
    CONSTRAINT time_entries_operation_requires_work_order_check CHECK (((wo_operation_id IS NULL) OR (work_order_id IS NOT NULL))),
    CONSTRAINT time_entries_work_region_override_reason CHECK (((work_region_source <> 'hr_override'::text) OR (NULLIF(btrim(work_region_reason), ''::text) IS NOT NULL))),
    CONSTRAINT time_entries_work_region_source CHECK ((((work_region IS NULL) AND (work_region_source IS NULL) AND (work_subregion IS NULL)) OR ((work_region IS NOT NULL) AND (work_region_source IS NOT NULL) AND (work_region_source = ANY (ARRAY['project_site'::text, 'payroll_profile'::text, 'hr_override'::text, 'imported_record'::text]))))),
    CONSTRAINT time_production_consumed_target_chk CHECK (((production_consumed_operation_id IS NULL) OR ((work_order_id IS NOT NULL) AND (wo_operation_id IS NOT NULL) AND (wo_operation_id = production_consumed_operation_id) AND (status = 'approved'::text))))
);

ALTER TABLE ONLY public.time_entries FORCE ROW LEVEL SECURITY;


--
-- Name: COLUMN time_entries.work_region; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.time_entries.work_region IS 'Jurisdiction of service. New entries default from project site jurisdiction, then employee payroll profile; HR corrections require a reason and are audited. Approved service dates feed payroll day counts.';


--
-- Name: COLUMN time_entries.service_visit_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.time_entries.service_visit_id IS 'The service visit this labor was worked on, recorded when the technician completes the visit. Exclusive with a project or a work order.';


--
-- Name: time_entries; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.time_entries WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    employee_party_id,
    worked_on,
    hours,
    time_type_id,
    item_id,
    project_id,
    project_task_id,
    department_id,
        CASE
            WHEN memo_is_private THEN NULL::text
            ELSE memo
        END AS memo,
    memo_is_private,
    is_billable,
    cost_rate,
    bill_rate,
    status,
    approved_by,
    approved_at,
    cost_journal_entry_id,
    invoiced_by_line_id,
    payroll_batch_ref,
    created_at,
    created_by,
    updated_at,
    updated_by,
    custom,
    overhead_journal_entry_id,
    field_ticket_id,
    labor_cost_rate_id,
    wage_rate,
    wage_currency,
    wage_fx_rate,
    cost_rate_currency,
    cost_rate_subsidiary_id,
    bill_rate_source_rate,
    bill_rate_source_currency,
    bill_rate_fx_rate,
    bill_rate_currency,
    bill_rate_book_id,
    bill_rate_version_id,
    bill_rate_line_id,
    billing_status,
    costing_basis,
    started_at,
    rejection_reason,
    amends_entry_id
   FROM public.time_entries
  WHERE (org_id = public.openbooks_query_org_id());


