--
-- Name: upgrade_legacy_provenance; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.upgrade_legacy_provenance (
    org_id uuid NOT NULL,
    migration text NOT NULL,
    table_name text NOT NULL,
    row_id uuid NOT NULL,
    note text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT upgrade_legacy_provenance_migration_present CHECK ((char_length(btrim(migration)) > 0)),
    CONSTRAINT upgrade_legacy_provenance_note_present CHECK ((char_length(btrim(note)) > 0)),
    CONSTRAINT upgrade_legacy_provenance_table_present CHECK ((char_length(btrim(table_name)) > 0))
);

ALTER TABLE ONLY public.upgrade_legacy_provenance FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE upgrade_legacy_provenance; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.upgrade_legacy_provenance IS 'Shared registry of rows whose pre-upgrade history was backfilled, not recorded. Readers refuse or label by (org, migration, table, row) membership; notes are human evidence, never read keys.';


--
-- Name: COLUMN upgrade_legacy_provenance.migration; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.upgrade_legacy_provenance.migration IS 'The migration whose backfill introduced the uncertainty (e.g. 0297_recognition_rule_versions). Part of the read key.';


--
-- Name: COLUMN upgrade_legacy_provenance.table_name; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.upgrade_legacy_provenance.table_name IS 'Subject table of the legacy row (e.g. recognition_rules). No row FK by design: one registry points at many tables; integrity comes from the upgrade backfill that recorded the row.';


--
-- Name: COLUMN upgrade_legacy_provenance.note; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.upgrade_legacy_provenance.note IS 'Why this row is legacy and what it means. Matched verbatim by release-lane assertions; readers must not key off it.';


--
-- Name: upgrade_legacy_provenance; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.upgrade_legacy_provenance WITH (security_barrier='true') AS
 SELECT org_id,
    migration,
    table_name,
    row_id,
    note,
    created_at
   FROM public.upgrade_legacy_provenance
  WHERE (org_id = public.openbooks_query_org_id());


