-- Name: withholding_deductions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.withholding_deductions (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    subsidiary_id uuid NOT NULL,
    enrollment_id uuid NOT NULL,
    standing_id uuid,
    payee_name text NOT NULL,
    payee_reference text,
    verification_reference text,
    scheme_code text NOT NULL,
    party_id uuid NOT NULL,
    payment_document_id uuid NOT NULL,
    bill_document_id uuid NOT NULL,
    bill_open_line_id uuid NOT NULL,
    journal_entry_id uuid NOT NULL,
    payment_date date NOT NULL,
    period_start date NOT NULL,
    period_end date NOT NULL,
    currency text NOT NULL,
    band_code text NOT NULL,
    rate_percent numeric(9,4) NOT NULL,
    downgraded_from text,
    paid_amount numeric(19,4) NOT NULL,
    net_amount numeric(19,4) NOT NULL,
    materials_amount numeric(19,4) NOT NULL,
    vat_amount numeric(19,4) NOT NULL,
    consideration_amount numeric(19,4) NOT NULL,
    base_amount numeric(19,4) NOT NULL,
    catch_up_base numeric(19,4) DEFAULT 0 NOT NULL,
    deducted_amount numeric(19,4) NOT NULL,
    uncollected_amount numeric(19,4) DEFAULT 0 NOT NULL,
    transaction_currency text,
    transaction_paid_amount numeric(19,4),
    transaction_deducted_amount numeric(19,4),
    reporting_fx_rate numeric(19,10),
    reporting_fx_evidence jsonb,
    below_threshold boolean DEFAULT false NOT NULL,
    authorisation_reference text,
    reasons jsonb DEFAULT '[]'::jsonb NOT NULL,
    status text DEFAULT 'posted'::text NOT NULL,
    voided_at timestamp with time zone,
    voided_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT withholding_deductions_authorisation_reference_check CHECK (((length(btrim(authorisation_reference)) >= 1) AND (length(btrim(authorisation_reference)) <= 100))),
    CONSTRAINT withholding_deductions_check CHECK (((period_end >= period_start) AND ((payment_date >= period_start) AND (payment_date <= period_end)))),
    CONSTRAINT withholding_deductions_check1 CHECK (((status = 'voided'::text) = (voided_at IS NOT NULL))),
    CONSTRAINT withholding_deductions_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT withholding_deductions_deducted_amount_check CHECK ((deducted_amount >= (0)::numeric)),
    CONSTRAINT withholding_deductions_fx_evidence_complete CHECK ((num_nonnulls(transaction_currency, transaction_paid_amount, transaction_deducted_amount, reporting_fx_rate, reporting_fx_evidence) = ANY (ARRAY[0, 5]))),
    CONSTRAINT withholding_deductions_fx_evidence_scope CHECK (((reporting_fx_evidence IS NULL) OR (((jsonb_typeof(reporting_fx_evidence) = 'object'::text) AND ((reporting_fx_evidence ->> 'kind'::text) = 'as-of'::text) AND ((reporting_fx_evidence ->> 'from'::text) = transaction_currency) AND ((reporting_fx_evidence ->> 'to'::text) = currency) AND ((reporting_fx_evidence ->> 'asOf'::text) = (payment_date)::text) AND ((reporting_fx_evidence ->> 'policy'::text) = 'direct-or-inverse-spot'::text) AND ((reporting_fx_evidence ->> 'table'::text) = 'fx_rates'::text) AND ((reporting_fx_evidence ->> 'digest'::text) ~ '^[a-f0-9]{64}$'::text) AND (((reporting_fx_evidence ->> 'rate'::text))::numeric = reporting_fx_rate) AND (jsonb_typeof((reporting_fx_evidence -> 'observations'::text)) = 'array'::text) AND (((reporting_fx_evidence ->> 'sameCurrencyPar'::text))::boolean = (transaction_currency = currency))) IS TRUE))),
    CONSTRAINT withholding_deductions_payee_name_check CHECK (((length(btrim(payee_name)) >= 1) AND (length(btrim(payee_name)) <= 500))),
    CONSTRAINT withholding_deductions_rate_percent_check CHECK (((rate_percent >= (0)::numeric) AND (rate_percent <= (100)::numeric))),
    CONSTRAINT withholding_deductions_reasons_check CHECK ((jsonb_typeof(reasons) = 'array'::text)),
    CONSTRAINT withholding_deductions_scheme_code_check CHECK ((scheme_code ~ '^[A-Z]{2}_[A-Z0-9_]{1,40}$'::text)),
    CONSTRAINT withholding_deductions_status_check CHECK ((status = ANY (ARRAY['posted'::text, 'voided'::text]))),
    CONSTRAINT withholding_deductions_transaction_amounts CHECK (((transaction_paid_amount >= (0)::numeric) AND (transaction_deducted_amount >= (0)::numeric) AND (transaction_deducted_amount <= transaction_paid_amount) AND (reporting_fx_rate > (0)::numeric))),
    CONSTRAINT withholding_deductions_transaction_currency_check CHECK ((transaction_currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT withholding_deductions_uncollected_amount_check CHECK ((uncollected_amount >= (0)::numeric))
);

ALTER TABLE ONLY public.withholding_deductions FORCE ROW LEVEL SECURITY;


