--
-- Name: asset_book_carrying_values; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.asset_book_carrying_values WITH (security_invoker='true') AS
 SELECT a.org_id,
    a.id AS asset_id,
    b.id AS book_id,
        CASE
            WHEN (a.status = ANY (ARRAY['disposed'::text, 'written_off'::text])) THEN (0)::numeric
            ELSE (a.acquisition_cost + COALESCE(x.cost_delta, (0)::numeric))
        END AS cost,
        CASE
            WHEN (a.status = ANY (ARRAY['disposed'::text, 'written_off'::text])) THEN (0)::numeric
            ELSE (a.salvage_value + COALESCE(x.salvage_delta, (0)::numeric))
        END AS salvage,
        CASE
            WHEN (a.status = ANY (ARRAY['disposed'::text, 'written_off'::text])) THEN (0)::numeric
            ELSE (((COALESCE(a.opening_accumulated_depreciation, (0)::numeric) + COALESCE(d.amount, (0)::numeric)) - COALESCE(v.amount, (0)::numeric)) + COALESCE(x.accumulated_delta, (0)::numeric))
        END AS accumulated,
        CASE
            WHEN (a.status = ANY (ARRAY['disposed'::text, 'written_off'::text])) THEN (0)::numeric
            ELSE (((((a.acquisition_cost + COALESCE(x.cost_delta, (0)::numeric)) - COALESCE(a.opening_accumulated_depreciation, (0)::numeric)) - COALESCE(d.amount, (0)::numeric)) + COALESCE(v.amount, (0)::numeric)) - COALESCE(x.accumulated_delta, (0)::numeric))
        END AS carrying_value,
    x.cutoff
   FROM ((((public.fixed_assets a
     JOIN public.accounting_books b ON ((b.org_id = a.org_id)))
     LEFT JOIN LATERAL ( SELECT sum(x_1.cost_delta) AS cost_delta,
            sum(x_1.accumulated_delta) AS accumulated_delta,
            sum(x_1.salvage_delta) AS salvage_delta,
            max(x_1.effective_on) AS cutoff
           FROM public.asset_basis_changes x_1
          WHERE ((x_1.org_id = a.org_id) AND (x_1.asset_id = a.id) AND (x_1.book_id = b.id))) x ON (true))
     LEFT JOIN LATERAL ( SELECT sum(l.posted_amount) AS amount
           FROM (public.depreciation_schedules s
             JOIN public.depreciation_schedule_lines l ON (((l.schedule_id = s.id) AND (l.org_id = s.org_id))))
          WHERE ((s.org_id = a.org_id) AND (s.asset_id = a.id) AND (s.book_id = b.id))) d ON (true))
     LEFT JOIN LATERAL ( SELECT sum(v_1.amount) AS amount
           FROM (public.asset_events v_1
             JOIN public.journal_entries e ON (((e.id = v_1.journal_entry_id) AND (e.org_id = v_1.org_id))))
          WHERE ((v_1.org_id = a.org_id) AND (v_1.asset_id = a.id) AND (e.book_id = b.id) AND (e.status = 'posted'::text) AND (v_1.kind = ANY (ARRAY['impaired'::text, 'revalued'::text])) AND (NOT (EXISTS ( SELECT 1
                   FROM public.asset_events r
                  WHERE ((r.org_id = v_1.org_id) AND (r.reverses_event_id = v_1.id))))))) v ON (true));


