    CONSTRAINT employment_changes_snapshot CHECK ((jsonb_typeof(prior_snapshot) = 'object'::text)),
    CONSTRAINT employment_changes_verb CHECK ((verb = ANY (ARRAY['apply'::text, 'cancel'::text, 'rescind'::text, 'correct'::text]))),
    CONSTRAINT employment_changes_verb_links CHECK ((((verb = 'rescind'::text) AND (reverses_change_id IS NOT NULL) AND (corrected_change_id IS NULL)) OR ((verb = 'correct'::text) AND (corrected_change_id IS NOT NULL) AND (reverses_change_id IS NULL)) OR ((verb = ANY (ARRAY['apply'::text, 'cancel'::text])) AND (reverses_change_id IS NULL) AND (corrected_change_id IS NULL))))
);

