    CONSTRAINT expense_receipt_captures_evidence_check CHECK ((jsonb_typeof(evidence) = 'array'::text)),
    CONSTRAINT expense_receipt_captures_failed CHECK (((status <> 'failed'::text) OR (char_length(btrim(COALESCE(last_error, ''::text))) > 0))),
    CONSTRAINT expense_receipt_captures_issues_check CHECK ((jsonb_typeof(issues) = 'array'::text)),
    CONSTRAINT expense_receipt_captures_original_filename_check CHECK (((char_length(btrim(original_filename)) >= 1) AND (char_length(btrim(original_filename)) <= 240))),
    CONSTRAINT expense_receipt_captures_overall_confidence_check CHECK (((overall_confidence >= (0)::numeric) AND (overall_confidence <= (1)::numeric))),
    CONSTRAINT expense_receipt_captures_provider_check CHECK ((provider = ANY (ARRAY['azure_document_intelligence'::text, 'llm_vision'::text]))),
    CONSTRAINT expense_receipt_captures_read CHECK (((status <> ALL (ARRAY['extracted'::text, 'confirmed'::text])) OR ((normalized IS NOT NULL) AND (draft IS NOT NULL)))),
    CONSTRAINT expense_receipt_captures_status_check CHECK ((status = ANY (ARRAY['extracting'::text, 'extracted'::text, 'failed'::text, 'confirmed'::text, 'discarded'::text])))
);

