--
-- Name: hrm_benefit_programs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hrm_benefit_programs (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    family text NOT NULL,
    description text,
    legal_entity_id uuid,
    currency character(3) NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    effective_from date NOT NULL,
    effective_to date,
    pay_component_id uuid,
    delivery_method text DEFAULT 'payroll'::text NOT NULL,
    valuation text DEFAULT 'fixed'::text NOT NULL,
    metric text,
    metric_scope text,
    allocation text DEFAULT 'equal'::text NOT NULL,
    percent_rate numeric(19,4),
    fixed_amount numeric(19,4),
    cap_amount numeric(19,4),
    budget_amount numeric(19,4),
    threshold_amount numeric(19,4),
    frequency text DEFAULT 'manual'::text NOT NULL,
    period_basis text,
    payment_delay_days integer DEFAULT 0 NOT NULL,
    revision integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    approval_mode text DEFAULT 'none'::text NOT NULL,
    unassigned_time text DEFAULT 'refuse'::text NOT NULL,
    loss_percent_rate numeric(9,4),
    project_profit_cap numeric(19,4),
    project_loss_cap numeric(19,4),
    pool_rounding text DEFAULT 'share'::text NOT NULL,
    include_open_commitments boolean DEFAULT false NOT NULL,
    hour_classifications text[],
    eligibility text DEFAULT 'members'::text NOT NULL,
    CONSTRAINT hrm_benefit_programs_allocation CHECK ((allocation = ANY (ARRAY['equal'::text, 'hours'::text, 'role'::text, 'responsibility'::text]))),
    CONSTRAINT hrm_benefit_programs_amounts CHECK ((((percent_rate IS NULL) OR (percent_rate >= (0)::numeric)) AND ((fixed_amount IS NULL) OR (fixed_amount >= (0)::numeric)) AND ((cap_amount IS NULL) OR (cap_amount >= (0)::numeric)) AND ((budget_amount IS NULL) OR (budget_amount >= (0)::numeric)) AND ((threshold_amount IS NULL) OR (threshold_amount >= (0)::numeric)))),
    CONSTRAINT hrm_benefit_programs_approval_mode CHECK ((approval_mode = ANY (ARRAY['none'::text, 'flows'::text]))),
    CONSTRAINT hrm_benefit_programs_code CHECK ((char_length(btrim(code)) > 0)),
    CONSTRAINT hrm_benefit_programs_currency CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT hrm_benefit_programs_delay CHECK ((payment_delay_days >= 0)),
    CONSTRAINT hrm_benefit_programs_delivery CHECK ((delivery_method = ANY (ARRAY['payroll'::text, 'external'::text]))),
    CONSTRAINT hrm_benefit_programs_eligibility CHECK ((eligibility = ANY (ARRAY['members'::text, 'all_employees'::text]))),
    CONSTRAINT hrm_benefit_programs_external_component CHECK (((delivery_method <> 'external'::text) OR (pay_component_id IS NULL) OR (family = ANY (ARRAY['reward'::text, 'allowance'::text, 'custom'::text])))),
    CONSTRAINT hrm_benefit_programs_family CHECK ((family = ANY (ARRAY['reward'::text, 'allowance'::text, 'incentive'::text, 'custom'::text]))),
    CONSTRAINT hrm_benefit_programs_finite_time CHECK (((effective_from >= '0001-01-01'::date) AND (effective_from <= '9999-12-31'::date) AND ((effective_to IS NULL) OR ((effective_to >= '0001-01-01'::date) AND (effective_to <= '9999-12-31'::date))))),
    CONSTRAINT hrm_benefit_programs_frequency CHECK ((frequency = ANY (ARRAY['monthly'::text, 'quarterly'::text, 'annual'::text, 'project_complete'::text, 'manual'::text]))),
    CONSTRAINT hrm_benefit_programs_hour_classifications CHECK (((hour_classifications IS NULL) OR ((cardinality(hour_classifications) > 0) AND (hour_classifications <@ ARRAY['regular'::text, 'overtime'::text, 'double_time'::text, 'other'::text])))),
    CONSTRAINT hrm_benefit_programs_incentive_metric CHECK (((family <> 'incentive'::text) OR (metric IS NOT NULL))),
    CONSTRAINT hrm_benefit_programs_metric CHECK (((metric IS NULL) OR (metric = ANY (ARRAY['revenue'::text, 'gross_profit'::text, 'net_profit'::text, 'approved_hours'::text, 'transactions'::text, 'project_margin'::text])))),
    CONSTRAINT hrm_benefit_programs_name CHECK ((char_length(btrim(name)) > 0)),
    CONSTRAINT hrm_benefit_programs_period_basis CHECK (((period_basis IS NULL) OR (period_basis = ANY (ARRAY['calendar'::text, 'fiscal'::text])))),
    CONSTRAINT hrm_benefit_programs_period_basis_required CHECK (((frequency <> ALL (ARRAY['quarterly'::text, 'annual'::text])) OR (period_basis IS NOT NULL))),
    CONSTRAINT hrm_benefit_programs_project_margin_terms CHECK ((((loss_percent_rate IS NULL) OR ((loss_percent_rate >= (0)::numeric) AND (loss_percent_rate <= (100)::numeric))) AND ((project_profit_cap IS NULL) OR (project_profit_cap >= (0)::numeric)) AND ((project_loss_cap IS NULL) OR (project_loss_cap >= (0)::numeric)) AND (pool_rounding = ANY (ARRAY['share'::text, 'pool'::text])))),
    CONSTRAINT hrm_benefit_programs_revision CHECK ((revision >= 1)),
    CONSTRAINT hrm_benefit_programs_scope CHECK (((metric_scope IS NULL) OR (metric_scope = ANY (ARRAY['company'::text, 'department'::text, 'project'::text])))),
    CONSTRAINT hrm_benefit_programs_status CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'closed'::text]))),
    CONSTRAINT hrm_benefit_programs_transaction_shape CHECK (((COALESCE((metric = 'transactions'::text), false) AND (valuation = ANY (ARRAY['percent'::text, 'per_unit'::text])) AND (allocation = 'responsibility'::text) AND (metric_scope = 'company'::text) AND (family = ANY (ARRAY['incentive'::text, 'custom'::text])) AND (delivery_method = 'payroll'::text) AND (cap_amount IS NULL) AND (threshold_amount IS NULL) AND (budget_amount IS NULL) AND (((valuation = 'percent'::text) AND (percent_rate IS NOT NULL) AND (percent_rate > (0)::numeric)) OR ((valuation = 'per_unit'::text) AND (fixed_amount IS NOT NULL) AND (fixed_amount > (0)::numeric)))) OR (COALESCE((metric = 'project_margin'::text), false) AND (valuation = 'percent'::text) AND (allocation = 'responsibility'::text) AND (metric_scope = 'company'::text) AND (family = 'incentive'::text) AND (delivery_method = 'payroll'::text) AND (cap_amount IS NULL) AND (threshold_amount IS NULL) AND (budget_amount IS NULL) AND (percent_rate IS NOT NULL) AND (percent_rate > (0)::numeric)) OR (((metric IS NULL) OR (metric <> ALL (ARRAY['transactions'::text, 'project_margin'::text]))) AND (valuation <> 'per_unit'::text) AND (allocation <> 'responsibility'::text)) OR (COALESCE((metric = 'approved_hours'::text), false) AND (valuation = 'per_unit'::text) AND (allocation = 'hours'::text) AND (family = 'incentive'::text) AND (delivery_method = 'payroll'::text) AND (percent_rate IS NULL) AND (fixed_amount IS NOT NULL) AND (fixed_amount > (0)::numeric)))),
    CONSTRAINT hrm_benefit_programs_unassigned_time CHECK ((unassigned_time = ANY (ARRAY['refuse'::text, 'exclude'::text]))),
    CONSTRAINT hrm_benefit_programs_valuation CHECK ((valuation = ANY (ARRAY['fixed'::text, 'percent'::text, 'pool'::text, 'per_unit'::text]))),
    CONSTRAINT hrm_benefit_programs_window CHECK (((effective_to IS NULL) OR (effective_to >= effective_from)))
);

