--
-- Name: hrm_employment_change_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hrm_employment_change_requests (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    employment_id uuid NOT NULL,
    request_revision integer DEFAULT 1 NOT NULL,
    expected_employment_revision integer NOT NULL,
    payload jsonb NOT NULL,
    payload_digest text NOT NULL,
    payload_schema_version text NOT NULL,
    reason text,
    status text DEFAULT 'draft'::text NOT NULL,
    submitted_by uuid,
    submitted_at timestamp with time zone,
    flow_run_id uuid,
    decision_snapshot jsonb,
    applied_at timestamp with time zone,
    applied_by uuid,
    applied_employment_revision integer,
    applied_employment_change_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    action text,
    reason_code text,
    CONSTRAINT hrm_employment_change_requests_applied_paired CHECK ((((status = 'applied'::text) = (applied_at IS NOT NULL)) AND ((status = 'applied'::text) = (applied_by IS NOT NULL)) AND ((status = 'applied'::text) = (applied_employment_revision IS NOT NULL)) AND ((status = 'applied'::text) = (applied_employment_change_id IS NOT NULL)))),
    CONSTRAINT hrm_employment_change_requests_payload_shape CHECK (((jsonb_typeof(payload) = 'object'::text) AND (payload_digest ~ '^[0-9a-f]{64}$'::text) AND (length(btrim(payload_schema_version)) > 0))),
    CONSTRAINT hrm_employment_change_requests_reason_on_submit CHECK (((submitted_at IS NULL) OR ((reason IS NOT NULL) AND (length(btrim(reason)) > 0)))),
    CONSTRAINT hrm_employment_change_requests_revision_floor CHECK (((request_revision >= 1) AND (expected_employment_revision >= 1))),
    CONSTRAINT hrm_employment_change_requests_snapshot_binding CHECK (((decision_snapshot IS NULL) OR ((jsonb_typeof(decision_snapshot) = 'object'::text) AND (decision_snapshot ? 'gates'::text) AND (jsonb_typeof((decision_snapshot -> 'gates'::text)) = 'array'::text) AND (decision_snapshot ? 'payload_digest'::text) AND (jsonb_typeof((decision_snapshot -> 'payload_digest'::text)) = 'string'::text) AND ((decision_snapshot ->> 'payload_digest'::text) = payload_digest) AND (decision_snapshot ? 'payload_schema_version'::text) AND (jsonb_typeof((decision_snapshot -> 'payload_schema_version'::text)) = 'string'::text) AND ((decision_snapshot ->> 'payload_schema_version'::text) = payload_schema_version) AND (decision_snapshot ? 'expected_employment_revision'::text) AND (jsonb_typeof((decision_snapshot -> 'expected_employment_revision'::text)) = 'number'::text) AND (((decision_snapshot ->> 'expected_employment_revision'::text))::numeric = (expected_employment_revision)::numeric) AND (((decision_snapshot ? 'flow_run_id'::text) AND (jsonb_typeof((decision_snapshot -> 'flow_run_id'::text)) = 'string'::text) AND (flow_run_id IS NOT NULL) AND ((decision_snapshot ->> 'flow_run_id'::text) = (flow_run_id)::text)) OR ((COALESCE((payload ->> 'kind'::text), ''::text) = ANY (ARRAY['hire'::text, 'status_change'::text, 'assignment_change'::text, 'termination'::text, 'position_assignment'::text, 'profile_change'::text, 'bank_change'::text])) AND (COALESCE((decision_snapshot ->> 'mode'::text), ''::text) = 'automatic'::text) AND ((COALESCE(((decision_snapshot -> 'policy'::text) ->> 'flowConfigured'::text), ''::text) = 'false'::text) OR (((decision_snapshot -> 'policy'::text) ->> 'kind'::text) = 'ungated'::text))))))),
    CONSTRAINT hrm_employment_change_requests_snapshot_iff_decided CHECK (((status = ANY (ARRAY['approved'::text, 'rejected'::text, 'applied'::text])) = (decision_snapshot IS NOT NULL))),
    CONSTRAINT hrm_employment_change_requests_status_valid CHECK ((status = ANY (ARRAY['draft'::text, 'pending_approval'::text, 'approved'::text, 'rejected'::text, 'withdrawn'::text, 'applied'::text]))),
    CONSTRAINT hrm_employment_change_requests_submission_paired CHECK (((submitted_at IS NULL) = (submitted_by IS NULL))),
    CONSTRAINT hrm_employment_change_requests_submission_presence CHECK (((status <> ALL (ARRAY['pending_approval'::text, 'approved'::text, 'rejected'::text, 'applied'::text])) OR (submitted_at IS NOT NULL))),
    CONSTRAINT hrm_employment_change_requests_submitted_not_draft CHECK (((submitted_at IS NULL) OR (status <> 'draft'::text)))
);

ALTER TABLE ONLY public.hrm_employment_change_requests FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE hrm_employment_change_requests; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.hrm_employment_change_requests IS 'Governed HRM employment change proposals. One row binds a frozen payload (storage-computed sha256 digest over canonical jsonb text) to the exact worker_employments revision it was written against and to the native Flows run that decides it. Lifecycle draft -> pending_approval -> approved/rejected/withdrawn, approved -> applied; rejected/withdrawn/applied are terminal and revised proposals are new rows, so no approval is ever re-pointed at edited payload. Canonical mutation stays in employment_changes; approval execution stays in flow_runs/flow_gates; application auth stays in the service — applied_by here is evidence only.';


--
-- Name: COLUMN hrm_employment_change_requests.expected_employment_revision; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.hrm_employment_change_requests.expected_employment_revision IS 'Exact worker_employments.revision the proposal was written against (>= 1; reserved identities sit at 1 with no effective version until a governed create applies). The application service refuses to apply when the live revision differs — storage binds the expectation, the service wins the race.';


--
-- Name: COLUMN hrm_employment_change_requests.payload_digest; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.hrm_employment_change_requests.payload_digest IS 'sha256 hex over convert_to(payload::text, UTF8): PostgreSQL jsonb normalized text is the canonical form. Computed by the guard trigger on insert and draft payload edits; callers must not trust a self-computed digest — submit the payload and read this back.';


--
-- Name: COLUMN hrm_employment_change_requests.decision_snapshot; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.hrm_employment_change_requests.decision_snapshot IS 'Immutable decision evidence written atomically with approve/reject: bound digests plus every decided native gate (actual decided_by with delegation principal). Bound keys are CHECK-pinned to the row; the gates themselves stay native — this snapshot duplicates no workflow state.';


