COMMENT ON TABLE public.hrm_interviews IS 'HRM interview sittings: one row per interview with kind, schedule, outcome on completion, and optional scorecard. Completed rows immutable; deletes only on the governed amend path.';


--
-- Name: hrm_job_descriptions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hrm_job_descriptions (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    name text NOT NULL,
    title text NOT NULL,
    employment_kind text,
    compensation_min numeric,
    compensation_max numeric,
    compensation_currency text,
    compensation_basis text,
    description text NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT hrm_job_descriptions_compensation_basis CHECK (((compensation_basis IS NULL) OR (compensation_basis = ANY (ARRAY['hourly'::text, 'annual'::text])))),
    CONSTRAINT hrm_job_descriptions_compensation_complete CHECK ((((compensation_min IS NULL) AND (compensation_max IS NULL) AND (compensation_currency IS NULL) AND (compensation_basis IS NULL)) OR ((compensation_min IS NOT NULL) AND (compensation_max IS NOT NULL) AND (compensation_currency IS NOT NULL) AND (compensation_basis IS NOT NULL)))),
    CONSTRAINT hrm_job_descriptions_compensation_currency CHECK (((compensation_currency IS NULL) OR (compensation_currency ~ '^[A-Z]{3}$'::text))),
    CONSTRAINT hrm_job_descriptions_compensation_range CHECK (((compensation_min IS NULL) OR ((compensation_min >= (0)::numeric) AND (compensation_min <= compensation_max)))),
    CONSTRAINT hrm_job_descriptions_description_not_blank CHECK ((char_length(btrim(description)) > 0)),
    CONSTRAINT hrm_job_descriptions_employment_kind_not_blank CHECK (((employment_kind IS NULL) OR (char_length(btrim(employment_kind)) > 0))),
    CONSTRAINT hrm_job_descriptions_name_not_blank CHECK ((char_length(btrim(name)) > 0)),
    CONSTRAINT hrm_job_descriptions_title_not_blank CHECK ((char_length(btrim(title)) > 0))
);

ALTER TABLE ONLY public.hrm_job_descriptions FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE hrm_job_descriptions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.hrm_job_descriptions IS 'HRM job descriptions: reusable posting content a requisition starts from. Requisitions copy the content at creation; an entry referenced by a requisition is history-pinned, so deactivate it instead of deleting it.';


