--
-- Name: TABLE hrm_job_levels; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.hrm_job_levels IS 'HRM job architecture: one rung per ladder per org code, NULL family = the org-wide ladder. Rank orders the ladder; equal_value_criteria carries the org-declared gender-neutral criteria the EU directive requires.';


--
-- Name: hrm_job_postings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hrm_job_postings (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    requisition_id uuid NOT NULL,
    board_key text NOT NULL,
    external_ref text,
