    published_at timestamp with time zone,
    closed_at timestamp with time zone,
    error_message text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT hrm_job_postings_board_not_blank CHECK ((char_length(btrim(board_key)) > 0)),
    CONSTRAINT hrm_job_postings_closed_paired CHECK (((status = 'closed'::text) = (closed_at IS NOT NULL))),
    CONSTRAINT hrm_job_postings_error_paired CHECK (((status = 'error'::text) = ((error_message IS NOT NULL) AND (char_length(btrim(error_message)) > 0)))),
    CONSTRAINT hrm_job_postings_finite_time CHECK ((((published_at IS NULL) OR ((published_at >= '0001-01-01 00:00:00+00'::timestamp with time zone) AND (published_at < '10000-01-01 00:00:00+00'::timestamp with time zone))) AND ((closed_at IS NULL) OR ((closed_at >= '0001-01-01 00:00:00+00'::timestamp with time zone) AND (closed_at < '10000-01-01 00:00:00+00'::timestamp with time zone))))),
    CONSTRAINT hrm_job_postings_published_paired CHECK (((status = ANY (ARRAY['published'::text, 'paused'::text, 'closed'::text])) = (published_at IS NOT NULL))),
    CONSTRAINT hrm_job_postings_status CHECK ((status = ANY (ARRAY['draft'::text, 'published'::text, 'paused'::text, 'closed'::text, 'error'::text])))
);

ALTER TABLE ONLY public.hrm_job_postings FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE hrm_job_postings; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.hrm_job_postings IS 'HRM job-board postings: one posting per (requisition, board_key). board_key is an org-declared connector key; the generic layer ships internal and feed. A posting with applicants or events is history-pinned.';


