    CONSTRAINT hrm_one_on_one_items_position CHECK (("position" >= 0)),
    CONSTRAINT hrm_one_on_one_items_status CHECK ((status = ANY (ARRAY['open'::text, 'done'::text, 'carried'::text]))),
