--
-- Name: hrm_one_on_ones; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hrm_one_on_ones (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    manager_employment_id uuid NOT NULL,
    report_employment_id uuid NOT NULL,
    scheduled_at timestamp with time zone NOT NULL,
    held_at timestamp with time zone,
    status text DEFAULT 'scheduled'::text NOT NULL,
    skip_reason text,
    recurrence jsonb,
    series_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT hrm_one_on_ones_finite_time CHECK (((scheduled_at >= '0001-01-01 00:00:00+00'::timestamp with time zone) AND (scheduled_at <= '9999-12-31 23:59:59+00'::timestamp with time zone) AND ((held_at IS NULL) OR ((held_at >= '0001-01-01 00:00:00+00'::timestamp with time zone) AND (held_at <= '9999-12-31 23:59:59+00'::timestamp with time zone))))),
    CONSTRAINT hrm_one_on_ones_held_paired CHECK (((status = 'held'::text) = (held_at IS NOT NULL))),
    CONSTRAINT hrm_one_on_ones_parties_differ CHECK ((manager_employment_id <> report_employment_id)),
    CONSTRAINT hrm_one_on_ones_recurrence_shape CHECK (((recurrence IS NULL) OR ((jsonb_typeof(recurrence) = 'object'::text) AND (recurrence ? 'every_weeks'::text) AND (recurrence ? 'weekday'::text) AND (jsonb_typeof((recurrence -> 'every_weeks'::text)) = 'number'::text) AND (((recurrence ->> 'every_weeks'::text))::numeric >= (1)::numeric) AND (((recurrence ->> 'every_weeks'::text))::numeric <= (12)::numeric) AND (jsonb_typeof((recurrence -> 'weekday'::text)) = 'number'::text) AND (((recurrence ->> 'weekday'::text))::numeric >= (0)::numeric) AND (((recurrence ->> 'weekday'::text))::numeric <= (6)::numeric)))),
    CONSTRAINT hrm_one_on_ones_skip_reason CHECK (((status <> 'skipped'::text) OR ((skip_reason IS NOT NULL) AND (char_length(btrim(skip_reason)) > 0)))),
    CONSTRAINT hrm_one_on_ones_status CHECK ((status = ANY (ARRAY['scheduled'::text, 'held'::text, 'skipped'::text, 'cancelled'::text])))
);

ALTER TABLE ONLY public.hrm_one_on_ones FORCE ROW LEVEL SECURITY;


