    updated_by uuid,
    CONSTRAINT hrm_pay_bands_basis CHECK ((basis = ANY (ARRAY['annual'::text, 'hourly'::text]))),
    CONSTRAINT hrm_pay_bands_ordered CHECK (((min <= max) AND ((target IS NULL) OR ((min <= target) AND (target <= max))))),
    CONSTRAINT hrm_pay_bands_positive CHECK (((min > (0)::numeric) AND (max > (0)::numeric) AND ((target IS NULL) OR (target > (0)::numeric)))),
    CONSTRAINT hrm_pay_bands_window CHECK (((effective_from >= '0001-01-01'::date) AND (effective_from <= '9999-12-31'::date) AND ((effective_to IS NULL) OR ((effective_to >= '0001-01-01'::date) AND (effective_to <= '9999-12-31'::date) AND (effective_to >= effective_from)))))
);

ALTER TABLE ONLY public.hrm_pay_bands FORCE ROW LEVEL SECURITY;


