    CONSTRAINT hrm_per_diem_entries_amount CHECK ((amount >= (0)::numeric)),
    CONSTRAINT hrm_per_diem_entries_status CHECK ((status = ANY (ARRAY['computed'::text, 'approved'::text, 'voided'::text, 'consumed'::text]))),
    CONSTRAINT hrm_per_diem_entries_void_reason CHECK ((((status = 'voided'::text) AND (void_reason IS NOT NULL) AND (char_length(btrim(void_reason)) > 0)) OR (status <> 'voided'::text)))
);

