    CONSTRAINT hrm_per_diem_policies_currency CHECK ((char_length(btrim((currency)::text)) = 3)),
    CONSTRAINT hrm_per_diem_policies_name CHECK ((char_length(btrim(name)) > 0)),
    CONSTRAINT hrm_per_diem_policies_rules_shape CHECK ((jsonb_typeof(rules) = 'object'::text)),
    CONSTRAINT hrm_per_diem_policies_weekly_shape CHECK (((weekly_rule IS NULL) OR (jsonb_typeof(weekly_rule) = 'object'::text))),
    CONSTRAINT hrm_per_diem_policies_window CHECK (((effective_to IS NULL) OR (effective_to >= effective_from)))
);

ALTER TABLE ONLY public.hrm_per_diem_policies FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE hrm_per_diem_policies; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.hrm_per_diem_policies IS 'HRM per-diem policies: org-declared computation rules per basis (flat_daily, distance_brackets, hours_threshold). rules shape is validated by the service''s zod schema per basis; taxable is an org declaration the pack interprets. The linked pay component must be kind earning (amounts paid to the worker price as earnings; taxability rides tax_treatment).';


