    CONSTRAINT hrm_pipeline_stages_name CHECK ((char_length(btrim(name)) > 0)),
    CONSTRAINT hrm_pipeline_stages_position CHECK (("position" >= 0)),
    CONSTRAINT hrm_pipeline_stages_terminal CHECK ((is_terminal = (kind = ANY (ARRAY['hired'::text, 'rejected'::text]))))
);

