    evidence_kind text DEFAULT 'none'::text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    done_by uuid,
    done_at timestamp with time zone,
    skip_reason text,
    attachment_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    design jsonb DEFAULT '{}'::jsonb NOT NULL,
    response jsonb,
    approval_status text DEFAULT 'none'::text NOT NULL,
    submitted_by uuid,
    submitted_at timestamp with time zone,
    flow_run_id uuid,
    reminder_sent_on date,
    CONSTRAINT hrm_process_steps_approval_status_check CHECK ((approval_status = ANY (ARRAY['none'::text, 'pending'::text, 'approved'::text, 'rejected'::text]))),
    CONSTRAINT hrm_process_steps_attachment_scope CHECK (((attachment_id IS NULL) OR (evidence_kind = 'attachment'::text))),
    CONSTRAINT hrm_process_steps_done_paired CHECK ((((status = 'done'::text) = (done_at IS NOT NULL)) AND ((status = 'done'::text) = (done_by IS NOT NULL)))),
    CONSTRAINT hrm_process_steps_evidence CHECK ((evidence_kind = ANY (ARRAY['none'::text, 'acknowledgement'::text, 'attachment'::text]))),
    CONSTRAINT hrm_process_steps_finite_time CHECK (((due_on >= '0001-01-01'::date) AND (due_on <= '9999-12-31'::date) AND ((done_at IS NULL) OR ((done_at >= '0001-01-01 00:00:00+00'::timestamp with time zone) AND (done_at < '10000-01-01 00:00:00+00'::timestamp with time zone))))),
    CONSTRAINT hrm_process_steps_owner CHECK ((owner_kind = ANY (ARRAY['manager'::text, 'hr'::text, 'employee'::text, 'named_party'::text]))),
    CONSTRAINT hrm_process_steps_owner_party CHECK (((owner_kind = 'named_party'::text) = (owner_party_id IS NOT NULL))),
    CONSTRAINT hrm_process_steps_position CHECK (("position" >= 0)),
    CONSTRAINT hrm_process_steps_skip_reason CHECK (((status = 'skipped'::text) = ((skip_reason IS NOT NULL) AND (char_length(btrim(skip_reason)) > 0)))),
    CONSTRAINT hrm_process_steps_status CHECK ((status = ANY (ARRAY['pending'::text, 'done'::text, 'skipped'::text]))),
    CONSTRAINT hrm_process_steps_title CHECK ((char_length(btrim(title)) > 0))
);

