--
-- Name: hrm_process_templates; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hrm_process_templates (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    kind text NOT NULL,
    name text NOT NULL,
    applies_to jsonb DEFAULT '{}'::jsonb NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    applies_employer_subsidiary_id uuid GENERATED ALWAYS AS (((applies_to ->> 'employer_subsidiary_id'::text))::uuid) STORED,
    applies_department_id uuid GENERATED ALWAYS AS (((applies_to ->> 'department_id'::text))::uuid) STORED,
    designer_managed boolean DEFAULT false NOT NULL,
    draft_document jsonb,
    draft_revision integer DEFAULT 0 NOT NULL,
    published_version integer DEFAULT 0 NOT NULL,
    published_revision integer DEFAULT 0 NOT NULL,
    CONSTRAINT hrm_process_templates_applies_shape CHECK (((jsonb_typeof(applies_to) = 'object'::text) AND (((applies_to - 'employer_subsidiary_id'::text) - 'department_id'::text) = '{}'::jsonb) AND ((NOT (applies_to ? 'employer_subsidiary_id'::text)) OR (jsonb_typeof((applies_to -> 'employer_subsidiary_id'::text)) = 'null'::text) OR ((jsonb_typeof((applies_to -> 'employer_subsidiary_id'::text)) = 'string'::text) AND ((applies_to ->> 'employer_subsidiary_id'::text) ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'::text))) AND ((NOT (applies_to ? 'department_id'::text)) OR (jsonb_typeof((applies_to -> 'department_id'::text)) = 'null'::text) OR ((jsonb_typeof((applies_to -> 'department_id'::text)) = 'string'::text) AND ((applies_to ->> 'department_id'::text) ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'::text))))),
    CONSTRAINT hrm_process_templates_draft_revision CHECK (((draft_revision >= 0) AND (published_version >= 0) AND (published_revision >= 0) AND (published_revision <= draft_revision))),
    CONSTRAINT hrm_process_templates_kind CHECK ((kind = ANY (ARRAY['onboarding'::text, 'offboarding'::text, 'transfer'::text]))),
    CONSTRAINT hrm_process_templates_name CHECK ((char_length(btrim(name)) > 0))
);

ALTER TABLE ONLY public.hrm_process_templates FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE hrm_process_templates; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.hrm_process_templates IS 'HRM process checklist configuration: one ordered checklist per (kind, name) with an applies_to filter (employer subsidiary / department, null = all). Deactivation preserves history; a template that opened processes cannot be deleted.';


--
