    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    template_version integer DEFAULT 0 NOT NULL,
    CONSTRAINT hrm_processes_cancel_reason CHECK (((status = 'cancelled'::text) = ((cancel_reason IS NOT NULL) AND (char_length(btrim(cancel_reason)) > 0)))),
    CONSTRAINT hrm_processes_cancelled_paired CHECK (((status = 'cancelled'::text) = (cancelled_at IS NOT NULL))),
    CONSTRAINT hrm_processes_completed_paired CHECK (((status = 'completed'::text) = (completed_at IS NOT NULL))),
    CONSTRAINT hrm_processes_finite_time CHECK (((effective_date >= '0001-01-01'::date) AND (effective_date <= '9999-12-31'::date) AND ((completed_at IS NULL) OR ((completed_at >= '0001-01-01 00:00:00+00'::timestamp with time zone) AND (completed_at < '10000-01-01 00:00:00+00'::timestamp with time zone))) AND ((cancelled_at IS NULL) OR ((cancelled_at >= '0001-01-01 00:00:00+00'::timestamp with time zone) AND (cancelled_at < '10000-01-01 00:00:00+00'::timestamp with time zone))))),
    CONSTRAINT hrm_processes_kind CHECK ((kind = ANY (ARRAY['onboarding'::text, 'offboarding'::text, 'transfer'::text]))),
    CONSTRAINT hrm_processes_status CHECK ((status = ANY (ARRAY['open'::text, 'completed'::text, 'cancelled'::text])))
);

