--
-- Name: pay_run_bank_files; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.pay_run_bank_files (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    pay_run_document_id uuid NOT NULL,
    payment_bank_profile_id uuid NOT NULL,
    format text NOT NULL,
    sequence_number integer NOT NULL,
    file_number text NOT NULL,
    sequence_value integer NOT NULL,
    file_creation_number integer,
    file_id_modifier text,
    filename text NOT NULL,
    content_type text NOT NULL,
    content_hash text NOT NULL,
    size_bytes integer NOT NULL,
    file_id uuid NOT NULL,
    file_version_id uuid NOT NULL,
    entry_count integer NOT NULL,
    control_total numeric(19,4) NOT NULL,
    currency text NOT NULL,
    excluded_cheque jsonb DEFAULT '[]'::jsonb NOT NULL,
    excluded_total numeric(19,4) DEFAULT 0 NOT NULL,
    status text DEFAULT 'generated'::text NOT NULL,
    generated_at timestamp with time zone DEFAULT now() NOT NULL,
    generated_by uuid,
    first_released_at timestamp with time zone,
    last_released_at timestamp with time zone,
    release_count integer DEFAULT 0 NOT NULL,
    superseded_at timestamp with time zone,
    superseded_by uuid,
    superseded_by_file_id uuid,
    supersede_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT pay_run_bank_files_control_total CHECK ((control_total > (0)::numeric)),
    CONSTRAINT pay_run_bank_files_entry_count CHECK ((entry_count > 0)),
    CONSTRAINT pay_run_bank_files_format CHECK ((format = ANY (ARRAY['cpa005'::text, 'nacha'::text, 'sepa'::text, 'cemtex'::text, 'bacs'::text, 'zengin'::text, 'cnab240'::text, 'rbc_std152'::text]))),
    CONSTRAINT pay_run_bank_files_format_numbering CHECK ((((format = 'cpa005'::text) AND ((file_creation_number >= 1) AND (file_creation_number <= 9999)) AND (file_id_modifier IS NULL)) OR ((format = 'nacha'::text) AND (file_id_modifier ~ '^[A-Z0-9]$'::text) AND (file_creation_number IS NULL)) OR ((format = ANY (ARRAY['sepa'::text, 'cemtex'::text, 'bacs'::text, 'zengin'::text, 'cnab240'::text])) AND (file_creation_number IS NULL) AND (file_id_modifier IS NULL)) OR ((format = 'rbc_std152'::text) AND (file_creation_number IS NOT NULL) AND ((file_creation_number >= 1) AND (file_creation_number <= 9999)) AND (file_id_modifier IS NULL)))),
    CONSTRAINT pay_run_bank_files_release_evidence CHECK ((((status = ANY (ARRAY['generated'::text, 'superseded'::text])) AND (release_count = 0) AND (first_released_at IS NULL) AND (last_released_at IS NULL)) OR ((status = ANY (ARRAY['released'::text, 'superseded'::text])) AND (release_count > 0) AND (first_released_at IS NOT NULL) AND (last_released_at IS NOT NULL)))),
    CONSTRAINT pay_run_bank_files_status CHECK ((status = ANY (ARRAY['generated'::text, 'released'::text, 'superseded'::text]))),
    CONSTRAINT pay_run_bank_files_supersede_evidence CHECK (((status <> 'superseded'::text) OR ((superseded_at IS NOT NULL) AND (superseded_by IS NOT NULL) AND (supersede_reason IS NOT NULL) AND (length(btrim(supersede_reason)) >= 5) AND (length(btrim(supersede_reason)) <= 500))))
);

