    submission_policy jsonb,
    CONSTRAINT payroll_compensation_assignments_authorship_check CHECK ((jsonb_typeof(authorship) = 'array'::text)),
    CONSTRAINT payroll_compensation_assignments_check CHECK (((effective_to >= effective_from) AND (effective_to <= '9999-12-31'::date))),
    CONSTRAINT payroll_compensation_assignments_check1 CHECK ((((status = ANY (ARRAY['draft'::text, 'cancelled'::text])) AND (submitted_by IS NULL) AND (submitted_at IS NULL) AND (decided_by IS NULL) AND (decided_at IS NULL)) OR ((status = 'submitted'::text) AND (submitted_by IS NOT NULL) AND (submitted_at IS NOT NULL) AND (decided_by IS NULL) AND (decided_at IS NULL)) OR ((status = ANY (ARRAY['active'::text, 'rejected'::text, 'ended'::text])) AND (submitted_by IS NOT NULL) AND (submitted_at IS NOT NULL) AND (decided_by IS NOT NULL) AND (decided_at IS NOT NULL)))),
    CONSTRAINT payroll_compensation_assignments_check2 CHECK (((status <> 'ended'::text) OR (effective_to IS NOT NULL))),
    CONSTRAINT payroll_compensation_assignments_effective_from_check CHECK (((effective_from >= '0001-01-01'::date) AND (effective_from <= '9999-12-31'::date))),
    CONSTRAINT payroll_compensation_assignments_inputs_check CHECK ((jsonb_typeof(inputs) = 'object'::text)),
    CONSTRAINT payroll_compensation_assignments_reason_check CHECK (((length(TRIM(BOTH FROM reason)) >= 1) AND (length(TRIM(BOTH FROM reason)) <= 2000))),
    CONSTRAINT payroll_compensation_assignments_revision_check CHECK ((revision > 0)),
    CONSTRAINT payroll_compensation_assignments_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'submitted'::text, 'active'::text, 'rejected'::text, 'ended'::text, 'cancelled'::text]))),
    CONSTRAINT payroll_compensation_assignments_submission_policy_shape CHECK (((submission_policy IS NULL) OR (((jsonb_typeof(submission_policy) = 'object'::text) AND ((submission_policy - ARRAY['version'::text, 'kind'::text, 'submittedRevision'::text]) = '{}'::jsonb) AND ((submission_policy -> 'version'::text) = '1'::jsonb) AND ((submission_policy ->> 'kind'::text) = ANY (ARRAY['flow'::text, 'ungated'::text])) AND (jsonb_typeof((submission_policy -> 'submittedRevision'::text)) = 'number'::text) AND ((submission_policy ->> 'submittedRevision'::text) ~ '^[1-9][0-9]{0,9}$'::text) AND (((submission_policy ->> 'submittedRevision'::text))::bigint <= revision) AND (status <> ALL (ARRAY['draft'::text, 'cancelled'::text])) AND (((submission_policy ->> 'kind'::text) <> 'ungated'::text) OR (status = ANY (ARRAY['approved'::text, 'active'::text, 'ended'::text])))) IS TRUE)))
);

