-- Name: payroll_opening_levy_source_authorities; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payroll_opening_levy_source_authorities (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    opening_balance_id uuid NOT NULL,
    employer_authority_id uuid NOT NULL,
    employee_party_id uuid NOT NULL,
    tax_year integer NOT NULL,
    subsidiary_id uuid NOT NULL,
    source_file_id uuid NOT NULL,
    source_version_id uuid NOT NULL,
    source_sha256 text NOT NULL,
    source_reference text NOT NULL,
    original_country text NOT NULL,
    original_currency text NOT NULL,
    coverage_start date NOT NULL,
    coverage_end date NOT NULL,
    coverage_complete boolean NOT NULL,
    change_reason text NOT NULL,
    opening_sha256 text NOT NULL,
    opening_children_snapshot jsonb NOT NULL,
    opening_children_sha256 text NOT NULL,
    allocation_sha256 text DEFAULT repeat('0'::text, 64) NOT NULL,
    allocation_snapshot jsonb DEFAULT '[]'::jsonb NOT NULL,
    sealed boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    supersedes_authority_id uuid,
    request_id uuid,
    request_sha256 text,
    CONSTRAINT payroll_opening_levy_source_authorities_facts CHECK (((original_country ~ '^[A-Z]{2}$'::text) AND (original_currency ~ '^[A-Z]{3}$'::text) AND ((original_country <> 'CA'::text) OR (original_currency = 'CAD'::text)) AND ((original_country <> 'US'::text) OR (original_currency = 'USD'::text)) AND coverage_complete AND (coverage_end >= coverage_start) AND (coverage_end < (coverage_start + '1 year'::interval)) AND ((EXTRACT(year FROM coverage_start) = (tax_year)::numeric) OR (EXTRACT(year FROM coverage_start) = ((tax_year - 1))::numeric)) AND ((original_country <> ALL (ARRAY['CA'::text, 'US'::text])) OR ((coverage_start = make_date(tax_year, 1, 1)) AND (coverage_end <= make_date(tax_year, 12, 31)))))),
    CONSTRAINT payroll_opening_levy_source_authorities_source CHECK (((source_sha256 ~ '^[a-f0-9]{64}$'::text) AND (opening_sha256 ~ '^[a-f0-9]{64}$'::text) AND (allocation_sha256 ~ '^[a-f0-9]{64}$'::text) AND (opening_children_sha256 ~ '^[a-f0-9]{64}$'::text) AND (jsonb_typeof(opening_children_snapshot) = 'object'::text) AND ((length(btrim(source_reference)) >= 1) AND (length(btrim(source_reference)) <= 2000)) AND ((length(btrim(change_reason)) >= 1) AND (length(btrim(change_reason)) <= 2000)) AND (jsonb_typeof(allocation_snapshot) = 'array'::text))),
    CONSTRAINT payroll_opening_levy_source_authorities_successor_request CHECK ((((supersedes_authority_id IS NULL) AND (request_id IS NULL) AND (request_sha256 IS NULL)) OR ((supersedes_authority_id IS NOT NULL) AND (supersedes_authority_id <> id) AND (request_id IS NOT NULL) AND (request_sha256 IS NOT NULL) AND (request_sha256 ~ '^[a-f0-9]{64}$'::text))))
);

ALTER TABLE ONLY public.payroll_opening_levy_source_authorities FORCE ROW LEVEL SECURITY;


