-- Name: psp_settlement_batches; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.psp_settlement_batches (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    provider text NOT NULL,
    external_ref text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    currency text NOT NULL,
    gross_amount numeric(19,4) DEFAULT 0 NOT NULL,
    fee_amount numeric(19,4) DEFAULT 0 NOT NULL,
    refund_amount numeric(19,4) DEFAULT 0 NOT NULL,
    dispute_amount numeric(19,4) DEFAULT 0 NOT NULL,
    net_amount numeric(19,4) DEFAULT 0 NOT NULL,
    fx_amount numeric(19,4) DEFAULT 0 NOT NULL,
    settlement_date date NOT NULL,
    bank_account_id uuid,
    fee_account_id uuid,
    dispute_account_id uuid,
    fx_account_id uuid,
    clearing_account_id uuid,
    subsidiary_id uuid,
    journal_entry_id uuid,
    source_payload jsonb,
    line_count integer DEFAULT 0 NOT NULL,
    posted_at timestamp with time zone,
    memo text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    reversal_entry_id uuid,
    reversal_reason text,
    reversed_at timestamp with time zone,
    reversed_by uuid,
    adjustment_amount numeric(19,4) DEFAULT 0 NOT NULL,
    source_currency text,
    conversion_rate numeric(19,10),
    conversion_rate_source text,
    payout_rate numeric(19,10),
    payout_rate_source text,
    CONSTRAINT psp_settlement_batches_fx_evidence_chk CHECK ((((source_currency IS NULL) AND (conversion_rate IS NULL) AND (conversion_rate_source IS NULL)) OR ((source_currency IS NOT NULL) AND (conversion_rate IS NOT NULL) AND (conversion_rate > (0)::numeric) AND (conversion_rate_source IS NOT NULL)))),
    CONSTRAINT psp_settlement_batches_lifecycle_evidence CHECK ((((status = 'draft'::text) AND (journal_entry_id IS NULL) AND (posted_at IS NULL) AND (reversal_entry_id IS NULL) AND (reversal_reason IS NULL) AND (reversed_at IS NULL) AND (reversed_by IS NULL)) OR ((status = 'posted'::text) AND (journal_entry_id IS NOT NULL) AND (posted_at IS NOT NULL) AND (reversal_entry_id IS NULL) AND (reversal_reason IS NULL) AND (reversed_at IS NULL) AND (reversed_by IS NULL)) OR ((status = 'void'::text) AND (journal_entry_id IS NOT NULL) AND (posted_at IS NOT NULL) AND (reversal_entry_id IS NOT NULL) AND (reversal_entry_id <> journal_entry_id) AND (reversal_reason IS NOT NULL) AND ((length(btrim(reversal_reason)) >= 5) AND (length(btrim(reversal_reason)) <= 500)) AND (reversed_at IS NOT NULL) AND (reversed_by IS NOT NULL)))),
    CONSTRAINT psp_settlement_batches_payout_rate_chk CHECK (((payout_rate IS NULL) OR (payout_rate > (0)::numeric))),
    CONSTRAINT psp_settlement_batches_provider_chk CHECK ((provider = ANY (ARRAY['stripe'::text, 'adyen'::text, 'gocardless'::text, 'recurly'::text, 'chargebee'::text, 'shopify_payments'::text, 'paypal'::text, 'square'::text]))),
    CONSTRAINT psp_settlement_batches_status_chk CHECK ((status = ANY (ARRAY['draft'::text, 'posted'::text, 'void'::text])))
);

ALTER TABLE ONLY public.psp_settlement_batches FORCE ROW LEVEL SECURITY;


--
-- Name: COLUMN psp_settlement_batches.adjustment_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.psp_settlement_batches.adjustment_amount IS 'Provider adjustments (e.g. Chargebee amount_adjusted) in settlement currency. Deducted from net like refunds but tracked separately so write-offs and credit-note applications never pollute refund metrics; zero on every batch imported before migration 0144.';


--
-- Name: COLUMN psp_settlement_batches.source_currency; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.psp_settlement_batches.source_currency IS 'Charges currency when it differs from the batch (payout) currency; null for single-currency batches.';


--
-- Name: COLUMN psp_settlement_batches.conversion_rate; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.psp_settlement_batches.conversion_rate IS 'Provider-evidenced rate: units of batch currency per 1 unit of source currency. Required whenever source_currency is set.';


--
-- Name: COLUMN psp_settlement_batches.conversion_rate_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.psp_settlement_batches.conversion_rate_source IS 'Provenance of conversion_rate (for example stripe:balance_transaction, paypal:payout, operator:manual).';


--
-- Name: COLUMN psp_settlement_batches.payout_rate; Type: COMMENT; Schema: public; Owner: -
