    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT reporting_relationships_closure CHECK ((((superseded_by IS NULL) = (recorded_until IS NULL)) AND ((superseded_by IS NULL) = (closed_by_change_id IS NULL)))),
    CONSTRAINT reporting_relationships_finite_time CHECK (((effective_from >= '0001-01-01'::date) AND (effective_from <= '9999-12-31'::date) AND ((effective_to IS NULL) OR ((effective_to >= '0001-01-01'::date) AND (effective_to <= '9999-12-31'::date))) AND (recorded_at >= '0001-01-01 00:00:00+00'::timestamp with time zone) AND (recorded_at < '10000-01-01 00:00:00+00'::timestamp with time zone) AND ((recorded_until IS NULL) OR ((recorded_until >= '0001-01-01 00:00:00+00'::timestamp with time zone) AND (recorded_until < '10000-01-01 00:00:00+00'::timestamp with time zone))))),
    CONSTRAINT reporting_relationships_kind CHECK ((kind = ANY (ARRAY['line'::text, 'matrix'::text]))),
    CONSTRAINT reporting_relationships_no CHECK ((version_no >= 1)),
    CONSTRAINT reporting_relationships_no_self CHECK ((manager_employment_id <> employment_id)),
    CONSTRAINT reporting_relationships_range CHECK (((effective_to IS NULL) OR (effective_to > effective_from))),
    CONSTRAINT reporting_relationships_recorded CHECK (((recorded_until IS NULL) OR (recorded_until > recorded_at)))
);

