--
-- Name: scheduler_outbox; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.scheduler_outbox (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid,
    kind text NOT NULL,
    subject_id uuid,
    occurrence_key text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    next_attempt_at timestamp with time zone DEFAULT now() NOT NULL,
    locked_at timestamp with time zone,
    last_attempt_at timestamp with time zone,
    finished_at timestamp with time zone,
    error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    terminal_failed_at timestamp with time zone,
    terminal_failed_by text,
    payload jsonb,
    lease_token uuid,
    CONSTRAINT scheduler_outbox_kind CHECK ((kind = ANY (ARRAY['dunning'::text, 'subscription_billing'::text, 'property_billing'::text, 'fx_providers'::text, 'approval_escalation'::text, 'flow_email'::text, 'allocation_run'::text, 'saas_metrics'::text, 'commerce_inbound'::text, 'commerce_channel_sync'::text, 'webhook_delivery'::text, 'autopay_collection'::text, 'usage_rating'::text, 'tax_provider_commit'::text, 'stored_value_breakage'::text, 'stripe_billing_import'::text, 'demand_forecast'::text, 'contract_cost_amortization'::text, 'consolidated_billing'::text, 'billing_import_sync'::text, 'tax_id_revalidation'::text, 'signature_reminder'::text, 'psp_payout_pull'::text, 'expense_amortization'::text]))),
    CONSTRAINT scheduler_outbox_nonnegative_attempts CHECK ((attempt_count >= 0)),
    CONSTRAINT scheduler_outbox_scope CHECK ((((kind = 'approval_escalation'::text) AND (org_id IS NOT NULL) AND (subject_id IS NOT NULL)) OR ((kind = 'flow_email'::text) AND (org_id IS NOT NULL) AND (subject_id IS NOT NULL) AND (payload IS NOT NULL)) OR ((kind = 'allocation_run'::text) AND (org_id IS NOT NULL) AND (subject_id IS NOT NULL) AND (payload IS NOT NULL)) OR ((kind <> ALL (ARRAY['approval_escalation'::text, 'flow_email'::text, 'allocation_run'::text])) AND (org_id IS NULL) AND (subject_id IS NULL)))),
    CONSTRAINT scheduler_outbox_status CHECK ((status = ANY (ARRAY['pending'::text, 'running'::text, 'succeeded'::text, 'failed'::text])))
);

ALTER TABLE ONLY public.scheduler_outbox FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE scheduler_outbox; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.scheduler_outbox IS 'Durable scheduler and approval-escalation outbox. Claim, run, fail with reason, retry with backoff; terminal failed rows stay visible to operators.';


--
-- Name: COLUMN scheduler_outbox.terminal_failed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.scheduler_outbox.terminal_failed_at IS 'Set once when attempt_count reaches the retry ceiling: the row will never be retried again.';


--
-- Name: COLUMN scheduler_outbox.terminal_failed_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.scheduler_outbox.terminal_failed_by IS 'System identity of the worker attempt that recorded the terminal failure.';


--
-- Name: COLUMN scheduler_outbox.payload; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.scheduler_outbox.payload IS 'Rendered email delivery for flow_email rows: to/subject/html/text plus optional attachments and meta. Written inside the flow caller''s transaction so a rollback discards the send; null for every other kind.';


--
-- Name: COLUMN scheduler_outbox.lease_token; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.scheduler_outbox.lease_token IS 'Random per-claim fencing token; success/failure updates must match the active running claim.';


--
-- Name: scheduler_outbox_terminal_audit; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.scheduler_outbox_terminal_audit (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    outbox_row_id uuid NOT NULL,
    event text NOT NULL,
    org_id uuid,
    kind text NOT NULL,
    subject_id uuid,
    occurrence_key text NOT NULL,
    attempt_count integer NOT NULL,
    reason text,
    marked_by text NOT NULL,
    at timestamp with time zone DEFAULT now() NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    failure_generation integer DEFAULT 0 NOT NULL,
    CONSTRAINT scheduler_outbox_terminal_audit_attempts_nonnegative CHECK ((attempt_count >= 0)),
    CONSTRAINT scheduler_outbox_terminal_audit_event CHECK ((event = ANY (ARRAY['terminal_failure'::text, 'crash_recovery_terminal_failure'::text, 'replay_authorized'::text]))),
    CONSTRAINT scheduler_outbox_terminal_audit_generation_nonnegative CHECK ((failure_generation >= 0))
);

ALTER TABLE ONLY public.scheduler_outbox_terminal_audit FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE scheduler_outbox_terminal_audit; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.scheduler_outbox_terminal_audit IS 'Append-only scheduler delivery evidence, with one terminal failure and one authorized replay for each recovery generation.';


--
-- Name: COLUMN scheduler_outbox_terminal_audit.outbox_row_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.scheduler_outbox_terminal_audit.outbox_row_id IS 'The poisoned scheduler_outbox.id this evidence certifies.';


--
-- Name: COLUMN scheduler_outbox_terminal_audit.event; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.scheduler_outbox_terminal_audit.event IS 'terminal_failure (attempt ceiling), crash_recovery_terminal_failure (stale lease recovered at the ceiling), or replay_authorized.';


--
-- Name: COLUMN scheduler_outbox_terminal_audit.reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.scheduler_outbox_terminal_audit.reason IS 'The final error on terminal paths, or the operator-supplied justification on a replay.';


--
-- Name: COLUMN scheduler_outbox_terminal_audit.marked_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.scheduler_outbox_terminal_audit.marked_by IS 'System identity that produced the transition, or the replaying user id.';


--
-- Name: COLUMN scheduler_outbox_terminal_audit.detail; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.scheduler_outbox_terminal_audit.detail IS 'Verbatim before/after envelope: status, attempts, stamps, kind and occurrence identity.';


--
-- Name: COLUMN scheduler_outbox_terminal_audit.failure_generation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.scheduler_outbox_terminal_audit.failure_generation IS 'Failure/replay pair ordinal. The first retained failure is generation zero; the next generation follows the latest immutable replay authorization.';


