    CONSTRAINT worker_employments_revision CHECK ((revision >= 1)),
    CONSTRAINT worker_employments_service_start CHECK ((((service_start IS NULL) AND (service_start_provenance IS NULL)) OR ((service_start IS NOT NULL) AND (service_start_provenance IS NOT NULL) AND (char_length(btrim(service_start_provenance)) > 0))))
);

ALTER TABLE ONLY public.worker_employments FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE worker_employments; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.worker_employments IS 'HRM stable employment identity: one worker party employed by one legal-employer subsidiary. No status, dates, or flags: lifecycle lives in worker_employment_versions. Employer immutable (worker_employments_identity_guard); worker remap only via audited party merge. Canonical employer, no legacy projection: no backfill here; ambiguous source employer/start refused by the one-time migration, never fabricated.';


--
-- Name: COLUMN worker_employments.employer_subsidiary_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.worker_employments.employer_subsidiary_id IS 'Legal employer of this employment: the single employer of record. Transfer = terminate + rehire, never an edit (worker_employments_identity_guard).';


