    SEQUENCE NAME tenant_retirement.events_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: fences; Type: TABLE; Schema: tenant_retirement; Owner: -
--

CREATE TABLE tenant_retirement.fences (
    tenant_id uuid NOT NULL,
    run_id uuid,
    state text DEFAULT 'active'::text NOT NULL,
    receipt jsonb,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT fences_check CHECK (((state = 'active'::text) = (run_id IS NULL))),
    CONSTRAINT fences_state_check CHECK ((state = ANY (ARRAY['active'::text, 'quarantined'::text, 'deleted'::text])))
);


--
-- Name: runs; Type: TABLE; Schema: tenant_retirement; Owner: -
--

CREATE TABLE tenant_retirement.runs (
    id uuid NOT NULL,
    plan_digest text NOT NULL,
    catalog_digest text NOT NULL,
    database_identity jsonb NOT NULL,
    retain_ids uuid[] NOT NULL,
    target_ids uuid[] NOT NULL,
    actor_id uuid NOT NULL,
    reason text NOT NULL,
    recovery_evidence jsonb NOT NULL,
    reviewed_state jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT runs_check CHECK (((cardinality(retain_ids) > 0) AND (cardinality(target_ids) > 0) AND (NOT (retain_ids && target_ids)))),
    CONSTRAINT runs_plan_digest_check CHECK ((plan_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT runs_reason_check CHECK (((length(reason) >= 12) AND (length(reason) <= 2000)))
);


--
-- Name: storage_manifests; Type: TABLE; Schema: tenant_retirement; Owner: -
--

CREATE TABLE tenant_retirement.storage_manifests (
    run_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    manifest jsonb NOT NULL,
    recorded_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL
);


