    ADD CONSTRAINT employee_pay_components_no_active_overlap EXCLUDE USING gist (org_id WITH =, COALESCE(employment_id, employee_party_id) WITH =, component_id WITH =, daterange(effective_from, effective_to, '[]'::text) WITH &&) WHERE (is_active);


--
-- Name: CONSTRAINT employee_pay_components_no_active_overlap ON employee_pay_components; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT employee_pay_components_no_active_overlap ON public.employee_pay_components IS 'One active effective window per (org, coalesce(employment_id, employee_party_id), component). The pay run sums every matching row, so an overlap is a double-pay; only storage can arbitrate the concurrent-writer race.';


