    ADD CONSTRAINT hrm_leave_policies_no_same_scope_overlap EXCLUDE USING gist (org_id WITH =, leave_type_id WITH =, COALESCE((applies_employer_subsidiary_id)::text, ''::text) WITH =, COALESCE((applies_department_id)::text, ''::text) WITH =, daterange(effective_from, effective_to, '[]'::text) WITH &&) WHERE ((is_active AND (COALESCE((applies_to -> 'employment_ids'::text), 'null'::jsonb) = ANY (ARRAY['null'::jsonb, '[]'::jsonb])) AND (COALESCE((applies_to -> 'classification_ids'::text), 'null'::jsonb) = ANY (ARRAY['null'::jsonb, '[]'::jsonb]))));


--
