--
-- Name: contacts_email_trgm; Type: INDEX; Schema: public; Owner: -
--

DO $trigram_index$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_extension WHERE extname = 'pg_trgm') THEN
    CREATE INDEX contacts_email_trgm ON public.contacts USING gin (email public.gin_trgm_ops);
  END IF;
END
$trigram_index$;


--
-- Name: contacts_name_trgm; Type: INDEX; Schema: public; Owner: -
--

DO $trigram_index$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_extension WHERE extname = 'pg_trgm') THEN
    CREATE INDEX contacts_name_trgm ON public.contacts USING gin (name public.gin_trgm_ops);
  END IF;
END
$trigram_index$;


