--
-- Name: sandboxes sandbox_isolation; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY sandbox_isolation ON public.sandboxes USING ((( SELECT public.app_bypass_rls_active() AS app_bypass_rls_active) OR ((org_id)::text = ( SELECT current_setting('app.current_org'::text, true) AS current_setting)) OR ((production_org_id)::text = ( SELECT current_setting('app.current_org'::text, true) AS current_setting)))) WITH CHECK ((( SELECT public.app_bypass_rls_active() AS app_bypass_rls_active) OR (((production_org_id)::text = ( SELECT current_setting('app.current_org'::text, true) AS current_setting)) AND (EXISTS ( SELECT 1
   FROM public.orgs sandbox_org
  WHERE ((sandbox_org.id = sandboxes.org_id) AND (sandbox_org.env_kind = 'sandbox'::text) AND (sandbox_org.sandbox_of = sandboxes.production_org_id)))))));


--
-- Name: POLICY sandbox_isolation ON sandboxes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON POLICY sandbox_isolation ON public.sandboxes IS 'openbooks:sandbox_isolation:v2';


