--
-- Name: tax_group_members tax_group_members_org_isolation; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY tax_group_members_org_isolation ON public.tax_group_members USING ((( SELECT public.app_bypass_rls_active() AS app_bypass_rls_active) OR (EXISTS ( SELECT 1
   FROM public.tax_groups tg
  WHERE ((tg.id = tax_group_members.tax_group_id) AND ((tg.org_id)::text = ( SELECT current_setting('app.current_org'::text, true) AS current_setting))))))) WITH CHECK ((( SELECT public.app_bypass_rls_active() AS app_bypass_rls_active) OR (EXISTS ( SELECT 1
   FROM public.tax_groups tg
  WHERE ((tg.id = tax_group_members.tax_group_id) AND ((tg.org_id)::text = ( SELECT current_setting('app.current_org'::text, true) AS current_setting)))))));


